-- ----------------------------
-- View structure for ActiveRoutineUnexpectedDurationNotificationsToday
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ActiveRoutineUnexpectedDurationNotificationsToday]') AND type IN ('V'))
	DROP VIEW [dbo].[ActiveRoutineUnexpectedDurationNotificationsToday]
GO

CREATE VIEW [dbo].[ActiveRoutineUnexpectedDurationNotificationsToday] AS with base as
(
	select ri.IDRoutineItem, ri.Description, tpv.IDTask , rud.PercentageAdvance, rud.PercentageDelay, ri.EstimatedDuration, ri.WorkingStatus, 
	dbo.TimeToTicks(0, ri.EstimatedDuration, 0) EstimatedDurationTicks, pr.Template as IDSysRoutineItem, fup.MouldNo, apv.AssetNumber, a.assetName,
	t.RunningStatus, r.RoutineKind, rud.ID, rud.IDWorkroom,rud.IDResource, ri.Name
	from SysOprRoutineItem ri
	inner join SysTaskProductionValues tpv on tpv.IDSysOprRoutineItem = ri.IDRoutineItem
	inner join SysTask t on t.IDTask = tpv.IDTask
	inner join SysPrRoutineItem pr on pr.IDRoutineItem = tpv.IDSysRoutineItem
	inner join RoutineUnexpectedDurationNotification rud on rud.IDRoutineItem = ri.IDRoutineItem
	inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
	inner join Asset a on a.IDSysOprRoutine = r.IDRoutine
	inner join SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	inner join FollowUpItemMouldFields fup on fup.IDFollowUpItem = a.IDFollowUpItem
	where rud.LastNotificationDate is null and Finished = 0 and rud.IDWorkroom is not null
), baseWithTimes as
(
	select b.*,t.ID as IDTime, t.StartDate, t.EndDate, t.Duration, t.Status
	from base b 
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on trrt.IDSysTime = t.ID and t.Type = 7
	where (Select count(*) from SysRoutineTeamRoleResource where IDRoutineItem = b.IDRoutineItem) = 0 
), totalTimesForOperation as
(
	select IDRoutineItem, SUM(Duration) TotalDurationForTask
	from baseWithTimes
	where Status in(2725, 2726)
	group by IDRoutineItem
), advancedOperations as
(
	select b.ID, b.IDResource, b.IDWorkroom, b.IDRoutineItem, null as IDTask, 0 as Kind, b.MouldNo, b.assetName, b.AssetNumber, null as Label, RoutineKind,
	TotalDurationForTask, EstimatedDurationTicks, Name
	from base b
	inner join totalTimesForOperation tt on tt.IDRoutineItem = b.IDRoutineItem 
	where EstimatedDurationTicks > 0 and b.WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2' 
	and (TotalDurationForTask * 100.0 / EstimatedDurationTicks) < PercentageAdvance
)
, delayedOperations as
(
	select b.ID, b.IDResource, b.IDWorkroom, b.IDRoutineItem, null as IDTask, 1 as Kind, b.MouldNo, b.assetName, b.AssetNumber, null as Label, RoutineKind,
	TotalDurationForTask, EstimatedDurationTicks, Name
	from base b
	inner join totalTimesForOperation tt on tt.IDRoutineItem = b.IDRoutineItem
	where EstimatedDuration > 0 and b.WorkingStatus in('2966AB3D-D7B6-4228-831B-342618A0FB13','483D173F-7287-4751-A9D1-741DAAAB41E0', '88B381D9-D1DB-4C80-8E78-3076B1E196F2') 
	and (TotalDurationForTask * 100.0 / EstimatedDurationTicks) > (100 + PercentageDelay)
)
, SubTasksBase as
(
	select b.*, rtt.SimulationTime, rtt.IDProcessRoutineItem, rtt.Label, dbo.TimeToTicks(0, rtt.SimulationTime, 0) SimulationTimeTicks
	from base b
	inner join SysRoutineTeamRoleResource rtt on rtt.IDRoutineItem = b.IDRoutineItem and rtt.IDProcessRoutineItem = b.IDSysRoutineItem
	where rtt.SimulationTime > 0
)
, SubTasksBaseWithTimes as
(
	select b.*,t.ID as IDTime, t.StartDate, t.EndDate, t.Duration, t.Status
	from SubTasksBase b 
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on trrt.IDSysTime = t.ID and t.Type = 7
), totalTimesForSubTask as
(
	select IDRoutineItem, IDTask, IDProcessRoutineItem, SUM(Duration) TotalDurationForTask
	from SubTasksBaseWithTimes
	where Status in(2725, 2726)
	group by IDRoutineItem, IDTask, IDProcessRoutineItem
), advancedSubTasks as 
(
	select b.ID, b.IDResource, b.IDWorkroom, b.IDRoutineItem, b.IDTask,2 as Kind, b.MouldNo, b.assetName, b.AssetNumber, Label, RoutineKind,
	TotalDurationForTask, SimulationTimeTicks, Name
	from SubTasksBase b
	inner join totalTimesForSubTask tt on tt.IDRoutineItem = b.IDRoutineItem and b.IDTask = tt.IDTask and b.IDProcessRoutineItem = tt.IDProcessRoutineItem 
	where b.RunningStatus = 2726 and (TotalDurationForTask * 100.0 / SimulationTimeTicks) < PercentageAdvance
), delayedSubTasks as
(
	select b.ID, b.IDResource, b.IDWorkroom, b.IDRoutineItem, b.IDTask,3 as Kind, b.MouldNo, b.assetName, b.AssetNumber, Label, RoutineKind,
	TotalDurationForTask, SimulationTimeTicks, Name
	from SubTasksBase b
	inner join totalTimesForSubTask tt on tt.IDRoutineItem = b.IDRoutineItem and b.IDTask = tt.IDTask and b.IDProcessRoutineItem = tt.IDProcessRoutineItem
	where (TotalDurationForTask * 100.0 / SimulationTimeTicks) > (100 + PercentageAdvance)
) 
select * from advancedOperations
union all 
select * from delayedOperations
union all
select * from advancedSubTasks
union all 
select * from delayedSubTasks
GO


-- ----------------------------
-- View structure for ActiveSessions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ActiveSessions]') AND type IN ('V'))
	DROP VIEW [dbo].[ActiveSessions]
GO

CREATE VIEW [dbo].[ActiveSessions] AS SELECT        s.IDSession, s.IDWorkstation, s.DateStart, s.IDLogin, s.DateEnd, s.IDCurrentResource, s.ClientVersion, s.ActualDateStart, s.SessionNo, s.TimezoneOffset, s.SessionVars, s.TimezoneId, l.Username, w.HostName, s.AccessKey, 
                         DATEDIFF(minute, s.DateStart, getutcdate()) AS EllapsedHeartbeat, s.ClientIP
FROM            dbo.SysSession AS s INNER JOIN
                         dbo.SysLogin AS l ON s.IDLogin = l.IDLogin INNER JOIN
                         dbo.SysWorkstation AS w ON s.IDWorkstation = w.Code
GO


