-- ----------------------------
-- View structure for ActivityTimesView
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ActivityTimesView]') AND type IN ('V'))
	DROP VIEW [dbo].[ActivityTimesView]
GO

CREATE VIEW [dbo].[ActivityTimesView] AS SELECT        
	ARRA.IDActivityResourceRoleActivity, TRRA.TimeWeight, TRRA.IDAgreementItem, TRRA.IDAgreementItemModule,
	t.Code, t.StartDate, t.EndDate, 
	case when t.TimeType = 1 then t.Duration else 0 end as EffectiveDuration, t.Duration, t.ID, ARRA.IDActivity, t.AutoEnd, 
	isnull(ARRA.IDResource, t.IDResource) as IDResource, ARRA.IDActivityRole, 
	t.TimeType, t.Type, TRRA.[description]
FROM            dbo.SysActivityResourceRoleActivity AS ARRA 
				INNER JOIN dbo.SysTask as task on ARRA.IDActivityResourceRoleActivity = task.IDActivityResourceRoleActivity
				inner join [dbo].[SysTaskResourceRole] as trr on task.IDTask = trr.IDTask
                INNER JOIN dbo.SysTimesResourceRoleTask AS TRRA ON trr.IDTaskResourceRole = TRRA.IDTaskResourceRole 
                INNER JOIN dbo.SysTimes AS t ON t.ID = TRRA.IDSysTime

	union all

SELECT        
	ARRA.IDActivityResourceRoleActivity, TRRA.TimeWeight, TRRA.IDAgreementItem, TRRA.IDAgreementItemModule,
	t.Code, t.StartDate, t.EndDate, 
	case when t.TimeType = 1 then t.Duration else 0 end as EffectiveDuration, t.Duration, t.ID, ARRA.IDActivity, t.AutoEnd, 
	isnull(ARRA.IDResource, t.IDResource) as IDResource, ARRA.IDActivityRole, 
	t.TimeType, t.Type, TRRA.[description]
FROM          
	dbo.SysTimes AS t 
	inner join dbo.SysTimesResourceRoleTask as TRRA ON t.ID = TRRA.IDSysTime
	inner join dbo.SysActivityResourceRoleActivity AS ARRA on TRRA.IDActivityResourceRoleActivity = ARRA.IDActivityResourceRoleActivity
GO


-- ----------------------------
-- View structure for AllActivityTimesByTask
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllActivityTimesByTask]') AND type IN ('V'))
	DROP VIEW [dbo].[AllActivityTimesByTask]
GO

CREATE VIEW [dbo].[AllActivityTimesByTask] AS with allActivityTimes as
(
	SELECT arra.IDActivity, isnull(Sum((TRRA.TimeWeight /100)* t.Duration ),0) TotalActivityDuration
	from dbo.SysTimes AS t 
	inner join dbo.SysTimesResourceRoleTask as TRRA ON t.ID = TRRA.IDSysTime
	inner join dbo.SysActivityResourceRoleActivity AS ARRA on TRRA.IDActivityResourceRoleActivity = ARRA.IDActivityResourceRoleActivity
	where ((TimeType=1))
	group by ARRA.IDActivity
)
select IDTask, IDTaskModule,CONVERT(bigint, Duration) DurationNoBlocks,CONVERT(bigint, case when DurationMinutes % 15 = 0 and DurationSeconds = 0 then duration else ((DurationMinutes - (DurationMinutes % 15) + 15)) * 60.0 * 10000000 end) as Duration15MinBlocks
from
(
	select *, ROUND(Duration / 10000000 / 60,0) as DurationMinutes, ROUND(Duration / 10000000 / 60,2) % 1 as DurationSeconds
	from
	(
		select tl.IDTask, tl.IDTaskModule, SUM(aat.TotalActivityDuration) Duration
		from SysTaskLine tl
		inner join allActivityTimes aat on aat.IDActivity = tl.IDActivity
		where tl.IDActivity is not null and IDTask is not null
		group by tl.IDTask, tl.IDTaskModule
	) t
) tt
GO


