-- ----------------------------
-- View structure for AllExternalResourcesTasks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllExternalResourcesTasks]') AND type IN ('V'))
	DROP VIEW [dbo].[AllExternalResourcesTasks]
GO

CREATE VIEW [dbo].[AllExternalResourcesTasks] AS with prebase as
(
	select fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, a.IDAsset, a.IDModule as IDAssetModule,pri.IDRoutine, pr.PartID, pri.IDRoutineItem, 
	pr.WorkingStatus, pri.WorkingStatus as ItemWorkingStatus,pri.IDOperationType, pri.IDPhaseTemplate, t.IDTask, t.IDModule as IDTaskModule, 
	concat(pri.Description, case when opt.IdOperationType is not null then concat('(', opt.Code,')') else concat('(', ri.Description,')') end) as Description, 	
	concat(fupf.MouldNo, case when apv.AssetNumber is null or apv.AssetNumber = '' then '' else '_' end, apv.AssetNumber) AssetMouldNumber,
	apv.AssetNumber, fupf.MouldNo, t.WorkStatus, t.Status, t.RunningStatus, t.StartDate, t.TotalWorkDuration, 
	case when apv.DeadlineType = 0 then apv.Deadline else apv.CalculatedDeadline end Deadline, ISNULL(pri.PhaseLocked, 0) PhaseLocked,
	ta.IDTask as IDTaskItem, ta.IDModule as IDTaskItemModule, ri.Template IDProcessRoutineItem
	, case when prr.ID IS NOT NULL then prr.ItemStartDate else '2099-12-31' end as SimulationStartDate, 0 as MultipleRoles, atar.IDActivityRole
	FROM SysPrRoutineCursor c
	INNER JOIN SysPrRoutine r ON c.IDSysRoutine = r.IDRoutine
	INNER join SysRoutine sr on sr.IDRoutine = r.RoutineClone
	INNER JOIN SysPrRoutineItem ri ON c.IDSysRoutineItem = ri.IDRoutineItem
	INNER JOIN SysActivityTypeActivityRole atar ON atar.IDActivityType = ri.IDSysActivityType
	INNER JOIN SysPrRoutineRequest rq ON c.IDRequest = rq.ID
	INNER JOIN SysTaskProductionValues tpv on tpv.IDSysPRRoutineRequest = c.IDRequest and tpv.IDSysRoutine = c.IDSysRoutine
	AND tpv.IDPART = c.IDPart AND tpv.IDSysRoutineItem = c.IDSysRoutineItem
	INNER JOIN SysTask t ON t.IDTask = tpv.IDTask
	INNER JOIN SysOprRoutineItem pri on tpv.IDSysOprRoutineItem = pri.IDRoutineItem
	INNER JOIN SysTask ta on ta.IDTask = pri.IDSysTask 
	INNER JOIN SysOprRoutine pr on pr.IDRoutine = pri.IDRoutine
	INNER JOIN Asset a ON pr.IDAsset = a.IDAsset AND pr.IDAssetModule = a.IDModule
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER JOIN SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset
	LEFT JOIN SysOperationType opt on opt.IdOperationType = pri.IDOperationType
	LEFT JOIN SysProductionRoutinesRunningSimulation prr on ri.Template = prr.IDPrRoutineItem and pri.IDRoutineItem = prr.IDRoutineItem and prr.IsSimulatedNode = 1
	where pr.WorkingStatus in
	(
		'2966AB3D-D7B6-4228-831B-342618A0FB13',
		'6490D6E5-501A-4E47-8C13-F7489DA3A233',
		'483D173F-7287-4751-A9D1-741DAAAB41E0'
	)
	and pri.WorkingStatus in
	(
		'2966AB3D-D7B6-4228-831B-342618A0FB13',
		'ECBF8E44-6B41-4C3D-A5E9-FCDC47D3C198',
		'C6812E70-56CB-4394-84A5-4C3DE719B44E',
		'483D173F-7287-4751-A9D1-741DAAAB41E0'
	) and pr.RoutineKind in(1,2) 
), unnasignedResource as
(
	select p.*, res.ResourceId as IDResource, res.DisplayName, res.Kind, ara.IDActivityRole IDRole, l.Username
	from prebase p
	INNER JOIN SysActivityRoleResource ara on ara.IDActivityRole = p.IDActivityRole
	INNER JOIN SysResources res on res.ResourceId = ara.IDResource 
	LEFT JOIN SysLogin2SysResource l2r on l2r.IDResource = res.ResourceId and isnull(l2r.Active,0) = 1
	LEFT JOIN SysLogin l on l2r.IDLogin = l.IDLogin and isnull(l.Active,0) = 1
	LEFT JOIN SM_NodePosicConfiguration nc on nc.IDOperationType = p.IDOperationType
	LEFT JOIN SM_NodePosic np on np.ID = nc.IDNode and np.WorkPosition = 1 and np.MachineID = res.ResourceId
	LEFT JOIN SysRoutineTeamRoleResource trr on trr.IDSysTask = p.IDTask and trr.IDResource is null
	where isnull(res.IsExternalResource,0) = 1
), assignedResource as
(
	select p.*, res.ResourceId as IDResource, res.DisplayName, res.Kind, trr.IDRole, l.Username
	from prebase p
	INNER JOIN SysRoutineTeamRoleResource trr on trr.IDSysTask = p.IDTask and trr.IDResource is not null
	INNER JOIN SysResources res on res.ResourceId = trr.IDResource  
	LEFT JOIN SysLogin2SysResource l2r on l2r.IDResource = res.ResourceId and isnull(l2r.Active,0) = 1
	LEFT JOIN SysLogin l on l2r.IDLogin = l.IDLogin and isnull(l.Active,0) = 1
	LEFT JOIN SM_NodePosicConfiguration nc on nc.IDOperationType = p.IDOperationType
	LEFT JOIN SM_NodePosic np on np.ID = nc.IDNode and np.WorkPosition = 1 and np.MachineID = res.ResourceId
	where isnull(res.IsExternalResource,0) = 1
), base as
(
	select * from unnasignedResource
	union all
	select * from assignedResource
), taskHasAttachments as(
	select *, case when (t.TechnicalSpecification <> '' and t.TechnicalSpecification is not null) or attachments > 0 then 1 else 0 end as HasInfo
	from
	(
		select b.IDTask, t.TechnicalSpecification ,isnull(count(distinct f2t.ID),0) attachments
		from base b
		inner join SysOprRoutineItem ri on ri.IDRoutineItem= b.IDRoutineItem
		inner join SysTask t on t.IDTask = ri.IDSysTask
		left join File2SysTask f2t on f2t.IDSysTask = t.IDTask and f2t.IDSysTaskModule = t.IDModule
		group by b.IDTask, t.TechnicalSpecification
	) t
), rolesCanStart as
(
	select distinct ri.IDRoutineItem, trr.IDRole
	from base ri
	inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
	inner join SysRole r on r.IDActivityRole = trr.IDRole
	where r.CanStartExternalResourceTask = 1
), timesWorking as
(
	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, 0 IsBestFit, 
	case when (b.RunningStatus = 2725 and b.IDResource = t.IDResource) then 0 else 1 end as AlternateStatus,
	CONCAT(b.IDResource, b.IDTask) CompareID, t.Status as TimeStatus
	from base b
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on t.Status = 2725 and trrt.IDSysTime = t.ID
	inner join SysResources res on t.IDResource = res.ResourceId
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	where (b.RunningStatus = 2725 and b.IDResource = t.IDResource) 
)
select NEWID() as ID, t.*
from
(
	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, 0 as IsBestFit, 
	case when (b.WorkStatus = 1 and b.RunningStatus = 2725 and b.IDResource = t.IDResource) then 0 else 1 end as AlternateStatus,
	CONCAT(b.IDResource, b.IDTask) CompareID, 
	case when t.IDResource = b.IDResource then t.Status else 2724 end as TimeStatus
	from base b
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on t.Status = 2725 and trrt.IDSysTime = t.ID
	inner join SysResources res on t.IDResource = res.ResourceId
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	where (b.RunningStatus = 2725 and res.Kind <> b.Kind and b.IDResource <> t.IDResource)
	and CONCAT(b.IDResource, b.IDTask) not in (select distinct CompareID from timesWorking)

	union all

	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, 0 as IsBestFit, 
	0 as AlternateStatus, CONCAT(b.IDResource, b.IDTask) as CompareID, 2724 as TimeStatus
	from base b
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	where (b.WorkStatus = 0 and b.RunningStatus in(2724,2725))
	and b.IDTask not in (select distinct IDTask from timesWorking)

	union all 

	select * from timesWorking
) t
GO


-- ----------------------------
-- View structure for AllMachineOperationsTaks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllMachineOperationsTaks]') AND type IN ('V'))
	DROP VIEW [dbo].[AllMachineOperationsTaks]
GO

CREATE VIEW [dbo].[AllMachineOperationsTaks] AS with activityTypesMultipleRoles as
(
	select act.IDSysActivityType, act.ShowOnMachineTasksScreen, COUNT(*) CountRoles
	from SysActivityType act
	inner join SysActivityTypeActivityRole atar on atar.IDActivityType = act.IDSysActivityType
	group by act.IDSysActivityType, act.ShowOnMachineTasksScreen
), rolesMachines as
(
	select distinct arr.IDActivityRole
	from SysActivityRoleResource arr 
	inner join sysresources res on res.ResourceId = arr.IDResource
	where res.Kind = 2
), allActivityTypeRoles as
(
	select atar.*, ShowOnMachineTasksScreen, 0 as MultipleRoles
	from activityTypesMultipleRoles atmr
	inner join SysActivityTypeActivityRole atar on atar.IDActivityType = atmr.IDSysActivityType
	where atmr.CountRoles = 1
	union all
	select atar.*, ShowOnMachineTasksScreen, 1 as MultipleRoles
	from activityTypesMultipleRoles atmr
	inner join SysActivityTypeActivityRole atar on atar.IDActivityType = atmr.IDSysActivityType
	--inner join rolesMachines rm on rm.IDActivityRole = atar.IDActivityRole
	where atmr.CountRoles > 1
), prebase as
(
	select fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, a.IDAsset, a.IDModule as IDAssetModule,pri.IDRoutine, pr.PartID, pri.IDRoutineItem, 
	pr.WorkingStatus, pri.WorkingStatus as ItemWorkingStatus,pri.IDOperationType, pri.IDPhaseTemplate, t.IDTask, t.IDModule as IDTaskModule, 
	concat(pri.Description, case when opt.IdOperationType is not null then concat('(', opt.Code,')') else concat('(', ri.Description,')') end) as Description, 
	concat(fupf.MouldNo, case when apv.AssetNumber is null or apv.AssetNumber = '' then '' else '_' end, apv.AssetNumber) AssetMouldNumber,
	apv.AssetNumber, fupf.MouldNo, t.WorkStatus, t.Status, t.RunningStatus, t.StartDate, t.TotalWorkDuration, 
	case when apv.DeadlineType = 0 then apv.Deadline else apv.CalculatedDeadline end Deadline, ISNULL(pri.PhaseLocked, 0) PhaseLocked,
	ta.IDTask as IDTaskItem, ta.IDModule as IDTaskItemModule,  ri.Template IDProcessRoutineItem
	, case when prr.ID IS NOT NULL then prr.ItemStartDate else '2099-12-31' end as SimulationStartDate, atar.MultipleRoles, 
	atar.IDActivityRole, isnull(atar.ShowOnMachineTasksScreen,0) as ShowOnMachineTasksScreen
	FROM SysPrRoutineCursor c
	INNER JOIN SysPrRoutine r ON c.IDSysRoutine = r.IDRoutine
	INNER join SysRoutine sr on sr.IDRoutine = r.RoutineClone
	INNER JOIN SysPrRoutineItem ri ON c.IDSysRoutineItem = ri.IDRoutineItem
	INNER JOIN allActivityTypeRoles atar ON atar.IDActivityType = ri.IDSysActivityType
	INNER JOIN SysPrRoutineRequest rq ON c.IDRequest = rq.ID
	INNER JOIN SysTaskProductionValues tpv on tpv.IDSysPRRoutineRequest = c.IDRequest and tpv.IDSysRoutine = c.IDSysRoutine
	AND tpv.IDPART = c.IDPart AND tpv.IDSysRoutineItem = c.IDSysRoutineItem
	INNER JOIN SysTask t ON t.IDTask = tpv.IDTask
	INNER JOIN SysOprRoutineItem pri on tpv.IDSysOprRoutineItem = pri.IDRoutineItem
	INNER JOIN SysTask ta on ta.IDTask = pri.IDSysTask 
	INNER JOIN SysOprRoutine pr on pr.IDRoutine = pri.IDRoutine
	INNER JOIN Asset a ON pr.IDAsset = a.IDAsset AND pr.IDAssetModule = a.IDModule
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER JOIN SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset
	LEFT JOIN SysOperationType opt on opt.IdOperationType = pri.IDOperationType
	LEFT JOIN SysProductionRoutinesRunningSimulation prr on ri.Template = prr.IDPrRoutineItem and pri.IDRoutineItem = prr.IDRoutineItem and prr.IsSimulatedNode = 1
	where pr.WorkingStatus in
	(
		'2966AB3D-D7B6-4228-831B-342618A0FB13',
		'6490D6E5-501A-4E47-8C13-F7489DA3A233',
		'483D173F-7287-4751-A9D1-741DAAAB41E0'
	)
	and pri.WorkingStatus in
	(
		'2966AB3D-D7B6-4228-831B-342618A0FB13',
		'ECBF8E44-6B41-4C3D-A5E9-FCDC47D3C198',
		'C6812E70-56CB-4394-84A5-4C3DE719B44E',
		'483D173F-7287-4751-A9D1-741DAAAB41E0'
	) and pr.RoutineKind = 2 
), unnasignedResource as
(
	select p.*, res.ResourceId as IDResource, res.DisplayName, res.Kind, ara.IDActivityRole IDRole, l.Username
	from prebase p
	INNER JOIN SysActivityRoleResource ara on ara.IDActivityRole = p.IDActivityRole
	INNER JOIN SysResources res on res.ResourceId = ara.IDResource 
	LEFT JOIN SysLogin2SysResource l2r on l2r.IDResource = res.ResourceId and isnull(l2r.Active,0) = 1
	LEFT JOIN SysLogin l on l2r.IDLogin = l.IDLogin and isnull(l.Active,0) = 1
	LEFT JOIN SM_NodePosicConfiguration nc on nc.IDOperationType = p.IDOperationType
	LEFT JOIN SM_NodePosic np on np.ID = nc.IDNode and np.WorkPosition = 1 and np.MachineID = res.ResourceId
	LEFT JOIN SysRoutineTeamRoleResource trr on trr.IDSysTask = p.IDTask and trr.IDResource is null
	where  res.Kind = 2 or p.ShowOnMachineTasksScreen = 1 and ISNULL(res.IsExternalResource, 0) = 0
), assignedResource as
(
	select p.*, res.ResourceId as IDResource, res.DisplayName, res.Kind, trr.IDRole, l.Username
	from prebase p
	INNER JOIN SysRoutineTeamRoleResource trr on trr.IDSysTask = p.IDTask and trr.IDResource is not null
	INNER JOIN SysResources res on res.ResourceId = trr.IDResource 
	LEFT JOIN SysLogin2SysResource l2r on l2r.IDResource = res.ResourceId and isnull(l2r.Active,0) = 1
	LEFT JOIN SysLogin l on l2r.IDLogin = l.IDLogin and isnull(l.Active,0) = 1
	LEFT JOIN SM_NodePosicConfiguration nc on nc.IDOperationType = p.IDOperationType
	LEFT JOIN SM_NodePosic np on np.ID = nc.IDNode and np.WorkPosition = 1 and np.MachineID = res.ResourceId
	where  res.Kind = 2 or p.ShowOnMachineTasksScreen = 1 and ISNULL(res.IsExternalResource, 0) = 0
), base as
(
	select * from unnasignedResource
	union all
	select * from assignedResource
), taskHasAttachments as(
	select *, case when (t.TechnicalSpecification <> '' and t.TechnicalSpecification is not null) or attachments > 0 then 1 else 0 end as HasInfo
	from
	(
		select b.IDTask, t.TechnicalSpecification ,isnull(count(distinct f2t.ID),0) attachments
		from base b
		inner join SysOprRoutineItem ri on ri.IDRoutineItem= b.IDRoutineItem
		inner join SysTask t on t.IDTask = ri.IDSysTask
		left join File2SysTask f2t on f2t.IDSysTask = t.IDTask and f2t.IDSysTaskModule = t.IDModule
		group by b.IDTask, t.TechnicalSpecification
	) t
), rolesCanStart as
(
	select distinct ri.IDRoutineItem, trr.IDRole
	from base ri
	inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
	inner join SysRole r on r.IDActivityRole = trr.IDRole
	where r.CanStartMachineProductionTask = 1
), ItemsIsResourceBestFit as
(
	select distinct b.IDRoutineItem, 1 as IsBestFit, trr.SimulatedBestFit, b.IDProcessRoutineItem, b.IDRole
	from base b
	inner join SysRoutineTeamRoleResource trr on b.IDProcessRoutineItem = trr.IDProcessRoutineItem and b.IDResource = trr.SimulatedBestFit
	and b.IDRole = trr.IDRole and b.IDRoutineItem = trr.IDRoutineItem
	inner join SysResources res on res.ResourceId = b.IDResource
	where res.Kind = 2
), timesWorking as
(
	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, ISNULL(IsBestFit,0) IsBestFit, 
	case when (b.RunningStatus = 2725 and b.IDResource = t.IDResource) then 0 else 1 end as AlternateStatus,
	CONCAT(b.IDResource, b.IDTask) CompareID, t.Status as TimeStatus
	from base b
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on t.Status = 2725 and trrt.IDSysTime = t.ID
	inner join SysResources res on t.IDResource = res.ResourceId
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	left join ItemsIsResourceBestFit bf on bf.IDRoutineItem = b.IDRoutineItem and b.IDRole = bf.IDRole
	and bf.SimulatedBestFit = b.IDResource and b.IDProcessRoutineItem = bf.IDProcessRoutineItem
	where (b.RunningStatus = 2725 and b.IDResource = t.IDResource) 
), resourcesWorkingCountPerTask as
(
	select tw.IDTask, COUNT(distinct IDResource) countResources
	from timesWorking tw
	group by tw.IDTask
)
select NEWID() as ID, t.*
from
(
	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, ISNULL(IsBestFit,0) IsBestFit, 
	case when (b.WorkStatus = 1 and b.RunningStatus = 2725 and b.IDResource = t.IDResource) then 0 else 1 end as AlternateStatus,
	CONCAT(b.IDResource, b.IDTask) CompareID, 
	case when t.IDResource = b.IDResource then t.Status else 2724 end as TimeStatus
	from base b
	left join resourcesWorkingCountPerTask rwc on rwc.IDTask = b.IDTask
	inner join SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner join SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner join systimes t on t.Status = 2725 and trrt.IDSysTime = t.ID
	inner join SysResources res on t.IDResource = res.ResourceId
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	left join ItemsIsResourceBestFit bf on bf.IDRoutineItem = b.IDRoutineItem and b.IDRole = bf.IDRole
	and bf.SimulatedBestFit = b.IDResource and b.IDProcessRoutineItem = bf.IDProcessRoutineItem
	where (b.RunningStatus = 2725 and b.MultipleRoles = 1 and res.Kind <> b.Kind and b.IDResource <> t.IDResource)
	and CONCAT(b.IDResource, b.IDTask) not in (select distinct CompareID from timesWorking) and (rwc.IDTask is null or rwc.countResources < 2)

	union all

	select distinct b.*, ta.HasInfo, rcs.IDRole as IDRoleCanStart, ISNULL(IsBestFit,0) IsBestFit, 
	0 as AlternateStatus, CONCAT(b.IDResource, b.IDTask) as CompareID, 2724 as TimeStatus
	from base b
	left join resourcesWorkingCountPerTask rwc on rwc.IDTask = b.IDTask
	left join taskHasAttachments ta on ta.IDTask = b.IDTask
	left join rolesCanStart rcs on rcs.IDRoutineItem = b.IDRoutineItem
	left join ItemsIsResourceBestFit bf on bf.IDRoutineItem = b.IDRoutineItem and b.IDRole = bf.IDRole
	and bf.SimulatedBestFit = b.IDResource and b.IDProcessRoutineItem = bf.IDProcessRoutineItem
	where (b.WorkStatus = 0 and b.RunningStatus in(2724,2725))
	and b.IDTask not in (select distinct IDTask from timesWorking) and (rwc.IDTask is null or rwc.countResources < 2)

	union all 

	select * from timesWorking
) t
GO


-- ----------------------------
-- View structure for AllMouldPhasesAndOperations
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllMouldPhasesAndOperations]') AND type IN ('V'))
	DROP VIEW [dbo].[AllMouldPhasesAndOperations]
GO

CREATE VIEW [dbo].[AllMouldPhasesAndOperations] AS with basePhases as
(
	select fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, a.IDAsset, a.IDModule as IDAssetModule,r.IDRoutine, r.PartID, ri.IDRoutineItem, 
	r.WorkingStatus, ri.WorkingStatus as ItemWorkingStatus,ri.IDOperationType, ri.IDPhaseTemplate, 
	fupf.MouldNo, case when isnull(ri.DeadlineType,0) = 0 then ri.Deadline else ri.CalculatedDeadline end Deadline,  isnull(ri.IsPhase,0) IsPhase,
	phk.IDTranslation, phk.IDTranslationTarget,
	ri.Description, ri.PhaseWorkingStatus, isnull(ri.AllowPhaseUnlock,0) AllowPhaseUnlock
	from SysOprRoutine r
	INNER JOIN SysOprRoutineItem ri on r.IDRoutine = ri.IDRoutine
	INNER JOIN Asset a ON r.IDAsset = a.IDAsset AND r.IDAssetModule = a.IDModule
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER JOIN SysProductionPhaseKind phk on phk.ID = ri.IDPhaseTemplate
	where r.RoutineKind = 1  
	and r.WorkingStatus = '483D173F-7287-4751-A9D1-741DAAAB41E0' and isnull(ri.VirtualNode,0) = 0
	and isnull(ri.IsPhase,0) = 1 and ri.IDPhaseTemplate is not null
), baseOperations as
(
	select fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, a.IDAsset, a.IDModule as IDAssetModule,r.IDRoutine, r.PartID, ri.IDRoutineItem, 
	r.WorkingStatus, ri.WorkingStatus as ItemWorkingStatus,ri.IDOperationType, ri.IDPhaseTemplate, 
	fupf.MouldNo, 	
	case when apv.DeadlineType = 0 then apv.Deadline else apv.CalculatedDeadline end Deadline,
	0 as IsPhase, null as IDTranslation, null as IDTranslationTarget, ri.Description, null as PhaseWorkingStatus, 0 as AllowPhaseUnlock
	FROM SysOprRoutine r
	INNER JOIN SysOprRoutineItem ri ON r.IDRoutine = ri.IDRoutine
	INNER JOIN Asset a ON r.IDAsset = a.IDAsset AND r.IDAssetModule = a.IDModule
	LEFT JOIN SysProductionPhaseKind pk on pk.ID = ri.IDPhaseTemplate
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER join SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset
	LEFT JOIN SysWorkingStatus wsr on wsr.ID = r.WorkingStatus
	LEFT JOIN SysWorkingStatus wsri on wsri.ID = ri.WorkingStatus
	WHERE 
	-- Estados
	r.RoutineKind = 1 and isnull(ri.VirtualNode,0) = 0 and isnull(ri.IsPhase,0) = 0
	AND r.WorkingStatus IN (
		'2966AB3D-D7B6-4228-831B-342618A0FB13',
		'6490D6E5-501A-4E47-8C13-F7489DA3A233',
		'483D173F-7287-4751-A9D1-741DAAAB41E0'
	)
), baseOperationswithTask as 
(
	select bo.IDRoutineItem, bo.WorkingStatus, tk.IDTask, tk.Status, tk.WorkStatus, tk.RunningStatus, tk.StartDate, tk.EndDate, tk.TotalWorkDuration
	from baseOperations bo
	INNER JOIN SysTaskProductionValues tpv on tpv.IDSysOprRoutineItem = bo.IDRoutineItem
	INNER JOIN SysTask tk on tk.IDTask = tpv.IDTask
	INNER JOIN SysPrRoutineItem prri on prri.IDRoutineItem = tpv.IDSysRoutineItem
), basedOperationsWithTasksGroupedRaw as
(
	select IDRoutineItem, MIN(StartDate) StartDate, MAX(EndDate) EndDate, SUM(TotalWorkDuration) TotalWorkDuration
	from baseOperationswithTask
	group by IDRoutineItem

), basedOperationsWithTasksGrouped as
(
	select bo.*, bot.StartDate, bot.EndDate, bot.TotalWorkDuration
	from baseOperations bo
	left join basedOperationsWithTasksGroupedRaw bot on bo.IDRoutineItem = bo.IDRoutineItem
), phasesWithTasks as
(
	select bp.IDRoutineItem, tk.StartDate, tk.EndDate, tk.TotalWorkDuration, tk.CreatedTime 
	from basePhases bp
	inner join Asset a on bp.IDFollowUpItem = a.IDFollowUpItem and bp.IDFollowUpItemModule = a.IDModule
	inner join SysOprRoutineItem ri on ri.IDRoutine = a.IDSysOprRoutine and bp.IDPhaseTemplate = ri.IDPhaseTemplate
	left join SysTaskProductionValues tpv on tpv.IDSysOprRoutineItem = ri.IDRoutineItem
	left join SysTask tk on tk.IDTask = tpv.IDTask
), phasesWithTasksGroupedRaw as
(
	select IDRoutineItem, isnull(MIN(StartDate), MIN(CreatedTime)) StartDate, MAX(EndDate) EndDate, SUM(TotalWorkDuration) TotalWorkDuration
	from phasesWithTasks
	group by IDRoutineItem
), phasesWithTasksGrouped as
(
	select bp.*, pwt.StartDate, pwt.EndDate, pwt.TotalWorkDuration
	from basePhases bp
	left join phasesWithTasksGroupedRaw pwt on pwt.IDRoutineItem = bp.IDRoutineItem
), baseUnited as
(
	select *, null as WorkStatus, null as RunningStatus
	from phasesWithTasksGrouped
	union all
	select *, 
	case 
		when ItemWorkingStatus in('483D173F-7287-4751-A9D1-741DAAAB41E0','2966AB3D-D7B6-4228-831B-342618A0FB13') then 1 
		else 0 
	end as WorkStatus, 
	case 
		when ItemWorkingStatus in('483D173F-7287-4751-A9D1-741DAAAB41E0','2966AB3D-D7B6-4228-831B-342618A0FB13') then 2725 
		when ItemWorkingStatus in('2F2593EC-D358-493E-B02C-3DB5A912C399', '88B381D9-D1DB-4C80-8E78-3076B1E196F2','5FF6EB53-52F6-4A50-83AE-B23CC8C44054') then 2726 
		else 2724 
	end as RunningStatus 
	from basedOperationsWithTasksGrouped
), partsInfo as
(
	select b.IDPhaseTemplate, r.IDRoutine, ri.IDRoutineItem, ri.WorkingStatus
	from baseUnited b
	inner join Asset a on a.IDFollowUpItem = b.IDFollowUpItem and a.IDModule in
	(
		select IDModule from GetModulesRec('1543F596-1571-4177-9B76-C6B32694C66C')
	)
	inner join SysOprRoutine r on r.IDAsset = a.IDAsset and r.IDAssetModule = a.IDModule
	inner join SysOprRoutineItem ri on r.IDRoutine = ri.IDRoutine and b.IDPhaseTemplate = ri.IDPhaseTemplate
	where b.IDPhaseTemplate is not null
), countParts as
(
	select IDPhaseTemplate, count(distinct IDRoutine) countParts
	from partsInfo
	group by IDPhaseTemplate
), countOperations as
(
	select IDPhaseTemplate, count(distinct IDRoutineItem) countOperations
	from partsInfo
	group by IDPhaseTemplate
), groupedOperations as
(
	select IDPhaseTemplate, idroutine, count(distinct IDRoutineItem) countOperations
	from partsInfo 
	group by IDPhaseTemplate, IDRoutine
), groupedOperationsFinished as
(
	select IDPhaseTemplate, idroutine, count(distinct IDRoutineItem) countOperations
	from partsInfo 
	where WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2'
	group by IDPhaseTemplate, IDRoutine
), partWithOperationsFinished as
(
	select gop.IDPhaseTemplate, sum(case when gop.countOperations = gopf.countOperations and gopf.countOperations > 0 then 1 else 0 end) countPartsFinished
	from groupedOperations gop
	inner join groupedOperationsFinished gopf on gopf.IDRoutine = gop.IDRoutine and gopf.IDPhaseTemplate = gop.IDPhaseTemplate
	group by gop.IDPhaseTemplate
)
select NEWID() as ID, t.*, isnull(np.CountParts,0) CountParts, isnull(nop.CountOperations,0) CountOperations, isnull(pof.countPartsFinished,0) CountPartsFinished,
case when t.WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2' then 1 else 0 end IsFinished
from
(
	select distinct b.*
	from baseUnited b
	where isnull(b.IsPhase,0) = 1
	union all
	select distinct b.*
	from baseUnited b
	where b.WorkStatus = 1 and b.RunningStatus in(2725,2726)
	union all
	select distinct b.*
	from baseUnited b
	where b.WorkStatus = 0 and b.RunningStatus in(2724,2725,2726) 
) t
left join countParts np on np.IDPhaseTemplate = t.IDPhaseTemplate
left join countOperations nop on nop.IDPhaseTemplate = t.IDPhaseTemplate
left join partWithOperationsFinished pof on pof.IDPhaseTemplate = t.IDPhaseTemplate
GO


-- ----------------------------
-- View structure for AllProductionRoutinesRunning
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllProductionRoutinesRunning]') AND type IN ('V'))
	DROP VIEW [dbo].[AllProductionRoutinesRunning]
GO

CREATE VIEW [dbo].[AllProductionRoutinesRunning] AS with base as
(
	SELECT distinct
	r.IDRoutine,r.Code, r.Description,  r.IDAsset, r.IDAssetModule, r.PartID, r.Priority, r.WorkingStatus,
	ri.IDRoutineItem, ri.IDOperationType, ri.WorkingStatus as ItemWorkingStatus, ri.VirtualNode, fupf.MouldNo, fup.Name as FUPName,
		ri.IDPhaseTemplate, pk.Name as PhaseTemplateDesc, pk.BGColor, pk.FGColor,
	fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, apv.AssetNumber,
	concat(concat(concat(fupf.MouldNo, case when (apv.AssetNumber is null or apv.AssetNumber = '' and apv.IDAsset <> apvMould.IDAsset)  then '' else '_' end, apv.AssetNumber), case when apv.AssetNumber is null or apv.AssetNumber = '' then '' else '_' end, ri.Description), case when rtt.ID IS not null then CONCAT('[', rtt.Label ,']') else '' end) AssetMouldNumber,
	wsr.BgColor as RoutineWStatusBGColor, wsr.FgColor as RoutineWStatusFGColor, wsri.BgColor as RoutineItemWStatusBGColor, 
	wsri.FgColor as RoutineItemWStatusFGColor, fup.Status,
	apvMould.Deadline as DeadLineMould, apv.Deadline as DeadLinePart, ri.DeadLine as DeadLineOperation,
	ri.code as ItemCode, ri.Name as ItemName, ri.EstimatedDuration, ri.ClosingItem,
	ri.IDPositionResource,ri.ManualPositionSetLogin,ri.IDERPTask, ri.IDERPTaskModule, ri.IDProcess, 
	apvMould.Deadline as MouldDeadline, apv.Deadline as PartDeadline, ri.Deadline,
	rtt.[Label] as SubTaskLabel, rtt.[Order] as SubTaskOrder, rtt.ID as IDSubTask,
	CONCAT(ri.Description, case when rtt.ID is not null then CONCAT('[', rtt.Label, ']') else '' end) as ItemDescription, r.RoutineKind,
	rtt.IDProcessRoutineItem, r.IDTranslation as IDTranslationRoutine, r.IDTranslationTarget as IDTranslationRoutineTarget,
	ri.IDTranslation as IDTranslationRoutineItem, ri.IDTranslationTarget as IDTranslationRoutineItemTarget,
	rtt.IDTranslation as IDTranslationSubTask,  rtt.IDTranslationTarget as IDTranslationSubTaskTarget,
	case 
		when r.IDTranslationTarget = 1 then tvrPT.Acronym 
		when r.IDTranslationTarget = 2 then tvrPT.ShortName
		when r.IDTranslationTarget = 3 then tvrPT.Name
		when r.IDTranslationTarget = 4 then tvrPT.Description
		when r.IDTranslationTarget = 5 then tvrPT.States
	end as TranslationRoutinePT,
	case 
		when r.IDTranslationTarget = 1 then tvrEN.Acronym 
		when r.IDTranslationTarget = 2 then tvrEN.ShortName
		when r.IDTranslationTarget = 3 then tvrEN.Name
		when r.IDTranslationTarget = 4 then tvrEN.Description
		when r.IDTranslationTarget = 5 then tvrEN.States		
	end as TranslationRoutineEN,
	case 
		when ri.IDTranslationTarget = 1 then tvriPT.Acronym 
		when ri.IDTranslationTarget = 2 then tvriPT.ShortName
		when ri.IDTranslationTarget = 3 then tvriPT.Name
		when ri.IDTranslationTarget = 4 then tvriPT.Description
		when ri.IDTranslationTarget = 5 then tvriPT.States
	end as TranslationRoutineItemPT,
	case 
		when ri.IDTranslationTarget = 1 then tvriEN.Acronym 
		when ri.IDTranslationTarget = 2 then tvriEN.ShortName
		when ri.IDTranslationTarget = 3 then tvriEN.Name
		when ri.IDTranslationTarget = 4 then tvriEN.Description
		when ri.IDTranslationTarget = 5 then tvriEN.States
	end as TranslationRoutineItemEN,
	case 
		when rtt.IDTranslationTarget = 1 then tvrttPT.Acronym 
		when rtt.IDTranslationTarget = 2 then tvrttPT.ShortName
		when rtt.IDTranslationTarget = 3 then tvrttPT.Name
		when rtt.IDTranslationTarget = 4 then tvrttPT.Description
		when rtt.IDTranslationTarget = 5 then tvrttPT.States
	end as TranslationSubTaskPT,
	case 
		when rtt.IDTranslationTarget = 1 then tvrttEN.Acronym 
		when rtt.IDTranslationTarget = 2 then tvrttEN.ShortName
		when rtt.IDTranslationTarget = 3 then tvrttEN.Name
		when rtt.IDTranslationTarget = 4 then tvrttEN.Description
		when rtt.IDTranslationTarget = 5 then tvrttEN.States 
	end as TranslationSubTaskEN, apvMould.IDAsset as IDAssetMould, rtt.ID as IDTeamRoutineSubTask,
	ri.OperationToExport
	FROM SysOprRoutine r
	INNER JOIN SysOprRoutineItem ri ON r.IDRoutine = ri.IDRoutine
	INNER JOIN Asset a ON r.IDAsset = a.IDAsset AND r.IDAssetModule = a.IDModule
	LEFT JOIN SysProductionPhaseKind pk on pk.ID = ri.IDPhaseTemplate
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER join SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset
	LEFT JOIN SysWorkingStatus wsr on wsr.ID = r.WorkingStatus
	LEFT JOIN SysWorkingStatus wsri on wsri.ID = ri.WorkingStatus
	LEFT JOIN SysRoutineTeamRoleResource rtt on rtt.IDRoutine = r.IDRoutine and rtt.IDRoutineItem = ri.IDRoutineItem
	LEFT JOIN SysTranslationValue tvrPT on tvrPT.IDTranslation = r.IDTranslation and tvrPT.IDLanguage = 1  
	LEFT JOIN SysTranslationValue tvrEN on tvrEN.IDTranslation = r.IDTranslation and tvrEN.IDLanguage = 4
	LEFT JOIN SysTranslationValue tvriPT on tvriPT.IDTranslation = ri.IDTranslation and tvriPT.IDLanguage = 1  
	LEFT JOIN SysTranslationValue tvriEN on tvriEN.IDTranslation = ri.IDTranslation and tvriEN.IDLanguage = 4
	LEFT JOIN SysTranslationValue tvrttPT on tvrttPT.IDTranslation = rtt.IDTranslation and tvrttPT.IDLanguage = 1  
	LEFT JOIN SysTranslationValue tvrttEN on tvrttEN.IDTranslation = rtt.IDTranslation and tvrttEN.IDLanguage = 4
	WHERE 
	-- Estados
	(
		r.RoutineKind = 2 or (r.RoutineKind = 1 and isnull(ri.VirtualNode,0) = 0 and isnull(ri.IsPhase,0) = 0 ) 
	)
	and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
)
select NEWID() as ID, b.*,
concat(concat(concat(b.MouldNo, case when (b.AssetNumber is null or b.AssetNumber = '' and b.IDAsset <> b.IDAssetMould)  then '' else '_' end, b.AssetNumber), case when b.AssetNumber is null or b.AssetNumber = '' then '' else '_' end, b.TranslationRoutineItemPT), case when b.IDTeamRoutineSubTask IS not null and TranslationSubTaskPT is not null and TranslationSubTaskPT <> '' then CONCAT('[', b.TranslationSubTaskPT ,']') else '' end) AssetMouldNumberPT,
concat(concat(concat(b.MouldNo, case when (b.AssetNumber is null or b.AssetNumber = '' and b.IDAsset <> b.IDAssetMould)  then '' else '_' end, b.AssetNumber), case when b.AssetNumber is null or b.AssetNumber = '' then '' else '_' end, b.TranslationRoutineItemEN), case when b.IDTeamRoutineSubTask IS not null and TranslationSubTaskPT is not null and TranslationSubTaskPT <> '' then CONCAT('[', b.TranslationSubTaskEN ,']') else '' end) AssetMouldNumberEN
from base b
GO


-- ----------------------------
-- View structure for AllProductionRoutinesRunningLinks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllProductionRoutinesRunningLinks]') AND type IN ('V'))
	DROP VIEW [dbo].[AllProductionRoutinesRunningLinks]
GO

CREATE VIEW [dbo].[AllProductionRoutinesRunningLinks] AS (
select NEWID() as ID,ri.IDRoutineItem, STUFF ((
SELECT Distinct ', '+ CAST (Destination as nvarchar(128)) as Destination  FROM SysOprRoutineItemLink WHERE Origin IS NOT NULL 
AND Origin <> '00000000-0000-0000-0000-000000000000' AND Origin = ri.IDRoutineItem GROUP By Destination, Origin
--ORDER BY ', ' + CAST (Destination as nvarchar(MAX)) 
FOR XML PATH(''), TYPE
		).value('.[1]', 'nvarchar(max)'), 1, 2, '') AS Next,
STUFF ((
SELECT Distinct ', '+ CAST (Origin as nvarchar(128)) as Origin  FROM SysOprRoutineItemLink WHERE Destination IS NOT NULL 
AND Destination <> '00000000-0000-0000-0000-000000000000' AND Destination = ri.IDRoutineItem GROUP By Origin,Destination
--ORDER BY ', ' + CAST (Destination as nvarchar(MAX)) 
FOR XML PATH(''), TYPE
		).value('.[1]', 'nvarchar(max)'), 1, 2, '') AS Prev 
FROM SysOprRoutineItem ri 
inner join SysOprRoutine r on r.iDRoutine = ri.IDRoutine
where (r.RoutineKind = 2 or (r.RoutineKind = 1 and isnull(ri.VirtualNode,0) = 0 and isnull(ri.IsPhase,0) = 0 ) )
and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
);
GO


-- ----------------------------
-- View structure for AllProductionRoutinesRunningTasks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllProductionRoutinesRunningTasks]') AND type IN ('V'))
	DROP VIEW [dbo].[AllProductionRoutinesRunningTasks]
GO

CREATE VIEW [dbo].[AllProductionRoutinesRunningTasks] AS with base as
(
	SELECT distinct
	r.IDRoutine, r.IDAsset, r.IDAssetModule, ri.IDRoutineItem, ri.IDOperationType, ri.WorkingStatus, 
	ri.IDERPTask, ri.IDERPTaskModule, ri.IDProcess, 
	rtt.[Label] as SubTaskLabel, rtt.[Order] as SubTaskOrder, rtt.ID as IDSubTask,
	r.RoutineKind,	rtt.IDProcessRoutineItem, rtt.ID as IDTeamRoutineSubTask, 
	apvMould.Deadline as DeadLineMould, apv.Deadline as DeadLinePart, ri.DeadLine as DeadLineOperation,
	apvMould.Deadline as MouldDeadline, apv.Deadline as PartDeadline, ri.Deadline
	FROM SysOprRoutine r
	INNER JOIN SysOprRoutineItem ri ON r.IDRoutine = ri.IDRoutine
	INNER JOIN Asset a ON r.IDAsset = a.IDAsset AND r.IDAssetModule = a.IDModule
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER join SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset
	LEFT JOIN SysWorkingStatus wsr on wsr.ID = r.WorkingStatus
	LEFT JOIN SysWorkingStatus wsri on wsri.ID = ri.WorkingStatus
	INNER JOIN SysRoutineTeamRoleResource rtt on rtt.IDRoutine = r.IDRoutine and rtt.IDRoutineItem = ri.IDRoutineItem
	WHERE 
	-- Estados
	(r.RoutineKind = 2 or (r.RoutineKind = 1 and isnull(ri.VirtualNode,0) = 0 and isnull(ri.IsPhase,0) = 0 ) )
	and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
),  baseWithTasks as
(
	select b.IDRoutineItem, b.WorkingStatus,b.IDSubTask, tk.IDTask,
	b.MouldDeadline, b.Deadline, b.PartDeadline, b.IDTeamRoutineSubTask, b.IDRoutine
	from base b
	INNER JOIN SysTaskProductionValues tpv on tpv.IDSysOprRoutineItem = b.IDRoutineItem 
	INNER JOIN SysPrRoutineItem prri on prri.IDRoutineItem = tpv.IDSysRoutineItem and prri.Template = b.IDProcessRoutineItem
	INNER JOIN SysTask tk on tk.IDTask = tpv.IDTask 
), baseWithTimesRaw as
(
	select b.IDTask, t.ID as IDTime, t.StartDate as TimeStartDate, t.EndDate as TimeEndDate, t.IDResource as IDResourceTime,
	b.MouldDeadline, b.Deadline, b.PartDeadline, b.IDTeamRoutineSubTask, b.IDRoutine
	from baseWithTasks b
	inner JOIN SysTaskResourceRole trr on trr.IDTask = b.IDTask
	inner JOIN SysTimesResourceRoleTask trrt on trrt.IDTaskResourceRole = trr.IDTaskResourceRole
	inner JOIN SysTimes t ON t.ID = trrt.IDSysTime
), baseWithTimes as
(
	select b.*, br.IDTime, br.TimeStartDate, br.TimeEndDate, br.IDResourceTime
	from baseWithTasks b
	left join baseWithTimesRaw br on br.IDTask = b.IDTask
), basewithItemsCompletedWithoutTimes as
(
	select b.IDTask, tk.ModifiedTime as TaskModifiedDate, (select top 1 IDResource from SysModuleTracker where IDRecord like b.IDTask) as IDResourceTracker
	from baseWithTimes b
	inner join SysTask tk on tk.IDTask = b.IDTask
	where WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2' and b.IDTime is null
), baseFinal as
(
	select distinct b.*, 
	case when IDTime IS null then TaskModifiedDate else TimeStartDate end as StartDate,
	case when IDTime IS null then DATEADD(SECOND, 1, TaskModifiedDate) else TimeEndDate end as EndDate,
	case when IDTime IS null then IDResourceTracker else IDResourceTime end as IDResource
	from baseWithTimes b
	left join basewithItemsCompletedWithoutTimes bw on bw.IDTask = b.IDTask
), datesByRoutineItem as
(
	select idRoutineItem, MIN(StartDate) as ItemStartDate, MAX(EndDate) as ItemEndDate
	from baseFinal
	group by IDRoutineItem
)
select NEWID() as ID, bf.*, dri.ItemStartDate, dri.ItemEndDate,
case 
	when MouldDeadline is null then null
	when DATEDIFF(day, ItemEndDate, MouldDeadline) > 15 then 0
	when DATEDIFF(day, ItemEndDate, MouldDeadline) <= 15 and DATEDIFF(day, ItemEndDate, MouldDeadline) > 10 then 1
	when DATEDIFF(day, ItemEndDate, MouldDeadline) <= 10 and DATEDIFF(day, ItemEndDate, MouldDeadline) > 5 then 2
	when DATEDIFF(day, ItemEndDate, MouldDeadline) <= 5 and DATEDIFF(day, ItemEndDate, MouldDeadline) >= 0 then 3
	else 4
end as DeadLineMouldStatus, 
case 
	when Deadline is null then null
	when DATEDIFF(day, ItemEndDate, Deadline) > 15 then 0
	when DATEDIFF(day, ItemEndDate, Deadline) <= 15 and DATEDIFF(day, ItemEndDate, PartDeadline) > 10 then 1
	when DATEDIFF(day, ItemEndDate, Deadline) <= 10 and DATEDIFF(day, ItemEndDate, PartDeadline) > 5 then 2
	when DATEDIFF(day, ItemEndDate, Deadline) <= 5 and DATEDIFF(day, ItemEndDate, PartDeadline) >= 0 then 3
	else 4
end as DeadLinePartStatus, 
case 
	when Deadline is null then null
	when DATEDIFF(day, ItemEndDate, Deadline) > 15 then 0
	when DATEDIFF(day, ItemEndDate, Deadline) <= 15 and DATEDIFF(day, ItemEndDate, Deadline) > 10 then 1
	when DATEDIFF(day, ItemEndDate, Deadline) <= 10 and DATEDIFF(day, ItemEndDate, Deadline) > 5 then 2
	when DATEDIFF(day, ItemEndDate, Deadline) <= 5 and DATEDIFF(day, ItemEndDate, Deadline) >= 0 then 3
	else 4
end as DeadLineOperationStatus
from basefinal bf
left join datesByRoutineItem dri on dri.IDRoutineItem = bf.IDRoutineItem;
GO


-- ----------------------------
-- View structure for AllResourcesHolidays
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllResourcesHolidays]') AND type IN ('V'))
	DROP VIEW [dbo].[AllResourcesHolidays]
GO

CREATE VIEW [dbo].[AllResourcesHolidays] AS selecT NEWID() as FillerID, res.ResourceId, hy.Year, h.Month, h.Day, acc.dbmask
	from SysResources res
	inner join SysResource2SysHolidaysPlan h2pl on h2pl.IDResource = res.ResourceId
	inner join SysHolidaysYear hy on hy.IDSysHolidaysPlan = h2pl.IDSysHolidaysPlan
	inner join SysHoliday h on h.IDHolidaysYear = hy.IDHolidaysYear
	inner join Account acc on acc.CurrentResource = res.ResourceId and acc.AccountYear = hy.Year and acc.IDModule in(
			select IDModule from GetModulesRec('3020DDD2-D6D9-4E3D-8B6F-70D228E1B7B2')
		)
	where res.Active = 1 and (select count(*) from SysLogin2SysResource where IDResource = res.ResourceId and active = 1) = 1
GO


-- ----------------------------
-- View structure for AllResourcesVacationDays
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllResourcesVacationDays]') AND type IN ('V'))
	DROP VIEW [dbo].[AllResourcesVacationDays]
GO

CREATE VIEW [dbo].[AllResourcesVacationDays] AS select NEWID() as FillerID, ResourceId ,dbmask, Year, Month, Day, CASE WHEN NPeriods = 1 THEN 1 ELSE 0 END HalfDay
	from(
		select res.ResourceId, acc.dbmask, YEAR(t.StartDate) Year,  month(t.StartDate) month, day(t.EndDate) day, count(*) NPeriods
		from SysResources res
		inner join SysTimes t on t.TimelineType = 1 and t.Type = 11 and t.IDResource = res.ResourceId 
		inner join Account acc on acc.CurrentResource = res.ResourceId and acc.AccountYear = YEAR(t.StartDate) and acc.IDModule in(
			select IDModule from GetModulesRec('3020DDD2-D6D9-4E3D-8B6F-70D228E1B7B2')
		)
		where res.Active = 1 and (select count(*) from SysLogin2SysResource where IDResource = res.ResourceId and active = 1) = 1
		group by res.ResourceId, acc.dbmask,YEAR(t.StartDate),  month(t.StartDate), day(t.EndDate)
	) t
GO


-- ----------------------------
-- View structure for AllResourcesWorkWeeks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllResourcesWorkWeeks]') AND type IN ('V'))
	DROP VIEW [dbo].[AllResourcesWorkWeeks]
GO

CREATE VIEW [dbo].[AllResourcesWorkWeeks] AS select NEWID() as FillerID, t.*
	from(
		select distinct acc.dbmask, res.ResourceId, scpl.StartDate, scpl.EndDate, scl.Frequency, scl.WorkWeek
		from SysResources res
		inner join SysSchedulePlanLine scpl on res.IDSysSchedulePlan = scpl.IDSysSchedulePlan
		inner join SysScheduleLine scl on scl.IDSchedule = scpl.IDSchedule
		inner join Account acc on acc.CurrentResource = res.ResourceId and acc.AccountYear = YEAR(GETDATE()) and acc.IDModule in(
			select IDModule from GetModulesRec('3020DDD2-D6D9-4E3D-8B6F-70D228E1B7B2')
		)
		where res.Active = 1 
	) t
GO


-- ----------------------------
-- View structure for ALLResourceVehiclesGPSCoordinates
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ALLResourceVehiclesGPSCoordinates]') AND type IN ('V'))
	DROP VIEW [dbo].[ALLResourceVehiclesGPSCoordinates]
GO

CREATE VIEW [dbo].[ALLResourceVehiclesGPSCoordinates] AS WITH ve2res AS (
	
	SELECT
		vt.IDTracker,
		v2r.IDResource,
		res.DisplayName,
		ISNULL(v2r.StartDate, '1900-01-01') AS StartDate,
		ISNULL(v2r.EndDate, '2099-12-31') AS EndDate
	FROM
		dbo.VehicleTracker AS vt
		LEFT OUTER JOIN dbo.VehicleTracker2SysResource AS v2r ON vt.ID = v2r.IDTracker
		LEFT OUTER JOIN dbo.SysResources AS res ON res.ResourceId = v2r.IDResource
		AND (
			v2r.StartDate IS NULL
			OR v2r.StartDate <= GETDATE()
		)
		AND (
			v2r.EndDate IS NULL
			OR v2r.EndDate >= GETDATE()
		)
)
SELECT
	NEWID() AS ID,
	vtc.IDTracker,
	v2r.IDResource,
	v2r.DisplayName,
	vtc.Lat,
	vtc.Lon,
	vtc.Date,
	vtc.Speed,
	vtc.CreatedTime,
	vtc.Elevation,
	vtc.[DeltaTime],
	vtc.[AverageSpeed],
	vtc.[Acceleration],
	vtc.[EventCode]
FROM
	dbo.VehicleTrackerCoordinates AS vtc
	LEFT OUTER JOIN ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker
	AND vtc.Date >= v2r.StartDate
	AND vtc.Date <= v2r.EndDate
	
UNION ALL

SELECT
	NEWID() AS ID,
	vtc.IDTracker,
	v2r.IDResource,
	v2r.DisplayName,
	vtc.Lat,
	vtc.Lon,
	vtc.Date,
	vtc.Speed,
	vtc.CreatedTime,
	vtc.Elevation,
	vtc.[DeltaTime],
	vtc.[AverageSpeed],
	vtc.[Acceleration],
	vtc.[EventCode]
FROM
	dbo.VehicleTrackerProcessedCoordinates AS vtc
	LEFT OUTER JOIN ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker
	AND vtc.Date >= v2r.StartDate
	AND vtc.Date <= v2r.EndDate
GO


-- ----------------------------
-- View structure for AllTaskTimesByActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllTaskTimesByActivity]') AND type IN ('V'))
	DROP VIEW [dbo].[AllTaskTimesByActivity]
GO

CREATE VIEW [dbo].[AllTaskTimesByActivity] AS with allTaskTimes as
(
	SELECT Task.IDTask, isnull(Sum((TRRA.TimeWeight /100)* t.Duration ),0) TotalTaskDuration
	FROM  dbo.SysTask AS task WITH(NOLOCK)
	inner join dbo.SysTaskResourceRole as TRR WITH(NOLOCK) ON task.IDTask = TRR.IDTask
	INNER JOIN dbo.SysTimesResourceRoleTask  AS TRRA  WITH (NOLOCK) ON TRR.IDTaskResourceRole = TRRA.IDTaskResourceRole
	INNER JOIN dbo.SysTimes as  t WITH (NOLOCK) ON t.ID = TRRA.IDSysTime
	where (TimeType=1 OR TimeType=4)
	group by Task.IDTask
)
select IDActivity, IDActivityModule, CONVERT(bigint, Duration) DurationNoBlocks, CONVERT(bigint, case when DurationMinutes % 15 = 0 then duration else ((DurationMinutes - (DurationMinutes % 15) + 15)) * 60.0 * 10000000 end) as Duration15MinBlocks
from
(
	select *, ROUND(Duration / 10000000 / 60,0) as DurationMinutes
	from
	(
		select tl.IDActivity, tl.IDActivityModule, SUM(aat.TotalTaskDuration) Duration
		from SysTaskLine tl
		inner join allTaskTimes aat on aat.IDTask = tl.IDTask
		where tl.IDActivity is not null and tl.IDTask is not null
		group by tl.IDActivity, tl.IDActivityModule
	) t
) tt
GO


-- ----------------------------
-- View structure for AndroidResourceSummaryHoursBankInfo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AndroidResourceSummaryHoursBankInfo]') AND type IN ('V'))
	DROP VIEW [dbo].[AndroidResourceSummaryHoursBankInfo]
GO

CREATE VIEW [dbo].[AndroidResourceSummaryHoursBankInfo] AS WITH SchedulesMinMax AS (
	
	SELECT
		spl.IDSysSchedulePlan,
		spl.IDSchedule,
		ISNULL(
			spl.StartDate,
			(
				
				SELECT
					CAST('1753-1-1' AS datetime) AS Expr1
			)
		) AS StartDate,
		ISNULL(
			spl.EndDate,
			(
				
				SELECT
					CAST('9999-12-30' AS datetime) AS Expr1
			)
		) AS EndDate,
		MIN(scl.StartTime) AS ScheduleStart,
		MAX(scl.EndTime) AS ScheduleEnd,
		SUM(DATEDIFF(MINUTE, scl.StartTime, scl.EndTime)) / 60 AS WorkingHoursDay
	FROM
		dbo.SysSchedulePlanLine AS spl
		INNER JOIN dbo.SysScheduleLine AS scl ON scl.IDSchedule = spl.IDSchedule
	GROUP BY
		spl.IDSysSchedulePlan,
		spl.IDSchedule,
		spl.StartDate,
		spl.EndDate
),
AccountDetails AS (
	
	SELECT
		l2r.IDLogin,
		l2r.IDResource,
		acc.IDAccount,
		acc.IDModule,
		res.IDSysSchedulePlan,
		accs.TotalQtyActualStock,
		acc.IDContact,
		acc.IDContactModule,
		acc.AccountYear,
		acc.IDParent
	FROM
		dbo.Account AS acc
		INNER JOIN dbo.AccountStock AS accs ON accs.IDAccount = acc.IDAccount
		AND accs.IDModule = acc.IDModule
		INNER JOIN dbo.Entity AS e ON e.organizationid = acc.IDContact
		AND e.IDModule = acc.IDContactModule
		INNER JOIN dbo.SysLogin2SysResource AS l2r ON l2r.IDPerson = e.organizationid
		AND l2r.IDPersonModule = e.IDModule
		AND l2r.Active = 1
		INNER JOIN dbo.SysResources AS res ON res.ResourceId = l2r.IDResource
	WHERE
		(
			acc.IDModule IN (
				
				SELECT
					IDModule
				FROM
					dbo.GetModulesRec('25C1DD8B-3766-4384-A3C1-4338D6EEFCF7')
			)
		)
),
AccountVacations AS (
	
	SELECT
		acc.IDLogin,
		acc.IDResource,
		acc.IDAccount,
		accV.IDAccount AS IDAccountVacation,
		acc.AccountYear,
		acc.IDModule,
		accV.IDModule AS IDAccountVacationModule,
		accs.TotalQtyActualStock
	FROM
		AccountDetails AS acc
		INNER JOIN dbo.Account AS accV ON acc.IDContact = accV.IDContact
		AND acc.IDContactModule = accV.IDContactModule
		AND acc.IDParent = accV.IDParent
		AND acc.AccountYear = accV.AccountYear
		INNER JOIN dbo.AccountStock AS accs ON accs.IDAccount = accV.IDAccount
		AND accs.IDModule = accV.IDModule
	WHERE
		(
			accV.IDModule IN (
				
				SELECT
					IDModule
				FROM
					dbo.GetModulesRec('3020DDD2-D6D9-4E3D-8B6F-70D228E1B7B2')
			)
		)
),
TimeMovementsDay AS (
	
	SELECT
		acc.IDLogin,
		acc.IDResource,
		acc.IDAccount,
		acc.IDModule,
		acc.IDSysSchedulePlan,
		acc.TotalQtyActualStock,
		acc.IDContact,
		acc.IDContactModule,
		acc.AccountYear,
		acc.IDParent,
		YEAR(pv.DateRecord) AS YEAR,
		MONTH(pv.DateRecord) AS MONTH,
		pv.QtyActualStock,
		pv.TotalCredit,
		pv.TotalDebit,
		pv.IDPocValue,
		pv.DateRecord,
		scm.WorkingHoursDay,
		CASE WHEN pv.TotalDebit = 0 THEN 1 WHEN pv.TotalDebit <> 0
		AND pv.TotalDebit <> scm.WorkingHoursDay THEN 2 ELSE 0 END AS DayOff
	FROM
		AccountDetails AS acc
		INNER JOIN dbo.SysPocValue AS pv ON pv.IDRecord = acc.IDAccount
		AND pv.IDRecordModule = acc.IDModule
		AND pv.MovementMode = 0
		INNER JOIN SchedulesMinMax AS scm ON scm.IDSysSchedulePlan = acc.IDSysSchedulePlan
		AND pv.DateRecord >= scm.StartDate
		AND pv.DateRecord <= scm.EndDate
	WHERE
		(pv.IDSrc IS NULL)
		AND (pv.Compensation = 0)
),
TimeMovementsAdjustment AS (
	
	SELECT
		IDLogin,
		IDResource,
		IDAccount,
		YEAR,
		MONTH,
		ISNULL(SUM(QtyActualStock), 0) AS TotalAdjustment
	FROM
		(
			
			SELECT
				acc.IDLogin,
				acc.IDResource,
				acc.IDAccount,
				YEAR(pv.DateRecord) AS YEAR,
				MONTH(pv.DateRecord) AS MONTH,
				pv.QtyActualStock
			FROM
				AccountDetails AS acc
				INNER JOIN dbo.SysPocValue AS pv ON pv.IDRecord = acc.IDAccount
				AND pv.IDRecordModule = acc.IDModule
				AND pv.MovementMode = 0
			WHERE
				(pv.IDSrc IS NOT NULL)
				AND (pv.Compensation = 0)
		) AS t
	GROUP BY
		IDLogin,
		IDResource,
		IDAccount,
		YEAR,
		MONTH
),
VacationDaysGiven AS (
	
	SELECT
		IDLogin,
		IDResource,
		IDAccount,
		YEAR,
		ISNULL(SUM(QtyDocAct), 0) AS TotalVacationDays
	FROM
		(
			
			SELECT
				acc.IDLogin,
				acc.IDResource,
				acc.IDAccount,
				YEAR(pv.DateRecord) AS YEAR,
				MONTH(pv.DateRecord) AS MONTH,
				pv.QtyDocAct
			FROM
				AccountVacations AS acc
				INNER JOIN dbo.SysPocValue AS pv ON pv.IDRecord = acc.IDAccountVacation
				AND pv.IDRecordModule = acc.IDAccountVacationModule
				AND pv.MovementMode = 0
			WHERE
				(pv.IDSrc IS NOT NULL)
				AND (pv.Compensation = 0)
				AND (
					pv.IDSrcModule IN (
						
						SELECT
							IDModule
						FROM
							dbo.GetModulesRec('7E3F3313-558B-4567-96BB-573B78837B27')
					)
				)
		) AS t
	GROUP BY
		IDLogin,
		IDResource,
		IDAccount,
		YEAR
),
VacationDaysTaken AS (
	
	SELECT
		IDLogin,
		IDResource,
		IDAccount,
		YEAR,
		MONTH,
		ABS(ISNULL(SUM(QtyDocAct), 0)) AS VacationDays
	FROM
		(
			
			SELECT
				acc.IDLogin,
				acc.IDResource,
				acc.IDAccount,
				YEAR(pv.DateRecord) AS YEAR,
				MONTH(pv.DateRecord) AS MONTH,
				pv.QtyDocAct
			FROM
				AccountVacations AS acc
				INNER JOIN dbo.SysPocValue AS pv ON pv.IDRecord = acc.IDAccountVacation
				AND pv.IDRecordModule = acc.IDAccountVacationModule
				AND pv.MovementMode = 0
			WHERE
				(pv.IDSrcTimes IS NOT NULL)
				AND (pv.Compensation = 0)
				AND (pv.IDSrc IS NULL)
		) AS t
	GROUP BY
		IDLogin,
		IDResource,
		IDAccount,
		YEAR,
		MONTH
),
DetailedMovementsDayAbsenceJustified AS (
	
	SELECT
		pc.IDParent,
		SUM(DATEDIFF(MINUTE, pc.StartTime, pc.EndTime)) AS AbsJusRaw
	FROM
		TimeMovementsDay AS tm
		INNER JOIN dbo.SysPocValue AS pc ON pc.IDParent = tm.IDPocValue
		INNER JOIN dbo.SysTimeType AS tp ON tp.CodeInt = pc.TimeType
	WHERE
		(pc.TimeType <> 11)
		AND (tp.Origin IN (1))
		AND (pc.Compensation = 0)
	GROUP BY
		pc.IDParent
),
DetailedMovementsDayAbsenceUnjustified AS (
	
	SELECT
		pc.IDParent,
		SUM(DATEDIFF(MINUTE, pc.StartTime, pc.EndTime)) AS AbsRaw
	FROM
		TimeMovementsDay AS tm
		INNER JOIN dbo.SysPocValue AS pc ON pc.IDParent = tm.IDPocValue
	WHERE
		(pc.TimeType = 16)
		AND (pc.Compensation = 0)
	GROUP BY
		pc.IDParent
),
DetailedMovementsDayAbsenceVacation AS (
	
	SELECT
		pc.IDParent,
		SUM(DATEDIFF(MINUTE, pc.StartTime, pc.EndTime)) AS VacationRaw
	FROM
		TimeMovementsDay AS tm
		INNER JOIN dbo.SysPocValue AS pc ON pc.IDParent = tm.IDPocValue
	WHERE
		(pc.TimeType = 11)
		AND (pc.Compensation = 0)
	GROUP BY
		pc.IDParent
),
TimeMovementsDayV2 AS (
	
	SELECT
		tm.IDLogin,
		tm.IDResource,
		tm.IDAccount,
		tm.IDModule,
		tm.IDSysSchedulePlan,
		tm.TotalQtyActualStock,
		tm.IDContact,
		tm.IDContactModule,
		tm.AccountYear,
		tm.IDParent,
		tm.Year,
		tm.Month,
		tm.QtyActualStock,
		tm.TotalCredit,
		tm.TotalDebit,
		tm.IDPocValue,
		tm.DateRecord,
		tm.WorkingHoursDay,
		tm.DayOff,
		ISNULL(j.AbsJusRaw, 0) AS AbsJusRaw,
		ISNULL(uj.AbsRaw, 0) AS AbsRaw
	FROM
		TimeMovementsDay AS tm
		LEFT OUTER JOIN DetailedMovementsDayAbsenceJustified AS j ON tm.IDPocValue = j.IDParent
		LEFT OUTER JOIN DetailedMovementsDayAbsenceUnjustified AS uj ON tm.IDPocValue = uj.IDParent
),
GroupedMovements AS (
	
	SELECT
		IDLogin,
		IDResource,
		IDAccount,
		IDModule AS IDAccountModule,
		YEAR,
		MONTH,
		TotalQtyActualStock,
		WorkingHoursDay,
		SUM(QtyActualStock) AS QtyActualStock,
		SUM(TotalCredit) AS TotalCredit,
		SUM(TotalDebit) AS TotalDebit,
		SUM(AbsRaw) AS AbsRaw,
		SUM(AbsJusRaw) AS AbsJusRaw
	FROM
		TimeMovementsDayV2
	GROUP BY
		IDLogin,
		IDResource,
		IDAccount,
		IDModule,
		YEAR,
		MONTH,
		TotalQtyActualStock,
		WorkingHoursDay
),
GroupedMovementsV2 AS (
	
	SELECT
		gm.IDLogin,
		gm.IDResource,
		gm.IDAccount,
		gm.IDAccountModule,
		gm.Year,
		gm.Month,
		ABS(CAST(gm.TotalQtyActualStock AS INT)) AS TotalQtyActualStockHours,
		ABS(CAST(ROUND(gm.TotalQtyActualStock % 1 * 60, 2) AS INT)) AS TotalQtyActualStockMinutes,
		CASE WHEN TotalQtyActualStock < 0 THEN '-' ELSE '' END AS TotalQtyPreString,
		CAST(gm.WorkingHoursDay AS INT) AS WorkingHoursDay,
		CAST(ROUND(gm.WorkingHoursDay % 1 * 60, 2) AS INT) AS WorkingMinutesDay,
		ABS(CAST(gm.QtyActualStock AS INT)) AS QtyActualStockHours,
		ABS(CAST(ROUND(gm.QtyActualStock % 1 * 60, 2) AS INT)) AS QtyActualStockMinutes,
		CASE WHEN QtyActualStock < 0 THEN '-' ELSE '' END AS QtyActualStockPreString,
		CAST(gm.TotalCredit AS INT) AS TotalCreditHours,
		CAST(ROUND(gm.TotalCredit % 1 * 60, 2) AS INT) AS TotalCreditMinutes,
		CAST(gm.TotalDebit AS INT) AS TotalDebitHours,
		CAST(ROUND(gm.TotalDebit % 1 * 60, 2) AS INT) AS TotalDebitMinutes,
		gm.AbsRaw / 60 AS AbsHours,
		gm.AbsRaw % 60 AS AbsMinutes,
		gm.AbsJusRaw / 60 AS AbsJusHours,
		gm.AbsJusRaw % 60 AS AbsJusMinutes,
		CAST(
			ISNULL(vct.VacationDays, 0) * gm.WorkingHoursDay AS INT
		) AS VacationHours,
		CAST(
			ROUND(
				CAST(
					ISNULL(vct.VacationDays, 0) * gm.WorkingHoursDay AS INT
				) % 1 * 60,
				2
			) AS INT
		) AS VacationMinutes,
		ISNULL(vct.VacationDays, 0) AS VacationDays,
		gm.TotalQtyActualStock AS TotalQtyActualStockRaw,
		gm.WorkingHoursDay AS WorkingHoursDayRaw,
		gm.QtyActualStock AS QtyActualStockRaw,
		gm.TotalCredit AS TotalCreditRaw,
		gm.TotalDebit AS TotalDebitRaw,
		gm.AbsRaw / 60.0 AS AbsRaw,
		gm.AbsJusRaw / 60.0 AS AbsJusRaw,
		ISNULL(vct.VacationDays, 0) AS VacationRaw,
		CAST(ISNULL(adj.TotalAdjustment, 0) AS INT) AS TotalAdjustmentHours,
		CAST(ROUND(ISNULL(adj.TotalAdjustment, 0) % 1 * 60, 2) AS INT) AS TotalAdjustmentMinutes,
		ISNULL(adj.TotalAdjustment, 0) AS TotalAdjustmentRaw,
		ISNULL(vc.TotalVacationDays, 0) AS TotalVacationDays
	FROM
		GroupedMovements AS gm
		LEFT OUTER JOIN TimeMovementsAdjustment AS adj ON adj.IDLogin = gm.IDLogin
		AND adj.IDResource = gm.IDResource
		AND adj.IDAccount = gm.IDAccount
		AND gm.Month = adj.Month
		LEFT OUTER JOIN VacationDaysGiven AS vc ON vc.IDLogin = gm.IDLogin
		AND vc.IDResource = gm.IDResource
		--AND vc.IDAccount = gm.IDAccount
		AND vc.Year = gm.Year
		LEFT OUTER JOIN VacationDaysTaken AS vct ON vct.IDLogin = gm.IDLogin
		AND vct.IDResource = gm.IDResource
		AND vct.Month = gm.Month
		AND vct.Year = gm.Year
),
GroupedMovementsV3 AS (
	
	SELECT
		IDLogin,
		IDResource,
		IDAccount,
		IDAccountModule,
		YEAR,
		MONTH,
		 CONCAT(
			TotalQtyPreString,
			TotalQtyActualStockHours,
			'h',
			CASE WHEN TotalQtyActualStockMinutes = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', TotalQtyActualStockMinutes), 2),
				'min'
			) END
		)  AS TotalQtyActualStock,
		CONCAT(
			QtyActualStockPreString,
			QtyActualStockHours,
			'h',
			CASE WHEN QtyActualStockMinutes = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', QtyActualStockMinutes), 2),
				'min'
			) END
		)  AS QtyActualStock,
		CONCAT(
			WorkingHoursDay,
			'h',
			CASE WHEN WorkingMinutesDay = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', WorkingMinutesDay), 2),
				'min'
			) END
		)  AS WorkingHoursDay,
		CONCAT(
			TotalCreditHours,
			'h',
			CASE WHEN TotalCreditMinutes = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', TotalCreditMinutes), 2),
				'min'
			) END
		)  AS TotalCredit,
		 CONCAT(
			TotalDebitHours,
			'h',
			CASE WHEN TotalDebitMinutes = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', TotalDebitMinutes), 2),
				'min'
			) END
		)  AS TotalDebit,
		 CONCAT(
			AbsHours,
			'h',
			CASE WHEN AbsMinutes = 0 THEN '' ELSE CONCAT(' ', RIGHT(CONCAT('00', AbsMinutes), 2), 'min') END
		)  AS AbsenceTime,
		 CONCAT(
			AbsJusHours,
			'h',
			CASE WHEN AbsJusMinutes = 0 THEN '' ELSE CONCAT(' ', RIGHT(CONCAT('00', AbsJusMinutes), 2), 'min') END
		)  AS AbsenceJustifiedTime,
		CONCAT(
			VacationHours,
			'h',
			CASE WHEN VacationMinutes = 0 THEN '' ELSE CONCAT(' ', RIGHT(CONCAT('00', VacationMinutes), 2), 'min') END
		)  AS VacationTime,
		 CONCAT(
			CASE WHEN VacationDays % 1 > 0.0 THEN CONCAT(CAST(VacationDays AS INT), '.5') ELSE CONCAT(CAST(VacationDays AS INT), '') END,
			'd'
		)  AS VacationDays,
		 CONCAT(
			TotalAdjustmentHours,
			'h',
			CASE WHEN TotalAdjustmentMinutes = 0 THEN '' ELSE CONCAT(
				' ',
				RIGHT(CONCAT('00', TotalAdjustmentMinutes), 2),
				'min'
			) END
		)  AS TotalAdjustment,
		 CONCAT(
			CASE WHEN TotalVacationDays % 1 > 0.0 THEN CONCAT(TotalVacationDays, '') ELSE CONCAT(CAST(TotalVacationDays AS INT), '') END,
			'd'
		)  AS TotalVacationDays,
		TotalQtyActualStockRaw,
		WorkingHoursDayRaw,
		QtyActualStockRaw,
		TotalCreditRaw,
		TotalDebitRaw,
		AbsRaw,
		AbsJusRaw,
		VacationRaw,
		VacationDays AS VacationDaysRaw,
		TotalAdjustmentRaw,
		TotalVacationDays AS TotalVacationDaysRaw
	FROM
		GroupedMovementsV2
)
SELECT
	NEWID() AS FillerID,
	g.IDLogin,
	l.FullName AS LoginName,
	g.IDResource,
	res.Code AS ResourceName,
	g.Year,
	g.Month,
	g.TotalQtyActualStock AS ResourceCurrentBalance,
	g.TotalDebit AS RequiredTime,
	g.TotalCredit AS WorkingTime,
	g.QtyActualStock AS MonthBalance,
	g.AbsenceTime,
	g.AbsenceJustifiedTime,
	g.VacationTime,
	g.VacationDays,
	g.TotalQtyActualStockRaw AS ResourceCurrentBalanceRaw,
	g.QtyActualStockRaw AS MonthBalanceRaw,
	g.TotalCreditRaw AS WorkingTimeRaw,
	g.TotalDebitRaw AS RequiredTimeRaw,
	g.AbsRaw AS AbsenceTimeRaw,
	g.AbsJusRaw AS AbsenceJustifiedTimeRaw,
	g.VacationRaw AS VacationTimeRaw,
	g.VacationDaysRaw,
	g.TotalAdjustment,
	g.TotalAdjustmentRaw,
	g.TotalVacationDays,
	g.TotalVacationDaysRaw
FROM
	GroupedMovementsV3 AS g
	INNER JOIN dbo.SysLogin AS l ON l.IDLogin = g.IDLogin
	INNER JOIN dbo.SysResources AS res ON res.ResourceId = g.IDResource
GO


