-- ----------------------------
-- View structure for DefaultBankAccounts
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DefaultBankAccounts]') AND type IN ('V'))
	DROP VIEW [dbo].[DefaultBankAccounts]
GO

CREATE VIEW [dbo].[DefaultBankAccounts] WITH SCHEMABINDING AS SELECT 
		a.IDAccount, a.IDModule as IDAccountModule,
		ba.IDAccount as IDBankAccount, ba.IDModule as IDBankAccountModule
	FROM 
		dbo.Account ba
		INNER JOIN
		dbo.Entity e ON ba.IDContact =  e.organizationid and ba.IDContactModule = e.IDModule and ba.RegisterSysStatus = 0 and e.RegisterSysStatus = 0
		INNER JOIN
		dbo.Account a ON a.IDContact = e.organizationid and a.IDContactModule = e.IDModule and a.RegisterSysStatus = 0

	WHERE
		(
			(BA.IsDefaultAccount = 1)	
		)
		AND
		(
			(a.accounttype in (2) and ba.accounttype in (13))
			or
			(a.accounttype in (0, 1, 3, 7, 9) and ba.accounttype in (14))
		)
		AND
		ba.dbmask = a.dbmask
GO


