-- View structure for DocLinesSearchView
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DocLinesSearchView]') AND type IN ('V'))
	DROP VIEW [dbo].[DocLinesSearchView]
GO

CREATE VIEW [dbo].[DocLinesSearchView] AS SELECT        d.IDModule, dl.ID, dl.GridOrder, dl.LineDepth, dl.IDParent, dl.IDRegister AS IDDocument, dl.IDModule AS IDDocumentModule, dl.ProductName, dl.ProductCode, dl.Qty, dl.ValueWithVat, dl.NetTotal, d.doc_ref, 
                         d.doc_date AS [Document Date], e.IDAccount AS accountname, e.IDModule AS accountnameModule, e1.Name AS our_accountname_AC, e1.IDAccount AS our_accountname, e1.IDModule AS our_accountnameModule, 
                         e.Name AS accountname_AC, m.Name, dl.dim1, dl.Dim1Code, dl.dim1Module, dl.dim2, dl.Dim2Code, dl.dim2Module, dl.dim3, dl.Dim3Code, dl.dim3Module, dl.dim4, dl.Dim4Code, dl.dim4Module, dl.dim5, dl.Dim5Code, 
                         dl.dim5Module, dl.dim6, dl.Dim6Code, dl.dim6Module, dl.dim7, dl.Dim7Code, dl.dim7Module, dl.dim8, dl.Dim8Code, dl.dim8Module, dl.dim9, dl.Dim9Code, dl.dim9Module, dl.dim10, dl.Dim10Code, dl.dim10Module, dl.dim11, 
                         dl.Dim11Code, dl.dim11Module, dl.dim12, dl.Dim12Code, dl.dim12Module, dl.dim13, dl.Dim13Code, dl.dim13Module, dl.dim14, dl.Dim14Code, dl.dim14Module, dl.dim15, dl.Dim15Code, dl.dim15Module, dl.dim16, dl.Dim16Code, 
                         dl.dim16Module, dim16CodeIcon, dl.dim17, dl.Dim17Code, dl.dim17Module, dl.dim18, dl.Dim18Code, dl.dim18Module, dl.dim19, dl.Dim19Code, dl.dim19Module, dl.dim20, dl.Dim20Code, dl.dim20Module, dl.dim21, dl.dim21Code, 
                         dl.dim21Module, dl.LineNumber, d.commercial_name, d.status, d.subject, d.RegisterStatus, d.RegisterSysStatus, d.dbmask, d.IDResourceAssign, d.IDResourceCreation, d.ModifiedTime, d.IDUserCreation, d.IDTemplateSource, 
                         d.IDTemplateSourceModule, d.TeamAssignedMask01, d.TeamAssignedMask02, d.TeamMask01, d.TeamMask02, d.TemplateDefaultMFVCreate, d.CreatedTime, d.TemplateMFVCreate, d.IsTemplate, d.doc_print,
						 d.doc_3rd, d.doc_3rdModule, d.doc_3rd_account, d.doc_3rd_accountModule,d.ValueWithVat as DocValueWithVat, d.TotalExec as DocTotalExec
FROM            dbo.DocumentLine AS dl INNER JOIN
                         dbo.[document] AS d ON d.IDDocument = dl.IDRegister AND dl.IDLineType IN (1, 6) AND dl.PartitionColumn = d.PartitionColumn AND d.RegisterSysStatus = 0 LEFT OUTER JOIN
                         dbo.Account AS e ON e.IDAccount = d.doc_3rd_account LEFT OUTER JOIN
                         dbo.Account AS e1 ON e1.IDAccount = d.doc_account LEFT OUTER JOIN
                         dbo.SysModule AS m ON m.IDModule = d.IDModule
GO


-- ----------------------------
-- View structure for DocPendingPayment
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DocPendingPayment]') AND type IN ('V'))
	DROP VIEW [dbo].[DocPendingPayment]
GO

CREATE VIEW [dbo].[DocPendingPayment] AS SELECT *, signedPaymentValue - signedPaymentFullfil AS Remaining, 
CASE WHEN PendingLiquidationDocument IS NULL THEN 0 ELSE 1 END as HasPendingLiquidationDocument,
convert(numeric(18,2),  CASE WHEN signedValueWithVatExec <> 0 THEN (signedPaymentValue - signedPaymentFullfil) * 100 / signedValueWithVatExec ELSE 100 END) PaymentPercent
FROM
(
SELECT *,
CASE 
	WHEN DATEDIFF(day, PaymentPrevDate, getdate()) < -10  THEN 0
	WHEN DATEDIFF(day, PaymentPrevDate, getdate()) between -10 and 0 THEN 1
	WHEN PaymentPrevDate IS NULL AND IDParent IS NULL THEN NULL  
	ELSE 2
END colorCC,
CASE 
	WHEN isDocCred = 1 THEN ISNULL(PaymentValue,0) * -1 
	ELSE ISNULL(PaymentValue,0)
END signedPaymentValue,
CASE 
	WHEN isDocCred = 1 THEN ISNULL(PaymentFullfil,0) * -1 
	ELSE ISNULL(PaymentFullfil,0)
END signedPaymentFullfil,
CASE 
	WHEN isDocCred = 1 THEN ISNULL(ValueWithVatExec,0) * -1 
	ELSE ValueWithVatExec
END SignedValueWithVatExec
FROM(
SELECT	d.IDDocument, d.doc_date, d.doc_account, d.doc_accountModule, d.doc_3rd, d.doc_3rd_account, d.doc_3rd_account_name, d.doc_3rd_accountModule, d.IDModule, d.description descriptionDoc, d.ValueWithVatExec , pl.ID, 
		pl.IDParent, pl.ReferenceDateLine, pl.Description, pl.PaymentPrevDate, d.subject, 
		pl.PaymentValue, d.doc_ref, d.TotalExec, d.Total, d.IDUser, d.IDUserCreation, d.IDResourceCreation, d.IDResource, d.IDResourceAssign, 
		d.TemplateDefaultMFVCreate, d.TemplateMFVCreate,
		d.TeamMask01, d.TeamMask02, d.TeamAssignedMask01, d.TeamAssignedMask02,
		d.RegisterSysStatus, d.RegisterStatus, d.IsTemplate, d.IDTemplateSource, d.IDTemplateSourceModule, d.dbmask, d.doc_3rd_ref,
		ISNULL(pl.PaymentFullfil, 0) AS PaymentFullfil, d.PartitionColumn 
		, d.IDModule AS IDDocumentModule, d.CreatedTime, d.ModifiedTime, d.TemplateCode, d.ExchangeID,pl.LineNumber,
		CASE 
			WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) > 0 THEN CONVERT(nvarchar, DATEDIFF(day, pl.PaymentPrevDate, getdate()))
			WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 1 THEN 'Em dia'
			WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 2 THEN 'No Vencido'
			WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 3 THEN 'Not Expired'
		END daysDiff,
		CASE 
			WHEN d.IDModule IN(
				select IDModule from GetModulesRec('26B03AFC-C215-4890-BB56-3E96DE9FD3C1')
				union all
				select IDModule from GetModulesRec('7E1F0CD7-5DDE-467C-AE69-4C8FD7B07BC2')
			) THEN 1
			ELSE 0
		END IsDocCred, PendingLiquidationDocument,PendingLiquidationDocumentModule, pl.IDRegister,
		pl.dim1, pl.Dim1Code, pl.dim1Module, pl.dim1CodeIcon ,pl.dim2, pl.Dim2Code, pl.dim2Module, pl.dim2CodeIcon,
		pl.dim7, pl.Dim7Code, pl.dim7Module, pl.dim7CodeIcon , pl.dim18, pl.Dim18Code, pl.dim18Module, pl.dim18CodeIcon,
		pl.dim19, pl.Dim19Code, pl.dim19Module, pl.dim19CodeIcon, pl.dim20, pl.Dim20Code, pl.dim20Module, pl.dim20CodeIcon,
		pl.dim12, pl.Dim12Code, pl.dim12Module, pl.dim12CodeIcon, pl.dim13, pl.Dim13Code, pl.dim13Module, pl.dim13CodeIcon,
		pl.ComissionsAmmount, pl.ComissionComercial, pl.ComissionComercialPercentage,
		pl.ComissionInsideSales, pl.ComissionInsideSalesPercentage,
		pl.ComissionTechnician, pl.ComissionTechnicianPercentage,
		pl.ComissionComercial2, pl.ComissionComercial2Percentage,
		ComissionsDescendants.DescendantsComissionComercial, ComissionsDescendants.DescendantsComissionInsideSales, 
		ComissionsDescendants.DescendantsComissionTechnician, ComissionsDescendants.DescendantsComissionComercial2,
		ComissionsDescendants.DescendantsComissionsAmmount,
		CONCAT(d.doc_ref, case when Trim(pl.LineNumber) <> '' then CONCAT(' | (', pl.LineNumber, ')') end) LineLinkCode, 
		CONCAT(dbo.GetTranslationValue(mod.IDTranslation, mod.IDTranslationTarget, d.IDLanguage), ' | ', convert(nvarchar(10), d.doc_date, 120), case when Trim(pl.Description) <> '' THEN CONCAT(' | ', pl.Description) end ) LineLinkDescription,
		case when ((pl.PaymentValue <> ISNULL(pl.PaymentFullfil, 0)) AND (pl.Closed = 0)) then 1 else 0 end IsPending  
FROM dbo.[document] AS d 
INNER JOIN dbo.SysModule mod on mod.IDModule = d.IDModule
INNER JOIN dbo.DocumentLine AS pl ON d.IDDocument = pl.IDRegister AND pl.IDLineType IN(2,3) AND d.PartitionColumn = pl.PartitionColumn
LEFT JOIN dbo.DocumentLine AS plp ON plp.ID = pl.IDParent AND plp.IDLineType in(2,3) AND d.PartitionColumn = plp.PartitionColumn AND d.IDDocument = plp.IDRegister
OUTER APPLY (
	SELECT  top 1 IDDocument as PendingLiquidationDocument, doc.IDModule PendingLiquidationDocumentModule
	FROM document doc
	INNER JOIN DocumentLine payLine ON doc.IDDocument = payLine.IDRegister AND pl.IDLineType in(2,3) AND d.PartitionColumn = pl.PartitionColumn
	WHERE payLine.LineLink = pl.ID
	AND payLine.LineDocSrc= d.IDDocument
	AND doc.RegisterStatus = 0
) PendingLiquidationDocuments 
left join (
	select plDesc.LineDocSrc, plDesc.LineDocSrcModule, 
	SUM(plDesc.ComissionsAmmount) DescendantsComissionsAmmount,
	SUM(plDesc.ComissionComercial) DescendantsComissionComercial, 
	SUM(plDesc.ComissionInsideSales) DescendantsComissionInsideSales, 
	SUM(plDesc.ComissionTechnician) DescendantsComissionTechnician, 
	SUM(plDesc.ComissionComercial2) DescendantsComissionComercial2
	from  DocumentLine plDesc
	inner join document dDesc on plDesc.IDRegister = dDesc.IDDocument and plDesc.IDModule = dDesc.IDModule and plDesc.PartitionColumn = dDesc.PartitionColumn
	where plDesc.IDLineType = 3 and dDesc.RegisterStatus = 1
	group by plDesc.LineDocSrc, plDesc.LineDocSrcModule
) ComissionsDescendants on ComissionsDescendants.LineDocSrc = d.IDDocument and ComissionsDescendants.LineDocSrcModule = d.IDModule
WHERE 
--(pl.PaymentValue <> ISNULL(pl.PaymentFullfil, 0)) AND (pl.Closed = 0) AND 
(d.RegisterStatus = 1) AND plp.IDParent IS NULL
) T
)TT
GO


-- ----------------------------
-- View structure for DocumentLineConnections
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DocumentLineConnections]') AND type IN ('V'))
	DROP VIEW [dbo].[DocumentLineConnections]
GO

CREATE VIEW [dbo].[DocumentLineConnections] AS SELECT        ID, IDRegister, COALESCE
                            ((SELECT        TOP (1) 1 AS Expr1
                                FROM            dbo.DocumentLine AS tmp
                                WHERE        (LineLink = DocumentLine.ID AND IDLineType = 1)), 0) AS HasChild, CASE WHEN LineLink IS NULL OR
                        LineLink = 0 THEN 0 ELSE 1 END AS HasParent
FROM            dbo.DocumentLine
WHERE			IDLineType = 1
GO


-- ----------------------------
-- View structure for DocumentLinesWithDescendantInfo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DocumentLinesWithDescendantInfo]') AND type IN ('V'))
	DROP VIEW [dbo].[DocumentLinesWithDescendantInfo]
GO

CREATE VIEW [dbo].[DocumentLinesWithDescendantInfo] AS select *, CASE WHEN Qty = QtyDescendant THEN 1 ELSE 0 END AS QtyMatchesDescendants  
from(
	select dl.ID, dl.IDModule, d.doc_ref + ' - ' + dl.LineNumber as LineID, d.RegisterStatus, 
	dl.Qty, d.IDDocument,dl.IDModule as IDDocumentModule , d.doc_date, d.doc_3rd, doc_3rdModule, doc_3rd_account, doc_3rd_accountModule, doc_3rd_account_name,
	dl.productID, dl.ProductName, dl.dim14, dl.dim14Module, dl.Dim14Code, d.dbmask,
	count(distinct dlDesc.id) as NumberDescendants, sum(dlDesc.qty) as QtyDescendant
	from
	document d
	inner join DocumentLine dl on d.IDDocument = dl.IDRegister and d.IDModule = dl.IDModule and dl.PartitionColumn = d.PartitionColumn
	left join DocumentLine dlDesc on dl.ID = dlDesc.LineLink and dl.IDModule = dlDesc.LineLinkModule
	where dl.IDLineType = 1
	group by dl.ID, dl.IDModule, d.doc_ref, dl.LineNumber, d.RegisterStatus, dl.Qty, d.IDDocument, d.doc_date, 
	d.doc_3rd, doc_3rdModule, doc_3rd_account, doc_3rd_accountModule, doc_3rd_account_name,
	dl.productID, dl.ProductName, dl.dim14, dl.dim14Module, dl.Dim14Code, d.dbmask
) t
GO


