-- ----------------------------
-- View structure for FollowUpItemsRedundatActivitiesFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FollowUpItemsRedundatActivitiesFields]') AND type IN ('V'))
	DROP VIEW [dbo].[FollowUpItemsRedundatActivitiesFields]
GO

CREATE VIEW [dbo].[FollowUpItemsRedundatActivitiesFields] AS WITH activityFollowUpItems AS (SELECT        a2r.relatedRecord, a2r.relatedRecordModule, a.IDActivity, a.IDModule, a.subject, a.activityCode, a.startDate, a.status
                                                                      FROM            dbo.Activity AS a INNER JOIN
                                                                                                dbo.Activity2Record AS a2r ON a2r.IDActivity = a.IDActivity AND a2r.IDActivityModule = a.IDModule
                                                                      WHERE        (a2r.relatedRecordModule IN
                                                                                                    (SELECT        IDModule
                                                                                                      FROM            dbo.GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944') AS GetModulesRec_1)) AND (a.status IN (2726, 2724))), maxDateCompleted AS
    (SELECT        relatedRecord, relatedRecordModule, MAX(startDate) AS MaxDateCompleted
      FROM            activityFollowUpItems AS activityFollowUpItems_3
      WHERE        (status = 2726)
      GROUP BY relatedRecord, relatedRecordModule), maxDateCompletedAux AS
    (SELECT        afup.relatedRecord, afup.relatedRecordModule, MAX(afup.IDActivity) AS IDActivity
      FROM            activityFollowUpItems AS afup INNER JOIN
                                maxDateCompleted AS mca ON afup.relatedRecord = mca.relatedRecord AND afup.relatedRecordModule = mca.relatedRecordModule AND afup.startDate = mca.MaxDateCompleted
      WHERE        (afup.status = 2726)
      GROUP BY afup.relatedRecord, afup.relatedRecordModule), minDatePlanned AS
    (SELECT        relatedRecord, relatedRecordModule, MIN(startDate) AS MinDatePlanned
      FROM            activityFollowUpItems AS activityFollowUpItems_2
      WHERE        (status = 2724)
      GROUP BY relatedRecord, relatedRecordModule), minDatePlannedAux AS
    (SELECT        afup.relatedRecord, afup.relatedRecordModule, MAX(afup.IDActivity) AS IDActivity
      FROM            activityFollowUpItems AS afup INNER JOIN
                                minDatePlanned AS mpa ON afup.relatedRecord = mpa.relatedRecord AND afup.relatedRecordModule = mpa.relatedRecordModule AND afup.startDate = mpa.MinDatePlanned
      WHERE        (afup.status = 2724)
      GROUP BY afup.relatedRecord, afup.relatedRecordModule), maxCompletedActivities AS
    (SELECT        afup.relatedRecord, afup.relatedRecordModule, afup.IDActivity, afup.IDModule, afup.subject, afup.activityCode, afup.startDate, afup.status
      FROM            activityFollowUpItems AS afup INNER JOIN
                                maxDateCompletedAux AS mca ON afup.relatedRecord = mca.relatedRecord AND afup.relatedRecordModule = mca.relatedRecordModule AND afup.IDActivity = mca.IDActivity), minPlannedActivities AS
    (SELECT        afup.relatedRecord, afup.relatedRecordModule, afup.IDActivity, afup.IDModule, afup.subject, afup.activityCode, afup.startDate, afup.status
      FROM            activityFollowUpItems AS afup INNER JOIN
                                minDatePlannedAux AS mpa ON afup.relatedRecord = mpa.relatedRecord AND afup.relatedRecordModule = mpa.relatedRecordModule AND afup.IDActivity = mpa.IDActivity), followUpItems AS
    (SELECT        t.relatedRecord, t.relatedRecordModule, fup.RegisterStatus, fup.Status
      FROM            (SELECT DISTINCT relatedRecord, relatedRecordModule
                                FROM            activityFollowUpItems AS activityFollowUpItems_1) AS t INNER JOIN
                                dbo.FollowUpItem AS fup ON t.relatedRecord = fup.IDFollowUpItem AND t.relatedRecordModule = fup.IDModule)
    SELECT        IDFollowUpItem, IDFollowUpItemModule, RegisterStatus, PreviousIDActivity, PreviousIDActivityModule, PreviousActivityLabel, PreviousActivityDate, NextIDActivity, NextIDActivityModule, NextActivityLabel, NextActivityDate, 
                              DaysSinceLastCompleted, DaysUntilNextPlanned, Status, CASE WHEN RegisterStatus NOT IN (1, 4) AND DaysUntilNextPlanned > 5 AND Status NOT IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) 
                              THEN 0 WHEN RegisterStatus NOT IN (1, 4) AND DaysUntilNextPlanned <= 5 AND DaysUntilNextPlanned >= 0 AND Status NOT IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) 
                              THEN 1 WHEN RegisterStatus NOT IN (1, 4) AND DaysUntilNextPlanned < 0 AND DaysUntilNextPlanned >= - 5 AND Status NOT IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) 
                              THEN 2 WHEN RegisterStatus NOT IN (1, 4) AND DaysUntilNextPlanned < - 5 AND Status NOT IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) THEN 3 WHEN (RegisterStatus NOT IN (1, 4) AND 
                              NextIDActivity IS NULL) AND Status NOT IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) THEN 4 ELSE NULL END AS DaysUntilNextPlannedStatus
     FROM            (SELECT        fup.relatedRecord AS IDFollowUpItem, fup.relatedRecordModule AS IDFollowUpItemModule, fup.RegisterStatus, mca.IDActivity AS PreviousIDActivity, mca.IDModule AS PreviousIDActivityModule, 
                                                         CASE WHEN mca.IDActivity IS NULL THEN NULL ELSE CONCAT(mca.activityCode, ' - ', LEFT(mca.subject, 50)) END AS PreviousActivityLabel, mca.startDate AS PreviousActivityDate, 
                                                         mpa.IDActivity AS NextIDActivity, mpa.IDModule AS NextIDActivityModule, CASE WHEN mpa.IDActivity IS NULL THEN NULL ELSE CONCAT(mpa.activityCode, ' - ', LEFT(mpa.subject, 50)) END AS NextActivityLabel, 
                                                         mpa.startDate AS NextActivityDate, CASE WHEN fup.RegisterStatus IN (1, 4) OR
                                                         fup.Status IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) THEN NULL ELSE DATEDIFF(DAY, mca.startDate, GETDATE()) END AS DaysSinceLastCompleted, CASE WHEN fup.RegisterStatus IN (1, 
                                                         4) OR
                                                         fup.Status IN (2421, 2422, 2428, 2124, 2603, 2604, 2605, 2576, 2582, 2578) THEN NULL ELSE DATEDIFF(DAY, GETDATE(), mpa.startDate) END AS DaysUntilNextPlanned, fup.Status
                               FROM            followUpItems AS fup LEFT OUTER JOIN
                                                         maxCompletedActivities AS mca ON mca.relatedRecord = fup.relatedRecord AND mca.relatedRecordModule = fup.relatedRecordModule LEFT OUTER JOIN
                                                         minPlannedActivities AS mpa ON mpa.relatedRecord = fup.relatedRecord AND mpa.relatedRecordModule = fup.relatedRecordModule) AS t_1
GO


