CREATE VIEW [dbo].[MainSysDSItems] AS SELECT        dsi.IDSysDSItem, dsi.InheritanceType, dsi.IDSysDS, dsi.Name, dsi.Description, dsi.BdField, dsi.BdFieldType, dsi.IDSysUIComponent, dsi.TrackChanges, dsi.DefaultValue, dsi.LabelName, dsi.LabelShName, 
                         dsi.IDSysDSTableField, dsi.IDSysDT2SysUIC, dsi.SystemType, dsi.UseLink, dsi.Mandatory, dsi.IDDimension, dsi.DimensionIDFieldValue, dsi.FgColor, dsi.BgColor, dsi.DimensionMoveKind, dsi._DimensionAccountTypeID, 
                         dsi.UseDefaultLine, dsi.DimensionLinesToMove, dsi.SearchAccount, dsi.DimensionIDFieldFilter, dsi.LabelNameTrId, dsi.LabelShNameTrId, dsi.IDRelation, dsi.AGmask01, dsi.AGmask02, dsi.AGWmask01, dsi.AGWmask02, 
                         dsi.DimensionAccountTypeID, dsi.IDTranslationToolTip, dsi.dumyParent, dsi.MaskEdit, dsi.MaskDisplay, dsi.IsReadOnly, dsi.AutoTruncateValue, dsi.IDTranslationToolTipTarget, dsi.LabelShNameTrIdTarget, 
                         dsi.LabelNameTrIdTarget, dsi.AfterChangeScript, dsi.AfterChangeScriptModule, dsi.FastSearch, dsi.AutoUpdateWithPreSql, dsi.AutoUpdateWithSql, dsi.Code, dsi.Code_counter, dsi.Code_IsTemp, ds.Code AS dsCode, 
                         ds2m.Code AS ds2mCode, ds2m.IDSysModule
FROM            dbo.SysDSItem AS dsi INNER JOIN
                         dbo.SysDSToModule AS ds2m ON ds2m.IDSysDS = dsi.IDSysDS INNER JOIN
                         dbo.SysDS AS ds ON ds.IDSysDs = dsi.IDSysDS
WHERE        (ds2m.MainDS = 1)
