-- ----------------------------
-- View structure for MouldAssetProgressInfo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[MouldAssetProgressInfo]') AND type IN ('V'))
	DROP VIEW [dbo].[MouldAssetProgressInfo]
GO

CREATE VIEW [dbo].[MouldAssetProgressInfo] AS with mainMouldAssetInfo as(
	select newid() as ID, fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, a.IDAsset, a.IDModule as IDAssetModule, a.assetNo, a.assetName, a.IDProduct, a.IDProductModule, 
	concat(case when isnull(fupf.MouldNo, '') = '' then '' else concat(fupf.MouldNo ,'_') end ,apv.AssetNumber) AssetNumber, 
	apv.AssetDimensions, ISNULL(apv.Deadline, apv.CalculatedDeadline) Deadline,
	case 
		when apv.Deadline is null and apv.CalculatedDeadline is null then null
		when DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) > 15 then 0
		when DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) <= 15 and DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) > 10 then 1
		when DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) <= 10 and DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) > 5 then 2
		when DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) <= 5 and DATEDIFF(day, GETDATE(), isnull(apv.Deadline, apv.CalculatedDeadline)) >= 0 then 3
		else 4
	end as DeadLineStatus,
	r.WorkingStatus, accStk.TotalQtyActualStock, accStk.TotalQtyPendingProduction, accStk.TotalQtyOrderedToSupplier,
	r.IDRoutine, 'd27119a4-7cee-4614-a7e8-7c6eb4ed6e8d' as IDRoutineModule, apv.AssetVisibleDimensions,
	 a.status, apv.ProductionStatus
	from FollowUpItem fup
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	inner join Asset a on a.IDFollowUpItem = fupf.IDFollowUpItem
	inner join SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	inner join Account acc on acc.IDContact = a.IDAsset and acc.IDContactModule = a.IDModule
	inner join AccountStock accStk on accStk.IDAccount = acc.IDAccount
	left join SysOprRoutine r on r.IDAsset = a.IDAsset
	where a.IDModule not in(
		select IDModule from GetModulesRec('A66CF09C-87E6-4D43-99B1-3E06A513C7BC')
	) 
), routineItemsDoneEndDate as
(
	select r.IDRoutine, ri.IDRoutineItem,
	case 
		when ra.IDActivity is null and t.ID is not null then t.EndDate 
		when ra.IDActivity is not null and t.ID IS NULL then ra.endDate
		when ra.IDActivity is not null and t.id is not null then 
			case when t.EndDate > ra.endDate then t.EndDate else ra.endDate end
	end as EndDate
	from SysOprRoutine r
	inner join SysOprRoutineItem ri on ri.IDRoutine = r.IDRoutine
	LEFT JOIN Activity ra ON ri.IDRoutineItem = ra.IDOprRoutineItem
	LEFT JOIN SysPrRoutineRequest rq ON rq.IDOperation = ri.IDRoutineItem
	LEFT JOIN SysTimes t ON t.IDRequest = rq.ID
	where ri.WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2' and ri.IDOperationType is not null
), routineMaxEndDate as(
	select IDRoutine, MAX(EndDate) MaxEndDate
	from routineItemsDoneEndDate
	group by IDRoutine
), lastDoneRoutineItemByRoutine as(
	select r.IDRoutine, concat(r.Code, '(', op.Code, ')' ) as LastRoutineItemDone
	from(
		select t.IDRoutine, max(t.IDRoutineItem) as IDRoutineItem
		from(
			select ri.*
			from routineMaxEndDate m
			inner join routineItemsDoneEndDate ri on m.MaxEndDate = ri.EndDate
			where m.MaxEndDate is not null
		) t
		group by t.IDRoutine
	)tt
	left join SysOprRoutineItem r on r.IDRoutineItem = tt.IDRoutineItem
	left join SysOperationType op on op.IdOperationType = r.IDOperationType
), phasesByIdRoutine as
(
	select distinct a.IDRoutine, ri.IDPhaseTemplate, tv.Name as Code, ri.WorkingStatus
	from mainMouldAssetInfo a
	inner join SysOprRoutineItem ri on ri.IDRoutine = a.IDRoutine
	inner join SysProductionPhaseKind spk on spk.ID = ri.IDPhaseTemplate
	inner join SysTranslationValue tv on tv.IDTranslation = spk.IDTranslation and tv.IDLanguage = 1
), allPhasesByIDRoutine as
(
	select distinct IDRoutine, 
	STUFF ((
	SELECT Distinct ', '+ code  FROM phasesByIdRoutine t2 where t.IDRoutine = t2.IDRoutine
	FOR XML PATH(''), TYPE
		  ).value('.[1]', 'nvarchar(max)'), 1, 2, '') as AllPhases
	from phasesByIdRoutine t
)
, groupedPhasesOneWorkingStatus as 
(
	select IDRoutine, IDPhaseTemplate, Code
	from phasesByIdRoutine pb 
	group by IDRoutine, IDPhaseTemplate, Code
	having count(distinct WorkingStatus) = 1
), groupedPhasesDoneWorkingStatus as 
(
	select distinct IDRoutine, IDPhaseTemplate, Code
	from phasesByIdRoutine pb 
	where WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2'
	group by IDRoutine, IDPhaseTemplate, Code
), routinePhasesDone as (
	select one.IDRoutine, one.code
	from groupedPhasesOneWorkingStatus one
	inner join groupedPhasesDoneWorkingStatus d on d.IDRoutine = one.IDRoutine and d.IDPhaseTemplate = one.IDPhaseTemplate
)
, allDonePhasesByIDRoutine as
(
	select distinct IDRoutine, 
	STUFF ((
	SELECT Distinct ', '+ code  FROM routinePhasesDone t2 where t2.IDRoutine = t.IDRoutine
	FOR XML PATH(''), TYPE
		  ).value('.[1]', 'nvarchar(max)'), 1, 2, '') as AllPhasesDone
	from routinePhasesDone t
), routineItemsInProgress as
(
	select distinct ri.IDRoutine, concat(ri.Name, '(', op.Code, ')' ) as name
	from mainMouldAssetInfo a
	inner join SysOprRoutineItem ri on ri.IDRoutine = a.IDRoutine
	left join SysOperationType op on op.IdOperationType = ri.IDOperationType
	where ri.WorkingStatus in(
		'483D173F-7287-4751-A9D1-741DAAAB41E0', '2966AB3D-D7B6-4228-831B-342618A0FB13'
	) and ri.IDOperationType is not null
), groupedRoutineItemsInProgress as
(
select distinct IDRoutine, 
	STUFF ((
	SELECT Distinct ', '+ name  FROM routineItemsInProgress  t2 where t2.IDRoutine = t.IDRoutine
	FOR XML PATH(''), TYPE
		  ).value('.[1]', 'nvarchar(max)'), 1, 2, '') as AllItemsInProgress
	from routineItemsInProgress t
), nextRoutineItems as
(
	select ri.IDRoutine, concat(ri.Name, '(', op.Code, ')' ) as name
	from mainMouldAssetInfo a
	inner join SysOprRoutineItem ri on ri.IDRoutine = a.IDRoutine
	left join SysOperationType op on op.IdOperationType = ri.IDOperationType
	where ri.WorkingStatus in(
		'C6812E70-56CB-4394-84A5-4C3DE719B44E', '2C16A9FF-BB7D-416A-AC93-145377304BB5'
	) and ri.IDOperationType is not null
), groupedNextRoutineItems as
(
select distinct IDRoutine, 
	STUFF ((
	SELECT Distinct ', '+ name  FROM nextRoutineItems  GROUP By idroutine, name
	FOR XML PATH(''), TYPE
		  ).value('.[1]', 'nvarchar(max)'), 1, 2, '') as AllNextRoutineItems
	from nextRoutineItems
)
select a.*, lri.LastRoutineItemDone, ap.AllPhases, apd.AllPhasesDone, inp.AllItemsInProgress, nxt.AllNextRoutineItems
from mainMouldAssetInfo a
left join lastDoneRoutineItemByRoutine lri on lri.IDRoutine = a.IDRoutine
left join allPhasesByIDRoutine ap on ap.IDRoutine = a.IDRoutine
left join allDonePhasesByIDRoutine apd on apd.IDRoutine = a.IDRoutine
left join groupedRoutineItemsInProgress inp on inp.IDRoutine = a.IDRoutine
left join groupedNextRoutineItems nxt on nxt.IDRoutine = a.IDRoutine;
GO


-- ----------------------------
-- View structure for OperationLogsWithModuleAndViewNames
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[OperationLogsWithModuleAndViewNames]') AND type IN ('V'))
	DROP VIEW [dbo].[OperationLogsWithModuleAndViewNames]
GO

CREATE VIEW [dbo].[OperationLogsWithModuleAndViewNames] AS SELECT        OL.AppClientVersion, SM.Name AS Module, MF2FV.Name AS FormView, OL.OperationName, OL.OperationType AS OpType, 
                         CASE OL.OperationType WHEN 1 THEN 'DataSource' WHEN 2 THEN 'Rendering' WHEN 3 THEN 'Using' ELSE 'Undefined' END AS OpTypeName, OL.StartTime, OL.EndTime, CAST(OL.DurationMs / 1000.0 AS DECIMAL(10, 3)) 
                         AS DurationSec, OL.AppUserName
FROM            dbo.OperationLog AS OL LEFT OUTER JOIN
                         dbo.SysModule AS SM ON SM.IDModule = OL.IdModule LEFT OUTER JOIN
                         dbo.SysModuleFilter2FormView AS MF2FV ON MF2FV.IDModuleFilter2FormView = OL.IdModuleFilterView
GO


-- ----------------------------
-- View structure for PendingLinesView
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[PendingLinesView]') AND type IN ('V'))
	DROP VIEW [dbo].[PendingLinesView]
GO

CREATE VIEW [dbo].[PendingLinesView] AS SELECT        TOP (100) PERCENT p.ID, p.IDParent AS parent, d.doc_ref AS serie,   p.ProductName AS [desc], p.ProductCode AS code, 
                         p.OriginalQuantity AS qt, p.OriginalValue AS value, p.Balance, p.Propagation, p.dbmask, LTRIM(RTRIM(t.Code)) AS pendingtype, t.ID AS idpendingtype, m.Name AS IDDocument_AC, 
                         d.IDModule AS IDDocumentModule, d.IDDocument, 

						 e.IDAccount AS accountname, 
						 e.IDModule AS accountnameModule, 
						 e.Name AS accountname_AC,

                         e1.IDAccount AS our_accountname,
						 e1.IDModule AS our_accountnameModule,
						 e1.Name AS our_accountname_AC,

						 p.dbmask AS mask, d.doc_date AS [Document Date], 0 AS Selected, 

						 p.ProductCode,
						 p.ProductName,
						 p.Qty,
						 p.UnitPrice,
						 p.DiscountEur,
						 p.DiscountPerc1,
						 p.DiscountPerc2,
						 p.DiscountPerc3,

						 p.IDDocumentLine
						 

FROM            dbo.PendingLine AS p LEFT OUTER JOIN
                         dbo.[document] AS d ON d.IDDocument = p.IDRegister LEFT OUTER JOIN
                         dbo.Account AS e ON e.IDAccount = d.doc_3rd_account LEFT OUTER JOIN
                         dbo.Account AS e1 ON e1.IDAccount = d.doc_account LEFT OUTER JOIN
                         dbo.SysTypePending AS t ON t.ID = p.PendingType LEFT OUTER JOIN
                         dbo.SysModule AS m ON m.IDModule = p.IDModule
WHERE        (p.Blocked = 0) AND (p.Closed = 0)
ORDER BY 'Document Date', 'id'
GO


-- ----------------------------
-- View structure for ProdCountryVatTaxesActive
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ProdCountryVatTaxesActive]') AND type IN ('V'))
	DROP VIEW [dbo].[ProdCountryVatTaxesActive]
GO

CREATE VIEW [dbo].[ProdCountryVatTaxesActive] AS SELECT        ID, IDRegister, TaxPosition, _IDCountry, StartDate, EndDate, dbmask, IsTemplate, TemplateCode, ModifiedTime, CreatedTime, ExchangeID, RegisterStatus, RegisterSysStatus, IDModule, IDResourceCreation, 
                         IDUserCreation, IDResource, IDUser, IDResourceAssign, Rate, IDCountry
FROM            dbo.ProdCountryVatTaxes
WHERE        (StartDate <= GETDATE()) AND (EndDate >= GETDATE() OR
                         EndDate IS NULL)
GO


-- ----------------------------
-- View structure for ProductionAssetPendingLines
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ProductionAssetPendingLines]') AND type IN ('V'))
	DROP VIEW [dbo].[ProductionAssetPendingLines]
GO

CREATE VIEW [dbo].[ProductionAssetPendingLines] AS with main as
(
	select d.IDDocument, d.IDModule as IDDocumentModule, d.doc_ref, dlp.LineNumber, a.IDAsset, a.IDModule IDAssetModule, a.assetNo, 
	p.productcode, p.productname, accStk.TotalQtyActualStock, accStk.TotalQtyPendingProduction, case when a.IDSysPartRoutine is not null then 1 else 0 end as AssetAction, 
	supp.organizationid IDDefaultSupplier, supp.IDModule IDDefaultSupplierModule, supp.ShortName as SupplierName,
	accSup.IDAccount IDDefaultSupplierAccount, accSup.IDModule IDDefaultSupplierAccountModule, a.IDAccount IDAssetAccount, 
	a.IDAccountModule IDAssetAccountModule,apv.AssetCatalog, apv.AssetDimensions, apv.AssetNumber, apv.Material, apv.Hardness, apv.HeatTreatment, 
	case when p.AssetCreationModule in
	(
		select IDModule from GetModulesRec('1543F596-1571-4177-9B76-C6B32694C66C') 
		union all
		select IDModule from GetModulesRec('F2052F31-F688-44CD-8909-CAB0F84498FE') 
	)  then 1 else 0 end IsProduction,
	accstk.TotalQtyPendingProduction as Qty, a.serialNumber, a.assetName, a.IDProduct, a.IDProductModule,	
	a.dbmask, aMould.IDAsset IDAssetMould, aMould.IDModule IDAssetMouldModule, 
	a.IDSysPartRoutine,
	case 
		when p2pr.IDProduct2SysPartRoutine is not null and p2pr.IDSysPartRoutine = a.IDSysPartRoutine then p2pr.IDProduct2SysPartRoutine
		when p2pr.IDSysPartRoutinePostBlock = a.IDSysPartRoutine then p2pr.HelperID
		else null
		end
		as IDProduct2SysPartRoutine,
	fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule, fupf.IDSysDocOprRoutine as IDSysDocOprRoutineMould, a.status,
	apv.ProductionStatus, isnull(dlp.dim3, dlr.dim3) dim3, 
	case when dlp.Dim3Code is null or dlp.Dim3Code = '' then dlr.Dim3Code else dlp.Dim3Code end dim3Code, 
	isnull(dlp.dim3Module, dlr.dim3Module) dim3Module, isnull(dlp.dim3CodeIcon, dlr.dim3CodeIcon) dim3CodeIcon,
	apv.IDAssetBlockParent, apv.IDAssetBlockParentModule, dlp.BlockPartsParent, apv.AssetVisibleDimensions,
	p.IDProductionPurchaseDocModule, a.IDSysDocOprRoutine
	from Account acc
	inner join AccountStock accStk on acc.IDAccount = accStk.IDAccount and acc.IDModule = accStk.IDModule
	inner join Asset a on a.IDAsset = acc.IDContact and a.IDModule = acc.IDContactModule
	inner join SS_AssetPartValues apv on apv.IDAsset = a.IDAsset and apv.IDModule = a.IDModule
	left join SysPocValue poc on poc.IDRecord = acc.IDAccount and poc.IDRecordModule = acc.IDModule and poc.Compensation = 0 and poc.MovementMode = 0 and (poc.QtyPendingProduction <> 0 or poc.QtyPendingProduction is null)
	inner join FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	inner join Asset aMould on aMould.IDAsset = fupf.IDAsset and aMould.IDModule = fupf.IDAssetModule
	inner join products p on p.productid = a.IDProduct and a.IDProductModule = p.IDModule
	left join Product2SysPartRoutine p2pr on p2pr.IDProduct = p.productid and (p2pr.IDSysPartRoutine = a.IDSysPartRoutine or p2pr.IDSysPartRoutinePostBlock = a.IDSysPartRoutine)
	left join Entity supp on supp.organizationid = p.vendor_id and supp.IDModule = p.vendor_idModule
	left join Account accSup on accSup.IDContact = supp.organizationid and accSup.IDContactModule = supp.IDModule 
	and accSup.IDModule in(
		select IDModule from GetModulesRec('9BEDCA5D-5B46-4BC4-992D-D4EDD16EB166') where dbmask = a.dbmask
	)
	left join DocumentLine dlp on dlp.IDLineType = 7 and dlp.assetid = a.IDAsset and dlp.assetidModule = a.IDModule 
	and dlp.IDModule in
	(
		select IDModule from GetModulesRec('b90862cc-3bba-4bea-97f1-a8aebe470262')
	)
	left join document d on d.PartitionColumn = dlp.PartitionColumn and dlp.IDRegister = d.IDDocument and dlp.IDModule = d.IDModule
	left join DocumentLine dlr on d.PartitionColumn = dlr.PartitionColumn and dlr.IDRegister = d.IDDocument and dlr.IDModule = d.IDModule and dlr.IDParent is null
	left join Product2SysPartRoutine p2part on p2part.IDProduct = p.productid and p2part.IDProductModule = p.IDModule and isnull(p2part.IsDefault, 0) = 1
	where 
	(
		(a.status not in(2801,2802,2803,2804,2805) and apv.ProductionStatus = 2) 
		or (a.status = 2801 and apv.ProductionStatus <> 2) 
		or (a.status not in(2801,2802,2803,2804,2805) and apv.ProductionStatus <> 2) 
	)
	and a.IDModule in(
		select IDModule from GetModulesRec('6B17ACA1-96E4-4E94-BB59-53E472F70389')
	)
	and a.IDModule not in(
		select IDModule from GetModulesRec('A66CF09C-87E6-4D43-99B1-3E06A513C7BC')
	)

	and (d.IDDocument is null or d.IDDocument is not null and d.RegisterStatus = 1)
	
)
, accStocks as
(
	select acc.IDContact as IDProduct, acc.IDContactModule as IDProductModule, acc.dbmask, 
	acc.IDAccount as IDAccountProduct, acc.IDModule as IDAccountProductModule, acc.account_no as AccountProductName,
	isnull(accStk.TotalQtyActualStock,0) as AccountProductCurrentStock, accStk.MinQty, accStk.ReorderQty	
	from Account acc 
	inner join AccountStock accStk on accStk.IDAccount = acc.IDAccount and accStk.IDModule = acc.IDModule
	where acc.IDContactModule = 'A8B3844C-D081-48ED-A1E5-25B992FFA353' and acc.IDContact in
	(
		select distinct IDProduct from main
	) and acc.IDParent is not null and isnull(accStk.StockManagement, 0) = 1
)
select newid() as IDProductionPendingAsset, m.*, acc.IDAccountProduct, acc.IDAccountProductModule, acc.AccountProductName, acc.AccountProductCurrentStock,
case when m.IsProduction = 1 then 'B9687ABE-1F38-4910-AC8A-F2E157079A45' else 'A3578C79-F024-4F1B-9DA3-07CF196649C4' end as DocModuleToCreate, 
acc.MinQty, acc.ReorderQty
from main m
left join accStocks acc on acc.IDProduct = m.IDProduct and acc.IDProductModule = m.IDProductModule
GO


-- ----------------------------
-- View structure for QualificationQuestionTree
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[QualificationQuestionTree]') AND type IN ('V'))
	DROP VIEW [dbo].[QualificationQuestionTree]
GO

CREATE VIEW [dbo].[QualificationQuestionTree] AS select -1 as ID,
Type,Name,
IDQualificationQuestion as IDRegister,IDModule,null as IDParent  
from QualificationQuestion 
Union 
select ID,Type,Name,IDRegister,IDModule,ISNULL( IDParent,-1) as   IDParent
from QualificationQuestionLine
GO


-- ----------------------------
-- View structure for RecordLastPlannedActivities
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[RecordLastPlannedActivities]') AND type IN ('V'))
	DROP VIEW [dbo].[RecordLastPlannedActivities]
GO

CREATE VIEW [dbo].[RecordLastPlannedActivities] AS select t.relatedRecord IDRecord, t.relatedRecordModule IDModule, a.IDActivity, a.IDModule as IDActivityModule, a.startDate, 
	CONCAT(a.activityCode, ' | ', convert(varchar(19), a.startdate, 120), ' | ', LEFT(a.subject,30), ' | ', r.DisplayName) FieldDisplay,
	dbo.GetIDIconFromModule(a.IDModule) ActivityModuleIcon
	from Activity a
	inner join (
		select a2r.relatedRecord, a2r.relatedRecordModule, min(a.IDActivity) IDActivity ,min(tt.MinStart) MinStart
		FROM Activity2Record a2r
		inner join Activity a on a2r.IDActivity = a.IDActivity
		inner join (
			select a2r.relatedRecord, a2r.relatedRecordModule, min(a.startDate) as MinStart
			from Activity2Record a2r
			inner join Activity a on a2r.IDActivity = a.IDActivity
			and [status] = 2724
			group by a2r.relatedRecord, a2r.relatedRecordModule 
		) tt on a2r.relatedRecord = tt.relatedRecord and a2r.relatedRecordModule = tt.relatedRecordModule and (a.startDate = tt.MinStart or (a.startDate is null and tt.MinStart is null))
		group by a2r.relatedRecord, a2r.relatedRecordModule
	) t on a.IDActivity = t.idactivity
	left join SysResources r on a.IDResourceAssign = r.ResourceId
GO


-- ----------------------------
-- View structure for ResourcesTotalHoursDay
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ResourcesTotalHoursDay]') AND type IN ('V'))
	DROP VIEW [dbo].[ResourcesTotalHoursDay]
GO

CREATE VIEW [dbo].[ResourcesTotalHoursDay] AS WITH SchedulesMinMax as
(
	select spl.IDSysSchedulePlan, spl.IDSchedule, 
	isnull(spl.StartDate, (select cast('1753-1-1' as datetime))) StartDate, 
	isnull(spl.EndDate, (select cast('9999-12-30' as datetime))) EndDate, 
	MIN(scl.StartTime) ScheduleStart, MAX(scl.EndTime) ScheduleEnd, sum(DATEDIFF(minute, scl.StartTime, scl.EndTime)) / 60 WorkingHoursDay
	from SysSchedulePlanLine spl
	inner join SysScheduleLine scl on scl.IDSchedule = spl.IDSchedule
	group by spl.IDSysSchedulePlan, spl.IDSchedule, spl.StartDate, spl.EndDate
), TimeMovements as(
	select l2r.IDLogin, null as IDAsset, l2r.IDResource, pv.DateRecord Date, pv.QtyActualStock DayExtraTime,  CAST(pv.QtyActualStock  AS INT) Hours, pv.QtyActualStock % 1 MinutesRaw, 
	pv.StartTime, pv.EndTime, scm.ScheduleStart, scm.ScheduleEnd,pv.TotalCredit, pv.TotalDebit, pv.RealDurationDescription, pv.CalculatedDurationDescription,
	case 
		when pv.TotalDebit = 0 then 1 
		when pv.TotalDebit <> 0 and pv.TotalDebit <> scm.WorkingHoursDay then 2
		else 0 end DayOff
	from Account acc
	inner join Entity e on e.organizationid = acc.IDContact and e.IDModule = acc.IDContactModule
	inner join SysLogin2SysResource l2r on l2r.IDPerson = e.organizationid and l2r.IDPersonModule = e.IDModule and l2r.Active = 1 
	inner join SysResources res on res.ResourceId = l2r.IDResource
	inner join SysPocValue pv on pv.IDRecord = acc.IDAccount and pv.IDRecordModule = acc.IDModule and pv.MovementMode = 0
	inner join SchedulesMinMax scm on scm.IDSysSchedulePlan = res.IDSysSchedulePlan and pv.DateRecord >= scm.StartDate and pv.DateRecord <= scm.EndDate
	and pv.IDSrc is null
	where acc.IDModule in(
		select IDModule from GetModulesRec('25C1DD8B-3766-4384-A3C1-4338D6EEFCF7')
	)
	
	union all

	select null, a.IDAsset ,l2r.IDResource, pv.DateRecord Date, pv.QtyActualStock DayExtraTime,  CAST(pv.QtyActualStock  AS INT) Hours, pv.QtyActualStock % 1 MinutesRaw, 
	pv.StartTime, pv.EndTime, null as ScheduleStart, null as ScheduleEnd,pv.TotalCredit, pv.TotalDebit, pv.RealDurationDescription, pv.CalculatedDurationDescription,
	case 
		when pv.TotalDebit = 0 then 1 
		when pv.TotalDebit <> 0  then 2
		else 0 end DayOff
	from Account acc
	inner join Asset a on a.IDAsset = acc.IDContact and a.IDModule = acc.IDContactModule
	inner join Asset2SysResource l2r on l2r.IDAsset = a.IDAsset and l2r.IDAssetModule = a.IDModule and l2r.Active = 1 
	inner join SysResources res on res.ResourceId = l2r.IDResource
	inner join SysPocValue pv on pv.IDRecord = acc.IDAccount and pv.IDRecordModule = acc.IDModule and pv.MovementMode = 0
	--left join SchedulesMinMax scm on scm.IDSysSchedulePlan = res.IDSysSchedulePlan and pv.DateRecord >= scm.StartDate and pv.DateRecord <= scm.EndDate
	and pv.IDSrc is null
	where acc.IDModule in(
		select IDModule from GetModulesRec('18B18F12-E13F-4E12-B5F7-85C49034F425')
	)
)
, PartialDaysSchedule as
(
	select t.*, DATEADD(HOUR, offset, StartSchedule) AlternativeStartSchedule, DATEADD(HOUR, offset, EndSchedule) AlternativeEndSchedule
	from
	(
		select tm.Date, tm.IDResource, tm.IDLogin, DATEPART(TZOFFSET, tm.Date AT TIME ZONE 'GMT Standard Time') / 60 offset, MIN(tSc.StartDate) StartSchedule, MAX(tsc.EndDate) EndSchedule
		from TimeMovements tm
		inner join SysTimes tSc on tsc.IDUser = tm.IDLogin and tsc.IDResource = tm.IDResource
		and year(tsc.StartDate) = YEAR(tm.Date) and month(tsc.StartDate) = month(tm.Date) and day(tsc.StartDate) = day(tm.Date) 
		and tSc.TimelineType = 1 and tSc.Type = 7
		where DayOff = 2
		group by tm.Date, tm.IDResource, tm.IDLogin
	) t
)
select IDResource, Date, DayExtraTime, DayExtraTimeDesc,StartTime, EndTime,TotalCredit, RealDurationDescription,RealDuration,
case when DayOff = 1 then null else StartSchedule end StartSchedule, 
case when DayOff = 1 then null else DATEDIFF(minute, StartTime, StartSchedule) end DiffStart, 
case when DayOff = 1 then null else EndSchedule end EndSchedule, 
case when DayOff = 1 then null else DATEDIFF(minute, EndSchedule, EndTime) end DiffEnd
from
(
	select tt.*, CONCAT(
		case when DayExtraTime < 0 Then '-' else '' end,
		case when Hours <> 0 then concat(abs(Hours), 'h ') else '' end,
		case when Minutes <> 0 then concat(abs(Minutes), 'min') else '' end
	) DayExtraTimeDesc, 
	case 
		when StartTime is null then null
		when DayOff = 2 and pds.Date is not null then AlternativeStartSchedule 
		else CONVERT(datetime,concat(CONVERT(varchar(10), StartTime, 120), ' ', RIGHT(CONVERT(varchar(100), ScheduleStart, 120), 8) )) 
	end StartSchedule,
	case 
		when EndTime is null then null
		when DayOff = 2 and pds.Date is not null then AlternativeEndSchedule 
		else CONVERT(datetime,concat(CONVERT(varchar(10), EndTime, 120), ' ', RIGHT(CONVERT(varchar(100), ScheduleEnd, 120), 8))) 
	end EndSchedule,
	CONCAT(
		case when DurationHours like '' or DurationHours like '00' Then '' else concat(abs(DurationHours), 'h ')  end,
		case when DurationMinutes like '' or DurationHours like '00' then '' else concat(abs(DurationMinutes), 'min') end
	) RealDuration
	from
	(
		select *,CAST(MinutesRaw * 60  AS INT) Minutes,
		case when RealDurationDescription = '' or RealDurationDescription is null or LEFT(RealDurationDescription, 1) like '-' then '' else LEFT(RealDurationDescription, 2) end as DurationHours,
		case when RealDurationDescription = '' or RealDurationDescription is null or LEFT(RealDurationDescription, 1) like '-' then '' else RIGHT(LEFT(RealDurationDescription, 5),2) end as DurationMinutes
		from TimeMovements t
	) tt
	left join PartialDaysSchedule pds on tt.DayOff = 2 and pds.Date = tt.Date and pds.IDResource = tt.IDResource and pds.IDLogin = tt.IDLogin 
) ttt
GO


-- ----------------------------
-- View structure for ResourceVehiclesLastGPSCoordinate
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ResourceVehiclesLastGPSCoordinate]') AND type IN ('V'))
	DROP VIEW [dbo].[ResourceVehiclesLastGPSCoordinate]
GO

CREATE VIEW [dbo].[ResourceVehiclesLastGPSCoordinate] AS WITH ve2res AS (SELECT        vt.IDTracker, v2r.IDResource, res.DisplayName, ISNULL(v2r.StartDate, '1900-01-01') AS StartDate, ISNULL(v2r.EndDate, '2099-12-31') AS EndDate
                                      FROM            dbo.VehicleTracker AS vt LEFT OUTER JOIN
                                                               dbo.VehicleTracker2SysResource AS v2r ON vt.ID = v2r.IDTracker LEFT OUTER JOIN
                                                               dbo.SysResources AS res ON res.ResourceId = v2r.IDResource AND (v2r.StartDate IS NULL OR
                                                               v2r.StartDate <= GETDATE()) AND (v2r.EndDate IS NULL OR
                                                               v2r.EndDate >= GETDATE())), maxDatesResource AS
    (SELECT        v2r.IDResource, v2r.DisplayName, vtc.IDTracker, MAX(vtc.Date) AS MaxDate
      FROM            dbo.VehicleTrackerCoordinates AS vtc INNER JOIN
                                ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker AND vtc.Date >= v2r.StartDate AND vtc.Date <= v2r.EndDate
      WHERE        (v2r.IDResource IS NOT NULL)
      GROUP BY v2r.IDResource, v2r.DisplayName, vtc.IDTracker
      UNION ALL
      SELECT        v2r.IDResource, v2r.DisplayName, vtc.IDTracker, MAX(vtc.Date) AS MaxDate
      FROM            dbo.VehicleTrackerProcessedCoordinates AS vtc INNER JOIN
                               ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker AND vtc.Date >= v2r.StartDate AND vtc.Date <= v2r.EndDate
      WHERE        (v2r.IDResource IS NOT NULL)
      GROUP BY v2r.IDResource, v2r.DisplayName, vtc.IDTracker), maxDatesNoResource AS
    (SELECT        vtc.IDTracker, MAX(vtc.Date) AS MaxDate
      FROM            dbo.VehicleTrackerCoordinates AS vtc INNER JOIN
                                ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker AND v2r.IDResource IS NULL
      GROUP BY vtc.IDTracker
      UNION ALL
      SELECT        vtc.IDTracker, MAX(vtc.Date) AS MaxDate
      FROM            dbo.VehicleTrackerProcessedCoordinates AS vtc INNER JOIN
                               ve2res AS v2r ON v2r.IDTracker = vtc.IDTracker AND v2r.IDResource IS NULL
      GROUP BY vtc.IDTracker), baseResource AS
    (SELECT        md.IDResource, md.DisplayName, md.IDTracker, vtc.Date, vtc.Lat, vtc.Lon, vtc.Speed, vtc.CreatedTime
      FROM            maxDatesResource AS md INNER JOIN
                                dbo.VehicleTrackerCoordinates AS vtc ON vtc.IDTracker = md.IDTracker AND vtc.Date = md.MaxDate
      UNION ALL
      SELECT        md.IDResource, md.DisplayName, md.IDTracker, vtc.Date, vtc.Lat, vtc.Lon, vtc.Speed, vtc.CreatedTime
      FROM            maxDatesResource AS md INNER JOIN
                               dbo.VehicleTrackerProcessedCoordinates AS vtc ON vtc.IDTracker = md.IDTracker AND vtc.Date = md.MaxDate), baseNoResource AS
    (SELECT        NULL AS IDResource, NULL AS DisplayName, md.IDTracker, vtc.Date, vtc.Lat, vtc.Lon, vtc.Speed, vtc.CreatedTime
      FROM            maxDatesNoResource AS md INNER JOIN
                                dbo.VehicleTrackerCoordinates AS vtc ON vtc.IDTracker = md.IDTracker AND vtc.Date = md.MaxDate
      UNION ALL
      SELECT        NULL AS IDResource, NULL AS DisplayName, md.IDTracker, vtc.Date, vtc.Lat, vtc.Lon, vtc.Speed, vtc.CreatedTime
      FROM            maxDatesNoResource AS md INNER JOIN
                               dbo.VehicleTrackerProcessedCoordinates AS vtc ON vtc.IDTracker = md.IDTracker AND vtc.Date = md.MaxDate), maxDatesPerResource AS
    (SELECT        IDResource, MAX(Date) AS MaxDate
      FROM            baseResource AS baseResource_1
      GROUP BY IDResource)
    SELECT        NEWID() AS ID, b.IDResource, b.DisplayName, b.IDTracker, b.Date, b.Lat, b.Lon, b.Speed, b.CreatedTime
     FROM            baseResource AS b INNER JOIN
                              maxDatesPerResource AS md ON md.IDResource = b.IDResource AND md.MaxDate = b.Date
GO


-- ----------------------------
-- View structure for RolesForAccount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[RolesForAccount]') AND type IN ('V'))
	DROP VIEW [dbo].[RolesForAccount]
GO

CREATE VIEW [dbo].[RolesForAccount] AS select distinct acc.IDAccount, acc.IDModule, rol.IDActivityRole, rol.Code, e.organizationid, e.IDModule organizationIDModule
from account acc
inner join Entity e on e.organizationid = acc.IDContact and e.IDModule = acc.IDContactModule
inner join SysLogin2SysResource l2r on l2r.IDLogin = e.IDRelatedLogin and l2r.Active = 1
inner join SysActivityRoleResource arr on arr.IDResource = l2r.IDResource
inner join SysRole rol on rol.IDActivityRole = arr.IDActivityRole
GO


-- ----------------------------
-- View structure for ServiceContract2AccountAssetHourPackActive
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ServiceContract2AccountAssetHourPackActive]') AND type IN ('V'))
	DROP VIEW [dbo].[ServiceContract2AccountAssetHourPackActive]
GO

CREATE VIEW [dbo].[ServiceContract2AccountAssetHourPackActive] AS with serviceC2Asset as(
	select s2a.IDRecServContr, s2a.IDRecServContrModule, a.IDAsset, a.IDModule, a.start, a.status 
	from ServiceContract2Asset s2a
	inner join Asset a on a.IDAsset = s2a.IDRecAsset and a.IDModule = s2a.IDRecAssetModule
	where a.status is not null and a.status = 2787 
	and a.IDModule in 
	(
		'43BC1559-1A20-43A2-9499-0EB3E738D1C7',
		'D5800746-0B4E-4DB3-B0DB-2AF7DA0955CD',
		'0DD3DB58-3946-4272-8603-BD8290D83088',
		'74F7D339-CA10-472D-8B79-F076C6561F97'
	)
), minDateAssetActive as
(
	select IDRecServContr, IDRecServContrModule, MIN(start) start
	from serviceC2Asset
	group by IDRecServContr, IDRecServContrModule
), minDateAssetActiveAux as 
(
	select s2a.IDRecServContr, s2a.IDRecServContrModule, MAX(IDAsset) IDAsset
	from serviceC2Asset s2a
	inner join minDateAssetActive mda on mda.IDRecServContr = s2a.IDRecServContr and mda.IDRecServContrModule =s2a.IDRecServContrModule and mda.start = s2a.start
	group by s2a.IDRecServContr, s2a.IDRecServContrModule
)
select s2a.IDRecServContr as IDServiceContract, s2a.IDRecServContrModule as IDServiceContractModule, accAsset.IDAccount as IDAccountAssetHourPackActive, accAsset.IDModule as IDAccountAssetHourPackActiveModule
from serviceC2Asset s2a
inner join minDateAssetActiveAux aux on s2a.IDRecServContr = aux.IDRecServContr and s2a.IDRecServContrModule = aux.IDRecServContrModule and s2a.IDAsset = s2a.IDAsset
inner join Account accAsset on accAsset.IDContact = s2a.IDAsset and accAsset.IDContactModule = s2a.IDModule
GO


