CREATE VIEW [dbo].[SysDSItemSF] AS SELECT
	m.IDModule AS IDSysModule, 
	ds2mod.IDSysDS2SysModule, 
	dsitem.IDSysDSItem, 
	dsitem.BdField
FROM            
	dbo.SysModule AS m 
INNER JOIN
	(SELECT        IDModule, dbo.GetModuleWithConf(IDModule) AS ModuleWithConf
	FROM            dbo.SysModule) AS aux ON m.IDModule = aux.IDModule 
INNER JOIN
	dbo.SysDSToModule AS ds2mod ON aux.ModuleWithConf = ds2mod.IDSysModule 
INNER JOIN
	dbo.SysDSItem AS dsitem ON ds2mod.IDSysDS = dsitem.IDSysDS AND ds2mod.MainDS = 1 AND dsitem.IDSysUIComponent = '7F8B20B2-EB23-42A5-817A-8FBA23064682'
GO


