CREATE VIEW [dbo].[SysMenuLinks] AS SELECT        Extent1.dbmask, Extent1.IDModule, Extent1.Name, Extent1.Sequence, Extent1.IDTranslation, Extent1.IDParent, Extent1.dbconfig, Extent1.FileSaving, Extent1.FgColor, Extent1.BgColor, 
                         Extent1.IdCountryItem, Extent1.IdDateItem, Extent1.AsksForVat, Extent1.KeepLinkToInheritanceView, Extent1.KeepLinkToInheritanceConfs, Extent1.IDIcon, Extent1.TypeField, Extent1.TrackerMode, 
                         Extent1.ModuleType, Extent1.Description, Extent1.IDAccountItem, Extent1.IDAccountTypeItem, Extent1.IsYearChange, Extent1.StartCounter, Extent1.CurrentCounter, Extent1.IDSerieItem, Extent1.Mask, 
                         Extent1.LastUpdated, Extent1.LastDocumentDate, Extent1.HasTmp, Extent1.TmpStartCounter, Extent1.TmpCurrentCounter, Extent1.TmpMask, Extent1.TmpLastUpdated, Extent1.TmpLastDocumentDate, 
                         Extent1.Action, Extent1.TmpAction, Extent1.SavesInEntity, Extent1.EntityNameItem, Extent1.AGmask01, Extent1.AGmask02, Extent1.AGWmask01, Extent1.AGWmask02, Extent1.KindTransaction, 
                         Extent2.IDSysFormView, Extent2.Name AS Name1, Extent2.Description AS Description1, Extent2.ViewType, Extent2.IDSysModule, Extent2.IDTranslation AS IDTranslation1, Extent2.Template, 
                         Extent2.IDSysViewContainer, Extent2.SystemType, Extent2.PopUpWidth, Extent2.PopUpHeight, Extent3.IDModuleFilter2FormView, Extent3.IDTranslation AS IDTranslation2, 
                         Extent3.IDSysFormView AS IDSysFormView1, Extent3.IDModuleFilter, Extent3.IDSysModule AS IDSysModule1, Extent3.IDModuleFilter2FormViewCreate, Extent3.AGmask01 AS AGmask011, 
                         Extent3.AGmask02 AS AGmask021, Extent3.AGWmask01 AS AGWmask011, Extent3.AGWmask02 AS AGWmask021
