-- ----------------------------
-- View structure for SysTasksInSprints
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysTasksInSprints]') AND type IN ('V'))
	DROP VIEW [dbo].[SysTasksInSprints]
GO

CREATE VIEW [dbo].[SysTasksInSprints] AS select	
	t.IDTask, t.IDModule as idTaskModule,
	fu.IDFollowUpItem, fu.IDModule as idfollowupitemModule, fu.Code, fu.[Name], fu.[Description]
from 
	systask t 
	inner join 
	(select
		IDTask,
		(select top 1
			fu.IDFollowUpItem
		from 
			SysTask t with(nolock)
			inner join SysTask2Record t2r  with(nolock) on t.IDTask = t2r.IDTask
			inner join FollowUpItem fu  with(nolock) on t2r.IDRecord = fu.IDFollowUpItem and t2r.IDRecordModule = fu.IDModule 
			inner join dbo.GetModulesRec('75AEE07B-0CD5-45EE-AC1C-F2B6A3D3B005') m on fu.IDModule = m.IDModule
		where 
			t.IDTask = main.IDTask
		order by 
			fu.CreationDate desc) as IDFollowUpItem
	from SysTask main
	) aux on t.IDTask = aux.IDTask
	inner join FollowUpItem fu on aux.IDFollowUpItem = fu.IDFollowUpItem
GO


