CREATE VIEW [dbo].[TeamRoleResourceView] AS SELECT        arr.IDResource, arr.IDActivityRole, t.IDTeam, t.Mask1, t.Mask2, r.RecordsTeamAccess, r.RecordsRoleAccess, r.RecordsTeammatesAccess
FROM            dbo.SysActivityRoleResource AS arr INNER JOIN
                         dbo.SysTeam AS t ON t.IDTeam = arr.IDTeam INNER JOIN
                         dbo.SysRole AS r ON r.IDActivityRole = arr.IDActivityRole
