-- ----------------------------
-- View structure for TimesToActivityView
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TimesToActivityView]') AND type IN ('V'))
	DROP VIEW [dbo].[TimesToActivityView]
GO

CREATE VIEW [dbo].[TimesToActivityView] AS SELECT
	(
		SELECT
			COUNT(arra2.IDTask)
		FROM
			SysTaskResourceRole arra2
		WHERE
			IDTask = t.IDTask
	) AS countTimes,
	CAST(task.IDTask AS nvarchar(100)) AS IDTask,
	task.IDModule,
	task.ProgressPercentage AS ProgressPercentage,
	task.runningStatus AS a_status,
	a.kind AS a_kind,
	task.AutoEnd AS a_AutoEnd,
	task.ShortName AS a_subject,
	ARRA.IDActivityRole,
	NULL AS IDRole,
	
	/*obsolete*/
	t.ID,
	t.StartDate,
	t.EndDate,
	t.Status,
	t.Duration,
	t.AutoEnd,
	t.IDUser,
	t.IDResource,
	t.TimeType,
	t.Code,
	task.Code AS activityCode,
	t.Type,
	COALESCE (task.shortname, t.Subject) AS Subject,
	t.Kind,
	ISNULL(a.type, 0) AS a_type,
	task.RegisterSysStatus,
	task.dbmask AS a_dbmask,
	task.TeamMask01 AS a_TeamMask01,
	task.TeamMask02 AS a_TeamMask02,
	0 AS IsTeamAssigned,
	a.Schedule,
	a.[Commit],
	t.Closed,
	t.Timelinetype,
	t.IDTimeRelated,
	TRRA.[LastRunningStatus],
	(
		
		SELECT
			STRING_AGG(CONCAT(IDResource, ''), ',') Resources
		FROM
			(
				
				SELECT
					trral.IDResource
				FROM
					dbo.SysTimesResourceRoleTask arral
					INNER JOIN dbo.SysTaskResourceRole trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTask task ON trral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND arral.IDSysTime = t.ID
					AND trral.IDResource IS NOT NULL
				UNION ALL
				
				SELECT
					arr.IDResource
				FROM
					dbo.SysTaskResourceRole arral
					INNER JOIN dbo.SysTimesResourceRoleTask trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTeam tt ON (tt.Mask1 & arral.TeamMask01) != 0
					OR (tt.Mask2 & arral.TeamMask02) != 0
					INNER JOIN SysActivityRoleResource arr ON arr.IDTeam = tt.IDTeam
					INNER JOIN SysRole r ON arr.IDActivityRole = r.IDActivityRole
					INNER JOIN SysTask task ON arral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND trral.IDSysTime = t.ID
					AND arral.IDResource IS NULL
					AND arral.IDActivityRole IS NULL
					AND r.TeamParticipation = 1
				UNION ALL
				
				SELECT
					arr.IDResource
				FROM
					dbo.SysTaskResourceRole arral
					INNER JOIN dbo.SysTimesResourceRoleTask trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTeam tt ON (tt.Mask1 & arral.TeamMask01) != 0
					OR (tt.Mask2 & arral.TeamMask02) != 0
					INNER JOIN SysActivityRoleResource arr ON arr.IDTeam = tt.IDTeam
					INNER JOIN SysRole r ON arr.IDActivityRole = r.IDActivityRole
					INNER JOIN SysTask task ON arral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND trral.IDSysTime = t.ID
					AND arral.IDResource IS NULL
					AND arral.IDActivityRole IS NOT NULL
					AND r.TeamParticipation = 1
					AND r.IDActivityRole = arral.IDActivityRole
			) r
	) AS AssignedResources,
	t.OwnUserChangedPoint,
	ISNULL(a.AppointmentType, 0) AppointmentType,
	(
		
		SELECT
			TOP 1 t2c.IDChannel
		FROM
			SysTask2Channel t2c
		WHERE
			t2c.Participation = 0
			AND t2c.IDTask = task.IDTask
	) AS IDChannel,
	(
		
		SELECT
			TOP 1 wr.Name
		FROM
			SysTask2Channel t2c
			INNER JOIN SysWorkRoom wr ON wr.IDWorkRoom = t2c.IDChannel
		WHERE
			t2c.Participation = 0
			AND t2c.IDTask = task.IDTask
	) AS OwnerChannelName, isnull(t.MachineError,0) MachineError
FROM
	dbo.SysTimes AS t
	LEFT OUTER JOIN dbo.SysTimesResourceRoleTask AS TRRA ON t.ID = TRRA.IDSysTime
	LEFT OUTER JOIN dbo.SysTaskResourceRole AS ARRA ON TRRA.IDTaskResourceRole = ARRA.IDTaskResourceRole
	LEFT OUTER JOIN dbo.SysTask AS task ON task.IDTask = ARRA.IDTask
	LEFT OUTER JOIN dbo.Activity AS a ON a.IDActivity = task.IDActivity
WHERE
	(task.RegisterSysStatus IS NULL)
	OR (task.RegisterSysStatus = 0)
UNION ALL
SELECT
	(
		
		SELECT
			COUNT(arra2.IDActivity)
		FROM
			SysActivityResourceRoleActivity arra2
		WHERE
			IDActivity = a.IDActivity
	) AS countTimes,
	CAST(a.IDActivity AS nvarchar(100)) AS IDTask,
	a.IDModule,
	0 AS ProgressPercentage,
	a.status AS a_status,
	a.kind AS a_kind,
	a.AutoEnd AS a_AutoEnd,
	a.subject AS a_subject,
	ARRA.IDActivityRole,
	NULL AS IDRole,
	
	/*obsolete*/
	t.ID,
	t.StartDate,
	t.EndDate,
	t.Status,
	t.Duration,
	t.AutoEnd,
	t.IDUser,
	t.IDResource,
	t.TimeType,
	t.Code,
	a.activityCode,
	t.Type,
	COALESCE (a.subject, t.Subject) AS Subject,
	t.Kind,
	ISNULL(a.type, 0) AS a_type,
	a.RegisterSysStatus,
	a.dbmask AS a_dbmask,
	a.TeamMask01 AS a_TeamMask01,
	a.TeamMask02 AS a_TeamMask02,
	0 AS IsTeamAssigned,
	a.Schedule,
	a.[Commit],
	t.Closed,
	t.Timelinetype,
	t.IDTimeRelated,
	TRRA.[LastRunningStatus],
	(
		
		SELECT
			STRING_AGG(CONCAT(IDResource, ''), ',') Resources
		FROM
			(
				
				SELECT
					trral.IDResource
				FROM
					dbo.SysTimesResourceRoleTask arral
					INNER JOIN dbo.SysTaskResourceRole trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTask task ON trral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND arral.IDSysTime = t.ID
					AND trral.IDResource IS NOT NULL
				UNION ALL
				
				SELECT
					arr.IDResource
				FROM
					dbo.SysTaskResourceRole arral
					INNER JOIN dbo.SysTimesResourceRoleTask trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTeam tt ON (tt.Mask1 & arral.TeamMask01) != 0
					OR (tt.Mask2 & arral.TeamMask02) != 0
					INNER JOIN SysActivityRoleResource arr ON arr.IDTeam = tt.IDTeam
					INNER JOIN SysRole r ON arr.IDActivityRole = r.IDActivityRole
					INNER JOIN SysTask task ON arral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND trral.IDSysTime = t.ID
					AND arral.IDResource IS NULL
					AND arral.IDActivityRole IS NULL
					AND r.TeamParticipation = 1
				UNION ALL
				
				SELECT
					arr.IDResource
				FROM
					dbo.SysTaskResourceRole arral
					INNER JOIN dbo.SysTimesResourceRoleTask trral ON arral.IDTaskResourceRole = trral.IDTaskResourceRole
					INNER JOIN SysTeam tt ON (tt.Mask1 & arral.TeamMask01) != 0
					OR (tt.Mask2 & arral.TeamMask02) != 0
					INNER JOIN SysActivityRoleResource arr ON arr.IDTeam = tt.IDTeam
					INNER JOIN SysRole r ON arr.IDActivityRole = r.IDActivityRole
					INNER JOIN SysTask task ON arral.IDTask = task.IDTask
				WHERE
					task.IDActivity = a.IDActivity
					AND trral.IDSysTime = t.ID
					AND arral.IDResource IS NULL
					AND arral.IDActivityRole IS NOT NULL
					AND r.TeamParticipation = 1
					AND r.IDActivityRole = arral.IDActivityRole
			) r
	) AS AssignedResources,
	t.OwnUserChangedPoint,
	ISNULL(a.AppointmentType, 0) AppointmentType,
	(
		
		SELECT
			TOP 1 a2c.IDChannel
		FROM
			Activity2Channel a2c
		WHERE
			a2c.Participation = 0
			AND a2c.IDActivity = a.IDActivity
	) AS IDChannel,
	(
		
		SELECT
			TOP 1 wr.Name
		FROM
			Activity2Channel a2c
			INNER JOIN SysWorkRoom wr ON wr.IDWorkRoom = a2c.IDChannel
		WHERE
			a2c.Participation = 0
			AND a2c.IDActivity = a.IDActivity
	) AS OwnerChannelName, isnull(t.MachineError,0) MachineError
FROM
	dbo.SysTimes AS t
	LEFT OUTER JOIN dbo.SysTimesResourceRoleTask AS TRRA ON t.ID = TRRA.IDSysTime
	LEFT OUTER JOIN dbo.SysActivityResourceRoleActivity AS ARRA ON TRRA.IDActivityResourceRoleActivity = ARRA.IDActivityResourceRoleActivity
	LEFT OUTER JOIN dbo.Activity AS a ON a.IDActivity = arra.IDActivity
	LEFT OUTER JOIN SysResources res on res.ResourceId = t.IDResource
WHERE
	(
		(a.RegisterSysStatus IS NULL)
		OR (a.RegisterSysStatus = 0)
	)
	AND (
		(
			t.TimeType = 2
			AND a.status = 2724
		)
		OR
		(
			t.TimeType = 2
			AND a.status = 2725
			AND res.Kind in(1,2,3,4)
		)
		OR t.TimeType != 2
	)
UNION ALL
SELECT
	(
		
		SELECT
			COUNT(arra2.IDTask)
		FROM
			SysTaskResourceRole arra2
		WHERE
			IDTask = t.IDTask
	) AS countTimes,
	CAST(t.IDTask AS nvarchar(100)),
	t.IDModule,
	t.ProgressPercentage AS ProgressPercentage,
	t.runningStatus AS a_status,
	a.kind AS a_kind,
	t.AutoEnd AS a_AutoEnd,
	t.ShortName AS a_subject,
	ARRA.IDActivityRole,
	NULL AS IDRole,
	NULL,
	t.StartDate,
	t.EndDate,
	t.runningStatus AS [Status],
	t.Duration,
	t.AutoEnd,
	arra.IDUser,
	arra.IDResource,
	NULL,
	NULL,
	t.Code AS activityCode,
	a.[Type],
	t.ShortName AS [Subject],
	NULL,
	ISNULL(a.type, 0) AS a_type,
	t.RegisterSysStatus,
	t.dbmask AS a_dbmask,
	t.TeamMask01 AS a_TeamMask01,
	t.TeamMask02 AS a_TeamMask02,
	1 AS IsTeamAssigned,
	a.Schedule,
	a.[Commit],
	0 AS Closed,
	0 AS TimelineType,
	NULL AS IDTimeRelated,
	TRRA.[LastRunningStatus],
	'' AS IDResources,
	0 AS OwnUserChangedPoint,
	ISNULL(a.AppointmentType, 0) AppointmentType,
	(
		
		SELECT
			TOP 1 t2c.IDChannel
		FROM
			SysTask2Channel t2c
		WHERE
			t2c.Participation = 0
			AND t2c.IDTask = t.IDTask
	) AS IDChannel,
	(
		
		SELECT
			TOP 1 wr.Name
		FROM
			SysTask2Channel t2c
			INNER JOIN SysWorkRoom wr ON wr.IDWorkRoom = t2c.IDChannel
		WHERE
			t2c.Participation = 0
			AND t2c.IDTask = t.IDTask
	) AS OwnerChannelName, 0 as MachineError
FROM
	dbo.SysTaskResourceRole AS ARRA
	INNER JOIN dbo.SysResources AS RES ON RES.ResourceId = arra.IDResource
	LEFT OUTER JOIN dbo.SysTimesResourceRoleTask AS TRRA ON TRRA.IDTaskResourceRole = ARRA.IDTaskResourceRole
	LEFT OUTER JOIN dbo.SysTask AS t ON t.IDTask = ARRA.IDTask
	LEFT OUTER JOIN dbo.Activity AS a ON t.IDActivity = a.IDActivity
WHERE
	(
		(t.RegisterSysStatus IS NULL)
		OR (t.RegisterSysStatus = 0)
	)
	AND res.kind = 2
	AND TRRA.ID IS NULL
UNION ALL
SELECT
	(
		
		SELECT
			COUNT(arra2.IDActivity)
		FROM
			SysActivityResourceRoleActivity arra2
		WHERE
			IDActivity = a.IDActivity
	) AS countTimes,
	CAST(a.IDActivity AS nvarchar(100)) AS IDTask,
	a.IDModule,
	0 AS ProgressPercentage,
	a.[Status] AS a_status,
	a.kind AS a_kind,
	a.AutoEnd AS a_AutoEnd,
	a.[Subject] AS a_subject,
	ARRA.IDActivityRole,
	NULL AS IDRole,
	NULL,
	a.StartDate,
	a.EndDate,
	a.[Status],
	a.Duration,
	a.AutoEnd,
	arra.IDUser,
	arra.IDResource,
	NULL,
	NULL,
	a.activityCode,
	a.[Type],
	a.[Subject],
	NULL,
	ISNULL(a.type, 0) AS a_type,
	a.RegisterSysStatus,
	a.dbmask AS a_dbmask,
	a.TeamMask01 AS a_TeamMask01,
	a.TeamMask02 AS a_TeamMask02,
	1 AS IsTeamAssigned,
	a.Schedule,
	a.[Commit],
	0 AS Closed,
	0 AS TimelineType,
	NULL AS IDTimeRelated,
	TRRA.[LastRunningStatus],
	'' AS IDResources,
	0 AS OwnUserChangedPoint,
	ISNULL(a.AppointmentType, 0) AppointmentType,
	(
		
		SELECT
			TOP 1 a2c.IDChannel
		FROM
			Activity2Channel a2c
		WHERE
			a2c.Participation = 0
			AND a2c.IDActivity = a.IDActivity
	) AS IDChannel,
	(
		
		SELECT
			TOP 1 wr.Name
		FROM
			Activity2Channel a2c
			INNER JOIN SysWorkRoom wr ON wr.IDWorkRoom = a2c.IDChannel
		WHERE
			a2c.Participation = 0
			AND a2c.IDActivity = a.IDActivity
	) AS OwnerChannelName, 0 as MachineError
FROM
	dbo.SysActivityResourceRoleActivity AS ARRA
	INNER JOIN dbo.SysResources AS RES ON RES.ResourceId = arra.IDResource
	LEFT OUTER JOIN dbo.SysTimesResourceRoleTask AS TRRA ON TRRA.IDActivityResourceRoleActivity = ARRA.IDActivityResourceRoleActivity
	LEFT OUTER JOIN dbo.Activity AS a ON arra.IDActivity = a.IDActivity
WHERE
	(
		(a.RegisterSysStatus IS NULL)
		OR (a.RegisterSysStatus = 0)
	)
	AND res.kind = 2
	AND TRRA.ID IS NULL
GO


-- ----------------------------
-- View structure for TimesWork
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TimesWork]') AND type IN ('V'))
	DROP VIEW [dbo].[TimesWork]
GO

CREATE VIEW [dbo].[TimesWork] AS WITH _cte
AS (select IDResource,IDUser,
 CAST(x.dt AS DATE) as DateWork,
 DATEPART(DW,CAST(x.dt AS DATE)) as DateWeekday,
WorkHours=SUM(
	case 
		-- Start and End Same day
		when CAST(x.dt AS DATE) = CAST(StartDate AS DATE) and CAST(x.dt AS DATE) = CAST(EndDate AS DATE)
			then DATEDIFF(second, StartDate, EndDate) / 3600.0
		-- Start before end same day
		when CAST(x.dt AS DATE) < CAST(StartDate AS DATE)  and CAST(x.dt AS DATE) = CAST(EndDate AS DATE) 
			then DATEDIFF(second, DATEADD(MS, -1, DATEADD(D, -1, CONVERT(DATETIME2,CAST(x.dt AS DATE) ))) ,  EndDate ) / 3600.0
		-- Start before end after day
		when CAST(x.dt AS DATE) > CAST(StartDate AS DATE)  and  CAST(x.dt AS DATE) < CAST(EndDate AS DATE) 
			then 24.0
		-- Start same day end after day
		when CAST(x.dt AS DATE) = CAST(StartDate AS DATE) AND CAST(x.dt AS DATE) < CAST(EndDate AS DATE) 
			then DATEDIFF(second, 
				StartDate  ,  
				DATEADD(MS, -1, DATEADD(D, 1, CONVERT(DATETIME2,CAST(StartDate AS DATE) ))) 
				) / 3600.0
	END)
from SysTimes 
CROSS APPLY  dbo.ExplodeDates(StartDate,EndDate) as x
where TimeType=1 
and (type=7 or type=8)
GROUP BY  CAST(x.dt AS DATE) , IDResource,IDUser
)
SELECT t.IDResource,t.IDUser,t.DateWork,t.DateWeekday,t.WorkHours,
(case 
 when t.DateWeekday =1 OR t.DateWeekday =7 then
	t.WorkHours	
 else
	t.WorkHours-7.67
end) as DiffWork8Hours,
r.dbmask
FROM _cte t
Left Join SysResources r on r.ResourceId =t.IDResource
GO


