-- ----------------------------
-- View structure for Unit2UnitConversionAndTypeConversions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Unit2UnitConversionAndTypeConversions]') AND type IN ('V'))
	DROP VIEW [dbo].[Unit2UnitConversionAndTypeConversions]
GO

CREATE VIEW [dbo].[Unit2UnitConversionAndTypeConversions] AS with convs as
	(
		select * 
		from Unit2UnitConversion 
	), concatValues as
	(
		select CONCAT(IDUnitSrc, '|', IDUnitDest) IDConcat
		from convs
	)
	select u.*, dest.Code as DestCode, src.Type
	from convs u 
	inner join usageunit dest on dest.IDUsageunit = u.IDUnitDest
	inner join usageunit src on src.IDUsageunit = u.IDUnitSrc

	union all

	select (ROW_NUMBER() OVER(ORDER BY u.IDUsageunit DESC) + (select count(*) from convs)) as ID, u.IDUsageunit, u.IDModule, uu.IDUsageunit, uu.IDModule,
	uu.InternalConversionFactor,
	null,null, null,uu.code, uu.code, null, uu.code, uu.code, u.Type
	from usageunit u
	inner join usageunit uu on u.Type = uu.Type and u.IDUsageunit <> uu.IDUsageunit
	where CONCAT(u.IDUsageunit, '|', uu.IDUsageunit) not in
	(
		select IDConcat from concatValues
	)
GO


