        e2e.Phone,
        e2e.IDModule,
        e2e.[Start],
        e2e.[End],
        e.ShortName,
        e2e.dbmask,
        e2e.ContactName
    FROM Entity2Entity e2e
    LEFT JOIN Entity e 
        ON e.organizationid = e2e.IDRecEntityChild
       AND e.IDModule = e2e.IDRecEntityChildModule
    WHERE e2e.RegisterSysStatus = 0
    
    UNION ALL
    
    SELECT
        e2e.ID,
        e2e.IDRecEntityChild,
        e2e.IDRecEntityChildModule,
        e2e.IDRecEntity,
        e2e.IDRecEntityModule,
        ert.InverseRelationship AS TYPE,
        e2e.Description,
        e.Gender,
        e2e.OurTitle,
        e2e.IDLocation,
        e2e.IDLocationModule,
        e2e.roleInCompany,
        e2e.departament,
        e2e.InsuranceNumber,
        e2e.Active,
        e2e.Title,
        e2e.Fax,
        e2e.Email,
        e2e.Skype,
        e2e.Mobile,
        e2e.Phone,
        e2e.IDModule,
        e2e.[Start],
        e2e.[End],
        e.ShortName,
        e2e.dbmask,
        e2e.ContactName
    FROM Entity2Entity e2e
    LEFT JOIN Entity e 
        ON e.organizationid = e2e.IDRecEntity
       AND e.IDModule = e2e.IDRecEntityModule
    LEFT JOIN EntityRelationshipType ert 
        ON ert.ID = e2e.Type
    WHERE e2e.RegisterSysStatus = 0
),
-- aggregate contracts
contracts as (
    select 
        sc.IDEntityRelatedTo as organizationid,
        sum(case when sc.status = 2667/*Em progresso*/ then 1 else 0 end) as service_contracts_progress,
        sum(case when sc.status = 2669/*Terminado*/ then 1 else 0 end) as service_contracts_terminated,
        STRING_AGG(cast(sc.subject  + ' [' 
                + case 
                    when sc.status = 2667 then 'A'
                    when sc.status = 2669 then 'I'
                    else 'D'
                  end
                + ']'  as nvarchar(max)), ';'+ CHAR(13) + CHAR(10)) as service_contracts
    from ServiceContract sc
    where sc.RegisterSysStatus != 1
      and sc.dbmask & 32 != 0
      and (sc.status = 2669/*Terminado*/ or sc.status = 2667/*Em progresso*/)
    group by sc.IDEntityRelatedTo
),
-- aggregate contacts
contacts as (
    select 
        c.IDRecEntity as organizationid,
        STRING_AGG(
            cast(
                ltrim(rtrim(c.ShortName)) 
                + case 
                    when c.Email is not null and c.Mobile is not null and  c.Email<>'' and c.Mobile<>''
                        then ' (' + c.Email + ', ' + c.Mobile + ')'
                    when c.Email is not null and c.Email <>''
                        then ' (' + c.Email + ')'
                    when c.Mobile is not null  and c.Mobile<>''
                        then ' (' + c.Mobile + ')'
                    else ''
                  end 
                as nvarchar(max)
            ), ';' + CHAR(13) + CHAR(10)
        ) as contactos
    from contacts_cte c
    where c.IDModule = 'CB58FE26-69E2-4D6A-9837-A3AE6AE901A4' /*Company2PersonRelationship*/
      and (c.dbmask & 32) != 0  
      and c.Active = 1
    group by c.IDRecEntity
)
select 
    e.organizationid,
    e.organization_no,
    e.ShortName,
	e.billingzip,
	e.billingstate,
	e.phone,
	e.email,
	e.accountname,
    a.account_no,
    a.dbmask,
    isnull(ct.service_contracts_progress,0) as service_contracts_progress,
    isnull(ct.service_contracts_terminated,0) as service_contracts_terminated,
    ct.service_contracts,
    co.contactos,
	isnull(lc.num_licenses,0) as num_licenses_in_service,
    lc.licenses
from entity e
inner join Account a 
    on a.IDContact = e.organizationid 
   and a.IDModule ='23175555-6410-4e63-a30f-321a0955b97e' /*Acc_Customer_ADN*/
   and a.RegisterSysStatus != 1
   and a.dbmask & 32 != 0
left join contracts ct 
    on ct.organizationid = e.organizationid
left join contacts co 
    on co.organizationid = e.organizationid
outer apply (
    select 
        count(*) as num_licenses,
        STRING_AGG(cast(l.assetName as nvarchar(max)), ';'+ CHAR(13) + CHAR(10)) as licenses
    from Entity2AssetsTree(e.organizationid, '053a9991-2090-4855-ac8d-34c2f5300dd6') l
    where l.status = '2787' /*In Service*/
      and l.dbmask & 32 <> 0
) lc
where e.RegisterSysStatus != 1
GO


-- ----------------------------
-- View structure for vw_ClientContractsLicenses
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_ClientContractsLicenses]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_ClientContractsLicenses]
GO

CREATE VIEW [dbo].[vw_ClientContractsLicenses] AS WITH contacts_cte AS (
	
	SELECT
		e2e.IDRecEntity AS organizationid,
		e2e.IDModule,
		e2e.dbmask,
		e.ShortName,
		e2e.Email,
		e2e.Mobile
	FROM
		dbo.Entity2Entity AS e2e
		LEFT OUTER JOIN dbo.Entity AS e ON e.organizationid = e2e.IDRecEntityChild
		AND e.IDModule = e2e.IDRecEntityChildModule
	WHERE
		(e2e.RegisterSysStatus = 0)
		AND (e2e.Active = 1)
	UNION ALL
	
	SELECT
		e2e.IDRecEntityChild AS organizationid,
		e2e.IDModule,
		e2e.dbmask,
		e.ShortName,
		e2e.Email,
		e2e.Mobile
	FROM
		dbo.Entity2Entity AS e2e
		LEFT OUTER JOIN dbo.Entity AS e ON e.organizationid = e2e.IDRecEntity
		AND e.IDModule = e2e.IDRecEntityModule
	WHERE
		(e2e.RegisterSysStatus = 0)
		AND (e2e.Active = 1)
),
contracts AS (
(
SELECT
    sd.dbmask,
    sc.IDEntityRelatedTo AS organizationid,
    SUM(CASE WHEN sc.status = 2667 THEN 1 ELSE 0 END) AS service_contracts_progress,
    SUM(CASE WHEN sc.status = 2669 THEN 1 ELSE 0 END) AS service_contracts_terminated,
    STRING_AGG(
        CAST(
            sc.subject + ' [' + CASE WHEN sc.status = 2667 THEN 'A' WHEN sc.status = 2669 THEN 'I' ELSE 'D' END + ']' AS nvarchar(MAX)
        ),
        ';' + CHAR(13) + CHAR(10)
    ) AS service_contracts
FROM
    dbo.ServiceContract AS sc
    CROSS APPLY (
        SELECT dbmask
        FROM dbo.SysDB 
        WHERE sc.dbmask & SysDB.dbmask > 0  -- Bitwise AND: if ANY shared bit exists
    ) sd
WHERE
    (sc.RegisterSysStatus <> 1)
    AND (
        sc.status = 2669
        OR sc.status = 2667
    )
GROUP BY
    sd.dbmask,
    sc.IDEntityRelatedTo
)
	/*
	SELECT
		dbmask,
		IDEntityRelatedTo AS organizationid,
		SUM(CASE WHEN sc.status = 2667 THEN 1 ELSE 0 END) AS service_contracts_progress,
		SUM(CASE WHEN sc.status = 2669 THEN 1 ELSE 0 END) AS service_contracts_terminated,
		STRING_AGG(
			CAST(
				subject + ' [' + CASE WHEN sc.status = 2667 THEN 'A' WHEN sc.status = 2669 THEN 'I' ELSE 'D' END + ']' AS nvarchar(MAX)
			),
			';' + CHAR(13) + CHAR(10)
		) AS service_contracts
	FROM
		dbo.ServiceContract AS sc
	WHERE
		(RegisterSysStatus <> 1)
		AND (
			status = 2669
			OR status = 2667
		)
	GROUP BY
		dbmask,
		IDEntityRelatedTo
		*/
),
contacts AS (
	
	SELECT
		mv.dbmask,
		c.organizationid,
		STRING_AGG(
			CAST(
				LTRIM(RTRIM(c.ShortName)) + CASE WHEN c.Email IS NOT NULL
				AND c.Mobile IS NOT NULL
				AND c.Email <> ''
				AND c.Mobile <> '' THEN ' (' + c.Email + ', ' + c.Mobile + ')' WHEN c.Email IS NOT NULL
				AND c.Email <> '' THEN ' (' + c.Email + ')' WHEN c.Mobile IS NOT NULL
				AND c.Mobile <> '' THEN ' (' + c.Mobile + ')' ELSE '' END AS nvarchar(MAX)
			),
			';' + CHAR(13) + CHAR(10)
		) AS contactos
	FROM
		dbo.SysDB AS mv
		LEFT OUTER JOIN contacts_cte AS c ON c.dbmask & mv.dbmask <> 0
	WHERE
		(
			c.IDModule = 'CB58FE26-69E2-4D6A-9837-A3AE6AE901A4'
		)
	GROUP BY
		mv.dbmask,
		c.organizationid
),
GetAssetsRec AS (
	
