AssetsExpanded AS (
	
	SELECT
		DISTINCT a.IDAsset,
		a.IDModule,
		rec.organizationid,
		rec.IDParent,
		rec.IDParentModule,
		a.assetName,
		a.dbmask,
		a.status,
		CASE WHEN a2a.IDRecAsset IS NULL THEN 0 ELSE 1 END AS HasChildren
	FROM
		dbo.Asset AS a
		INNER JOIN GetAssetsRec AS rec ON a.IDAsset = rec.IDAsset
		AND a.IDModule = rec.IDModule
		LEFT OUTER JOIN dbo.Asset2Asset AS a2a ON a2a.IDRecAsset = a.IDAsset
		AND a2a.IDRecAssetModule = a.IDModule
		CROSS APPLY (
        SELECT dbmask
        FROM dbo.SysDB 
        WHERE a.dbmask & SysDB.dbmask > 0  -- Bitwise AND: if ANY shared bit exists
    ) sd
	WHERE
		(a.RegisterSysStatus = 0)
),
LicensesAgg AS (
	
	SELECT
		dbmask,
		organizationid,
		COUNT(*) AS num_licenses,
		STRING_AGG(
			CAST(assetName AS nvarchar(MAX)),
			';' + CHAR(13) + CHAR(10)
		) AS licenses
	FROM
		AssetsExpanded AS AssetsExpanded_1
	WHERE
		(status = '2787')
		OR (status = '2801')
	GROUP BY
		dbmask,
		organizationid
)
SELECT
	e.organizationid,
	e.organization_no,
	e.ShortName,
	e.billingzip,
	e.billingstate,
	e.billingstreet,
	e.phone,
	e.email,
	e.accountname,
	a.account_no,
	a.dbmask,
	ISNULL(ct.service_contracts_progress, 0) AS service_contracts_progress,
	ISNULL(ct.service_contracts_terminated, 0) AS service_contracts_terminated,
	ct.service_contracts,
	co.contactos,
	ISNULL(lc.num_licenses, 0) AS num_licenses_in_service,
	lc.licenses
FROM
	dbo.Entity AS e
	INNER JOIN dbo.Account AS a ON a.IDContact = e.organizationid
	AND a.RegisterSysStatus <> 1
	INNER JOIN dbo.GetModulesRec('E93A6D50-31BA-4C2D-829A-35F63F505FD9') AS gm ON gm.IDModule = a.IDModule
	LEFT OUTER JOIN contracts AS ct ON ct.organizationid = e.organizationid
	AND ct.dbmask & a.dbmask <> 0
	LEFT OUTER JOIN contacts AS co ON co.organizationid = e.organizationid
	AND co.dbmask & a.dbmask <> 0
	LEFT OUTER JOIN LicensesAgg AS lc ON lc.organizationid = e.organizationid
	AND lc.dbmask & a.dbmask <> 0
WHERE
	(e.RegisterSysStatus <> 1)
GO


-- ----------------------------
-- View structure for vw_ServiceContractsDaysLastActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[vw_ServiceContractsDaysLastActivity]') AND type IN ('V'))
	DROP VIEW [dbo].[vw_ServiceContractsDaysLastActivity]
GO

CREATE VIEW [dbo].[vw_ServiceContractsDaysLastActivity] AS WITH BusinessAreaCTE AS (SELECT        IDBusinessArea, IDParent, 0 AS Nivel
                                                              FROM            dbo.BusinessArea
                                                              WHERE        (IDBusinessArea = 2)
                                                              UNION ALL
                                                              SELECT        ba.IDBusinessArea, ba.IDParent, cte.Nivel + 1 AS Expr1
                                                              FROM            dbo.BusinessArea AS ba INNER JOIN
                                                                                       BusinessAreaCTE AS cte ON ba.IDParent = cte.IDBusinessArea
                                                              WHERE        (cte.Nivel < 2))
    SELECT        sc.IDServiceContract, sc.IDModule AS IDServiceContractModule, sc.contractNo AS Contrato, e.organization_no AS Codigo, e.accountname AS Empresa, e.email, e.email2, e.organizationid, e.IDModule, MIN(DATEDIFF(DAY, 
                              a.endDate, GETDATE())) AS DiasUltimaAtividade
     FROM            dbo.ServiceContract AS sc INNER JOIN
                              dbo.Entity AS e ON e.organizationid = sc.IDEntityRelatedTo LEFT OUTER JOIN
                              dbo.Activity2Record AS a2r ON a2r.relatedRecord = sc.IDServiceContract AND a2r.relatedRecordModule = sc.IDModule LEFT OUTER JOIN
                              dbo.Activity AS a ON a.IDActivity = a2r.IDActivity LEFT OUTER JOIN
                              dbo.SysActivityResourceRoleActivity AS arra ON arra.TeamMask01 IN (512, 1024, 32768) AND arra.IDActivity = a.IDActivity
     WHERE        (sc.dbmask IN (1, 32)) AND (sc.IDBusinessArea IN
                                  (SELECT        IDBusinessArea
                                    FROM            BusinessAreaCTE AS BusinessAreaCTE_1)) AND (sc.status = 2667)
     GROUP BY sc.IDServiceContract, sc.IDModule, sc.contractNo, e.organization_no, e.accountname, e.email, e.email2, e.organizationid, e.IDModule
GO


-- ----------------------------
-- function structure for ReadPocValuesFinanceEntity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ReadPocValuesFinanceEntity]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ReadPocValuesFinanceEntity]
GO

CREATE FUNCTION [dbo].[ReadPocValuesFinanceEntity] 
(	
	@IDContact int,
	@IDContactModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	select acc.IDContact, acc.IDContactModule, acc.dbmask, acc.Name ,
	movs.DateRecord, movs.Depth, movs.IDParent, movs.IDPocValue, movs.IDRecord,
	movs.IDRecordModule, movs.IDSrc, movs.IDSrcCode, movs.IDSrcModule, movs.MovementMode,
	movs.MovementRootType, movs.LineDocSrc, movs.LineDocSrcModule, movs.ValueDocActBalance, 
	movs.ValueDocPlanBalance, case when MovementMode = 0 then ValueFinAct else 0 end as ValueFinAct,
	case when MovementMode in(1,4) then ValueFinAct else 0 end as ValueFinPlan,
	movs.HasChildren
	from Account acc
	cross apply ReadPocValuesTF_Acc(acc.IDModule, acc.IDAccount) movs
	where acc.IDModule in(
		select IDModule from GetModulesRec('0E421489-9AF0-4AAA-96AF-308BD06DDD2A')
	)
	and movs.MovementRootType = 0
	and MovementMode <> 3
	and acc.IDContact = @IDContact and acc.IDContactModule = @IDContactModule
);
GO


-- ----------------------------
-- procedure structure for Query_CustomersByIndustry
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_CustomersByIndustry]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_CustomersByIndustry]
GO

CREATE PROCEDURE [dbo].[Query_CustomersByIndustry]
	@dbmask int
AS
BEGIN
	
	SET NOCOUNT ON;

	--declare  @tmpTable table (
	--	id int 
	--)

	--insert into @tmpTable(id)
	--select organizationid
	--from Entity e 
	--where 
	--	e.industry  in (
	--	select productid
	--	from products
	--	where productname in (
	--	'IND Arte',
	--	'IND Escola Design',
	--	'IND Hobby',
	--	'IND Joalharia',
	--	'IND Escultura',
	--	'IND Medicina',
	--	'IND Desenv Produto',
	--	'IND Design',
	--	'IND Moda',
	--	'IND Ensino',
	--	'IND Education',
	--	'IND Dental'
	--	)
	--)

	with cte as (
	select organizationid, 0 as [level] from entity where industry in (
			select productid
			from products
			where productname in (
			--'IND Arte',
			--'IND Escola Design',
			-- 'IND Cerâmica'
			--'IND Hobby',
			'IND Joalharia'
			--'IND Escultura',
			--'IND Medicina',
			--'IND Desenv Produto',
			--'IND Design',
			--'IND Moda',
			--'IND Ensino',
			--'IND University',
			--'IND Education' -- ,
			--'IND Dental'
			)
		)

		union all

		select	e.organizationid, cte.[level] + 1
		from	cte 
				inner join Entity2Entity	e2e on cte.organizationid = e2e.IDRecEntity 
				inner join entity			e	on e2e.IDRecEntityChild = e.organizationid
		where
			cte.[level] < 100

		
	)

    select 
		e.organizationid as id,
		e.organization_no as code,
		e.accountname as name,
		
		case 
			when idmodule = '28BEE890-28FA-45E2-8D51-8D30F36C4F04' then 
				coalesce((
				select top 1 comp.accountname 
				from	entity comp 
						inner join Entity2Entity e2e on comp.organizationid = e2e.IDRecEntity and e.organizationid = e2e.IDRecEntityChild and comp.IDModule = '053A9991-2090-4855-AC8D-34C2F5300DD6'
						and comp.registersysstatus = 0

				 ) , '')
			else 
				''
		end as Company,

		coalesce(e.email, '') as email,
		coalesce(e.email2, '') as email2,

		coalesce(replace(replace(e.billingcity, char(13), ' '), char(10), ' '), '') as billingcity,
		coalesce(replace(replace(e.billingcountry, char(13), ' '), char(10), ' '), '') as billingcountry,
		coalesce(replace(replace(e.billingpobox, char(13), ' '), char(10), ' '), '') as billingpobox,
		coalesce(replace(replace(e.billingstate, char(13), ' '), char(10), ' '), '') as billingstate,
		coalesce(replace(replace(e.billingstreet, char(13), ' '), char(10), ' '), '') as billingstreet,
		coalesce(replace(replace(e.billingzip, char(13), ' '), char(10), ' '), '') as billingzip,
		coalesce(replace(replace(e.billingGps, char(13), ' '), char(10), ' '), '') as billingGps,

		coalesce(replace(replace(e.mailingcity, char(13), ' '), char(10), ' '), '') as mailingcity,
		coalesce(replace(replace(e.mailingcountry, char(13), ' '), char(10), ' '), '') as mailingcountry,
		coalesce(replace(replace(e.mailingpobox, char(13), ' '), char(10), ' '), '') as mailingpobox,
		coalesce(replace(replace(e.mailingstate, char(13), ' '), char(10), ' '), '') as mailingstate,
		coalesce(replace(replace(e.mailingstreet, char(13), ' '), char(10), ' '), '') as mailingstreet,
		coalesce(replace(replace(e.mailingzip, char(13), ' '), char(10), ' '), '') as mailingzip,
		coalesce(replace(replace(e.mailingGps, char(13), ' '), char(10), ' '), '') as mailingGps

	from 
		Entity e 
	where 
		--(
		--e.organizationid in (select id from @tmpTable)
		--or
		--e.organizationid in (select IDRecEntityChild from Entity2Entity e2e where e2e.IDRecEntity in (select id from @tmpTable))
		--)

		(e.organizationid in (select organizationid from cte where [level] < 99))
		and
		(e.dbmask & @dbmask) != 0 and e.RegisterSysStatus = 0 and coalesce(e.emailoptout, 0) = 0
	order by idmodule
	OPTION (MAXRECURSION 100)

END
GO


-- ----------------------------
-- procedure structure for CalculateDeadLineAsset
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CalculateDeadLineAsset]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CalculateDeadLineAsset]
GO

CREATE PROCEDURE [dbo].[CalculateDeadLineAsset]
	@IDAsset int
AS
BEGIN
	
	update FollowUpItemMouldFields set IDAsset = @IDAsset, IDAssetModule = t.IDAM
	from(
		select fup.IDFollowUpItem IDF, a.IDModule IDAM
		from Asset a
		inner join FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem
		where a.IDAsset = @IDAsset
	) t
	where IDFollowUpItem = t.IDF;


	update SS_AssetPartValues set CalculatedDeadline = CalcDead
	from(
		select ac.IDAsset as IDA, CASE 
			when apvc.DeadlineType = 0 then null 
			when apvc.DeadlineType = 1 and apvc.offsethours is not null and apvp.IDAsset is not null and apvp.Deadline is not null  then DATEADD(DAY, -1 * apvc.offsethours, apvp.Deadline)
			else null 
		end CalcDead
		from Asset ac
		inner join SS_AssetPartValues apvc on ac.IDAsset = apvc.IDAsset and ac.IDModule = apvc.IDModule
		left join Asset2Asset a2a on a2a.IDRecAssetChild = ac.IDAsset
		left join SS_AssetPartValues apvp on apvp.IDAsset = a2a.IDRecAsset and apvp.IDModule = a2a.IDRecAssetModule
		where ac.IDAsset = @IDAsset	
	) t
	where IDAsset = t.IDA;

	update SS_AssetPartValues set CalculatedDeadline = CalcDead
	from(
		select apvc.IDAsset as IDA, CASE 
			when apvc.DeadlineType = 0 then null 
			when apvc.DeadlineType = 1 and apvc.offsethours is not null and apvc.IDAsset is not null and apvp.Deadline is not null  then DATEADD(DAY, -1 * apvc.offsethours, apvp.Deadline)
			else null 
		end CalcDead 
		from Asset ap
		inner join SS_AssetPartValues apvp on ap.IDAsset = apvp.IDAsset and ap.IDModule = apvp.IDModule
		left join Asset2Asset a2a on a2a.IDRecAsset = ap.IDAsset
		left join SS_AssetPartValues apvc on apvc.IDAsset = a2a.IDRecAssetChild and apvc.IDModule = a2a.IDRecAssetChildModule
		where ap.IDAsset = @IDAsset
	) t
	where IDAsset = t.IDA;
	
	update SysDocOprRoutineItem set CalculatedDeadline = CalcDead
	from(
		select opr.IDRoutineItem as IDR, CASE 
			when opr.DeadlineType = 0 then null 
			when opr.DeadlineType = 1 and opr.offsethours is not null and opr.IDRoutineItem is not null and apvp.Deadline is not null  then DATEADD(DAY, -1 * opr.offsethours, apvp.Deadline)
			else null 
		end CalcDead 
		from Asset ap
		inner join SS_AssetPartValues apvp on ap.IDAsset = apvp.IDAsset and ap.IDModule = apvp.IDModule
		inner join FollowUpItem fup on fup.IDFollowUpItem = ap.IDFollowUpItem and fup.IDModule = ap.IDFollowUpItemModule
		INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
		left join SysDocOprRoutineItem opr on opr.IDRoutine = fupf.IDSysDocOprRoutine 
		where ap.IDAsset = @IDAsset and ap.IDModule in
		(
			select IDModule from GetModulesRec('a66cf09c-87e6-4d43-99b1-3e06a513c7bc')
		)
	) t
	where idroutineitem = t.IDR;

	update SysOprRoutineItem set CalculatedDeadline = CalcDead
	from(
		select opr.IDRoutineItem as IDR, CASE 
			when opr.DeadlineType = 0 then null 
			when opr.DeadlineType = 1 and opr.offsethours is not null and opr.IDRoutineItem is not null and apvp.Deadline is not null  then DATEADD(DAY, -1 * opr.offsethours, apvp.Deadline)
			else null 
		end CalcDead 
		from Asset ap
		inner join SS_AssetPartValues apvp on ap.IDAsset = apvp.IDAsset and ap.IDModule = apvp.IDModule
		inner join FollowUpItem fup on fup.IDFollowUpItem = ap.IDFollowUpItem and fup.IDModule = ap.IDFollowUpItemModule
		INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
		left join SysOprRoutineItem opr on opr.IDRoutine = fupf.IDSysDocOprRoutine 
		where ap.IDAsset = @IDAsset and ap.IDModule in
		(
			select IDModule from GetModulesRec('a66cf09c-87e6-4d43-99b1-3e06a513c7bc')
		)
	) t
	where idroutineitem = t.IDr;

	update SysDocOprRoutine set Deadline = t.Dead
	from(
		select fupf.IDSysDocOprRoutine as IDR, apvp.Deadline Dead
		from Asset ap
		inner join SS_AssetPartValues apvp on ap.IDAsset = apvp.IDAsset and ap.IDModule = apvp.IDModule
		inner join FollowUpItem fup on fup.IDFollowUpItem = ap.IDFollowUpItem and fup.IDModule = ap.IDFollowUpItemModule
		INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
		where ap.IDAsset = @IDAsset and ap.IDModule in
		(
			select IDModule from GetModulesRec('a66cf09c-87e6-4d43-99b1-3e06a513c7bc')
		)
	) t
	where IDRoutine = t.IDR;

	update SysOprRoutine set Deadline = t.Dead
	from(
		select fupf.IDSysOprRoutine as IDR, apvp.Deadline Dead
		from Asset ap
		inner join SS_AssetPartValues apvp on ap.IDAsset = apvp.IDAsset and ap.IDModule = apvp.IDModule
		inner join FollowUpItem fup on fup.IDFollowUpItem = ap.IDFollowUpItem and fup.IDModule = ap.IDFollowUpItemModule
		INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
		where ap.IDAsset = @IDAsset and ap.IDModule in
		(
			select IDModule from GetModulesRec('a66cf09c-87e6-4d43-99b1-3e06a513c7bc')
		)
	) t
	where IDRoutine = t.IDR;

END
GO


-- ----------------------------
-- function structure for GetActivityTime
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetActivityTime]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetActivityTime]
GO

CREATE FUNCTION [dbo].[GetActivityTime]
(
	-- Add the parameters for the function here
	@ID integer
)
RETURNS integer
AS
BEGIN
	-- Declare the return variable here
	DECLARE @result integer = 0
	DECLARE @result1 integer = 0

	-- Add the T-SQL statements to compute the return value here
	DECLARE @IDActivity INT

	DECLARE CurName CURSOR FAST_FORWARD READ_ONLY
	FOR
		SELECT  IDActivity
		FROM    Activity WHERE IDParentActivity = @ID

	OPEN CurName

	FETCH NEXT FROM CurName INTO @IDActivity

	WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @result1 =  dbo.GetActivityTime(@IDActivity);
			SET @result = @result + @result1
			FETCH NEXT FROM CurName INTO @IDActivity
		END

	CLOSE CurName
	DEALLOCATE CurName

	if(@result = 0)
	BEGIN
		SET @result = (SELECT DATEDIFF(MINUTE,StartDate, EndDate) FROM Activity WHERE IDActivity = @ID)
	END
	-- Return the result of the function
	RETURN @result

END
GO


-- ----------------------------
-- procedure structure for CopyPermissionsFomModuleParent
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CopyPermissionsFomModuleParent]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CopyPermissionsFomModuleParent]
GO

CREATE PROCEDURE [dbo].[CopyPermissionsFomModuleParent]
	@IDModule int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @IDParent int = 0;
    -- Insert statements for procedure here
	SET @IDParent=( SELECT IDParent FROM SysModule WHERE IDModule=@IDModule)
	if(@IDParent>0)
	begin
		--Copy Role 
		DECLARE CursorRole2Module CURSOR FOR   SELECT IDRole2Module,IDRole,PermissionMenu,PermissionRead,PermissionDelete,PermissionWrite FROM SysRole2Module WHERE IDModule=@IDParent
		OPEN CursorRole2Module
		DECLARE @IDRole2Module int =0,
				@IDRole int=0,
				@PermissionRead bit,
				@PermissionMenu bit,
				@PermissionDelete bit,
				@PermissionWrite bit,
				@IDRole2ModuleNew int =0;
			FETCH NEXT FROM CursorRole2Module INTO @IDRole2Module,@IDRole,@PermissionMenu,@PermissionRead,@PermissionDelete,@PermissionWrite
			WHILE @@FETCH_STATUS = 0
			BEGIN
				
				INSERT INTO SysRole2Module(IDModule,IDRole,PermissionMenu,PermissionRead,PermissionDelete,PermissionWrite) VALUES (@IDModule,@IDRole,@PermissionMenu,@PermissionRead,@PermissionDelete,@PermissionWrite)
				SET @IDRole2ModuleNew = (SELECT SCOPE_IDENTITY())

					-- Copy Role2Module2Field --
					DECLARE CursorRole2Module2Field CURSOR FOR SELECT IDField,PermissionLevel FROM SysRole2Module2Field WHERE IDRole2Module=@IDRole2Module
					OPEN CursorRole2Module2Field
					DECLARE @IDFieldParent int = 0,
							@PermissionLevel int=0;

						FETCH NEXT FROM CursorRole2Module2Field INTO @IDFieldParent,@PermissionLevel
						WHILE @@FETCH_STATUS = 0
						BEGIN
							DECLARE @IDField int =0;

							SET @IDField=( SELECT IDField FROM SysField WHERE IDModule=@IDModule AND InheritanceField=@IDFieldParent)
							if(@IDField>0)
							begin
								INSERT INTO SysRole2Module2Field(IDField,IDRole2Module,PermissionLevel) VALUES (@IDField,@IDRole2ModuleNew,@PermissionLevel)
							end
							FETCH NEXT FROM CursorRole2Module2Field INTO @IDFieldParent,@PermissionLevel
						END
					CLOSE CursorRole2Module2Field
					DEALLOCATE CursorRole2Module2Field
					-- End Role2Module2Field --

				FETCH NEXT FROM CursorRole2Module INTO @IDRole2Module,@IDRole,@PermissionMenu,@PermissionRead,@PermissionDelete,@PermissionWrite
			END
		CLOSE CursorRole2Module
		DEALLOCATE CursorRole2Module
	end
END
GO


-- ----------------------------
-- procedure structure for Query_NewContacts
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_NewContacts]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_NewContacts]
GO

CREATE PROCEDURE [dbo].[Query_NewContacts]
	@dtstart datetime = null,
	@dtend datetime = null,
	@dbmask int = 3,
  @ignoreConsent int = 0
AS
BEGIN

	SET NOCOUNT ON;

	SELECT *
	FROM
	(
		SELECT  
		e.organization_no as code, 'CONTACT' as type, e.firstname, e.lastname, e.accountname, null as industry, c.accountname as company, 
		coalesce(
			case when rtrim(e2e.Email) = '' then null else e2e.Email end, 
			case when rtrim(e.email) = '' then null else e.email end
		) email, e.email2, '' as BAName,
      case WHEN ( (isnull(e.ConsentToCommunicate, 0) = 1 and ISNULL(e.emailoptout, 0) = 0 ) ) THEN 'sim' ELSE 'nao' END AS Consent
		FROM Entity e
		OUTER APPLY 
		(
			SELECT e2ec.*, e2ec.IDRecEntity as ActualIDRecEntity, e2ec.IDRecEntityModule as ActualIDRecEntityModule
			FROM [dbo].[Entity2Entity] e2ec 
			WHERE e2ec.IDRecEntityChild = e.organizationid and e2ec.IDRecEntityChildModule = e.IDModule and e2ec.Active = 1 and (e2ec.dbmask & @dbmask) != 0

			union all

			SELECT e2ec.*, e2ec.IDRecEntityChild as ActualIDRecEntity, e2ec.IDRecEntityChildModule as ActualIDRecEntityModule
			FROM [dbo].[Entity2Entity] e2ec 
			WHERE e2ec.IDRecEntity= e.organizationid and e2ec.IDRecEntityModule = e.IDModule and e2ec.Active = 1 and (e2ec.dbmask & @dbmask) != 0
			and e2ec.IDRecEntity not in(
				SELECT distinct e2ec.IDRecEntityChild 
				FROM [dbo].[Entity2Entity] e2ec 
				WHERE e2ec.IDRecEntityChild = e.organizationid and e2ec.IDRecEntityChildModule = e.IDModule  and e2ec.Active = 1
			)
		) AS e2e
		inner join Entity c on c.organizationid =  e2e.ActualIDRecEntity and c.IDModule = '053A9991-2090-4855-AC8D-34C2F5300DD6' 
		WHERE e.IDModule = '28bee890-28fa-45e2-8d51-8d30f36c4f04' and e.RegisterSysStatus = 0 and (e.dbmask & @dbmask) != 0 
		and 
     (@ignoreConsent = 1 OR (isnull(e.ConsentToCommunicate, 0) = 1 and ISNULL(e.emailoptout, 0) = 0 ))
		and 
		(
			(e.ModifiedTime >= @dtstart AND e.ModifiedTime <= @dtend) or 
			(e.CreatedTime >= @dtstart AND e.CreatedTime <= @dtend) OR
			(e2e.ModifiedTime >= @dtstart AND e2e.ModifiedTime <= @dtend) or 
			(e2e.CreatedTime >= @dtstart AND e2e.CreatedTime <= @dtend)
		) 
		and e.organization_no != ''
	) t

	union all

	select e.organization_no as code, 'COMPANY' as [type], 
	e.firstname, e.lastname, e.accountname as [fullname], i.productname as industry, null as company, e.email, e.email2, '' as BAName,
      case WHEN ( ISNULL(e.emailoptout, 0) = 0 ) THEN 'sim' ELSE 'nao' END AS Consent
	from 
	Entity e 
	left join products i on e.Industry = i.productid
	inner join  Account acc on acc.IDModule in
	(
		select IDModule from GetModulesRec('AADBC233-B9C6-43F9-A18F-F050984556AF')
	) and acc.RegisterStatus = 0 and isnull(acc.Status,0) = 0 and acc.IDContact = e.organizationid and acc.IDContactModule = e.IDModule and acc.dbmask & @dbmask != 0
	where (e.dbmask & @dbmask) != 0 and 
    (@ignoreConsent = 1 OR ISNULL(e.emailoptout, 0) = 0 )
	and 
		((e.ModifiedTime >= @dtstart AND e.ModifiedTime <= @dtend) or 
		(e.CreatedTime >= @dtstart AND e.CreatedTime <= @dtend)) 
		and e.organization_no != ''
	and e.IDModule = '053A9991-2090-4855-AC8D-34C2F5300DD6'	
	group by e.organization_no, e.firstname, e.lastname, e.accountname, i.productname, e.email, e.email2, case WHEN ( ISNULL(e.emailoptout, 0) = 0 ) THEN 'sim' ELSE 'nao' END
	having count(distinct acc.IDAccount) > 0

	union all

	select l.lead_no, 'LEAD', l.firstname, l.lastname, '', ind.[Name] as industry, company, email, email2, b_tv.[Name] as BAName,
      case WHEN ( isnull(l.ConsentToCommunicate, 0) = 1 and ISNULL(l.DoNotEmail, 0) = 0 ) THEN 'sim' ELSE 'nao' END AS Consent
	from Leads l 
	left join Industry ind on l.IDIndustry = ind.IDIndustry
	left join BusinessArea b on l.IDBusinessArea = b.IDBusinessArea
	left join SysTranslationValue b_tv on b_tv.IDTranslation = b.BAName and b_tv.IDLanguage = 1
	where (l.dbmask & @dbmask) != 0 
  and 
  (@ignoreConsent = 1
    OR ( isnull(l.ConsentToCommunicate, 0) = 1 and ISNULL(l.DoNotEmail, 0) = 0 ))
	and 
	((l.ModifiedTime >= @dtstart AND l.ModifiedTime <= @dtend) or 
	(l.CreatedTime >= @dtstart AND l.CreatedTime <= @dtend))

END
GO


