-- ----------------------------
-- procedure structure for LeadsSolidWorks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LeadsSolidWorks]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[LeadsSolidWorks]
GO

CREATE PROCEDURE [dbo].[LeadsSolidWorks]
	@idCampaign int = null,
	@dtCreateStart datetime = null,
	@dtCreateEnd datetime = null
AS
BEGIN
	SET NOCOUNT ON;

	if not @idCampaign is null
	begin

		select CreatedTime, lead_no, leadDate, partnerId, fvi.Code as [status], fvi2.Code as leadFollowUp, resumoPartner, company
		from 
			Leads l 
			left join SysFieldValueItem fvi on l.[status] = fvi.CodeInt and fvi.GroupCode = 'LeadStatus'
			left join SysFieldValueItem fvi2 on l.leadFollowUp = fvi2.CodeInt and fvi2.GroupCode = 'Leads LeadFollowUp'
		where 
			 IDLead in (select IDLead from Campaign2Lead where IDCampaign = @idCampaign) and l.RegisterSysStatus = 0
	
	end
	else
	begin

	
		select CreatedTime, lead_no, isnull(leadDate, ''), isnull(partnerId, ''), fvi.Code as [status], isnull(fvi2.Code, '') as leadFollowUp, isnull(replace(replace(resumoPartner, '\n', ''), '\r', ''), ''), isnull(company, '')
		from 
			Leads l 
			left join SysFieldValueItem fvi on l.[status] = fvi.CodeInt and fvi.GroupCode = 'LeadStatus'
			left join SysFieldValueItem fvi2 on l.leadFollowUp = fvi2.CodeInt and fvi2.GroupCode = 'Leads LeadFollowUp'
		where 
			 CreatedTime >= @dtCreateStart AND CreatedTime <= @dtCreateEnd and isnull(partnerId, '') != '' and l.RegisterSysStatus = 0
	
	end
END
GO


-- ----------------------------
-- procedure structure for SaveChatMessage
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SaveChatMessage]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SaveChatMessage]
GO

CREATE PROCEDURE [dbo].[SaveChatMessage]
	@IDSender uniqueidentifier,
	@IDSenderResource uniqueidentifier,

	@IDWorkRoom uniqueidentifier,
	@RawMessage nvarchar(2000),
	@IDActivityConversation int,
	@Status int,

	@Importance int,
	@IsPublic int,
	@ChatQuestionMessage int,
	@Kind int,
  	
	@IDTask uniqueidentifier,
	@IDActivity int,
	@TaskRunningStatus int,
	@TaskStatus int,
	@TaskStatusStr nvarchar(50),
	@TaskTitle nvarchar(50),
	@TaskKind int,
	@TaskShortName nvarchar(120),
	@TaskArchived int,
	@InviteResourceAccessType int,
	@InviteIsOwner int,
	@ProgressPercentage decimal(18,2),
	@IDChatExtVars uniqueidentifier,

	@IDTaskVote uniqueidentifier,
	@OpChosenText nvarchar(1000),
	@ExtraData nvarchar(max),
	@InviteTasksPermissions int,
	@InviteActivitiesPermissions int,
	@IDVideoCall uniqueidentifier,
	@IDMail uniqueidentifier,
	@QuestionType int,
	@QuestionStatus int,
	@QuestionID int,
	@QuestionAuthor uniqueidentifier,
	@IDThirdParty int,
	@IDRecord bigint,
	@IDRecordModule uniqueidentifier,
	@InviteLinkKind int,
	@GIDRecord uniqueidentifier,
	@RecordCode nvarchar(50),
	@RecordShortName nvarchar(120),
	@DataLinkType int,
	@InviteAllowPublish int,
	@InviteMonitorFeatureFlags int,
	@InviteSpokesperson int,
	@ExternalChannels varchar(max),
	@InviteShowCurrentWork int,
	@InviteShowCurrentAttendance int,
	@AttentionCall int,
	@Stamp datetime = NULL
AS
BEGIN
	
	SET NOCOUNT ON;

DECLARE @ids TABLE (
    idChat2 INT
)

declare @QuestionStatusLastChange datetime
set @QuestionStatusLastChange = null

if @QuestionStatus > 0
begin
	set @QuestionStatusLastChange = GETUTCDATE()
end

declare @HasExternalChannels int
set @HasExternalChannels=0
If IsNull(@ExternalChannels, '') != ''
begin
	set @HasExternalChannels=1
end

INSERT INTO SysChat(IDSender, IDSenderResource, 
                    RawMessage, IDActivityConversation, Stamp, Status,
                    Importance, IsPublic, ChatQuestionMessage, Kind, IDTask, IDActivity, TaskStatus, TaskTitle, TaskKind,
					TaskStatusStr, TaskRunningStatus, IDWorkRoom, TaskShortName, TaskArchived, OpChosenText,
                    InviteIsOwner, InviteResourceAccessType, ProgressPercentage, IDChatExtVars, IDTaskVote, 
					InviteTasksPermissions, InviteActivitiesPermissions, ExtraData, IDVideoCall, IDMail,
					QuestionType, QuestionStatus, QuestionID, QuestionAuthor, QuestionStatusLastChange,IDThirdParty, 
					IDRecord, IDRecordModule,InviteLinkKind,
					GIDRecord,RecordCode,RecordShortName,DataLinkType,InviteAllowPublish,InviteMonitorFeatureFlags,
					InviteSpokesperson,ExternalChannels,InviteShowCurrentWork,InviteShowCurrentAttendance,AttentionCall)
OUTPUT inserted.idChat2 INTO @ids VALUES 
                    (@IDSender, @IDSenderResource, 
                    @RawMessage, @IDActivityConversation, 
					CASE 
						WHEN @Stamp IS NULL OR @Stamp < '1753-01-01' THEN GETUTCDATE() 
						ELSE @Stamp 
					END,
					@Status, @Importance, @IsPublic, @ChatQuestionMessage, @Kind, @IDTask, @IDActivity, @TaskStatus, @TaskTitle, @TaskKind,
					@TaskStatusStr, @TaskRunningStatus, @IDWorkRoom, @TaskShortName, @TaskArchived, @OpChosenText,
                    @InviteIsOwner, @InviteResourceAccessType, @ProgressPercentage, @IDChatExtVars, @IDTaskVote, 				        
                    @InviteTasksPermissions, @InviteActivitiesPermissions, @ExtraData, @IDVideoCall, @IDMail,
					@QuestionType, @QuestionStatus, @QuestionID, @QuestionAuthor, @QuestionStatusLastChange,@IDThirdParty, 
					@IDRecord, @IDRecordModule, @InviteLinkKind,
					@GIDRecord,@RecordCode,@RecordShortName,@DataLinkType,@InviteAllowPublish,@InviteMonitorFeatureFlags,
					@InviteSpokesperson,@HasExternalChannels,@InviteShowCurrentWork,@InviteShowCurrentAttendance,@AttentionCall);


INSERT INTO SysChat2SysWorkRoom(IDChat2, IDWorkRoom, Kind)
SELECT idchat2, @idworkroom, 0
FROM @ids

If IsNull(@ExternalChannels, '') != ''
begin
INSERT INTO SysChat2SysWorkRoom(IDChat2, IDWorkRoom, Kind)
	SELECT idchat2, CONVERT(uniqueidentifier,Data) ,1
	FROM [dbo].[Split](@ExternalChannels, ','),
	@ids
	WHERE CONVERT(uniqueidentifier,Data)!=@idworkroom
end

SELECT IDChat2 FROM @ids
END
GO


