-- procedure structure for SS_InsertJobPP
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertJobPP]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertJobPP]
GO

CREATE PROCEDURE [dbo].[SS_InsertJobPP]
	-- Add the parameters for the stored procedure here
	@Kind int,
	@Name nvarchar(50),
	@InUse bit,
	@Overwrite bit,
	@IDJobPPTemplate uniqueidentifier,
	@LoginID uniqueidentifier,
	@JobPPID uniqueidentifier out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	declare @LocalPath nvarchar(200);
	set @LocalPath= (Select [SetupPathDefault] from ss_config);
	SET NOCOUNT ON;
	set @JobPPID=(select top 1 idjobPP from sysJobPP where name like @Name)
	if @JobPPID is null
	BEGIN
		set @JobPPID= newid();
		insert into sysJobPP(
		idjobPP,Kind,Name, 
		InUse, LocalPath,IDJobPPTemplate,
		DateCreated,DateModified,
		IDLoginCreated,IDLoginModified,IDMachine,State) 
		values (@JobPPID,@Kind, @Name,
		@InUse, @LocalPath,@IDJobPPTemplate,
		getdate(),getdate(),
		@LoginID,@LoginID,(select  idmachine from SysJobPPTemplate where idtemplate=@IDJobPPTemplate),0);
				
		update sysJobPP set LocalPath=@LocalPath+Name+'.smstp' where idjobpp=@JobPPID ;
	END
END
GO


-- ----------------------------
-- function structure for GetMailAddress
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetMailAddress]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetMailAddress]
GO

CREATE FUNCTION [dbo].[GetMailAddress]
(
	@IDLogin uniqueidentifier,
	@IDResource uniqueidentifier,
	@dbmask int
)
RETURNS varchar(100)
AS
BEGIN	
	DECLARE @r varchar(100)
	set @r = NULL

	-- 1 commercial/personal email
	
	declare @id int
		
	select @id = e.organizationid
	from SysLogin l inner join Entity e on l.IDLogin = e.IDRelatedLogin 
	where l.IDLogin = @r

	set @r = dbo.GetCommercialEmail(@id, @dbmask)

	if coalesce(@r, '') != ''
	begin
		goto _end
	end


	-- 2 login email
	select @r = MailAddress from SysLogin WHERE IDLogin = @IDLogin

	if coalesce(@r, '') != ''
	begin
		goto _end
	end

	-- 3 resource email


	select @r = MailAddress from SysResources WHERE ResourceId = @IDResource
	
	_end:
	return @r
END
GO


-- ----------------------------
-- procedure structure for AutoSelectBestContactMatch
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AutoSelectBestContactMatch]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[AutoSelectBestContactMatch]
GO

CREATE PROCEDURE [dbo].[AutoSelectBestContactMatch]	
	@NewIDRecord int ,
	@NewIDModule uniqueidentifier 
AS
BEGIN

	SET NOCOUNT ON;

	-- if this a lead?
	if exists(select idmodule from dbo.GetModulesRec('862156D4-A768-4464-A790-9A1C67452AE5') where idmodule = @NewIDModule)
	begin
		declare @email1 nvarchar(max), @email2 nvarchar(max)
		declare @dbmask int

		set @dbmask = 
			(select dbmask
			from Leads
			where idlead = @NewIDRecord and idmodule = @NewIDModule)
		set @email1 = 
			(select rtrim(coalesce(email, ''))
			from Leads
			where idlead = @NewIDRecord and idmodule = @NewIDModule)

		set @email2 = 
			(select rtrim(coalesce(email2, ''))
			from Leads
			where idlead = @NewIDRecord and idmodule = @NewIDModule)

		declare @idContact int
		declare @idContactModule uniqueidentifier

		set @idContact = null
		set @idContactModule = null

		select @idContact = organizationid, @idContactModule = IDModule
		from entity e 
		where 
			(dbmask & @dbmask) != 0
			and
			(
				(
					(@email1 != '' and email = @email1 )
					or
					(@email1 != '' and email2 = @email1 )
				)
				or
				(
					(@email2 != '' and email = @email2 )
					or
					(@email2 != '' and email2 = @email2 )
				)
			)

		if not @idContact is null and not @idContactModule is null
		begin

			update Leads
			set idContact = @idContact,
				idContactModule = @idContactModule,
				[status] = 1345,
				IsKnownAtImportTime = 1
			where IDLead = @NewIDRecord and IDModule = @NewIDModule

		end
	end

END
GO


-- ----------------------------
-- function structure for GetIDChat4AttachNewRecord
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetIDChat4AttachNewRecord]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetIDChat4AttachNewRecord]
GO

CREATE FUNCTION [dbo].[GetIDChat4AttachNewRecord](@IDChat2 INT) 
RETURNS INT 
AS 
BEGIN 
	DECLARE @Result INT;
	SELECT
		TOP 1 @Result = IDChat2
	FROM
		SysChat
	WHERE
		IDChat2 = @IDChat2
		AND kind NOT IN (
			13, -- play
			14, -- pause
			35, -- Test
			45, -- Redo
			2, -- TaskStatus
			3, -- TaskUpdate
			7, -- TaskTransfer
			8, -- InviteRequest
			9, -- InviteOffer
			23, -- TaskVote
			28, -- VideoCallStart
			29, -- VideoCallStop
			20, --InviteRejected
			21 --InviteCancelled
		) 

	IF @@ROWCOUNT = 0
	SET
		@Result = -1;

	RETURN @Result;

END
GO


