-- ----------------------------
-- procedure structure for FixMouldAssemblyFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FixMouldAssemblyFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[FixMouldAssemblyFields]
GO

CREATE PROCEDURE [dbo].[FixMouldAssemblyFields]
	@IDFollowUpItem bigint
AS
BEGIN
	
	UPDATE SM_AssemblyNodePart set IDRoutineItem = t.IDR
	from
	(
		select np.IDRoutineItem IDR, ap.ID as IDA
		from SM_AssemblyNodePosic np
		inner join SM_AssemblyNodePart ap on np.ID = ap.IDNodePosic
		where np.IDFollowUpItem = @IDFollowUpItem
	) t
	where ID = t.IDA;

	UPDATE SM_AssemblyNodePosic set IDNodePartParent = t.IDA
	from
	(
		select nc.ID IDP, ap.ID as IDA
		from SM_AssemblyNodePosic nc
		inner join SM_AssemblyNodePosic np on np.ID = nc.IDNodePosicParent
		inner join SM_AssemblyNodePart ap on ap.IDNodePosic = np.ID
		where np.IDFollowUpItem = @IDFollowUpItem 
	) t
	where ID = t.IDP;

END
GO


-- ----------------------------
-- function structure for SS_GetObjectIDByParams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetObjectIDByParams]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetObjectIDByParams]
GO

CREATE FUNCTION [dbo].[SS_GetObjectIDByParams]
(	
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@instanceNum int,
	@Family nvarchar(50),
	@FamilyID int,
	@SysMirrX bit,
	@SysMirrY bit,
	@ClientName nvarchar (50)='',
	@NoCopies bit=0
)
RETURNS @Res TABLE 
(
	id uniqueidentifier,
	isCopy bit
)
AS
BEGIN


	-- Declare the return variable here
	if (not @Family is null) and (@FamilyID is null)
	begin
		if @Family='D' or @Family='d'
			set @FamilyID=1
		if @Family='P' or @Family='p'
			set @FamilyID=2
		if @Family='A' or @Family='a'
			set @FamilyID=3
	end

	-- Add the T-SQL statements to compute the return value here
	if @PartOf is null
	begin
		insert into @res Select p.id,0
			from ss_object p
			inner join ss_mould m on m.id=p.mouldid
			left join SysAccount c on c.IDAccount=m.IDAccount
			where m.name=@MouldName and p.shortname=@ObjectName 
			and (@ClientName is null or @ClientName='' or @ClientName=c.name)
			AND p.ParentID IS  NULL;
			
	end
	else
	begin
		insert into @res Select o.id,0
			from ss_object o
			inner join ss_mould m on m.id=o.mouldid
			inner join ss_object p on p.id=o.parentid
			left join ss_eletrode e on e.id=o.id
			left join SysAccount c on c.IDAccount=m.IDAccount 
			where 
				m.name=@MouldName and 
				(@ClientName is null or @ClientName='' or @ClientName=c.name) and
				p.shortname=@PartOf and 
				o.shortname=@ObjectName and 
				((@Gap is null) or (e.gap=@Gap)) and
				((@FamilyID is null) or (e.EletrodeFamily=@FamilyID)) and
				((@instanceNum is null) or (e.instanceNum=@instanceNum)) 
	end

	if @NoCopies=0
	insert into @res Select o.id,1
			from ss_object o where 
			(copyfromid in ( select id from @res))
				and			((@SysMirrX is null) or (@SysMirrX=o.CopyMirrorX)) and
				((@SysMirrY is null) or (@SysMirrY=o.CopyMirrorY)) 
			 and  (id not in ( select id from @res));

return
END
GO


