-- procedure structure for UpdateActivityThirdParties
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateActivityThirdParties]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateActivityThirdParties]
GO

CREATE PROCEDURE [dbo].[UpdateActivityThirdParties]
	@IDActivity int
AS
BEGIN
	SET NOCOUNT ON;

	declare @thirdParties nvarchar(max) = (
		SELECT SUBSTRING(
		(
			SELECT ', '+ e.ShortName  AS [text()]
			from Activity2Record a2r 
			inner join Entity e on e.organizationid = a2r.relatedRecord and e.IDModule = '053A9991-2090-4855-AC8D-34C2F5300DD6'
			where IDActivity = @IDActivity 
			order by a2r.IDActivity2Record
			FOR XML PATH ('')
		), 2, 1000) [Entities]
	);
	
	update Activity set ThirdPartiesRelated = @thirdParties where IDActivity = @IDActivity;

END
GO


-- ----------------------------
-- function structure for AssetIsInDocs
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AssetIsInDocs]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[AssetIsInDocs]
GO

CREATE FUNCTION [dbo].[AssetIsInDocs](@IDAsset int, @RegisterStatus int , @IDModule uniqueidentifier, @IDModule2 uniqueidentifier, @NotIn int)
RETURNS int
AS
BEGIN
	if @NotIn = 0
	begin
		return 
		(
			select case when COUNT(*) > 0 then 1 else 0 end
			from DocumentLine dl 
			inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule and dl.PartitionColumn = d.PartitionColumn
			where dl.assetid = @IDAsset 
			and (d.RegisterStatus = @RegisterStatus or @RegisterStatus is null)
			and d.IDModule = @IDModule and d.IDModule <> '587EA54F-D1F3-4467-A56B-8AF1B8DAF476'
		)
	end

	if @NotIn = 1 
	begin
		return 
		(
			select case when COUNT(*) > 0 then 1 else 0 end
			from DocumentLine dl 
			inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule and dl.PartitionColumn = d.PartitionColumn
			where dl.assetid = @IDAsset
			and (d.RegisterStatus = @RegisterStatus or @RegisterStatus is null)
			and d.IDModule <> @IDModule and (@IDModule2 is null or d.IDModule <> @IDModule2) and d.IDModule <> '587EA54F-D1F3-4467-A56B-8AF1B8DAF476'
		)
	end

	return 0;
END
GO


-- ----------------------------
-- procedure structure for UpdateAccountBalances
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAccountBalances]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAccountBalances]
GO

CREATE PROCEDURE [dbo].[UpdateAccountBalances]
	@IDRecord int,
	@IDModule uniqueidentifier
AS
BEGIN
	SET NOCOUNT ON;

	update account
	set 
		TotalValueFinAct = t.NewTotalValueFinAct,
		TotalValueFinPlan = t.NewTotalValueFinPlan, 
		TotalValueDocAct = t.NewTotalValueDocAct, 
		TotalValueDocPlan = t.NewTotalValueDocPlan,
		TotalValueTransAct = t.NewTotalValueTransAct, 
		TotalValueTransPlan = t.NewTotalValueTransPlan, 
		TotalValueDebt = t.NewTotalValueDebt,
		TotalQtyFinAct = t.NewTotalQtyFinAct, 
		TotalQtyFinPlan = t.NewTotalQtyFinPlan, 
		TotalQtyDocAct = t.NewTotalQtyDocAct, 
		TotalQtyDocPlan = t.NewTotalQtyDocPlan, 
		TotalQtyTransAct = t.NewTotalQtyTransAct, 
		TotalQtyTransPlan = t.NewTotalQtyTransPlan,
		ModifiedTime = GETUTCDATE()
	from(
		select 
		[ValueFinActBalance] as NewTotalValueFinAct, 
		[ValueFinPlanBalance] as NewTotalValueFinPlan,
		[ValueDocActBalance] as NewTotalValueDocAct, 
		[ValueDocPlanBalance] as NewTotalValueDocPlan,
		[ValueTransActBalance] as NewTotalValueTransAct, 
		[ValueTransPlanBalance] as NewTotalValueTransPlan,		
		[TotalValueDebt] as NewTotalValueDebt,		
		[QtyFinActBalance] as NewTotalQtyFinAct, 
		[QtyFinPlanBalance] as NewTotalQtyFinPlan,
		[QtyDocActBalance] as NewTotalQtyDocAct, 
		[QtyDocPlanBalance] as NewTotalQtyDocPlan,
		[QtyTransActBalance] as NewTotalQtyTransAct, 
		[QtyTransPlanBalance] as NewTotalQtyTransPlan
 		from SysPocValue where MovementMode = 3 and MovementRootType = 0 and IDRecord = @IDRecord and IDRecordModule = @idModule
	) t
	where IDAccount = @IDRecord;

	update AccountStock
	set
	TotalQtyActualStock = t.NewTotalQtyActualStock, 
	TotalQtyOrderedByCustomer = t.NewTotalQtyOrderedByCustomer,
	TotalQtyOrderedToSupplier = t.NewTotalQtyOrderedToSupplier, 
	TotalQtyInProduction = t.NewTotalQtyInProduction,
	TotalQtyInConsumption = t.NewTotalQtyInConsumption,
	TotalReservedStock = t.NewTotalReservedStock,
	TotalQtyPendingProduction = t.NewTotalQtyPendingProduction,
	StockStatus = CASE WHEN ISNULL(StockManagement,0) = 0 THEN 0 ELSE
		CASE 
		WHEN t.NewTotalQtyActualStock < 0 THEN 9
		WHEN t.NewPredictedStock < 0 THEN 8
		WHEN t.NewTotalAvailableStock < 0 THEN 7
		WHEN t.NewTotalQtyActualStock = 0 OR t.NewTotalQtyActualStock IS NULL THEN 6
		WHEN t.NewPredictedStock = 0 OR t.NewPredictedStock IS NULL THEN 5
		WHEN t.NewTotalAvailableStock = 0 OR t.NewTotalAvailableStock IS NULL THEN 4
		WHEN t.NewTotalQtyActualStock < MinQty THEN 3
		WHEN t.NewPredictedStock < MinQty THEN 2
		WHEN t.NewTotalAvailableStock < MinQty THEN 1
		ELSE 0
		END
	END
	from(
		select 
		[TotalQtyActualStock] NewTotalQtyActualStock,
		[TotalQtyOrderedByCustomer] NewTotalQtyOrderedByCustomer,
		[TotalQtyOrderedToSupplier] NewTotalQtyOrderedToSupplier,
		[TotalQtyInProduction] NewTotalQtyInProduction,
		[TotalQtyInConsumption] NewTotalQtyInConsumption, 
		[TotalReservedStock] NewTotalReservedStock,
		[TotalQtyPendingProduction] NewTotalQtyPendingProduction,
		TotalQtyActualStock - TotalReservedStock - TotalQtyInConsumption NewTotalAvailableStock,
		TotalQtyActualStock - TotalReservedStock - TotalQtyInConsumption + TotalQtyOrderedToSupplier + TotalQtyInProduction NewPredictedStock
		from SysPocValue where MovementMode = 3 and MovementRootType = 0 and IDRecord = @IDRecord and IDRecordModule = @idModule
	) t
	where IDAccount = @IDRecord;

	if @IDModule in (select IDModule from GetModulesRec('F9DFD9B3-86FC-4D20-B62C-C6E28A1DC4F0'))
	begin
		update AccountStock set IsAccVirtualFinalized = 
		case
			when TotalQtyActualStock = 0 and TotalQtyInConsumption = 0 and TotalQtyInProduction = 0 
			and TotalQtyOrderedByCustomer = 0 and TotalQtyOrderedToSupplier = 0 then 1
			else 0
		end
		where IDAccount = @IDRecord and IDModule = @IDModule
	end
END
GO


-- ----------------------------
-- procedure structure for UpdateProductDBMaskFromStockAccount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateProductDBMaskFromStockAccount]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateProductDBMaskFromStockAccount]
GO

CREATE PROCEDURE [dbo].[UpdateProductDBMaskFromStockAccount] 
	@IDRecord int,
	@IDModule uniqueidentifier
AS
BEGIN
	update products set dbmask = dbmask | t.NewDBMask
	from(
		select p.productid ID, p.IDModule PIDModule, acc.dbmask NewDBMask
		from Account acc
		inner join products p on p.productid = acc.IDContact and p.IDModule = acc.IDContactModule
		where acc.IDAccount = @IDRecord and acc.IDModule = @IDModule
	) t
	where productid = t.ID and IDModule = t.PIDModule
END
GO


-- ----------------------------
-- procedure structure for UpdateTaskProductionFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateTaskProductionFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateTaskProductionFields]
GO

CREATE PROCEDURE [dbo].[UpdateTaskProductionFields]
	 @IDTask uniqueidentifier,
	 @IDModule uniqueidentifier
AS
BEGIN
	declare @IsProduction int = dbo.GetIsTaskProduction(@IDTask);
	
	if @IsProduction = 1
	BEGIN
		declare @StartDate datetime = (select top 1 StartDateEstimated from SysTask where IDTask = @IDTask);
		update SysRoutineTeamRoleResource set StartDateEstimated = @StartDate where IDSysTaskProcess = @IDTask;

		update SysTask set StartDateEstimated = t.SD
		from
		(
			select rtrr.IDSysTaskProcess IDT, rtrr.StartDateEstimated SD
			from SysTask t
			inner join SysRoutineTeamRoleResource rtrr on t.IDTask = rtrr.IDSysTask
			where t.IDTask = @IDTask
		) t
		where IDTask = t.IDT;

		update MouldTest set status = t.NewStatus
		from
		(
			select mt.IDMouldTest as IDMT, t.RunningStatus NewStatus
			from SysTask t
			inner join SysRoutineTeamRoleResource trr on trr.IDSysTask = t.IDTask
			inner join SysOprRoutineItem ori on ori.IDRoutineItem = trr.IDRoutineItem
			inner join MouldTest mt on mt.IDSysDocOprRoutineItem = ori.DocTemplate
			where 
			IDTask = @IDTask 
			and trr.IDProcessRoutineItem = '1CDF6966-60D9-445A-8553-E5A824735CB1'
		) t
		where IDMouldTest = t.IDMT;
	END
END
GO


-- ----------------------------
-- procedure structure for Query_POs_to_3dsystems
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_POs_to_3dsystems]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_POs_to_3dsystems]
GO

CREATE PROCEDURE [dbo].[Query_POs_to_3dsystems]

AS
BEGIN
	SET NOCOUNT ON;

	select	
		d.doc_ref,
		d.doc_date,
		d.doc_3rd_account_name,
		d.subject,
		dl.LineNumber,
		dl.productcode,
		dl.ProductName,
		dl.Qty,
		dl.UnitPrice,
		dl.DiscountPerc1,
		dl.DiscountPerc2,
		dl.DiscountPerc3,
		dl.AssetSerial,
		dl.DiscountEur,
		dl.NetTotal
	from document d inner join DocumentLine dl on d.IDDocument = dl.IDRegister
	where 
		d.doc_3rd_account_name like '3d systems%' and year(doc_date) = 2019
		and d.idmodule in (select idmodule from dbo.GetModulesRec('bc2c3113-36fa-4c7c-900e-b2876893c12a'))
		and d.RegisterSysStatus = 0 and
		(  ( d.[RelActive] = 1 And d.[AlternativeActive] = 1  ) ) and dl.IDLineType = 1 
		and not dl.IDParent is null
		and not exists(select  ID from DocumentLine aux where aux.IDParent = dl.ID)
	order by d.IDDocument, dl.GridOrder
END
GO


-- ----------------------------
-- procedure structure for ChatUpdateDateRead
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatUpdateDateRead]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatUpdateDateRead]
GO

CREATE PROCEDURE [dbo].[ChatUpdateDateRead]
    @IDUser UNIQUEIDENTIFIER = NULL,
    @IDResource UNIQUEIDENTIFIER = NULL,
    @IDChannel UNIQUEIDENTIFIER, 
    @IDChat INT,
    @NewDate DATETIME,
    @MessageState INT, -- 0 = Initialized, 1 = Unread, 2 = Marked, 3 = Read
    @MessageConfidentialityLevel INT, -- 0 = Public, 1 = Normal, 2 = Confidential, 3 = Private
    @ResourceAccessType INT, -- 0 = Public, 1 = Normal, 2 = Confidential
    @IsOnDestiny INT -- 0 = Is not on destiny, 1 = Is on destiny 
AS
BEGIN
    SET NOCOUNT ON;

    -- Table variable to capture the specific channels affected by the update
    DECLARE @AffectedChannels TABLE (
        IDChannel UNIQUEIDENTIFIER,
        OldState INT
    );

    BEGIN TRANSACTION;

    BEGIN TRY
        -- ==========================================================================================
        -- 1. UPDATE PATH
        -- Attempt to update ALL occurrences of this chat for the user/resource.
        -- Optimization: The WHERE clause ensures updates only occur if the MessageState implies a change.
        -- ==========================================================================================
        UPDATE SysChatUserInteraction
        SET DateState = CASE
                            WHEN MessageState = 1 THEN GETUTCDATE()
                            ELSE DateState
                        END,
            MessageState = @MessageState
        OUTPUT deleted.IDChannel, deleted.MessageState INTO @AffectedChannels
        WHERE IDChat = @IDChat
          AND (IDUser = @IDUser OR IDResource = @IDResource)
          AND MessageState <> @MessageState
          AND MessageState >= 1 AND MessageState <= 3 ; 

        -- ==========================================================================================
        -- 2. CHECK: Were any records updated?
        -- ==========================================================================================
        IF EXISTS (SELECT 1 FROM @AffectedChannels)
        BEGIN
            -- Logic: Update counters for all channels that were modified.
            
            -- Increment Counter (State became Marked)
            IF (@MessageState = 2) 
            BEGIN
                UPDATE R
                SET UnreadMessagesCounter = R.UnreadMessagesCounter + 1
                FROM SysWorkRoomResource R
                INNER JOIN @AffectedChannels AC ON R.IDWorkRoom = AC.IDChannel
                WHERE (R.IDResource = @IDResource OR R.IDLogin = @IDUser);
            END
            ELSE 
            -- Decrement Counter (State became Read)
            IF (@MessageState = 3)
            BEGIN
                UPDATE R
                SET UnreadMessagesCounter = CASE 
                                                WHEN R.UnreadMessagesCounter > 0 THEN R.UnreadMessagesCounter - 1 
                                                ELSE 0 
                                            END
                FROM SysWorkRoomResource R
                INNER JOIN @AffectedChannels AC ON R.IDWorkRoom = AC.IDChannel
                WHERE (R.IDResource = @IDResource OR R.IDLogin = @IDUser)
                  AND (AC.OldState = 1 OR AC.OldState = 2);
            END

            -- Commit transaction and return the list of affected channels to the application.
            COMMIT TRANSACTION;
            SELECT IDChannel, OldState FROM @AffectedChannels;
        END
        ELSE
        BEGIN
            -- ==========================================================================================
            -- 3. INSERT OR IDEMPOTENT PATH
            -- If no rows were updated, check if the record is missing or if the state was already correct.
            -- ==========================================================================================
            
            IF NOT EXISTS (SELECT 1 FROM SysChatUserInteraction WHERE IDChat = @IDChat AND (IDUser = @IDUser OR IDResource = @IDResource) AND MessageState >= 1 AND MessageState <= 3 )
            BEGIN
                -- Case A: INSERT (Record does not exist)
                -- Insert into the specific IDChannel provided.
                
                INSERT INTO SysChatUserInteraction (IDChat, IDUser, IDResource, DateState, IDChannel, MessageState)
                VALUES (@IDChat, @IDUser, @IDResource, @NewDate, @IDChannel, @MessageState);
                
                -- Update Counter for the single new entry
                IF (@MessageState = 2) 
                BEGIN
                    UPDATE SysWorkRoomResource
                    SET UnreadMessagesCounter = UnreadMessagesCounter + 1
                    WHERE IDWorkRoom = @IDChannel
                      AND (IDResource = @IDResource OR IDLogin = @IDUser);
                END
                
                -- Commit and return the IDChannel as it is a newly affected row.
                COMMIT TRANSACTION;
                SELECT @IDChannel AS IDChannel, 2 As OldState; -- 2 = Marked
            END
            ELSE
            BEGIN
                -- Case B: NO-OP (Record exists, but State matches @MessageState)
                -- The transaction must be committed to release locks.
                -- We do NOT return a result set (SELECT). This signals the application that no logical change occurred.
                
                COMMIT TRANSACTION;
                RETURN 0; 
            END
        END
        
        -- Fallback return
        RETURN 0;

    END TRY
    BEGIN CATCH
        -- Rollback if an error occurs during the transaction
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        
        RETURN 2; -- Error Code
    END CATCH
END
GO


