CREATE PROCEDURE [dbo].[LaunchWorkflow1] @idtask integer, @date1 datetime, @date2 datetime, @cost float, @costvalue float
AS BEGIN
	SET NOCOUNT ON;

	DECLARE @id1 as int = 0;
	DECLARE @id2 as int = 0;
	DECLARE @id3 as int = 0;
	DECLARE @idWF as int = 0;
	DECLARE @iditem1 as int = 0;
	DECLARE @iditem2 as int = 0;
	DECLARE @iditem3 as int = 0;
	DECLARE @idvar1 as int = 0;
	DECLARE @idvar2 as int = 0;
	DECLARE @idvar3 as int = 0;
	DECLARE @idcond1 as int = 0;
	DECLARE @idcond2 as int = 0;
	DECLARE @idcond3 as int = 0;
	DECLARE @idaction1 as int = 0;
	DECLARE @idaction2 as int = 0;
	DECLARE @idaction3 as int = 0;
	DECLARE @idaction4 as int = 0;


	DECLARE @idModulo as int = 19;
	
	Begin Tran T1
	INSERT INTO [dbo].[TaskTimes]([IDTask] ,[StartTime] ,[EndTime] ,[TaskCost] ,[TaskCostvalue])
    VALUES(@idtask ,@date1,@date2 ,@cost ,@costvalue )
	SET @id1 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[TaskTimes]([IDTask] ,[StartTime] ,[EndTime] ,[TaskCost] ,[TaskCostvalue])
    VALUES(@idtask ,DATEADD(day,1,@date1),DATEADD(day,1,@date2) ,@cost ,@costvalue)
	SET @id2 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[TaskTimes]([IDTask] ,[StartTime] ,[EndTime] ,[TaskCost] ,[TaskCostvalue])
    VALUES(@idtask ,DATEADD(day,5,@date1), DATEADD(day,6,@date2),@cost ,@costvalue)
	SET @id3 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflow] ([IsTemplate] ,[Descricao] ,[IDWorkflowParent] ,[IDRole] ,[WorkflowClone])
    VALUES (0 ,'' ,0 ,0 ,17)
	SET @idWF = (SELECT SCOPE_IDENTITY())


	INSERT INTO [dbo].[SysWorkflowItem]([IDWorkflow],[IDModule],[IDRegisto],[IDRole],[Disponibilidade],[Priority],[Severity],[Complexity],[Descricao],[Code],[Order])
	VALUES(@idWF,@idModulo,@id1,1,1,1,1,1,'','OP1',0)
	SET @iditem1 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowItem]([IDWorkflow],[IDModule],[IDRegisto],[IDRole],[Disponibilidade],[Priority],[Severity],[Complexity],[Descricao],[Code],[Order])
	VALUES(@idWF,@idModulo,@id2,0,0,1,1,1,'','OP2',1)
	SET @iditem2 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowItem]([IDWorkflow],[IDModule],[IDRegisto],[IDRole],[Disponibilidade],[Priority],[Severity],[Complexity],[Descricao],[Code],[Order])
	VALUES(@idWF,@idModulo,@id3,0,0,1,1,1,'','OP3',2)
	SET @iditem3 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowVars] ([IDWorkflow] ,[Code] ,[DefaultValue] ,[IDModule] ,[IDField] ,[CurrentVal])
	VALUES (@idWF ,'Var1' ,0 ,NULL ,NULL ,1)
	SET @idvar1 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowVars] ([IDWorkflow] ,[Code] ,[DefaultValue] ,[IDModule] ,[IDField] ,[CurrentVal])
	VALUES (@idWF ,'Var2' ,0 ,NULL ,NULL ,0)
	SET @idvar2 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowVars] ([IDWorkflow] ,[Code] ,[DefaultValue] ,[IDModule] ,[IDField] ,[CurrentVal])
	VALUES (@idWF ,'Var3' ,0 ,NULL ,NULL ,0)
	SET @idvar3 = (SELECT SCOPE_IDENTITY())


	INSERT INTO [dbo].[SysWorkflowConditions] ([IDWorkflowItem] ,[Condition] ,[InitCondition] ,[EndCondition])
	VALUES (@iditem1 ,'Cond1' ,1 ,0)
	SET @idcond1 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowConditions] ([IDWorkflowItem] ,[Condition] ,[InitCondition] ,[EndCondition])
	VALUES (@iditem2 ,'Cond1' ,1 ,0)
	SET @idcond2 = (SELECT SCOPE_IDENTITY())

	INSERT INTO [dbo].[SysWorkflowConditions] ([IDWorkflowItem] ,[Condition] ,[InitCondition] ,[EndCondition])
	VALUES (@iditem3 ,'Cond1' ,1 ,0)
	SET @idcond3 = (SELECT SCOPE_IDENTITY())


	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond1 ,@idvar1 ,'equal' ,'1' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond1 ,@idvar2 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond1 ,@idvar3 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond2 ,@idvar1 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond2 ,@idvar2 ,'equal' ,'1' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond2 ,@idvar3 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond3 ,@idvar1 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond3 ,@idvar2 ,'equal' ,'0' ,'AND' ,null)

	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent])
	VALUES (@idcond3 ,@idvar3 ,'equal' ,'1' ,'AND' ,null)

	
INSERT INTO [dbo].[SysWorkflowActions] ([Codigo] ,[IDWorkflowItem]) VALUES ('Go To Step2' ,@iditem1)
SET @idaction1 = (SELECT SCOPE_IDENTITY())
INSERT INTO [dbo].[SysWorkflowActionIteractions] ([IDWorkflowAction] ,[IDActionType] ,[IDField] ,[StoredProcedure] ,[SqlCommand] ,[FieldValue]) VALUES (@idaction1 ,1 ,0 ,null ,'UPDATE SysWorkflowVars SET CurrentVal = '+ CONVERT(VARCHAR(12), 1) + ' WHERE IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar2) + '; UPDATE SysWorkflowVars SET CurrentVal =  '+ CONVERT(VARCHAR(12), 0) + ' WHERE IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar3) + ' OR IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar1) + '; ' ,null)
