INSERT INTO [dbo].[SysWorkflowActions] ([Codigo] ,[IDWorkflowItem]) VALUES ('Go To Step3' ,@iditem2)
SET @idaction3 = (SELECT SCOPE_IDENTITY())
INSERT INTO [dbo].[SysWorkflowActionIteractions] ([IDWorkflowAction] ,[IDActionType] ,[IDField] ,[StoredProcedure] ,[SqlCommand] ,[FieldValue]) VALUES (@idaction3 ,1 ,0 ,null ,'UPDATE SysWorkflowVars SET CurrentVal = '+ CONVERT(VARCHAR(12), 1) + ' WHERE IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar3) + '; UPDATE SysWorkflowVars SET CurrentVal = '+ CONVERT(VARCHAR(12), 0) + ' WHERE IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar2) + ' OR IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar1) + '; ' ,null)
INSERT INTO [dbo].[SysWorkflowActions] ([Codigo] ,[IDWorkflowItem]) VALUES ('Finish' ,@iditem3)
SET @idaction4 = (SELECT SCOPE_IDENTITY())
INSERT INTO [dbo].[SysWorkflowActionIteractions] ([IDWorkflowAction] ,[IDActionType] ,[IDField] ,[StoredProcedure] ,[SqlCommand] ,[FieldValue]) VALUES (@idaction4 ,1 ,0 ,null ,'UPDATE SysWorkflowVars SET CurrentVal = '+ CONVERT(VARCHAR(12), 0) + ' WHERE IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar3) + ' OR IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar1) + ' OR IDWorkflowVars = ' + CONVERT(VARCHAR(12), @idvar2) + '; ' ,null)




	Commit Tran T1
END
