-- ----------------------------
-- procedure structure for ChatCreateUserRead
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatCreateUserRead]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatCreateUserRead]
GO

CREATE PROCEDURE [dbo].[ChatCreateUserRead]
    @IDChat INT,
    @IDUser UNIQUEIDENTIFIER,
    @IDResource UNIQUEIDENTIFIER,
    @IDChannel UNIQUEIDENTIFIER,
    @MessageConfidentialityLevel INT,
    @ResourceAccessType INT,
    @IsOnDestiny INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1
        FROM SysChatUserInteraction
        WHERE IDChannel = @IDChannel
          AND IDChat = @IDChat
          AND (IDUser = @IDUser OR IDResource = @IDResource)
    )
    BEGIN
        INSERT INTO SysChatUserInteraction (IDChat, IDUser, IDResource, DateState, IDChannel, MessageState, MessageConfidentialityLevel, ResourceAccessType, IsOnDestiny)
        VALUES (@IDChat, @IDUser, @IDResource, NULL, @IDChannel, 1, @MessageConfidentialityLevel, @ResourceAccessType, @IsOnDestiny);

        UPDATE SysWorkRoomResource
        SET UnreadMessagesCounter = UnreadMessagesCounter + 1
        WHERE IDWorkRoom = @IDChannel
          AND (IDResource = @IDResource OR IDLogin = @IDUser);

        RETURN 0;
    END

    RETURN 1; -- already exists
END
GO


-- ----------------------------
-- function structure for GetStrModuleSelect
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetStrModuleSelect]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetStrModuleSelect]
GO

CREATE FUNCTION [dbo].[GetStrModuleSelect]
(
	-- Add the parameters for the function here
	@IDModule int
)
RETURNS NVARCHAR(MAX)
AS
BEGIN

	DECLARE @f_TableName varchar (50)
	DECLARE @f_ColumnName varchar (50) 
	DECLARE @RESULT_STRING nvarchar(max);
	DECLARE myCursor CURSOR FOR 
		SELECT TableName,ColumnName FROM Field
		WHERE IDModule=@IDModule
	SET @RESULT_STRING=''
	OPEN myCursor

	FETCH NEXT FROM myCursor INTO @f_TableName, @f_ColumnName

	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		if (ISNULL( @RESULT_STRING,'')!='')
			SET @RESULT_STRING=@RESULT_STRING+', '
		if (ISNULL( @f_TableName,'')!='')
		SET @RESULT_STRING = @RESULT_STRING + @f_TableName + '.' + @f_ColumnName
		
		FETCH NEXT FROM myCursor INTO @f_TableName, @f_ColumnName
	END

	CLOSE myCursor
	DEALLOCATE myCursor
	-- Return the result of the function
	RETURN @RESULT_STRING

END
GO


