-- ----------------------------
-- function structure for GetProductChildren
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetProductChildren]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetProductChildren]
GO

CREATE FUNCTION [dbo].[GetProductChildren]
(	
	@productid int
)
RETURNS TABLE 
AS
RETURN 
(
	with GetModulesRecc as (
		select productid, IDParent
		from products
		where productid = @productid
		union all
		select m.productid, m.IDParent
		from products m inner join GetModulesRecc p on m.idparent = p.productid
	)
	select m.productid
	from products m
		inner join
		GetModulesRecc rec on m.productid = rec.productid
)
GO


