-- function structure for GetRowFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRowFields]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetRowFields]
GO

CREATE FUNCTION [dbo].[GetRowFields]
(
	@IDModule int,
	@IDRole int,
	@IDView int
) 
RETURNS NVARCHAR(MAX)
AS
BEGIN
	DECLARE @f_TableName varchar (50)
	DECLARE @f_ColumnName varchar (50) 
	DECLARE @RESULT_STRING nvarchar(max);
	DECLARE myCursor CURSOR FOR 
		SELECT TableName,ColumnName FROM Field f
		INNER JOIN T_Fields2Role fr on fr.IDRole=@IDRole AND fr.IDField=f.IDField
		INNER JOIN T_Field2View fv on fv.IDView=@IDView AND fv.IDField =f.IDField
		WHERE IDModule=@IDModule

	OPEN myCursor

	FETCH NEXT FROM myCursor INTO @f_TableName, @f_ColumnName

	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		if (ISNULL( @RESULT_STRING,'')!='')
			SET @RESULT_STRING=@RESULT_STRING+', '
		if (ISNULL( @f_TableName,'')!='')
		SET @RESULT_STRING = @RESULT_STRING + @f_TableName + '.' + @f_ColumnName
		
		FETCH NEXT FROM myCursor INTO @f_TableName, @f_ColumnName
	END

	CLOSE myCursor
	DEALLOCATE myCursor
	-- Return the result of the function
	RETURN @RESULT_STRING

END
GO


-- ----------------------------
-- procedure structure for GetField
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetField]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetField]
GO

CREATE PROCEDURE [dbo].[GetField] @Module int = 0, @Parent int = 0, @Count int = 0 OUTPUT
AS 
	--PRINT @Module
	DECLARE @Table varchar(50), @Column varchar(50), @sequence int, @ParentF int, @UI varchar(20), @ID int, @IDF int = 0
	IF @Parent = null
		BEGIN
			SELECT @ID = IdField, @Table = TableName, @Column = ColumnName, @sequence = Sequence, @ParentF = IDParentField, @UI = UIType FROM SysField WHERE IDModule = @Module AND IDParentField = 0
			PRINT @Count
			SET @Count  = @Count + 1
		END
	ELSE
		BEGIN
			SELECT @ID = IdField, @Table = TableName, @Column = ColumnName, @sequence = Sequence, @ParentF = IDParentField, @UI = UIType FROM SysField WHERE IDModule = @Module AND IDParentField = @Parent
			PRINT @Count
			SET @Count  = @Count + 1
		END
	
	--SELECT @ID = IdField, @Table = TableName, @Column = ColumnName, @sequence = Sequence, @ParentF = IDParentField, @UI = UIType FROM SysField WHERE IDModule = @Module
	PRINT CAST(@ID as varchar(10)) + '||' + CAST(@Table as varchar(50)) + '||' + CAST(@Column as varchar(50)) + '||' + CAST(@sequence as varchar(10)) + '||' + CAST(@ParentF as varchar(10)) + '||' +CAST(@UI as varchar(10)) 

	DECLARE cursorName CURSOR LOCAL FOR SELECT IdField FROM  SysField WHERE IDParentField = @ID AND IDModule = @Module ORDER BY Sequence ASC
	OPEN cursorName -- open the cursor

	FETCH NEXT FROM cursorName INTO @IDF
	WHILE @@FETCH_STATUS = 0
		BEGIN
			EXECUTE GetField @Module , @IDF, @Count = @Count Output
			FETCH NEXT FROM cursorName INTO  @IDF
		END
CLOSE cursorName -- close the cursorName cursor
DEALLOCATE cursorName -- Deallocate the cursor
GO


-- ----------------------------
-- procedure structure for GetRecursiveAllSubordinatesRoles
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRecursiveAllSubordinatesRoles]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetRecursiveAllSubordinatesRoles]
GO

CREATE PROCEDURE [dbo].[GetRecursiveAllSubordinatesRoles]
	-- Add the parameters for the stored procedure here
	@resource nvarchar(100)
AS

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	WITH tblChild AS(
                        SELECT *
                            FROM SysRoleRelationship WHERE IDResource = @resource
                        UNION ALL
                            SELECT SysRoleRelationship.*  FROM SysRoleRelationship  
                            JOIN tblChild  ON SysRoleRelationship.IDRoleRelParent = tblChild.IDRoleRel
                    )
                    SELECT IDResource
                        FROM tblChild
	                WHERE IDResource <> @resource
                    OPTION(MAXRECURSION 32767)
GO


-- ----------------------------
-- procedure structure for Try_LockDocumentForClosing
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Try_LockDocumentForClosing]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Try_LockDocumentForClosing]
GO

CREATE PROCEDURE [dbo].[Try_LockDocumentForClosing]
@locking int,
@IDDocument int,
@IDModule uniqueidentifier,

@IDLogin uniqueidentifier out,
@IDResource uniqueidentifier,
@ExpectedRegisterStatus int = 2,
@CurrentRegisterStatus int = 2,
@IDSession uniqueidentifier out,
@IDWorkstation nvarchar(50) out,
@Token nvarchar(50) out,
@o_registerStatusOld int = null out
AS
BEGIN
SET NOCOUNT ON;

SET TRANSACTION ISOLATION LEVEL SERIALIZABLE
begin tran
	
DECLARE @this_result int
set @this_result = 0
DECLARE @r INT
DECLARE @d_idRecord int, @d_idModule uniqueidentifier, @registerStatusOld int, @mTable nvarchar(200), @mTablePk nvarchar(200)
-- DECLARE @token nvarchar(50)

-- Check if record exists

IF @IDModule in( select idmodule from GetModulesRec('9FC0A690-18E0-4290-90A3-9874333B12E5'))
begin
	SELECT @d_idRecord = IDDocument, @d_idModule = IDModule
	FROM document
	WHERE IDDocument = @IDDocument AND IDModule = @IDModule
	set @mTable = 'document';
	set @mTablePk = 'IDDocument';
end
else if @IDModule in( select idmodule from GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944'))
begin
	SELECT @d_idRecord = IDFollowUpItem, @d_idModule = IDModule
	FROM FollowUpItem
	WHERE IDFollowUpItem = @IDDocument AND IDModule = @IDModule
	set @mTable = 'FollowUpItem';
	set @mTablePk = 'IDFollowUpItem';
end

print concat('set lock record ', @IDDocument, @IDModule)

EXEC @r = [dbo].[Try_LockRecordForEdition] @locking = @locking, 
	@IDRecord = @d_idRecord, @IDModule = @d_idModule, 
	@IDSession = @IDSession, @IDWorkstation = @IDWorkstation,
	@IDLogin = @IDLogin, @IDResource = @IDResource, @MainTable = @mTable, 
	@MainTablePk = @mTablePk, @MainTableModId = 'IDModule', @IDModuleFilterView = NULL, @expectedRegisterStatus = @CurrentRegisterStatus, @registerStatus = @CurrentRegisterStatus,
	@o_token = @token output, @o_registerStatusOld = @registerStatusOld output
	
set @o_registerStatusOld = @registerStatusOld

IF @r != 0 
begin
	print concat('Error on lock record = ', @r);
	set @this_result = 1
	goto _end
end
-- Lock document lines with the same token

declare @l_ID int, @l_IDRegister int, @l_IDModule uniqueidentifier, @l_IDRegisterLink int, @l_IDModuleLink uniqueidentifier
declare lines cursor for
		SELECT ID, productid, productidModule, IDRegisterLink, IDModuleLink
		FROM documentline
		WHERE IDRegister = @IDDocument AND IDModule = @IDModule

open lines;
fetch next from lines into @l_ID, @l_IDRegister, @l_IDModule, @l_IDRegisterLink, @l_IDModuleLink

WHILE @@FETCH_STATUS = 0
begin
	IF @l_IDRegister is not null AND @l_IDRegister > 0 AND @l_IDModule is not null 
	begin
		print concat('lock main product IDRecord = ', @l_IDRegister, ' IDModule = ', @l_IDModule)

		EXEC @r = [dbo].[Try_LockRecordForEdition] @locking = @locking, 
			@IDRecord = @l_IDRegister, @IDModule = @l_IDModule, 
			@IDSession = @IDSession, @IDWorkstation = @IDWorkstation,
			@IDLogin = @IDLogin, @IDResource = @IDResource, @MainTable = '', @IDModuleFilterView = NULL, @expectedRegisterStatus = @ExpectedRegisterStatus, @registerStatus = @CurrentRegisterStatus,
			@MainTablePk = '', @MainTableModId = '', @o_token = @token output, @o_registerStatusOld = @registerStatusOld output

		IF @r != 0 
		begin
			print concat('Error on lock = ', @r);
			set @this_result = 1
			goto _end_with_lines_dealloc
		end
	end

	IF @l_IDRegisterLink is not null AND @l_IDRegisterLink > 0 AND @l_IDModuleLink is not null 
	begin
		print concat('lock src product IDRecord = ', @l_IDRegisterLink, ' IDModule = ', @l_IDModuleLink)

		EXEC @r = [dbo].[Try_LockRecordForEdition] @locking = @locking, 
			@IDRecord = @l_IDRegisterLink, @IDModule = @l_IDModuleLink, 
			@IDSession = @IDSession, @IDWorkstation = @IDWorkstation,
			@IDLogin = @IDLogin, @IDResource = @IDResource, @MainTable = '',  @IDModuleFilterView = NULL, @expectedRegisterStatus = 0, @registerStatus = 2,
			@MainTablePk = '', @MainTableModId = '', @o_token = @token output, @o_registerStatusOld = @registerStatusOld output

		IF @r != 0 
		begin
			print concat('Error on lock = ', @r);
			set @this_result = 1
			goto _end_with_lines_dealloc
		end
	end

	fetch next from lines into @l_ID, @l_IDRegister, @l_IDModule, @l_IDRegisterLink, @l_IDModuleLink;
end;

_end_with_lines_dealloc:

close lines;
deallocate lines;
	
_end:

if @this_result = 0
begin
	-- All locks were created
	commit
end
else
begin
	-- Locks rollbacked
	rollback

	select lr.*, concat('nº ', d.doc_ref, ' ', CONVERT(nvarchar(50), d.doc_date, 105), ' ', d.[subject]) as title
	from 
		SysLockRecord lr
		INNER JOIN document d ON lr.IDModule = d.IDModule and lr.IDRecord = cast( d.IDDocument as nvarchar(50))
		and d.IDDocument = @IDDocument and d.IDModule = @IDModule
	where lr.[Status] = 1
	union
	select lr.*, concat('nº ', fup.Code, ' ', CONVERT(nvarchar(50), fup.CreationDate, 105), ' ', fup.[Name]) as title
	from 
		SysLockRecord lr
		INNER JOIN FollowUpItem fup ON lr.IDModule = fup.IDModule and lr.IDRecord = cast( fup.IDFollowUpItem as nvarchar(50))
		and fup.IDFollowUpItem = @IDDocument and fup.IDModule = @IDModule
	where lr.[Status] = 1
	select lr.*, p.productname as title
	from 
		SysLockRecord lr
		left join DocumentLine dl on lr.IDModule = dl.productidModule  and lr.IDRecord =cast( dl.productid as nvarchar(50)) and dl.IDRegister = @IDDocument and dl.IDModule = @IDModule
		inner join products p on dl.productidModule = p.IDModule and dl.productid = p.productid
	where lr.[Status] = 1
	union
	select lr.*, p.productname as title
	from 
		SysLockRecord lr
		left  join DocumentLine dl2 on lr.IDModule = dl2.IDModuleLink  and lr.IDRecord = cast(dl2.IDRegisterLink as nvarchar(50)) and dl2.IDRegister = @IDDocument and dl2.IDModule = @IDModule
		inner join products p on dl2.IDModuleLink = p.IDModule and dl2.IDRegisterLink = p.productid
	where lr.[Status] = 1

end

return @this_result;
END
GO


