CREATE FUNCTION [dbo].[GetModuleSQLStr]
(
	@IDModule int,
	@IDRole int,
	@IDView int
)
RETURNS nvarchar(MAX)
AS
BEGIN
	DECLARE @sql_str nvarchar(MAX)
	SET @sql_str=''
	SET @sql_str=( SELECT tf.SQL FROM T_Filters tf WHERE tf.IDModule=@IDModule)
	if(ISNULL(@sql_str,'')='')
		SET @sql_str='SELECT ' + [dbo].[GetRowFields](@IDModule,@IDRole,@IDView)+ [dbo].[GETModuleSQLFrom](@IDModule)
	RETURN @sql_str

END
GO


-- ----------------------------
-- procedure structure for CloseAllExpiredSessions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseAllExpiredSessions]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseAllExpiredSessions]
GO

CREATE PROCEDURE [dbo].[CloseAllExpiredSessions]
	@sessionTimeoutMin int = null
AS
	 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @IDSession uniqueidentifier
	declare @dateStart datetime

	-- DECLARE @sessionTimeout INT
	--SET @sessionTimeout = (SELECT CASE WHEN ISNUMERIC(Value) = 1 THEN CAST(Value AS INT) ELSE 9999 END Value FROM SysSettings WHERE Name = 'SessionTimeout')
		
	if @sessionTimeoutMin is null
	begin
		SET @sessionTimeoutMin = (select top 1 SessionTimeout from SysSettings) --(SELECT CASE WHEN ISNUMERIC(Value) = 1 THEN CAST(Value AS INT) ELSE 9999 END Value FROM SysSettings WHERE Name = 'SessionTimeout')
	end
	
	if @sessionTimeoutMin is null
	begin
		set @sessionTimeoutMin = 9999
	end

    declare CloseAllExpiredSessions_it cursor 
		LOCAL STATIC READ_ONLY FORWARD_ONLY
		for
		select IDSession,DateStart from SysSession WHERE @sessionTimeoutMin <= DATEDIFF(minute, DateStart, GETUTCDATE());
	open CloseAllExpiredSessions_it;

	fetch next from CloseAllExpiredSessions_it into @IDSession, @dateStart;
	while @@FETCH_STATUS = 0
	begin

		print concat('session ', @IDSession, ' diff: ', DATEDIFF(minute, @dateStart, GETUTCDATE()), ' (timeout is ', @sessionTimeoutMin ,')')

		print concat('closing ', @IDSession, ' due to expired ')
			exec dbo.CloseSession @IDSession

		fetch next from CloseAllExpiredSessions_it into @IDSession, @dateStart;
	end

	close CloseAllExpiredSessions_it;
	deallocate CloseAllExpiredSessions_it;
	
	exec CloseAllZombieLocks


	delete
	from syslockrecord
	where Status = 0 and DATEDIFF(day, EndDate, getutcdate()) > 1
END
GO


-- ----------------------------
-- procedure structure for Update_VatTaxesTables
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Update_VatTaxesTables]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Update_VatTaxesTables]
GO

CREATE PROCEDURE [dbo].[Update_VatTaxesTables]
AS
BEGIN
	SET NOCOUNT ON;

	declare @now datetime
	set @now = GETUTCDATE()

	declare @current_taxes table(
		IDCountry uniqueidentifier not null,
		StartDate datetime not null,
		EndDate datetime null,
		Position int not null,
		Rate decimal(18,2) not null
	)

	insert into @current_taxes(IDCountry, StartDate, EndDate, Position, Rate)
	select IDCountry, StartDate, EndDate, Position, Rate
	from 
		SysVatTab t
		INNER JOIN SysVatTaxes tx ON t.IDVatTab = tx.IDVatTab
	WHERE 
		StartDate <= @now and (EndDate is null or EndDate > @now)


	-- update only open ProdCountryVatTaxes
	update pcvt
	set pcvt.Rate = ct.Rate
	from ProdCountryVatTaxes as pcvt
		inner join @current_taxes ct on
		pcvt.IDCountry = ct.IDCountry
		and
		pcvt.TaxPosition = ct.Position
		and
		pcvt.StartDate <= @now
		and
		(pcvt.EndDate is null or pcvt.EndDate > @now)

END
GO


