-- ----------------------------
-- procedure structure for SS_GenerateMsg
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GenerateMsg]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_GenerateMsg]
GO

CREATE PROCEDURE [dbo].[SS_GenerateMsg]
	-- Add the parameters for the stored procedure here
	@OperationID int,
	@ObjectID uniqueidentifier,
	@LoginID int,
	@Note nvarchar(100)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Verificar se as mensagens estao ligadas
	declare @SendMessages bit
	Set @SendMessages= (Select top 1 isnull(ShowMessages,0) from ss_config);
	if @SendMessages=1 
	begin
		-- Verificar se é para enviar mensagens para esta operaçao
		declare @MsgOperation int
		set @MsgOperation=(Select isnull(id,0) from ss_cfgmsgOperation where idoperation=@OperationID)
		if @MsgOperation>0
		begin
			-- Enviar notificaçoes para os logins 'target'

			insert into SS_ObjectMessages(IDObject,IDLoginCreated,IDLoginTarget,DateCreated,Msg,dateread) 
			Select @ObjectID,@LoginID,l.idlogin,getdate(),@Note,null
			from SS_CfgMsgLogin l
			where l.idcfgmsg=@MsgOperation
		end
	end
END
GO


