CREATE FUNCTION [dbo].[GetResourceTeamResource]
(	
	-- Add the parameters for the function here
		@resource nvarchar(100)
)
RETURNS TABLE 
AS
RETURN 
(
	-- Add the SELECT statement with parameter references here
	select  SysResources.* from SysResourceRelationship 
	join SysResourceRelationship relresourceparent on relresourceparent.IDResourceRel = SysResourceRelationship.IDResourceRelParent
	join SysResources on ResourceId =  relresourceparent.IDResource and SysResources.Kind = -2 --There are no longer resources of kind Team
	where SysResourceRelationship.IDResource = @resource
)
GO


-- ----------------------------
-- function structure for GETModuleSQLFrom
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GETModuleSQLFrom]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GETModuleSQLFrom]
GO

CREATE FUNCTION [dbo].[GETModuleSQLFrom]
(
	-- Add the parameters for the function here
	@IDModule int
)
RETURNS nvarchar(MAX)
AS
BEGIN
	DECLARE @f_RelationTable varchar (50)
	DECLARE @f_RelationField varchar (50)
	DECLARE @f_IDRelation varchar (50)
	DECLARE @RESULT_STRING nvarchar(max)
	DECLARE @RESULT_CHILD nvarchar(max)
	DECLARE myCursor CURSOR FOR 		
		Select tm.RelationTable,tm.RelationField,tr.IDRelation FROM TableRelation tr 
		INNER JOIN TableModule tm on (tr.RelationKind ='TM' and tm.IDTableModule=tr.IDRelationKind and tr.IDRelationParent=0) 
		WHERE tr.IDModule=@IDModule  
	SET @RESULT_STRING=''
	OPEN myCursor

	FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField,@f_IDRelation

	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		-- Child Relation INNER JOIN statement
		SET @RESULT_CHILD= [dbo].GetRelationChildsStr(@f_IDRelation,@f_RelationTable+'.'+@f_RelationField)

		if(ISNULL(@RESULT_CHILD,'')!='')
		begin
			if (ISNULL( @RESULT_STRING,'')!='')
				SET @RESULT_STRING=@RESULT_STRING+', '			
			SET @RESULT_STRING=@RESULT_STRING + @f_RelationTable + '.' + @f_RelationField +@RESULT_CHILD
		end
		else
		begin
			if (ISNULL( @RESULT_STRING,'')!='')
				SET @RESULT_STRING=@RESULT_STRING+', '
			if (ISNULL( @f_RelationTable,'')!='')
			SET @RESULT_STRING = @RESULT_STRING + @f_RelationTable 
		end
		FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField,@f_IDRelation
	END

	CLOSE myCursor
	DEALLOCATE myCursor
	SET @RESULT_STRING = ' FROM '+@RESULT_STRING
	RETURN @RESULT_STRING

END
GO


-- ----------------------------
-- procedure structure for ChatUpdateAccessAndRefresh
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatUpdateAccessAndRefresh]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatUpdateAccessAndRefresh]
GO

CREATE PROCEDURE [dbo].[ChatUpdateAccessAndRefresh]
    @IDUser UNIQUEIDENTIFIER,
    @IDResource UNIQUEIDENTIFIER,
    @IDChannel UNIQUEIDENTIFIER,
    @NewResourceAccessType INT -- The new access level to be applied
AS
BEGIN
    SET NOCOUNT ON;

    -- Table variable to capture the state of deleted messages for counter logic
    DECLARE @DeletedMessages TABLE (
        IDChat INT,
        MessageState INT
    );

    DECLARE @DecrementAmount INT = 0;

    BEGIN TRANSACTION;

    BEGIN TRY
        -- 1. UPDATE STEP: First, apply the new Access Type to all records for this user/resource in the channel
        UPDATE SysChatUserInteraction
        SET ResourceAccessType = @NewResourceAccessType
        WHERE IDChannel = @IDChannel
          AND (IDUser = @IDUser OR IDResource = @IDResource);

        -- 2. DELETE STEP: Verify permissions based on the updated column and existing row data.
        --    Rule to Keep: ResourceAccessType >= MessageConfidentialityLevel OR IsOnDestiny = 1
        --    Rule to Delete (Inverse): ResourceAccessType < MessageConfidentialityLevel AND IsOnDestiny = 0
        
        DELETE FROM SysChatUserInteraction
        OUTPUT deleted.IDChat, deleted.MessageState INTO @DeletedMessages
        WHERE IDChannel = @IDChannel
          AND (IDUser = @IDUser OR IDResource = @IDResource)
          AND ResourceAccessType < MessageConfidentialityLevel -- Fails confidentiality check
          AND IsOnDestiny = 0; -- Is not a direct recipient

        -- 3. COUNTER UPDATE: Calculate impact on UnreadMessagesCounter
        --    We check for states 1 (Unread) and 2 (ToBeRead).
        
        SELECT @DecrementAmount = COUNT(1)
        FROM @DeletedMessages
        WHERE MessageState IN (1, 2);

        IF @DecrementAmount > 0
        BEGIN
            UPDATE R
            SET UnreadMessagesCounter = CASE 
                                            WHEN R.UnreadMessagesCounter >= @DecrementAmount 
                                            THEN R.UnreadMessagesCounter - @DecrementAmount
                                            ELSE 0 -- Safety net to prevent negative numbers
                                        END
            FROM SysWorkRoomResource R
            WHERE R.IDWorkRoom = @IDChannel
              AND (R.IDResource = @IDResource OR R.IDLogin = @IDUser);
        END

        COMMIT TRANSACTION;

        -- Return useful info for debugging or UI feedback
        SELECT @DecrementAmount AS CounterDecrementValue;
        
        RETURN 0;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);
        RETURN 2;
    END CATCH
END
GO


