-- ----------------------------
-- function structure for GetRelationChildsStr
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRelationChildsStr]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetRelationChildsStr]
GO

CREATE FUNCTION [dbo].[GetRelationChildsStr]
(
	-- Add the parameters for the function here
	@IDRelationParent int,
	@OnStrClause nvarchar(max)
)
RETURNS nvarchar(MAX)
AS
BEGIN
	DECLARE @RESULT_STRING_CHILD nvarchar(max)
	DECLARE @f_RelationTable nvarchar(max)
	DECLARE @f_RelationField nvarchar(max)
	DECLARE myCursor CURSOR FOR 
			SELECT tm.RelationTable,tm.RelationField 
			FROM TableRelation tr  
			INNER JOIN TableModule tm on (tr.RelationKind ='TM' and tm.IDTableModule=tr.IDRelationKind) 
			WHERE tr.IDRelationParent =@IDRelationParent
			
	SET @RESULT_STRING_CHILD=''

	if(@IDRelationParent=0)
		RETURN @RESULT_STRING_CHILD
	OPEN myCursor

	FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField
		
	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		SET @RESULT_STRING_CHILD=@RESULT_STRING_CHILD+' INNER JOIN '+@f_RelationTable+' ON '+ @OnStrClause +' = '+@f_RelationTable+'.'+ @f_RelationField
		FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField
	END
	CLOSE myCursor
	DEALLOCATE myCursor
	RETURN @RESULT_STRING_CHILD

END
GO


-- ----------------------------
-- function structure for GetDocPendingPaymentValues
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetDocPendingPaymentValues]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetDocPendingPaymentValues]
GO

CREATE FUNCTION [dbo].[GetDocPendingPaymentValues]
(	
	@IDDocument int,
	@Param int
)
RETURNS numeric(18,5) 
AS
BEGIN
RETURN 
(
	
	SELECT TOP 1 convert(numeric(18,5),ISNULL(
		CASE 
			WHEN mo.HasDocFinancialDescendants = 1 AND @Param = 0 THEN
			(
				SELECT sum(remaining) SumTotal
				FROM DocPendingPayment
				WHERE IDDocument = @IDDocument AND IDParent IS NOT NULL
				GROUP BY IDDocument, IDModule
			)
			WHEN mo.HasDocFinancialDescendants = 1 AND @Param = 1 THEN
			(
				SELECT sum(remaining) SumTotal
				FROM DocPendingPayment
				WHERE IDDocument = @IDDocument AND IDParent IS NOT NULL 
				AND DATEDIFF(day, PaymentPrevDate, GETDATE()) > 0
				GROUP BY IDDocument, IDModule
			)
			ELSE 0.0 END,0.0)) AS PaymentPendingValueTotal		
		FROM document doc
		inner join SysModule mo on mo.IDModule = doc.IDModule	
		WHERE doc.IDDocument = @IDDocument 
)
END
GO


