	from Account acc
	inner join ReadPocValuesTF_Stock(@IDModule, @IDRecord) spv on spv.IDRecord = acc.IDAccount and spv.IDRecordModule = acc.IDModule
	where acc.IDAccount = @IDRecord and acc.IDModule = @IDModule 
	--and year(spv.DateRecord) = acc.AccountYear and ((month(spv.DateRecord) = DATEPART(MONTH, acc.ClosedMovementsDate) + 1) or (month(acc.ClosedMovementsDate) = 12 and DATEPART(MONTH, spv.DateRecord) = 1))
	AND DATEPART(MONTH,DATEADD(MONTH,1, acc.ClosedMovementsDate))= month(spv.DateRecord)
