-- ----------------------------
-- procedure structure for ChatUpdateConfidentialityAndRefresh
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatUpdateConfidentialityAndRefresh]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatUpdateConfidentialityAndRefresh]
GO

CREATE PROCEDURE [dbo].[ChatUpdateConfidentialityAndRefresh]
    @IDChat INT,
    @NewConfidentialityLevel INT -- The new confidentiality level of the message
AS
BEGIN
    SET NOCOUNT ON;

    -- Table variable to capture the deleted messages details for bulk counter updates
    DECLARE @DeletedMessages TABLE (
        IDChannel UNIQUEIDENTIFIER,
        IDUser UNIQUEIDENTIFIER,
        IDResource UNIQUEIDENTIFIER,
        MessageState INT
    );

    BEGIN TRANSACTION;

    BEGIN TRY
        -- 1. UPDATE STEP: Update the confidentiality level for this message globally 
        --    (in all occurrences within SysChatUserInteraction)
        UPDATE SysChatUserInteraction
        SET MessageConfidentialityLevel = @NewConfidentialityLevel
        WHERE IDChat = @IDChat;

        -- 2. DELETE STEP: Identify and remove users who lost access.
        --    Rule to Keep: ResourceAccessType >= MessageConfidentialityLevel OR IsOnDestiny = 1
        --    Rule to Delete: ResourceAccessType < MessageConfidentialityLevel AND IsOnDestiny = 0
        
        DELETE FROM SysChatUserInteraction
        OUTPUT deleted.IDChannel, deleted.IDUser, deleted.IDResource, deleted.MessageState 
        INTO @DeletedMessages
        WHERE IDChat = @IDChat
          AND ResourceAccessType < @NewConfidentialityLevel -- Fails new confidentiality check
          AND IsOnDestiny = 0; -- Is not a direct recipient

        -- 3. COUNTER UPDATE STEP: 
        --    Since we might have deleted messages for multiple different users in multiple channels,
        --    we must aggregate the decrements by Channel + User/Resource.
        
        --    CTE to calculate how many unread messages were removed per User/Channel pair
        ;WITH CounterAdjustments AS (
            SELECT 
                IDChannel,
                IDUser,
                IDResource,
                COUNT(1) AS DecrementAmount
            FROM @DeletedMessages
            WHERE MessageState IN (1, 2) -- Only count if Unread (1) or ToBeRead (2)
            GROUP BY IDChannel, IDUser, IDResource
        )
        UPDATE R
        SET UnreadMessagesCounter = CASE 
                                        WHEN R.UnreadMessagesCounter >= CA.DecrementAmount 
                                        THEN R.UnreadMessagesCounter - CA.DecrementAmount
                                        ELSE 0 -- Safety net
                                    END
        FROM SysWorkRoomResource R
        INNER JOIN CounterAdjustments CA ON R.IDWorkRoom = CA.IDChannel
        AND (
            (R.IDLogin IS NOT NULL AND R.IDLogin = CA.IDUser)
            OR
            (R.IDResource IS NOT NULL AND R.IDResource = CA.IDResource)
        );

        COMMIT TRANSACTION;

        -- Return the total number of deleted access records for debugging
        SELECT COUNT(1) AS TotalAccessesRevoked FROM @DeletedMessages;
        
        RETURN 0;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);
        RETURN 2;
    END CATCH
END
GO


