CREATE FUNCTION [dbo].[GetPaymentLineDescendants]
(	
	-- Add the parameters for the function here
	@ID int,
	@IDModule uniqueidentifier
	
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT d.IDDocument as IDDocScr, d.IDModule as IDDocSrcModule ,dd.IDDocument, dd.doc_ref, dd.description as DocDescription, dd.RegisterStatus as DocRegisterStatus, dd.IDModule as IDDocumentModule, pld.* 
