-- ----------------------------
-- function structure for GetTimesDayReportForResource
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTimesDayReportForResource]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTimesDayReportForResource]
GO

CREATE FUNCTION [dbo].[GetTimesDayReportForResource]
(	
@IDResource uniqueidentifier,
@Month int,
@Year int
)
RETURNS @Ret Table
(
	[Day] DateTime,
	StartTime DateTime,
	EndTime DateTime,
	Absence bigint,
	Pause bigint,
	Meal bigint,
	Duration bigint,
	Description nvarchar(500),
	Hours bigint,
	Time decimal(18,5),
	Expected bigint,
	IsWorkDay int
)
AS

begin

declare @i int = 1;
declare @maxdaysmonth int = (select DATEPART(day, EOMONTH(CONVERT(datetime, concat(@Year, '-', @Month, '-01')))));
declare @MonthDays Table(
	[Day] int, [DayOfWeek] int
);

begin
	while @i <= @maxdaysmonth
	begin
		insert into @MonthDays
		select @i, (select DATEPART(DW, concat(@Year, '-', @Month, '-', RIGHT(concat('0', @i), 2))))
		set @i = @i + 1;
	end
end;

with times as(
	select * 
	from
	(
		select  t.StartDate, t.EndDate, t.ID as IDTime, l.IDLogin, t.Type, t.Duration, DATEPART(day, t.StartDate) Day, res.IDSysSchedulePlan
		from SysTimes t with (nolock)
		inner join SysLogin2SysResource r2l with (nolock) on r2l.IDResource = t.IDResource and r2l.Active = 1
		inner join SysLogin l with (nolock) on l.IDLogin = r2l.IDLogin
		inner join SysResources res with (nolock) on res.ResourceId = r2l.IDResource
		where t.IDResource = @IDResource and MONTH(t.StartDate) = @Month and MONTH(t.EndDate) = @Month 
		and YEAR(t.StartDate) = @Year and YEAR(t.EndDate) = @Year and t.TimelineType = 0
	) t

), accountConfigs as
(
	select distinct acc.IDAccount, acc.IDModule, acc.ClosedMovementsDate, acc.StartDate, acc.EndDate, 
	acc.AccountYear, acc.IDHourBankConfiguration, e.IDLanguage
	from times t with (nolock)
	inner join Entity e with (nolock) on e.IDRelatedLogin = t.IDLogin
	inner join account acc with (nolock) on acc.IDContact = e.organizationid and acc.IDContactModule = e.IDModule
	where acc.IDModule in(
		select IDModule from GetModulesRec('25c1dd8b-3766-4384-a3c1-4338d6eefcf7')
	) and acc.RegisterStatus = 0 
	--and acc.AccountYear = @Year 
	 and (acc.EndDate is null or YEAR(acc.EndDate) >= @Year)
	and (
		(acc.StartDate is null or 
			 acc.StartDate <= EOMONTH(DATEFROMPARTS(@Year, @Month, 1))
			--acc.StartDate <=DATEFROMPARTS(@Year,@Month,1)
			--(MONTH(acc.StartDate) <= @Month 
			--	--and YEAR(acc.StartDate) >= @Year
			--	)
			) 
		and 
		(acc.EndDate is null or 
			acc.EndDate >=DATEFROMPARTS(@Year,@Month,1)
			--(MONTH(acc.EndDate) >= @Month 
			--	--and YEAR(acc.EndDate) <= @Year
			--	)
			)
		)
	--and (acc.Status is null or acc.Status = 0)
), TimesTypesConfig as
(
	select acc.IDAccount, hbl.TimeType, hbl.AccountingMode 
	from SysHourBankConfigurationLine hbl with (nolock)
	inner join accountConfigs acc with (nolock) on acc.IDHourBankConfiguration = hbl.IDHourBankConfiguration
), timeMovements as
(
	select spv.*, acc.IDLanguage 
	from SysPocValue spv with (nolock)
	inner join accountConfigs acc with (nolock) on acc.IDAccount = spv.IDRecord and acc.IDModule = spv.IDRecordModule
	left join times t with (nolock) on t.IDTime = spv.IDSrcTimes
	left join TimesTypesConfig ttc with (nolock) on ttc.TimeType = spv.TimeType
	where spv.IDSrc is null and spv.MovementMode <> 3 and spv.MovementRootType = 0 and spv.MovementMode = 0
	and DATEPART(month, spv.DateRecord) = @Month
	and DATEPART(year, spv.DateRecord) = @Year 
	and Compensation = 0
), hasAccountedMovements as( 
	select distinct pp.IDPocValue
	from timeMovements pp with (nolock)
	inner join SysPocValue pc with (nolock) on pc.IDParent = pp.IDPocValue and pc.TimeType is not null 
	inner join TimesTypesConfig ttc with (nolock) on ttc.TimeType = pc.TimeType
	where ttc.AccountingMode <> 3 and pc.Compensation = 0
), timeMovementsv2 as
(
	select tm.*, case when acc.IDPocValue is not null then 1 else 0 end HasConfigMovs, 0 as IsAdjustment
	from timeMovements tm with (nolock)
	left join hasAccountedMovements acc with (nolock) on tm.IDPocValue = acc.IDPocValue
), adjustmentMovements as
(
	select distinct spv.*, acc.IDLanguage, 1 as HasConfigMovs, 1 as IsAdjustment
	from SysPocValue spv with (nolock)
	inner join accountConfigs acc with (nolock) on acc.IDAccount = spv.IDRecord and acc.IDModule = spv.IDRecordModule
	inner join DocumentLine dl with (nolock) on dl.IDRegister = spv.IDSrc and dl.IDModule = spv.IDSrcModule 
	and spv.IDRecord = dl.dim21 and spv.IDRecordModule = dl.dim21Module
	where spv.IDSrc is not null and spv.MovementMode <> 3 and spv.MovementRootType = 0 and spv.MovementMode = 0 
	and Compensation = 0 and DATEPART(month, spv.DateRecord) = @Month and DATEPART(year, spv.DateRecord) = @Year 
), movements as(
	select * from timeMovementsv2
	union all
	select * from adjustmentMovements
), childMovements as 
(
	select m.IDPocValue, 
		case 
		when m.HasConfigMovs = 1 and ISNULL(pc.TimeType,0) <> 6 then dbo.TimeToTicks(SUBSTRING(pc.RealDurationDescription,0,3), SUBSTRING(pc.RealDurationDescription,4,2),  SUBSTRING(pc.RealDurationDescription,7,2))
		when m.HasConfigMovs = 1 and ISNULL(pc.TimeType,0) = 6 then dbo.TimeToTicks(SUBSTRING(pc.CalculatedDurationDescription,0,3), SUBSTRING(pc.CalculatedDurationDescription,4,2),  SUBSTRING(pc.CalculatedDurationDescription,7,2))
		else 0 end as CreditDuration
	from movements m
	left join SysPocValue pc on pc.IDParent = m.IDPocValue
	where pc.TotalCredit <> 0
), childMovementsv2 as
(
	select c.IDPocValue, SUM(CreditDuration) CreditDuration
	from childMovements c
	inner join movements m on m.IDPocValue = c.IDPocValue
	group by c.IDPocValue
), timeMovementsExtended as(
	select m.IDPocValue, case when m.IsAdjustment = 1 then (case when m.HasConfigMovs = 1 then dbo.TimeToTicks(SUBSTRING(m.RealDurationDescription,0,3), SUBSTRING(m.RealDurationDescription,4,2),  SUBSTRING(m.RealDurationDescription,7,2)) else 0 end) else c.CreditDuration end as CreditDuration
	from movements m
	left join childMovementsv2 c on c.IDPocValue = m.IDPocValue
), finalTimeMovements as(
	select tm.*, tmx.CreditDuration, tm.QtyActualStock * 3600 * 10000000 ExtraHours, tm.TotalDebit * 3600 * 10000000 ExpectedHours
	from movements tm
	left join timeMovementsExtended tmx on tm.IDPocValue = tmx.IDPocValue
), timeTypesDescription as(
	select distinct day(p.DateRecord) Day, ttc.TimeType, 
	case 
		when tv.IDTranslationValue is null then sfv.Description
		when sfv.IDTranslationTarget = 1 then tv.Acronym
		when sfv.IDTranslationTarget = 2 then tv.ShortName
		when sfv.IDTranslationTarget = 3 then tv.Name
		when sfv.IDTranslationTarget = 4 then tv.Description
		when sfv.IDTranslationTarget = 5 then tv.States
		else ''
	end Code, IsAdjustment
	from movements p with (nolock)
	inner join SysPocValue pc with (nolock) on pc.IDParent = p.IDPocValue 
	inner join TimesTypesConfig ttc with (nolock) on ttc.TimeType = pc.TimeType
	inner join SysTimeType sfv with (nolock) on sfv.CodeInt = ttc.TimeType 
	left join SysTranslationValue tv with (nolock) on tv.IDTranslation = sfv.IDTranslation and tv.IDLanguage = p.IDLanguage 
	where (ttc.AccountingMode = 3 or ttc.TimeType = 11 ) and ttc.TimeType not in(15,16) and pc.Compensation = 0
	union all
	select distinct day(p.DateRecord) Day, p.IDPocValue, concat('Ajuste ', p.description) as Code, IsAdjustment
	from movements p
	where IDSrc is not null
), finalTimeTypesDescription as(
	SELECT Main.Day, IsAdjustment,LEFT(Main.Codes,Len(Main.Codes)-1) As "Codes"
		FROM
			(
				SELECT DISTINCT ST2.Day, IsAdjustment , 
					(
						SELECT  ST1.Code + ',' AS [text()]
						FROM timeTypesDescription ST1
						WHERE ST1.Day = ST2.Day and ST1.IsAdjustment = ST2.IsAdjustment
						ORDER BY ST1.Day, ST1.IsAdjustment
						FOR XML PATH ('')
					) [Codes]
				FROM timeTypesDescription ST2
			) [Main]
)
, holidays as(
	select distinct md.Day, ho.Name
	from times b  with (nolock)
	inner join SysResource2SysHolidaysPlan l2hp with (nolock) on l2hp.IDResource = @IDResource
	inner join SysHolidaysYear hy with (nolock) on hy.IDSysHolidaysPlan = l2hp.IDSysHolidaysPlan
	inner join SysHoliday ho with (nolock) on ho.IDHolidaysYear = hy.IDHolidaysYear and ho.Month = @Month and hy.Year = @Year
	inner join @MonthDays md on ho.Day = md.Day
), timesAbsenceDay as
(
	select t.Day , sum(Duration) Duration
	from times t with (nolock)
	where t.Type in(
		select TimeType
		from TimesTypesConfig ttc with (nolock)
		inner join SysTimeType stt on stt.codeint = ttc.TimeType
		where AccountingMode = 3 and stt.Origin in(1,3)
	)
	group by Day
), timesPause as
(
	select t.Day , sum(Duration) Duration
	from times t with (nolock)
	where t.Type in(
		select TimeType
		from TimesTypesConfig with (nolock)
		where AccountingMode = 1  
	)  
	group by Day
), timesLunch as
(
	select t.Day , sum(Duration) Duration
	from times t with (nolock)
	where t.Type = 15
	group by Day
), timesAutomaticAbsenceDay as (
	select t.Day , sum(Duration) Duration
	from times t with (nolock)
	where t.Type = 16
	group by Day
), workDays as
(
	select day, max(IsWorkDay) IsWorkDay
	from
	(
		select distinct m.day, case when ho.Day is null and CHARINDEX(convert(nvarchar(1),DayOfWeek), WorkWeek) > 0 then 1 else 0 end IsWorkDay
	from 
		(select top 1 * from times with (nolock)) t
		left join @MonthDays m on 1 = 1 
		inner join SysSchedulePlanLine spl with (nolock) on spl.IDSysSchedulePlan = t.IDSysSchedulePlan
		and CONVERT(datetime, CONCAT(@Year, '-', @Month, '-', m.Day) ,120) >= isnull(spl.StartDate, (select cast('1753-1-1' as datetime))) 
		and  CONVERT(datetime, CONCAT(@Year, '-', @Month, '-', m.Day) ,120) <= isnull(spl.EndDate, (select cast('9999-12-30' as datetime))) 
		inner join sysscheduleline sl with (nolock) on spl.IDSchedule = sl.IDSchedule
		left join holidays ho on ho.Day = m.Day
	) t
	group by Day
), finalColumns as
(
	select CONVERT(datetime, concat(@year, '-', @Month, '-', m.Day)) Day, 
	tm.StartTime as StartTime, tm.EndTime as EndTime, 
	isnull(tud.Duration, 0) Absence, 
	isnull(tp.Duration, 0) Pause, 
	isnull(tl.Duration, 0) Meal, 
	isnull(tm.CreditDuration,0)as NumberHours, 
	case 
		when ho.Day is not null then ho.Name 
		when tad.Duration is not null and tad.Duration > 0 and tm.ExpectedHours is not null and tm.ExpectedHours > 0 and tad.Duration >= 0.5 * tm.ExpectedHours  then 'Falta'
		when ttd.Day is not null then ttd.Codes 
		else '' end Description, 
	isnull(tm.extraHours,0) Hours,
	isnull(tm.QtyActualStock, 0) Time,
	isnull(tm.ExpectedHours, 0) Expected,
	isnull(wo.IsWorkDay,0) IsWorkDay,
	tm.IsAdjustment
	from @MonthDays m
	left join finalTimeMovements tm with (nolock) on day(tm.DateRecord) = m.Day 
	left join finalTimeTypesDescription ttd with (nolock) on m.Day = ttd.Day and tm.IsAdjustment = ttd.IsAdjustment
	left join holidays ho with (nolock) on ho.Day = m.Day
	left join timesAbsenceDay tud with (nolock) on tud.Day = m.Day
	left join timesPause tp with (nolock) on tp.Day = m.Day
	left join timesLunch tl with (nolock) on tl.Day = m.Day
	left join workDays wo with (nolock) on wo.Day = m.Day
	left join timesAutomaticAbsenceDay tad with (nolock) on tad.Day = m.Day 
)
insert into @Ret
select Day, min(StartTime) StartTime, MAX(EndTime) EndTime, Absence, Pause, Meal, sum(NumberHours) NumberHours, Description, sum(Hours) Hours, sum(Time) Time, sum(Expected) Expected, IsWorkDay
from finalColumns with (nolock)
group by Day, Absence, Pause, Meal, Description, IsWorkDay
return
end
GO


-- ----------------------------
-- procedure structure for ChatMarkAllAsRead
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatMarkAllAsRead]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatMarkAllAsRead]
GO

CREATE PROCEDURE [dbo].[ChatMarkAllAsRead]
    @IDUser UNIQUEIDENTIFIER = NULL,
    @IDResource UNIQUEIDENTIFIER = NULL,
    @IDChannel UNIQUEIDENTIFIER,
    @IncludeToBeRead BIT -- 0 (False) = Only 'Unread' (1); 1 (True) = 'Unread' (1) AND 'ToBeRead' (2)
AS
BEGIN
    SET NOCOUNT ON;

    -- Table variable to capture the IDs of updated rows
    DECLARE @UpdatedMessages TABLE (
        IDChat INT
    );

    DECLARE @DecrementAmount INT = 0;

    BEGIN TRANSACTION;

    BEGIN TRY
        -- 1. UPDATE STEP: Mark messages as Read (3) and capture the IDs
        --    Using OUTPUT inserted.IDChat to grab the IDs of the rows processed.
        
        UPDATE SysChatUserInteraction
        SET MessageState = 3, -- Set to Read
            DateState = GETUTCDATE()
        OUTPUT inserted.IDChat INTO @UpdatedMessages
        WHERE IDChannel = @IDChannel
          AND (IDUser = @IDUser OR IDResource = @IDResource)
          AND (
                MessageState = 1 -- Always include Unread
                OR 
                (@IncludeToBeRead = 1 AND MessageState = 2) -- If True, also include ToBeRead
              );

        -- 2. COUNTER CALCULATION
        SELECT @DecrementAmount = COUNT(1) FROM @UpdatedMessages;

        -- 3. COUNTER UPDATE STEP
        IF @DecrementAmount > 0
        BEGIN
            UPDATE R
            SET UnreadMessagesCounter = CASE 
                                            WHEN R.UnreadMessagesCounter >= @DecrementAmount 
                                            THEN R.UnreadMessagesCounter - @DecrementAmount
                                            ELSE 0 
                                        END
            FROM SysWorkRoomResource R
            WHERE R.IDWorkRoom = @IDChannel
              AND (R.IDResource = @IDResource OR R.IDLogin = @IDUser);
        END
        ELSE
        BEGIN
            UPDATE R
            SET UnreadMessagesCounter = 0
            FROM SysWorkRoomResource R
            WHERE R.IDWorkRoom = @IDChannel
              AND (R.IDResource = @IDResource OR R.IDLogin = @IDUser);
        END

        COMMIT TRANSACTION;

        -- 4. RETURN STEP: Return the IDs to the application
        SELECT IDChat FROM @UpdatedMessages;
        
        RETURN 0;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@ErrorMessage, 16, 1);
        RETURN 2;
    END CATCH
END
GO


-- ----------------------------
-- function structure for AllChildrenOfCatalogItem
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[AllChildrenOfCatalogItem]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[AllChildrenOfCatalogItem]
GO

CREATE FUNCTION [dbo].[AllChildrenOfCatalogItem]
(
	-- Add the parameters for the function here
	@IDRoot int
)
RETURNS 
@ret TABLE 
(
	-- Add the column definitions for the TABLE variable here
	IDCatalogItem int not null
)
AS
BEGIN

	with tblChild as (
	select * -- idrecord, idrecordmodule
	from CatalogItem
	where idparentcatalogitem = @IDRoot
	union all

	select ci.* -- idrecord, idrecordmodule
	from CatalogItem ci inner join tblChild c on ci.idparentcatalogitem = c.idcatalogitem

	)

	insert into @ret(IDCatalogItem)
	select IDCatalogItem from tblchild;

	return
END
GO


-- ----------------------------
-- function structure for str2uniq
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[str2uniq]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[str2uniq]
GO

CREATE FUNCTION [dbo].[str2uniq](@s varchar(100)) returns uniqueidentifier as begin
    -- just in case it came in with 0x prefix or dashes...
    set @s = replace(replace(@s,'0x',''),'-','')
    -- inject dashes in the right places
    set @s = stuff(stuff(stuff(stuff(@s,21,0,'-'),17,0,'-'),13,0,'-'),9,0,'-')
    return TRY_CONVERT(uniqueidentifier,@s )
end
GO


-- ----------------------------
-- function structure for GetResourceSharedResources
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourceSharedResources]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourceSharedResources]
GO

CREATE FUNCTION [dbo].[GetResourceSharedResources] 
(	
	-- Add the parameters for the function here
	@resourceid uniqueidentifier
	
)
RETURNS @T TABLE(IDResource uniqueidentifier)

AS
BEGIN
	declare @AccessSelf int
	declare @AccessParent int
	declare @AccessBrothers int
	declare @AccessSubordinates int

	select @AccessParent =AccessParent, @AccessBrothers=AccessBrothers, @AccessSubordinates=AccessSubordinates 
	from SysResourceRelationship where IDResource=@resourceid

	insert into @T(IDResource)
	select IDResource from SysResourceRelationship  where IDResource=@resourceid
	union all
		 select idresource 
		 from GetResourceDescendants(@resourceid) 
		 where @AccessSubordinates > 0 and idresource <> @resourceid
	 
	union all
		select resourceid 
		from getResourceTeamResource(@resourceid) 
		where @AccessParent > 0 and resourceid <> @resourceid
	union all
		select resourceid 
		from getResourceTeamSiblings (@resourceid) 
		where @AccessBrothers > 0 and resourceid <> @resourceid

	
	
	RETURN 
END
GO


-- ----------------------------
-- function structure for SS_GetEDMShapeName
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetEDMShapeName]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetEDMShapeName]
GO

CREATE FUNCTION [dbo].[SS_GetEDMShapeName]
(
	@ObjectID uniqueidentifier
)
RETURNS nvarchar(50)
AS
BEGIN
	-- Declare the return variable here
	declare @res nvarchar(50);
	declare @shortname nvarchar(50);
	declare @PArtOF uniqueidentifier;
	declare @Mould uniqueidentifier;

	select @Mould=mouldid,@PArtOF=parentid,@shortname=shortname from ss_object where id=@objectid
	set @res=@shortname;

	--SE tiver pai
	if @PArtOF is not null and (@partof<>@Mould)
	begin
		select @shortname=shortname from ss_object where id=@PArtOF
		set @res=@shortname+'-E'+@res;
	end

--Se tiver molde
	if @Mould is not null
	begin
		select @shortname=shortname from ss_object where id=@mould
		set @res=@shortname+'-'+@res;
	end


	RETURN @res
END
GO


