IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetBusinessAreaRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetBusinessAreaRec]
GO

CREATE FUNCTION [dbo].[GetBusinessAreaRec]
(	
	@IDBusinessArea int
)
RETURNS TABLE 
AS
RETURN 
(
	with BusinessAreaRec as (
		select IDBusinessArea, IDParent 
		from BusinessArea 
		where IDBusinessArea = @IDBusinessArea
		union all
		select b.IDBusinessArea, b.IDParent
		from BusinessArea b inner join BusinessArea p on b.IDParent = p.IDBusinessArea
	)
	select b.*
	from BusinessArea b
		inner join
		BusinessAreaRec bcr on b.IDBusinessArea = bcr.IDBusinessArea
);
GO


