-- ----------------------------
-- procedure structure for SS_InsertSetup
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertSetup]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertSetup]
GO

CREATE PROCEDURE [dbo].[SS_InsertSetup]
	-- Add the parameters for the stored procedure here
	@Kind int,
	@Name nvarchar(50),
	@InUse bit,
	@Overwrite bit,
	@IDSetupTemplate int,
	@LoginID int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	declare @SetupID int;
	declare @LocalPath nvarchar(200);
	set @LocalPath= (Select [SetupPathDefault] from ss_config);
	SET NOCOUNT ON;
	set @SetupID=(select top 1 id from SS_Setup where name like @Name)
	if @SetupID is null
	BEGIN
		insert into SS_Setup(Kind,Name, InUse, LocalPath,IDSetupTemplate,DateCreated,DateModified,IDLoginCreated,IDLoginModified,IDMachine,State) 
		values (@Kind, @Name,@InUse, @LocalPath,@IDSetupTemplate,getdate(),getdate(),@LoginID,@LoginID,(select  idmachine from SS_SetupTemplate where id=@IDSetupTemplate),0);
		set @SetupID= scope_identity();
		update ss_setup set LocalPath=@LocalPath+Name+'.smstp';
		return @SetupID
	END
	else
		if @Overwrite=1
			return @SetupID
		else
			return -1
END
GO


-- ----------------------------
-- function structure for CamelCase
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CamelCase]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[CamelCase]
GO

CREATE FUNCTION [dbo].[CamelCase](@Str varchar(8000))
RETURNS varchar(8000) As
Begin
	Declare @Result varchar(2000)
	SET @Str = LOWER(@Str) + ' '
	SET @Result = ''

	While 1=1
	Begin
	        IF PATINDEX('% %',@Str) = 0 BREAK
		SET @Result = @Result+UPPER(Left(@Str,1))+SubString(@Str,2,CharIndex(' ',@Str)-1)
		SET @Str = SubString(@Str,CharIndex(' ',@Str)+1,Len(@Str))
	End
	SET @Result = Left(@Result,Len(@Result))
	Return @Result
End
GO


-- ----------------------------
-- procedure structure for sp_upgraddiagrams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_upgraddiagrams]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_upgraddiagrams]
GO

CREATE PROCEDURE [dbo].[sp_upgraddiagrams]
	AS
	BEGIN
		IF OBJECT_ID(N'dbo.sysdiagrams') IS NOT NULL
			return 0;
	
		CREATE TABLE dbo.sysdiagrams
		(
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
	
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
			(
				principal_id,
				name
			)
		);


		/* Add this if we need to have some form of extended properties for diagrams */
		/*
		IF OBJECT_ID(N'dbo.sysdiagram_properties') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
			(
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
			)
		END
		*/

		IF OBJECT_ID(N'dbo.dtproperties') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
			(
				[name],
				[principal_id],
				[version],
				[definition]
			)
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N'dbo'),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = 'DtgSchemaGUID' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = 'DtgSchemaDATA' and dgdef.[objectid] = dgnm.[objectid]
				
			where dgnm.[property] = 'DtgSchemaNAME' and dggd.[uvalue] like N'_EA3E6268-D998-11CE-9454-00AA00A3F36E_' 
			return 2;
		end
		return 1;
	END
GO


-- ----------------------------
-- procedure structure for CopyTeamOptionsToChildRoles
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CopyTeamOptionsToChildRoles]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CopyTeamOptionsToChildRoles]
GO

CREATE PROCEDURE [dbo].[CopyTeamOptionsToChildRoles]
	-- Add the parameters for the stored procedure here
	@IDRoleTeam int,
	@TeamSharingData int,
	@TeamSharingMenu int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE CursorChildTeamRoles CURSOR FOR 
				SELECT  
				r.IDRole
				from SysRole2SysRole r2r
				INNER JOIN SysRole r ON r.IDRole=r2r.IDRoleChild 
				where r.TeamSharingDefinition=1 AND r2r.IDRoleParent=@IDRoleTeam AND r.Kind is null
	OPEN CursorChildTeamRoles
		DECLARE @IDChildRole int =0;
		FETCH NEXT FROM CursorChildTeamRoles INTO @IDChildRole
		WHILE @@FETCH_STATUS = 0
			BEGIN
			UPDATE SysRole SET TeamSharingData= @TeamSharingData,TeamSharingMenu=@TeamSharingMenu
			FETCH NEXT FROM CursorChildTeamRoles INTO @IDChildRole
			END
    CLOSE CursorChildTeamRoles
	DEALLOCATE CursorChildTeamRoles
END
GO


