-- ----------------------------
-- procedure structure for CreateSupplierAccount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreateSupplierAccount]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreateSupplierAccount]
GO

CREATE PROCEDURE [dbo].[CreateSupplierAccount]	
	@NewIDRecord int ,
	@NewIDModule uniqueidentifier,
	@Fornecedor int null,
	@dbmask int null = 1,
	@idmodule uniqueidentifier = '943F4A40-6E56-4648-853C-F7A3B2810581',
	@startMask nvarchar(50) = 'ACC_IS_SUPP_'
AS
BEGIN

	if @Fornecedor = 1
	begin
		declare @CurrentCounter int = (select CurrentCounter + 1 from SysModule where IDModule = @IDModule);

		declare @Mask nvarchar(50) = concat
		(
			@startMask,
			right(concat('000000', @CurrentCounter ), 6)
		);

		DECLARE @tmp TABLE ( 
			IDAccount INT NOT NULL 
		);

		INSERT INTO Account  (
		[Name], [IDCoin],[IDContact], [dbmask], [AccountType], [IsTemplate],  [ModifiedTime]
		, [CreatedTime], [record_no], [account_no], [account_no_counter], [RegisterStatus]
		, [RegisterSysStatus], [IDModule], [IDContactModule], [IDUserCreation]
		, [IDUser], [IDResourceCreation], [IDResource], [IDResourceAssign], [AccG01], [AccG02], [IDCountry]
		, [AccountMovementType], [account_no_IsTemp], [IDLanguage],[IDTemplateSource], [IDTemplateSourceModule]
		, [TeamMask01], [TeamMask02], [TemplateDefaultMFVCreate], [Dirty], [IsRootAccount]) OUTPUT inserted.[IDAccount] INTO @tmp(IDAccount)
		SELECT concat(e.accountname, '_Supplier') AS [Name], 1, e.organizationid AS [IDContact], @dbmask AS [dbmask], 0 AS [AccountType], 0 AS [IsTemplate], 
		GETDATE() AS [ModifiedTime], GETDATE() AS [CreatedTime], 
		e.organization_no AS [record_no], 
		@Mask, 
		@CurrentCounter
		, 0 AS [RegisterStatus],  0 AS [RegisterSysStatus], @IDModule AS [IDModule], 
		e.IDModule AS [IDContactModule],  e.IDUserCreation AS [IDUserCreation], 
		e.[IDUser] AS [IDUser], e.[IDResourceCreation] AS [IDResourceCreation], 
		e.[IDResource] AS [IDResource], e.[IDResourceAssign] AS [IDResourceAssign], 
		-1 AS [AccG01], -1 AS [AccG02], e.IDCountry, 0 AS [AccountMovementType],  0 AS [account_no_IsTemp], e.IDLanguage,  e.organizationid AS [IDTemplateSource], 
		e.IDModule AS [IDTemplateSourceModule],  -1 AS [TeamMask01], -1 AS [TeamMask02], 
		1 AS [TemplateDefaultMFVCreate], 0 AS [Dirty], 0 as [IsRootAccount]
		from entity e 
		where organizationid = @NewIDRecord and IDModule = @NewIDModule

		declare @CreatedIDAccount int = (select top 1 IDAccount from @tmp);

		update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @IDModule;

		exec UpdateAccountBalances @CreatedIDAccount, @IDModule;
		exec CreateAccountRootMovements @CreatedIDAccount, @IDModule;
	end

END
GO


-- ----------------------------
-- procedure structure for SS_NewNonConformity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_NewNonConformity]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_NewNonConformity]
GO

CREATE PROCEDURE [dbo].[SS_NewNonConformity]
	@ObjectID uniqueidentifier,
	@OperationID int,
	@NonConformityID int,
	@Notes nvarchar(500),
	@LoginID int
AS
BEGIN
	DECLARE @IDWorkFlowItem int;

	-- Add the T-SQL statements to compute the return value here
	set @IDWorkFlowItem=(Select top 1 IDWorkFlowItem from SysWorkFlowItem where idregisto=@ObjectID and idkind=@OperationID)

	insert into [dbo].[SysWorkflowItemNonConformity] ( IDNonConformity, Notes, IDWorkFlowItem) values (@NonConformityID,@Notes,@IDWorkFlowItem);
	
	--Adicionar nas notas 
	declare @FinalNote nvarchar(Max);
	set @FinalNote = (Select isnull(name,'') from [dbo].[SS_NonConformity] where id=@NonConformityID)
	set @FinalNote=@FinalNote+ ' - '+@Notes;

	Insert into SS_ObjectNotes (IDObject, IDLogin, Note, IDOperation, ReadOnly, Data, UserMsg, Importance)
	values (@ObjectID,@LoginID,@FinalNote,@OperationID,1,getdate(),0,2)


END
GO


