	DROP FUNCTION [dbo].[GetModulesAscRec]
GO

CREATE FUNCTION [dbo].[GetModulesAscRec]
(	
	@IDModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	with GetModulesRecc as (
		select IDModule, IDParent
		from SysModule
		where IDModule = @IDModule
		union all
		select m.IDModule, m.IDParent
		from SysModule m inner join GetModulesRecc p on m.idmodule = p.idparent
	)
	select m.*
	from SysModule m
		inner join
		GetModulesRecc rec on m.IDModule = rec.IDModule
)
GO


