-- ----------------------------
-- function structure for GetTotalTimesDurationsActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTotalTimesDurationsActivity]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTotalTimesDurationsActivity]
GO

CREATE FUNCTION [dbo].[GetTotalTimesDurationsActivity]
(	
	@IDActivity int
)
RETURNS bigint 
AS
BEGIN
	---FOR NOW IT ONLY TAKES INTO ACCOUNT TIMES DIRECTLY RELATED TO THE ACTIVITY INSTEAD OF THE TIMES RELATED TO THE TASK

	DECLARE @duration bigint
	
	set @duration=	isnull((SELECT  Sum((TRRA.TimeWeight /100)* t.Duration ) 
		from dbo.SysTimes AS t 
		inner join dbo.SysTimesResourceRoleTask as TRRA ON t.ID = TRRA.IDSysTime
		inner join dbo.SysActivityResourceRoleActivity AS ARRA on TRRA.IDActivityResourceRoleActivity = ARRA.IDActivityResourceRoleActivity
		where (ARRA.IDActivity=@IDActivity and (TimeType=1 OR TimeType=4))),0)
		
		--OLD
		--set @duration=	isnull((SELECT  Sum((TRRA.TimeWeight /100)* t.Duration ) 
		--FROM  dbo.SysActivityResourceRoleActivity AS ARRA  WITH (NOLOCK)				
		--INNER JOIN dbo.SysTask AS task WITH(NOLOCK) ON ARRA.IDActivityResourceRoleActivity = task.IDActivityResourceRoleActivity
		--inner join dbo.SysTaskResourceRole as TRR WITH(NOLOCK) ON task.IDTask = TRR.IDTask
		--INNER JOIN dbo.SysTimesResourceRoleTask  AS TRRA  WITH (NOLOCK) ON TRR.IDTaskResourceRole = TRRA.IDTaskResourceRole
		--INNER JOIN dbo.SysTimes as  t WITH (NOLOCK) ON t.ID = TRRA.IDSysTime
		--where (ARRA.IDActivity=@IDActivity and (TimeType=1 OR TimeType=4))),0) 

	return @duration

end
GO


-- ----------------------------
-- procedure structure for sp_helpdiagramdefinition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_helpdiagramdefinition]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_helpdiagramdefinition]
GO

CREATE PROCEDURE [dbo].[sp_helpdiagramdefinition]
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END
GO


-- ----------------------------
-- procedure structure for SS_OpenOperation
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_OpenOperation]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_OpenOperation]
GO

CREATE PROCEDURE [dbo].[SS_OpenOperation]
	-- Add the parameters for the stored procedure here
	@ObjectID int,
	@IDKind int,
    @LoginID int=null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @IDWorkflowItem int;
	declare @OpCode nvarchar(50);
	declare @IDWorkflowItemTemplate int;
	--Procurar Workflowitem a fechar
	Select @IDWorkflowItem =IDWorkflowItem,@IDWorkflowItemTemplate=template,@OpCode=code from sysworkflowitem where idregisto=@objectid and idkind=@IDKind;

	declare @IDWorkflow int;
	declare @IDWorkflowTemplate int;
	--Procurar IDWorkflow do item
	Select @IDWorkflow = wf.idworkflow, @IDWorkflowTemplate=wf.WorkflowClone from sysworkflowitem wfi inner join sysworkflow wf on wf.IDWorkflow=wfi.IDWorkflow where idregisto=@objectid and idkind=@IDKind;

	--Procurar o ID da sua condição de fecho
	declare @IDClosingCondition int;
	set @IDClosingCondition = (Select IDWorkflowConditions from SysWorkflowConditions where idworkflowitem=@IDWorkflowItemTemplate and targetstate=2);


	--Procurar as variaveis que definem a condiçao de fim deste item e provocar a sua mudança para o mecanismo fechar a operaçao normalmente
	declare @IDWorkflowVar int;
	declare @TargetValue int;
	DECLARE lc2 CURSOR LOCAL
	FOR select v.SysKind,value from SysWorkflowConditionsStep s inner join SysWorkflowVars  v on v.IDWorkflowVars=s.IDWorkflowVar where idcondition=@IDClosingCondition;
	OPEN lc2;
	FETCH NEXT FROM lc2
		INTO  @IDWorkflowVar,@TargetValue;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Fechar Vars
		EXEC dbo.ChangeVarFromObject @ObjectID,@IDWorkflowVar,@TargetValue,null,''

		FETCH NEXT FROM lc2
		INTO @IDWorkflowVar,@TargetValue;
	END;
		
	CLOSE lc2;
	DEALLOCATE lc2;


	set @OpCode='Operação '+@OpCode+' reaberta.' 
	EXEC SS_AddObjectNote	@ObjectID ,	@IDKind ,	1 ,	@LoginID	,@OpCode	
END
GO


-- ----------------------------
-- procedure structure for UpdateFUPActivityRedundantItems
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateFUPActivityRedundantItems]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateFUPActivityRedundantItems]
GO

CREATE PROCEDURE [dbo].[UpdateFUPActivityRedundantItems]
	@IDRecord int,
	@IDModule uniqueidentifier,
	@RegisterStatusChanged int
AS
BEGIN
	
	SET NOCOUNT ON;
	
	WITH RelevantFups as (
		select distinct relatedRecord as IDFUP, relatedRecordModule as IDFUPModule
		from Activity2Record a2r
		where a2r.relatedRecordModule in(
			select IDModule from GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944')
		) and 
		(
			(a2r.relatedRecord = @IDRecord and a2r.relatedRecordModule = @IDModule) or 
			(a2r.IDActivity = @IDRecord and a2r.IDActivityModule = @IDModule)
		)
	), activityFollowUpItems as(
		select a2r.relatedRecord, a2r.relatedRecordModule,  a.IDActivity, a.IDModule, a.subject ,a.activityCode, a.startDate, a.status
		from Activity a
		inner join Activity2Record a2r on a2r.IDActivity = a.IDActivity and a2r.IDActivityModule = a.IDModule
		inner join RelevantFups fups on fups.IDFUP = a2r.relatedRecord and fups.IDFUPModule = a2r.relatedRecordModule
		where a2r.relatedRecordModule in(
			select IDModule from GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944')
		) 
		and a.status in(2726, 2724)
	), maxDateCompleted as(
		select relatedRecord, relatedRecordModule, MAX(startDate) MaxDateCompleted
		from activityFollowUpItems
		where status = 2726
		group by relatedRecord, relatedRecordModule
	),maxDateCompletedAux as(
		select afup.relatedRecord, afup.relatedRecordModule, MAX(IDActivity) IDActivity
		from activityFollowUpItems afup
		inner join maxDateCompleted mca on afup.relatedRecord = mca.relatedRecord and afup.relatedRecordModule = mca.relatedRecordModule and afup.startDate = mca.MaxDateCompleted
		where status = 2726
		group by afup.relatedRecord, afup.relatedRecordModule
	),minDatePlanned as(
		select relatedRecord, relatedRecordModule, min(startDate) MinDatePlanned
		from activityFollowUpItems
		where status = 2724
		group by relatedRecord, relatedRecordModule
	), minDatePlannedAux as (
		select afup.relatedRecord, afup.relatedRecordModule, MAX(IDActivity) IDActivity
		from activityFollowUpItems afup
		inner join minDatePlanned mpa on afup.relatedRecord = mpa.relatedRecord and afup.relatedRecordModule = mpa.relatedRecordModule and afup.startDate = mpa.MinDatePlanned
		where status = 2724
		group by afup.relatedRecord, afup.relatedRecordModule
	), maxCompletedActivities as(
		select afup.*
		from activityFollowUpItems afup
		inner join maxDateCompletedAux mca on afup.relatedRecord = mca.relatedRecord and afup.relatedRecordModule = mca.relatedRecordModule and afup.IDActivity = mca.IDActivity
	), minPlannedActivities as(
		select afup.*
		from activityFollowUpItems afup
		inner join minDatePlannedAux mpa on afup.relatedRecord = mpa.relatedRecord and afup.relatedRecordModule = mpa.relatedRecordModule and afup.IDActivity = mpa.IDActivity
	),
	followUpItems as(
		select t.*, fup.RegisterStatus, fup.Status 
		from 
		(
			select distinct relatedRecord, relatedRecordModule
			from activityFollowUpItems
		) t
		inner join FollowUpItem fup on t.relatedRecord = fup.IDFollowUpItem and t.relatedRecordModule = fup.IDModule
	), finalValues as (
		select t.*, 
		case 
			when RegisterStatus not in(1,4) and DaysUntilNextPlanned > 5 and (Status not in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442) or @RegisterStatusChanged = 1) then 0
			when RegisterStatus not in(1,4) and DaysUntilNextPlanned <= 5 and DaysUntilNextPlanned >= 0 and (Status not in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442) or @RegisterStatusChanged = 1) then 1
			when RegisterStatus not in(1,4) and  DaysUntilNextPlanned < 0 and DaysUntilNextPlanned >= -5 and (Status not in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442) or @RegisterStatusChanged = 1) then 2
			when RegisterStatus not in(1,4) and DaysUntilNextPlanned <- 5 and (Status not in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442)  or @RegisterStatusChanged = 1) then 3
			when (RegisterStatus not in(1,4) and NextIDActivity is null) and (Status not in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442)  or @RegisterStatusChanged = 1) then 4
		else null end DaysUntilNextPlannedStatus,
		case when @RegisterStatusChanged = 0 then t.Status 
		else
			case 
				when t.IsTicket = 1 and t.RegisterStatus = 1 and t.Status not in(2578,2582) then 2577
				when t.IsTicket = 1 and t.RegisterStatus = 4 and t.Status not in(2578,2577) then 2582
				when t.IsOpportunity = 1 and t.RegisterStatus = 1 and t.Status not in(2428,2124) then 2421
				when t.IsOpportunity = 1 and t.RegisterStatus = 4 and t.Status not in(2421,2124) then 2428
				when t.IsProject = 1 and t.RegisterStatus = 1 and t.Status not in(2605) then 2604
				when t.IsProject = 1 and t.RegisterStatus = 4 and t.Status not in(2604) then 2605
				when t.IsEvent = 1 and t.RegisterStatus = 1 and t.Status not in(2703) then 2704
				when t.IsEvent = 1 and t.RegisterStatus = 4 and t.Status not in(2704) then 2703
				when t.IsSprint = 1 and t.RegisterStatus = 1 and t.Status not in(9443) then 9442
				when t.IsSprint = 1 and t.RegisterStatus = 4 and t.Status not in(9442) then 9443
				else t.Status
			end
		end NewStatus	
		from
		(
			select fup.relatedRecord as IDFUP, fup.relatedRecordModule as IDFUPModule, fup.RegisterStatus,
			mca.IDActivity as PreviousIDActivity, mca.IDModule as PreviousIDActivityModule, case when mca.IDActivity IS null then null else CONCAT(mca.activityCode, ' - ', left(mca.subject,50)) end PreviousActivityLabel, mca.startDate as PreviousActivityDate,
			mpa.IDActivity as NextIDActivity, mpa.IDModule as NextIDActivityModule, case when mpa.IDActivity IS null then null else CONCAT(mpa.activityCode, ' - ', left(mpa.subject,50)) end  NextActivityLabel, mpa.startDate as NextActivityDate,
			case when fup.RegisterStatus in(1,4) or (fup.Status in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442) and @RegisterStatusChanged = 0) then null else DATEDIFF(day, mca.startDate, GETDATE()) end as DaysSinceLastCompleted, 
			case when  fup.RegisterStatus in(1,4) or (fup.Status in(2421,2422,2427,2428,2124,2603,2604,2605,2576,2582,2578,2703,2704,9443,9442) and @RegisterStatusChanged = 0) then null else DATEDIFF(day, GETDATE(), mpa.startDate) end as DaysUntilNextPlanned,
			fup.Status,
			case when fup.relatedRecordModule in(
				select idmodule from getmodulesRec('CB18AB15-5DD7-4CFD-8C43-71FE8582F377')
			) then 1 else 0
			end IsTicket,
			case when fup.relatedRecordModule in(
				select idmodule from getmodulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1')
			) then 1 else 0
			end IsOpportunity,
			case when fup.relatedRecordModule in(
				select idmodule from getmodulesRec('47DD4FB6-3ECF-4EF8-ACAE-196155FE4F55')
			) then 1 else 0
			end IsProject,
			case when fup.relatedRecordModule in(
				select idmodule from getmodulesRec('F1BD0624-3A46-4B35-9EE0-A13D82558ECA')
				union all
				select idmodule from getmodulesRec('5BA94EA7-9CDC-4E3E-AE16-5C176FA214C1')
			) then 1 else 0
			end IsEvent,
			case when fup.relatedRecordModule in(
				select idmodule from getmodulesRec('75AEE07B-0CD5-45EE-AC1C-F2B6A3D3B005')
			) then 1
			else 0
			end IsSprint
			from followUpItems fup
			left join maxCompletedActivities mca on mca.relatedRecord = fup.relatedRecord and mca.relatedRecordModule = fup.relatedRecordModule
			left join minPlannedActivities mpa on mpa.relatedRecord = fup.relatedRecord and mpa.relatedRecordModule = fup.relatedRecordModule
		) t
	)
	update FollowUpItem set 
	PreviousIDActivity = t.PreviousIDActivity ,
	PreviousActivityLabel = t.PreviousActivityLabel ,
	PreviousActivityDate = t.PreviousActivityDate ,
	NextIDActivity = t.NextIDActivity ,
	NextIDActivityModule = t.NextIDActivityModule ,
	NextActivityLabel = t.NextActivityLabel ,
	NextActivityDate = t.NextActivityDate ,
	DaysSinceLastCompleted = t.DaysSinceLastCompleted ,
	DaysUntilNextPlanned = t.DaysUntilNextPlanned ,
	DaysUntilNextPlannedStatus = t.DaysUntilNextPlannedStatus,
	Status = t.NewStatus
	from(
		select * 
		from finalValues
	) t
	where IDFollowUpItem = t.IDFUP and  IDModule = t.IDFUPModule;
	
	update FollowUpItem2Assets set RegisterStatus = RegStatus
	from(
		select RegisterStatus RegStatus, IDFollowUpItem IDF, IDModule IDFMod
		from FollowUpItem 
		where IDFollowUpItem = @IDRecord and IDModule = @IDModule
	) t
	where IDRecFollowUpItem = t.IDF and IDRecFollowUpItemModule = t.IDFMod

END
GO


-- ----------------------------
-- procedure structure for sp_creatediagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_creatediagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_creatediagram]
GO

CREATE PROCEDURE [dbo].[sp_creatediagram]
	(
		@diagramname 	sysname,
		@owner_id		int	= null, 	
		@version 		int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId int
		declare @retval int
		declare @IsDbo	int
		declare @userName sysname
		if(@version is null or @diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID(); 
		select @IsDbo = IS_MEMBER(N'db_owner');
		revert; 
		
		if @owner_id is null
		begin
			select @owner_id = @theId;
		end
		else
		begin
			if @theId <> @owner_id
			begin
				if @IsDbo = 0
				begin
					RAISERROR (N'E_INVALIDARG', 16, 1);
					return -1
				end
				select @theId = @owner_id
			end
		end
		-- next 2 line only for test, will be removed after define name unique
		if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end
	
		insert into dbo.sysdiagrams(name, principal_id , version, definition)
				VALUES(@diagramname, @theId, @version, @definition) ;
		
		select @retval = @@IDENTITY 
		return @retval
	END
GO


-- ----------------------------
-- procedure structure for sp_renamediagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_renamediagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_renamediagram]
GO

CREATE PROCEDURE [dbo].[sp_renamediagram]
	(
		@diagramname 		sysname,
		@owner_id		int	= null,
		@new_diagramname	sysname
	
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @DiagIdTarg		int
		declare @u_name			sysname
		if((@diagramname is null) or (@new_diagramname is null))
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT;
	
		select @u_name = USER_NAME(@owner_id)
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
		--	return 0;
	
		if(@u_name is null)
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
		else
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname
	
		if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end		
	
		if(@u_name is null)
			update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
		else
			update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
		return 0
	END
GO


-- ----------------------------
-- procedure structure for sp_alterdiagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_alterdiagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_alterdiagram]
GO

CREATE PROCEDURE [dbo].[sp_alterdiagram]
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END
GO


-- ----------------------------
-- procedure structure for UpdateMouldLastRoutine
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateMouldLastRoutine]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateMouldLastRoutine]
GO

CREATE PROCEDURE [dbo].[UpdateMouldLastRoutine]
	(@IDRecord int, @IDModule uniqueidentifier)
AS
BEGIN
	
	SET NOCOUNT ON;

	declare @IDFollowUpItem int =
	(
		select IDMould
		from ProductionRoutineChanges
		where ID = @IDRecord
	);

	declare @CurrentCounter int = 
	(
		select max([order]) 
		from ProductionRoutineChanges
		where idmould = @IDFollowUpItem
	);
	
	update FollowUpItemMouldFields 
		set 
			RoutineChangeIndex = @CurrentCounter , 
			IDLastRoutineChange = @IDRecord, 
			IDLastRoutineChangeModule = @IDModule,
			MouldNo = 
			case 
					when CHARINDEX('_A',MouldNo) = 0 then CONCAT(MouldNo,'_A', @CurrentCounter)
					when CHARINDEX('_A',MouldNo) > 0 then CONCAT(SUBSTRING(mouldno, 0, CHARINDEX('_A',MouldNo)), '_A', @CurrentCounter)
			end		
	where IDFollowUpItem = @IDFollowUpItem;

END
GO


