-- ----------------------------
-- procedure structure for sp_dropdiagram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_dropdiagram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_dropdiagram]
GO

CREATE PROCEDURE [dbo].[sp_dropdiagram]
	(
		@diagramname 	sysname,
		@owner_id	int	= null
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		end
	
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT; 
		
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		end
	
		delete from dbo.sysdiagrams where diagram_id = @DiagId;
	
		return 0;
	END
GO


-- ----------------------------
-- procedure structure for CreateDocLines2Tag
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreateDocLines2Tag]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreateDocLines2Tag]
GO

CREATE PROCEDURE [dbo].[CreateDocLines2Tag]
(
	@IDLineDest int, 
	@IDLineDestModule uniqueidentifier,
	@IDLineSrc int,
	@IDLineSrcModule uniqueidentifier
)
AS
BEGIN
	declare @DBMaskToUse int = (select top 1 dbmask from DocumentLine where ID = @IDLineDest);
	declare @TagToUse uniqueidentifier = (select top 1 idtag from Tag2DocumentLine where IDDocLine = @IDLineSrc and Auto = 1);
	declare @IDModuleTag uniqueidentifier = 
	(
		select top 1 idmodule 
		from GetModulesRec('542BCEEF-C43E-434B-B2E9-9FB6AB8FA9D0') 
		where dbmask = @DBMaskToUse
	);

	if(@IDModuleTag is null)
	begin
		return;
	end 

	declare @code nvarchar(5)= case 
		when @DBMaskToUse = 1 then '_IS_'
		when @DBMaskToUse = 4 then '_CS_'
		when @DBMaskToUse = 8 then '_X3D_'
		when @DBMaskToUse = 16 then '_SPT_'
		when @DBMaskToUse = 32 then '_CN_'
	end 
	if @TagToUse is null
	begin
		declare @CurrentCounter int = (select currentcounter from SysModule where IDModule = @IDModuleTag);

		declare @Name nvarchar(500) = 
		(
			select CONCAT(d.doc_ref, 
				case 
				when dl.IDParent is null then '_Totalizer' 
				else CONCAT('_', dl.LineNumber, 
				(
					case 
					when dl.ProductCode is not null and dl.ProductCode <> '' then CONCAT('_' ,dl.ProductCode)
					end)
				) end)
			from DocumentLine dl
			inner join document d on d.IDDocument = dl.IDRegister and d.IDModule = dl.IDModule and dl.PartitionColumn = d.PartitionColumn
			where dl.ID = @IDLineSrc
		);

		DECLARE @tmp TABLE ( 
        IDTag uniqueidentifier NOT NULL
		);

		insert into Tags
		(
			ID, Code, Name, Description, Kind, Code_counter, Code_IsTemp,
			dbmask,IsTemplate,TemplateCode,ModifiedTime,CreatedTime,RegisterStatus,RegisterSysStatus,IDModule,IDUserCreation,
			IDUser,IDResourceCreation,IDResource,IDResourceAssign,
			TeamMask01,TeamMask02,TemplateDefaultMFVCreate  
		) output inserted.ID into @tmp(IDTag)
			values(NEWID(), CONCAT('TAG',@code ,RIGHT(concat('000000', @CurrentCounter), 6)), @Name, @Name, 0, @CurrentCounter, 0,
			@DBMaskToUse, 0,'',GETDATE(),GETDATE(),0,0, @IDModuleTag,'BFC1CA04-091D-4096-AEBF-48DC5B6EE77C',
			'BFC1CA04-091D-4096-AEBF-48DC5B6EE77C','23788371-162C-41DF-AAF2-1D55558AE57C','23788371-162C-41DF-AAF2-1D55558AE57C','23788371-162C-41DF-AAF2-1D55558AE57C',
			-1,-1,0
			);

		set @TagToUse = (select top 1 IDTag from @tmp);

		insert into Tag2DocumentLine
		values(@TagToUse, @IDModuleTag, @IDLineSrc, @IDLineSrcModule, 1);

		update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @IDModuleTag;
	end

	insert into Tag2DocumentLine
	values(@TagToUse, @IDModuleTag, @IDLineDest, @IDLineDestModule, 1);
END
GO


