-- ----------------------------
-- procedure structure for UpdateOpportunityDaysToClose
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateOpportunityDaysToClose]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateOpportunityDaysToClose]
GO

CREATE PROCEDURE [dbo].[UpdateOpportunityDaysToClose]
	@IDRecord int
AS
BEGIN

		--Vermelho
	UPDATE FollowUpItem 
	SET DaysToClose=DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate),
		DaysToCloseStatus =4
	where 
	IDModule in (select IDModule from GetModulesRec('596a893b-06e8-48e0-b03c-4e33aa9fe9f1')) and
	 IDFollowUpItem=@IDRecord and 
	ExpectedCloseDate is not null
	and DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)<30
	--Laranja
	UPDATE FollowUpItem 
	SET DaysToClose=DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate),
		DaysToCloseStatus =3
	from FollowUpItem 
	where 
	IDModule in (select IDModule from GetModulesRec('596a893b-06e8-48e0-b03c-4e33aa9fe9f1')) and
	IDFollowUpItem=@IDRecord and 
	ExpectedCloseDate is not null
	and (DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)>30 and  DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)<60)
	--Amarelo
	UPDATE FollowUpItem 
	SET DaysToClose=DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate),
		DaysToCloseStatus =2
	from FollowUpItem 
	where
	IDModule in (select IDModule from GetModulesRec('596a893b-06e8-48e0-b03c-4e33aa9fe9f1')) and
	IDFollowUpItem=@IDRecord and 
	ExpectedCloseDate is not null
	and 
	(DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)>60 and  DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)<90)
	-- Verde
	UPDATE FollowUpItem 
	SET DaysToClose=DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate),
		DaysToCloseStatus =1
	from FollowUpItem 
	where
	IDModule in (select IDModule from GetModulesRec('596a893b-06e8-48e0-b03c-4e33aa9fe9f1')) and
	IDFollowUpItem=@IDRecord  
	and
	(
	( ExpectedCloseDate is not null
	and DATEDIFF(day,  GETUTCDATE(), ExpectedCloseDate)>90 ) 
	or ExpectedCloseDate is null
	)

END
GO


-- ----------------------------
-- procedure structure for MergeChannels
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[MergeChannels]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[MergeChannels]
GO

CREATE PROCEDURE [dbo].[MergeChannels]
    -- Add the parameters for the stored procedure here
    @IDChannel2Remove uniqueidentifier,
    @IDChannelTarget uniqueidentifier,
    @IDResource uniqueidentifier,
    @IDLogin uniqueidentifier
AS
BEGIN
    DECLARE @count as int
    Declare @channelName as nvarchar(100)
    DECLARE @newDesktopIDChannel as uniqueidentifier
    BEGIN TRANSACTION;
    SAVE TRANSACTION MySavePoint;

     BEGIN TRY

     SET @count=(SELECT COUNT(IDWorkRoom) 
     FROM SysWorkRoom 
     WHERE IDWorkRoom=@IDChannel2Remove or IDWorkRoom=@IDChannelTarget)

     IF @count<>2
     BEGIN
        RAISERROR('Not all Channel exist',16,1)
     END 

     UPDATE SysChat SET IDWorkRoom=@IDChannelTarget WHERE IDWorkRoom=@IDChannel2Remove

     -- Remove conflicting rows 
     DELETE FROM SysChat2SysWorkRoom WHERE IDWorkRoom = @IDChannel2Remove AND EXISTS ( SELECT 1 FROM SysChat2SysWorkRoom AS target WHERE target.IDWorkRoom = @IDChannelTarget AND target.IDChat2 = SysChat2SysWorkRoom.IDChat2 AND target.Kind = SysChat2SysWorkRoom.Kind );

     UPDATE SysChat2SysWorkRoom SET IDWorkRoom=@IDChannelTarget WHERE IDWorkRoom=@IDChannel2Remove

     -- Migrate Tasks
	 -- Remove conflicting rows
     DELETE FROM SysTask2Channel WHERE IDChannel = @IDChannel2Remove AND EXISTS ( SELECT 1 FROM SysTask2Channel AS target WHERE target.IDChannel = @IDChannelTarget AND target.IDTask = SysTask2Channel.IDTask);
     UPDATE SysTask2Channel SET IDChannel=@IDChannelTarget WHERE IDChannel=@IDChannel2Remove

     -- Migrate Activities
     -- Remove conflicting rows
     DELETE FROM Activity2Channel WHERE IDChannel = @IDChannel2Remove AND EXISTS ( SELECT 1 FROM Activity2Channel AS target WHERE target.IDChannel = @IDChannelTarget AND target.IDActivity = Activity2Channel.IDActivity);
     UPDATE Activity2Channel SET IDChannel=@IDChannelTarget WHERE IDChannel=@IDChannel2Remove

     -- Migrate Email's
     -- Remove conflicting rows
     DELETE FROM SysMail2SysWorkroom WHERE IDWorkroom = @IDChannel2Remove AND EXISTS ( SELECT 1 FROM SysMail2SysWorkroom AS target WHERE target.IDWorkroom = @IDChannelTarget AND target.IDMail = SysMail2SysWorkroom.IDMail);
     UPDATE SysMail2SysWorkroom SET IDWorkRoom=@IDChannelTarget WHERE IDWorkRoom=@IDChannel2Remove

     -- Migrate FollowUpItems
     -- Remove conflicting rows
     DELETE FROM SysEntity2Channel WHERE IDChannel = @IDChannel2Remove AND EXISTS ( SELECT 1 FROM SysEntity2Channel AS target WHERE target.IDChannel = @IDChannelTarget AND target.[IDEntity] = SysEntity2Channel.[IDEntity] AND target.IDEntityModule = SysEntity2Channel.IDEntityModule);
     UPDATE SysEntity2Channel SET IDChannel=@IDChannelTarget WHERE IDChannel=@IDChannel2Remove

     -- Migrate Resources not in target channel but in removed channel
    INSERT INTO 
    SysWorkRoomResource(IDResource,ShareChat,ShareScheduler,IDWorkRoom,IDWorkRoomResource,ResourceAccessType,IsOwner,Importance,MonitorChannel,ActivitiesPermissions,TasksPermissions,LinkKind,AllowPublish,MonitorFeatureFlags,Spokesperson)
    SELECT IDResource,ShareChat,ShareScheduler,@IDChannelTarget,newid(),ResourceAccessType,IsOwner,Importance,MonitorChannel,ActivitiesPermissions,TasksPermissions,LinkKind,AllowPublish,MonitorFeatureFlags,Spokesperson
    FROM SysWorkRoomResource  
    WHERE IDWorkRoom=@IDChannel2Remove
    AND IDResource not in (SELECT wrt.IDResource 
    FROM SysWorkRoomResource wrt  WHERE  wrt.IDWorkRoom=@IDChannelTarget)

    -- Migrate SysDesktopItems
    SET @count=(SELECT COUNT(*)
    FROM SysDesktopItems 
    WHERE IDChannel=@IDChannel2Remove
    and( IDParent is null or IDParent='00000000-0000-0000-0000-000000000000'))

    -- Has desktop items ?
     IF @count>0
     BEGIN
		
        --Set @newDesktopIDChannel =NEWID()

		Set @newDesktopIDChannel = (select top 1 ID
		from SysDesktopItems 
		where IDChannel=@IDChannelTarget
		and( IDParent is null or IDParent='00000000-0000-0000-0000-000000000000'))


		if @newDesktopIDChannel is not null 
		BEGIN

			-- Migrate all SysDesktopItems to new Channel
			Update SysDesktopItems 
			SET 
				IDChannel = @IDChannelTarget
			WHERE IDChannel = @IDChannel2Remove 
			AND 
			( 
				ID NOT IN 
				(
					SELECT ID
					FROM SysDesktopItems 
					WHERE IDChannel=@IDChannel2Remove
					AND( IDParent IS NULL OR IDParent='00000000-0000-0000-0000-000000000000')
				)
			)

			Update SysDesktopItems 
			SET 
				IDParent = @newDesktopIDChannel
			WHERE IDParent IN (
					SELECT ID
					FROM SysDesktopItems 
					WHERE IDChannel=@IDChannel2Remove
					AND( IDParent IS NULL OR IDParent='00000000-0000-0000-0000-000000000000')
				)

			DELETE FROM SysDesktopItems 
			WHERE IDChannel=@IDChannel2Remove
			AND( IDParent IS NULL OR IDParent='00000000-0000-0000-0000-000000000000')

		END
		ELSE
		BEGIN

			Update SysDesktopItems 
			SET 
				IDChannel = @IDChannelTarget
			WHERE IDChannel = @IDChannel2Remove 

		END
     END

     Update SysWorkRoom set active=0 where  IDWorkRoom =@IDChannel2Remove

     COMMIT TRANSACTION 
     --ROLLBACK TRANSACTION
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
        BEGIN
            ROLLBACK TRANSACTION MySavePoint; -- rollback to MySavePoint
        END

        
    DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR('Erro capturado: %s', 16, 1, @ErrMsg);
    END CATCH
END
GO


