CREATE PROCEDURE [dbo].[CreateAlternative]
	-- Add the parameters for the stored procedure here
	@TableName sysname,
	@PrimaryKey nvarchar(100),
	@IDRecord nvarchar(100)
AS
BEGIN
	DECLARE @sql AS NVARCHAR(MAX)
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	SET @sql = 'UPDATE '+@TableName+' SET alternativeCounter=alternativeCounter+1 WHERE '+@PrimaryKey+'='''+@IDRecord+''''
	EXEC sp_executesql @sql

	SET @sql = 'UPDATE '+@TableName+' SET alternativeParentID='''+@IDRecord+''' WHERE '+@PrimaryKey+'='''+@IDRecord+''' AND alternativeParentID IS NULL'
	EXEC sp_executesql @sql
END
GO


-- ----------------------------
-- function structure for GetResourcePositions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourcePositions]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourcePositions]
GO

CREATE FUNCTION [dbo].[GetResourcePositions]
(	
)
RETURNS TABLE 
AS
RETURN 
(
	-- Add the SELECT statement with parameter references here
	SELECT rrp.ID, LTRIM(RTRIM(r.Code)) AS [Resource], LTRIM(RTRIM(pr.Code)) AS [Process], LTRIM(RTRIM(COALESCE(pr1.Code,''))) AS [Children Of],
	 LTRIM(RTRIM(COALESCE(pri.Code,''))) AS [Task], LTRIM(RTRIM(COALESCE(np.Code,''))) AS [Position Assigned], 
	 LTRIM(RTRIM(COALESCE(o.Fullname,''))) as [Part]  FROM SysPrRoutineResourcePositions rrp
	INNER JOIN SysResources r ON rrp.IDResource = r.ResourceId
	LEFT JOIN SysPrRoutine pr ON rrp.IDProcess = pr.IDRoutine
	LEFT JOIN SysPrRoutineItem pri ON rrp.IDPrRoutineItem = pri.IDRoutineItem
	LEFT JOIN SM_NodePosic np ON rrp.IDPosic = np.ID
	LEFT JOIN SS_Object o ON rrp.IDPart = o.ID
	LEFT JOIN SysPrRoutineRequest r0 ON rrp.IDRequest = r0.ID
	LEFT JOIN SysPrRoutineCursor c ON r0.IDTask = c.IDSysRoutineCursor
	LEFT JOIN SysPrRoutineRequest r1 ON c.IDRequest = r1.ID
	LEFT JOIN SysPrRoutine pr1 ON r1.IDPrRoutine = pr1.IDRoutine

)
GO


-- ----------------------------
-- procedure structure for CloseToken
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseToken]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseToken]
GO

CREATE PROCEDURE [dbo].[CloseToken]
	@Token nvarchar(50)
AS
BEGIN
	SET NOCOUNT ON;

	declare it cursor 
		LOCAL STATIC READ_ONLY FORWARD_ONLY for 
		select IDLock
		from sysLockRecord
		where Token = @Token AND [Status] = 1;

	open it;
	declare @idlock uniqueidentifier

	fetch next from it into @idLock
	while @@fetch_status = 0
	begin
		-- ..
		exec CloseLock @idLock, 97

		fetch next from it into @idLock
	end

	close it;
	deallocate it;
END
GO


