-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[LeadsQuery]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[LeadsQuery]
