CREATE PROCEDURE [dbo].[LeadsQuery]
AS
BEGIN

	SET NOCOUNT ON;

select
	cast(CreatedTime as date) as createdTime,
	lead_no,
	cast(leadDate as date) as leadDate,
	partnerId,
	leadstatusItems.code as [status],
	followupItems.Code as leadFollowUp,
	resumoPartner,
	company
from 
	leads 
	left join (select * from sysfieldvalueitem where GroupCode like 'leadstatus') leadstatusItems on leads.status = leadstatusItems.codeint
	left join (select * from sysfieldvalueitem where GroupCode like '%follow%') followupItems on leads.leadFollowUp = followupItems.codeint
where 
	leads.RegisterStatus = 0
	 and IDCampaign in (209091
, 212116
)
	--and isnull(partnerId, '') != ''
	--and year(leadDate) = 2017
	--and month(leaddate) in( 3, 4)
	


	-- and leadstatusItems.code like 'not%'
END
