-- ----------------------------
-- function structure for FnEntity2ServiceContract2BusinessArea
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FnEntity2ServiceContract2BusinessArea]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[FnEntity2ServiceContract2BusinessArea]
GO

CREATE FUNCTION [dbo].[FnEntity2ServiceContract2BusinessArea]
(
	@NAlmostExpiringDays int,
	@NAboutToExpireDays int
)
RETURNS 
@Entity2ServiceContract2BusinessArea TABLE 
(
	[ID] int not null identity(1,1),
	[IDRecEntity] [int] NOT NULL,
	[IDRecEntityModule] [uniqueidentifier] NOT NULL,
	[IDBusinessArea] [int] NOT NULL,
	[IDBusinessAreaModule] [uniqueidentifier] NOT NULL,
	[IsMaintenanceActive] [int] NULL,
	[SupplierRegistry] [int] NULL,
	[IDServiceContract] [int] NOT NULL,
	[IDServiceContractModule] [uniqueidentifier] NOT NULL,
	[IDParent] [int] NULL,
	[Status] [int] NULL,
	[EndDatePurchase] [datetime] NULL,
	[EndDateSale] [datetime] NULL,
	[dbmask] [int] NOT NULL,
	PRIMARY KEY (ID),
	INDEX IX_Lookup NONCLUSTERED (IDRecEntity, IDServiceContract, IDBusinessArea)
)
AS
BEGIN
	DECLARE @CurrentDate datetime = GETDATE();
	
	DECLARE @AuxTable TABLE (
		ID int IDENTITY(1,1) PRIMARY KEY,
		IDRecEntity int,
		IDRecEntityModule uniqueidentifier,
		IDServiceContract int,
		IDServiceContractModule uniqueidentifier,
		IDBusinessArea int,
		IDBusinessAreaModule uniqueidentifier,
		IDBusinessAreaParent int,
		EndDatePurchase datetime,
		EndDateSale datetime,
		HasOwnDates int,
		LineDepth int,
		dbmask int,
		INDEX IX_Depth NONCLUSTERED (LineDepth, IDRecEntity, IDServiceContract, IDBusinessArea)
	);

	-- OPTIMIZED: Single-pass hierarchy calculation
	;WITH 
	-- Pre-calculate ALL BusinessArea LineDepths once (reusable)
	AllBALineDepths AS (
		SELECT IDBusinessArea, IDParent, IDModule, 0 AS LineDepth
		FROM BusinessArea
		WHERE IDParent IS NULL
		
		UNION ALL
		
		SELECT ba.IDBusinessArea, ba.IDParent, ba.IDModule, ld.LineDepth + 1
		FROM BusinessArea ba
		INNER JOIN AllBALineDepths ld ON ba.IDParent = ld.IDBusinessArea
	),
	-- Materialize depths with MAX to handle multiple paths
	BADepths AS (
		SELECT IDBusinessArea, IDParent, IDModule, MAX(LineDepth) AS LineDepth
		FROM AllBALineDepths
		GROUP BY IDBusinessArea, IDParent, IDModule
	),
	-- Get contract BAs and expand ancestors in ONE CTE
	ContractBAWithAncestors AS (
		-- Anchor: Contract business areas
		SELECT 
			e.organizationid AS IDRecEntity,
			e.IDModule AS IDRecEntityModule,
			sc.IDServiceContract,
			sc.IDModule AS IDServiceContractModule,
			ba.IDBusinessArea,
			ba.IDModule AS IDBusinessAreaModule,
			ba.IDParent AS IDBusinessAreaParent,
			sc2ba.EndDatePurchase,
			sc2ba.EndDateSale,
			1 AS HasOwnDates,
			ba.LineDepth,
			sc.dbmask
		FROM Entity e
		INNER JOIN ServiceContract sc 
			ON e.organizationid = sc.IDEntityRelatedTo 
			AND e.IDModule = sc.IDEntityRelatedToModule
		INNER JOIN ServiceContract2BusinessArea sc2ba 
			ON sc.IDServiceContract = sc2ba.IDRecServiceContract 
			AND sc.IDModule = sc2ba.IDRecServiceContractModule
		INNER JOIN BADepths ba ON sc2ba.IDBusinessArea = ba.IDBusinessArea
		WHERE sc.status NOT IN (2668, 2669, 2670)
		
		UNION ALL
		
		-- Recursive: Add parent BAs
		SELECT 
			cba.IDRecEntity,
			cba.IDRecEntityModule,
			cba.IDServiceContract,
			cba.IDServiceContractModule,
			parent.IDBusinessArea,
			parent.IDModule,
			parent.IDParent,
			NULL AS EndDatePurchase,
			NULL AS EndDateSale,
			0 AS HasOwnDates,
			parent.LineDepth,
			cba.dbmask
		FROM ContractBAWithAncestors cba
		INNER JOIN BADepths parent ON cba.IDBusinessAreaParent = parent.IDBusinessArea
	)
	INSERT INTO @AuxTable (IDRecEntity, IDRecEntityModule, IDServiceContract, IDServiceContractModule, 
		IDBusinessArea, IDBusinessAreaModule, IDBusinessAreaParent, EndDatePurchase, EndDateSale, 
		HasOwnDates, LineDepth, dbmask)
	SELECT DISTINCT
		IDRecEntity, IDRecEntityModule, IDServiceContract, IDServiceContractModule, 
		IDBusinessArea, IDBusinessAreaModule, IDBusinessAreaParent, EndDatePurchase, EndDateSale, 
		HasOwnDates, LineDepth, dbmask
	FROM ContractBAWithAncestors
	OPTION (MAXRECURSION 0);

	-- Remove duplicates (optimized)
	DELETE t
	FROM @AuxTable t
	WHERE t.HasOwnDates = 0
	AND EXISTS (
		SELECT 1
		FROM @AuxTable dup
		WHERE dup.IDRecEntity = t.IDRecEntity
			AND dup.IDServiceContract = t.IDServiceContract
			AND dup.IDBusinessArea = t.IDBusinessArea
			AND dup.LineDepth = t.LineDepth
			AND dup.HasOwnDates = 1
			AND dup.ID < t.ID
	);

	DECLARE @MaxDepth int = (SELECT MAX(LineDepth) FROM @AuxTable);

	-- Insert root level
	INSERT INTO @Entity2ServiceContract2BusinessArea (
		IDRecEntity, IDRecEntityModule, IDBusinessArea, IDBusinessAreaModule, 
		IsMaintenanceActive, SupplierRegistry, IDServiceContract, IDServiceContractModule, 
		IDParent, Status, EndDatePurchase, EndDateSale, dbmask
	)
	SELECT 
		IDRecEntity, IDRecEntityModule, IDBusinessArea, IDBusinessAreaModule,
		CASE WHEN HasOwnDates = 1 AND DATEDIFF(DAY, EndDateSale, @CurrentDate) >= 0 
			THEN 1 ELSE 0 END,
		NULL,
		IDServiceContract, IDServiceContractModule, NULL, NULL,
		CASE WHEN HasOwnDates = 1 THEN EndDatePurchase ELSE NULL END,
		CASE WHEN HasOwnDates = 1 THEN EndDateSale ELSE NULL END,
		dbmask
	FROM @AuxTable
	WHERE LineDepth = 0;

	-- Batch insert hierarchical levels (reduce loop iterations)
	DECLARE @i int = 1;
	WHILE @i <= @MaxDepth
	BEGIN
		INSERT INTO @Entity2ServiceContract2BusinessArea (
			IDRecEntity, IDRecEntityModule, IDBusinessArea, IDBusinessAreaModule, 
			IsMaintenanceActive, SupplierRegistry, IDServiceContract, IDServiceContractModule, 
			IDParent, Status, EndDatePurchase, EndDateSale, dbmask
		)
		SELECT 
			t.IDRecEntity, t.IDRecEntityModule, t.IDBusinessArea, t.IDBusinessAreaModule,
			CASE WHEN HasOwnDates = 1 AND DATEDIFF(DAY, EndDateSale, @CurrentDate) <= 0 
				THEN 1 ELSE 0 END,
			NULL,
			t.IDServiceContract, t.IDServiceContractModule,
			(SELECT TOP 1 aux.ID
			 FROM @Entity2ServiceContract2BusinessArea aux 
			 WHERE aux.IDRecEntity = t.IDRecEntity 
				AND aux.IDServiceContract = t.IDServiceContract
				AND aux.IDBusinessArea = t.IDBusinessAreaParent),
			NULL,
			CASE WHEN HasOwnDates = 1 THEN t.EndDatePurchase ELSE NULL END,
			CASE WHEN HasOwnDates = 1 THEN t.EndDateSale ELSE NULL END,
			t.dbmask
		FROM @AuxTable t
		WHERE LineDepth = @i;
		
		SET @i += 1;
	END

	-- Propagate dates (optimized with reduced joins)
	SET @i = @MaxDepth - 1;
	WHILE @i >= 0 
	BEGIN
		UPDATE e
		SET 
			e.EndDatePurchase = md.MinEndPurchase, 
			e.EndDateSale = md.MinEndSale
		FROM @Entity2ServiceContract2BusinessArea e
		INNER JOIN (
			SELECT 
				t.IDServiceContract, 
				t.IDRecEntity, 
				t.IDBusinessAreaParent, 
				MIN(t2.EndDatePurchase) AS MinEndPurchase, 
				MIN(t2.EndDateSale) AS MinEndSale
			FROM @AuxTable t
			INNER JOIN @AuxTable t2 
				ON t.IDServiceContract = t2.IDServiceContract
				AND t.IDRecEntity = t2.IDRecEntity
				AND t.IDBusinessAreaParent = t2.IDBusinessArea
			WHERE t.LineDepth = @i 
				AND t.HasOwnDates = 0
				AND t2.LineDepth > @i
			GROUP BY t.IDServiceContract, t.IDRecEntity, t.IDBusinessAreaParent
		) md ON e.IDServiceContract = md.IDServiceContract
			AND e.IDRecEntity = md.IDRecEntity
			AND e.IDBusinessArea = md.IDBusinessAreaParent;

		SET @i -= 1;
	END

	-- Final status calculation
	UPDATE @Entity2ServiceContract2BusinessArea 
	SET 
		IsMaintenanceActive = CASE WHEN EndDateSale IS NOT NULL 
			AND DATEDIFF(DAY, @CurrentDate, EndDateSale) < 0 THEN 0 ELSE 1 END,
		Status = CASE 
			WHEN EndDateSale IS NULL THEN 0
			WHEN DATEDIFF(DAY, @CurrentDate, EndDateSale) > @NAlmostExpiringDays THEN 0
			WHEN DATEDIFF(DAY, @CurrentDate, EndDateSale) BETWEEN (@NAboutToExpireDays + 1) 
				AND @NAlmostExpiringDays THEN 1
			WHEN DATEDIFF(DAY, @CurrentDate, EndDateSale) >= 0 THEN 2
			ELSE 3 
		END;

	RETURN;
END
GO


-- ----------------------------
-- function structure for GetRelationFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRelationFields]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetRelationFields]
GO

CREATE FUNCTION [dbo].[GetRelationFields]
(
	@IDModule int
)
RETURNS nvarchar(max)
AS
BEGIN
	DECLARE @f_RelationTable varchar (50)
	DECLARE @f_RelationField varchar (50)
	DECLARE @RESULT_STRING nvarchar(max)

	DECLARE myCursor CURSOR FOR 		
			Select tm.RelationTable as tb,tm.RelationField as f FROM TableRelation tr 
		INNER JOIN TableModule tm on (tr.RelationKind ='TM' and tm.IDTableModule=tr.IDRelationKind and tr.IDRelationParent=0) 
		WHERE tr.IDModule=@IDModule
	except
		Select Field.TableName as tb,Field.ColumnName as f FROM Field
		where Field.IDModule=@IDModule and Field.IDParendField >0

	SET @RESULT_STRING=''

	OPEN myCursor

	FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField

	WHILE(@@FETCH_STATUS = 0)
	BEGIN
		
		if (ISNULL( @RESULT_STRING,'')!='')
			SET @RESULT_STRING=@RESULT_STRING+', '
		if (ISNULL( @f_RelationTable,'')!='')
		SET @RESULT_STRING = @RESULT_STRING + @f_RelationTable + '.' + @f_RelationField

		FETCH NEXT FROM myCursor INTO @f_RelationTable, @f_RelationField
	END

	CLOSE myCursor
	DEALLOCATE myCursor


	RETURN @RESULT_STRING

END
GO


