-- ----------------------------
-- procedure structure for Query_Quotes3dSystems
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_Quotes3dSystems]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_Quotes3dSystems]
GO

CREATE PROCEDURE [dbo].[Query_Quotes3dSystems]

AS
BEGIN
	SET NOCOUNT ON;

	select
		d.doc_ref,
		d.doc_date,
		isnull(d.doc_3rd_account_name, '') as customer, 
		isnull(e.billingcity, '') as billingcity, 
		isnull(e.mailingcity, '') as mailingcity, 

		isnull(tv.Translation, '') as geoarea
	from 
		document d
		left join Entity e on d.doc_3rd = e.organizationid
		left join
		GeographicalArea g on e.IDGeographicArea = g.IDGeographicalArea
		left join 
		SysTranslation t on g.GAName = t.IDTranslation
		left join
		SysTranslationValue tv on t.IDTranslation = tv.IDTranslation and tv.IDLanguage = 1
	where 
	d.IDModule in (
		'761D4BF2-AD9C-4411-BF11-7747DC81C06C',
		'F27B5BE9-7748-491A-9866-BC99BAF9014C',
		'E2FCAE35-0290-42B9-B422-D63AB4C83F70'
	)
	and
	d.RegisterSysStatus = 0
	and
	d.IDDocument in (
		select idregister
		from DocumentLine
		where productid in (select productid from dbo.GetProductChildren(128562))
	)

END
GO


-- ----------------------------
-- procedure structure for CloseLock
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseLock]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseLock]
GO

CREATE PROCEDURE [dbo].[CloseLock]
	@IDLock uniqueidentifier,	
	@src int = null
AS
BEGIN
	SET NOCOUNT ON;

	--print concat('closelock(', @IDLock, ')')

	if @src is null
	begin
		set @src = 2
	end

	declare CloseLock_it cursor for
		select Token, IDModule, IDRecord, IDSession, IDLogin
		from SysLockRecord
		where IDLock = @IDLock and [Status] = 1

	open CloseLock_it;

	declare @l_Token nvarchar(50), @l_IDModule uniqueidentifier, @l_IDRecord nvarchar(36), @l_IDSession uniqueidentifier, @l_IDLogin uniqueidentifier, @result int;

	fetch next from CloseLock_it into @l_Token, @l_IDModule, @l_IDRecord, @l_IDSession, @l_IDLogin
	while @@FETCH_STATUS = 0
	begin
		
		exec @result = [dbo].[Try_LockRecordForEdition] @locking = 0, @IDRecord = @l_IDRecord, @IDModule = @l_IDModule, @IDSession = @l_IDSession, @IDWorkstation = NULL, 
			@IDLogin = @l_IDLogin, @IDResource = NULL, @MainTable = '', @MainTablePk = '', @MainTableModId = '', @IDModuleFilterView = null, @o_token = @l_Token, 
			@src = @src


		--print concat('=', @result)
		fetch next from CloseLock_it into @l_Token, @l_IDModule, @l_IDRecord, @l_IDSession, @l_IDLogin
	end;

	close CloseLock_it;
	deallocate CloseLock_it;

END
GO


