-- ----------------------------
-- procedure structure for Try_LockRecordForEdition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Try_LockRecordForEdition]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Try_LockRecordForEdition]
GO

CREATE PROCEDURE [dbo].[Try_LockRecordForEdition]
	@locking int,
	@IDRecord nvarchar(50),
	@IDModule uniqueidentifier,
	@IDSession uniqueidentifier out,
	@IDWorkstation nvarchar(50) out,
	@IDLogin uniqueidentifier out,
	@IDResource uniqueidentifier out,

	@MainTable nvarchar(100),
	@MainTablePk nvarchar(100),
	@MainTableModId nvarchar(100),

	@IDModuleFilterView uniqueidentifier,
		
	@expectedRegisterStatus int = 0,
	@registerStatus int = 3,
	
	@o_token nvarchar(50) out,
	@o_actualStartDate datetime = null out,
	@o_registerStatusOld int = null out,
	
	@src int = null

AS
BEGIN	

 -- return 0
	-- normalize token
	set @o_token = trim(UPPER(@o_token))
	-- normalize token
	set @o_token = trim(UPPER(@IDRecord))

	SET NOCOUNT ON;
	DECLARE @return INT
	DECLARE @isLocked INT
	DECLARE @ignoreTimeouts INT
	set @ignoreTimeouts = 0

	DECLARE @RecordLockAction_LockStatus INT
	set @RecordLockAction_LockStatus=5
	DECLARE @alternativeExpectedRegisterStatusForLockStatusClosed INT
	set @alternativeExpectedRegisterStatusForLockStatusClosed=1
	DECLARE @alternativeExpectedRegisterStatusForLockStatusCanceled INT
	set @alternativeExpectedRegisterStatusForLockStatusCanceled=4

	DECLARE @sql nvarchar(max)
	-- DECLARE @OldRegisterStatus INT

	set @o_actualStartDate = null

	IF @locking = 3
	begin

		UPDATE SysLockRecord
		SET StartDate = GETUTCDATE()
		WHERE Token = @o_token AND IDSession = @IDSession

	end -- end IF @locking = 4 
	else 
	begin

		DECLARE @l_idLock uniqueidentifier
		DECLARE @l_startDate datetime, @l_actualDateStart datetime
		DECLARE @l_idLogin uniqueidentifier, @l_idResource uniqueidentifier, @l_idSession uniqueidentifier
		DECLARE @l_idWorkstation nvarchar(50)

		select 
			@l_idLock = lr.IdLock, 
			@o_token = lr.Token, 
			@l_startDate = lr.StartDate, 
			@l_actualDateStart = lr.ActualStartDate,
			@l_idLogin = lr.IDLogin, 
			@l_idResource = lr.IDResource, 
			@l_idSession = lr.IDSession,
			@l_idWorkstation = s.IDWorkstation
		from 
			SysLockRecord lr left join SysSession s on lr.IDSession = s.IDSession
		where IDModule = @IDModule AND IDRecord = @IDRecord and lr.[Status] = 1

		IF @locking = 1 or @locking = 2 OR @locking=@RecordLockAction_LockStatus
		begin

			IF @l_idLock is not null
			begin
				--IF @locking = 1
				--begin
				--	-- report lock already existing, regardless of user
				--	set @IDLogin = @l_idLogin
				--	set @IDSession = @l_idSession
				--	set @IDWorkstation = @l_idWorkstation
				--	set @IDResource = @l_idResource

				--	return 1
				--end
				--else
				--begin
				--	-- @locking = 2, report that lock is on
				--	set @IDLogin = @l_idLogin
				--	set @IDSession = @l_idSession
				--	set @IDWorkstation = @l_idWorkstation
				--	set @IDResource = @l_idResource

				--	return 0
				--end
				IF @l_idLogin != @IDLogin OR @IDSession != @l_idSession
				begin
					-- Record is already locked by another user+session
					set @IDLogin = @l_idLogin
					set @IDResource = @l_idResource
					set @IDSession = @l_idSession
					set @IDWorkstation = @l_idWorkstation

					return 1
				end 
				else 
				begin

					IF @locking = 1
					begin
						-- Try to Renew Lock
						-- TODO this can fail due to lock expiration?
						UPDATE SysLockRecord SET StartDate = GETUTCDATE() WHERE IdLock = @l_idLock AND Token = @o_token
					end
				
					-- TODO check if our token was reset

					return 0
				end

			end -- end IF @l_idLock is not null
			else
			begin
				-- Record is not locked

			
				IF @locking = 1 OR @locking = @RecordLockAction_LockStatus
				begin
					-- Lock Record and return success

					DECLARE @StartDate DATETIME
					SET @StartDate = GETUTCDATE()
					
					if @o_token is null  or @o_token = ''
					begin
						SET @o_token = CONVERT(VARCHAR(32),HashBytes ('MD5',CONCAT( CONVERT(VARCHAR(19),GETUTCDATE(),131) ,CONCAT(@IDRecord, @IDModule))),2) 
					end

					
					
					SET @MainTable = ISNULL(@MainTable, '')
					SET @MainTablePk = ISNULL(@MainTablePk, '')
					SET @MainTableModId = ISNULL(@MainTableModId, '')

					IF @MainTable != '' AND @MainTablePk != '' AND @MainTableModId != ''
					BEGIN
						
						set @sql = concat('select @oldValue = RegisterStatus from ', @MainTable, ' where ', @MainTablePk, ' = ''', @IDRecord, ''' AND ', @MainTableModId, ' = ''', @IDModule, '''');

						print concat('sql is ', @sql)
						exec sp_executesql @sql, N'@oldValue int output', @oldValue = @o_registerStatusOld output;

						--print concat('OldRegisterStatus is ', @o_registerStatusOld);

						IF  (@locking = 1 AND @o_registerStatusOld != @expectedRegisterStatus)
						 OR( @locking = @RecordLockAction_LockStatus AND 
							( @o_registerStatusOld !=@alternativeExpectedRegisterStatusForLockStatusClosed 
								AND @o_registerStatusOld != @alternativeExpectedRegisterStatusForLockStatusCanceled
								AND  @o_registerStatusOld !=@expectedRegisterStatus))
						begin
							-- error! record cant be locked
							return 7
						end
					END
					

					INSERT INTO SysLockRecord(IDRecord, IDModule, TypeRegister, Token, ActualStartDate, StartDate, IDLogin, IDResource, IDSession, MainTab, MainTabPk, MainTabModId, OldRegisterStatus, [Status])
					VALUES(@IDRecord, @IDModule, '', @o_token, @StartDate, @StartDate, @IDLogin, @IDResource, @IDSession, @MainTable, @MainTablePk, @MainTableModId, @o_registerStatusOld, 1)

					-- if insert works, set registerstatus to inEditing
					if @MainTable != '' AND @MainTablePk != '' AND @MainTableModId != ''
					begin
						set @sql = concat('update ', @MainTable, ' set RegisterStatus = ', @registerStatus, ' where ', @MainTablePk, ' = ''', @IDRecord, ''' AND ', @MainTableModId, ' = ''', @IDModule, '''')
						print concat('sql is ', @sql)

						exec sp_executesql @sql
					end

					SET @IDWorkstation = (select IDWorkstation from SysSession where IDSession = @IDSession)

					RETURN 0
				END
				ELSE IF @locking = 2
				BEGIN 
					set @o_actualStartDate = @l_actualDateStart

					RETURN 4
				END
			
			END
		END
		ELSE IF @locking = 0 OR @locking = 4
		BEGIN
			-- The "Owner" of a lock is the user+session that holds the lock
			-- A lock / session is considered "Dead" if it has timedout or forcefully closed already

			-- Only the owner of the lock can unconditionally remove it
			-- The user of a lock can remove it only if the session is dead of if the lock is dead or by forcefully unlocking 
			
			
			DECLARE @canDelete INT
			SET @canDelete = -1


			IF (@IDLogin = @l_idLogin AND @IDSession = @l_idSession) OR (@IDLogin = @l_idLogin AND @locking = 4)
			BEGIN
				SET @canDelete = 0
			END
			ELSE 
			BEGIN
				print 'same login but different session'

				-- Check if either session is dead or lock is dead
				DECLARE @sessionTimeout INT
				SET @sessionTimeout = (SELECT top 1 SessionTimeout FROM SysSettings)
				if @ignoreTimeouts = 1 or @sessionTimeout is null
				begin
					set @sessionTimeout = 999999
				end

				print concat('session timeout is ', @sessionTimeout)

				DECLARE @s_IDSession UNIQUEIDENTIFIER, @s_DateStart DATETIME, @s_DateEnd DATETIME

				SELECT @s_IDSession = IDSession, @s_DateStart = DateStart, @s_DateEnd = DateEnd FROM SysSession WHERE IDSession = @l_idSession

				print concat('sessionID = ', @s_IDSession, ' Start = <<', @s_DateStart, '>> End = <<', @s_DateEnd, '>> Session duration = ', DATEDIFF(minute, @s_DateStart, GETUTCDATE()))

				IF @s_IDSession IS NOT NULL AND (@s_DateEnd IS NULL AND @sessionTimeout > DATEDIFF(minute, @s_DateStart, GETUTCDATE())) AND @locking != 4
				BEGIN
					-- Session is still active
					print 'session is still active'
					SET @canDelete = 6
				END
				ELSE
				BEGIN
					-- Session is dead, so lock can be reclaimed
					print 'session is dead'
					SET @canDelete = 0
				END

				IF @canDelete != 0
				BEGIN
				

					DECLARE @lockedTimeout INT
					SET @lockedTimeout = (SELECT top 1 LockedTimeout FROM SysSettings)
					if @ignoreTimeouts = 1 or @lockedTimeout is null 
					begin
						set @lockedTimeout = 999999
					end

					print concat('lock timetout is ', @sessionTimeout)

					if @lockedTimeout < DATEDIFF(minute, @l_startDate, GETUTCDATE()) or @locking = 4
					begin
						print 'lock is dead'
						SET @canDelete = 0
					end
					else
					begin
						-- lock is still alive, so it wont be deleted
						print 'lock is still alive'
						SET @canDelete = 5
					end

					SET @canDelete = 5

				END -- IF @canDelete != 0
			END -- @IDLogin = @l_idLogin AND @IDSession = @l_idSession
			
			
			IF @canDelete = 0
			BEGIN
				--print 'deleting lock'

				-- TODO reset registerstatus

				SELECT @mainTable = MainTab, @MainTablePk = MainTabPk, @MainTableModId = MainTabModId, @o_registerStatusOld = OldRegisterStatus
				FROM SysLockRecord
				WHERE @o_token = Token AND @IDModule = IDModule AND @IDRecord = IDRecord AND [Status] = 1

				SET @MainTable = ISNULL(@MainTable, '')
				SET @MainTablePk = ISNULL(@MainTablePk, '')
				SET @MainTableModId = ISNULL(@MainTableModId, '')
				DECLARE @params NVARCHAR(MAX)
				DECLARE @canUnlock INT
				SET @canUnlock=1

				if @MainTable != '' AND @MainTablePk != '' AND @MainTableModId != '' and not @o_registerStatusOld is null
				begin
					---set @sql = concat('UPDATE ', @MainTable, ' set RegisterStatus = ', @o_registerStatusOld ,' where ', @MainTablePk, ' = ''', @IDRecord, ''' AND ', @MainTableModId, ' = ''', @IDModule, '''')

				  SET @sql = N'UPDATE ' + QUOTENAME(@MainTable) + 
							   N' SET RegisterStatus = @o_registerStatusOld WHERE ' + 
							   QUOTENAME(@MainTablePk) + N' = @IDRecord AND ' + 
							   QUOTENAME(@MainTableModId) + N' = @IDModule'
    
					SET @params = N'@o_registerStatusOld NVARCHAR(255), @IDRecord NVARCHAR(255), @IDModule NVARCHAR(255)'
    
					--print concat('sql is ', @sql)
						BEGIN TRY
						-- Execute the parameterized SQL statement
						EXEC sp_executesql @sql, @params, 
										   @o_registerStatusOld = @o_registerStatusOld, 
										   @IDRecord = @IDRecord, 
										   @IDModule = @IDModule
					END TRY
					BEGIN CATCH
						SET @canUnlock=0
						-- Log the error message and other relevant information
						--PRINT 'Error occurred during sp_executesql execution'
						--PRINT ERROR_MESSAGE()
							DECLARE @errorMsg nvarchar(max)
						SET @errorMsg= CONCAT('Token: ', @o_token, ', IDModule: ', @IDModule, ', IDRecord: ', @IDRecord, ', RegisterStatus: ', @o_registerStatusOld, ', sql: ', @sql, ', Error: ',ERROR_MESSAGE())
						INSERT INTO Log4Net(Date,Thread,Level,Logger,Message,Exception)
									VALUES (GETUTCDATE(),'SQL SERVER','ERROR','SP Try_LockRecordForEdition ','Error occurred during sp_executesql execution',@errorMsg)
					END CATCH
				end

				--print concat('deleting(', @o_token, ', ', @IDModule, ', ', @IDRecord, ')')
				if(@canUnlock =1)
				begin
						UPDATE SysLockRecord 
							SET [Status] = 0, 
								[EndDate] = GETUTCDATE(), 
								[EndSrc] = @src 
						WHERE @o_token = Token 
						  AND @IDModule = IDModule 
						  AND @IDRecord = IDRecord
						  AND [Status] = 1
						return 0
				end
				else
				begin
					return 5 -- ?? or new error
				end
			END
			ELSE IF @canDelete > -1
			BEGIN
				return @canDelete
			END
			else 
			begin
				-- RAISEERROR(N'shouldnt fall here', 16, 1);
				return 1
			end
		END

	END -- end ELSE @locking = 4 
	

	RETURN 0
END
GO


