-- ----------------------------
-- procedure structure for GetRemainingWork
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRemainingWork]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetRemainingWork]
GO

CREATE PROCEDURE [dbo].[GetRemainingWork]
	-- Add the parameters for the stored procedure here
		@Factor float,
		@Optype uniqueidentifier,
		@Parent uniqueidentifier,
		@FreeNodes uniqueidentifier,
		@Resource uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
		SET NOCOUNT ON;

    CREATE TABLE #PartsInCell
	(
	   ID uniqueidentifier
	)

	CREATE TABLE #PartsInCell4
	(
	   ID uniqueidentifier
	)
	CREATE TABLE #PartsInCell2
	(
	   ID uniqueidentifier,
	   Resources nvarchar(250) collate Latin1_General_CI_AS
	)

	CREATE TABLE #PartsInCell3
	(
	   ID uniqueidentifier,
	   timerem int,
	   timeremfactor int
	)

	CREATE TABLE #NodesNotInCell
	(
	   ID uniqueidentifier
	)

	DECLARE @parentNode uniqueidentifier

Create TABLE #tempTable 
(Parent uniqueidentifier, Node uniqueidentifier)

DECLARE parent_cursor CURSOR FOR 
SELECT Distinct IDStorage as IDStorage FROM SM_NodePosicConfiguration WHERE WorkAssignment = 1 AND IDOperationType = @Optype AND IDStorage IS NOT NULL AND IDStorage <> '00000000-0000-0000-0000-000000000000'

OPEN parent_cursor  
FETCH NEXT FROM parent_cursor INTO @parentNode  

WHILE @@FETCH_STATUS = 0  
BEGIN  
      
	  INSERT INTO #tempTable(Parent, Node) SELECT @parentNode, id FROM dbo.[SM_GetNOdeChilds](@parentNode)
      FETCH NEXT FROM parent_cursor INTO @parentNode 
END 

CLOSE parent_cursor  
DEALLOCATE parent_cursor 

	

	INSERT INTO #NodesNotInCell SELECT id FROM dbo.[SM_GetNOdeChilds](@FreeNodes)

	IF @Parent = cast(cast(0 as binary) as uniqueidentifier) 
		BEGIN
			INSERT INTO #PartsInCell SELECT DISTINCT(COALESCE(IDNodePartReserved, IDNodePartDocked)) FROM SM_NodePosic
			 WHERE (IDNodePartDocked IS NOT NULL OR IDNodePartReserved IS NOT NULL) 
			 AND ( 
				ID NOT IN (SELECT ID FROM #NodesNotInCell  ) 
				AND
				IDNodePosicParent is not null and IDNodePosicParent <> '00000000-0000-0000-0000-000000000000')
		END
	ELSE
		BEGIN
			--INSERT INTO #PartsInCell SELECT COALESCE(IDNodePartReserved, IDNodePartDocked) FROM SM_NodePosic WHERE (IDNodePartDocked IS NOT NULL OR IDNodePartReserved IS NOT NULL) 
			--AND ( 
			--	ID IN (SELECT id FROM dbo.[SM_GetNOdeChilds](@Parent)) 
			--	OR 
			--	ID IN (SELECT IDNode FROM SM_NodePosicConfiguration WHERE IDStorage = @Parent))
			INSERT INTO #PartsInCell SELECT DISTINCT(COALESCE(IDNodePartReserved, IDNodePartDocked)) FROM SM_NodePosic WHERE 
(IDNodePartDocked IS NOT NULL OR IDNodePartReserved IS NOT NULL) 
AND ( ID IN (SELECT id FROM dbo.[SM_GetNOdeChilds](@Parent)) OR 
ID IN (SELECT Distinct(p.IDNodePosic) FROM SM_NodePosicConfiguration c
INNER JOIN SM_NodePart p ON p.IDEntryPosition = c.IDNode
 WHERE IDStorage = @Parent AND IDNode IS NOT NULL AND IDNode <> '00000000-0000-0000-0000-000000000000')
)
		END
	
	INSERT INTO #PartsInCell SELECT ID FROM SS_Object WHERE BlankNeeded = 1 AND ID NOT IN (SELECT ID FROM #PartsInCell)

	INSERT INTO #PartsInCell4 SELECT ID FROM #PartsInCell WHERE ID IN (SELECT ID FROM SS_Object WHERE IDRoutine IS NOT NULL AND Visibility = 0 ) AND ID IN (SELECT IDPart FROM SysJobPart 
				WHERE IDJob IN (SELECT ID FROM SysJob WHERE IDOperationType = @Optype AND Status NOT IN(
				'88B381D9-D1DB-4C80-8E78-3076B1E196F2', 
				'2F2593EC-D358-493E-B02C-3DB5A912C399', 
				'5FF6EB53-52F6-4A50-83AE-B23CC8C44054', 
				'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70'
				)
				) )
	INSERT INTO #PartsInCell2(ID, Resources) (SELECT c4.ID, 
	COALESCE
					( 
						(
							SELECT STUFF
								((
										
										SELECT Distinct ', '+ code as Code FROM dbo.GetResourcesPrevisionV2(c4.ID,@Optype, tt.Parent)
									ORDER BY ', ' + Code FOR XML PATH(''), TYPE
						).value('.[1]', 'nvarchar(max)'), 1, 2, '')) ,'') collate Latin1_General_CI_AS 
						 as Resources
	FROM #PartsInCell4 c4
	INNER JOIN SM_NodePart np ON np.ID = c4.ID
	INNER JOIN #tempTable tt ON tt.Node = np.IDEntryPosition)
	 

	 INSERT INTO #PartsInCell3(ID, timerem, timeremfactor) (SELECT ID, COALESCE(dbo.GetCurrentTimeToEnd(ID,@Optype,1),0), COALESCE(dbo.GetCurrentTimeToEnd(ID,@Optype,@Factor),0) FROM #PartsInCell4)


	SELECT 
		b.ID, 
		b.PriorityManagement,
		ISNULL(CONCAT(dbo.SS_GetClientName(b.ID) + '_',COALESCE(RTRIM(LTRIM(b.FullName)),RTRIM(LTRIM(b.ShortName)))),'' ) as [FullName],
		dbo.GetTimeFromSeconds(COALESCE(tempS7 - pic2.timerem,0)) as [S7], 
		COALESCE(tempS7 - pic2.timerem,0) AS S7Val, 
		dbo.GetTimeFromSeconds(SUM(COALESCE(tempS7 - pic2.timerem,0)) OVER(ORDER BY b.Evaluation DESC,b.Priority DESC, b.FullName, b.MinJob ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT  ROW)) as [SUM_S7], 
		dbo.GetTimeFromSeconds(COALESCE([tempS7p] - pic2.timeremfactor,0)) as [S7p], 
		COALESCE([tempS7p]- pic2.timeremfactor,0) AS S7pVal, 
		dbo.GetTimeFromSeconds(SUM(COALESCE([tempS7p]- pic2.timeremfactor,0)) OVER(ORDER BY b.Evaluation DESC,b.Priority DESC, b.FullName, b.MinJob ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT  ROW)) as [SUM_S7p] ,
		Position , 
		Priority, 
		ROUND(Evaluation, 2) as [Evaluation], 
		IDPriority,
		SetPosition, 
		LTRIM(RTRIM(Resource)) as Resource,
		pt.Code as [ProgramType], 
		InFault, 
		Errors  ,
		CASE 
				WHEN Resource IS NOT NULL AND Resource <> ''  
				THEN 
					LTRIM(RTRIM(Resource))
				ELSE 
				---''
					LTRIM(RTRIM(pic.Resources))
						
			END as ResourcePrev 
		FROM
		(  
			SELECT 
				o.ID, 
				o.FullName, 
				o.ShortName, 
				MAX(o.PriorityManagement) AS PriorityManagement,
				ot.IdOperationType, 
				ot.Code as [Operation],  
				SUM(p.EstimatedTime) AS [tempS7], 
				SUM(p.EstimatedTime) * @Factor AS [tempS7p] , 
				CASE 
					WHEN o.BlankNeeded = 1 AND LTRIM(RTRIM(n.Code)) IS NULL THEN 'Waiting for Blank' 
					WHEN o.BlankNeeded = 1 AND LTRIM(RTRIM(n.Code)) IS NOT NULL THEN LTRIM(RTRIM(n.Code)) 
					WHEN o.BlankNeeded <> 1 AND  n.WorkPosition = 1 THEN 
					 CONCAT(LTRIM(RTRIM(n.Code)) , CONCAT(' (', CONCAT(LTRIM(RTRIM(n.MachineCode)),')'))) 
					WHEN o.BlankNeeded <> 1 AND n.WorkPosition <> 1 THEN LTRIM(RTRIM(n.Code)) 

				END as Position,    
				CASE 
					WHEN MAX(o.Priority) = 1 THEN 'Very Low' 
					WHEN MAX(o.Priority) = 2 THEN 'Low' 
					WHEN MAX(o.Priority) = 3 THEN 'Normal'  
					WHEN MAX(o.Priority) = 4 THEN 'High' 
					WHEN MAX(o.Priority) = 5 THEN 'Urgent' 
				END As Priority, 
				MAX(o.Priority) AS 'IDPriority',  
				dbo.GetMaxEvaluation(o.ID, @Optype) AS Evaluation , 
				CASE 
					WHEN j.IDResource IS NOT NULL AND j.IDResource <> cast(cast(0 as binary) as uniqueidentifier)  THEN 1
					ELSE 0
				END	AS SetPosition, 
				CASE 
					WHEN j.IDResource IS NOT NULL AND j.IDResource <> cast(cast(0 as binary) as uniqueidentifier)  THEN n1.Code 
					WHEN n.WorkPosition IS NOT NULL AND n.WorkPosition = 1  THEN (SELECT LTRIM(RTRIM(Code)) FROM SysResources WHERE ResourceId = n.MachineID)
					ELSE '' 
				END as Resource , 
				
				MAX(p.FileType) AS [Program Type] , 
				COALESCE(dbo.GetInFault(o.ID, @Optype), '') AS[InFault],  
				COALESCE(dbo.GetErrorRequestCount(o.ID, @Optype), '0') As[Errors] , 
				Min(j.ID) as MinJob
			FROM SysJob j 
			LEFT JOIN SysJobPart jp ON j.ID = jp.IDJob   
			LEFT JOIN SS_Object o ON jp.IDPart = o.ID  
			LEFT JOIN SysOprRoutineItem opr ON jp.IDPart = opr.IDPart AND opr.IDOperationType = @Optype
			INNER JOIN SysJobLine jl ON j.ID = jl.IDJob AND j.IDOperationType = @Optype 
			LEFT JOIN SysOperationType ot ON j.IDOperationType = ot.IdOperationType  
			LEFT JOIN SM_NodePart n2 ON o.ID = n2.ID  
			LEFT JOIN SM_NodePosic n ON n.ID = n2.IDEntryPosition 
			LEFT JOIN SysResources n1 ON j.IDResource = n1.ResourceId  
			LEFT JOIN SS_Program p ON p.ID = jl.IDProgram  
			WHERE 
			o.ID IN (SELECT ID FROM #PartsInCell4) 
			AND j.IDOperationType = @Optype 
			AND j.Status NOT IN(
				'88B381D9-D1DB-4C80-8E78-3076B1E196F2', 
				'2F2593EC-D358-493E-B02C-3DB5A912C399', 
				'5FF6EB53-52F6-4A50-83AE-B23CC8C44054', 
				'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70'
			)  
			AND jl.LineType = 0 
			AND jl.Active = 1  
			AND jl.Status NOT IN(
				'88B381D9-D1DB-4C80-8E78-3076B1E196F2', 
				'2F2593EC-D358-493E-B02C-3DB5A912C399', 
				'5FF6EB53-52F6-4A50-83AE-B23CC8C44054', 
				'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70'
			)  
			AND 1 = 
				CASE 
					WHEN 
						@Resource <> cast(cast(0 as binary) as uniqueidentifier) AND (j.IDResource = @Resource ) 
							THEN 1
					WHEN 
						@Resource = cast(cast(0 as binary) as uniqueidentifier) 
							THEN 1
					ELSE 0
				 END
			
			GROUP BY 
				o.ID, 
				o.Priority, 
				o.FullName, 
				o.ShortName, 
				ot.IdOperationType, 
				ot.Code, 
				n.Code, 
				n.MachineCode, 
				n.WorkPosition,
				n.MachineID,
				n1.Code,
				j.IDResource,
				o.BlankNeeded
		) as b  
	LEFT JOIN SS_ProgramType pt ON b.[Program Type] = pt.ID  
	LEFT JOIN #PartsInCell2 pic ON pic.ID = b.ID
	LEFT JOIN #PartsInCell3 pic2 ON pic2.ID = b.ID
	ORDER BY 
		b.Evaluation DESC, 
		b.IDPriority DESC, 
		b.FullName,
		b.MinJob ASC

	DROP TABLE #PartsInCell
	DROP TABLE #PartsInCell2
	DROP TABLE #PartsInCell3
	DROP TABLE #PartsInCell4
	DROP TABLE #NodesNotInCell
	DROP TABLE #tempTable

END
GO


-- ----------------------------
-- function structure for GetEmailsForEntity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetEmailsForEntity]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetEmailsForEntity]
GO

CREATE FUNCTION [dbo].[GetEmailsForEntity] 
(	
	@IdRecord int,
	@IdModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	select organizationid, idModule, name, email, kind, kindtext,IDLogin
	from (
		select organizationid, idModule, 1 as kind, '<geral>' as name, email, '' as kindtext,null as IDLogin
		from  Entity
		where organizationid = @IdRecord and IDModule = @IdModule and isnull(email, '') != ''
	union
		select organizationid, idModule, 2 as kind, '<geral>', email2, 'secondary email' as kindtext,null as IDLogin
		from  Entity
		where organizationid = @IdRecord and IDModule = @IdModule and isnull(email2, '') != ''
	union

		select c.organizationid, c.idModule, 1 as kind, c.accountname,
		CASE WHEN isnull(e2e.Email, '') != '' then e2e.Email
		else
		c.email
		END
		, '' kindtext,null as IDLogin
		from 
			Entity2Entity e2e
			inner join Entity c on e2e.IDRecEntityChild = c.organizationid
		where
			e2e.IDRecEntity = @IdRecord and e2e.IDRecEntityModule = @IdModule
			and  (isnull(e2e.Email, '') != '' OR isnull(c.email, '') != '')
	--union 
	--	select c.organizationid, c.idModule, 1 as kind, c.accountname, c.email, '' as kindtext,null as IDLogin
	--	from 
	--		Entity2Entity e2e
	--		inner join Entity c on e2e.IDRecEntityChild = c.organizationid
	--	where
	--		e2e.IDRecEntity = @IdRecord and e2e.IDRecEntityModule = @IdModule and isnull(c.email, '') != ''
	union
		select c.organizationid, c.idModule, 2 as kind, c.accountname, c.email2, 'secondary email' kindtext,null as IDLogin
		from 
			Entity2Entity e2e
			inner join Entity c on e2e.IDRecEntityChild = c.organizationid
		where
			e2e.IDRecEntity = @IdRecord and e2e.IDRecEntityModule = @IdModule and isnull(c.email2, '') != ''
	union
		select c.organizationid,c.IDModule,3 as kind,c.accountname,c.email,'Login email' kindtext,l.IDLogin
		from [dbo].[Entity] c
		Inner join SysLogin l ON l.IDLogin=c.IDRelatedLogin 
		where l.active =1 and isnull(c.email, '') != ''
	union
		select c.organizationid,c.IDModule,3 as kind,c.accountname,c.email2,'Login email 2' kindtext,l.IDLogin
		from [dbo].[Entity] c
		left join SysLogin l ON l.IDLogin=c.IDRelatedLogin 
		where l.active =1 and isnull(c.email2, '') != ''
	) aux
)
GO


-- ----------------------------
-- function structure for GetSysTaskChannels
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetSysTaskChannels]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetSysTaskChannels]
GO

CREATE FUNCTION [dbo].[GetSysTaskChannels]
(
	@idTask uniqueidentifier
)
RETURNS nvarchar(max)
AS
BEGIN
			
	declare @t nvarchar(max)
	set @t = ''

	declare @u nvarchar(max)

	declare it cursor for 
		select SysWorkRoom.[Name]
		from SysTask with(nolock)
			inner join SysTask2Channel with(nolock) on SysTask.IDTask = SysTask2Channel.IDTask
			inner join SysWorkRoom with(nolock) on SysTask2Channel.IDChannel = SysWorkRoom.IDWorkRoom
		where
			SysTask.IDTask = @idTask

	open it

	fetch next from it into @u

	while @@FETCH_STATUS = 0
	begin
		if @u != '' and not @u is null
		begin
			set @t = CONCAT(@t, case when @t = '' then '' else ', ' end, @u)
		end
		fetch next from it into @u
	end

	close it
	deallocate it

	set @t = TRIM(@t)
	
	RETURN @t
END
GO


-- ----------------------------
-- procedure structure for CheckActiveVehicleTrackerResourceConnection
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CheckActiveVehicleTrackerResourceConnection]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CheckActiveVehicleTrackerResourceConnection]
GO

CREATE PROCEDURE [dbo].[CheckActiveVehicleTrackerResourceConnection]
AS
BEGIN
	with activeConnections as(
		select a2r.ID
		from VehicleTracker2SysResource a2r
		where 
		(
			(GETDATE() between a2r.StartDate and a2r.EndDate) or
			(a2r.StartDate is null or a2r.EndDate is null)
		)
	)
	UPDATE VehicleTracker2SysResource set Active = 
	case 
		when id in(
			select ID from activeConnections
		) then 1
		else 0
	end;
END
GO


-- ----------------------------
-- procedure structure for UpdateAccountRootMovementParent
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAccountRootMovementParent]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAccountRootMovementParent]
GO

CREATE PROCEDURE [dbo].[UpdateAccountRootMovementParent]
(
	@IDAccount int,
	@IDModule uniqueidentifier
)
AS
BEGIN
	
	declare @IDParentAccount int; 
	declare @MovementRoot int;
	declare @MovementRootParent int;

	select @IDParentAccount = acc.IDParent , @MovementRoot = pc.IDPocValue,  @MovementRootParent = pc.IDParent
	from Account acc
	inner join SysPocValue pc on pc.IDRecord = acc.IDAccount and pc.IDRecordModule = acc.IDModule and pc.MovementMode = 3
	where IDAccount = @IDAccount and IDModule = @IDModule;

	if @IDParentAccount is not null and @MovementRootParent is null
	begin
		update SysPocValue set IDParent = (select top 1 IDPocValue from SysPocValue where IDRecord = @IDParentAccount and MovementMode = 3)
		where IDPocValue = @MovementRoot;
	end
END
GO


