-- ----------------------------
-- procedure structure for FillAccountParentCostCenter
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FillAccountParentCostCenter]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[FillAccountParentCostCenter]
GO

CREATE PROCEDURE [dbo].[FillAccountParentCostCenter]
(
	@IDAccount int,
	@IDModule uniqueidentifier
)
AS
BEGIN
	
	declare @IDParentAccount int; 
	declare @IDParentAccountModule uniqueidentifier; 
	declare @HasDefaultCostCenterAccount int

	select @HasDefaultCostCenterAccount = count(*)
	from GetModulesRec(@IDModule)
	where AccountCostCenterParent is not null;

	select @IDParentAccount = acc.IDParent
	from Account acc
	where IDAccount = @IDAccount and IDModule = @IDModule;

	if @IDParentAccount is null and @HasDefaultCostCenterAccount > 0
	begin
		declare @CurrentModule uniqueidentifier = @IDModule;		
		set @IDParentAccount = null;
		set @IDParentAccountModule = null;
		declare @HasParent int = (select top 1 case when IDParent is null then 0 else 1 end from SysModule where IDModule = @CurrentModule);
		while @HasParent = 1 and @IDParentAccount is null
		begin
			set @IDParentAccount = (select top 1 AccountCostCenterParent from SysModule where IDModule = @CurrentModule);
			set @IDParentAccountModule = (select top 1 AccountCostCenterParentModule from SysModule where IDModule = @CurrentModule);
			set @CurrentModule = (select top 1 IDParent from SysModule where IDModule = @CurrentModule);
			set @HasParent = (select top 1 case when IDParent is null then 0 else 1 end from SysModule where IDModule = @CurrentModule);
		end

		update Account set IDParent = @IDParentAccount, IDParentModule = @IDParentAccountModule where IDAccount = @IDAccount;
	end
END
GO


