CREATE PROCEDURE [dbo].[CloseSession]
	@IDSession uniqueidentifier,
	@Force bit = 0
AS
BEGIN	
	SET NOCOUNT ON;

	 
	declare @sessionTimeoutMin int

	if @sessionTimeoutMin is null
	begin
		SET @sessionTimeoutMin = (select top 1 SessionTimeout from SysSettings) --(SELECT CASE WHEN ISNUMERIC(Value) = 1 THEN CAST(Value AS INT) ELSE 9999 END Value FROM SysSettings WHERE Name = 'SessionTimeout')
	end
	
	if @sessionTimeoutMin is null
	begin
		set @sessionTimeoutMin = 9999
	end
	
	-- session can be closed if it has no accessKey, or if it does and it has expired
	set @IDSession = (SELECT IDSession
					FROM SysSession 
					WHERE IDSession = @IDSession 
						AND 
						(@Force = 1 OR 
							((NOT AccessKey IS NULL AND @sessionTimeoutMin <= DATEDIFF(minute, DateStart, GETUTCDATE()))
							OR
							(AccessKey IS NULL))
						 OR 
						 (IDApplication = '778ee9c6-18ad-4d37-8e54-677897e8fc2d')));

	IF @IDSession IS NULL
	BEGIN
		RETURN 0
	END;

	 

    declare CloseSession_it cursor 
		LOCAL STATIC READ_ONLY FORWARD_ONLY
		for
		select Token, IDModule, IDRecord, IDSession, IDLogin
		from SysLockRecord
		where IDSession = @IDSession AND [Status] = 1;

	open CloseSession_it;

	declare @l_Token nvarchar(50), @l_IDModule uniqueidentifier, @l_IDRecord nvarchar(36), @l_IDSession uniqueidentifier, @l_IDLogin uniqueidentifier;

	fetch next from CloseSession_it into @l_Token, @l_IDModule, @l_IDRecord, @l_IDSession, @l_IDLogin
	while @@FETCH_STATUS = 0
	begin
		
		exec [dbo].[Try_LockRecordForEdition] @locking = 0, @IDRecord = @l_IDRecord, @IDModule = @l_IDModule, @IDSession = @l_IDSession, @IDWorkstation = NULL, 
			@IDLogin = @l_IDLogin, @IDResource = NULL, @MainTable = '', @MainTablePk = '', @MainTableModId = '', @IDModuleFilterView = null, @o_token = @l_Token,
			@src = 3

		fetch next from CloseSession_it into @l_Token, @l_IDModule, @l_IDRecord, @l_IDSession, @l_IDLogin
	end;

	close CloseSession_it;
	deallocate CloseSession_it;

	DELETE FROM SysLockResource WHERE IDSession = @IDSession;

	DELETE FROM SysSession WHERE IDSession = @IDSession;

	delete from sysSessionInfo where idsession = @idsession

	print concat('deleted session ', @idSession)
END
GO


-- ----------------------------
-- function structure for GetMovementParentsRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetMovementParentsRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
