GO

CREATE FUNCTION [dbo].[GetMovementParentsRec]
(	
	@IDMovement int
)
RETURNS TABLE 
AS
RETURN 
(
	with GetMovementsRec as (
		select IDPocValue, IDParent
		from SysPocValue
		where IDPocValue = @IDMovement
		union all
		select c.IDPocValue, c.IDParent
		from SysPocValue c 
		inner join GetMovementsRec p on c.IDPocValue = p.idparent
	)
	select p.*
	from SysPocValue p
		inner join
		GetMovementsRec rec on p.IDPocValue = rec.IDPocValue
)
GO


