-- ----------------------------
-- procedure structure for Query_LeadTimeToQualification
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_LeadTimeToQualification]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_LeadTimeToQualification]
GO

CREATE PROCEDURE [dbo].[Query_LeadTimeToQualification]
AS 
BEGIN
	
	SET NOCOUNT ON;

	
select 
	l.CreatedTime, 
	isnull(switchToQualif.StartDate, 
	case when status != 417 then
		l.CreatedTime
	else 
		NULL
	end
	 ) as QualificationTime, 

	 	isnull(DATEDIFF(day, l.CreatedTime, switchToQualif.StartDate), 
	case when [status] != 417 then
		0
	else 
		NULL
	end)
	as 
	daysToQualif,

	l.lead_no, email, phone, mobilephone, companyPhone, lastname, r.Code as ResourceAssigned

	from Leads l 
	inner join SysResources r on l.IDResourceAssign = r.ResourceId
	left join (
	
	select idrecord, min(StartDate) as StartDate
	from SysModuleTracker 
	where IDModuleTracker in (

	select IDModuleTracker
	from SysModuleTrackerDetail
	where IDModuleTracker in (select IDModuleTracker
	from SysModuleTracker
	where IDModule in
	('F992F837-5A07-420D-BF9D-3C4FD807CD51',
	'A7D2372E-4EF7-4F2A-B21A-7EE1F24D88DC')
	) 
	and 
	(
		(FieldName = 'Lead Status' and cast(OldValue as nvarchar(max)) = 'NotQualified' and cast(NewValue as nvarchar(max)) != 'NotQualified')
		or 
		(IDDSItem = 'F06467D0-8490-4424-A84F-95BEAA633362' and cast(OldValue as nvarchar(max)) = '417' and cast(NewValue as nvarchar(max)) != '417')
	)

	)
	group by IDRecord

	) switchToQualif on l.IDLead = switchToQualif.IDRecord
	where IDModule in
	('F992F837-5A07-420D-BF9D-3C4FD807CD51',
	'A7D2372E-4EF7-4F2A-B21A-7EE1F24D88DC')

	and year(createdtime) = 2017 and RegisterSysStatus = 0


END
GO


