-- ----------------------------
-- procedure structure for GetWorkingTimeByPosition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetWorkingTimeByPosition]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetWorkingTimeByPosition]
GO

CREATE PROCEDURE [dbo].[GetWorkingTimeByPosition]
	-- Add the parameters for the stored procedure here
	@IDPOSIC as UniqueIdentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

 --   DECLARE @IDPOSIC as UniqueIdentifier
 --SET @IDPOSIC = '407685e2-6e6b-4c4b-a5af-5dbcadf5d990'
 
 DECLARE @DAYSBEHIND int
 SET @DAYSBEHIND = -30
 
 DECLARE @StartDate AS DATETIME  
 DECLARE @EndDate AS DATETIME  
 DECLARE @CurrentDate AS DATETIME  
 DECLARE @ProductTotals TABLE 
 (   
	Date datetime,  
	Duration int,  
	IDPosition uniqueidentifier,  
	Code nvarchar(150)
)  
DECLARE @PNAME Nvarchar(100)
SET @PNAME = (SELECT LTRIM(RTRIM(Code)) FROM SM_NodePosic WHERE ID = @IDPOSIC )
SET @EndDate = CONVERT(date, GETDATE())  
SET @StartDate = CONVERT(date, DATEADD(d, @DAYSBEHIND, @EndDate))  
SET @CurrentDate = @StartDate  
WHILE(@CurrentDate <= @EndDate)  
BEGIN  INSERT INTO @ProductTotals(Date, Duration, IDPosition, Code)  
SELECT 
	CONVERT(date, @CurrentDate) AS Date,  
	CASE WHEN CONVERT(date, t.StartDate) = CONVERT(date, t.endDate) 
		THEN DATEDIFF(s, t.startdate, t.enddate)  
	WHEN CONVERT(date, t.endDate) > CONVERT(date, @CurrentDate) AND CONVERT(date, t.startDate) = CONVERT(date, @CurrentDate)
		THEN DATEDIFF(s, t.startDate, DATEADD(d, 1, @CurrentDate))  
	WHEN CONVERT(date, t.endDate) > CONVERT(date, @CurrentDate) AND CONVERT(date, t.startDate) < CONVERT(date, @CurrentDate)
		THEN 24*60*60 
	ELSE 
		DATEDIFF(s, CONVERT(date, @CurrentDate), t.endDate) 
	END 
	AS Duration, 
	@IDPOSIC,
	@PNAME 
FROM (
SELECT r.ID, MIN(a.startdate) as startDate, MAX(a.endDate) as endDate
FROM
SysTimes a
INNER JOIN SysPrRoutineRequest r   ON r.ID = a.IDRequest  

WHERE r.IDJob > 0 
AND r.StartDate >= CONVERT(date, DATEADD(d, @DAYSBEHIND, GETDATE()))  
--AND a.IDRoutineItem IS NOT NULL 
AND r.IDPosition IN (SELECT ID FROM SM_NodePosic WHERE WorkPosition = 1 AND MACHINEID IN (
SELECT MachineID FROM SM_Nodeposic WHERE ID = @IDPOSIC  
)
)
AND ( 
	(a.startDate > @CurrentDate AND a.startDate < DATEADD(d, 1, @CurrentDate)) 
	OR 
	(a.startDate < @CurrentDate AND a.endDate >= @CurrentDate) 
	OR 
	(a.startDate < @CurrentDate AND a.endDate >= DATEADD(d, 1, @CurrentDate)) 
)
GROUP BY r.ID 
) t
ORDER BY t.startDate ASC 
SET @CurrentDate = convert(varchar(30), dateadd(day, 1, @CurrentDate), 101); /*increment current date*/  
END 
	

DECLARE @ProductTotals2 TABLE 
(   
	Date datetime,  
	Duration nvarchar(16),  
	Seconds int,  
	[Ocupation] DECIMAL(10, 2),
	Code nvarchar(100),
	IDPosition uniqueidentifier
)  


SET @StartDate = CONVERT(date, DATEADD(d, @DAYSBEHIND, @EndDate))  
SET @CurrentDate = @StartDate  
DECLARE @TotalTime int 

WHILE(@CurrentDate <= @EndDate)  
BEGIN  


SET @TotalTime = ISNULL((SELECT 
		
		SUM(Duration) as TotalTime
		
		FROM @ProductTotals 
		WHERE Date = @CurrentDate
		GROUP BY 
			Date
			),0)
Print @TotalTime;
INSERT INTO @ProductTotals2(Date, Duration, Seconds, [Ocupation], Code, IDPosition)  

VALUES( @CurrentDate, 
dbo.GetTimeFromSeconds(@TotalTime) , 
@TotalTime, 
CONVERT(DECIMAL(10, 2), ((1.0 * (@TotalTime)) / DATEDIFF(s, DATEADD(d, -1, GETDATE()), GETDATE()) * 100))  ,
@PNAME, 
@IDPOSIC 
)

SET @TotalTime = 0
SET @CurrentDate = convert(varchar(30), dateadd(day, 1, @CurrentDate), 101); /*increment current date*/  
END 

SELECT * FROM @ProductTotals2 ORDER BY Date ASC


END
GO


