CREATE PROCEDURE [dbo].[UpdateProduct2ProductionPartNumbersList]
	@IDRecord int,
	@IDModule uniqueidentifier
AS
BEGIN
	SET NOCOUNT ON;

	--update products set PartNumbers = t.NewPartNumbers
	--from(
	--	select p.productid as IDP,(
	--		SELECT Distinct '|', PartNumber, '|'  FROM Product2ProductionPartNumber WHERE IDProduct = @IDRecord and IDProductModule = @IDModule
