-- ----------------------------
-- function structure for GetSysTaskAssigned
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetSysTaskAssigned]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetSysTaskAssigned]
GO

CREATE FUNCTION [dbo].[GetSysTaskAssigned]
(
	@idTask uniqueidentifier
)
RETURNS nvarchar(max)
AS
BEGIN
	
	declare @t nvarchar(max)
	set @t = ''

	declare @u nvarchar(max)

	declare it cursor for 	
		select 
			case 
				when Username = '' then ResourceName
				when ResourceName = '' then Username
				else
					concat(Username, ' (', ResourceName, ')')
			end
		from (

			select 	
				case isnull(rtrim(SysLogin.FullName), '')
					when  '' then 
						(case isnull(rtrim(SysLogin.Nick), '')
							when '' then
								isnull(rtrim(Username), '')
							else
								isnull(rtrim(SysLogin.Nick), '')
						end)
					else
						isnull(rtrim(SysLogin.FullName), '')
					end as UserName,

				case isnull(rtrim(SysResources.DisplayName), '')
					when  '' then 
						(case isnull(rtrim(SysResources.ResourceName), '')
							when '' then
								isnull(rtrim(SysResources.Code), '')
							else
								isnull(rtrim(SysResources.ResourceName), '')	
						end)
					else
						isnull(rtrim(SysResources.DisplayName), '')
					end as ResourceName

			from SysTask with(nolock)
				inner join SysTaskResourceRole with(nolock) on SysTask.IDTask = SysTaskResourceRole.IDTask
				left join SysResources with(nolock) on SysTaskResourceRole.IDResource = SysResources.ResourceId 			
				left join SysLogin with(nolock) on SysTaskResourceRole.IDUser = SysLogin.IDLogin
			where				
				not (SysTaskResourceRole.IDResource is null and SysTaskResourceRole.IDUser is null)
				and SysTask.IDTask = @idTask
		) aux

	/*
		select 
			SysResources.DisplayName, SysLogin.Username
		from SysTask with(nolock)
			inner join SysTaskResourceRole with(nolock) on SysTask.IDTask = SysTaskResourceRole.IDTask
			left join SysResources with(nolock) on SysTaskResourceRole.IDResource = SysResources.ResourceId 			
			left join SysLogin with(nolock) on SysTaskResourceRole.IDUser = SysLogin.IDLogin
		where
			SysTask.IDTask = @idTask
			and not (SysTaskResourceRole.IDResource is null and SysTaskResourceRole.IDUser is null)
*/
	open it

	fetch next from it into @u

	while @@FETCH_STATUS = 0
	begin
		if @u != '' and not @u is null
		begin
			set @t = CONCAT(@t, case when @t = '' then '' else ', ' end, @u)
		end
		fetch next from it into @u
	end

	close it
	deallocate it

	set @t = TRIM(@t)
	
	RETURN @t

END
GO


