CREATE PROCEDURE [dbo].[ToDeleteSameTableRelSetData]
	-- Add the parameters for the stored procedure here
	@ParentID int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

declare @start datetime;
declare @end datetime;
	while @ParentID is not null
	begin
		select @start=Min(starttime),@end=Max(endtime) 
		from todeletetasktimes t 
		inner join ToDeleteTaskPArent tp on tp.IDTask=t.id and tp.IDTaskParent=@ParentID

		Update todeletetask set starttime=@start, endtime=@end where id=@ParentID;
		select @ParentID=idparent from todeletetask where id=@ParentID;

	end;
END
GO


-- ----------------------------
-- function structure for GetTaskManagement
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTaskManagement]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTaskManagement]
GO

CREATE FUNCTION [dbo].[GetTaskManagement]
(
	@IDTask uniqueidentifier,
	@IDOwnResource uniqueidentifier
)
RETURNS int
AS
BEGIN
	declare  @IsManager int = 3
	declare @ret int = 0

	if @IDTask = '00000000-0000-0000-0000-000000000000'
	begin
		set @ret = 2
	end
	else
	begin
		declare @test table (
			idResource uniqueidentifier null
		)

		insert into @test(idResource)
		select idResource from [SysTaskResourceRole] aux with(nolock) where aux.IDTask = @IDTask and aux.kind = @IsManager

		if (exists(select top 1 1 from @test))
		begin
			set @ret = 1
			if (exists(select top 1 1 from @test where idResource = @IDOwnResource))
			begin
				set @ret = 2
			end
		end
	end
	return @ret

END
GO


-- ----------------------------
-- function structure for DistanceByPoints
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DistanceByPoints]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[DistanceByPoints]
GO

CREATE FUNCTION [dbo].[DistanceByPoints](@lat decimal(12,9), @long decimal(12,9), @lat2 decimal(12,9), @long2 decimal(12,9)) returns float as 
begin
	if((@lat2 IS NULL) or (@long2 IS NULL ) or (@lat IS NULL) or (@long IS NULL ))
	begin 
		return NULL
	end
	else
	begin
		DECLARE @orig geography = geography::Point(@lat2, @long2, 4326);
		DECLARE @dest geography = geography::Point(@lat, @long, 4326);
		return @orig.STDistance(@dest)
	end
	return NULL
end
GO


