-- ----------------------------
-- function structure for GetAccountsParentsRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetAccountsParentsRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetAccountsParentsRec]
GO

CREATE FUNCTION [dbo].[GetAccountsParentsRec]
(	
	@IDAccount int
)
RETURNS TABLE 
AS
RETURN 
(
	with GetAccountsRec as (
		select IDAccount, IDParent
		from Account
		where IDAccount = @IDAccount
		union all
		select c.IDAccount, c.IDParent
		from Account c 
		inner join GetAccountsRec p on c.IDAccount = p.idparent
	)
	select p.*
	from Account p
		inner join
		GetAccountsRec rec on p.IDAccount = rec.IDAccount
)
GO


