-- ----------------------------
-- procedure structure for CreatePartNumbersForProduct
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreatePartNumbersForProduct]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreatePartNumbersForProduct]
GO

CREATE PROCEDURE [dbo].[CreatePartNumbersForProduct]	
	@NewIDRecord int ,
	@NewIDModule uniqueidentifier,
	@PartNumbers nvarchar(Max)
AS
BEGIN
	
	Set @PartNumbers = trim(@PartNumbers);

	declare it cursor for
	select distinct Data from dbo.Split(@PartNumbers, ',')

	open it;

	declare @data nvarchar(200);

	fetch next from it into @data;

	while @@FETCH_STATUS = 0
	begin
		
		insert into Product2ProductionPartNumber
		values(@data, '', @NewIDRecord, @NewIDModule);

		fetch next from it into @data;
	end

	close it;
	deallocate it;

	exec UpdateProduct2ProductionPartNumbersList @NewIDRecord, @NewIDModule;

END
GO


-- ----------------------------
-- procedure structure for Query_MaintenanceSWSC_ContractsNoActivities
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_MaintenanceSWSC_ContractsNoActivities]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_MaintenanceSWSC_ContractsNoActivities]
GO

CREATE PROCEDURE [dbo].[Query_MaintenanceSWSC_ContractsNoActivities]

AS
BEGIN
	SET NOCOUNT ON;
		
	-- setup helper table with businessarea

	select sc.contractNo as Contrato,e.organization_no as Codigo ,e.accountname Empresa, e.email, e.email2
	from ServiceContract sc
	inner join entity e on e.organizationid = sc.IDEntityRelatedTo
	left join Activity2Record a2r on a2r.relatedRecord = sc.IDServiceContract and a2r.relatedRecordModule = sc.IDModule
	left join Activity a on a.IDActivity = a2r.IDActivity and DATEDIFF(MONTH, a.endDate, getdate()) <= 3
	left join SysActivityResourceRoleActivity arra on arra.TeamMask01 in
	(
	512,
	1024,
	32768
	) and arra.IDActivity = a.IDActivity
	where sc.dbmask in(1,32)
	and IDBusinessArea in
	(
		---select IDBusinessArea from BusinessArea where IDBusinessArea = 2 or IDParent = 2
						select ba.IDBusinessArea from BusinessArea ba
		inner join BusinessArea ba2 on ba2.IDParent=ba.IDBusinessArea 
		 where ba.IDBusinessArea = 2 or ba.IDParent = 2
	) and sc.status  = 2667
	group by sc.contractNo,e.organization_no ,e.accountname, e.email, e.email2
	having COUNT(distinct a2r.IDActivity) = 0
	order by 3


END
GO


-- ----------------------------
-- procedure structure for GetWorkingTimeByResource
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetWorkingTimeByResource]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetWorkingTimeByResource]
GO

CREATE PROCEDURE [dbo].[GetWorkingTimeByResource]
	-- Add the parameters for the stored procedure here
	@IDRESOURCE as UniqueIdentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

 --   DECLARE @IDPOSIC as UniqueIdentifier
 --SET @IDPOSIC = '407685e2-6e6b-4c4b-a5af-5dbcadf5d990'
 
 DECLARE @DAYSBEHIND int
 SET @DAYSBEHIND = -130
 
 DECLARE @StartDate AS DATETIME  
 DECLARE @EndDate AS DATETIME  
 DECLARE @CurrentDate AS DATETIME  
 DECLARE @ProductTotals TABLE 
 (   
	Date datetime,  
	Duration int,  
	IDRESOURCE uniqueidentifier,  
	Code nvarchar(150)
)  
DECLARE @PNAME Nvarchar(100)
SET @PNAME = (SELECT LTRIM(RTRIM(Code)) FROM SysResources WHERE ResourceId = @IDRESOURCE )
SET @EndDate = CONVERT(date, GETDATE())  
SET @StartDate = CONVERT(date, DATEADD(d, @DAYSBEHIND, @EndDate))  
SET @CurrentDate = @StartDate  
WHILE(@CurrentDate <= @EndDate)  
BEGIN  INSERT INTO @ProductTotals(Date, Duration, IDRESOURCE, Code)  
SELECT 
	CONVERT(date, @CurrentDate) AS Date,  
	CASE WHEN CONVERT(date, t.StartDate) = CONVERT(date, t.endDate) 
		THEN DATEDIFF(s, t.startdate, t.enddate)  
	WHEN CONVERT(date, t.endDate) > CONVERT(date, @CurrentDate) AND CONVERT(date, t.startDate) = CONVERT(date, @CurrentDate)
		THEN DATEDIFF(s, t.startDate, DATEADD(d, 1, @CurrentDate))  
	WHEN CONVERT(date, t.endDate) > CONVERT(date, @CurrentDate) AND CONVERT(date, t.startDate) < CONVERT(date, @CurrentDate)
		THEN 24*60*60 
	ELSE 
		DATEDIFF(s, CONVERT(date, @CurrentDate), t.endDate) 
	END 
	AS Duration, 
	@IDRESOURCE,
	@PNAME 
FROM (
SELECT r.ID, MIN(a.startdate) as startDate, MAX(a.endDate) as endDate
FROM Activity a
 
INNER JOIN SysPrRoutineRequest r  ON r.ID = a.IDRequest  

WHERE r.IDJob > 0 
AND r.StartDate >= CONVERT(date, DATEADD(d, @DAYSBEHIND, GETDATE()))  
AND a.IDRoutineItem IS NOT NULL 
AND r.IDResourcePosition = @IDRESOURCE  
AND ( 
	(a.startDate > @CurrentDate AND a.startDate < DATEADD(d, 1, @CurrentDate)) 
	OR 
	(a.startDate < @CurrentDate AND a.endDate >= @CurrentDate) 
	OR 
	(a.startDate < @CurrentDate AND a.endDate >= DATEADD(d, 1, @CurrentDate)) 
)
GROUP BY r.ID 
) t
ORDER BY t.startDate ASC 
SET @CurrentDate = convert(varchar(30), dateadd(day, 1, @CurrentDate), 101); /*increment current date*/  
END 
	

DECLARE @ProductTotals2 TABLE 
(   
	Date datetime,  
	Duration nvarchar(16),  
	Seconds int,  
	[Ocupation] DECIMAL(10, 2),
	Code nvarchar(100),
	IDRESOURCE uniqueidentifier
)  


SET @StartDate = CONVERT(date, DATEADD(d, @DAYSBEHIND, @EndDate))  
SET @CurrentDate = @StartDate  
DECLARE @TotalTime int 

WHILE(@CurrentDate <= @EndDate)  
BEGIN  


SET @TotalTime = ISNULL((SELECT 
		
		SUM(Duration) as TotalTime
		
		FROM @ProductTotals 
		WHERE Date = @CurrentDate
		GROUP BY 
			Date
			),0)
Print @TotalTime;
INSERT INTO @ProductTotals2(Date, Duration, Seconds, [Ocupation], Code, IDRESOURCE)  

VALUES( @CurrentDate, 
dbo.GetTimeFromSeconds(@TotalTime) , 
@TotalTime, 
CONVERT(DECIMAL(10, 2), ((1.0 * (@TotalTime)) / DATEDIFF(s, DATEADD(d, -1, GETDATE()), GETDATE()) * 100))  ,
@PNAME, 
@IDRESOURCE 
)

SET @TotalTime = 0
SET @CurrentDate = convert(varchar(30), dateadd(day, 1, @CurrentDate), 101); /*increment current date*/  
END 

SELECT * FROM @ProductTotals2 ORDER BY Date ASC


END
GO


-- ----------------------------
-- function structure for StrParse
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[StrParse]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[StrParse]
GO

CREATE FUNCTION [dbo].[StrParse]
               (@delimiter CHAR(1),  
                @csv       NTEXT)  
RETURNS @tbl TABLE(Keys  NVARCHAR(255))  
AS  

  BEGIN  
    DECLARE  @len INT  
    SET @len = Datalength(@csv)  
    IF NOT @len > 0  
      RETURN  

    DECLARE  @l INT  
    DECLARE  @m INT  

    SET @l = 0  
    SET @m = 0  

    DECLARE  @s VARCHAR(255)  
    DECLARE  @slen INT  

    WHILE @l <= @len  
      BEGIN  

        SET @l = @m + 1--current position  
        SET @m = Charindex(@delimiter,Substring(@csv,@l + 1,255))--next delimiter or 0  

        IF @m <> 0  
          SET @m = @m + @l  
        --insert @tbl(keys) values(@m)  
        SELECT @slen = CASE   
                         WHEN @m = 0 THEN 255 --returns the remainder of the string  
                         ELSE @m - @l  
                       END --returns number of characters up to next delimiter  

        IF @slen > 0  
          BEGIN  
            SET @s = Substring(@csv,@l,@slen)  
            INSERT INTO @tbl  
                       (Keys)  
            SELECT @s  
          END  

        SELECT @l = CASE   
                      WHEN @m = 0 THEN @len + 1 --breaks the loop  
                      ELSE @m + 1  
                    END --sets current position to 1 after next delimiter  
      END  

    RETURN  
  END
GO


