GO

CREATE FUNCTION [dbo].[GetResourceAscendants]
(	
	@IDResource uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	with role_ascendants (idrolerel, idrolerelparent, idresource, [Level]) as 
	(
		select idrolerel, idrolerelparent, idresource, 0 as [Level]
		from SysRoleRelationship
		where IDResource = @IDResource
		union all
		select r.idrolerel, r.idrolerelparent, r.idresource, d.[Level] - 1 as [Level]
		from SysRoleRelationship r inner join role_ascendants d on r.idrolerel = d.idrolerelparent
	)

	select * from role_ascendants
)
GO


