-- ----------------------------
-- procedure structure for UpdateAssetProductionStatus
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAssetProductionStatus]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAssetProductionStatus]
GO

CREATE PROCEDURE [dbo].[UpdateAssetProductionStatus]
	@IDAsset int,
	@IDModule uniqueidentifier
AS
BEGIN

	declare @CurrentStatus int = 0;
	declare @CurrentProductionStatus int = 0;
	declare @TotalPendingStock numeric(18,5) = 0;
	declare @TotalExistingStock numeric(18,5) = 0;
	declare @TotalOrderedStock numeric(18,5) = 0;
	declare @SysPartRoutine uniqueidentifier;
	declare @SysOprRoutine uniqueidentifier;
	declare @IDAccountAsset int;
	declare @AssetCreationDate datetime;
	declare @HasMouldLink int = 0;
	declare @HasRequestedBudget int = 0;
	declare @HasNoBudgets int = 0;
	declare @HasLateBudgets int = 0;
	declare @HasLateBudgetsFromSupplier int = 0;
	declare @HasBudgetToEvaluate int = 0;
	declare @HasLateBudgetsEvaluation int = 0;
	declare @HasPurchaseOrderOrInvoice int = 0;
	declare @HasLateDelivery int = 0;
	declare @IsAssetAssemblyPart int = 0;

	select top 1 @CurrentStatus = a.status, @CurrentProductionStatus = apv.ProductionStatus, 
	@TotalPendingStock = accStk.TotalQtyPendingProduction, @TotalExistingStock = accStk.TotalQtyActualStock,
	@SysPartRoutine = a.IDSysPartRoutine, @HasMouldLink = case when fup.IDFollowUpItem is null then 0 else 1 end,
	@TotalOrderedStock = accStk.TotalQtyOrderedToSupplier, @SysOprRoutine = a.IDSysOprRoutine, 
	@AssetCreationDate = a.CreatedTime, @IDAccountAsset = acc.IDAccount, @IsAssetAssemblyPart =
	case when a.IDModule in
	( 
		select IDModule from GetModulesRec('52873931-5697-44ee-801b-a687109e5e75')
	) then 1 else 0 end 
	from Asset a
	inner join SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	inner join Account acc on acc.IDContact = a.IDAsset and acc.IDContactModule = a.IDModule
	inner join AccountStock accStk on accStk.IDAccount = acc.IDAccount
	left join FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem
	where a.IDAsset = @IDAsset and a.IDModule = @IDModule

	IF (@TotalPendingStock = @TotalExistingStock OR @IsAssetAssemblyPart = 1) and @CurrentStatus <> 2801
	begin
		update Asset set status = 2801 where IDAsset = @IDAsset;
		print 'Stock fulfilled';
	end
	else if @CurrentStatus in(2787,2788,2789,2790,2791,2799,2792)
	begin
		if @CurrentStatus in(2787, 2788)
		begin
			if @CurrentStatus = 2787
			begin
				set @HasLateBudgets = (
					select top 1 case when t.c > 0 then 1 else 0 end 
					from
					(
						select count(*) c
						from DocumentLine dl
						inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
						and d.PartitionColumn = dl.PartitionColumn
						where dl.dim16 = @IDAccountAsset and d.IDModule in
						(
							select IDModule 
							from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
						) 
						and d.status = 2496 and datediff(day, @AssetCreationDate, getdate()) >= 4
					) t
				);

				set @HasNoBudgets = (
					select top 1 case when t.c > 0 then 1 else 0 end 
					from
					(
						select count(*) c
						from DocumentLine dl
						inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
						and d.PartitionColumn = dl.PartitionColumn
						where dl.dim16 = @IDAccountAsset and d.IDModule in
						(
							select IDModule 
							from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
						) 
					) t
				);

				print concat('HasLateBudgets: ', @HasLateBudgets);
				print concat('HasNoBudgets: ', @HasNoBudgets);
				if @HasLateBudgets = 1 or (@HasNoBudgets = 0 and datediff(day, @AssetCreationDate, getdate()) >= 4)
				begin
					update Asset set status = 2788 where IDAsset = @IDAsset;
				end
			end

			set @HasRequestedBudget = (
				select top 1 case when t.c > 0 then 1 else 0 end 
				from
				(
					select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule 
						from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
					) and d.status = 2497
				) t
			);

			print concat('HasRequestedBudget: ', @HasRequestedBudget);
			if @HasRequestedBudget = 1 
			begin
				update Asset set status = 2789 where IDAsset = @IDAsset;
			end
		end
		else if @CurrentStatus = 2789
		begin
			set @HasLateBudgetsFromSupplier = (
				select top 1 case when t.c > 0 then 1 else 0 end 
				from
				(
					select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule 
						from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
					) 
					and d.status = 2497 and d.validuntil is not null and datediff(day, d.validuntil, getdate()) >= 1
				) t
			);

			print concat('HasLateBudgetsFromSupplier: ', @HasLateBudgetsFromSupplier);
			if @HasLateBudgetsFromSupplier = 1 
			begin
				update Asset set status = 2790 where IDAsset = @IDAsset;
			end

			set @HasBudgetToEvaluate = (
			select top 1 case when t.c > 0 then 1 else 0 end 
			from
			(
				select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule 
						from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
					) 
					and d.status = 8750 
				) t
			);

			print concat('HasBudgetToEvaluate: ', @HasBudgetToEvaluate);
			if @HasBudgetToEvaluate = 1
			begin
				update Asset set status = 2791 where IDAsset = @IDAsset;
			end


			set @HasLateBudgetsEvaluation = (
			select top 1 case when t.c > 0 then 1 else 0 end 
			from
			(
				select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					inner join SysModuleTracker mt on mt.IDRecord = d.IDDocument and mt.IDModule = d.IDModule
					and mt.ProgressStatus = 8750
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule 
						from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
					) 
					and d.status = 8750 and datediff(day, mt.EndDate, getdate()) >= 2
				) t
			);

			print concat('HasLateBudgetsEvaluation: ', @HasLateBudgetsEvaluation);
			if @HasLateBudgetsEvaluation = 1 
			begin
				update Asset set status = 2799 where IDAsset = @IDAsset;
			end

		end
		else if @CurrentStatus = 2791
		begin
			set @HasLateBudgetsEvaluation = (
			select top 1 case when t.c > 0 then 1 else 0 end 
			from
			(
				select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					inner join SysModuleTracker mt on mt.IDRecord = d.IDDocument and mt.IDModule = d.IDModule
					and mt.ProgressStatus = 8750
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule 
						from GetModulesRec('dfa0b1eb-c5a3-4c67-a98b-033c10aa1eed')
					) 
					and d.status = 8750 and datediff(day, mt.EndDate, getdate()) >= 2
				) t
			);

			print concat('HasLateBudgetsEvaluation: ', @HasLateBudgetsEvaluation);
			if @HasLateBudgetsEvaluation = 1 
			begin
				update Asset set status = 2799 where IDAsset = @IDAsset;
			end
		end

		if @CurrentStatus in(2787,2788,2789,2790,2791, 2794, 2795,2799)
		begin
			set @HasPurchaseOrderOrInvoice = (
				select top 1 case when t.c > 0 then 1 else 0 end 
				from
				(
					select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule from GetModulesRec('a3578c79-f024-4f1b-9da3-07cf196649c4')
						union all
						select IDModule from GetModulesRec('bc2c3113-36fa-4c7c-900e-b2876893c12a')
					) 
					and d.RegisterStatus = 1 
				) t
			);

			print concat('HasPurchaseOrderOrInvoice: ', @HasPurchaseOrderOrInvoice);
			if @HasPurchaseOrderOrInvoice = 1 
			begin
				update Asset set status = 2792 where IDAsset = @IDAsset;
			end
		end
		else if @CurrentStatus = 2792
		begin
			set @HasLateDelivery = (
				select top 1 case when t.c > 0 then 1 else 0 end 
				from
				(
					select count(*) c
					from DocumentLine dl
					inner join document d on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule 
					and d.PartitionColumn = dl.PartitionColumn
					where dl.dim16 = @IDAccountAsset and d.IDModule in
					(
						select IDModule from GetModulesRec('a3578c79-f024-4f1b-9da3-07cf196649c4')
						union all
						select IDModule from GetModulesRec('bc2c3113-36fa-4c7c-900e-b2876893c12a')
					) 
					and d.RegisterStatus = 1 and dl.PaymentPrevDate is not null and datediff(day, dl.PaymentPrevDate, getdate()) >= 1
				) t
			);
			print concat('HasLateDelivery: ', @HasLateDelivery);
			if @HasLateDelivery = 1 
			begin
				update Asset set status = 2793 where IDAsset = @IDAsset;
			end
		end
	end

	IF @SysPartRoutine is null and @CurrentProductionStatus = 0
	begin
		UPDATE SS_AssetPartValues set ProductionStatus = 2 where IDAsset = @IDAsset
	end
	ELSE IF @CurrentProductionStatus = 0 and @SysPartRoutine is not null and @SysOprRoutine is null and DATEDIFF(DAY, @AssetCreationDate, GETDATE()) >= 4 
	begin
		UPDATE SS_AssetPartValues set ProductionStatus = 1 where IDAsset = @IDAsset
	end
	ELSE IF @SysPartRoutine is not null and @SysOprRoutine is not null and @CurrentProductionStatus in(0,1)
	begin
		UPDATE SS_AssetPartValues set ProductionStatus = 2 where IDAsset = @IDAsset
	end
END
GO


-- ----------------------------
-- procedure structure for ResetSelfStartingProcesses
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ResetSelfStartingProcesses]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ResetSelfStartingProcesses]
GO

CREATE PROCEDURE [dbo].[ResetSelfStartingProcesses] AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    
DELETE FROM SysPrRoutineTimers WHERE IDRequest IN (SELECT ID FROM SysPrRoutineRequest WHERE IDPrRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1))
DELETE FROM SysPrRoutineResourcePositions WHERE IDRequest IN (SELECT ID FROM SysPrRoutineRequest WHERE IDPrRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1))
DELETE FROM SysPrRoutineRequest WHERE IDPrRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1)

DELETE FROM SysPrRoutineVar WHERE IDRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1)
DELETE FROM SysPrRoutineCursorConditions WHERE IDSysRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1)
DELETE FROM SysPrRoutineCursor WHERE IDSysRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1)
--DELETE FROM SysPrRoutineVarTemplate WHERE IDRoutine IN (SELECT IDRoutine FROM SysPrRoutine WHERE IsSelfStartingProcess = 1)

END
GO


-- ----------------------------
-- function structure for SM_GetNOdeChildsV2
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SM_GetNOdeChildsV2]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SM_GetNOdeChildsV2]
GO

CREATE FUNCTION [dbo].[SM_GetNOdeChildsV2]
(
	@ParentID nvarchar(4000)
)
RETURNS 
@Res TABLE 
(
	id uniqueidentifier
)
AS
BEGIN

	insert into @res select CAST(keys as uniqueidentifier) as keys from dbo.StrParse(',',@ParentID);
	WITH    v (idv) AS
			(
			SELECT  id
			FROM    sm_nodeposic
			WHERE   IDNodePosicParent IN (select CAST(keys as uniqueidentifier) as keys from dbo.StrParse(',',@ParentID))
	        
			UNION ALL
	        
			SELECT  id
			FROM    v
			JOIN    sm_nodeposic t
			ON      t.IDNodePosicParent = v.idv
			)
	insert into @res    
	SELECT  DISTINCT(idv)
	--select *
	FROM    v WHERE idv not in (SELECT ID FROM @Res)
	option (maxrecursion 0)

	
	RETURN 
END
GO


