-- ----------------------------
-- procedure structure for UpdateStatusOfDocumentProductionAssets
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateStatusOfDocumentProductionAssets]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateStatusOfDocumentProductionAssets]
GO

CREATE PROCEDURE [dbo].[UpdateStatusOfDocumentProductionAssets]
	@IDDocument int,
	@IDModule uniqueidentifier
AS
BEGIN
	declare it cursor for
	select a.IDAsset, a.IDModule 
	from DocumentLine dl
	inner join Asset a on a.IDAccount = dl.dim16
	where dl.IDLineType = 1 and dl.IDRegister = @IDDocument and dl.IDModule = @IDModule

	union all

	select a.IDAsset, a.IDModule 
	from DocumentLine dl
	inner join Asset a on a.IDAsset = dl.assetid
	where dl.IDRegister = @IDDocument and dl.IDModule = @IDModule

	open it;

	declare @idrecord int, @IDAssetModule uniqueidentifier

	fetch next from it into @idrecord, @IDAssetModule

	while @@FETCH_STATUS = 0
	begin
	 exec [UpdateAssetProductionStatus] @idrecord, @IDAssetModule

	 fetch next from it into @idrecord, @IDAssetModule
	end

	close it;
	deallocate it;

END
GO


-- ----------------------------
-- function structure for GetHoursAccountForResource
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetHoursAccountForResource]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetHoursAccountForResource]
GO

CREATE FUNCTION [dbo].[GetHoursAccountForResource]
(	
	@IDResource uniqueidentifier,
	@AccountType int
)
RETURNS TABLE 
AS
RETURN 
(
	select acc.IDAccount, acc.IDModule, e.ShortName as AccountName, acc.AccountYear, isnull(acc.Status,0) Status, e.organizationid as IDPerson, e.IDModule as IDPersonModule, 
	isnull(acc.TotalQtyDocAct,0)  as TotalQtyDocAct
	from SysLogin2SysResource res
	inner join Entity e on e.organizationid = res.IDPerson and e.IDModule = res.IDPersonModule
	inner join account acc on acc.IDContact = e.organizationid and acc.IDContactModule = e.IDModule
	where res.Active = 1 and res.IDResource = @IDResource and (acc.[Status]!=1 or acc.[Status] is null) and 
	(
		(
			@AccountType = 0 and acc.IDModule in
			(
				select IDModule from GetModulesRec('3020DDD2-D6D9-4E3D-8B6F-70D228E1B7B2')
			)
		)
	OR
		(
			@AccountType = 1 and acc.IDModule in
			(
				select IDModule from GetModulesRec('25C1DD8B-3766-4384-A3C1-4338D6EEFCF7')
			)
		)
	)
);
GO


-- ----------------------------
-- function structure for GetAssetProductionChildrenRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetAssetProductionChildrenRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetAssetProductionChildrenRec]
GO

CREATE FUNCTION [dbo].[GetAssetProductionChildrenRec] 
(	
	@IDAsset int,
	@IDAssetModule uniqueidentifier
)
  
RETURNS TABLE 
AS
RETURN 
(
	with GetAssets2AssetsRec as 
	(
		select IDRecAssetChild, IDRecAsset
		from Asset2Asset
		where IDRecAsset = @IDAsset and IDRecAssetModule = @IDAssetModule
		union all
		select a2a.IDRecAssetChild, a2a.IDRecAsset
		from Asset2Asset a2a inner join GetAssets2AssetsRec p on a2a.IDRecAsset = p.IDRecAssetChild
	)
	select a.*, ap.AssetCatalog, ap.AssetDimensions, ap.AssetNumber, ap.Hardness, ap.HeatTreatment, ap.IsProduction, ap.Material, 
	a2a.IDRecAsset IDParent, a2a.IDRecAssetModule IDParentModule, a.IDModule as IDAssetModule, @IDAsset as IDAssetRoot, ap.AssetVisibleDimensions
	from Asset2Asset a2a
	inner join GetAssets2AssetsRec rec on a2a.IDRecAssetChild = rec.IDRecAssetChild
	inner join Asset a on a.IDAsset = a2a.IDRecAssetChild and a.IDModule = a2a.IDRecAssetChildModule
	left join SS_AssetPartValues ap on ap.IDAsset = a.IDAsset and ap.IDModule = a.IDModule
)
GO


-- ----------------------------
-- function structure for GetRemainigTimeForPartInResource
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRemainigTimeForPartInResource]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetRemainigTimeForPartInResource]
GO

CREATE FUNCTION [dbo].[GetRemainigTimeForPartInResource] 
(
	-- Add the parameters for the function here
	@IDResource UniqueIdentifier,
	@IDPart UniqueIdentifier,
	@Factor float
)
RETURNS bigint
AS
BEGIN
	-- Declare the return variable here
	DECLARE @result  bigint;

	-- Add the T-SQL statements to compute the return value here
	SELECT @result = (SELECT (COALESCE(SUM(t.RemainingTime), 0)) AS RemainingTime FROM (


	SElECT cASE WHEN x.RemainingTime < 0 THEN 0 ELSE  RemainingTime  END as RemainingTime FROM (
SELECT 
--a.startDate, a.endDate, p.EstimatedTime, p.EstimatedTime * @Factor as [FactorTime] ,
CASE 
WHEN a.startDate IS NOT NULL THEN ((p.EstimatedTime * @Factor) - (DATEDIFF(s, a.StartDate, GETDATE())))
ELSE p.EstimatedTime * @Factor 
END as RemainingTime
FROM SysJob j 

LEFT JOIN SysJobLine jl ON j.ID = jl.IDJob
LEFT JOIN SysPrRoutineRequest r ON jl.IDJobLine = r.IDJobLine
INNER JOIN Activity a ON r.ID = a.IDRequest
LEFT JOIN SS_Program p ON jl.IDProgram = p.ID
WHERE 
jl.IDPart = @IDPart 
AND (j.IDResource IS NULL OR j.IDResource = @IDResource) 
AND a.IDPart = @IDPart AND a.IDRequest IS NOT NULL 
AND p.IDObject = @IDPart AND p.IDJob IS NOT NULL
AND jl.Active = 1 
AND jl.IDProgram IS NOT NULL 
AND jl.IDProgram <> '00000000-0000-0000-0000-000000000000'
AND jl.Status IN ('C6812E70-56CB-4394-84A5-4C3DE719B44E', 'CD69321D-BF74-4503-A9D6-0614F0C7CE01', '483D173F-7287-4751-A9D1-741DAAAB41E0')
AND j.Status IN ('C6812E70-56CB-4394-84A5-4C3DE719B44E', 'CD69321D-BF74-4503-A9D6-0614F0C7CE01', '483D173F-7287-4751-A9D1-741DAAAB41E0')
) x
) t)

	-- Return the result of the function
	RETURN @result

END
GO


-- ----------------------------
-- procedure structure for UpdateDocStatusAfterEmailCreated
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateDocStatusAfterEmailCreated]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateDocStatusAfterEmailCreated]
GO

CREATE PROCEDURE [dbo].[UpdateDocStatusAfterEmailCreated]
	@IDRecord int,
	@IDModule uniqueidentifier
	AS
BEGIN
	SET NOCOUNT ON;

	declare it cursor for
		select distinct relatedRecord, relatedRecordModule 
		from Activity2Record a2r
		inner join document d on d.IDDocument = a2r.relatedRecord and d.IDModule = a2r.relatedRecordModule
		where a2r.IDActivity = @IDRecord and a2r.IDActivityModule = @IDModule 
		and 
		(
			d.status is null 
			or
			d.status in(2496,9454)
		)
	open it;

	declare @iddocument int, @iddocumentModule uniqueidentifier

	fetch next from it into @iddocument, @iddocumentModule

	while @@FETCH_STATUS = 0
	begin
		update document set status = 2497 where IDDocument = @iddocument and IDModule = @iddocumentModule;

		fetch next from it into @iddocument, @iddocumentModule
	end

	close it;
	deallocate it;
END
GO


