	--		FROM    sm_node
	--		WHERE   ParentID = @ParentID

	        
	--		UNION ALL
	        
	--		SELECT  id,code,ord
	--		FROM    v
	--		JOIN    sm_node t
	--		ON      t.ParentID = v.idv

	--		)
	--insert into @res    
	--SELECT  *
	--FROM    v
	----order by ordInt
	--option (maxrecursion 0)
	declare @curID uniqueidentifier;
	declare @code nvarchar(50);

	--Inserir Primeiro nó
	Select @curID=id, @code=code from sm_nodeposic where id=@ParentID;
