-- ----------------------------
-- procedure structure for Assets_UpdateDatesRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Assets_UpdateDatesRec]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Assets_UpdateDatesRec]
GO

CREATE PROCEDURE [dbo].[Assets_UpdateDatesRec]
	 @IDRegister int,
	 @IDModule int,

	 @IDUser int,
	 @IDRole int,
	 @IDRoleEntry int,

	 @nestedCall int = 0
AS
BEGIN
	print concat('[Assets_UpdateDatesRec](', @IDRegister, ', ', @IDModule, ')')
	

	SET NOCOUNT ON;

	-- insert into Log4Net ([Date], [Level], [Logger], Thread, Exception, [Message])
	-- select getdate(), 'DEBUG', 'teste', 0, '', concat('[dbo].[Assets_UpdateDatesRec](', @IDRegister , ', ', @IDModule , ')')

	DECLARE @dateStart DATETIME, @dateInService DATETIME, @dateExpiration DATETIME, @datesIndep BIT

	-- a) update self date

	SELECT @dateStart = start, @dateInService = dateInService, @dateExpiration = licExpirationDate, @datesIndep = datesIndep
	from Asset 
	where IDModule = @IDModule AND IDAsset = @IDRegister

	IF (@datesIndep = 0)
	begin
		

		declare @p_idAssetParent int, @p_dateStart datetime, @p_dateInService datetime, @p_dateExpiration datetime
		
		select top 1 @p_idAssetParent = IDAsset, @p_dateStart = start, @p_dateInService = dateInService, @p_dateExpiration = licExpirationDate
		from 
			SysModuleRelationship mr
			INNER JOIN Asset ON mr.IDRegister = Asset.IDAsset
		where 
			IDModuleRelationship IN (
				select IDModuleRelationshipParent
				from SysModuleRelationship
				where IDModule = @IDModule AND IDRegister = @IDRegister AND IDModule2ModuleRelationship = 4089 and not IDModuleRelationshipParent  is null
			)

		print concat('not dates independent ', @p_idAssetParent, ', ', @p_dateStart, ', ', @p_dateInService, ', ', @p_dateExpiration)

		IF (@p_idAssetParent > 0)
		BEGIN

			-- print concat('parent = ', @p_idAssetParent)

			declare @old_dateStart datetime, @old_dateInService datetime, @old_dateExpiration datetime

			select @old_dateStart = start, @old_dateInService = dateInService, @old_dateExpiration = licExpirationDate
			from Asset
			where IDModule = @IDModule AND IDAsset = @IDRegister

			update Asset
			set start = @p_dateStart, dateInService = @p_dateInService, licExpirationDate = @p_dateExpiration
			where IDModule = @IDModule AND IDAsset = @IDRegister

			-- IF (@nestedCall = 1)
			-- begin
				-- print concat('nestedCall = ', @nestedCall)
				
				declare @idModuleTracker int

				-- write in logs
				insert into sysmoduletracker (IDModule, ModuleName, IDRegister, IDRole, IDUser, [Status], StartDate, EndDate)
				select IDModule, Name, @IDRegister, @IDRole, @IDUser, 2, GETDATE(), GETDATE()
				from SysModule 
				where IDModule = @IDModule;

				SET @idModuleTracker = SCOPE_IDENTITY()
				
				-- yyyy-MM-ddTHH:mm:ss.fff 
				declare @t_old_dateStart nvarchar(15), @t_old_dateInService nvarchar(15), @t_old_dateExpiration nvarchar(15)
				declare @t_p_dateStart nvarchar(15), @t_p_dateInService nvarchar(15), @t_p_dateExpiration nvarchar(15)

				set @t_old_dateStart = coalesce(convert(nvarchar(15), @old_dateStart, 120), '')
				set @t_old_dateInService = coalesce(convert(nvarchar(15), @old_dateInService, 120), '')
				set @t_old_dateExpiration = coalesce(convert(nvarchar(15), @old_dateExpiration, 120), '')

				set @t_p_dateStart = coalesce(convert(nvarchar(15), @p_dateStart, 120), '')
				set @t_p_dateInService = coalesce(convert(nvarchar(15), @p_dateInService, 120), '')
				set @t_p_dateExpiration = coalesce(convert(nvarchar(15), @p_dateExpiration, 120), '')

				

				insert into SysModuleTrackerDetail(IDModuleTracker, IDField, FieldName, OldValue, NewValue)
					select top 1 @idModuleTracker, IDField, '', @t_old_dateStart, @t_p_dateStart 
					from SysField
					where TrackChanges = 1 AND SystemType = 0 AND ColumnName = 'start' and IDModule = @IDModule AND @t_old_dateStart != @t_p_dateStart

				union
					select top 1 @idModuleTracker, IDField, '', @t_old_dateInService, @t_p_dateInService 
					from SysField
					where TrackChanges = 1 AND SystemType = 0 AND ColumnName = 'dateInService' and IDModule = @IDModule AND @t_old_dateInService != @t_p_dateInService

				union
					select top 1 @idModuleTracker, IDField, '', @t_old_dateExpiration, @t_p_dateExpiration 
					from SysField
					where TrackChanges = 1 AND SystemType = 0 AND ColumnName = 'licExpirationDate' and IDModule = @IDModule AND @t_old_dateExpiration != @t_p_dateExpiration

			-- end -- IF (@nestedCall = 1)
		END -- IF (@p_idAssetParent > 0)
	end; -- IF (@datesIndep = 0)

	-- b) update children (recursively)

	-- get direct children

	declare @children table (
		IDAsset int,
		IDModule int
	)

	insert into @children(IDAsset, IDModule)
	select IDRegister, IDModule
	from SysModuleRelationship
	where IDModuleRelationshipParent = (
		select IDModuleRelationship
		from SysModuleRelationship
		where IDModule2ModuleRelationship = 4089 and IDModule = @IDModule AND IDRegister = @IDRegister and IDModuleRelationshipParent is null)

	
	declare IT cursor local for
		select IDAsset, IDModule
		from @children

	declare @it_IDAsset int, @it_IDModule int

	open IT

	fetch next from IT into @it_IDAsset, @it_IDModule

	while @@FETCH_STATUS=0
	begin

		exec [dbo].[Assets_UpdateDatesRec] @it_IDAsset, @it_IDModule , @IDUser, @IDRole, @IDRoleEntry, @nestedCall = 1
		fetch next from IT into @it_IDAsset, @it_IDModule
	end

	close IT;
	deallocate IT;

	return 0

END
GO


-- ----------------------------
-- function structure for TestResourceWithTriplet
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TestResourceWithTriplet]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[TestResourceWithTriplet]
GO

CREATE FUNCTION [dbo].[TestResourceWithTriplet]
(
	@IDResourceToTest uniqueidentifier null,
	@IDResource uniqueidentifier null,
	@IDActivityRole uniqueidentifier null,
	@TeamMask01 bigint null,
	@TeamMask02 bigint null,
	@excludeTeamParticipation0 int null
)
RETURNS int
AS
BEGIN	
	DECLARE @ok int
	set @ok = 0

	if @excludeTeamParticipation0 is null
	begin
		set @excludeTeamParticipation0 = 0
	end
	
	if @IDResourceToTest is null
	begin
		goto _end
	end

	if @IDResource is not null and @IDResourceToTest = @IDResource
	begin
		set @ok = 1
		goto _end
	end
		 
	if not @IDResource is null 
	begin
		-- at this point, @IDResourceToTest != @IDResource and @IDResource is filled
		-- REVISION if resource test has role in provided team that has access to teammates records then he has permissions
		goto _end;
		begin
			set @ok = 1
			goto _end
		end

		goto _end
	end

	set @TeamMask01 = coalesce (@TeamMask01, 0)
	set @TeamMask02 = coalesce (@TeamMask02, 0)

	if @TeamMask01 = 0 and @TeamMask02 = 0
	begin
		goto _end
	end

	if @IDActivityRole is null
	begin

		if exists
		(	
			select arr.IDActivityRoleResourceRole
			from SysTeam t with(nolock)
			inner join SysActivityRoleResource arr with(nolock) on t.IDTeam = arr.IDTeam
			inner join SysRole r with(nolock) on arr.IDActivityRole = r.IDActivityRole
			where
			(
				(t.Mask1 & @teamMask01) != 0 or (t.Mask2 & @teamMask02) != 0
			) 
			and arr.IDResource = @IDResourceToTest 
			and 
			(
				@excludeTeamParticipation0 = 0 or (@excludeTeamParticipation0 = 1 and isnull(r.TeamParticipation,0) != 0)
			)
		)
		begin
			set @ok = 1
			goto _end
		end
	end
	else
	begin
		-- if we test with role, don't exclude monitor
		if exists
		(	
			select arr.IDActivityRoleResourceRole
			from 
			SysTeam t with(nolock)
			inner join SysActivityRoleResource arr with(nolock) on t.IDTeam = arr.IDTeam
			where
			(
				(t.Mask1 & @teamMask01) != 0 or (t.Mask2 & @teamMask02) != 0
			) 
			and arr.IDResource = @IDResourceToTest 
			and arr.IDActivityRole = @IDActivityRole 
		)
		begin
			set @ok = 1
			goto _end
		end
	end
	
_end:
	RETURN @ok
END
GO


-- ----------------------------
-- procedure structure for GetRequestsInProcess
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetRequestsInProcess]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetRequestsInProcess]
GO

CREATE PROCEDURE [dbo].[GetRequestsInProcess]
	-- Add the parameters for the stored procedure here
	@IDProcess uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT 
		r.ID,
		ISNULL(CONCAT(dbo.SS_GetClientName(o.ID) + '_',COALESCE(RTRIM(LTRIM(o.FullName)),RTRIM(LTRIM(o.ShortName)))),'' ) as [Part], 
		ws.Code as [Status] ,
		CASE 
			WHEN r.Priority = 1 THEN 'Very Low' 
			WHEN r.Priority = 2 THEN 'Low' 
			WHEN r.Priority = 3 THEN 'Normal'  
			WHEN r.Priority = 4 THEN 'High' 
			WHEN r.Priority = 5 THEN 'Urgent' 
		END As Priority, 
		r.CreationDate,
		r.InFault
	FROM SysPrRoutineRequest r
	LEFT JOIN SS_Object o ON r.IDPart = o.ID
	LEFT JOIN SysWorkingStatus ws ON r.WorkingStatus = ws.ID
	WHERE 
		r.IDPrRoutine = @IDProcess
		AND r.WorkingStatus IN ('C6812E70-56CB-4394-84A5-4C3DE719B44E','483D173F-7287-4751-A9D1-741DAAAB41E0')
	ORDER BY r.Evaluation DESC, r.CreationDate DESC
END
GO


-- ----------------------------
-- procedure structure for UpdateMouldDeadline
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateMouldDeadline]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateMouldDeadline]
GO

CREATE PROCEDURE [dbo].[UpdateMouldDeadline]
(
	@IDFollowUpItem bigint
)
AS
BEGIN

	declare @Deadline datetime = 
	(
		select MIN(mt.Date) 
		from MouldTest mt
		inner join SysDocOprRoutineItem dri on dri.IDRoutineItem = mt.IDSysDocOprRoutineItem
		inner join SysOprRoutineItem ri on ri.DocTemplate = dri.IDRoutineItem
		where mt.IDFollowUpItem = @IDFollowUpItem and ri.WorkingStatus not in
		(
			'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70',
			'2F2593EC-D358-493E-B02C-3DB5A912C399',
			'88B381D9-D1DB-4C80-8E78-3076B1E196F2'
		)
	);

	if @Deadline is null
	begin
		set @Deadline = 
		(
			select MAX(isnull(mt.EffectiveDateTest, mt.Date))
			from MouldTest mt
			where mt.IDFollowUpItem = @IDFollowUpItem 
		)
	end

	begin 
		update FollowUpItemMouldFields set Deadline = @Deadline where IDFollowUpItem = @IDFollowUpItem;
		update SS_AssetPartValues set Deadline = @Deadline where IDAsset = (Select IDAsset from FollowUpItemMouldFields where IDFollowUpItem = @IDFollowUpItem);
	end
END
GO


-- ----------------------------
-- function structure for SM_GetcurrentRequestOpsResume
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SM_GetcurrentRequestOpsResume]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SM_GetcurrentRequestOpsResume]
GO

CREATE FUNCTION [dbo].[SM_GetcurrentRequestOpsResume]
(
	-- Add the parameters for the function here
	@Request_IDPrRoutine as uniqueidentifier,
	@IDPart as uniqueidentifier
)
RETURNS nvarchar(400)
AS
BEGIN
	declare @res nvarchar(400)
	declare @curCode as nvarchar(200)
	set @res='';
	
		DECLARE LocalCursor2 CURSOR LOCAL
		FOR Select routItem.code
			from SysPrRoutineCursor cur 
			left join SysPrRoutineItem routItem on cur.IDSysRoutineItem=routItem.IDRoutineItem
			where cur.IDSysRoutine=@Request_IDPrRoutine and cur.IDPart=@IDPart

		OPEN LocalCursor2;
		FETCH NEXT FROM LocalCursor2
			INTO  @curCode;
		WHILE @@FETCH_STATUS = 0
		BEGIN
			if @curCode is not null
					set @res=@res+@curCode+'; '

			FETCH NEXT FROM LocalCursor2
			INTO @curCode;
		END;
		
		CLOSE LocalCursor2;
		DEALLOCATE LocalCursor2;
		
	return @res
END
GO


