-- ----------------------------
-- procedure structure for CopyRolePermissionsFromTemplate
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CopyRolePermissionsFromTemplate]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CopyRolePermissionsFromTemplate]
GO

CREATE PROCEDURE [dbo].[CopyRolePermissionsFromTemplate]
	-- Add the parameters for the stored procedure here
	@IDRoleTemplate int,
	@IDRole int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


			--Copy Role 
		DECLARE CursorRole2Module CURSOR FOR   SELECT IDRole2Module,IDModule,PermissionRead,PermissionDelete,PermissionWrite FROM SysRole2Module WHERE IDRole=@IDRoleTemplate
		OPEN CursorRole2Module
		DECLARE @IDRole2Module int =0,
				@IDModule int=0,
				@PermissionRead bit,
				@PermissionDelete bit,
				@PermissionWrite bit,
				@IDRole2ModuleNew int =0;
			FETCH NEXT FROM CursorRole2Module INTO @IDRole2Module,@IDModule,@PermissionRead,@PermissionDelete,@PermissionWrite
			WHILE @@FETCH_STATUS = 0
			BEGIN
				
				INSERT INTO SysRole2Module(IDModule,IDRole,PermissionRead,PermissionDelete,PermissionWrite) VALUES (@IDModule,@IDRole,@PermissionRead,@PermissionDelete,@PermissionWrite)
				SET @IDRole2ModuleNew = (SELECT SCOPE_IDENTITY())

					-- Copy Role2Module2Field --
					DECLARE CursorRole2Module2Field CURSOR FOR SELECT IDField,PermissionLevel FROM SysRole2Module2Field WHERE IDRole2Module=@IDRole2Module
					OPEN CursorRole2Module2Field
					DECLARE @IDField int = 0,
							@PermissionLevel int=0;

						FETCH NEXT FROM CursorRole2Module2Field INTO @IDField,@PermissionLevel
						WHILE @@FETCH_STATUS = 0
						BEGIN

							INSERT INTO SysRole2Module2Field(IDField,IDRole2Module,PermissionLevel) VALUES (@IDField,@IDRole2ModuleNew,@PermissionLevel)

							FETCH NEXT FROM CursorRole2Module2Field INTO @IDField,@PermissionLevel
						END
					CLOSE CursorRole2Module2Field
					DEALLOCATE CursorRole2Module2Field
					-- End Role2Module2Field --

				FETCH NEXT FROM CursorRole2Module INTO @IDRole2Module,@IDModule,@PermissionRead,@PermissionDelete,@PermissionWrite
			END
		CLOSE CursorRole2Module
		DEALLOCATE CursorRole2Module

END
GO


-- ----------------------------
-- procedure structure for DeleteSysModule
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DeleteSysModule]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[DeleteSysModule]
GO

CREATE PROCEDURE [dbo].[DeleteSysModule]
	@IDModule int
AS
BEGIN	
	SET NOCOUNT ON;

	with tbl_menuitems as (
	select IDMenuItem from SysMenuItem WHERE IDModule = @IDModule OR IDModuleFilterView IN (
			SELECT IDModuleFilterView
			FROM SysModuleFilterView mfv
			INNER JOIN SysModuleCustomView cv on mfv.IDModuleCustomView = cv.IDModuleCustomView 
			where IDModule = @IDModule
	)
	union  all
	select SysMenuItem.IDMenuItem 
	from SysMenuItem
		inner join tbl_menuitems on SysMenuItem.idParentMenuItem = tbl_menuitems.IDMenuItem
	)
	DELETE FROM SysMenuItem where IDMenuItem in (select distinct IDMenuItem from tbl_menuitems);
		
	UPDATE SysTPopupField
	set IDModuleFilterView = NULL
	where IDModuleFilterView in (select IDModuleCustomView from SysModuleCustomView where IDModule = @IDModule);

	DELETE FROM SysModuleFilterViewRole WHERE IDModuleFilterView IN (select IDModuleFilterView FROM SysModuleFilterView WHERE IDModuleCustomView in (select IDModuleCustomView from SysModuleCustomView where IDModule = @IDModule))

	DELETE FROM SysModuleFilterView WHERE IDModuleCustomView in (select IDModuleCustomView from SysModuleCustomView where IDModule = @IDModule);
	 
	DELETE FROM SysModuleFilter WHERE IDModule = @IDModule

	DELETE FROM SysModuleCustomView WHERE IDModule = @IDModule
	
	DELETE FROM SysRole2Module2Field WHERE IDRole2Module in (select IDRole2Module from SysRole2Module where idmodule = @IDModule);

	DELETE FROM SysRole2Module WHERE idmodule = @IDModule;

	DELETE from SysModuleSeriesReportFiles WHERE IDModule = @IDModule;
	-- select*from SysModule2Module
	DELETE FROM SysModule2Module WHERE Module1ID = @IDModule OR Module2ID = @IDModule;

	DELETE FROM SysModuleRelated WHERE IDModule = @IDModule OR IDField in (select IDField from SysField WHERE IDModule = @IDModule);

	DELETE FROM SysField WHERE IDModule = @IDModule;

	DELETE FROM SysModule WHERE IDModule = @IDModule;
END
GO


-- ----------------------------
-- function structure for SM_GetNodePredictedPositions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SM_GetNodePredictedPositions]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SM_GetNodePredictedPositions]
GO

CREATE FUNCTION [dbo].[SM_GetNodePredictedPositions]
(

)
RETURNS 
@Res TABLE 
(
 PartID uniqueidentifier,
 Positions nvarchar(500)
)
AS
BEGIN
 declare @ReqID uniqueidentifier;
 declare @ReqPrevPosic uniqueidentifier;
 declare @ReqPartID uniqueidentifier;
 declare @PrevPosicCode nvarchar(50);
 declare @PrevMaqCode nvarchar(50);
 declare @desc nvarchar(500)
 declare @localdesc nvarchar(500)

 declare @PrevPart uniqueidentifier;
set @PrevPart=null
set @desc=''

	declare @DummyTable TABLE 
(
 PartID uniqueidentifier,
 PosicID uniqueidentifier,
 Positions nvarchar(500)
)


--Preencher Dummy Table
insert into @DummyTable(PartID,PosicID)
  select idpart,IDPosition from SysPrRoutineRequest pr where (workingstatus<>'88B381D9-D1DB-4C80-8E78-3076B1E196F2') and (pr.IDPosition<>cast(cast(0 as binary) as uniqueidentifier)	)	order by idpart

--Preencer Desc Posics
update dt set positions=rtrim(ctx.MachineCode)+' ('+rtrim(ctx.Code)+') '
from @DummyTable dt
left join SM_GetNodeContext()  ctx on dt.PosicID=ctx.id

--insert into @res(PartID,Positions) select PartID,Positions from @DummyTable

 DECLARE lc2 CURSOR LOCAL
 FOR select PartID,Positions from @DummyTable order by PartID
 OPEN lc2;
 FETCH NEXT FROM lc2
  INTO  @ReqPartID,@localdesc;

 WHILE @@FETCH_STATUS = 0
 BEGIN
	if (@PrevPart<>@ReqPartID) and (@desc<>'')
	begin
		insert into @res(PartID,Positions) values (@PrevPart,@desc)
		set @desc=''
	end

	if (@PrevPart is not null)
		set @desc= @desc+@localdesc+ ' ;'


	set @PrevPart=@ReqPartID

  FETCH NEXT FROM lc2
  INTO  @ReqPartID,@localdesc;
 END;
  
 CLOSE lc2;
 DEALLOCATE lc2;

	if (@desc<>'')
		insert into @res(PartID,Positions) values (@PrevPart,@desc)
	 
 RETURN

	 
 RETURN
END
GO


