-- ----------------------------
-- function structure for str2Distance
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[str2Distance]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[str2Distance]
GO

CREATE FUNCTION [dbo].[str2Distance](@s varchar(100),@lat decimal(12,9), @long decimal(12,9)) returns float as begin
	DECLARE @i as int
	set @i=CHARINDEX(',',@s)
	if( @i>0)
	begin		
		DECLARE @latTxt as varchar(100)
		set @latTxt = LEFT(@s,@i-1)
		DECLARE @longTxt as varchar(100)
		set @longTxt =  LTRIM(RIGHT(@s,LEN(@s) - @i ))

		DECLARE @lat2 as decimal(12,9)
		DECLARE @long2 as decimal(12,9)

		set @lat2= TRY_CONVERT(decimal(12,9), @latTxt)
		set @long2= TRY_CONVERT(decimal(12,9), @longTxt)

		if((@lat2 IS NULL) or (@long2 IS NULL ))
		begin 
			return NULL
		end
		else
		begin
			DECLARE @orig geography = geography::Point(@lat2, @long2, 4326);
			DECLARE @dest geography = geography::Point(@lat, @long, 4326);
			return @orig.STDistance(@dest)
		end
	end
	return NULL
end
GO


