-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetErosionGap]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetErosionGap]
GO

CREATE FUNCTION [dbo].[SS_GetErosionGap]
(
	@EletrodeID	uniqueidentifier
)
RETURNS float
AS
BEGIN
	--Regra de Gap de Erosão , pode ser diferente por cliente
	Declare @EGap float

	set @EGap =( select isnull(isnull(CMMRealGap,gap) ,0) from ss_eletrode where id=@EletrodeID)

	declare @SplitGap int= (Select top 1 isnull(EletrodeEDMGap,0) from ss_config)
	if @SplitGap=1
		Set @EGap= @EGap/2


	RETURN @EGap
END
GO


