	DROP FUNCTION [dbo].[TimeToTicks]
GO

CREATE FUNCTION [dbo].[TimeToTicks] (@hour int, @minute int, @second int)  
RETURNS bigint 
WITH SCHEMABINDING
AS 
-- converts the given hour/minute/second to the corresponding ticks
BEGIN 
RETURN (((@hour * 3600) + CONVERT(bigint, @minute) * 60) + CONVERT(bigint, @second)) * 10000000
END
GO


-- ----------------------------
-- function structure for ProductLinesOfDocument
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ProductLinesOfDocument]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ProductLinesOfDocument]
GO

CREATE FUNCTION [dbo].[ProductLinesOfDocument]
(	
	@IDModule uniqueidentifier,
	@IDRecord int
)
RETURNS TABLE 
AS
RETURN 
(
	select distinct pl.*, dl.IDRegister as IDRegisterDoc, dl.IDModule as IDRegisterDocModule 
	from DocumentLine dl 
	inner join DocumentLine pl on dl.productid = pl.IDRegister and dl.productidModule = pl.IDModule
	inner join Document doc on dl.IDRegister = doc.iddocument and dl.IDModule = doc.IDModule and doc.PartitionColumn = dl.PartitionColumn 
	where dl.IDLineType = 1 and dl.IDRegister = @IDRecord and dl.IDModule = @IDModule 
	and pl.Kind in(0,1) and pl.PartitionColumn = 1 and pl.IDLineType = 4
	and (pl.IDThirdParty = doc.doc_3rd or pl.IDThirdParty is null) and (pl.dbmask & doc.dbmask <> 0)
) ;
GO


