	declare @res nvarchar(50);
	declare @shortname nvarchar(50);
	declare @PArtOF uniqueidentifier;
	declare @Mould uniqueidentifier;

	select @Mould=mouldid,@PArtOF=parentid,@shortname=shortname from ss_object where id=@objectid
	set @res=@shortname;

	--SE tiver pai
	if @PArtOF is not null  and (@partof<>@Mould)
	begin
		select @shortname=shortname from ss_object where id=@PArtOF
		set @res=@shortname+'_E'+@res;
	end

--Se tiver molde
	if @Mould is not null 
	begin
		select @shortname=shortname from ss_object where id=@mould
		set @res=@shortname+'_'+@res;
	end

--SE for eletrodo
	declare @gap float
	declare @fam int
	declare @instancenum int

	select @gap=gap,@fam=EletrodeFamily, @instancenum=instancenum from ss_eletrode where id=@objectid
	if @gap is not null
	begin
		set @res=@res+'_Gap'+replace(cast(@gap as nvarchar(5)),'.','')
	end
	
		
	--Instance
	if @instancenum is not null
	begin
		set @res=@res+'-N'+cast(@instancenum as nvarchar(5))		
	end


	RETURN @res
END
GO


-- ----------------------------
-- function structure for DateToTicks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DateToTicks]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[DateToTicks]
GO

CREATE FUNCTION [dbo].[DateToTicks] (@year int, @month int, @day int)
RETURNS bigint
WITH SCHEMABINDING
AS
-- converts the given year/month/day to the corresponding ticks
BEGIN 
RETURN CONVERT(bigint, (((((((@year - 1) * 365) + ((@year - 1) / 4)) - ((@year - 1) / 100)) + ((@year - 1) / 400)) + dbo.MonthToDays(@year, @month - 1)) + @day) - 1) * 864000000000;
END
GO


