-- function structure for SS_GetGeneralStatistics
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetGeneralStatistics]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetGeneralStatistics]
GO

CREATE FUNCTION [dbo].[SS_GetGeneralStatistics]
(

)
RETURNS 
@Res TABLE 
(	id	int,
	Codigo nvarchar(50),
	Valor float
)
AS
BEGIN
	
	insert into @Res(id,Codigo,Valor) values (1,'Mould Count',(Select count(id) from SS_Mould));
	insert into @Res(id,Codigo,Valor) values (2,'Part Count',(Select count(id) from SS_object where typeid=1));
	insert into @Res(id,Codigo,Valor) values (3,'Eletrode Count',(Select count(id) from SS_eletrode));

	insert into @Res(id,Codigo,Valor) values (4,'Milled Parts',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		where t.idKind=dbo.MILLKind() and t.disponibilidade>2));


	insert into @Res(id,Codigo,Valor) values (5,'Measured Parts',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		where t.idKind=dbo.CMMKind() and t.disponibilidade>3));	

	insert into @Res(id,Codigo,Valor) values (6,'Parts waiting for milling',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		where t.idKind=dbo.MILLKind() and t.disponibilidade=2));

	insert into @Res(id,Codigo,Valor) values (7,'Parts waiting for measuring',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		where t.idKind=dbo.CMMKind() and t.disponibilidade=2));	

	insert into @Res(id,Codigo,Valor) values (8,'Milled Parts Today',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		inner join  SysWorkflowItemTimes tt on t.idWorkflowItem =tt.idWorkflowItem and day(tt.date)=day(getdate())
		where t.idKind=dbo.MILLKind() and tt.State=4));

	insert into @Res(id,Codigo,Valor) values (9,'Measured Parts Today',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		inner join  SysWorkflowItemTimes tt on t.idWorkflowItem=tt.idWorkflowItem and day(tt.date)=day(getdate())
		where t.idKind=dbo.CMMKind() and tt.State=4));

	insert into @Res(id,Codigo,Valor) values (10,'Modeled Parts Today',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		inner join  SysWorkflowItemTimes tt on t.idWorkflowItem=tt.idWorkflowItem and day(tt.date)=day(getdate())
		where t.idKind=dbo.CadKind() and tt.State=4));

	insert into @Res(id,Codigo,Valor) values (11,'CAM Programs made Today',(
		Select count(o.id) 
		from SS_object o inner join  SysWorkflowItem t on t.idRegisto=o.id
		inner join  SysWorkflowItemTimes tt on t.idWorkflowItem=tt.idWorkflowItem and day(tt.date)=day(getdate())
		where t.idKind=dbo.CAMKind() and t.disponibilidade=4));
	RETURN 
END
GO


-- ----------------------------
-- function structure for DateTimeToTicks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DateTimeToTicks]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[DateTimeToTicks]
GO

CREATE FUNCTION [dbo].[DateTimeToTicks] (@d datetime)
RETURNS bigint
WITH SCHEMABINDING
AS
-- converts the given datetime to .NET-compatible ticks
-- see http://msdn.microsoft.com/library/default.asp?url=/library/en-us/cpref/html/frlrfsystemdatetimeclasstickstopic.asp
BEGIN 
RETURN 
	dbo.DateToTicks(DATEPART(yyyy, @d), DATEPART(mm, @d), DATEPART(dd, @d)) +
	dbo.TimeToTicks(DATEPART(hh, @d), DATEPART(mi, @d), DATEPART(ss, @d)) +
	(CONVERT(bigint, DATEPART(ms, @d)) * CONVERT(bigint,10000));
END
GO


