-- ----------------------------
-- procedure structure for Query_SoliworksMarketingAnalysis
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_SoliworksMarketingAnalysis]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_SoliworksMarketingAnalysis]
GO

CREATE PROCEDURE [dbo].[Query_SoliworksMarketingAnalysis]
AS
BEGIN
	SET NOCOUNT ON;


	select
		lead_no,
		leads.designation,
		f.code as [status],
		cast(Leads.CreatedTime as date) as Createdtime,	
		coalesce(FollowUpItem.Code, '') as Opport		
	from 
		Leads 
		left join FollowUpItem on leads.IDOpportunity = FollowUpItem.IDFollowUpItem 
		left join SysFieldValueItem f on leads.status = f.CodeInt and f.GroupCode = 'LeadStatus                    '
	where 
	((Leads.CreatedTime >= '2018-07-10' and Leads.CreatedTime < '2018-10-01' )
		OR
		(Leads.IDOpportunity in (
			select FollowUpItem.IDFollowUpItem
			from FollowUpItem left join
				(select CodeInt, code
			from SysFieldValueItem
			where GroupCode = 'Oportunity Sales Stage        '
			) aux on FollowUpItem.[Status] = aux.CodeInt
			where 
				((CreatedTime >= '2018-07-10' and CreatedTime < '2018-10-01' )
				OR
				cast(IDFollowUpItem as nvarchar) in 
				(
					select IDRecord
					from SysModuleTracker mt
					inner join 
					SysModuleTrackerDetail mtd on mt.IDModuleTracker = mtd.IDModuleTracker
					where cast(NewValue as nvarchar(max)) = '2421' and cast(OldValue as nvarchar(max)) != '2421' and idmodule in (select idmodule from dbo.GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1'))
					and (StartDate >= '2018-07-10' and StartDate < '2018-10-01')		
				)
				)
				and	
				idmodule in (select idmodule from dbo.GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1'))
				and (dbmask & 3) != 0
				and IDBusinessArea = 11
	
		))
		) and Leads.IDBusinessArea = 11 and (Leads.dbmask & 3) != 0


	select FollowUpItem.Code, [Name], aux.Code as [Status], cast(CreatedTime as date) as createdTime, coalesce(
			cast(cast((select max( StartDate)
			from SysModuleTracker mt
			inner join 
			SysModuleTrackerDetail mtd on mt.IDModuleTracker = mtd.IDModuleTracker
			where 
			IDRecord = cast(FollowUpItem.IDFollowUpItem as nvarchar) and
			FollowUpItem.[Status] = 2421 and
			cast(NewValue as nvarchar(max)) = '2421' and cast(OldValue as nvarchar(max)) != '2421' and idmodule in (select idmodule from dbo.GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1'))		
	) as date) as nvarchar)			
			, '') as CloseTime
	from FollowUpItem left join
		(select CodeInt, code
	from SysFieldValueItem
	where GroupCode = 'Oportunity Sales Stage        '
	) aux on FollowUpItem.[Status] = aux.CodeInt
	where 
		((CreatedTime >= '2018-07-10' and CreatedTime < '2018-10-01' )
		OR
		cast(IDFollowUpItem as nvarchar) in 
		(
			select IDRecord
			from SysModuleTracker mt
			inner join 
			SysModuleTrackerDetail mtd on mt.IDModuleTracker = mtd.IDModuleTracker
			where cast(NewValue as nvarchar(max)) = '2421' and cast(OldValue as nvarchar(max)) != '2421' and idmodule in (select idmodule from dbo.GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1'))
			and (StartDate >= '2018-07-10' and StartDate < '2018-10-01')		
		)
		)
		and	
		idmodule in (select idmodule from dbo.GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1'))
		and (dbmask & 3) != 0
		and IDBusinessArea = 11
END
GO


-- ----------------------------
-- procedure structure for SysBigTables
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysBigTables]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SysBigTables]
GO

CREATE PROCEDURE [dbo].[SysBigTables]

AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT 
		t.name AS TableName,
		i.name as indexName,
		sum(p.rows) as RowCounts,
		sum(a.total_pages) as TotalPages, 
		sum(a.used_pages) as UsedPages, 
		sum(a.data_pages) as DataPages,
		(sum(a.total_pages) * 8) / 1024 as TotalSpaceMB, 
		(sum(a.used_pages) * 8) / 1024 as UsedSpaceMB, 
		(sum(a.data_pages) * 8) / 1024 as DataSpaceMB
	FROM 
		sys.tables t
	INNER JOIN      
		sys.indexes i ON t.object_id = i.object_id
	INNER JOIN 
		sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id
	INNER JOIN 
		sys.allocation_units a ON p.partition_id = a.container_id
	WHERE 
		t.name NOT LIKE 'dt%' AND
		i.object_id > 255 AND  
		i.index_id <= 1
	GROUP BY 
		t.name, i.object_id, i.index_id, i.name 
	ORDER BY 
		TotalPages
		DESC
END
GO


