CREATE FUNCTION [dbo].[IsRecordLocked]
(
 @IDModule uniqueidentifier,
 @IDRecord nvarchar(MAX)
)
RETURNS  int
AS
BEGIN

 DECLARE @IdLock uniqueidentifier;
 declare @R int;
 SET @IdLock=(Select IDLock FROM SysLockRecord WHERE IDModule=@IDModule AND IDRecord=@IDRecord AND [Status] = 1);
 
 IF @IdLock IS NULL
	set @R = 0
  ELSE
	set @R = 1

  return @R
END
GO


-- ----------------------------
-- function structure for SS_GetObjectChilds
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetObjectChilds]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetObjectChilds]
GO

CREATE FUNCTION [dbo].[SS_GetObjectChilds]
(
	@ParentID uniqueidentifier
)
RETURNS 
@Res TABLE 
(
	id uniqueidentifier
)
AS
BEGIN
	insert into @res values (@ParentID);
	WITH    v (idv) AS
			(
			SELECT  id
			FROM    ss_Object
			WHERE   ParentID = @ParentID
	        
			UNION ALL
	        
			SELECT  id
			FROM    v
			JOIN    ss_Object t
			ON      t.ParentID = v.idv
			)
	insert into @res    
	SELECT  *
	FROM    v
	option (maxrecursion 0)

	
	RETURN 
END
GO


