-- ----------------------------
-- procedure structure for CopyWorkflowConditionStepFromTemplate
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CopyWorkflowConditionStepFromTemplate]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CopyWorkflowConditionStepFromTemplate]
GO

CREATE PROCEDURE [dbo].[CopyWorkflowConditionStepFromTemplate]
	-- Add the parameters for the stored procedure here
	@idWorkflow int = 0,
	@IDWorkflowCondition int = 0, 
	@IDWorkflowConditionStep int = 0,
	@IDWorkflowConditionStepNew int output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	INSERT INTO [dbo].[SysWorkflowConditionsStep] ([IDCondition] ,[IDWorkflowVar] ,[Operator] ,[Value] ,[Condition] ,[IDParent], [Template])
    SELECT @IDWorkflowCondition ,
	(SELECT ISNULL(IDWorkflowVars,0) FROM [dbo].[SysWorkflowVars] WHERE IDWorkflow = @idWorkflow AND Template = ( SELECT [IDWorkflowVar] FROM [SysWorkflowConditionsStep] WHERE IDWorkflowConditionsStep = @IDWorkflowConditionStep)) ,
	[Operator] ,[Value] ,[Condition] ,
	/*SELECT COALESCE((SELECT ISNULL(IDWorkflowConditionsStep,0) FROM [dbo].[SysWorkflowConditionsStep] WHERE Template = ( SELECT ISNULL([IDParent],0) FROM [dbo].[SysWorkflowConditionsStep] WHERE IDWorkflowConditionsStep = @IDWorkflowConditionStep ) AND IDCondition = @IDWorkflowCondition),0), */
	(SELECT COALESCE((SELECT COALESCE(IDWorkflowConditionsStep,0) FROM [dbo].[SysWorkflowConditionsStep] WHERE Template = ( SELECT ISNULL([IDParent],0) FROM [dbo].[SysWorkflowConditionsStep] WHERE IDWorkflowConditionsStep = @IDWorkflowConditionStep ) AND IDCondition = @IDWorkflowCondition),0)),
	/*SELECT COALESCE((SELECT coalesce(b.IDWorkflowConditionsStep, 0) AS 'IDPARENT' FROM [dbo].[SysWorkflowConditionsStep] a	LEFT JOIN  [dbo].[SysWorkflowConditionsStep] B ON a.IDWorkflowConditionsStep = b.IDParent where a.IDCondition = @IDWorkflowCondition AND a.Template = @IDWorkflowConditionStep),*/
	@IDWorkflowConditionStep  FROM [dbo].[SysWorkflowConditionsStep] WHERE [IDWorkflowConditionsStep] = @IDWorkflowConditionStep;
	SET @IDWorkflowConditionStepNew = (SELECT SCOPE_IDENTITY())
END
GO


