GO

CREATE FUNCTION [dbo].[GetProductUsageInDocuments]
(	
	@IDProduct int,
	@IDProductModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	
	select
		d.IDDocument,
		d.IDModule as IDDocumentModule,

		d.doc_ref,
		d.doc_date,
		d.doc_3rd_account,
		d.doc_3rd_account_name,
		d.doc_3rd_accountModule,
		d.doc_3rd,
		d.doc_3rdModule,
		d.[subject],
		d.doc_3rd_date,
		d.doc_3rd_ref,
		d.status,
		d.RegisterStatus,

		dl.ID as IDDocLine,
		dl.lineNumber,
		dl.ProductName,
		dl.Designation,
		dl.Qty,
		dl.UnitPrice,
		dl.DiscountPerc1,
		dl.DiscountPerc2,
		dl.DiscountPerc3,
		dl.DiscountEur,
		dl.AssetSerial,
		dl.NetTotal
		-- ,*
	from 
		document d 
	
		inner join documentline dl on d.iddocument = dl.idregister and d.IDModule = dl.IDModule
	where
		@IDProduct != 0
		AND
		dl.productid = @IDProduct
		and
		dl.productidModule = @IDProductModule
		and
		d.RegisterSysStatus = 0
)
GO


