-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TaskLockedRegisters]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[TaskLockedRegisters]
GO

CREATE PROCEDURE [dbo].[TaskLockedRegisters]
AS
BEGIN
	-- Default Timeout : 1 Minutes
	DECLARE @MinutesLockedTimeout int ;
	Set @MinutesLockedTimeout=1;
	SELECT @MinutesLockedTimeout = Value from SysSettings where [Type]='GeneralSettings' AND Name='LockedTimeout';
	
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	BEGIN TRANSACTION LRDelete
	
	DELETE FROM SysLockRecord where  dateadd(minute, @MinutesLockedTimeout, StartDate)<=GETUTCDATE() 

	COMMIT TRANSACTION LRDelete;
END
GO


