-- ----------------------------
-- procedure structure for CheckActivePersonLoginResourceConnection
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CheckActivePersonLoginResourceConnection]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CheckActivePersonLoginResourceConnection]
GO

CREATE PROCEDURE [dbo].[CheckActivePersonLoginResourceConnection]
AS
BEGIN
	with activeConnections as(
		select l2r.IDLogin2Resource
		from SysLogin2SysResource l2r
		inner join Entity e on l2r.IDPerson = e.organizationid and l2r.IDPersonModule = e.IDModule 
		inner join SysLogin l on l.IDLogin = e.IDRelatedLogin and l2r.IDLogin = l.IDLogin
		inner join SysResources r on r.ResourceId = l2r.IDResource
		where l.Active = 1 and r.Active = 1 and (
			(GETDATE() between isnull(l2r.StartDate, '1900-01-01') and ISNULL(l2r.EndDate,'2099-12-31')) 
		)
		union all
		select l2r.IDLogin2Resource
		from SysLogin2SysResource l2r
		inner join SysLogin l on l2r.IDLogin = l.IDLogin
		inner join SysResources r on r.ResourceId = l2r.IDResource
		where l.Active = 1 and r.Active = 1 and
		r.Kind in(
			5,7
		)
	)
	UPDATE SysLogin2SysResource set Active = 
	case 
		when IDLogin2Resource in(
			select IDLogin2Resource from activeConnections
		) then 1
		else 0
	end;

	update SysLogin Set ActiveIDLogin2Resource = t.IDActiveL2r
	from(
		select l.IDLogin IDL, l2r.IDLogin2Resource IDActiveL2r
		from SysLogin l
		left join entity e on e.IDRelatedLogin = l.IDLogin
		left join SysLogin2SysResource l2r on l2r.IDPerson = e.organizationid and l2r.IDLogin = l.IDLogin and l2r.Active = 1
	) t
	where IDLogin = t.IDL;


	update SysResources Set ActiveIDLogin2Resource = t.IDActiveL2r
	from(
		select r.ResourceId IDR, l2r.IDLogin2Resource IDActiveL2r
		from SysResources r
		left join SysLogin2SysResource l2r on l2r.IDResource = r.ResourceId and l2r.Active = 1
	) t
	where ResourceId = t.IDR;

declare it cursor for
select distinct l2r.IDPerson
from SysResources r
left join SysLogin2SysResource l2r on l2r.IDResource = r.ResourceId 

open it;

declare @idrecord int

fetch next from it into @idrecord

while @@FETCH_STATUS = 0
begin
	exec [UpdateEntityCalculatedFields] @idrecord

	fetch next from it into @idrecord
end

close it;
deallocate it;

END
GO


