-- ----------------------------
-- procedure structure for UpdatePersonLoginResourceConnection
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdatePersonLoginResourceConnection]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdatePersonLoginResourceConnection]
GO

CREATE PROCEDURE [dbo].[UpdatePersonLoginResourceConnection]
	@IDPerson int null,
	@IDLogin uniqueidentifier null
AS
BEGIN
	if @IDPerson is not null
	begin
		
		declare @CurrentPersonLogin uniqueidentifier = (select top 1 idrelatedlogin from Entity where organizationid = @IDPerson);
		
		update SysLogin 
		set IDPerson = @IDPerson, IDPersonModule = '28bee890-28fa-45e2-8d51-8d30f36c4f04' 
		where IDLogin = @CurrentPersonLogin;	

		update SysLogin 
		set IDPerson = null, IDPersonModule = null
		where IDPerson = @IDPerson and IDLogin <> @CurrentPersonLogin;	

		update SysLogin2SysResource
		set IDLogin = @CurrentPersonLogin 
		where IDPerson = @IDPerson;
	end

	if @IDLogin is not null
	begin 
		declare @CurrentLoginPerson int = (select top 1 IDPerson from SysLogin where IDLogin = @IDLogin);
		
		update Entity 
		set IDRelatedLogin = @IDLogin
		where organizationid = @CurrentLoginPerson;	

		update Entity 
		set IDRelatedLogin = null
		where IDRelatedLogin = @IDLogin and organizationid <> @CurrentLoginPerson;	

		update SysLogin2SysResource
		set IDLogin = @IDLogin 
		where IDPerson = @CurrentLoginPerson;

		update SysLogin2SysResource
		set IDPerson = @CurrentLoginPerson 
		where IDPerson is null and IDLogin = @IDLogin;
	end
END;
GO


-- ----------------------------
-- function structure for GetResourceUsernames
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourceUsernames]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourceUsernames]
GO

CREATE FUNCTION [dbo].[GetResourceUsernames]
(
	@idResource uniqueidentifier,
	/* 
		0: username
		1: fullname
		2: nick
		3: nick when exists, fullname if not, username if not
	*/
	@k int 
)
RETURNS nvarchar(max)
AS
BEGIN
	
	declare @t nvarchar(max)
	set @t = ''

	declare @u nvarchar(max)

	declare it cursor for 
		select case @k 
					when 3 then coalesce(
						case when trim(l.Nick) = '' then null else trim(l.Nick) end, 
						case when trim(l.Fullname) = '' then null else trim(l.Fullname) end, 
						case when trim(l.username) = '' then null else trim(l.username) end)
					when 2 then trim(l.Nick)
					when 1 then trim(l.FullName)
					else -- 0 / any other param
						trim(l.Username)
					end
		from SysLogin l with (nolock)
			inner join SysLogin2SysResource l2r with (nolock) on l.IDLogin = l2r.IDLogin
		where
			l2r.IDResource = @idResource
			and
			l.Active = 1 and l2r.Active = 1

	open it

	fetch next from it into @u

	while @@FETCH_STATUS = 0
	begin
		if @u != '' and not @u is null
		begin
			set @t = CONCAT(@t, case when @t = '' then '' else ', ' end, @u)
		end
		fetch next from it into @u
	end

	close it
	deallocate it

	set @t = TRIM(@t)
	
	RETURN @t

END
GO


