-- ----------------------------
-- function structure for GetResourcesTeamMask02
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourcesTeamMask02]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourcesTeamMask02]
GO

CREATE FUNCTION [dbo].[GetResourcesTeamMask02]
(
	@IDResource as uniqueidentifier
)
RETURNS bigint
AS
BEGIN
	DECLARE @mask02 bigint,
	@mask bigint
	set @mask =0

	DECLARE CursorTeams CURSOR FOR
	select  t.Mask2
		from SysTeam t
		Inner join SysActivityRoleResource rr on rr.IDTeam=t.IDTeam
		where rr.IDResource=@IDResource

	OPEN CursorTeams
	FETCH NEXT FROM CursorTeams INTO @mask02					
	WHILE  @@FETCH_STATUS = 0
	BEGIN
		
		set  @mask |= @mask02

		FETCH NEXT FROM CursorTeams INTO @mask02	
	END
	CLOSE CursorTeams 
	DEALLOCATE CursorTeams 

	return @mask
END
GO


-- ----------------------------
-- procedure structure for CreateOrUpdateAccStockParent
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreateOrUpdateAccStockParent]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreateOrUpdateAccStockParent]
GO

CREATE PROCEDURE [dbo].[CreateOrUpdateAccStockParent]
(
	@IDAccount int,
	@IDModule uniqueidentifier
)
AS
BEGIN
	
	declare @ParentAccountID int = 
	(
		select accP.IDAccount 
		from Account accP
		inner join Account acc on acc.IDContact = accp.IDContact and acc.IDContactModule = accp.IDContactModule 
		and acc.IDAccount <> accp.IDAccount and accp.IDModule = acc.IDModule
		where acc.IDAccount = @IDAccount and acc.IDModule = @IDModule and accp.IDParent is null and accp.IsRootAccount = 1
	);

	if(@ParentAccountID is null)
	begin

		DECLARE @tmp TABLE ( 
            IDAccount INT NOT NULL 
        );

		declare @CurrentCounter int = (select CurrentCounter + 1 from SysModule where IDModule = @IDModule);
		declare @Mask nvarchar(50) = concat
		(
		'ACC_ST_',
		(
			select case 
				when @idmodule = '5E2F05BF-DB92-4862-8EDD-29E997E33ED3' then 'CS_'
				when @idmodule = '7BA87029-2F44-4B10-8138-456238785232' then 'IS_'
				when @idmodule = 'F0E74E40-B1A1-4D7C-B3A9-74E0C09F019C' then 'X3D_'
				when @idmodule = '2357c11c-9727-494d-8643-b3e707009bc4' then 'SC_'
			end
		), right(concat('0000', @CurrentCounter ), 6)
		);

		INSERT INTO Account  (
		[Name], [IDContact], [dbmask], [AccountType], [IsTemplate],  [ModifiedTime]
		, [CreatedTime], [record_no], [account_no], [account_no_counter], [RegisterStatus]
		, [RegisterSysStatus], [IDModule], [IDContactModule], [IDUserCreation]
		, [IDUser], [IDResourceCreation], [IDResource], [IDResourceAssign], [AccG01], [AccG02]
		, [AccountMovementType], [account_no_IsTemp], [IDTemplateSource], [IDTemplateSourceModule]
		, [TeamMask01], [TeamMask02], [TemplateDefaultMFVCreate], [Dirty], [IsRootAccount]) OUTPUT inserted.[IDAccount] INTO @tmp(IDAccount)
		SELECT p.productcode AS [Name], p.productid AS [IDContact], acc.dbmask AS [dbmask], 4 AS [AccountType], 'False' AS [IsTemplate], 
		GETDATE() AS [ModifiedTime], GETDATE() AS [CreatedTime], 
		p.productcode AS [record_no], 
		@Mask, 
		@CurrentCounter
		, 0 AS [RegisterStatus],  0 AS [RegisterSysStatus], acc.IDModule AS [IDModule], 
		acc.IDContactModule AS [IDContactModule],  acc.IDUserCreation AS [IDUserCreation], 
		acc.[IDUser] AS [IDUser], acc.[IDResourceCreation] AS [IDResourceCreation], 
		acc.[IDResource] AS [IDResource], acc.[IDResourceAssign] AS [IDResourceAssign], 
		15 AS [AccG01], 0 AS [AccG02], 1 AS [AccountMovementType],  0 AS [account_no_IsTemp],  acc.IDTemplateSource AS [IDTemplateSource], 
		acc.[IDTemplateSourceModule] AS [IDTemplateSourceModule],  -1 AS [TeamMask01], -1 AS [TeamMask02], 
		1 AS [TemplateDefaultMFVCreate], 0 AS [Dirty], 1 as [IsRootAccount]
		from Account acc 
		inner join products p on p.productid = acc.IDContact and p.IDModule = acc.IDContactModule
		where acc.IDAccount = @IDAccount

		set @ParentAccountID = (select top 1 IDAccount from @tmp);

		update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @IDModule;

		INSERT INTO AccountStock  (
		[IDAccount], [dbmask], [IDModule], [IsTemplate], [ModifiedTime], [CreatedTime]
		, [RegisterStatus], [RegisterSysStatus], [IDUserCreation], [IDUser], [IDResourceCreation], [IDResource]
		, [IDResourceAssign], [IDTemplateSource], [IDTemplateSourceModule]
		, [TeamMask01], [TeamMask02], [TemplateDefaultMFVCreate], [usageunit], [usageunitModule]
		, [StockManagement], [StockLimitType]
		) 
		SELECT @ParentAccountID AS [IDAccount],
		1 AS [dbmask], acc.IDModule AS [IDModule], 'False' AS [IsTemplate], 
		getdate() AS [ModifiedTime], getdate() AS [CreatedTime], 
		0 AS [RegisterStatus], 0 AS [RegisterSysStatus], acc.[IDUserCreation] AS [IDUserCreation], acc.[IDUser] AS [IDUser], acc.[IDResourceCreation] AS [IDResourceCreation],  
		acc.[IDResource] AS [IDResource], acc.[IDResourceAssign] AS [IDResourceAssign], 
		acc.IDContact AS [IDTemplateSource], acc.IDContactModule AS [IDTemplateSourceModule], 
		-1 AS [TeamMask01], -1 AS [TeamMask02], 1 AS [TemplateDefaultMFVCreate], 
		stk.usageunit, stk.usageunitModule, stk.StockManagement, stk.StockLimitType
		from Account acc 
		inner join AccountStock stk on stk.IDAccount = acc.IDAccount
		where acc.IDAccount = @IDAccount

		exec CreateAccountRootMovements @ParentAccountID, @IDModule;

	end

	update Account set IDParent = @ParentAccountID, IDParentModule = @IDModule where IDAccount = @IDAccount;

	exec UpdateAccountRootMovementParent @IDAccount, @IDModule;
	exec UpdateAccountBalances @ParentAccountID, @IDModule;
END
GO


