IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetFixtureAvailable]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetFixtureAvailable]
GO

CREATE PROCEDURE [dbo].[GetFixtureAvailable] (
  @template uniqueidentifier
)
AS 
BEGIN
SET NOCOUNT ON;
    declare @id uniqueidentifier;

    set ROWCOUNT 1
    Update SysFixture Set 
      State = 'CD23AE47-4DF4-4BAA-AF91-B58A4C6B072E', @id = ID
      where 
      fixturetemplate = @template and (State is null or State ='27BD4F95-6593-4105-ACC1-82A9299A25BC'  or State ='6D3BC355-46D9-4509-AE3F-2D75FE9482AF');
    set ROWCOUNT 0
    select top 1 * from [SysFixture] where Id = @id
END
GO


-- ----------------------------
-- procedure structure for ResetPocValueDisableAccountST
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ResetPocValueDisableAccountST]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ResetPocValueDisableAccountST]
GO

CREATE PROCEDURE [dbo].[ResetPocValueDisableAccountST]
    @IDAccount INT
AS
BEGIN
    BEGIN TRANSACTION T1;

    BEGIN TRY
        -- Reset Times to be processed
        UPDATE SysTimes
        SET Dirty = 1,
            IDPocValueAccounting = NULL
        WHERE IDPocValueAccounting IN (
            SELECT IDPocValue
            FROM SysPocValue
            WHERE IDRecord = @IDAccount AND IDPocValue IS NOT NULL
        );

        -- Delete SysPocValue entries with IDSrcTimes
        DELETE FROM SysPocValue
        WHERE IDRecord = @IDAccount AND IDSrcTimes IS NOT NULL;

        -- Delete SysPocValue entries with IDParent
        DELETE FROM SysPocValue
        WHERE IDRecord = @IDAccount AND IDParent IS NOT NULL;

        -- Reset Stock counters
        UPDATE SysPocValue
        SET QtyActualStock = 0,
            TotalQtyActualStock = 0,
            TotalCredit = 0,
            TotalDebit = 0
        WHERE IDRecord = @IDAccount AND IDParent IS NULL;

        -- Disable Account
        UPDATE Account
        SET Status = 1
        WHERE IDAccount = @IDAccount;


        COMMIT TRANSACTION T1;
    END TRY
    BEGIN CATCH
        -- Rollback transaction in case of an error
        ROLLBACK TRANSACTION T1;

        -- Re-throw the error to be handled by the caller
        THROW;
    END CATCH
END
GO


-- ----------------------------
-- function structure for GetResourceUserCount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourceUserCount]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourceUserCount]
GO

CREATE FUNCTION [dbo].[GetResourceUserCount]
(
	@resourceId uniqueidentifier
)
RETURNS int
AS
BEGIN

	declare @c int 
	set @c = 0

	select @c = count(*)
	from SysLogin l 
		inner join SysLogin2SysResource l2r on l.IDLogin = l2r.IDLogin and l2r.Active = 1
	where l.Active = 1 and l2r.IDResource = @resourceId

	return @c
END
GO


