-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetProductionRoutineSimulationBaseData]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetProductionRoutineSimulationBaseData]
GO

CREATE FUNCTION [dbo].[GetProductionRoutineSimulationBaseData]
(	
	@IDSimulation uniqueidentifier,
	@SimulationDate datetime,
	@IsSimulatedNode int,
	@IDRoutine uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT @IDSimulation as IDSimulation, @SimulationDate as SimulationDate, Code,Description,r.IDRoutine,IDAsset,IDAssetModule,
	PartID,Priority,WorkingStatus,ItemDescription,ItemStartDate,ItemEndDate,
	r.IDRoutineItem,
	VirtualNode,MouldNo,FUPName,Next,Prev,StartDate,EndDate,IDResource,
	IDPhaseTemplate,PhaseTemplateDesc,BGColor,FGColor,IDFollowUpItem,
	IDFollowUpItemModule,AssetNumber,AssetMouldNumber,RoutineWStatusBGColor,RoutineWStatusFGColor,
	Status,DeadLineMould,DeadLinePart,DeadLineOperation,
	DeadLineMouldStatus,DeadLinePartStatus,DeadLineOperationStatus, 
	@IsSimulatedNode IsSimulatedNode, IDOperationType, IDProcessRoutineItem
	FROM AllProductionRoutinesRunning r
	left join AllProductionRoutinesRunningLinks l on l.idroutineitem = r.idroutineitem
	left join 
	(
		select distinct t.idroutine, t.idroutineitem, itemstartdate, itemEndDate, deadlinemouldstatus, deadlinepartstatus, deadlineoperationstatus,startdate, enddate,idresource
		from AllProductionRoutinesRunningTasks t
		where t.idroutine = @IDRoutine and WorkingStatus <> 'CD69321D-BF74-4503-A9D6-0614F0C7CE01' 
	) t on t.idroutineitem = r.IDRoutineItem and t.idroutine = r.idroutine                    
	where r.IDRoutine = @IDRoutine  
	AND WorkingStatus <> 'CD69321D-BF74-4503-A9D6-0614F0C7CE01'
)
GO


-- ----------------------------
-- procedure structure for DeleteModuleFilterView
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DeleteModuleFilterView]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[DeleteModuleFilterView]
GO

CREATE PROCEDURE [dbo].[DeleteModuleFilterView]
	@IDModuleFilterView int
AS
BEGIN
	SET NOCOUNT ON;

	with tbl_menuitems as (
	select IDMenuItem from SysMenuItem WHERE IDModuleFilterView = @IDModuleFilterView
	
	union  all
	select SysMenuItem.IDMenuItem 
	from SysMenuItem
		inner join tbl_menuitems on SysMenuItem.idParentMenuItem = tbl_menuitems.IDMenuItem
	)
		
	DELETE FROM SysMenuItem where IDMenuItem in (select distinct IDMenuItem from tbl_menuitems);

	UPDATE SysTPopupField
	set IDModuleFilterView = NULL
	where IDModuleFilterView = @IDModuleFilterView;

	DELETE FROM SysModuleFilterViewRole WHERE IDModuleFilterView = @IDModuleFilterView;

	DELETE FROM SysModuleFilterView WHERE IDModuleFilterView = @IDModuleFilterView;
	
END
GO


