	DROP FUNCTION [dbo].[ReadProductPocValuesTF_Stock]
GO

CREATE FUNCTION [dbo].[ReadProductPocValuesTF_Stock]
(	
	@IDProduct int,
	@IDModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	select poc.*, p.productid as IDProduct, p.IDModule as IDProductModule, acc.dbmask
	from products p
	inner join Account acc on acc.IDContact = p.productid and acc.IDContactModule = p.IDModule and acc.IsRootAccount = 1
	cross apply ReadPocValuesTF_Stock(acc.IDModule, acc.IDAccount) poc
	where p.productid = @IDProduct and p.IDModule = @IDModule and acc.dbmask & 2 = 0
);
GO


