CREATE PROCEDURE [dbo].[SM_MergeObjects]
	@TargetObjectID uniqueidentifier,
	@SourceObjectID uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @TargetExists int
	declare @SourceExists int

	set @TargetExists= (Select count(id) from SS_Object where id=@TargetObjectID)
	set @SourceExists= (Select count(id) from SS_Object where id=@SourceObjectID)

	if (@TargetExists>0) and (@SourceExists>0)
	begin

		-- Info de BLANK para PART
		update Part set 
			Part.DimBlock_X=Blank.DimBlock_X,
			Part.DimBlock_Y=Blank.DimBlock_Y,
			Part.DimBlock_Z=Blank.DimBlock_Z,
			Part.DispBlock_X=Blank.DispBlock_X,
			Part.DispBlock_Y=Blank.DispBlock_Y,
			Part.DispBlock_Z=Blank.DispBlock_Z,
			Part.MILLRC=Blank.MILLRC,
			Part.IDHolder=Blank.IDHolder,
			Part.IDMillBase=Blank.IDMillBase,
			Part.IdMaterial=BLank.idmaterial,
			Part.BlankTemplateID=Blank.BlankTemplateID,
			Part.BlankinstanceCode=Blank.Fullname,
			Part.BlankNeeded=0
		from SS_object Part
		left join ss_object Blank on blank.id=@SourceObjectID
		where part.id=@TargetObjectID

		--insert into SS_ObjectNotes(IDLogin, Note, IDOperation, ReadOnly, Data, UserMsg, Importance, IDObject)
		--	select IDLogin, Note, IDOperation, ReadOnly, Data, UserMsg, Importance, @TargetObjectID
		--	from SS_ObjectNotes where IDObject=@SourceObjectID

		--MERGE DE OPERAçÕES - VER COM O SERGIO que tabelas sao

		--DELETE Blank
		Delete from ss_object where id=@SourceObjectID
		--Delete from SS_ObjectNotes where IDObject=@SourceObjectID
		Delete from sm_nodepart where id=@SourceObjectID

	end


END
GO


