-- function structure for GetCommercialMobile
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetCommercialMobile]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetCommercialMobile]
GO

CREATE FUNCTION [dbo].[GetCommercialMobile]
(
	@IdContact int ,
	@dbmask int
)
RETURNS nvarchar(max)
AS
BEGIN
	declare @r nvarchar(max)
	select top 1
		-- e.organizationid, e.accountname,
		@r = coalesce(
			case when rtrim(e2e.mobile) = '' then null else e2e.mobile end, 
			case when rtrim(e2e.phone) = '' then null else e2e.phone end, 
			case when rtrim(e.mobile) = '' then null else e.mobile end, 
			case when rtrim(e.phone) = '' then null else e.phone end, 
			case when rtrim(p.mobile) = '' then null else p.mobile end, 
			case when rtrim(p.phone) = '' then null else p.phone end) -- , as ComputedEmail,
		-- e.email, e.email2, e2e.Email, p.email, p.email2
	from 
		Entity e
		inner join Entity2Entity e2e on e.organizationid = e2e.IDRecEntityChild and e2e.dbmask = @dbmask
		inner join entity p on p.organizationid = e2e.IDRecEntity
		inner join SysDB db on p.organizationid = db.idcompany and db.dbmask = @dbmask
	where
		e.organizationid = @IdContact


	if @r is null or @r = '' 
	begin
		select top 1
			-- e.organizationid, e.accountname,
			@r = coalesce(
				case when rtrim(e2e.mobile) = '' then null else e2e.mobile end, 
				case when rtrim(e2e.phone) = '' then null else e2e.phone end, 
				case when rtrim(e.mobile) = '' then null else e.mobile end, 
				case when rtrim(e.phone) = '' then null else e.phone end, 
				case when rtrim(p.mobile) = '' then null else p.mobile end, 
				case when rtrim(p.phone) = '' then null else p.phone end) -- , as ComputedEmail,
			-- e.email, e.email2, e2e.Email, p.email, p.email2
		from 
			Entity e
			inner join Entity2Entity e2e on e.organizationid = e2e.IDRecEntityChild
			inner join entity p on p.organizationid = e2e.IDRecEntity
			inner join SysDB db on p.organizationid = db.idcompany and db.dbmask = @dbmask
		where
			e.organizationid = @IdContact
	end
	

	if @r is null or @r = '' 
	begin
		select top 1
			-- e.organizationid, e.accountname,
			@r = coalesce(
			case when rtrim(e2e.mobile) = '' then null else e2e.mobile end, 
			case when rtrim(e2e.phone) = '' then null else e2e.phone end, 
			case when rtrim(e.mobile) = '' then null else e.mobile end, 
			case when rtrim(e.phone) = '' then null else e.phone end, 
			case when rtrim(p.mobile) = '' then null else p.mobile end, 
			case when rtrim(p.phone) = '' then null else p.phone end) -- , as ComputedEmail,
			-- e.email, e.email2, e2e.Email, p.email, p.email2
		from 
			Entity e
			inner join Entity2Entity e2e on e.organizationid = e2e.IDRecEntity and e2e.dbmask = @dbmask
			inner join entity p on p.organizationid = e2e.IDRecEntityChild
			inner join SysDB db on p.organizationid = db.idcompany and db.dbmask = @dbmask
		where
			e.organizationid = @IdContact
	end


	if @r is null or @r = '' 
	begin
		select top 1
			-- e.organizationid, e.accountname,
			@r = coalesce(
			case when rtrim(e2e.mobile) = '' then null else e2e.mobile end, 
			case when rtrim(e2e.phone) = '' then null else e2e.phone end, 
			case when rtrim(e.mobile) = '' then null else e.mobile end, 
			case when rtrim(e.phone) = '' then null else e.phone end, 
			case when rtrim(p.mobile) = '' then null else p.mobile end, 
			case when rtrim(p.phone) = '' then null else p.phone end) -- , as ComputedEmail,
			-- e.email, e.email2, e2e.Email, p.email, p.email2
		from 
			Entity e
			inner join Entity2Entity e2e on e.organizationid = e2e.IDRecEntity
			inner join entity p on p.organizationid = e2e.IDRecEntityChild
			inner join SysDB db on p.organizationid = db.idcompany and db.dbmask = @dbmask
		where
			e.organizationid = @IdContact
	end


	if @r is null or @r = '' 
	begin
		select @r = coalesce(
			case when rtrim(e.mobile) = '' then null else e.mobile end, 
			case when rtrim(e.phone) = '' then null else e.phone end
		)
		from 
		Entity e
		where
		e.organizationid = @IdContact

	end
			
	return @r

END
GO


