-- ----------------------------
-- function structure for ReadPocValuesTF_Stock
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ReadPocValuesTF_Stock]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ReadPocValuesTF_Stock]
GO

CREATE FUNCTION [dbo].[ReadPocValuesTF_Stock]
(	
	@IDModule uniqueidentifier,
	@IDRecord int
)
RETURNS TABLE 
AS
RETURN 
(
	select *, TotalAvailableStock + TotalQtyOrderedToSupplier + TotalQtyInProduction as TotalPredictedStock
	from(
		select poc.*, dl.ID, dl.LineLink, dl.LineLinkModule ,dl.IDParent as IDParentLine,
		CASE 
			WHEN poc.IDParent IS NULL THEN (select top 1 account_no from Account where IDAccount = poc.IDRecord and IDModule = poc.IDRecordModule) 
			ELSE (select top 1 doc_ref from document where IDDocument = poc.IDSrc and IDModule = poc.IDSrcModule) 
		END as IDDocSrc, 
		poc.TotalQtyActualStock - poc.TotalReservedStock - poc.TotalQtyInConsumption as TotalAvailableStock, 
		case when MovementMode = 3 then IDRecord else IDSrc end IDLink,
		case when MovementMode = 3 then IDRecordModule else IDSrcModule end IDLinkModule,
		case when MovementMode = 3 then accStk.StockStatus else null end StockStatus,
		case when MovementMode = 3 then acc.LinkedEntity3rdParty else null end LinkedEntity3rdParty,
		case when MovementMode = 3 then acc.LinkedEntity3rdPartyModule else null end LinkedEntity3rdPartyModule,
		case when MovementMode = 3 then accStk.IDDocumentSrc else null end IDDocumentSrc,
		case when MovementMode = 3 then accStk.IDDocumentSrcModule else null end IDDocumentSrcModule,
		case when MovementMode = 3 then accStk.IDFollowUpItemRelated else null end IDFollowUpItemRelated,
		case when MovementMode = 3 then accStk.IDFollowUpItemRelatedModule else null end IDFollowUpItemRelatedModule,
		case when MovementMode = 3 then accStk.IsAccVirtualFinalized else null end IsAccVirtualFinalized
		from ReadPocValuesTF(@IDModule, @IDRecord) poc
		left join DocumentLine dl on dl.ID = poc.IDLine and dl.IDParent is not null and dl.IDLineType = 1 and dl.PartitionColumn = Year(poc.DateSrc)	
		left join Account acc on acc.IDAccount = poc.IDRecord and acc.IDModule = poc.IDRecordModule
		left join AccountStock accStk on accStk.IDAccount = acc.IDAccount and accStk.IDModule = acc.IDModule
		where (TypeOfValue = 1 or poc.MovementMode = 3)
	) t
);
GO


-- ----------------------------
-- procedure structure for SS_AddEletrodeToPart
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_AddEletrodeToPart]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_AddEletrodeToPart]
GO

CREATE PROCEDURE [dbo].[SS_AddEletrodeToPart]
	-- Add the parameters for the stored procedure here
	@PartID uniqueidentifier,
	@EletrodeID uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @ProgID uniqueidentifier;
	declare @NewProgID uniqueidentifier;
    -- Procurar os pontos de erosão do elétrodo que estão associados na peça pai (isto pode ser errado)
	declare @Progs  table (
		ProgID uniqueidentifier
	)
	insert into @progs select p.id
						from ss_program p 
						inner join SS_EDMPoint e on p.id=e.id 
						where p.ToolID=@EletrodeID and idobject is null and e.IsTemplatePoint=1 and (idjob is null)
	--Inserir novos programas de erosão na peça seleccionada
	--declare @IDWorkflowItem int
	--set @IDWorkflowItem= (Select IDWorkflowItem from sysworkflowitem where idKind=dbo.EDMKind() 
	--	and idregisto=@PartID);
	--if @IDWorkflowItem is not null
	--begin
		--Apagar programas ja existentes com este eletrodo
		delete from SS_EDMPoint where id in (Select id from SS_Program where idobject=@PartID and ToolID=@EletrodeID  and (idjob is null)) and IsTemplatePoint=0
		delete from SS_Program  where idobject=@PartID and ToolID=@EletrodeID  and (idjob is null) and id in 
			(Select id from SS_EDMPoint where IsTemplatePoint=0 )


		DECLARE ep CURSOR LOCAL
		FOR select ProgID from @progs
		OPEN ep;
		FETCH NEXT FROM ep
			INTO  @ProgID;

		WHILE @@FETCH_STATUS = 0
		BEGIN
			--Inserir m novo programa para associar à task
			declare @programid uniqueidentifier
			set @programid= newid();

			Insert into SS_Program(id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,toolid,
					EstimatedTime,ParentID,HasChilds) 
			select @programid,Code,Kind,Ordem,@PartID,FilePath,Position,ProgramType,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,toolid,
					EstimatedTime,ParentID,HasChilds
			from sS_program where id=@ProgID


			insert into dbo.SS_EDMPoint(id, 	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint)
			select  @programid,  	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint from ss_edmpoint where id=@ProgID

			FETCH NEXT FROM ep
			INTO @ProgID;
		END;
		
		CLOSE ep;
		DEALLOCATE ep;
		
	--end;
END


SET ANSI_NULLS ON
GO


-- ----------------------------
-- function structure for ReadPocValuesTF_Acc
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ReadPocValuesTF_Acc]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ReadPocValuesTF_Acc]
GO

CREATE FUNCTION [dbo].[ReadPocValuesTF_Acc]
(	
	@IDModule uniqueidentifier,
	@IDRecord int
)
RETURNS TABLE 
AS
RETURN 
(
with lines as(
select 
poc.[Compensation],poc.[CreatedOn],poc.[DateRecord],poc.[DateSrc],poc.[Description],poc.[IDLine],poc.[IDParent],poc.[IDPocValue],poc.[IDRecord],
poc.[IDRecordModule],poc.[IDResourceCreation],poc.[IDSrc],poc.[IDSrcModule],poc.[IDSysAccountMovementType],poc.[IDSysActivityType],poc.[IDUserCreation],
poc.[MovementMode],poc.[MovementRootType],poc.[QtyDocAct],poc.[QtyDocActBalance],poc.[QtyDocPlan],poc.[QtyDocPlanBalance],poc.[QtyFinAct],poc.[QtyFinActBalance],
poc.[QtyFinPlan],poc.[QtyFinPlanBalance],poc.[QtyTransAct],poc.[QtyTransActBalance],poc.[QtyTransPlan],poc.[QtyTransPlanBalance], 
poc.[TotalCredit],poc.[TotalDebit],poc.[TotalQtyDocAct],poc.[TotalQtyDocPlan],poc.[TotalQtyFinAct],poc.[TotalQtyFinPlan],poc.[TotalQtyTransAct],
poc.[TotalQtyTransPlan],poc.[TotalValueDebt],poc.[TotalValueDocAct],poc.[TotalValueDocPlan],poc.[TotalValueFinAct],poc.[TotalValueFinPlan],poc.[TotalValueTransAct],
poc.[TotalValueTransPlan],poc.[TypeOfValue],poc.[ValueDebt], poc.[Depth] , poc.[IDSrcCode] , poc.[HasChildren] , poc.[ParentMovementMode], poc.[hierarchy],
case when @IDModule in(select idmodule from GetModulesRec('e93a6d50-31ba-4c2d-829a-35f63f505fd9')) then poc.[ValueDocAct] * -1 else poc.[ValueDocAct] end as [ValueDocAct],
poc.[ValueDocActBalance],
poc.[ValueDocPlan],
poc.[ValueDocPlanBalance],
case when @IDModule not in(select idmodule from GetModulesRec('e93a6d50-31ba-4c2d-829a-35f63f505fd9')) then poc.[ValueFinAct] * -1 else poc.[ValueFinAct] end as [ValueFinAct],
poc.[ValueFinActBalance],
poc.[ValueFinPlan],
poc.[ValueFinPlanBalance],
case when @IDModule in(select idmodule from GetModulesRec('e93a6d50-31ba-4c2d-829a-35f63f505fd9')) then poc.[ValueTransAct] * -1 else poc.[ValueTransAct] end as [ValueTransAct],
poc.[ValueTransActBalance],
poc.[ValueTransPlan],
poc.[ValueTransPlanBalance],
pl.ID, pl.PaymentValue, pl.PaymentFullfil, pl.Closed, pl.LineLink, pl.IDParent as IDParentLine,DATEDIFF(day, poc.DateRecord, getdate()) daysDiff, pl.LineDocSrc, isnull(pl.LineDocSrcModule, poc.IDSrcModule) LineDocSrcModule,
CASE 
	WHEN poc.IDParent IS NULL THEN (select top 1 account_no from Account where IDAccount = poc.IDRecord and IDModule = poc.IDRecordModule) 
	ELSE (select top 1 doc_ref from document where IDDocument = poc.IDSrc and IDModule = poc.IDSrcModule) 
END as IDDocSrc, 
fupDep.IDFollowUpItem as FollowUpItemRelated, fupDep.IDModule as FollowUpItemRelatedModule, fupDep.Status as FollowUpItemRelatedStatus,
pl.productid, pl.productidModule, poc.TimeType, poc.StartTime, poc.EndTime, poc.[IDAccount], poc.[IDAccountModule], 
poc.Code, poc.Code_counter, poc.Code_counterPlanned,
case when MovementMode = 3 then IDRecord else IDSrc end IDLink,
case when MovementMode = 3 then IDRecordModule else IDSrcModule end IDLinkModule
from ReadPocValuesTF(@IDModule, @IDRecord) poc
left join DocumentLine pl on pl.ID = poc.IDLine and pl.IDParent is not null and pl.IDLineType in(1,2,3)	
left join Account accFUP on accFUP.IDAccount = poc.IDRecord
left join FollowUpItem fupDep on fupDep.IDFollowUpItem = accFUP.IDContact and fupDep.IDModule = accFUP.IDContactModule

), linesInDebt as(
	select  IDPocValue
	from lines
	where (IDParentLine is not null and (PaymentFullfil <> PaymentValue or PaymentFullfil is null) and MovementMode in(1,4)) 
)
select *, 
	case 
	when inDebt = 0 then -1
	else behind
	end colorCC
from (
	select  *,		
	case 
	when FollowUpItemRelated IS Not NULL and FollowUpItemRelatedStatus not in(2421, 2604, 2577,2578) then 3
	else (select top 1 CodeInt from SysPaymentStatus where daysDiff between DaysIntervalStart and DaysIntervalEnd order by codeint desc)
	end behind,
			case 
				when idpocvalue in (
					select * from linesInDebt
				) then 1 					
				else 0
			end inDebt
	from lines
) tt
where ((IDSysAccountMovementType in(1,2,3,4,5)) or MovementMode = 3)
);
GO


-- ----------------------------
-- procedure structure for UpdateStockStatusAccount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateStockStatusAccount]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateStockStatusAccount]
GO

CREATE PROCEDURE [dbo].[UpdateStockStatusAccount] 
	@IDRecord int,
	@IDModule uniqueidentifier
AS
BEGIN
	SET NOCOUNT ON;
	declare @TotalAvailableStock decimal(16,8),
			@TotalPredictedStock decimal(16,8);

	set @TotalAvailableStock =
	(
		select top 1 TotalQtyActualStock - TotalQtyOrderedByCustomer - TotalQtyInConsumption from AccountStock where IDAccount = @IDRecord and IDModule = @IDModule
	);
		
	set @TotalPredictedStock =
	(
		select top 1 @TotalAvailableStock + TotalQtyInProduction + TotalQtyOrderedToSupplier from AccountStock where IDAccount = @IDRecord and IDModule = @IDModule
	);

	update AccountStock
	set	
	StockStatus = CASE WHEN ISNULL(StockManagement,0) = 0 THEN 0 ELSE
		CASE 
		WHEN TotalQtyActualStock < 0 THEN 9
		WHEN @TotalPredictedStock < 0 THEN 8
		WHEN @TotalAvailableStock < 0 THEN 7
		WHEN TotalQtyActualStock = 0 OR TotalQtyActualStock IS NULL THEN 6
		WHEN @TotalPredictedStock = 0 OR @TotalPredictedStock IS NULL THEN 5
		WHEN @TotalAvailableStock <= 0 OR @TotalAvailableStock <= 0 THEN 4
		WHEN TotalQtyActualStock < MinQty THEN 3
		WHEN @TotalPredictedStock < MinQty THEN 2
		WHEN @TotalAvailableStock < MinQty THEN 1
		ELSE 0
		END
	END
	where IDAccount = @IDRecord;
END
GO


