	DROP PROCEDURE [dbo].[clearSignatureInReopen]
GO

CREATE PROCEDURE [dbo].[clearSignatureInReopen]
	@IDRecord int,	
	@IDModule uniqueidentifier
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE @imageGuid  uniqueidentifier;

	SET @imageGuid = (select SignatureImage from document where IDDocument=@IDRecord);

	UPDATE document SET  SignatureImage= null WHERE IDDocument=@IDRecord;
	DELETE FROM SysFilesSystem WHERE Guid = @imageGuid;
END
GO


