-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_AddObjectNote]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_AddObjectNote]
GO

CREATE PROCEDURE [dbo].[SS_AddObjectNote]
	@IDObject uniqueidentifier,
	@IDOperation int,
	@Readonly bit, --Legacy, nao eh usado
	@IDLogin	uniqueidentifier,
	@Note nvarchar(100),
	@Kind integer=0
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	
	declare @IDOperationType as uniqueidentifier
	declare @importance int=null

	Select @IDOperationType=op.idoperationtype
	from  SysOperationType op 
	where op.SystemBehaviour=@IDOperation

	if @Kind=3
		set @importance=1;	

	insert into [dbo].[SS_ObjectNotes] ( IDObject, IDLogin, IDOperation,note,  ReadOnly,data,NoteKind,Importance)
		values ( @IDObject, @IDLogin, @IDOperationType, @note, @Readonly,getdate(),@Kind,@importance);

	if @Kind=3
		UPDATE SS_Object SET HasUserMessages=@importance WHERE ((HasUserMessages is null) or (HasUserMessages<@importance)) AND ID=@IDObject;

END
GO


-- ----------------------------
-- function structure for GetDaysDiffPayment
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetDaysDiffPayment]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetDaysDiffPayment]
GO

CREATE FUNCTION [dbo].[GetDaysDiffPayment]
(	
	@IDRecord int
)
RETURNS nvarchar(100) 
AS

BEGIN
return(
	select CASE 
		WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) > 0 THEN CONVERT(nvarchar, DATEDIFF(day, pl.PaymentPrevDate, getdate()))
		WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 1 THEN 'Em dia'
		WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 2 THEN 'No Vencido'
		WHEN DATEDIFF(day, pl.PaymentPrevDate, getdate()) <= 0 and d.IDLanguage = 3 THEN 'Not Expired'
	END DaysDue
	FROM DocumentLine pl
	inner join document d on d.iddocument = pl.IDRegister
	where pl.ID = @IDRecord AND pl.IDLineType in(2,3))
END
GO


-- ----------------------------
-- procedure structure for GetAllDocumentLinesChildrenAndParents
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetAllDocumentLinesChildrenAndParents]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetAllDocumentLinesChildrenAndParents]
GO

CREATE PROCEDURE [dbo].[GetAllDocumentLinesChildrenAndParents]
	-- Add the parameters for the stored procedure here
	@id int = 0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	with childcte as (
	  select id, TrackingLineLink, IDRegister, IDModule, ProductCode, ProductName, isnull(QtyTracking,Qty) Qty , isnull(ValueTracking, ValueWithVat) ValueWithVat
	  from documentline
	  where id = @id and IDLineType = 1
	  union all
	  select d.id, d.TrackingLineLink, d.IDRegister, d.IDModule,d.ProductCode, d.ProductName, isnull(d.QtyTracking,d.Qty) Qty, isnull(d.ValueTracking, d.ValueWithVat)ValueWithVat
	  from documentline d
		join childcte on d.TrackingLineLink = childcte.id 
		where IDLineType = 1
	), parentcte as (
	  select id, TrackingLineLink, IDRegister, IDModule, ProductCode, ProductName, isnull(QtyTracking,Qty) Qty, isnull(ValueTracking, ValueWithVat) ValueWithVat
	  from documentline
	  where id = @id and IDLineType = 1
	  union all
	  select d.id, d.TrackingLineLink, d.IDRegister, d.IDModule, d.ProductCode, d.ProductName, isnull(d.QtyTracking,d.Qty) Qty, isnull(d.ValueTracking, d.ValueWithVat) ValueWithVat
	  from documentline d
		join parentcte on d.id  = parentcte.TrackingLineLink 
		where IDLineType = 1
	  )
	SELECT t.id, t.TrackingLineLink, t.IDRegister, t.IDModule, t.ProductCode, t.ProductName, t.Qty, t.ValueWithVat, d.doc_ref, d.doc_date, d.doc_3rd_account, e.Name as [thirdAccount], null as hasChildren, CASE WHEN t.id <> @id THEN 0 ELSE 1 END  as originalID FROM (
	select *
	from childcte
	union 
	select *
	from parentcte) t
	LEFT JOIN document d ON d.IDDocument = t.IDRegister
	LEFT JOIN Account e ON d.doc_3rd_account = e.IDAccount;

END
GO


