CREATE FUNCTION [dbo].[aux_MRRP_f_a9b904beecf64dbdad1620887438b755]
(
@id int
)
RETURNS nvarchar(max)
AS
BEGIN
declare @r nvarchar(max)
SELECT @r = STRING_AGG(t_MRRP3.Industries ,'; ')
 FROM (  SELECT E2R.IDRecEntity, E2R.IDRecIndustry,i.Name AS Industries
 FROM  Entity2Industry E2R
 LEFT JOIN Industry i ON i.IDIndustry=E2R.IDRecIndustry) as t_MRRP3 
 WHERE @id=t_MRRP3.IDRecEntity
return @r
END
