-- ----------------------------
-- function structure for GetStockStatus
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetStockStatus]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetStockStatus]
GO

CREATE FUNCTION [dbo].[GetStockStatus]
(
	@IDRecord as int 
)
RETURNS INT
AS
BEGIN 

	DECLARE @auxTable TABLE(
		RegisterStatus int,
		IDAccountStock int,
		IDAccountStockModule uniqueidentifier,
		StockManagement int,
		LimitToExistingStock int,
		DocModule uniqueidentifier,
		DocParentModule uniqueidentifier,
		ProductQty decimal(18,6),
		MinStock decimal(18,6),
		TotalAvailableStock decimal(18,6),
		TotalPredictedStock decimal(18,6),
		TotalQtyActualStock decimal(18,6),
		TotalQtyOrderedByCustomer decimal(18,6),
		TotalQtyOrderedToSupplier decimal(18,6),
		TotalQtyInProduction decimal(18,6),
		TotalQtyInConsumption decimal(18,6)
	)
	DECLARE @RegisterStatus int;
	DECLARE @IDAccountStock int;
	DECLARE @IDAccountStockModule uniqueidentifier;
	DECLARE @StockManagement int;
	DECLARE @LimitToExistingStock int;
	DECLARE @DocModule uniqueidentifier;
	DECLARE @DocParentModule uniqueidentifier;
	DECLARE @ProductQty decimal(18,6);
	DECLARE @MinStock decimal(18,6);
	DECLARE @TotalAvailableStock decimal(18,6);
	DECLARE @TotalPredictedStock decimal(18,6);
	DECLARE @TotalQtyActualStock decimal(18,6);
	DECLARE @TotalQtyOrderedByCustomer decimal(18,6);
	DECLARE @TotalQtyOrderedToSupplier decimal(18,6);
	DECLARE @TotalQtyInProduction decimal(18,6);
	DECLARE @TotalQtyInConsumption decimal(18,6);

	insert into @auxTable
	select top 1 d.RegisterStatus, acc.IDAccount, acc.IDModule, acc.StockManagement, 
	acc.StockLimitType, d.IDModule, m.IDParent as parentModule,
	dl.Qty,
	acc.MinQty,
	isnull(acc.TotalQtyActualStock,0) - isnull(acc.TotalQtyInConsumption,0) - isnull(acc.TotalQtyOrderedByCustomer,0),
	isnull(acc.TotalQtyActualStock,0) - isnull(acc.TotalQtyInConsumption,0) - isnull(acc.TotalQtyOrderedByCustomer,0) + isnull(acc.TotalQtyInProduction,0) + isnull(acc.TotalQtyOrderedToSupplier,0),
	isnull(acc.TotalQtyActualStock,0),
	acc.TotalQtyOrderedByCustomer,
	acc.TotalQtyOrderedToSupplier,
	acc.TotalQtyInProduction,
	acc.TotalQtyInConsumption
	from DocumentLine dl 
	inner join document d on dl.IDRegister = d.IDDocument and dl.PartitionColumn = d.PartitionColumn and dl.IDModule = d.IDModule
	left join AccountStock acc on dl.dim14 = acc.IDAccount and dl.dim14Module = acc.IDModule	
	left join SysModule m on m.IDModule = d.IDModule	
	where dl.IDLineType = 1 and dl.ID = @IDRecord
		
	declare auxCursor cursor for 
	select * from @auxTable

	open auxCursor
		fetch next from auxCursor into @RegisterStatus, @IDAccountStock,@IDAccountStockModule,@StockManagement,@LimitToExistingStock,@DocModule, @DocParentModule,
		@ProductQty,@MinStock,@TotalAvailableStock,@TotalPredictedStock,@TotalQtyActualStock,@TotalQtyOrderedByCustomer,@TotalQtyOrderedToSupplier,@TotalQtyInProduction,@TotalQtyInConsumption
	close auxCursor
	deallocate auxCursor

	IF @RegisterStatus not in(0,3) OR @IDAccountStock IS NULL 
	begin
		return null
	end 
	
	IF @StockManagement IS NULL or @StockManagement = 0
	begin
		return 0
	end	


	DECLARE @auxMovementTable TABLE(
		IsActualStock int,
		IsInConsumption int,
		IsOrderedByCustomer int,
		IsInProduction int,
		IsOrderedToSupplier int
	);

	declare @IsActualStock int;
	declare @IsInConsumption int;
	declare @IsOrderedByCustomer int;
	declare @IsInProduction int;
	declare @IsOrderedToSupplier int;
	declare @ActualQty int;
	declare @AvailableQty int;
	declare @PredictedQty int;


	insert into @auxMovementTable
	select top 1 * from(
		select top 1 IsActualStock, IsInConsumption,IsOrderedByCustomer, IsInProduction, IsOrderedToSupplier
		from SysModule m
		left join SysModulePendingTypesDimension pm on pm.IDModule = m.IDModule and pm.IDDimension = 14 
		where m.IDModule = @DocModule and pm.IsMainDimRelation = 1
		union all
		select top 1 IsActualStock, IsInConsumption,IsOrderedByCustomer, IsInProduction, IsOrderedToSupplier
		from SysModule m
		left join SysModulePendingTypesDimension pm on pm.IDModule = m.IDModule and pm.IDDimension = 14 
		where m.IDModule = @DocParentModule and pm.IsMainDimRelation = 1
	) t
	

	declare auxMovementCursor cursor for 
	select top 1 * from @auxMovementTable

	open auxMovementCursor
		fetch next from auxMovementCursor into @IsActualStock, @IsInconsumption,@IsOrderedByCustomer, @IsInProduction, @IsOrderedToSupplier
	
	close auxMovementCursor
	deallocate auxMovementCursor
		
	set @ActualQty = isnull(@IsActualStock,0);
	set @PredictedQty = isnull(@IsInProduction + @IsOrderedToSupplier,0);
	set @AvailableQty = (isnull(@IsInConsumption + @IsOrderedByCustomer,0) * -1);


	if  (select count(*) from @auxMovementTable) > 0
	begin
		
		return CASE 
		WHEN (@TotalQtyActualStock - @ProductQty) < 0 THEN 9
		WHEN (@TotalPredictedStock - @ProductQty) < 0 THEN 8
		WHEN (@TotalAvailableStock - @ProductQty) < 0 THEN 7
		WHEN (@TotalQtyActualStock - @ProductQty) = 0 THEN 6
		WHEN (@TotalPredictedStock - @ProductQty) = 0 THEN 5
		WHEN (@TotalAvailableStock - @ProductQty) = 0 THEN 4
		WHEN (@TotalQtyActualStock - @ProductQty) < @MinStock THEN 3
		WHEN (@TotalPredictedStock - @ProductQty) < @MinStock THEN 2
		WHEN (@TotalAvailableStock - @ProductQty) < @MinStock THEN 1
		ELSE 0
		END;
	end	

	return 0	
END
GO


-- ----------------------------
-- procedure structure for UpdateOpportunityFollowUpAccountName
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateOpportunityFollowUpAccountName]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateOpportunityFollowUpAccountName]
GO

CREATE PROCEDURE [dbo].[UpdateOpportunityFollowUpAccountName]
	@IDRecord int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Update FollowUpItem Account Name
	Update Account SET Name = CONCAT(fl.Name,'_',fl.Code)
	FROM (
		SELECT TOP 1 FollowUpItem.IDRecordAccount,FollowUpItem.Name,FollowUpItem.Code 
		FROM FollowUpItem 
		WHERE FollowUpItem.IDFollowUpItem= @IDRecord
	) fl
	WHERE IDAccount=fl.IDRecordAccount
END
GO


