-- procedure structure for GetAllParts
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetAllParts]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetAllParts]
GO

CREATE PROCEDURE [dbo].[GetAllParts] 
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	CREATE TABLE #PartsInCell
	(
	   ID uniqueidentifier,
	   Name nvarchar(250) collate Latin1_General_CI_AS
	)
	INSERT INTO #PartsInCell(ID, Name)
    -- Insert statements for procedure here
	SELECT * FROM (
		SELECT o.ID, ISNULL(CONCAT(dbo.SS_GetClientName(o.ID) + '_',COALESCE(RTRIM(LTRIM(FullName)),RTRIM(LTRIM(ShortName)))),'' ) as FullName 
		FROM SS_Object o 
		WHERE o.Visibility = 0 AND o.TypeID IN (1,2) 
	) t ORDER By t.FullName
	
	INSERT INTO #PartsInCell(ID, Name)
	SELECT ID, LTRIM(RTRIM(Code)) AS Code FROM SM_NodePart WHERE ID  IN (
	SELECT ID FROM SysFixture WHERE ID NOT IN (
	SELECT IDHolder FROM SS_Object WHERE IDHolder IS NOT NULL 
	)
	) AND IDNodePosic = '00000000-0000-0000-0000-000000000000'

	SELECT * FROM #PartsInCell ORDER BY Name

	DROP TABLE #PartsInCell

END
GO


-- ----------------------------
-- function structure for GetIsTaskProduction
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetIsTaskProduction]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetIsTaskProduction]
GO

CREATE FUNCTION [dbo].[GetIsTaskProduction]
(
	@IDTask uniqueidentifier
)
RETURNS int
AS
BEGIN

	declare @count int = 0;
	 
	select @count = count(*)  
	from SysTaskProductionValues 
	where IDTask = @IDTask 
	and IDSysRoutine is not null and IDSysRoutineItem is not null and IDSysPRRoutineRequest is not null

	set @count = @count + (select count(*) from SysDocOprRoutineItem where IDSysTask = @IDTask);
	set @count = @count + (select count(*) from SysOprRoutineItem where IDSysTask = @IDTask);
	set @count = @count + (select count(*) from SysOprRoutineItem where IDERPTask = @IDTask);

	return (case when @count = 0 then 0 else 1 end);
END
GO


-- ----------------------------
-- function structure for GetMaxEvaluation
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetMaxEvaluation]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetMaxEvaluation]
GO

CREATE FUNCTION [dbo].[GetMaxEvaluation]
(
	@IDPart uniqueidentifier,
	@IDOpType uniqueidentifier
)
RETURNS decimal
AS
BEGIN
	DECLARE @Result decimal
	-- Add the T-SQL statements to compute the return value here
	SET @Result = COALESCE(
		(SELECT MAX(Evaluation) 
			FROM SysPrRoutineRequest 
			WHERE 
			IDPart = @IDPart 
			AND IDOperationType = @IDOpType
			AND (IDJob IS NOT NULL AND IDJob > 0)
			AND IDTask IS NULL 
			AND IDRequestToResolve IS NULL 
			AND 
			( 
				WorkingStatus IN
				( 
					'483D173F-7287-4751-A9D1-741DAAAB41E0' , 
					'C6812E70-56CB-4394-84A5-4C3DE719B44E',
					'3A223268-BC2E-408E-AD63-55163DFF0950',
					'CA5EAAF2-3E1B-43E5-9722-998B93E98821'
				)
			)
		)
		,0)
	RETURN @Result
END
GO


