-- ----------------------------
-- procedure structure for ChatMarkAsRead
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChatMarkAsRead]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChatMarkAsRead]
GO

CREATE PROCEDURE [dbo].[ChatMarkAsRead]
	@IDChat int,
	@IDResource uniqueidentifier,
	@IDLogin uniqueidentifier,
	@IDChannel uniqueidentifier out
AS
BEGIN
	SET NOCOUNT ON;

	declare @dt datetime
	set @dt = GETUTCDATE()

	IF EXISTS(SELECT ID FROM SysChatUserInteraction WHERE IDUser = @IDLogin AND IDResource = @IDResource AND  IDChannel = @IDChannel) 
	BEGIN
		update SysChatUserInteraction
		set IDChat = @IDChat, DateState = @dt
		where IDUser = @IDLogin AND IDResource = @IDResource AND  IDChannel = @IDChannel and idchat < @IDChat
		
	END
	ELSE
	BEGIN
		
		INSERT INTO SysChatUserInteraction(IDChat, IDUser, IDResource, DateState, IDChannel)
			VALUES(@IDChat, @IDLogin, @IDResource, @dt, @IDChannel);

		RETURN 0
	END

		
    IF NOT EXISTS(SELECT IDChatRead FROM SysChatRead WHERE IDChat = @IDChat AND IDLoginRead = @IDLogin) 
	BEGIN
		
		INSERT INTO SysChatRead(IDChat, IDLoginRead, IDResourceRead, DateRead)
			VALUES(@IDChat, @IDLogin, @IDResource, @dt);

		RETURN 0
	END

END
GO


