-- ----------------------------
-- function structure for GetTimeFromSeconds
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTimeFromSeconds]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTimeFromSeconds]
GO

CREATE FUNCTION [dbo].[GetTimeFromSeconds] 
(
	-- Add the parameters for the function here
	@sec BIGINT
)
RETURNS nvarchar(16)
AS
BEGIN

DECLARE @Result nvarchar(16)
DECLARE @I BIGINT
SET @I = @sec * 1000

DECLARE @I1 BIGINT
DECLARE @I2 BIGINT
DECLARE @I3 BIGINT
DECLARE @I4 BIGINT
DECLARE @I5 BIGINT

SET @I1 = (@I/86400000)
SET @I2 = (@I%86400000)/3600000
SET @I3 = (((@I%86400000)%3600000)/60000)
SET @I4 = ((((@I%86400000)%3600000)%60000)/1000)
SET @I5 = (((@I%86400000)%3600000)%1000)

IF @I1 > 0 
	BEGIN
		SELECT @Result = 
		RIGHT ('' + convert(varchar(10), @I1),2) + 'd ' + 
		RIGHT ('0' + convert(varchar(10), @I2),2) + ':' +
		RIGHT ('0' + convert(varchar(10), @I3),2) + ':' +
		RIGHT ('0' + convert(varchar(10), @I4),2) 
	END
ELSE 
	BEGIN
		SELECT @Result = 
		RIGHT ('0' + convert(varchar(10), @I2),2) + ':' +
		RIGHT ('0' + convert(varchar(10), @I3),2) + ':' +
		RIGHT ('0' + convert(varchar(10), @I4),2)
	END
	-- Return the result of the function
	RETURN @Result
END
GO


-- ----------------------------
-- procedure structure for GetPartsList
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPartsList]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetPartsList]
GO

CREATE PROCEDURE [dbo].[GetPartsList]
	-- Add the parameters for the stored procedure here
	@IDParent uniqueidentifier 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT 

ISNULL(RTRIM(LTRIM(ShortName)), ISNULL(RTRIM(LTRIM(f.Code)),'')) AS ShortName, 
ISNULL(RTRIM(LTRIM(f.Code)), ISNULL(	CONCAT( dbo.SS_GetClientName(o.ID) + '_', COALESCE( RTRIM( LTRIM(FullName)), RTRIM( LTRIM(ShortName)))), '' )) as FullName, 
 ISNULL(o.ID, f.ID) AS [ID], 
 CASE o.CleanState   
     WHEN 1 THEN ''  
     WHEN 2 THEN 'Powder'  
	 WHEN 3 THEN 'Dielectric'  
	 WHEN 4 THEN 'Dirty Scobs'  
	 ELSE ''   
END As CleanState ,
CASE o.Priority   
     WHEN 1 THEN 'Very Low'  
     WHEN 2 THEN 'Low'  
	 WHEN 3 THEN 'Normal'  
	 WHEN 4 THEN 'High'  
	 WHEN 5 THEN 'Urgent'  
	 ELSE ''   
END As Priority ,
ISNULL(o.Priority,1) As IDPriority ,
ISNULL(o.PriorityManagement,0) As PriorityManagement,
 LTRIM(RTRIM(p.Code)) [Position], 
 LTRIM(RTRIM(ISNULL(p.MachineCode,''))), 
 p.IDNodePosicParent,  
 COALESCE(ps.Code, 'RAW') as OpState,
 (SELECT Count(*) FROM SysPrRoutineRequest WHERE  (IDPart = o.ID OR IDTool = o.ID) AND IDOperationType IN (SELECT IDOperationType FROM SysOperationType WHERE PhisicalObjectRequired = 1) AND IDRequestToResolve IS NULL  AND IDTask IS NULL  AND ( WorkingStatus = '3a223268-bc2e-408e-ad63-55163dff0950' OR WorkingStatus = 'ca5eaaf2-3e1b-43e5-9722-998b93e98821' OR WorkingStatus = '483d173f-7287-4751-a9d1-741daaab41e0')    ) as [IN], 

 COALESCE( (SELECT STUFF(( SELECT Distinct ', ' + r.Code FROM SysOprRoutineItem rq  LEFT JOIN SysOperationType r ON rq.IDOperationType = r.IDOperationType  WHERE ( (rq.IDPart = o.ID) AND rq.VirtualNode <> 1 AND rq.IDOperationType IS NOT NULL  AND rq.WorkingStatus <> '2f2593ec-d358-493e-b02c-3db5a912c399' AND rq.WorkingStatus <> '88b381d9-d1db-4c80-8e78-3076b1e196f2' AND rq.WorkingStatus <> 'a52e3bcc-9bdd-4f8f-99d7-b5d5c69eab70')  ORDER BY ', ' + r.Code FOR XML PATH(''), TYPE).value('.[1]', 'nvarchar(max)'), 1, 2, '')),'') as [Processes] ,
 COALESCE((SELECT STUFF((SELECT Distinct '; [''' + r.Color + ''', ''' + r.Code + ''']' FROM SysOprRoutineItem rq  LEFT JOIN SysOperationType r ON rq.IDOperationType = r.IDOperationType   WHERE  (rq.IDPart = o.ID) AND rq.VirtualNode <> 1 AND rq.IDOperationType IS NOT NULL AND (rq.WorkingStatus IN ('c6812e70-56cb-4394-84a5-4c3de719b44e','2c16a9ff-bb7d-416a-ac93-145377304bb5')) ORDER BY '; [''' + r.Color + ''', ''' + r.Code + ''']' FOR XML PATH(''), TYPE).value('.[1]', 'nvarchar(max)'), 1, 2, '')),'') as [ReadyProcesses] ,  
   COALESCE(  (SELECT STUFF((SELECT Distinct ', ' + CONCAT(r.Code, CONCAT(':', LTRIM(RTRIM(m.Code)))) 
   FROM 
   ( SELECT IDPart, IDResourcePosition, IDPrRoutine FROM SysPrRoutineRequest rq WHERE rq.IDPart = o.ID AND rq.IDJOb > 0  AND  rq.IDTask IS NULL AND (IDOperation IS NOT NULL AND IDOperation <> '00000000-0000-0000-0000-000000000000') AND rq.IDRequestToResolve IS NULL AND rq.IDRequestLink IS NULL AND rq.IDResourcePosition IS NOT NULL AND rq.IDResourcePosition <> '00000000-0000-0000-0000-000000000000'  AND  (rq.WorkingStatus = '88b381d9-d1db-4c80-8e78-3076b1e196f2') GROUP BY IDPart, IDResourcePosition, IDPrRoutine ) rq  
   INNER JOIN SysPrRoutine r ON rq.IDPrRoutine = r.IDRoutine  
   INNER JOIN  SysResources m ON rq.IDResourcePosition = m.ResourceID  
   WHERE rq.IDPart = o.ID
   ORDER BY ', ' + CONCAT(r.Code, CONCAT(':', LTRIM(RTRIM(m.Code)))) FOR XML PATH(''), TYPE).value('.[1]', 'nvarchar(max)'), 1, 2, '')),'') as [Resources] ,  
   LTRIM(RTRIM(ISNULL(ptp.Code,''))) as [PartType] , 
   LTRIM(RTRIM(COALESCE(h.Code, ''))) as [Holder], 
   LTRIM(RTRIM(np.Code)) AS [Localization],  
   ISNULL(LTRIM(RTRIM(np2.Code)),LTRIM(RTRIM(np3.Code))) AS [Reserved]  
   --LTRIM(RTRIM(np3.Code)) AS [Reserved2] ,p.IDNodePartDocked
   FROM  SM_NodePart np1 
   LEFT JOIN SS_Object o ON np1.ID = o.ID  
   LEFT JOIN SysFixture f ON np1.ID = f.ID  
   LEFT JOIN SM_NodePosic p ON np1.IDEntryPosition = p.ID
   LEFT JOIN SysPartType ptp ON o.IDPartType = ptp.ID  
   LEFT JOIN SysFixture h ON o.IDHolder = h.ID  
   LEFT JOIN SM_NodePart np ON p.IDNodePartParent = np.ID   
   LEFT JOIN SM_NodePosic np2 ON np2.IDNodePartReserved = o.ID 
   LEFT JOIN SM_NodePosic np3 ON np3.IDNodePartReserved = p.IDNodePartDocked
   LEFT JOIN SysPartState ps ON o.OperationsStage = ps.ID
   WHERE 
	p.IDNodePosicParent NOT IN ( @IDParent ) 
	--AND 
	--o.IDPartType IS NOT NULL   
	--AND (p.IDNodePartDocked IS NOT NULL OR np2.IDNodePartReserved IS NOT NULL) 
	--AND (np2.ID IS NULL OR p.ID <> np2.ID)
END
GO


-- ----------------------------
-- function structure for aux_MRRP_f_2a8f263608794dc183a5d671d3c149db
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[aux_MRRP_f_2a8f263608794dc183a5d671d3c149db]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[aux_MRRP_f_2a8f263608794dc183a5d671d3c149db]
GO

CREATE FUNCTION [dbo].[aux_MRRP_f_2a8f263608794dc183a5d671d3c149db]
(
@id int
, @Q_IDLanguage int 
)
RETURNS nvarchar(max)
AS
BEGIN
declare @r nvarchar(max)
SELECT @r = STRING_AGG(t_MRRP2.ModuleName ,'; ')
 FROM (Select
 ar.IDActivity,
 fup.IDFollowUpItem,
 CONCAT(ISNULL((CASE 
  WHEN (m.IDTranslationTarget = 1) THEN (t.Acronym) 
  WHEN (m.IDTranslationTarget = 2) THEN (t.ShortName) 
  WHEN (m.IDTranslationTarget = 3) THEN (t.Name) 
  WHEN (m.IDTranslationTarget = 4) THEN (t.Description) END),''), ' [',TRIM(fup.Code),'] | ',fup.Name) as ModuleName
From
 Activity2Record ar
  LEFT JOIN FollowUpItem fup on ar.relatedRecord = fup.IDFollowUpItem and ar.relatedRecordModule = fup.IDModule
  LEFT JOIN SysModule m on fup.IDModule = m.IDModule
  LEFT JOIN SysTranslationValue t on m.IDTranslation = t.IDTranslation and t.IDLanguage = @Q_IDLanguage
Where
 fup.IDModule in (Select IDModule from GetModulesRec('19164347-8e56-4495-8c87-fb21580ae944'))) as t_MRRP2 
 WHERE @id=t_MRRP2.IDActivity
return @r
END
GO


-- ----------------------------
-- procedure structure for SS_CopyConfig
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CopyConfig]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CopyConfig]
GO

CREATE PROCEDURE [dbo].[SS_CopyConfig]
	-- Add the parameters for the stored procedure here
	@ConfigName nvarchar(50),
	@IDCopyConfig int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	insert into SS_importerConfig (name)
	values (@configname);

	declare @Config int;
	set @Config=SCOPE_IDENTITY();

	--Loop pelas
	declare @IDFileSearch int;
	DECLARE ep CURSOR LOCAL
	FOR select id from SS_ImporterSearchFile where ConfigID=@IDCopyConfig
	OPEN ep;
	FETCH NEXT FROM ep
		INTO  @IDFileSearch;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--
		declare @res int;
		EXEC SS_CopyFileSearch @IDFileSearch,@Config,@res output;

		FETCH NEXT FROM ep
		INTO @IDFileSearch;
	END;
		
	CLOSE ep;
	DEALLOCATE ep;


END
GO


-- ----------------------------
-- procedure structure for GetUnUsedRoutineVariables
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetUnUsedRoutineVariables]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetUnUsedRoutineVariables]
GO

CREATE PROCEDURE [dbo].[GetUnUsedRoutineVariables]
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT v.Code as [Variable], r.Code as [Routine], v.IDRoutineVar as [IDVar] FROM SysRoutineVar v
	INNER JOIN SysRoutine r ON r.IDRoutine = v.IDRoutine
	WHERE v.IDRoutineVar NOT IN (
		SELECT IDRoutineVar FROM SysRoutineVar 
		WHERE 
		IDRoutineVar  IN (
			SELECT IDSysRoutineVar FROM SysRoutineVarsRelation
		)
		OR
		IDRoutineVar IN (
			SELECT IDSysRoutineVarDest FROM SysRoutineVarsRelation
		)
	)
ORDER By R.Code, v.Code
END
GO


