CREATE FUNCTION [dbo].[SS_GetDataSheetEstimatedTime]
(
	-- Add the parameters for the function here
	@Kind int,
	@ObjectID uniqueidentifier
)
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @EstimatedTime int;

	set @EstimatedTime= (
		Select sum(EstimatedTime)
		from ss_program
		where idobject=@ObjectID and kind=@kind and active=1 and idjob is null)

	-- Return the result of the function
	RETURN @EstimatedTime

END
