CREATE PROCEDURE [dbo].[UpdateLeadCalculatedFields]
	@IDLead int 
AS
BEGIN
	SET NOCOUNT ON;
	
	update Leads
	set Families = (SELECT STRING_AGG(Family,'; ')
		FROM (SELECT f.Name as Family 
			FROM Lead2Family l2f inner JOIN Family f ON f.IDFamily=l2f.idfamily AND l2f.IDLead = @IDLead )m)
	where IDLead = @IDLead
END
