-- ----------------------------
-- procedure structure for SS_CopyEletrode
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CopyEletrode]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CopyEletrode]
GO

CREATE PROCEDURE [dbo].[SS_CopyEletrode]
	-- Add the parameters for the stored procedure here
	@ObjectID uniqueidentifier,
	@GAP float,
	@EletrodeFamily int,
	@FULL bit,
	@FromCopyPart bit,
	@LoginID uniqueidentifier=null,
	@FixedParentID uniqueidentifier = null,
	@NewName nvarchar(50) = null,
	@MirrX bit,
	@MirrY bit,
	@LinkToOriginal bit,
	@CopyCAM bit,
	@CreatedID uniqueidentifier out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;
	declare @toLink uniqueidentifier;
	declare @ParentId uniqueidentifier;
	declare @MouldID uniqueidentifier;
	--declare @IDTemplateWorkflow int;
	declare @shortname nvarchar(50);
	declare	@saveMirrX bit=0;
	declare @saveMirrY bit=0;

	--Copiar dados de uma peça para um novo registo
	--Tabela de Objectos
	set @toLink=null
	if (@FromCopyPart=1) or (@LinkToOriginal=1)
	begin
		set @tolink=@ObjectID
		set @saveMirrX =@MirrX;
		set @saveMirrY =@MirrY;
	end

	Select @ParentId=parentid,@MouldID=mouldid,@shortname=shortname from ss_object where id=@ObjectID;
		
	Set @shortname=Isnull(@NewName,@shortname);


	if @FixedParentID is not null	
	begin
		set @ParentId=@FixedParentID
		set @MouldID=(Select mouldid from ss_object where id=@FixedParentID);
	end
	declare @ResultID uniqueidentifier

	Exec SS_SystemWFCreateObject @ResultID out
	set @CreatedID=@ResultID

	--Eletrode Information
	UPDATE o1 SET 
		o1.IDMaterial=o2.IDMaterial, 
		o1.copyfromid=@tolink, 
		o1.TypeID=o2.TypeID,
		o1.MouldID=@MouldID,
		o1.ParentID=@ParentId,
		o1.ShortName=@shortname,
		o1.DimCAD_X=o2.DimCAD_X, 
		o1.DimCAD_Y=o2.DimCAD_Y, 
		o1.DimCAD_Z=o2.DimCAD_Z,
		o1.DimReal_X=o2.DimReal_X, 
		o1.DimReal_Y=o2.DimReal_Y, 
		o1.DimReal_Z=o2.DimReal_Z,
		o1.DimBlock_X=o2.DimBlock_X, 
		o1.DimBlock_Y=o2.DimBlock_Y, 
		o1.DimBlock_Z=o2.DimBlock_Z,
		o1.DispBlock_X=o2.DispBlock_X,
		o1.DispBlock_Y=o2.DispBlock_Y, 
		o1.DispBlock_Z=o2.DispBlock_Z,
		o1.MILLRC=o2.MillRC,
		o1.IDPartType=o2.idparttype,
		o1.IDRoutine=o2.idroutine,
		o1.CopyMirrorX=@saveMirrX,
		o1.CopyMirrorY=@saveMirrY,
		o1.DimMestra_XMin=o2.DimMestra_XMin,	
		o1.DimMestra_XMax=o2.DimMestra_XMax	,
		o1.DimMestra_YMin=o2.DimMestra_YMin	,
		o1.DimMestra_YMax=o2.DimMestra_YMax,
		o1.IDCMMBase=o2.IDCMMBase,
		o1.IDEDMBase=o2.IDEDMBase,
		o1.MestraZ=o2.MestraZ,
		o1.STLFileMILL=o2.STLFileMILL,
		o1.STLFileEDM=o2.STLFileEDM,
		o1.STLFileCMM=o2.STLFileCMM,
		o1.imagefile=o2.imagefile,
		o1.IdMILLBase=o2.idMillBase,
		o1.available=o2.available 
	from SS_Object o1
	INNER JOIN SS_Object o2	ON o2.id=@ObjectID
	where o1.id=@CreatedID

	declare @instanceNum int;
	set @instanceNum=1;
	--Gerar num de instancia
	while exists (Select o.id from ss_object o inner join ss_eletrode e on e.id=o.id where parentid=@ParentId and shortname=@shortname and ((@gap is null) or (e.gap=@gap) ) and instancenum=@instancenum) 
		set @instancenum=@instancenum+1;


	--Tabela de info de eletrodo
	insert into SS_Eletrode(id,gap,instancenum,EletrodeFamily,cadbasedimz,ToolDX,ToolDY,ToolDZ,ToolDC,ToolProgDZ )  select @CreatedID,@GAP,@instanceNum,@EletrodeFamily,cadbasedimz,ToolDX,ToolDY,ToolDZ,Tooldc,ToolProgDZ from SS_Eletrode where id=@ObjectID;

	update ss_object set fullname=dbo.SS_GetFullName(@ResultID) where id=@CreatedID 

	Exec SS_DeployOperations @CreatedID

	EXEC SS_AddObjectNote	@CreatedID ,	-1 ,	1 ,	@LoginID	,	'Objecto criado.'
	--Se o original é um eletrodo que vai erodir numa peça então vamos copiar os pontos de erosao
	declare @Code nvarchar(100)
	declare @Kind int
	declare @FilePath nvarchar(500)
	declare @Position int
	declare @ProgramType int
	declare @EstimatedTime int
	declare @HasChilds bit
	declare @ToolID uniqueidentifier

	declare @PX float
	declare @PY float
	declare @PZ float
	declare @PA float
	declare @PB float
	declare @PC float
	declare @PXIni float
	declare @PYIni float
	declare @PZIni float
	declare @PAIni float
	declare @PBIni float
	declare @PCIni float
	declare @VectorI float
	declare @VectorJ float
	declare @VectorK float

	declare @IDTechnology int
	declare @TechnologyText nvarchar(50)
	declare @IDEletrodeType int
	declare @PartID uniqueidentifier

		declare @MultMirrX int;
	declare @MultMirrY int;
	set @MultMirrX=1;
	set @MultMirrY=1;

	if (@MirrX is not null) and (@MirrX=1)
		set @MultMirrX=-1;

	if (@MirrY is not null) and (@MirrY=1)
		set @MultMirrY=-1;	
	
	DECLARE ep CURSOR LOCAL
	FOR select p.Code,p.Kind,p.idObject,p.FilePath,p.Position,p.ProgramType,
					p.PX,	p.PY,p.PZ,p.PA,p.PB,p.PC,p.PXIni,p.PYIni,p.PZIni,p.PAIni,p.PBIni,p.PCIni,p.VectorI,p.VectorJ,p.VectorK,p.toolid,
					p.EstimatedTime,p.ParentID,p.HasChilds,ep.IDTechnology,ep.TechnologyText,ep.IDEletrodeType
		from ss_program p
		inner join SS_EDMPoint ep on ep.ID=p.id
		where p.kind=dbo.EDMKind() and p.toolid=@ObjectID and ep.istemplatepoint=0 and (p.idjob is null)
		order by ordem asc
	OPEN ep;
	FETCH NEXT FROM ep
		INTO  @Code,@Kind,@PartID,@FilePath,@Position,@ProgramType,
					@PX,@PY,@PZ,@PA,@PB,@PC,@PXIni,@PYIni,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI,@VectorJ,@VectorK,@toolid,
					@EstimatedTime,@ParentID,@HasChilds,@IDTechnology,@TechnologyText,@IDEletrodeType;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Ordem Maxima dos pontos de erosa da peça a que o eletrodo corresponde para nao repetir ordens. 
		Declare @MaxOrdemPeca int
		Set @MaxOrdemPeca =0;
		Select @MaxOrdemPeca=max(Ordem) 
			from ss_program p 
			inner join SS_EDMPoint ep on ep.ID=p.id
			where p.kind=dbo.EDMKind() and p.IdObject=@PartID and ep.istemplatepoint=0 and (p.idjob is null)

		set @MaxOrdemPeca=@MaxOrdemPeca+1;
		--Inserir novo programa na peça para erodir tambem o novo eletrodo
		--Se for chamado a partir do copy part nao faz isto para nao linqar na peça original
		declare @NewProgID uniqueidentifier;

		if (@FromCopyPart is null) or (@FromCopyPart=0) 
		begin
			set @NewProgID = newid();
			Insert into SS_Program(id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,toolid,
					EstimatedTime,ParentID,HasChilds) 
			values (@NewProgID,@Code,@Kind,@MaxOrdemPeca,@PartID,@FilePath,@Position,@ProgramType,
					@PX*@MultMirrX,	@PY*@MultMirrY,@PZ,@PA,@PB,@PC,@PXIni*@MultMirrX,@PYIni*@MultMirrY,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI*@MultMirrX,@VectorJ*@MultMirrY,@VectorK,@CreatedID,
					@EstimatedTime,@ParentID,@HasChilds);

			insert into dbo.SS_EDMPoint(id,	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint) values ( 
				@NewProgID,  @IDTechnology, @TechnologyText, @IDEletrodeType,0);
		end
			set @NewProgID = newid();
		--Inserir m novo programa para guardar como template para cópias
			Insert into SS_Program(id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,toolid,
					EstimatedTime,ParentID,HasChilds) 
			values (@NewProgID,@Code,@Kind,@MaxOrdemPeca,null,null,@Position,@ProgramType,
					@PX*@MultMirrX,	@PY*@MultMirrY,@PZ,@PA,@PB,@PC,@PXIni*@MultMirrX,@PYIni*@MultMirrY,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI*@MultMirrX,@VectorJ*@MultMirrY,@VectorK,@CreatedID,
					@EstimatedTime,@ParentID,@HasChilds);
		
			insert into dbo.SS_EDMPoint(id,	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint) values ( 
				@NewProgID,  @IDTechnology, @TechnologyText, @IDEletrodeType,1);

		FETCH NEXT FROM ep
		INTO @Code,@Kind,@PartID,@FilePath,@Position,@ProgramType,
					@PX,@PY,@PZ,@PA,@PB,@PC,@PXIni,@PYIni,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI,@VectorJ,@VectorK,@toolid,
					@EstimatedTime,@ParentID,@HasChilds,@IDTechnology,@TechnologyText,@IDEletrodeType;
	END;
		
	CLOSE ep;
	DEALLOCATE ep;


	--Copiar programas
	Create Table #IDList (
		OldProgramID uniqueidentifier,
		NewProgramID uniqueidentifier
	);
	--Declare @IDWorkflowITem int
	--Declare @WorkflowITemKind int
	--Declare @NewIDWorkflowITem int
	declare @NewProgramID uniqueidentifier;
		DECLARE lc2 CURSOR LOCAL
		FOR select id from ss_program where idobject=@ObjectID and (idjob is null) and ((@FULL=1) or (code not like '%gap%') ) order by parentid;
		OPEN lc2;
		FETCH NEXT FROM lc2
			INTO  @NewProgID;

		WHILE @@FETCH_STATUS = 0
		BEGIN
			set @NewProgramID= newid();
			insert into #IDList values (@NewProgID,@NewProgramID);
			--Programs

			if @CopyCAM=1 
			begin

				insert into SS_Program (id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
				PX,Py,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,
							EstimatedTime,ParentID,HasChilds,FileType,idmodule,idoperation,RelationType) 
					select @NewProgramID,Code,Kind,Ordem,@CreatedID,FilePath,Position,ProgramType,
					PX*@MultMirrX,Py*@MultMirrY,PZ,PA,PB,PC,PXIni*@MultMirrX,PYIni*@MultMirry,PZIni,PAIni,PBIni,PCIni,VectorI*@MultMirrX,VectorJ*@MultMirrY,VectorK,
							EstimatedTime,(Select NewProgramID from #IDList where OldProgramID=ParentID),HasChilds,FileType,idmodule,idoperation,RelationType from ss_program where id=@NewProgID
					order by ordem asc;

				--MIll programs
				insert into SS_MILLProgram(ID,	Feed,Spindle,FactorFeed,FactorSpindle,Tool,TCode,HolderCode,
							TD,TR,TH,TAD,TZ,Tol,Strategy,StkFin,XMin,XMax,YMin,YMax,ZMin,ZMax,AMax,AMin,BMax,BMin,CMax,CMin,PIniZG01,
							LookAheadUse,SplitCondition,ProgramStartLine,ProgramLastLine,NumProgInFile,FileModificationDate) 
					select @NewProgramID,Feed,Spindle,FactorFeed,FactorSpindle,Tool,TCode,HolderCode,
							TD,TR,TH,TAD,TZ,Tol,Strategy,StkFin,XMin,XMax,YMin,YMax,ZMin,ZMax,AMax,AMin,BMax,BMin,CMax,CMin,PIniZG01,
							LookAheadUse,SplitCondition,ProgramStartLine,ProgramLastLine,NumProgInFile,FileModificationDate from SS_MILLProgram where id=@NewProgID;
			end
			else
			begin
				insert into SS_Program (id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
							PX,Py,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,
							EstimatedTime,ParentID,HasChilds,FileType,idmodule,idoperation,RelationType) 
					select @NewProgramID,Code,Kind,Ordem,@CreatedID,FilePath,Position,ProgramType,
							PX*@MultMirrX,Py*@MultMirrY,PZ,PA,PB,PC,PXIni*@MultMirrX,PYIni*@MultMirry,PZIni,PAIni,PBIni,PCIni,VectorI*@MultMirrX,VectorJ*@MultMirrY,VectorK,
							EstimatedTime,ParentID,HasChilds,FileType,idmodule,idoperation,RelationType from ss_program where id=@NewProgID and kind<>2
					order by ordem asc;
			end

			--EDM programs
			--insert into SS_edmPoint(ID, Ordem, X, Y, Z,Apx,Apy,Apz, C) 
				--select @NewProgramID, Ordem, X, Y, Z,Apx,Apy,Apz, C from SS_edmPoint where id=@programid;

			--CMM points
			insert into ss_cmmpoint (ID, PointXExp, PointYExp, PointZExp, PointXIniExp, PointYIniExp, PointZIniExp,PointRAExp,PointRCExp) 
				select @NewProgramID, PointXExp, PointYExp, PointZExp, PointXIniExp, PointYIniExp, PointZIniExp,PointRAExp,PointRCExp from ss_cmmpoint
					 where id=@NewProgID;

			FETCH NEXT FROM lc2
			INTO @NewProgID;
		END;
		
		CLOSE lc2;
		DEALLOCATE lc2;
drop table #IDList;
END
GO


-- ----------------------------
-- function structure for GetResourcesPrevision
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourcesPrevision]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourcesPrevision]
GO

CREATE FUNCTION [dbo].[GetResourcesPrevision]
(	
	-- Add the parameters for the function here
	@IDPart uniqueidentifier, 
	@IDOperationType uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT LTRIM(RTRIM(r.Code)) AS Code FROM SM_NodePosic np  
INNER JOIN SysResources r ON r.ResourceId = np.MachineID
 WHERE  r.PartHandlingMode = 0 
 AND r.Mode <> 1 AND np.ID IN (

SELECT DISTINCT(IDNode) FROM SM_NodePosicConfiguration c
INNER JOIN (
SELECT MAX(p.FileType) as FileType, j.IDOperationType, o.IDPartType, O.IDMaterial, nprt.IDEntryPosition FROM SysJobLine jl
INNER JOIN SysJob j ON j.ID = jl.IDJob
INNER JOIN SS_Program p ON p.ID = jl.IDProgram
INNER JOIN SS_Object o ON o.ID = p.IDObject
INNER JOIN SM_NodePart nprt ON nprt.ID = o.ID
INNER JOIN SM_NodePosic nps ON nps.ID = nprt.IDEntryPosition
WHERE o.ID = @IDPart
AND j.Status IN ('CD69321D-BF74-4503-A9D6-0614F0C7CE01',
'2966AB3D-D7B6-4228-831B-342618A0FB13',
'C6812E70-56CB-4394-84A5-4C3DE719B44E',
'483D173F-7287-4751-A9D1-741DAAAB41E0')
AND j.IDOperationType = @IDOperationType
GROUP BY j.IDOperationType, o.IDPartType, O.IDMaterial, nprt.IDEntryPosition) t ON 
c.WorkAssignment = 1
AND
(c.IDOperationType = t.IDOperationType) 
AND
(c.IDFileType IS NULL OR c.IDFileType = t.FileType)
AND
(c.IDMaterial IS NULL OR c.IDMaterial = '00000000-0000-0000-0000-000000000000' OR c.IDMaterial = t.IDMaterial)
AND
(c.IDPartType IS NULL OR c.IDPartType = '00000000-0000-0000-0000-000000000000' OR c.IDPartType = t.IDPartType)
AND 
(t.IDEntryPosition IS NOT NULL AND (c.IDStorage IS NULL OR c.IDStorage = '00000000-0000-0000-0000-000000000000' OR t.IDEntryPosition IN (SELECT id FROM dbo.[SM_GetNOdeChilds](c.IDStorage)) ))
WHERE t.IDOperationType = @IDOperationType
)
)
GO


-- ----------------------------
-- procedure structure for CheckActiveAssetResourceConnection
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CheckActiveAssetResourceConnection]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CheckActiveAssetResourceConnection]
GO

CREATE PROCEDURE [dbo].[CheckActiveAssetResourceConnection]
AS
BEGIN
	with activeConnections as(
		select a2r.IDAsset2SysResource
		from Asset2SysResource a2r
		inner join Asset a on a2r.IDAsset = a.IDAsset and a2r.IDAssetModule = a.IDModule 
		inner join SysResources r on r.ResourceId = a2r.IDResource
		where a.Status not in(2788, 2801, 2792) and r.Active = 1 and (
			(GETDATE() between a2r.StartDate and a2r.EndDate) or
			(a2r.StartDate is null or a2r.EndDate is null)
		)
	)
	UPDATE Asset2SysResource set Active = 
	case 
		when IDAsset2SysResource in(
			select IDAsset2SysResource from activeConnections
		) then 1
		else 0
	end;

	update Asset Set ActiveIDAsset2Resource = t.IDActivea2r
	from(
		select a.IDAsset IDA, a2r.IDAsset2SysResource IDActivea2r
		from Asset a
		left join Asset2SysResource a2r on a2r.IDAsset = a.IDAsset and a2r.IDAssetModule = a.IDModule and a2r.Active = 1
	) t
	where IDAsset = t.IDA;

	update SysResources Set ActiveIDAsset2Resource = t.IDActivea2r
	from(
		select r.ResourceId IDR, a2r.IDAsset2SysResource IDActivea2r
		from SysResources r
		left join Asset2SysResource a2r on a2r.IDResource = r.ResourceId and a2r.Active = 1
	) t
	where ResourceId = t.IDR;
END
GO


-- ----------------------------
-- function structure for SS_GetObjectNotes
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetObjectNotes]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetObjectNotes]
GO

CREATE FUNCTION [dbo].[SS_GetObjectNotes]
(
	@ObjectID uniqueidentifier
)
RETURNS nvarchar(600)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Res nvarchar(600)

	-- Add the T-SQL statements to compute the return value here
	declare @idNote int;
	declare @note nvarchar(500);
	DECLARE ep CURSOR LOCAL
	FOR select id,Note from SS_ObjectNotes where IDObject=@ObjectID and NoteKind=3
	OPEN ep;
	FETCH NEXT FROM ep
		INTO  @idNote,@note;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		set @Res=isnull(@Res,'')+isnull(@note,'');
		FETCH NEXT FROM ep
		INTO @idNote,@note;
	END;
		
	CLOSE ep;
	DEALLOCATE ep;


	-- Return the result of the function
	RETURN @Res

END
GO


-- ----------------------------
-- procedure structure for CreateActivitiesForFixedDatedRoutines
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreateActivitiesForFixedDatedRoutines]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreateActivitiesForFixedDatedRoutines]
GO

CREATE PROCEDURE [dbo].[CreateActivitiesForFixedDatedRoutines]
	@IDRoutine uniqueidentifier
AS
BEGIN

	declare @IDFollowUpItem int, @IDFollowUpItemModule uniqueidentifier, @IDAsset int , @IDAssetModule uniqueidentifier, @dbmask int;
	declare @ActivityModule uniqueidentifier = '78C873AA-BDF4-4F1A-9F63-6A8FBB788B95';
	declare @TimeModule uniqueidentifier = '6060570B-9370-49F5-B629-1F1787FFB68D';
	declare @AdminIDUser uniqueidentifier = 'BFC1CA04-091D-4096-AEBF-48DC5B6EE77C';
	declare @AdminIDResource uniqueidentifier = '23788371-162C-41DF-AAF2-1D55558AE57C';

	select @IDFollowUpItem = a.IDFollowUpItem, @IDFollowUpItemModule = a.IDFollowUpItemModule, @IDAsset = a.IDAsset, @IDAssetModule = a.IDModule, @dbmask = a.dbmask
	from SysOprRoutine r 
	inner join Asset a on a.IDSysOprRoutine = r.IDRoutine
	where r.IDRoutine = @IDRoutine;

	declare it cursor for
	select ri.IDRoutineItem
	from SysOprRoutineItem ri
	inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
	inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
	left join Activity ac on ac.IDOprRoutineItem = ri.IDRoutineItem and ac.TemplateCode = convert(nvarchar(36), trr.ID)
	where trr.IDResource is not null and 
	isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
	and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
	and r.IDRoutine = @IDRoutine and ac.IDActivity is null;

	declare @tmp table
	(
		IDActivity int
	);

	declare @tmp2 table
	(
		IDActivityTRR uniqueidentifier
	);

	declare @tmp3 table
	(
		IDTime uniqueidentifier
	);

	open it;

	declare @IDOprRoutineItem uniqueidentifier;
	declare @CurrentCounter int = (select currentcounter from SysModule where IDModule = @ActivityModule) + 1;
	declare @CurrentCounterTime int = (select currentcounter from SysModule where IDModule = @TimeModule) + 1;
	declare @IDActivity int;
	declare @IDActivityTRR uniqueidentifier;
	declare @IDTime uniqueidentifier;
	fetch next from it into @IDOprRoutineItem

	while @@FETCH_STATUS = 0
	begin
	
		delete from @tmp;

		INSERT INTO Activity
		(subject ,status ,startDate, endDate ,dbMask ,ModifiedTime,CreatedTime ,RelatedRecord ,RegisterStatus ,
		RegisterSysStatus,IDModule,relatedRecordModule,IDUser,IDUserCreation,IDResourceCreation,IDResource,
		IDResourceAssign, TeamMask01, TeamMask02, ActivityCode, ActivityCode_Counter, activityCode_IsTemp,
		IDOprRoutineItem, IDRoutine, TemplateCode, pivotSelected, PartitionColumn)
		OUTPUT inserted.[IDActivity]
		INTO @tmp([IDActivity])
		select case 
			when fup.IDAsset = apv.IDAsset then CONCAT(fup.MouldNo, '_', ri.Name, '(', trr.Label ,')')
			else CONCAT(fup.MouldNo,'_',apv.AssetNumber ,'_', ri.Name, '(', trr.Label ,')')
		end, 2724, ri.Deadline, DATEADD(minute,isnull(trr.SimulationTime, 60),ri.Deadline), @dbmask, getdate(), getdate(), @IDFollowUpItem,0,
		0, @ActivityModule, @IDFollowUpItemModule, @AdminIDUser,@AdminIDUser, @AdminIDResource, trr.IDResource,
		trr.IDResource,trr.TeamMask01, trr.TeamMask02, concat('AT', right(concat('00000', @CurrentCounter), 5)), @CurrentCounter, 0,
		ri.IDRoutineItem, r.IDRoutine, convert(nvarchar(36), trr.ID), 1, YEAR(getdate())
		from SysOprRoutineItem ri
		inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
		inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
		inner join Asset a on a.IDSysOprRoutine = ri.IDRoutine
		inner join SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
		inner join FollowUpItemMouldFields fup on fup.IDFollowUpItem = a.IDFollowUpItem
		where trr.IDResource is not null and 
		isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
		and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
		and ri.IDRoutineItem = @IDOprRoutineItem;

		set @IDActivity = (select top 1 idactivity from @tmp);

		insert into SysActivityResourceRoleActivity
		OUTPUT inserted.[IDActivityResourceRoleActivity] INTO @tmp2(IDActivityTRR)
		select newid(), trr.idrole, @IDActivity, trr.IDResource, @ActivityModule, l2r.IDLogin,1,null, trr.TeamMask01, trr.TeamMask02, 0,0
		from SysOprRoutineItem ri
		inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
		inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where trr.IDResource is not null and 
		isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
		and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
		and ri.IDRoutineItem = @IDOprRoutineItem

		set @IDActivityTRR = (select top 1 IDActivityTRR from @tmp2);

		insert into Systimes
		(
			ID,_old_ID,Code,Code_counter,Code_IsTemp,StartDate,EndDate,
			Duration,Type,Status,IDResource,IDUser,
			AutoEnd,Subject, pivotSelected,TimeWeight,TimeType,TRegisterType,IsAccountedHoursBank,Dirty,Closed,TimelineType,
			SwitchTimeTypeAutomatically,TeamMask01,TeamMask02,IDRole,OwnUserChangedPoint
		)
		OUTPUT inserted.[ID] INTO @tmp3(IDTime)
		select newid(), NEWID(), CONCAT('TM-', RIGHT(concat('000000', @CurrentCounterTime),6)), @CurrentCounterTime, 0, ri.Deadline, DATEADD(minute,isnull(trr.SimulationTime, 60),ri.Deadline),
		dbo.TimeToTicks(0, isnull(trr.SimulationTime, 60),0) ,7,2726,trr.IDResource, isnull(l2r.IDLogin, '00000000-0000-0000-0000-000000000000'),
		0, 'Planned',2, 100.0,2,2,0,0,0,0,0,trr.TeamMask01, trr.TeamMask02, trr.IDRole,0
		from SysOprRoutineItem ri
		inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
		inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where trr.IDResource is not null and 
		isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
		and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
		and ri.IDRoutineItem = @IDOprRoutineItem;

		set @IDTime = (select top 1 IDTime from @tmp3);

		insert into SysTimesResourceRoleTask
		values(NEWID(), NEWID(), @IDTime, null, 100.0, null,null,null, @IDActivityTRR,null,null,null);

		insert into Activity2Record
		(
			IDActivity,IDActivityModule,IDModule,relatedRecord,relatedRecordModule,IDResource,IDUser,
			IsTemplate,TemplateCode,IDResourceAssign,IDResourceCreation,IDUserCreation,dbmask,
			ModifiedTime,CreatedTime,RegisterStatus,RegisterSysStatus,TeamMask01,TeamMask02,TemplateDefaultMFVCreate
		)
		select @IDActivity, @ActivityModule, '59CF0AA6-9CF6-4528-9508-9BFC41D7F359', @IDFollowUpItem, @IDFollowUpItemModule, @AdminIDResource, @AdminIDUser,
		0, '', @AdminIDResource, @AdminIDResource, @AdminIDUser, @dbmask,
		GETDATE(), getdate(), 0,0,trr.TeamMask01, trr.TeamMask02,0
		from SysOprRoutineItem ri
		inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
		inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where trr.IDResource is not null and 
		isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
		and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
		and ri.IDRoutineItem = @IDOprRoutineItem

		union all

		select @IDActivity, @ActivityModule, '59CF0AA6-9CF6-4528-9508-9BFC41D7F359', @IDAsset, @IDAssetModule, @AdminIDResource, @AdminIDUser,
		0, '', @AdminIDResource, @AdminIDResource, @AdminIDUser, @dbmask,
		GETDATE(), getdate(), 0,0,trr.TeamMask01, trr.TeamMask02,0
		from SysOprRoutineItem ri
		inner join SysOprRoutine r on r.IDRoutine = ri.IDRoutine
		inner join SysRoutineTeamRoleResource trr on ri.IDRoutineItem = trr.IDRoutineItem
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where trr.IDResource is not null and 
		isnull(ri.FixedDeadLine,0) = 1 and ri.Deadline is not null
		and r.WorkingStatus NOT IN ('88B381D9-D1DB-4C80-8E78-3076B1E196F2', '2F2593EC-D358-493E-B02C-3DB5A912C399', 'A52E3BCC-9BDD-4F8F-99D7-B5D5C69EAB70')
		and ri.IDRoutineItem = @IDOprRoutineItem

		update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @ActivityModule;
		update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @TimeModule;

		set @CurrentCounter = @CurrentCounter + 1;
		set @CurrentCounterTime = @CurrentCounterTime + 1;

		fetch next from it into @IDOprRoutineItem
	end

	close it;
	deallocate it;

END
GO


