-- ----------------------------
-- procedure structure for DeleteRoutine
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DeleteRoutine]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[DeleteRoutine]
GO

CREATE PROCEDURE [dbo].[DeleteRoutine] 
	-- Add the parameters for the stored procedure here
	@IDRoutine uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @ReqCounter int
DECLARE @PRCounter int
SET @ReqCounter = 0
SET @PRCounter = 0

DECLARE @Message Nvarchar(MAX)
SET @Message = ''


SET @PRCounter = (SELECT COUNT(*) FROM SysRoutine WHERE IDRoutine = @IDRoutine)
IF @PRCounter = 0 
	BEGIN
		SET @Message = CONCAT(@Message,'No Routine Found')
	END
ELSE
	BEGIN
		SET @ReqCounter = (SELECT COUNT(*) FROM SysPrRoutineRequest WHERE IDPrRoutine IN (
		SELECT IDRoutine FROM SysPrRoutine WHERE RoutineClone = @IDRoutine
		)
		AND WorkingStatus IN ('CD69321D-BF74-4503-A9D6-0614F0C7CE01','C6812E70-56CB-4394-84A5-4C3DE719B44E','483D173F-7287-4751-A9D1-741DAAAB41E0')
		)

		IF @ReqCounter > 0
			BEGIN
				SET @Message = CONCAT(@Message,'Found Routine, but Open Requests')
			END
		ELSE
			BEGIN

			
			DELETE FROM SysRoutineItem WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutineItemLink WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutineVarsRelation WHERE IDSysRoutine = @IDRoutine
			DELETE FROM SysRoutineCondition WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutineItemIntProductCondition WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutineOperationType WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutine WHERE IDRoutine = @IDRoutine
			DELETE FROM SysRoutineVar WHERE IDRoutine = @IDRoutine

			DECLARE @NEWID uniqueidentifier 
			
			SET @NEWID = (SELECT IDRoutine FROM SysPrRoutine WHERE RoutineClone = @IDRoutine)

			IF @NEWID IS NULL
				BEGIN
					SET @Message = CONCAT(@Message,', NO Routine In Production')
				END 
			ELSE
				BEGIN
					DELETE FROM SysPrRoutineItem WHERE IDRoutine = @NEWID
					DELETE FROM SysPrRoutineItemLink WHERE IDRoutine = @NEWID
					DELETE FROM SysPrRoutineVarsRelation WHERE IDSysRoutine = @NEWID
					DELETE FROM SysPrRoutineCursorConditions WHERE IDSysRoutine = @NEWID
					DELETE FROM SysPrRoutineCursor WHERE IDSysRoutine = @NEWID
					DELETE FROM SysPrRoutineTimers WHERE IDRequest IN (SELECT ID FROM SysPrRoutineRequest WHERE IDPrRoutine = @NEWID)
					DELETE FROM SysPrRoutineOperationType WHERE IDRoutine = @NEWID
					DELETE FROM SysPrRoutineVarTemplate WHERE IDRoutine = @NEWID
					DELETE FROM SysPrRoutineResourcePositions WHERE IDProcess = @NEWID
					DELETE FROM SysPrRoutineRequest WHERE IDPrRoutine = @NEWID AND ID NOT IN (SELECT IDREQUEST FROM SysTimes)
					DELETE FROM SysPrRoutineVar WHERE IDRoutine = @NEWID
					DELETE FROM SysPrRoutine WHERE IDRoutine = @NEWID
				END
			
				SET @Message = CONCAT(@Message,' DELETED Routine')

			END
		
	END

	PRINT @Message
END
GO


-- ----------------------------
-- procedure structure for UpdateAssetCalculatedFields
