IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAssetCalculatedFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAssetCalculatedFields]
GO

CREATE PROCEDURE [dbo].[UpdateAssetCalculatedFields]
	(@IDAsset int)
AS
BEGIN
	
	SET NOCOUNT ON;

	declare @AssetModule uniqueidentifier = (select top 1 IDModule from asset where idasset = @IDAsset);
	declare @CurrentResource uniqueidentifier = (select top 1 IDResource from Asset2SysResource where IDAsset = @IDAsset and IDAssetModule = @AssetModule and Active = 1);

	if(@CurrentResource is not null)
	begin
		update asset set CurrentResource = @CurrentResource
		where idasset = @IDAsset;

		update Account set CurrentResource = @CurrentResource
		where IDContact = @IDAsset and IDContactModule = @AssetModule;

	end
	
END
GO


-- ----------------------------
-- function structure for SS_GetJobListTimes
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetJobListTimes]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[SS_GetJobListTimes]
GO

CREATE FUNCTION [dbo].[SS_GetJobListTimes]
(	
	@OperationKind uniqueidentifier
)
RETURNS @Res TABLE 
(
	EstimatedTime int,
	RealTime int,
	StartDate datetime,
	IDJob int,
	IDObject uniqueidentifier,
	IDResource uniqueidentifier
)
AS
BEGIN
	
	Insert into @Res
	Select sum(spr.ProgramEstimatedTime),Sum(a.Duration) 'RealTime',
	Min(a.StartDate) 'ProcessedDate',j.id,j.IDPart,spr.IDResourcePosition
	from SysJob j 
	inner join SysJobLine jl on jl.idjob=j.ID and jl.Active=1 and jl.LineType=0 and (jl.Status='88B381D9-D1DB-4C80-8E78-3076B1E196F2' or jl.Status='5FF6EB53-52F6-4A50-83AE-B23CC8C44054'
	or jl.Status = '2F2593EC-D358-493E-B02C-3DB5A912C399')
	inner join SysPrRoutineRequest spr on spr.IDJobLine=jl.IDJobLine
	inner JOIN (SELECT Min(StartDate) as StartDate, Max(endDate) as EndDate, 
	DATEDIFF(SECOND,Isnull(Min(StartDate),0),Isnull(Max(endDate),Min(StartDate))) Duration, IDRequest, IDPart FROM SysTimes WHERE IDRequest IS NOT NULL AND IDPart IS NOT NULL GROUP BY IDPart, IDRequest) a ON spr.ID = a.IDRequest 
	 where j.IDOperationType=@OperationKind 
	 AND spr.IDResourcePosition IS NOT NULL
	 AND spr.IDRequestToResolve is null 
	 AND spr.idtask is null 
	 AND spr.IDRequestLink IS NULL
	group by j.id,j.IDPart,spr.IDResourcePosition

	
return
END
GO


-- ----------------------------
-- procedure structure for UdateActivitiesDatesForFixedDatedRoutines
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UdateActivitiesDatesForFixedDatedRoutines]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UdateActivitiesDatesForFixedDatedRoutines]
GO

CREATE PROCEDURE [dbo].[UdateActivitiesDatesForFixedDatedRoutines]
	@IDDocRoutine uniqueidentifier
AS
BEGIN
	declare @IDRoutine uniqueidentifier = (select top 1 idroutine from SysOprRoutine where DocTemplate = @IDDocRoutine);

	update Activity set status = 2726 where IDActivity in
	(
		select IDActivity
		from Activity a
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = a.IDOprRoutineItem
		inner join SysRoutineTeamRoleResource trr on trr.IDRoutineItem = ri.IDRoutineItem and a.TemplateCode = convert(nvarchar(36), trr.ID)
		where ri.IDRoutine = @IDRoutine and
		(
			isnull(ri.FixedDeadLine,0) = 0 or trr.IDResource is null
		)
	);

	update Activity set startDate = t.SDate, endDate = t.EDate, duration = dbo.TimeToTicks(0, DATEDIFF(minute, t.sdate, t.edate), 0)
	from
	(
		select a.IDActivity IDA, ri.Deadline SDate, DATEADD(MINUTE, trr.SimulationTime, ri.Deadline) EDate
		from Activity a
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = a.IDOprRoutineItem
		inner join SysRoutineTeamRoleResource trr on trr.IDRoutineItem = ri.IDRoutineItem and a.TemplateCode = convert(nvarchar(36), trr.ID)
		where ri.IDRoutine = @IDRoutine
		and isnull(ri.FixedDeadLine,0) = 1 or trr.IDResource is not null
	) t
	where IDActivity = IDA;

	update SysActivityResourceRoleActivity set TeamMask01 = t.IDT1, TeamMask02 = t.IDT2, IDActivityRole = t.IDRol,
	IDResource = t.IDR, IDUser = t.IDL
	from
	(
		select a.IDActivity IDA, trr.TeamMask01 IDT1, trr.TeamMask02 IDT2, trr.IDRole IDRol,trr.IDResource IDR, l2r.IDLogin IDL
		from Activity a
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = a.IDOprRoutineItem
		inner join SysRoutineTeamRoleResource trr on trr.IDRoutineItem = ri.IDRoutineItem and a.TemplateCode = convert(nvarchar(36), trr.ID)
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where ri.IDRoutine = @IDRoutine
		and isnull(ri.FixedDeadLine,0) = 1 or trr.IDResource is not null
	) t
	where IDActivity = IDA;

	update SysTimes set TeamMask01 = t.IDT1, TeamMask02 = t.IDT2, IDRole = t.IDRol,
	IDResource = t.IDR, IDUser = t.IDL, StartDate = t.SDate, EndDate = t.EDate, Duration = dbo.TimeToTicks(0, DATEDIFF(minute, t.sdate, t.edate), 0)
	from
	(
		select a.IDActivity IDA, trr.TeamMask01 IDT1, trr.TeamMask02 IDT2, trr.IDRole IDRol,trr.IDResource IDR, isnull(l2r.IDLogin, '00000000-0000-0000-0000-000000000000') IDL, t.ID as IDT,
		ri.Deadline as SDate, DATEADD(MINUTE, trr.SimulationTime, ri.Deadline) EDate
		from Activity a
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = a.IDOprRoutineItem
		inner join SysRoutineTeamRoleResource trr on trr.IDRoutineItem = ri.IDRoutineItem and a.TemplateCode = convert(nvarchar(36), trr.ID)
		inner join SysActivityResourceRoleActivity arra on arra.IDActivity = a.IDActivity
		inner join SysTimesResourceRoleTask trrt on trrt.IDActivityResourceRoleActivity = arra.IDActivityResourceRoleActivity
		inner join SysTimes t on t.ID = trrt.IDSysTime
		left join SysLogin2SysResource l2r on l2r.IDResource = trr.IDResource and isnull(l2r.Active,0) = 1
		where ri.IDRoutine = @IDRoutine
		and isnull(ri.FixedDeadLine,0) = 1 or trr.IDResource is not null
	) t
	where ID = IDT;
END
GO


-- ----------------------------
-- procedure structure for SS_CopyFileSearch
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CopyFileSearch]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CopyFileSearch]
GO

CREATE PROCEDURE [dbo].[SS_CopyFileSearch]
	-- Add the parameters for the stored procedure here
	@IDFileSearch int,
	@IDTargetConfig int,
	@ResultID int output
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	Insert into [SS_ImporterSearchFile] ( Name, ConfigID, SearchFolder, FilenameA2XFile, FileExt, OnlyTopFolder, MoveAction, MoveDestination, ParseFilePath)
	select  Name, @IDTargetConfig, SearchFolder, FilenameA2XFile, FileExt, OnlyTopFolder, MoveAction, MoveDestination, ParseFilePath from [SS_ImporterSearchFile] where id=@IDFileSearch

	set @ResultID=SCOPE_IDENTITY();

	declare @IDFileInfo int;
	DECLARE ep CURSOR LOCAL
	FOR select id from SS_ImporterSearchInfo where SearchFilesID=@IDFileSearch
	OPEN ep;
	FETCH NEXT FROM ep
		INTO  @IDFileInfo;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--
		declare @res int;
		EXEC SS_CopyFileInfo @IDFileInfo,@ResultID,@res output;

		FETCH NEXT FROM ep
		INTO @IDFileInfo;
	END;
		
	CLOSE ep;
	DEALLOCATE ep;


END
GO


-- ----------------------------
-- function structure for GetCurrentTimeToEnd
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetCurrentTimeToEnd]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetCurrentTimeToEnd]
GO

CREATE FUNCTION [dbo].[GetCurrentTimeToEnd] 
(
	-- Add the parameters for the function here
	@IDPart UniqueIdentifier,
	@IDOpType UniqueIdentifier,
	@Factor float
)
RETURNS float
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Result float

	DECLARE @Times TABLE (
	date datetime,
	time float
)

INSERT INTO @Times (date, time)
SELECT t.StartDate, COALESCE((p.EstimatedTime * @Factor),0) FROM SysTimes t 
LEFT JOIN SysPrRoutineRequest rr ON rr.ID = t.IDRequest 
LEFT JOIN SS_Program p ON p.ID = rr.IDProgram
WHERE 
t.EndDate IS NULL
AND t.IDPart = @IDPart 
AND rr.IDOperationType = @IDOpType 
AND rr.IDRequestLink IS NULL 
AND rr.IDRequestToResolve IS NULL 
AND rr.IDTask IS NULL 
AND rr.WorkingStatus  = '483D173F-7287-4751-A9D1-741DAAAB41E0'


SELECT @Result  = (
SELECT 
CASE 
				WHEN eltime < 0   
				THEN 
					0
				WHEN eltime > time
				THEN 
					time
				ELSE 
					eltime
						
			END as TimeRem 
FROM(
	SELECT DATEDIFF ( ss , date , GETDATE() ) as eltime, time  FROM @Times
) t)

	-- Add the T-SQL statements to compute the return value here
	

	-- Return the result of the function
	RETURN @Result

END
GO


-- ----------------------------
-- function structure for GetTotalTimesDurationsTask
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTotalTimesDurationsTask]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTotalTimesDurationsTask]
GO

CREATE FUNCTION [dbo].[GetTotalTimesDurationsTask]
(	
	@IDTask uniqueidentifier
)
RETURNS bigint 
AS
BEGIN

	DECLARE @duration bigint
	
	set @duration=	isnull((SELECT  Sum((TRRA.TimeWeight /100)* t.Duration ) 
		FROM  dbo.SysTask AS task WITH(NOLOCK)
		inner join dbo.SysTaskResourceRole as TRR WITH(NOLOCK) ON task.IDTask = TRR.IDTask
		INNER JOIN dbo.SysTimesResourceRoleTask  AS TRRA  WITH (NOLOCK) ON TRR.IDTaskResourceRole = TRRA.IDTaskResourceRole
		INNER JOIN dbo.SysTimes as  t WITH (NOLOCK) ON t.ID = TRRA.IDSysTime
		where task.IDTask = @IDTask and (TimeType=1 OR TimeType=4)),0)
		
	return @duration

end
GO


-- ----------------------------
-- procedure structure for GetPartListSolidset
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPartListSolidset]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetPartListSolidset]
GO

CREATE PROCEDURE [dbo].[GetPartListSolidset]
	-- Add the parameters for the stored procedure here
	@IDParent uniqueidentifier = null,
	@Visibility int = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	select  Q.*,  wsJOBMILL.code JOBMILLCode,  wsCAD.code CADCode,  wsCMM.code CMMCode,  wsCAM.code CAMCode,  wsPreSet.code PreSetCode,  wsMill.code MillCode,  
wsEDMJobPreparation.code EDMJobPreparationCode,  wsJobPreset.code JobPresetCode,  wsEDM.code EDMCode,  wsJobCMM.code JobCMMCode,  wsCMMValidation.code CMMValidationCode,  
mat.code MaterialCode,  wsWorkingstatus.code WorkingstatusCode  from
(  SELECT  
case 
when TypeId = 1 then 'Part'       
when TypeId = 2 then 'Electrode'       
when TypeId = 3 then 'Mould'       
else null  end as ObjectType,  
o.ID, o.IDShape, m.name 'MouldName', o.Idroutine, o.Idholder,  cRes.cmmvalidated, TypeID, ShortName,  MILLRC, Available, e.EletrodeFamily,  e.Gap, o.Idparttype, o.DimReal_Z, o.fullname 'Fullname', 
o.ImageFile,  o.Workingstatus,  case when TypeId = 1 then MouldId       when TypeId = 2 then o.ParentID       when TypeId = 3 then null       else null  end as Parentid,  o.Mouldid, o.CleanState,  
RTRIM(po.Code) + ' (' + RTRIM(po.MachineCode) + ')' 'CurPosicCode',  o.IdMaterial,  MAX(o.Priority) 'Priority',  
MAX(case when opr.IDOperationType = 'B16C495E-F245-471E-A0FE-0D8DA4BE1A71' then opr.workingstatus end) as JOBMILL,  
MAX(case when opr.IDOperationType = 'C5033B3E-A7D2-472E-B051-2D0FABE1A0F9' then opr.workingstatus end) as CAD,  
MAX(case when opr.IDOperationType = 'DCE05E46-10CF-487C-838F-2FE8FEDBC0EB' then opr.workingstatus end) as CMM,  
MAX(case when opr.IDOperationType = '789748CF-69A3-41FE-84AB-32839E4487E3' then opr.workingstatus end) as CAM,  
MAX(case when opr.IDOperationType = '0E25BA69-DC29-4372-9499-61D9A8DF0B9B' then opr.workingstatus end) as PreSet,  
MAX(case when opr.IDOperationType = 'EF565EE7-488B-438D-95D8-913C0697F61B' then opr.workingstatus end) as Mill,  
MAX(case when opr.IDOperationType = '80B6F5F0-1971-4BE4-B612-ADCD21CC1A9E' then opr.workingstatus end) as EDMJobPreparation,  
MAX(case when opr.IDOperationType = 'C927384F-B500-450A-B9C4-BD9B0BDC5B85' then opr.workingstatus end) as JobPreset,  
MAX(case when opr.IDOperationType = '0B310861-E07E-460F-87F0-D9120455CD2D' then opr.workingstatus end) as EDM,  
MAX(case when opr.IDOperationType = '6751FD69-2DD8-4B24-88B3-DCEF6772E3D7' then opr.workingstatus end) as Material,  
MAX(case when opr.IDOperationType = 'C5438CF2-1354-4C97-BD71-EF90CFEFC814' then opr.workingstatus end) as JobCMM,  
MAX(case when opr.IDOperationType = '3AD8B184-794B-416B-8A60-FF75ACE9F9FF' then opr.workingstatus end) as CMMValidation  
FROM SS_Object o  
LEFT JOIN (SELECT IDPart, IDOperationType, WorkingStatus FROM SysOprRoutineItem WHERE IDOperationType IS NOT NULL) opr on opr.IDPart = o.ID  
LEFT JOIN ss_mould m ON m.id = o.mouldid  
LEFT JOIN SS_Eletrode e ON o.id = e.id  
LEFT JOIN SysJobCMMResults cRes ON cRes.IDJob = o.CMMIDJobResults  
LEFT JOIN (SELECT IDNodePartDocked, Code, MachineCode FROM sm_nodeposic) po ON po.IDNodePartDocked = o.IDHolder 
WHERE o.TypeId IS NOT NULL 
AND 
(
((@Visibility IS NULL) and (o.Visibility = 1 OR o.Visibility = 0))
OR
((@Visibility IS NOT NULL) and (o.Visibility = @Visibility))
)
GROUP BY o.ID, o.IDShape, m.name , o.idroutine, o.idholder,  cRes.cmmvalidated, TypeID, ShortName,  MILLRC, Available, e.EletrodeFamily, e.gap, o.idparttype, o.DimReal_Z, o.fullname, o.ImageFile,  
o.workingstatus, o.parentid, o.mouldid, o.CleanState, RTRIM(po.Code) + ' (' + RTRIM(po.MachineCode) + ')', o.IdMaterial  
UNION SELECT 'Shape' as ObjectType, s.ID, null IDShape, null name, null Idroutine, null Idholder,  null cmmvalidated, null TypeID, null ShortName, null MILLRC, null Available, null ElectrodeFamily,  
s.Gap, null Idparttype, null DimReal_Z, s.Fullname, null ImageFile,  null Workingstatus, idparent Parentid, null Mouldid, null CleanState, null CurPosicCode,  null IdMaterial,  null Priority, 
null JOBMILL,  null CAD,  null CMM,  null CAM,  null Preset,  null Mill,  null EDMJobPreparation,  null JobPreset,  null EDM,  null Material,  null JobCMM,  null CMMValidation  
FROM SS_Shape s  
WHERE s.ID in (select idshape from SS_Object)  ) as Q  
LEFT JOIN SS_Material mat ON q.IdMaterial = mat.idmaterial  
LEFT JOIN SysWorkingStatus wsWorkingstatus ON q.Workingstatus = wsWorkingstatus.id  
LEFT JOIN SysWorkingStatus wsJOBMILL ON q.JOBMILL = wsJOBMILL.id  
LEFT JOIN SysWorkingStatus wsCAD ON q.CAD = wsCAD.id  
LEFT JOIN SysWorkingStatus wsCMM ON q.CMM = wsCMM.id  
LEFT JOIN SysWorkingStatus wsCAM ON q.CAM = wsCAM.id  
LEFT JOIN SysWorkingStatus wsPreSet ON q.PreSet = wsPreSet.id  
LEFT JOIN SysWorkingStatus wsMill ON q.Mill = wsMill.id  
LEFT JOIN SysWorkingStatus wsEDMJobPreparation ON q.EDMJobPreparation = wsEDMJobPreparation.id  
LEFT JOIN SysWorkingStatus wsJobPreset ON q.JobPreset = wsJobPreset.id  
LEFT JOIN SysWorkingStatus wsEDM ON q.EDM = wsEDM.id  
LEFT JOIN SysWorkingStatus wsJobCMM ON q.JobCMM = wsJobCMM.id  
LEFT JOIN SysWorkingStatus wsCMMValidation ON q.CMMValidation = wsCMMValidation.id 
where 
((@IDParent IS NULL) and (Q.Parentid IS NULL))
OR
((@IDParent IS NOT NULL) and (Q.Parentid = @IDParent))
option(recompile) 
END
GO


