CREATE PROCEDURE [dbo].[SS_CopyMachine]
	@MAchineName nvarchar(50),
	@IDCopyMahine int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @NewMachineID uniqueidentifier
	declare @CopyMachineID uniqueidentifier
	set @CopyMachineID=(Select IDPostProcessor from ss_Postprocessor where Id=@IDCopyMahine)
set @NewMachineID=newID();


insert into SS_PostProcessor (IDPostProcessor,
	code, Logo, Description, FeedRapid, FeedMax, SpindleMax, WriteType, WriteLineNumberStart, 
	WriteLineNumberFin, WriteLineNumberInc, WriteNumbering, ValidationZLimit, WriteRapidType, 
	WriteArcsType, WriteArcsPlaneType, WriteArcsPlane, WriteArcsG6, WritePointInteger, WritePointFeed, 
	WriteDecPlaces, WriteWordSpaces, WriteNResetType, Wr90, CommentsType, Comments, ToolCH, ToolCHPrep, 
	ToolCompH, ToolCompDType, ToolCompD41, ToolCompD40, ToolCompD42, ToolVerifyBeforeProg, ToolVerifyAfterProg, 
	SpindleRightON, SpindleOFF, SpindleLeftON, Origin, NCSETStartNoNumber, NCSETStart, NCSETEnd, NCSETEndNoNumber, 
	PalletLoad, PalletStart, PalletEnd, ProgramStart, ProgramEnd, Program, Pallet, PalletStore, NCSET, NCSETNoNumber, 
	HeadLockON, HeadLockOFF, HeadIndexON, HeadIndexOFF, Tol1Def, Tol1STKmax, Tol2Def, Tol2STKmax, Tol3Def, TolDefOFF,
	 Stop, WriteLinearType, WriteDecPlacesFixed, Dev1ON, Dev1OFF, Dev2ON, Dev2OFF, Dev3ON, Dev3OFF, Dev4ON, Dev4OFF, 
	 Dev5ON, Dev5OFF,  ToolCompHinSec, ToolCompHinPart, OriginReProcAftToolCH, OriginReProcAftTooVer, OriginReProcAftSec,
	  PartStart, PartLoad, PartEnd, Part, PartStore, TableOriginX, TableOriginY, TableOriginZ, WriterapidFMax, SecurityABSXY,
	   SecurityABSZ, CommentsMaxChar, Dev6ON, Dev6OFF, Dev7ON, Dev7OFF, Dev8ON, Dev8OFF, Dev9ON, Dev9OFF, Dev10ON, Dev10OFF,
	    WriteFeedMax, Dev1Code, Dev2Code, Dev3Code, Dev4Code, Dev5Code, Dev6Code, Dev7Code, Dev8Code, Dev9Code, Dev10Code,
	 MeasurePointXYZ, SecX, SecY, SecZ, AbsXCutMin, AbsXCutMax, AbsYCutMin, AbsYCutMax, AbsZCutmin, AbsZCutMax, CyclePlaneRect, 
	 Cycle, OriginDisplType, OriginDisplDef, MeasureSpindle, PartLoaderSecX, PartLoaderSecY, PartLoaderSecZ, ReprocCompAfterOrigin, 
	 CommentsInEnglish, MeasureFeed, Type, WriteAbsoluteCoordinatesDef, SpindleDef, HeadDontLock, LADist, LAAngMin, LAAngMax, 
	 LAFeedMax, LAFeedMin, Zseguranca, EDMStart, EDM, DestFile, DefExt, EleMagSTL, MakeLogs, FirstPXYSuffix, CMMResultFilePath, ToolRotate, ProgramExecute,
	 RotAOrigin, RotBOrigin, RotCOrigin, RotADirection, RotBDirection, RotCDirection, CmmMeasureFeed, CMMMoveToCoordinate, 
	 CycleEnd, WriteM90, OriginDisplEndDef, ReadPartRotation)
select @NewMachineID, @MAchineName,Logo, Description, FeedRapid, FeedMax, SpindleMax, WriteType, WriteLineNumberStart, 
	WriteLineNumberFin, WriteLineNumberInc, WriteNumbering, ValidationZLimit, WriteRapidType, 
	WriteArcsType, WriteArcsPlaneType, WriteArcsPlane, WriteArcsG6, WritePointInteger, WritePointFeed, 
	WriteDecPlaces, WriteWordSpaces, WriteNResetType, Wr90, CommentsType, Comments, ToolCH, ToolCHPrep, 
	ToolCompH, ToolCompDType, ToolCompD41, ToolCompD40, ToolCompD42, ToolVerifyBeforeProg, ToolVerifyAfterProg, 
	SpindleRightON, SpindleOFF, SpindleLeftON, Origin, NCSETStartNoNumber, NCSETStart, NCSETEnd, NCSETEndNoNumber, 
	PalletLoad, PalletStart, PalletEnd, ProgramStart, ProgramEnd, Program, Pallet, PalletStore, NCSET, NCSETNoNumber, 
	HeadLockON, HeadLockOFF, HeadIndexON, HeadIndexOFF, Tol1Def, Tol1STKmax, Tol2Def, Tol2STKmax, Tol3Def, TolDefOFF,
	 Stop, WriteLinearType, WriteDecPlacesFixed, Dev1ON, Dev1OFF, Dev2ON, Dev2OFF, Dev3ON, Dev3OFF, Dev4ON, Dev4OFF, 
	 Dev5ON, Dev5OFF,  ToolCompHinSec, ToolCompHinPart, OriginReProcAftToolCH, OriginReProcAftTooVer, OriginReProcAftSec,
	  PartStart, PartLoad, PartEnd, Part, PartStore, TableOriginX, TableOriginY, TableOriginZ, WriterapidFMax, SecurityABSXY,
	   SecurityABSZ, CommentsMaxChar, Dev6ON, Dev6OFF, Dev7ON, Dev7OFF, Dev8ON, Dev8OFF, Dev9ON, Dev9OFF, Dev10ON, Dev10OFF,
	    WriteFeedMax, Dev1Code, Dev2Code, Dev3Code, Dev4Code, Dev5Code, Dev6Code, Dev7Code, Dev8Code, Dev9Code, Dev10Code,
	 MeasurePointXYZ, SecX, SecY, SecZ, AbsXCutMin, AbsXCutMax, AbsYCutMin, AbsYCutMax, AbsZCutmin, AbsZCutMax, CyclePlaneRect, 
	 Cycle, OriginDisplType, OriginDisplDef, MeasureSpindle, PartLoaderSecX, PartLoaderSecY, PartLoaderSecZ, ReprocCompAfterOrigin, 
	 CommentsInEnglish, MeasureFeed, Type, WriteAbsoluteCoordinatesDef, SpindleDef, HeadDontLock, LADist, LAAngMin, LAAngMax, 
	 LAFeedMax, LAFeedMin, Zseguranca, EDMStart, EDM, DestFile, DefExt, EleMagSTL, MakeLogs, FirstPXYSuffix, CMMResultFilePath, ToolRotate, ProgramExecute,
	 RotAOrigin, RotBOrigin, RotCOrigin, RotADirection, RotBDirection, RotCDirection, CmmMeasureFeed, CMMMoveToCoordinate, 
	 CycleEnd, WriteM90, OriginDisplEndDef, ReadPartRotation
	  from SS_PostProcessor where idpostprocessor=@CopyMachineID


INSERT [dbo].[SS_EDMEletrodeTypes] ( [Code], IDPostProcessor) select [Code], @NewMachineID from [SS_EDMEletrodeTypes] where IDPostProcessor=@CopyMachineID

INSERT [dbo].SS_PostProcessorEDMTec ( [IDPostProcessor], [Code], [MinimumGap], [MaximumGap], [IDEletrodeType], [CompZ]) 
select @NewMachineID, [Code], [MinimumGap], [MaximumGap], [IDEletrodeType], [CompZ] from SS_PostProcessorEDMTec where [IDPostProcessor]=@CopyMachineID
END
GO


-- ----------------------------
-- function structure for GetBAsAscRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetBAsAscRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetBAsAscRec]
GO

CREATE FUNCTION [dbo].[GetBAsAscRec]
(	
	@IDBusinessArea int
)
RETURNS TABLE 
AS
RETURN 
(
	with LineDepthsAux as(
		select IDBusinessArea, IDParent, 0 LineDepth
		from BusinessArea
		where IDParent is null
		union all
		select m.IDBusinessArea, m.IDParent, case when m.IDParent is null then 0 else p.LineDepth + 1 end LineDepth
		from BusinessArea m inner join LineDepthsAux p on m.IDParent = p.IDBusinessArea
	), LineDepths as(
		select m.IDBusinessArea, rec.LineDepth
		from BusinessArea m
		inner join LineDepthsAux rec on m.IDBusinessArea = rec.IDBusinessArea
	),GetBAsAscRec as (
		select IDBusinessArea, IDParent, 0 LineDepth
		from BusinessArea
		where IDBusinessArea = @IDBusinessArea
		union all
		select m.IDBusinessArea, m.IDParent, case when m.IDParent is null then 0 else p.LineDepth + 1 end LineDepth
		from BusinessArea m inner join GetBAsAscRec p on m.IDBusinessArea = p.idparent
	)
	select m.*, depths.LineDepth
	from BusinessArea m
	inner join GetBAsAscRec rec on m.IDBusinessArea = rec.IDBusinessArea
	inner join LineDepths depths on m.IDBusinessArea = depths.IDBusinessArea
)
GO


-- ----------------------------
-- function structure for GetNexTasksForTaskProduction
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetNexTasksForTaskProduction]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetNexTasksForTaskProduction]
GO

CREATE FUNCTION [dbo].[GetNexTasksForTaskProduction]
(
	@IDTask uniqueidentifier
)
RETURNS @RET TABLE
(
	IDRoutine uniqueidentifier,	
	IDRoutineItem uniqueidentifier,	
	Label nvarchar(500),	
	IDTask uniqueidentifier,
	AssetMouldNumber nvarchar(1000),
	IsPhase int, 
	IDTaskModule uniqueidentifier
)
AS
BEGIN

	declare @tmp Table
	(
		IDRoutine uniqueidentifier,	
		IDRoutineItem uniqueidentifier,	
		ID uniqueidentifier,	
		[Order] int,	
		Label nvarchar(500),	
		IDProcessRoutineItem uniqueidentifier,	
		VirtualNode	int,
		ClosingItem int, 
		IDTask uniqueidentifier,
		IsPhase int
	);

	declare @IDRoutine uniqueidentifier = (select top 1 IDRoutine from SysRoutineTeamRoleResource where IDSysTaskProcess = @IDTask);

	with currentTask as 
	(
		select IDRoutine, IDRoutineItem, ID, [Order], Label, IDProcessRoutineItem 
		from SysRoutineTeamRoleResource 
		where IDSysTaskProcess = @IDTask
	), nextRoutineItems as
	(
		select t.IDRoutine, t.IDRoutineItem, trr.ID, trr.[Order], trr.Label, nxt.IDRoutineItem as IDProcessRoutineItemNext, 
		isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem
		from currentTask t
		inner join SysRoutineItemLink l on l.Origin = t.IDProcessRoutineItem 
		inner join SysRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
		left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and t.IDRoutineItem = trr.IDRoutineItem 
		and trr.IDProcessRoutineItem = nxt.IDRoutineItem 
	), nextNextRoutineItems as
	(
		select t.IDRoutine, t.IDRoutineItem, trr.ID, trr.[Order], trr.Label, t.IDProcessRoutineItemNext, nxt.IDRoutineItem as IDProcessRoutineItemNextNext, 
		isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem
		from nextRoutineItems t
		inner join SysRoutineItemLink l on l.Origin = t.IDProcessRoutineItemNext 
		inner join SysRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
		left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and t.IDRoutineItem = trr.IDRoutineItem 
		and trr.IDProcessRoutineItem = nxt.IDRoutineItem 
	), nextNextNextRoutineItems as
	(
		select t.IDRoutine, t.IDRoutineItem, trr.ID, trr.[Order], trr.Label, t.IDProcessRoutineItemNextNext, nxt.IDRoutineItem as IDProcessRoutineItemNextNextNext, 
		isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem
		from nextNextRoutineItems t
		inner join SysRoutineItemLink l on l.Origin = t.IDProcessRoutineItemNextNext
		inner join SysRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
		left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and t.IDRoutineItem = trr.IDRoutineItem 
		and trr.IDProcessRoutineItem = nxt.IDRoutineItem 
	), next4RoutineItems as
	(
		select t.IDRoutine, t.IDRoutineItem, trr.ID, trr.[Order], trr.Label, t.IDProcessRoutineItemNextNextNext, nxt.IDRoutineItem as IDProcessRoutineItemNext4, 
		isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem
		from nextNextNextRoutineItems t
		inner join SysRoutineItemLink l on l.Origin = t.IDProcessRoutineItemNextNextNext
		inner join SysRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
		left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and t.IDRoutineItem = trr.IDRoutineItem 
		and trr.IDProcessRoutineItem = nxt.IDRoutineItem 
	), allSameOperationTasks as
	(
		select * 
		from NextRoutineItems nr
		where VirtualNode = 0 and IDRoutine = @IDRoutine

		union all 

		select n2.IDRoutine, n2.IDRoutineItem, n2.ID, n2.[Order], n2.Label, n2.IDProcessRoutineItemNextNext,
		n2.VirtualNode, n2.ClosingItem
		from nextNextRoutineItems n2
		inner join nextRoutineItems n1 on n1.IDProcessRoutineItemNext = n2.IDProcessRoutineItemNext
		where n1.VirtualNode = 1 and n2.VirtualNode = 0 and n2.IDRoutine = @IDRoutine

		union all 

		select n3.IDRoutine, n3.IDRoutineItem, n3.ID, n3.[Order], n3.Label, n3.IDProcessRoutineItemNextNextNext,
		n3.VirtualNode, n3.ClosingItem
		from nextNextNextRoutineItems n3
		inner join nextNextRoutineItems n2 on n2.IDProcessRoutineItemNextNext = n3.IDProcessRoutineItemNextNext
		inner join nextRoutineItems n1 on n1.IDProcessRoutineItemNext = n2.IDProcessRoutineItemNext
		where n1.VirtualNode = 1 and n2.VirtualNode = 1 and n3.VirtualNode = 0 and n3.IDRoutine = @IDRoutine

		union all 

		select n4.IDRoutine, n4.IDRoutineItem, n4.ID, n4.[Order], n4.Label, n4.IDProcessRoutineItemNext4,
		n4.VirtualNode, n4.ClosingItem
		from next4RoutineItems n4
		inner join nextNextNextRoutineItems n3 on n3.IDProcessRoutineItemNextNextNext = n4.IDProcessRoutineItemNextNextNext
		inner join nextNextRoutineItems n2 on n2.IDProcessRoutineItemNextNext = n3.IDProcessRoutineItemNextNext
		inner join nextRoutineItems n1 on n1.IDProcessRoutineItemNext = n2.IDProcessRoutineItemNext
		where n1.VirtualNode = 1 and n2.VirtualNode = 1 and n3.VirtualNode = 1 and n4.VirtualNode = 0 and n4.IDRoutine = @IDRoutine
	), allSameOperationTasksWithTask as
	(
		select asot.*, ri.IDSysTask
		from allSameOperationTasks asot
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = asot.IDRoutineItem

	)
	insert into @tmp
	select *,0 
	from allSameOperationTasksWithTask;

	if (select count(*) from @tmp) = 0
	begin
		with currentTask as 
		(
			select IDRoutine, IDRoutineItem, ID, [Order], Label, IDProcessRoutineItem 
			from SysRoutineTeamRoleResource 
			where IDSysTaskProcess = @IDTask
		),nextOperationTask as 
		(
			select t.IDRoutine, nxt.IDRoutineItem, trr.ID, trr.[Order], trr.Label, ri.IDRoutineItem as IDProcessRoutineItemNext,
			isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem, ISNULL(nxt.IsPhase,0) IsPhase
			from currentTask t
			inner join SysOprRoutineItemLink l on l.Origin = t.IDRoutineItem 
			inner join SysOprRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
			left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and nxt.IDRoutineItem = trr.IDRoutineItem 
			and trr.[Order] = 1
			left join SysRoutineItem ri on ri.IDRoutineItem = trr.IDProcessRoutineItem
		), next2OperationTask as 
		(
			select t.IDRoutine, nxt.IDRoutineItem, trr.ID, trr.[Order], trr.Label, ri.IDRoutineItem as IDProcessRoutineItemNext, t.IDRoutineItem as IDRNxt,
			isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem, ISNULL(nxt.IsPhase,0) IsPhase
			from nextOperationTask t
			inner join SysOprRoutineItemLink l on l.Origin = t.IDRoutineItem 
			inner join SysOprRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
			left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and nxt.IDRoutineItem = trr.IDRoutineItem 
			and trr.[Order] = 1
			left join SysRoutineItem ri on ri.IDRoutineItem = trr.IDProcessRoutineItem
		), next3OperationTask as 
		(
			select t.IDRoutine, nxt.IDRoutineItem, trr.ID, trr.[Order], trr.Label, ri.IDRoutineItem as IDProcessRoutineItemNext, t.IDRoutineItem as IDRNxt2,
			isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem, ISNULL(nxt.IsPhase,0) IsPhase
			from next2OperationTask t
			inner join SysOprRoutineItemLink l on l.Origin = t.IDRoutineItem 
			inner join SysOprRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
			left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and nxt.IDRoutineItem = trr.IDRoutineItem 
			and trr.[Order] = 1
			left join SysRoutineItem ri on ri.IDRoutineItem = trr.IDProcessRoutineItem
		), next4OperationTask as 
		(
			select t.IDRoutine, nxt.IDRoutineItem, trr.ID, trr.[Order], trr.Label, ri.IDRoutineItem as IDProcessRoutineItemNext, t.IDRoutineItem as IDRNxt3,
			isnull(nxt.VirtualNode,0) VirtualNode, isnull(nxt.ClosingItem,0) ClosingItem, ISNULL(nxt.IsPhase,0) IsPhase
			from next3OperationTask t
			inner join SysOprRoutineItemLink l on l.Origin = t.IDRoutineItem 
			inner join SysOprRoutineItem nxt on nxt.IDRoutineItem = l.Destination 
			left join SysRoutineTeamRoleResource trr on t.IDRoutine = trr.IDRoutine and nxt.IDRoutineItem = trr.IDRoutineItem 
			and trr.[Order] = 1
			left join SysRoutineItem ri on ri.IDRoutineItem = trr.IDProcessRoutineItem
		), allNextOperationTasks as
		(
			select IDRoutine, IDRoutineItem, ID, [Order], Label, IDProcessRoutineItemNext,
			VirtualNode, ClosingItem, IsPhase
			from nextOperationTask 
			where VirtualNode = 0 and IDRoutine = @IDRoutine 

			union all 

			select n2.IDRoutine, n2.IDRoutineItem, n2.ID, n2.[Order], n2.Label, n2.IDProcessRoutineItemNext,
			n2.VirtualNode, n2.ClosingItem, n2.IsPhase
			from next2OperationTask n2
			inner join nextOperationTask n1 on n1.IDRoutineItem = n2.IDRNxt
			where n1.VirtualNode = 1 and n2.VirtualNode = 0 and n2.IDRoutine = @IDRoutine

			union all 

			select n3.IDRoutine, n3.IDRoutineItem, n3.ID, n3.[Order], n3.Label, n3.IDProcessRoutineItemNext,
			n3.VirtualNode, n3.ClosingItem, n3.IsPhase
			from next3OperationTask n3
			inner join next2OperationTask n2 on n2.IDRoutineItem = n3.IDRNxt2
			inner join nextOperationTask n1 on n1.IDRoutineItem = n2.IDRNxt
			where n1.VirtualNode = 1 and n2.VirtualNode = 1 and n3.VirtualNode = 0 and n3.IDRoutine = @IDRoutine

			union all 

			select n4.IDRoutine, n4.IDRoutineItem, n4.ID, n4.[Order], n4.Label, n4.IDProcessRoutineItemNext,
			n4.VirtualNode, n4.ClosingItem, n4.IsPhase
			from next4OperationTask n4
			inner join next3OperationTask n3 on n3.IDRoutineItem = n4.IDRNxt3
			inner join next2OperationTask n2 on n2.IDRoutineItem = n3.IDRNxt2
			inner join nextOperationTask n1 on n1.IDRoutineItem = n2.IDRNxt
			where n1.VirtualNode = 1 and n2.VirtualNode = 1 and n3.VirtualNode = 1 and n4.VirtualNode = 0 and n4.IDRoutine = @IDRoutine
		), allNextOperationTasksWithTasks as
		(
			select asot.IDRoutine, asot.IDRoutineItem, asot.ID, asot.[Order], Label, IDProcessRoutineItemNext,
			asot.VirtualNode, asot.ClosingItem, ri.IDSysTask, asot.IsPhase
			from allNextOperationTasks asot
			inner join SysOprRoutineItem ri on ri.IDRoutineItem = asot.IDRoutineItem
		)
		insert into @tmp
		select * from allNextOperationTasksWithTasks;
	end

	insert into @RET
	select distinct r.IDRoutine, ri.IDRoutineItem, t.Label, t.IDTask, 
	concat(concat(concat(MouldNo, case when (apv.AssetNumber is null or apv.AssetNumber = '' and r.IDAsset <> apvmould.IDAsset)  then '' else '_' end, apv.AssetNumber), case when apv.AssetNumber is null or apv.AssetNumber = '' then '_' else '_' end, ri.Description), case when t.ID IS not null and t.Label is not null and t.Label <> '' then CONCAT('[', t.Label ,']') else '' end) AssetMouldNumber,
	ri.IsPhase, '241A28AA-2DD2-481A-BFE0-86C800C45ED5'
	from @tmp t
	inner join SysOprRoutine r on r.IDRoutine = t.IDRoutine
	inner join SysOprRoutineItem ri on ri.IDRoutineItem = t.IDRoutineItem
	INNER JOIN Asset a ON r.IDAsset = a.IDAsset AND r.IDAssetModule = a.IDModule
	LEFT JOIN SysProductionPhaseKind pk on pk.ID = ri.IDPhaseTemplate
	INNER JOIN FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem and fup.IDModule = a.IDFollowUpItemModule
	INNER JOIN FollowUpItemMouldFields fupf on fupf.IDFollowUpItem = fup.IDFollowUpItem and fupf.IDModule = fup.IDModule
	INNER JOIN SS_AssetPartValues apv on apv.IDAsset = a.IDAsset
	INNER join SS_AssetPartValues apvMould on apvMould.IDAsset = fupf.IDAsset

	RETURN
END
GO


-- ----------------------------
-- function structure for GetProductsAllowAssetLinkTo
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetProductsAllowAssetLinkTo]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetProductsAllowAssetLinkTo]
GO

CREATE FUNCTION [dbo].[GetProductsAllowAssetLinkTo]
(	
	@idProduct int
)
RETURNS TABLE 
AS
RETURN 
(
	select productidrelated
	 from (
			 select  productid, productidrelated
			from products2products
			where tipo = 3
			union
			select productid, productid 
			from products
	 ) aux
	 where productid  = @idProduct
)
GO


-- ----------------------------
-- procedure structure for SS_CopyPart
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CopyPart]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CopyPart]
GO

CREATE PROCEDURE [dbo].[SS_CopyPart]
	-- Add the parameters for the stored procedure here
	@ObjectID uniqueidentifier,
	@MouldID uniqueidentifier,
	@PartName nvarchar(50),
	@CopyEletrodes bit,
	@MirrorX bit,
	@MirrorY bit,
	@CopyCAM bit,
	@LoginID uniqueidentifier=null,
	@GIDStr varbinary(MAX)=null out
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets fromf
	SET NOCOUNT ON;

	--Copiar dados de uma peça para um novo registo
	--Tabela de Objectos
	declare @ResultID uniqueidentifier;
	set @GidStr=null;
	--Validar que não existe nenhuma peça com este nome
	declare @existingID uniqueidentifier;
	set @existingID = (Select id from ss_object where mouldid=@mouldid and ShortName=@PartName)
	if @existingID is null
	begin
		Exec SS_SystemWFCreateObject @ResultID out
		set @GIDStr=convert(varbinary(max),concat(@GIDStr,@ResultID,';'));

		UPDATE o1    
			SET o1.copyfromid=@ObjectID, o1.copyeletrodes=@CopyEletrodes,
			o1.IDPartType=o2.idparttype,o1.IDRoutine=o2.idroutine,
			o1.DimMestra_XMin=o2.DimMestra_XMin,	o1.DimMestra_XMax=o2.DimMestra_XMax	,o1.DimMestra_YMin=o2.DimMestra_YMin	,o1.DimMestra_YMax=o2.DimMestra_YMax,
			o1.CopyMirrorX=@MirrorX,o1.CopyMirrory=@MirrorY,
			o1.DimReal_X=o2.DimReal_X, o1.DimReal_Y=o2.DimReal_Y, o1.DimReal_Z=o2.DimReal_Z,o1.DimBlock_X=o2.DimBlock_X, o1.DimBlock_Y=o2.DimBlock_Y, o1.DimBlock_Z=o2.DimBlock_Z,o1.DispBlock_X=o2.DispBlock_X, o1.DispBlock_Y=o2.DispBlock_Y, o1.DispBlock_Z=o2.DispBlock_Z,
			o1.TypeID=o2.TypeID,o1.MouldID=@MouldID,o1.ParentID=o2.ParentID,o1.ShortName=@PartName,o1.DimCAD_X=o2.DimCAD_X, o1.DimCAD_Y=o2.DimCAD_Y, o1.DimCAD_Z=o2.DimCAD_Z,
		o1.IDCMMBase=o2.IDCMMBase,o1.IDEDMBase=o2.IDEDMBase,o1.MestraZ=o2.MestraZ,o1.STLFileMILL=o2.STLFileMILL,o1.STLFileEDM=o2.STLFileEDM,o1.STLFileCMM=o2.STLFileCMM,o1.imagefile=o2.imagefile,o1.IdMILLBase=o2.idMillBase,o1.available=o2.available 
		from SS_Object o1
		INNER JOIN SS_Object o2	ON o2.id=@ObjectID
		where o1.id=@ResultID

		EXEC SS_AddObjectNote	@ResultID ,	-1 ,	1 ,	@LoginID	,	'Objecto criado.'
		update ss_object set fullname = dbo.SS_GetFullName(id) where id = @ResultID
		Exec SS_DeployOperations @ResultID


		--Copiar Eletrodos
		if (@CopyEletrodes=1) 
		begin
			declare @EletrodeID uniqueidentifier
			DECLARE lc CURSOR LOCAL
			FOR select id from ss_object where ParentID=@ObjectID;
			OPEN lc;
			FETCH NEXT FROM lc
				INTO  @EletrodeID;

			WHILE @@FETCH_STATUS = 0
			BEGIN
				--Programs
				--Se for para copiar os eletrodos todos da peça original
				declare @CreateEletrodeID uniqueidentifier
				--Verificar se este eletrodo já existe
				set @CreateEletrodeID= null
				Select @CreateEletrodeID=id  from ss_object where CopyFromID=@EletrodeID and ParentID=@ResultID

				if @CreateEletrodeID is null
				begin
					declare @gap float
					declare @EletrodeFamily int
					select @GAP=gap,@EletrodeFamily=EletrodeFamily from SS_Eletrode where id=@EletrodeID
					--Copia Eletrodo
					exec [dbo].[SS_CopyEletrode] @EletrodeID, @GAP, @EletrodeFamily, 1, 1, @LoginID, @ResultID,null,@MirrorX,@MirrorY,1,@CopyCAM,@CreateEletrodeID out
					set @GIDStr=convert(varbinary(max),concat(@GIDStr,@CreateEletrodeID,';'));
				end;

				FETCH NEXT FROM lc
				INTO @EletrodeID;
			END;
	
			CLOSE lc;
			DEALLOCATE lc;					
		end


		declare @MultMirrX int;
		declare @MultMirrY int;
		set @MultMirrX=1;
		set @MultMirrY=1;

		if (@MirrorX is not null) and (@MirrorX=1)
			set @MultMirrX=-1;

		if (@MirrorY is not null) and (@MirrorY=1)
			set @MultMirrY=-1;	

		--Copiar programas
	Create Table #IDList (
		OldProgramID uniqueidentifier,
		NewProgramID uniqueidentifier
	);
		declare @programid uniqueidentifier

		Declare @NewProgramID uniqueidentifier
		Declare @ProgramKind int
		DECLARE lc2 CURSOR LOCAL
		FOR select id,kind,toolid from ss_program where IDObject=@ObjectID and (idjob is null) order by ordem asc;
		OPEN lc2;
		FETCH NEXT FROM lc2
			INTO  @ProgramID,@ProgramKind,@EletrodeID;

		WHILE @@FETCH_STATUS = 0
		BEGIN
			--Programs
			--Se for para copiar os eletrodos todos da peça original
			
			set @NewProgramID=newID();
			insert into #IDList values (@programid,@NewProgramID);
			declare @MyEletrodeRef uniqueidentifier
			set @MyEletrodeRef=null

				--Verificar se este eletrodo já existe
				Select @MyEletrodeRef=id  from ss_object where CopyFromID=@EletrodeID and ParentID=@ResultID

			if @CopyCAM=1 
			begin
				insert into SS_Program (id,active,Code,Ordem, Kind, ToolID,FilePath,IDObject,position,programtype,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,
					EstimatedTime,ParentID,HasChilds) 
				select @NewProgramID,1,code,Ordem,kind,isnull(@MyEletrodeRef,toolid),FilePath,@ResultID,position ,programtype,
					PX*@MultMirrX,Py*@MultMirrY,PZ,PA,PB,PC,PXIni*@MultMirrX,PYIni*@MultMirry,PZIni,PAIni,PBIni,PCIni,VectorI*@MultMirrX,VectorJ*@MultMirrY,VectorK,
					EstimatedTime,(Select NewProgramID from #IDList where OldProgramID=ParentID),HasChilds from ss_program where id=@programid;
			
			

				--MIll programs
				insert into SS_MILLProgram(ID,	Feed,Spindle,FactorFeed,FactorSpindle,Tool,TCode,HolderCode,
							TD,TR,TH,TAD,TZ,Tol,Strategy,StkFin,XMin,XMax,YMin,YMax,ZMin,ZMax,PIniZG01,
							LookAheadUse,SplitCondition,ProgramStartLine,NumProgInFile,FileModificationDate) 
					select @NewProgramID,Feed,Spindle,FactorFeed,FactorSpindle,Tool,TCode,HolderCode,
							TD,TR,TH,TAD,TZ,Tol,Strategy,StkFin,XMin,XMax,YMin,YMax,ZMin,ZMax,PIniZG01,
							LookAheadUse,SplitCondition,ProgramStartLine,NumProgInFile,FileModificationDate from SS_MILLProgram where id=@ProgramID ;
			end
			else
			begin
				insert into SS_Program (id,active,Code,Ordem, Kind, ToolID,FilePath,IDObject,position,programtype,
					PX,PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,
					EstimatedTime,ParentID,HasChilds) 
				select @NewProgramID,1,code,Ordem,kind,isnull(@MyEletrodeRef,toolid),FilePath,@ResultID,position ,programtype,
					PX*@MultMirrX,Py*@MultMirrY,PZ,PA,PB,PC,PXIni*@MultMirrX,PYIni*@MultMirry,PZIni,PAIni,PBIni,PCIni,VectorI*@MultMirrX,VectorJ*@MultMirrY,VectorK,
					EstimatedTime,ParentID,HasChilds from ss_program where id=@programid and kind<>2;
					
			end

			--EDM programs
			insert into SS_edmPoint(ID,IDTechnology, TechnologyText, IDEletrodeType, IsTemplatePoint ) 
				select @NewProgramID, IDTechnology, TechnologyText, IDEletrodeType, IsTemplatePoint from SS_edmPoint where id=@programid;

			--CMM points
			insert into ss_cmmpoint (ID, PointXExp, PointYExp, PointZExp, PointXIniExp, PointYIniExp, PointZIniExp,PointRAExp,PointRCExp) 
				select @NewProgramID, PointXExp, PointYExp, PointZExp, PointXIniExp, PointYIniExp, PointZIniExp,PointRAExp,PointRCExp from ss_cmmpoint where id=@programid;

			-- Falta o copiar de eletrodes se o link =0
			FETCH NEXT FROM lc2
			INTO @ProgramID,@ProgramKind,@EletrodeID;
		END;
		
		CLOSE lc2;
		DEALLOCATE lc2;

	end
drop table #IDList;
END


SET ANSI_NULLS ON
GO


