CREATE PROCEDURE [dbo].[DocumentLinesForPrint]
	@idDocument int,
	@kind int
AS
BEGIN
	SET NOCOUNT ON;

	selecT*
	from documentline
	where IDRegister = @idDocument 
	order by GridOrder
	return

	declare @lineNumber nvarchar(50), @product_name nvarchar(max), @qty decimal(18,5)
	declare @unit_price decimal(18,5), @net_total decimal(18,5), @lineDepth int
	declare @ID int, @IDParent int

	declare  @DocumentLinesTable table (
		ID int not null, 

		printKind int null,
		CCount int null,
		GCCount int null,

		[GridOrder] [int] NULL,
		[LineDepth] [int] NULL,
		[IDParent] [int] NULL,
		[IDRegister] [int] NOT NULL,
		[IDRegisterLink] [int] NULL,
		[dbmask] [int] NULL,
		[ModuleCode] [nvarchar](50) NULL,
		[p_unit_price] [decimal](18, 5) NULL,
		[unit_price] [decimal](18, 5) NULL,
		[assetid] [int] NULL,
		[productid] [int] NULL,
		[product_code] [nvarchar](100) NULL,
		[product_name] [nvarchar](max) NULL,
		[qty] [decimal](18, 5) NULL,
		[cost_price] [decimal](18, 5) NULL,
		[maint_price] [decimal](18, 5) NULL,
		[maint_cost_price] [decimal](18, 5) NULL,
		[net_total] [decimal](18, 5) NULL,
		[discount_perc_3] [decimal](18, 5) NULL,
		[discount_perc_2] [decimal](18, 5) NULL,
		[discount_perc] [decimal](18, 5) NULL,
		[vat_perc] [decimal](18, 5) NULL,
		[discount_eur] [decimal](18, 5) NULL,
		[market_price] [decimal](18, 5) NULL,
		[LineLink] [int] NULL,
		--[IsTemplate] [bit] NOT NULL,
		--[TemplateCode] [nvarchar](250) NULL,
		[LinkReferenceLine] [int] NULL,
		[LinkReferenceField] [int] NULL,
		[ModifiedTime] [datetime] NULL,
		[CreatedTime] [datetime] NULL,
		[ExchangeID] [nvarchar](max) NULL,
		[vat_amount] [decimal](18, 5) NULL,
		[VatRate0] [decimal](18, 5) NULL,
		[VatRate1] [decimal](18, 5) NULL,
		[VatRate2] [decimal](18, 5) NULL,
		[VatRate3] [decimal](18, 5) NULL,
		--[RegisterStatus] [int] NOT NULL,
		[percExec] [decimal](18, 5) NULL,
		[percValue] [decimal](18, 5) NULL,
		[ValorCIva] [decimal](18, 5) NULL,
		[roundvalue] [decimal](18, 5) NULL,
		[valorfinal] [decimal](18, 5) NULL,
		[totalIva] [decimal](18, 5) NULL,
		[DefaultDimensionLines] [int] NULL,
		[PendingID] [int] NULL,
		[LineType] [int] NULL,
		--[RegisterSysStatus] [int] NOT NULL,
		--[Balance] [numeric](18, 5) NOT NULL,
		--[PaymentValue] [numeric](18, 5) NOT NULL,
		--[PaymentPercent] [numeric](18, 5) NOT NULL,
		--[PaymentOriginalValue] [numeric](18, 5) NOT NULL,
		--[Closed] [bit] NOT NULL,
		[PaymentPrevDate] [datetime] NULL,
		--[IDModule] [uniqueidentifier] NOT NULL,
		--[IDModuleLink] [uniqueidentifier] NULL,
		[IDUserCreation] [uniqueidentifier] NULL,
		[IDUser] [uniqueidentifier] NULL,
		[IDRoleCreation] [uniqueidentifier] NULL,
		[IDRole] [uniqueidentifier] NULL,
		[IDRoleAssign] [uniqueidentifier] NULL,
		--[KindTransaction] [int] NOT NULL,
		[vat_code] [int] NULL,
		[asset_serial] [nvarchar](200) NULL,
		[PendingType] [uniqueidentifier] NULL,
		[group_discount_type] [int] NULL,
		[discount_calc_type] [int] NULL,
		[productidModule] [uniqueidentifier] NULL,
		[Propagation] [int] NULL,
		[lineNumber] [nvarchar](50) NULL,
		[Kind] [int] NOT NULL
	)

	declare  @DocumentLinesTmp table (
		ID int not null, 

		printKind int null,
		CCount int null,
		GCCount int null,

		[GridOrder] [int] NULL,
		[LineDepth] [int] NULL,
		[IDParent] [int] NULL,
		[IDRegister] [int] NOT NULL,
		[IDRegisterLink] [int] NULL,
		[dbmask] [int] NULL,
		[ModuleCode] [nvarchar](50) NULL,
		[p_unit_price] [decimal](18, 5) NULL,
		[unit_price] [decimal](18, 5) NULL,
		[assetid] [int] NULL,
		[productid] [int] NULL,
		[product_code] [nvarchar](100) NULL,
		[product_name] [nvarchar](max) NULL,
		[qty] [decimal](18, 5) NULL,
		[cost_price] [decimal](18, 5) NULL,
		[maint_price] [decimal](18, 5) NULL,
		[maint_cost_price] [decimal](18, 5) NULL,
		[net_total] [decimal](18, 5) NULL,
		[discount_perc_3] [decimal](18, 5) NULL,
		[discount_perc_2] [decimal](18, 5) NULL,
		[discount_perc] [decimal](18, 5) NULL,
		[vat_perc] [decimal](18, 5) NULL,
		[discount_eur] [decimal](18, 5) NULL,
		[market_price] [decimal](18, 5) NULL,
		[LineLink] [int] NULL,
		--[IsTemplate] [bit] NOT NULL,
		--[TemplateCode] [nvarchar](250) NULL,
		[LinkReferenceLine] [int] NULL,
		[LinkReferenceField] [int] NULL,
		[ModifiedTime] [datetime] NULL,
		[CreatedTime] [datetime] NULL,
		[ExchangeID] [nvarchar](max) NULL,
		[vat_amount] [decimal](18, 5) NULL,
		[VatRate0] [decimal](18, 5) NULL,
		[VatRate1] [decimal](18, 5) NULL,
		[VatRate2] [decimal](18, 5) NULL,
		[VatRate3] [decimal](18, 5) NULL,
		--[RegisterStatus] [int] NOT NULL,
		[percExec] [decimal](18, 5) NULL,
		[percValue] [decimal](18, 5) NULL,
		[ValorCIva] [decimal](18, 5) NULL,
		[roundvalue] [decimal](18, 5) NULL,
		[valorfinal] [decimal](18, 5) NULL,
		[totalIva] [decimal](18, 5) NULL,
		[DefaultDimensionLines] [int] NULL,
		[PendingID] [int] NULL,
		[LineType] [int] NULL,
		--[RegisterSysStatus] [int] NOT NULL,
		--[Balance] [numeric](18, 5) NOT NULL,
		--[PaymentValue] [numeric](18, 5) NOT NULL,
		--[PaymentPercent] [numeric](18, 5) NOT NULL,
		--[PaymentOriginalValue] [numeric](18, 5) NOT NULL,
		--[Closed] [bit] NOT NULL,
		--[PaymentPrevDate] [datetime] NULL,
		--[IDModule] [uniqueidentifier] NOT NULL,
		--[IDModuleLink] [uniqueidentifier] NULL,
		[IDUserCreation] [uniqueidentifier] NULL,
		[IDUser] [uniqueidentifier] NULL,
		[IDRoleCreation] [uniqueidentifier] NULL,
		[IDRole] [uniqueidentifier] NULL,
		[IDRoleAssign] [uniqueidentifier] NULL,
		--[KindTransaction] [int] NOT NULL,
		[vat_code] [int] NULL,
		[asset_serial] [nvarchar](200) NULL,
		[PendingType] [uniqueidentifier] NULL,
		[group_discount_type] [int] NULL,
		[discount_calc_type] [int] NULL,
		[productidModule] [uniqueidentifier] NULL,
		[Propagation] [int] NULL,
		[lineNumber] [nvarchar](50) NULL,
		[Kind] [int] NOT NULL
	)
	
	insert into @DocumentLinesTmp([ID],[GridOrder],[LineDepth],[IDParent],[IDRegister],[IDRegisterLink],[dbmask],[ModuleCode]
      ,[p_unit_price],[unit_price],[assetid],[productid],[product_code],[product_name],[qty],[cost_price],[maint_price]
      ,[maint_cost_price],[net_total],[discount_perc_3],[discount_perc_2],[discount_perc],[vat_perc],[discount_eur],[market_price]
      ,[LineLink],[LinkReferenceLine],[LinkReferenceField],[ModifiedTime],[CreatedTime],[ExchangeID]
      ,[vat_amount],[VatRate0],[VatRate1],[VatRate2],[VatRate3],[percExec],[percValue],[ValorCIva],[roundvalue]
      ,[valorfinal],[totalIva],[DefaultDimensionLines],[PendingID],[LineType],[IDUserCreation],[IDUser]
      ,[IDRoleCreation],[IDRole],[IDRoleAssign],[vat_code],[asset_serial],[PendingType],[group_discount_type],[discount_calc_type]
      ,[productidModule],[Propagation],[lineNumber], [Kind])
	SELECT [ID],[GridOrder],[LineDepth],[IDParent],[IDRegister],[IDRegisterLink],[dbmask],[ModuleCode]
      ,[p_unit_price],[unit_price],[assetid],[productid],[product_code],[product_name],[qty],[cost_price],[maint_price]
      ,[maint_cost_price],[net_total],[discount_perc_3],[discount_perc_2],[discount_perc],[vat_perc],[discount_eur],[market_price]
      ,[LineLink],[LinkReferenceLine],[LinkReferenceField],[ModifiedTime],[CreatedTime],[ExchangeID]
      ,[vat_amount],[VatRate0],[VatRate1],[VatRate2],[VatRate3],[percExec],[percValue],[ValorCIva],[roundvalue]
      ,[valorfinal],[totalIva],[DefaultDimensionLines],[PendingID],[LineType],[IDUserCreation],[IDUser]
      ,[IDRoleCreation],[IDRole],[IDRoleAssign],[vat_code],[asset_serial],[PendingType],[group_discount_type],[discount_calc_type]
      ,[productidModule],[Propagation],[lineNumber], [Kind]
	FROM DocumentLine
	WHERE (@kind = -1 OR Kind = @kind OR LineDepth = 0) AND IDRegister = @idDocument
	ORDER BY GridOrder;

	declare  DocumentLinesForPrint_IT cursor for
		select Id, IDParent, lineNumber, product_name, qty, unit_price, net_total, LineDepth
		from @DocumentLinesTmp
		-- where LineDepth > 0
		ORDER BY GridOrder;

	open DocumentLinesForPrint_IT;
	
	fetch next from DocumentLinesForPrint_IT 
	into @Id, @IDParent, @lineNumber, @product_name, @qty, @unit_price, @net_total, @lineDepth ;

	declare @current_lineDepth int
	declare @CCount int, @GCCount int
	declare @lastParent int
		
	set @current_lineDepth = -1
	set @lastParent = NULL

	declare  @grpStack table (
		seq int not null identity(1,1),
		ID int not null
	)

	while @@FETCH_STATUS = 0
	begin
		declare @printKind int
		set @printKind = 0

		IF @current_lineDepth > @lineDepth
		begin
			-- detect need for sum row
			-- delete @lastParent from @grpStack
			-- set lastParent to @grpStack MAX

			-- pop all lastParents from grpStack
			-- until top of stack is idparent of this row

			while @lastParent != @IDParent or @lastParent is null
			begin
				delete from @grpStack where ID = @lastParent
				
				INSERT INTO @DocumentLinesTable(ID, printKind, product_name, qty, unit_price, net_total, LineDepth, kind, IDRegister)
				select 0, 1, product_name, qty, unit_price, net_total, LineDepth, Kind, IDRegister
				from @DocumentLinesTmp
				where ID = @lastParent

				set @lastParent = (select ID from @grpStack where seq = (select max(seq) from @grpStack))
			end
		end

		SELECT @CCount = count(*) FROM @DocumentLinesTmp WHERE IDParent = @ID
		SELECT @GCCount = count(*) FROM @DocumentLinesTmp WHERE IDParent IN (SELECT ID FROM @DocumentLinesTmp WHERE IDParent = @ID)

		IF @CCount > 0
		begin
			set @lastParent = @ID
			insert into @grpStack(ID) values (@ID)

			set @printKind = 2
		end

		INSERT INTO @DocumentLinesTable(Id, IDParent, printKind, lineNumber, product_name, qty, unit_price, net_total, LineDepth, CCount, GCCount, kind, idregister)
		VALUES(@Id, @IDParent, @printKind, @lineNumber, @product_name, @qty, @unit_price, @net_total, @lineDepth, @CCount, @GCCount, @kind, @idDocument)
		
		SET @current_lineDepth = @lineDepth

		FETCH NEXT FROM DocumentLinesForPrint_IT 
		INTO @Id, @IDParent, @lineNumber, @product_name, @qty, @unit_price, @net_total, @lineDepth ;
				
	END

	-- Close all open groups
	while not @lastParent is null
	begin
		delete from @grpStack where ID = @lastParent

		INSERT INTO @DocumentLinesTable(ID, printKind, product_name, qty, unit_price, net_total, LineDepth, kind, idregister)
		select 0, 1, product_name, qty, unit_price, net_total, LineDepth, @kind, @idDocument
		from @DocumentLinesTmp
		where ID = @lastParent

		set @lastParent = (select ID from @grpStack where seq = (select max(seq) from @grpStack))
	end

	CLOSE DocumentLinesForPrint_IT;
	DEALLOCATE DocumentLinesForPrint_IT;

	--SELECT*
	--FROM DocumentLine
	--WHERE (@kind = -1 OR Kind = @kind) AND IDRegister = @idDocument
	--ORDER BY GridOrder;
	
	SELECT*
	FROM @DocumentLinesTable
END
GO


