CREATE FUNCTION [dbo].[GetNexTasksForTaskProductionStr]
(
	@IDTask uniqueidentifier
)
RETURNS nvarchar(MAX)
AS
BEGIN
	RETURN(
		select STUFF ((
		select distinct ', ' + assetmouldNumber
		from GetNexTasksForTaskProduction(@IDTask)
