-- ----------------------------
-- procedure structure for SS_CreateNewBlank
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CreateNewBlank]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CreateNewBlank]
GO

CREATE PROCEDURE [dbo].[SS_CreateNewBlank]
	-- Add the parameters for the stored procedure here
	@BlankKind uniqueidentifier,
	@ShortName nvarchar (50),
    @DimBlock_X float,
	@DimBlock_Y float,
	@DimBlock_Z float,
    @DispBlock_X float,
	@DispBlock_Y float,
	@DispBlock_Z float,	
	@PartTypeGID uniqueidentifier,
	@PartRoutineGID uniqueidentifier,
	@HolderKindGID uniqueidentifier,
	@HolderGID uniqueidentifier,
	@RotC float,
	@ResultID uniqueidentifier OUTPUT,
	@LoginID uniqueidentifier =null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @NewID uniqueidentifier;
	declare @Count int
	declare @idmaterial uniqueidentifier;
	
	declare @fullname nvarchar(50)
	Select @idmaterial=idmaterial,@ShortName=code,@Count=isnull(counter,1) from SM_BlankTemplate where id=@BlankKind
	update SM_BlankTemplate set counter=isnull(counter,1) +1 where  id=@BlankKind

	set @ShortName=@ShortName+ '('+cast(@count as nvarchar(5))+')'

	set @fullname=@ShortName;

	--Novo Registo de eletrodo-------------------------
	Exec SS_SystemWFCreateObject @ResultID out

	if @PartTypeGID is null
		set @PartTypeGID = (Select DefaultPartType from SS_ObjectType o where  o.SystemBehaviour=4)
	if @PartRoutineGID is null
		set @PartRoutineGID= (Select p.IDPartRoutine  from SysPartType p where ID=@PartTypeGID)

	UPDATE SS_Object 
	SET TypeID=524288,ShortName=@ShortName,fullname = @fullname,available=1,DispBlock_X=@DispBlock_X, DispBlock_Y=@DispBlock_Y, DispBlock_Z=@DispBlock_Z,IDPartType=@PartTypeGID,IDRoutine=@PartRoutineGID,
		DimBlock_X=@DimBlock_X, DimBlock_Y=@DimBlock_Y, DimBlock_Z=@DimBlock_Z	,MILLRC=@RotC,BlankTemplateID=@BlankKind,idmaterial=@idmaterial
		,IDHolder=@HolderGID,IDMillBase=@HolderKindGID
	where id=@ResultID;

	Exec SS_DeployOperations @ResultID

	--Constroi nome no trigger
	exec SS_AddObjectNote 	@ResultID,	1,1,@LoginID,'Blank Created'	
				--

	update np
	set np.code=o.shortname,np.name=o.fullname
	from SM_nodePart np
	left join ss_object o on o.id=np.id
	where np.id=@ResultID

	----------------------------
END
GO


-- ----------------------------
-- function structure for GetTaskFollowing
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTaskFollowing]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTaskFollowing]
GO

CREATE FUNCTION [dbo].[GetTaskFollowing]
(
	@IDTask uniqueidentifier,
	@IDOwnResource uniqueidentifier
)
RETURNS int
AS
BEGIN
	declare @ret int = 0

	if @IDTask = '00000000-0000-0000-0000-000000000000'
	begin
		set @ret = 2
	end
	else
	begin
		declare @test table (
			idResource uniqueidentifier null
		)

		insert into @test(idResource)
		select idResource from [SysTaskResourceRole] aux with(nolock) where aux.IDTask = @IDTask and aux.kind = 1

		if (exists(select top 1 1 from @test))
		begin
			set @ret = 1
			if (exists(select top 1 1 from @test where idResource = @IDOwnResource))
			begin
				set @ret = 2
			end
		end
	end
	return @ret

END
GO


