-- function structure for GetActivityAssigning
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetActivityAssigning]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetActivityAssigning]
GO

CREATE FUNCTION [dbo].[GetActivityAssigning]
(
	@IDActivity int,
	@IDOwn uniqueidentifier,
	@IDOwnResource uniqueidentifier
)
RETURNS int
AS
BEGIN
	declare @ret int = 0

	declare @test table (
		idResource uniqueidentifier null,
		IDUser uniqueidentifier null,
		IDActivityRole uniqueidentifier null,
		TeamMask01 bigint null,
		TeamMask02 bigint null
	)
	
	insert into @test(idResource, iduser, idActivityRole, TeamMask01, TeamMask02)
	select idResource, iduser, idActivityRole, TeamMask01, TeamMask02
	from SysActivityResourceRoleActivity aux with(nolock) where aux.IDActivity = @IDActivity

	if (exists (select 1 from @test where (not IDResource is null or not IDUser is null)))
	begin
		set @ret = 1
		if (exists (select 1 
                    from @test 
                    where (IDUser = @IDOwn OR dbo.TestResourceWithTriplet(@IDOwnResource, IDResource, IDActivityRole, TeamMask01, TeamMask02, 1) = 1) ))
		begin
			set @ret = 2
		end
	end
	
	return @ret
END
GO


-- ----------------------------
-- procedure structure for ValidateLocksAndZombies
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ValidateLocksAndZombies]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ValidateLocksAndZombies]
GO

CREATE PROCEDURE [dbo].[ValidateLocksAndZombies]
    @IDDocument INT,
    @IDModule NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate active locks
    WITH ActiveLocks AS (
        SELECT lr.*,
               CASE
                   WHEN d.IDDocument IS NOT NULL THEN CONCAT('n� ', d.doc_ref, ' ', CONVERT(NVARCHAR(50), d.doc_date, 105), ' ', d.[subject])
                   WHEN fup.IDFollowUpItem IS NOT NULL THEN CONCAT('n� ', fup.Code, ' ', CONVERT(NVARCHAR(50), fup.CreationDate, 105), ' ', fup.[Name])
                   WHEN dl.productid IS NOT NULL THEN p.productname
                   WHEN dl2.IDRegisterLink IS NOT NULL THEN p.productname
                   ELSE NULL
               END AS title
        FROM SysLockRecord lr
        LEFT JOIN document d ON lr.IDModule = d.IDModule AND lr.IDRecord = CAST(d.IDDocument AS NVARCHAR(50)) AND d.IDDocument = @IDDocument AND d.IDModule = @IDModule
        LEFT JOIN FollowUpItem fup ON lr.IDModule = fup.IDModule AND lr.IDRecord = CAST(fup.IDFollowUpItem AS NVARCHAR(50)) AND fup.IDFollowUpItem = @IDDocument AND fup.IDModule = @IDModule
        LEFT JOIN DocumentLine dl ON lr.IDModule = dl.productidModule AND lr.IDRecord = CAST(dl.productid AS NVARCHAR(50)) AND dl.IDRegister = @IDDocument AND dl.IDModule = @IDModule
        LEFT JOIN products p ON dl.productidModule = p.IDModule AND dl.productid = p.productid
        LEFT JOIN DocumentLine dl2 ON lr.IDModule = dl2.IDModuleLink AND lr.IDRecord = CAST(dl2.IDRegisterLink AS NVARCHAR(50)) AND dl2.IDRegister = @IDDocument AND dl2.IDModule = @IDModule
        WHERE lr.[Status] = 1
    )
    SELECT * FROM ActiveLocks WHERE title IS NOT NULL;

    -- Validate zombie locks
    WITH ZombieLocks AS (
        SELECT CONCAT('n� ', d.doc_ref, ' ', CONVERT(NVARCHAR(50), d.doc_date, 105), ' ', d.[subject]) AS title
        FROM document d
        WHERE d.IDDocument = @IDDocument AND d.IDModule = @IDModule AND RegisterStatus = 3
        UNION ALL
        SELECT CONCAT('n� ', fup.Code, ' ', CONVERT(NVARCHAR(50), fup.CreationDate, 105), ' ', fup.[Name]) AS title
        FROM FollowUpItem fup
        WHERE fup.IDFollowUpItem = @IDDocument AND fup.IDModule = @IDModule AND RegisterStatus = 3
        UNION ALL
        SELECT p.productname AS title
        FROM DocumentLine dl
        INNER JOIN products p ON dl.productidModule = p.IDModule AND dl.productid = p.productid
        WHERE dl.IDRegister = @IDDocument AND dl.IDModule = @IDModule AND p.RegisterStatus = 3
        UNION ALL
        SELECT p.productname AS title
        FROM DocumentLine dl2
        INNER JOIN products p ON dl2.IDModuleLink = p.IDModule AND dl2.IDRegisterLink = p.productid
        WHERE dl2.IDRegister = @IDDocument AND dl2.IDModule = @IDModule AND p.RegisterStatus = 3
    )
    SELECT * FROM ZombieLocks;

		SELECT dd.IDDocument, dd.registerStatus as statusDoc,pld.LineLink, pl.Id ,pld.ID as xxx, pl.* 
	FROM DocumentLine pl
	INNER JOIN Document d on d.IdDocument = pl.IdRegister and pl.IDModule = d.IDModule
	INNER JOIN DocumentLine pld on pld.LineLink = pl.Id  
	INNER JOIN Document dd on dd.IdDocument = pld.IDRegister and pld.IDModule = dd.IDModule 
	WHERE d.iddocument =  @IDDocument 
	and dd.registerStatus <> 0 and dd.registerStatus <> 4 and dd.registerStatus <> 3
END;
GO


-- ----------------------------
-- procedure structure for SS_DeleteEletrodeEDMPoints
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_DeleteEletrodeEDMPoints]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_DeleteEletrodeEDMPoints]
GO

CREATE PROCEDURE [dbo].[SS_DeleteEletrodeEDMPoints]
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@Family nvarchar(50),
	@Instance int,
	@Pos int,
	@EDMClient nvarchar(50),
	@EDMMouldName nvarchar(50),
	@EDMPartOf nvarchar (50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @ToolID uniqueidentifier;
	declare @PartID uniqueidentifier;
	set @PartID= (Select top 1 id from dbo.SS_GetObjectIDByParams(@EDMMouldName,@EDMPartOf,null,NULL,NULL,NULL,NULL,NULL,NULL,@EDMClient,default));


	 	DECLARE LocalCursor2 CURSOR LOCAL
		FOR select id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,@Instance,@Family,NULL,NULL,NULL,@Client,default);
		OPEN LocalCursor2;
		FETCH NEXT FROM LocalCursor2
			INTO  @ToolID;

		WHILE @@FETCH_STATUS = 0
		BEGIN
			-- Insert statements for procedure here
			Delete from SS_EDMPoint where id in (Select id from ss_program where toolid=@ToolID and kind=dbo.EDMKind()  and IDObject=@PartID and (idjob is null) and (@Pos is null or @Pos=Position));
			delete from ss_program where toolid=@ToolID  and (idjob is null) and kind=dbo.EDMKind() and idobject=@PartID  and (@Pos is null or @Pos=Position);

			FETCH NEXT FROM LocalCursor2
			INTO @ToolID;
		END;
		
		CLOSE LocalCursor2;
		DEALLOCATE LocalCursor2;
END



SET ANSI_NULLS ON
GO


-- ----------------------------
-- function structure for GetCanStartTaskProduction
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetCanStartTaskProduction]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetCanStartTaskProduction]
GO

CREATE FUNCTION [dbo].[GetCanStartTaskProduction]
(
	@IDTask uniqueidentifier
)
RETURNS int
AS
BEGIN

	declare @IsProduction int = dbo.GetIsTaskProduction(@IDTask);
	declare @PhaseLocked int = isnull((select top 1 ri.PhaseLocked
	from SysTaskProductionValues tpv 
	inner join SysOprRoutineItem ri on ri.IDRoutineItem = tpv.IDSysOprRoutineItem
	where tpv.IDTask = @IDTask
	),0); 

	return case 
		when @IsProduction = 0 then 1
		when @IsProduction = 1 and @PhaseLocked = 0 then 1
		else 0
	end
END
GO


