-- procedure structure for SS_DeleteObject
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_DeleteObject]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_DeleteObject]
GO

CREATE PROCEDURE [dbo].[SS_DeleteObject]
	-- Add the parameters for the stored procedure here
	@ObjectID uniqueidentifier
AS
BEGIN
	declare @Fullname nvarchar(300);
	set @Fullname=(Select fullname from ss_object where id=@ObjectID);
	set @Fullname='Deleted '+@Fullname;

	insert into [dbo].[SS_ObjectNotes] ( IDObject, IDLogin, IDOperation,note,  ReadOnly,data,NoteKind)
		values ( null, null, null, @Fullname, 0,getdate(),0);


	--Apagar dos Nodes
	delete from Operations where idrecord=@ObjectID;
	delete from SM_NodePart where id =@ObjectID;
	update SM_NodePosic set 
		IDNodePartDocked= null, 
		NodePartDockedCode=null,
		NodePartDockedKindMask1=null,
		NodePartDockedKindMask2=null,
		NodePartDockedName=null
	where IDNodePartDocked=@ObjectID


	--Apagar restante info

	Delete from dbo.SS_Eletrode where id=@ObjectID;
	Delete from dbo.SS_Object where id=@ObjectID;
	dELETE from dbo.SS_Mould where id=@objectid;


	CREATE TABLE #ProgID
	(
	   ID uniqueidentifier
	)

	INSERT INTO #ProgID SELECT ID from ss_program where IDObject=@objectid or toolid=@objectid

	delete from SS_MILLProgram where id in (select id from #ProgID )
	delete from SS_CMMPoint where id in (select id from #ProgID )
	--delete from SS_CMMResult where id in (select id from ss_program where IDObject=@objectid or toolid=@objectid)
	delete from SS_EDMPoint where id in (select id from #ProgID )
	delete from SS_MILLCycles where id in (select id from #ProgID )

	delete from ss_program where ID IN (select id from #ProgID )
		
	DROP TABLE #ProgID


	delete from SS_ObjectFiles where ObjectID=@ObjectID;
	delete from SS_ObjectPosition where IDObject=@ObjectID;


	CREATE TABLE #RotID
	(
	   ID uniqueidentifier
	)

	INSERT INTO #RotID SELECT IDRoutine FROM SysOprRoutine WHERE PartID = @ObjectID

	

	--- Part Routine
	delete from SysOprRoutineVarsRelation WHERE IDSysRoutine IN (SELECT ID FROM #RotID);
	delete from SysOprRoutineVar  WHERE IDRoutine IN (SELECT ID FROM #RotID);
	delete from SysOprRoutineCursorConditions WHERE IDSysRoutine IN (SELECT ID FROM #RotID);
	delete from SysOprRoutineCursor WHERE IDSysRoutine IN (SELECT ID FROM #RotID);
	delete from SysOprRoutineItemLink WHERE IDRoutine IN (SELECT ID FROM #RotID);
	delete from SysOprRoutineItem WHERE IDRoutine IN (SELECT ID FROM #RotID);	
	delete from SysOprRoutine WHERE IDRoutine IN (SELECT ID FROM #RotID);

	DROP TABLE #RotID

	CREATE TABLE #ReqID
	(
	   ID uniqueidentifier
	)

	INSERT INTO #ReqID SELECT ID FROM SysPrRoutineRequest WHERE IDPart = @ObjectID

	

	delete from SysPrRoutineCursorConditions WHERE IDRequest IN (select id from #ReqID )
	delete from SysPrRoutineCursor WHERE IDRequest IN (select id from #ReqID )
	delete from SysPrRoutineVar WHERE IDRequest IN (select id from #ReqID )
	delete from SysPrRoutineResourcePositions WHERE IDRequest IN (select id from #ReqID )
	delete from SysPrRoutineRequest WHERE ID IN (select id from #ReqID ) 
	
	DROP TABLE #ReqID

	DECLARE LocalCursor CURSOR LOCAL 
	FOR select id from SS_Object where ParentID=@ObjectID or MouldID=@ObjectID
	DECLARE @ChildID uniqueidentifier
	OPEN LocalCursor;
	FETCH NEXT FROM LocalCursor
		INTO @CHILDID;
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXEC SS_DeleteObject @ChildID			
		FETCH NEXT FROM LocalCursor
			INTO @ChildID;
	END;
		
	CLOSE LocalCursor;
	DEALLOCATE LocalCursor;
			
END
GO


