-- function structure for GetDescendanDocumentLinesFromDocument
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetDescendanDocumentLinesFromDocument]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetDescendanDocumentLinesFromDocument]
GO

CREATE FUNCTION [dbo].[GetDescendanDocumentLinesFromDocument]
(	
	@IDRecord int,
	@IDModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	select d.IDDocument, d.IDModule as IDDocumentModule, d.doc_ref as SrcDocRef, dl.ID as IDLineSrc, dl.LineNumber as LineNumberSrc,dl.qty as QtySrc, dlDest.Qty as QtyDest,
	dlDest.productid as IDProduct, dlDest.productidModule as IDProductModule, dlDest.ProductCode, dlDest.LineNumber as LineNumberDest, dlDest.ID as IDLineDest,
	dDest.IDDocument as IDDocumentDest, dDest.IDModule as IDDocumentDestModule, dDest.doc_ref, dDest.RegisterStatus, dDest.doc_date, dDest.status
	from Document d
	inner join DocumentLine dl on dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule and dl.PartitionColumn = d.PartitionColumn
	inner join DocumentLine dlDest on dlDest.LineLink = dl.ID 
	inner join document dDest on dDest.IDDocument = dlDest.IDRegister and dDest.IDModule = dlDest.IDModule and dDest.PartitionColumn = dlDest.PartitionColumn
	where d.IDDocument = @IDRecord and d.IDModule = @IDModule
)
GO


