-- function structure for aux_MRRP_f_abf048888b2e4f20a1a794c1e16f20a7
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[aux_MRRP_f_abf048888b2e4f20a1a794c1e16f20a7]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[aux_MRRP_f_abf048888b2e4f20a1a794c1e16f20a7]
