CREATE FUNCTION [dbo].[aux_MRRP_f_abf048888b2e4f20a1a794c1e16f20a7]
(
@id int
)
RETURNS nvarchar(max)
AS
BEGIN
declare @r nvarchar(max)
SELECT @r = STRING_AGG(t_MRRP7.AssignResourceCode ,'; ')
 FROM (select a2r.IDTask2Entity, arra.IDTaskResourceRole, arra.IDTask,arra.IDResource,arra.IDUser ,l.FullName,r.Code, 
CONCAT(l.FullName,' (',TRIM(r.Code),')') AS AssignResourceCode
FROM  SysTask2Entity a2r
inner join SysTaskResourceRole  arra  on a2r.IDTask= arra.IDTask
LEFT JOIN SysResources r on r.ResourceId=arra.IDResource
LEFT Join SysLogin l on l.IDLogin =arra.IDUser) as t_MRRP7 
 WHERE @id=t_MRRP7.IDTask2Entity
return @r
END
GO


