GO

CREATE PROCEDURE [dbo].[SS_DeleteTaskOfOperation]
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@instanceNum int,
	@OperationID int,
	@SysMirrX bit,
	@SysMirrY bit,
	@Pos int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @ObjectID uniqueidentifier;		
	Declare @NoCopies bit
	set @NoCopies=0;
	if @OperationID=dbo.CMMResKind()
		set @NoCopies=1;	

	 	DECLARE LocalCursor2 CURSOR LOCAL

		FOR select id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,@instanceNum,NULL,NULL,@SysMirrX,@SysMirrY,@Client,@NoCopies);
		OPEN LocalCursor2;
		FETCH NEXT FROM LocalCursor2
			INTO  @ObjectID;

		WHILE @@FETCH_STATUS = 0
		BEGIN

			if @OperationID=dbo.CMMKind()
			begin
				Delete from  SS_CMMPoint where id in (Select id from ss_program where idobject=@ObjectID and (idjob is null) and kind= dbo.CMMKind() and ProgramType=9)
			end

			FETCH NEXT FROM LocalCursor2
			INTO @ObjectID;
		END;
		
		CLOSE LocalCursor2;
		DEALLOCATE LocalCursor2;


END

