-- ----------------------------
-- procedure structure for SetupNodePartForRole
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SetupNodePartForRole]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SetupNodePartForRole]
GO

CREATE PROCEDURE [dbo].[SetupNodePartForRole]
	@IDRole UNIQUEIDENTIFIER,
	@isCreate BIT,
	@NodePartParent UNIQUEIDENTIFIER = NULL
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @EMPTY UNIQUEIDENTIFIER;
	SET @EMPTY = '00000000-0000-0000-0000-000000000000';

	if @NodePartParent = @EMPTY 
	begin
		set @NodePartParent = NULL
	end
	-- declare @IDNodePart uniqueidentifier

	IF @isCreate = 1
	BEGIN

		DECLARE @ParentPosic UNIQUEIDENTIFIER
		DECLARE @Posic  UNIQUEIDENTIFIER

		set @Posic = NULL;
		
		select @Posic = pos.ID
		from sm_nodeposic pos
			inner join sm_nodepart p on pos.IDNodePosicParent = p.IDNodePosic
		where pos.IDNodePartDocked is null and p.ID = @NodePartParent;
		
		if @posic is null or @NodePartParent is null  
		begin

			DECLARE @resultsPosic TABLE (
				IDNodePosic UNIQUEIDENTIFIER NULL
			);
			
			if @NodePartParent is null
			begin
						
				INSERT INTO sm_nodeposic(ID, Code, IDNodePosicParent, IDNodePartParent, AllowedKind1, AllowedKind2, KindMask1, KindMask2) 
				OUTPUT inserted.id INTO @resultsPosic(IDNodePosic)
				VALUES (NEWID(), '', @EMPTY, @EMPTY, 64319, 0, 8192, 0)
				
			end
			else
			begin
			
				INSERT INTO sm_nodeposic(ID, Code, IDNodePosicParent, IDNodePartParent, AllowedKind1, AllowedKind2, KindMask1, KindMask2) 
				OUTPUT inserted.id INTO @resultsPosic(IDNodePosic)
				SELECT NEWID(), '', IDNodePosic, ID, 64319, 0, 8192, 0
				FROM sm_nodepart
				WHERE ID = @NodePartParent
			end


			select @posic = IDNodePosic from @resultsPosic
			-- we need to create a new posic
			-- print concat('error for ', @NodePartParent);
			-- throw 51000, 'error', 1;
		end

		DECLARE @results TABLE (
			IDNodePart UNIQUEIDENTIFIER NULL,
			Code CHAR(50), 
			Name CHAR(200), 
			KindMask1 INT,
			KindMask2 INT
		);
		INSERT INTO SM_NodePart(ID, IDNodePosic, Code, Name, KindMask1, KindMask2) 
		OUTPUT inserted.ID, inserted.Code, inserted.Name, inserted.KindMask1, inserted.KindMask2 into @results(IDNodePart, Code, Name, KindMask1, KindMask2)
		SELECT resourceid, @EMPTY, Code, Code, KindMask1, KindMask2
		FROM sysresources 
		WHERE resourceid = @IDRole;

		UPDATE sm_nodeposic
		SET IDNodePartDocked = r.IDNodePart,
			NodePartDockedCode = r.Code,
			NodePartDockedName = r.Name,
			NodePartDockedKindMask1 = r.KindMask1,
			NodePartDockedKindMask2 = r.KindMask2
		FROM
			sm_nodeposic, @results r
		WHERE ID = @Posic;

	END
	ELSE
	BEGIN

		UPDATE SM_NodePart
		SET 
			SM_NodePart.KindMask1 = SysResources.KindMask1,
			SM_NodePart.KindMask2 = SysResources.KindMask2
		FROM SM_NodePart INNER JOIN SysResources ON SM_NodePart.ID = SysResources.ResourceID
		WHERE  SysResources.ResourceId = @IDRole;

		UPDATE pos
		SET 
			IDNodePartDocked = p.ID,
			NodePartDockedCode = p.Code,
			NodePartDockedName = p.Name,
			NodePartDockedKindMask1 = p.KindMask1,
			NodePartDockedKindMask2 = p.KindMask2
		from sm_nodeposic pos inner join SM_NodePart p on pos.IDNodePartDocked = p.ID
		where p.ID = @IDRole

	END
	
END
GO


-- ----------------------------
-- procedure structure for UpdateOrCreateTranslatableActivityFollowUpItem
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateOrCreateTranslatableActivityFollowUpItem]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateOrCreateTranslatableActivityFollowUpItem]
GO

CREATE PROCEDURE [dbo].[UpdateOrCreateTranslatableActivityFollowUpItem]
(
	@idActivity int,
	@idTransl uniqueidentifier OUTPUT,
	@target int output
)
AS
BEGIN
	SET NOCOUNT ON;

	declare @isTranslOfFup bit
	set @isTranslOfFup = 0

	if exists(select * from FollowUpItem where followupitemTranslation = @idTransl and not followupitemTranslation is null)
	begin
		set @isTranslOfFup = 1
	end

	declare @nrel int
	set @nrel = 0

	select @nrel = COUNT(*) from Activity2Record ar
	  inner JOIN FollowUpItem fup on ar.relatedRecord = fup.IDFollowUpItem and ar.relatedRecordModule = fup.IDModule and ar.IDActivity = @idActivity

	if @nrel > 0
	begin

		set @target = 3
		
		if @nrel > 1 
		begin
			-- if we have more than one relationship, and are using the translation of a fup, we want to create a new translation but keep the fup 
			-- translation in the db
			if @isTranslOfFup = 1
			begin
				set @idTransl = null 
			end
		end
		else 
		begin
			-- if we have only one relationship, and are using a non fup translation, we want to delete it and use the translation of the fup
			if @isTranslOfFup = 0
			begin
				delete from SysTranslationDataLanguage where IDTranslationData = @idTransl
				delete from SysTranslationData where IDTranslationData = @idTransl
			end

			select @idTransl = fup.followupitemTranslation from Activity2Record ar
			inner JOIN FollowUpItem fup on ar.relatedRecord = fup.IDFollowUpItem and ar.relatedRecordModule = fup.IDModule and ar.IDActivity = @idActivity 
			where not fup.followupitemTranslation is null

			if not @idTransl is null and @idTransl != '00000000-0000-0000-0000-000000000000' 
			begin
				set @isTranslOfFup = 1
			end
		end

		if @idTransl is null or @idTransl = '00000000-0000-0000-0000-000000000000' 
		begin
			-- if by this point we have no translation, we want to create a new one
			set @idTransl = NEWID()
			insert into SysTranslationData(IDTranslationData) values (@idTransl)

			insert into SysTranslationDataLanguage(IDTranslationData, IDLanguage, Name) 
			select @idtransl, IDLanguage, ''
			from SysLanguage
			where Active = 1

			set @isTranslOfFup = 0
		end

		if @isTranslOfFup = 0
		begin
			-- if we have a non fup translation, we want to update it by aggregating the related fup translations

			update SysTranslationDataLanguage
			set Name = ModuleName
			from SysTranslationDataLanguage inner join (
				SELECT IDLanguage, STRING_AGG(t_MRRP2.ModuleName ,'; ') as ModuleName
				 FROM (Select
				 l.IDLanguage,
				 t.Name as ModuleName
				From
				 Activity2Record ar
				  LEFT JOIN FollowUpItem fup on ar.relatedRecord = fup.IDFollowUpItem and ar.relatedRecordModule = fup.IDModule			  
				  LEFT JOIN SysTranslationValue t on fup.FollowUpItemTranslation = t.IDTranslation 
				  left join SysLanguage l on t.IDLanguage = l.IDLanguage
				Where
				 fup.IDModule in (Select IDModule from GetModulesRec('19164347-8e56-4495-8c87-fb21580ae944'))
				 and @idActivity=ar.IDActivity
				 and not l.IDLanguage is null
			 
				 ) as t_MRRP2 
				 group by IDLanguage
			 
			) as aux
			on SysTranslationDataLanguage.IDLanguage = aux.IDLanguage
			where IDTranslationData = @idtransl
		end
	end
	else 
	begin
		-- if we have 0 rels, and are using a non fup translation, we want to delete it
		if @isTranslOfFup = 0
		begin
			delete from SysTranslationDataLanguage where IDTranslationData = @idTransl
			delete from SysTranslationData where IDTranslationData = @idTransl
		end

		set @idTransl = null
		set @target = null
	end
	
END
GO


