-- function structure for GetJobLineGlobalOrder
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetJobLineGlobalOrder]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetJobLineGlobalOrder]
GO

CREATE FUNCTION [dbo].[GetJobLineGlobalOrder]
(
	-- Add the parameters for the function here
	@IDJobLine bigint 
)
RETURNS nvarchar(100)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @ResultVar nvarchar(100) = ''

	-- Add the T-SQL statements to compute the return value here
	SELECT @ResultVar = (SELECT CASE WHEN IDParent IS NULL THEN REPLACE(STR(0,4),' ','0') ELSE CONCAT (CONCAT(dbo.GetJobLineGlobalOrder(IDParent), '_') ,REPLACE(STR(Ordem,4),' ','0')) END as Ordem1 FROM SysJobLine WHERE IDJobLine = @IDJobLine)

	-- Return the result of the function
	RETURN @ResultVar

END
GO


-- ----------------------------
-- procedure structure for CloseAllSessions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseAllSessions]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseAllSessions]
GO

CREATE PROCEDURE [dbo].[CloseAllSessions]
	@IDWorkstation nvarchar(50) = null,
	@IDLogin uniqueidentifier = null,
	@ClientVersion nvarchar(50) = null,
	@HeartBeatMin int = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @IDSession uniqueidentifier

    declare CloseAllSessions_it cursor 
		LOCAL STATIC READ_ONLY FORWARD_ONLY
		for
		select IDSession from SysSession
		where 
			(@IDWorkstation is null or IDWorkstation = @IDWorkstation)
			and
			(@IDLogin is null or IDLogin = @IDLogin)
			and
			(@ClientVersion is null or ClientVersion = @ClientVersion)
			and
			(@HeartBeatMin is null or DATEDIFF(minute, datestart, GETUTCDATE()) >= @HeartBeatMin);

	open CloseAllSessions_it;

	fetch next from CloseAllSessions_it into @IDSession;
	while @@FETCH_STATUS = 0
	begin

		--print 'CloseSession' 

		exec dbo.CloseSession @IDSession, 1

		fetch next from CloseAllSessions_it into @IDSession;
	end

	close CloseAllSessions_it;
	deallocate CloseAllSessions_it;

	exec CloseAllZombieLocks

END
GO


