-- ----------------------------
-- procedure structure for GetPositionCurrentJob
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPositionCurrentJob]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetPositionCurrentJob]
GO

CREATE PROCEDURE [dbo].[GetPositionCurrentJob]
	-- Add the parameters for the stored procedure here
	@IDPOSIC Uniqueidentifier ,
	@Factor float
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
DECLARE @Working Uniqueidentifier = '483D173F-7287-4751-A9D1-741DAAAB41E0'
DECLARE @WInit Uniqueidentifier = '3A223268-BC2E-408E-AD63-55163DFF0950'
DECLARE @WReady Uniqueidentifier = 'C6812E70-56CB-4394-84A5-4C3DE719B44E'

SELECT jl.Ordem, COALESCE(p.Code,'') as [Code], j.Code AS [Job], ISNULL(jl.IDParent,-1) AS IDParent, jl.IDJobline as IDJobline
,dbo.GetJobLineGlobalOrder(jl.IDJobline) as GlobalOrder, 1 as [IsExpandedFlag],
CASE 
	WHEN (jl.IDTool IS NULL OR jl.IDTool = '00000000-0000-0000-0000-000000000000') AND  (jl.IDShape IS NOT NULL AND jl.IDShape <> '00000000-0000-0000-0000-000000000000'   )
	THEN 
		ISNULL(CONCAT('Instance of ',COALESCE(RTRIM(LTRIM(s.Fullname)),'')),'' )  
	WHEN p.ToolID IS NOT NULL AND p.ToolID <> '00000000-0000-0000-0000-000000000000'  
		THEN ISNULL(CONCAT(dbo.SS_GetClientName(o.ID) + '_',COALESCE(RTRIM(LTRIM(o.FullName)),RTRIM(LTRIM(o.ShortName)))),'' )  
	ELSE 
		LTRIM(RTRIM(COALESCE(mp.Tool,'')))  
	END AS Tool , 
COALESCE(mp.TH,'') as TH, COALESCE(LTRIM(RTRIM(mp.HolderCode)),'') As HolderCode,  
COALESCE(dbo.GetTimeFromSeconds(p.EstimatedTime),'') as EstimatedTime ,   
COALESCE(dbo.GetTimeFromSeconds(SUM(p.EstimatedTime) 
	OVER(ORDER BY jl.idjob ,dbo.GetJobLineGlobalOrder(jl.IDJobline) ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT  ROW)),'') AS Total , 
COALESCE(dbo.GetTimeFromSeconds((p.EstimatedTime*@Factor)),'') as [S7] ,   
COALESCE( dbo.GetTimeFromSeconds(SUM(p.EstimatedTime*@Factor) 
	OVER(ORDER BY jl.idjob ,dbo.GetJobLineGlobalOrder(jl.IDJobline) ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT  ROW)), '') AS TotalS7 , 
w.Code as [Status]  , 
r.StartDate, r.EndDate,  
COALESCE(dbo.GetTimeFromSeconds(DATEDIFF(SECOND, r.StartDate, r.EndDate)),'') As [RealDuration] ,  
COALESCE(dbo.GetTimeFromSeconds(SUM(DATEDIFF(SECOND, r.StartDate, r.EndDate))  
	OVER(ORDER BY jl.idjob ,dbo.GetJobLineGlobalOrder(jl.IDJobline) ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT  ROW)), '') AS[RealDurationTotal] 

FROM SysJobLine jl  
LEFT JOIN SysJob j ON jl.IDJob = j.ID  
LEFT JOIN SS_Shape s ON s.ID = jl.IDShape
LEFT JOIN SS_Program p ON jl.IDProgram = p.ID  AND p.IDObject = jl.IDPart
LEFT JOIN SS_MILLProgram mp ON p.ID = mp.ID  
LEFT JOIN SysWorkingStatus w ON jl.Status = w.ID  
LEFT JOIN SysPrRoutineRequest r ON jl.IDJobLine = r.IDJobLine  
LEFT JOIN SS_Object o ON p.ToolID = o.ID  
WHERE j.IDPart = (SELECT ID FROM SM_NodePart WHERE IDEntryPosition = @IDPOSIC)   
AND j.Status IN (@Working,@WInit,@WReady)  
AND r.IDRequestToResolve IS NULL 
AND r.IDRequestLink IS NULL
AND r.IDTask IS NULL 
--AND r.IDJob IS NOT NULL AND r.IDJob > 0
--AND r.IDOperationType = j.IDOperationType
AND (r.IDOperation IS NULL OR r.IDOperation <> '00000000-0000-0000-0000-000000000000')
--AND jl.LineType = 0 
AND jl.Active =1  
AND j.IDOperationType 
IN (SELECT IDOperationType FROM SM_NodePosicConfiguration WHERE WorkAssignment = 1 AND IDNode =  @IDPOSIC)  
ORDER BY j.ID ASC, dbo.GetJobLineGlobalOrder(jl.IDJobline) ASC 
END
GO


-- ----------------------------
-- procedure structure for UpdateAllAccountsBalances
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAllAccountsBalances]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAllAccountsBalances]
GO

CREATE PROCEDURE [dbo].[UpdateAllAccountsBalances]
	
AS
BEGIN
	SET NOCOUNT ON;

	declare it cursor for
		select distinct idrecord, idrecordmodule from syspocvalue

	open it;

	declare @idrecord int, @idmodule uniqueidentifier

	fetch next from it into @idrecord, @idmodule

	while @@FETCH_STATUS = 0
	begin
		print concat('update account balances ', @idrecord, ' ', @idmodule)
		exec [UpdateAccountBalances] @idrecord, @idmodule

		fetch next from it into @idrecord, @idmodule
	end

	close it;
	deallocate it;
END
GO


-- ----------------------------
-- procedure structure for UpdateEntityCalculatedFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateEntityCalculatedFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateEntityCalculatedFields]
GO

CREATE PROCEDURE [dbo].[UpdateEntityCalculatedFields]
	(@IDOrganization int)
AS
BEGIN
	
	SET NOCOUNT ON;

	update Entity
	set Industries = (SELECT STRING_AGG(Industries ,'; ')
		FROM(SELECT E2R.IDRecEntity, E2R.IDRecIndustry,i.Name AS Industries 
		FROM Entity2Industry E2R LEFT JOIN Industry i ON i.IDIndustry=E2R.IDRecIndustry AND E2R.IDRecEntity = @IDOrganization )m)
	where organizationid = @IDOrganization

	update Entity
	set CAE = (SELECT STRING_AGG(CAE ,'; ')
		FROM(SELECT E2C.[IDEntity], E2C.IDCae, concat(c.Code, ' | ', c.usualname) AS CAE 
		FROM Entity2SysCae E2C INNER JOIN sysCae c ON c.IDCae=E2C.IDCae AND E2C.[IDEntity] = @IDOrganization )m)
	where organizationid = @IDOrganization

	declare @EntityModule uniqueidentifier = (select top 1 IDModule from Entity where organizationid = @IDOrganization);
	if(@EntityModule = '28bee890-28fa-45e2-8d51-8d30f36c4f04')
	begin
		declare @EntityLogin uniqueidentifier = (select top 1 idrelatedlogin from Entity where organizationid = @IDOrganization);
		declare @CurrentResource uniqueidentifier = (select top 1 IDResource from SysLogin2SysResource where IDPerson = @IDOrganization and IDPersonModule = @EntityModule and Active = 1);

		if(@EntityLogin is not null and @CurrentResource is not null)
		begin
			update entity set CurrentResource = @CurrentResource
			where organizationid = @IDOrganization;

			update Account set CurrentResource = @CurrentResource
			where IDContact = @IDOrganization and IDContactModule = @EntityModule;

		end
	end
END
GO


-- ----------------------------
-- procedure structure for IndicatorCalculateSuperiorValues
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[IndicatorCalculateSuperiorValues]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[IndicatorCalculateSuperiorValues]
GO

CREATE PROCEDURE [dbo].[IndicatorCalculateSuperiorValues] 
	 @PeriodType int,
	 @IDQueryIndicator uniqueidentifier
AS
BEGIN

	SET NOCOUNT ON;
	--Declare Type of indicators
	DECLARE @Week int = 2;	
	DECLARE @Month int = 3;	
	DECLARE @Semester int = 4;	
	DECLARE @Quarter int = 5;		 --4 months
	DECLARE @Quadrimestre int = 6;	 --3 months
	DECLARE @Year int = 7;	

	--INSERT INTO Log4Net VALUES (CAST(GETDATE() As date ),0,'INFO','@PeriodType <-> @IDQueryIndicator',@PeriodType,@IDQueryIndicator,0)

	--Remove last calculated Value, keep only base type Periods
	DELETE FROM SysQueryIndicatorItem WHERE PeriodType<>@PeriodType AND IDQueryIndicator=@IDQueryIndicator;

	-- IF period is a week create Month,Quarter,Quadrimester,Semester and Year Indicators
	IF  @PeriodType = @Week
	BEGIN
		--Weeks to Month
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),DATEPART(MONTH, DateEnd), SUM(NumValue), Year , @IDQueryIndicator, @Month
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,DATEPART(MONTH, DateEnd);

		--Weeks to quarter
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),DATEPART(QUARTER, DateEnd), SUM(NumValue), Year , @IDQueryIndicator, @Quadrimestre
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,DATEPART(QUARTER, DateEnd);

		--Weeks to trimester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(MONTH,DateEnd)-1)/4)+1, SUM(NumValue), Year , @IDQueryIndicator, @Quarter
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(MONTH,DateEnd)-1)/4)+1;

		--Weeks to Semester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(quarter,DateEnd)-1)/2)+1, SUM(NumValue), Year , @IDQueryIndicator, @Semester
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(quarter,DateEnd)-1)/2)+1;

		--Weeks to Year
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),(DATEPART(YEAR,DateEnd)), SUM(NumValue), Year , @IDQueryIndicator, @Year
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,(DATEPART(YEAR,DateEnd));

	END
	IF @PeriodType = @Month
	BEGIN
		--Month to quarter
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),DATEPART(QUARTER, DateEnd), SUM(NumValue), Year , @IDQueryIndicator, @Quadrimestre
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,DATEPART(QUARTER, DateEnd);

		--Month to trimester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(MONTH,DateEnd)-1)/4)+1, SUM(NumValue), Year , @IDQueryIndicator, @Quarter
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(MONTH,DateEnd)-1)/4)+1;

		--Month to Semester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(quarter,DateEnd)-1)/2)+1, SUM(NumValue), Year , @IDQueryIndicator, @Semester
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(quarter,DateEnd)-1)/2)+1;

		--Month to Year
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),(DATEPART(YEAR,DateEnd)), SUM(NumValue), Year , @IDQueryIndicator, @Year
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,(DATEPART(YEAR,DateEnd));
	END
	IF  @PeriodType = @Quarter
	BEGIN
		--Quarter to Quadimester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(MONTH,DateEnd)-1)/4)+1, SUM(NumValue), Year , @IDQueryIndicator, @Quadrimestre
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(MONTH,DateEnd)-1)/4)+1;

		--Quarter to semester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(quarter,DateEnd)-1)/2)+1, SUM(NumValue), Year , @IDQueryIndicator, @Semester
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(quarter,DateEnd)-1)/2)+1;

		--Quarter to Year
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),(DATEPART(YEAR,DateEnd)), SUM(NumValue), Year , @IDQueryIndicator, @Year
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,(DATEPART(YEAR,DateEnd));
	END
	IF  @PeriodType = @Quadrimestre
	BEGIN
		--Quadrimestre to semester
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),((DATEPART(quarter,DateEnd)-1)/2)+1, SUM(NumValue), Year , @IDQueryIndicator, @Semester
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,((DATEPART(quarter,DateEnd)-1)/2)+1;

		--Quadrimestre to Year
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),(DATEPART(YEAR,DateEnd)), SUM(NumValue), Year , @IDQueryIndicator, @Year
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,(DATEPART(YEAR,DateEnd));
	END
	IF  @PeriodType = @Semester

		--Semester to year
		INSERT INTO SysQueryIndicatorItem (DateStart,DateEnd,Period,NumValue,Year,IDQueryIndicator,PeriodType)
		SELECT MIN(DateStart), MAX(DateEnd),(DATEPART(YEAR,DateEnd)), SUM(NumValue), Year , @IDQueryIndicator, @Year
		FROM SysQueryIndicatorItem
		WHERE IDQueryIndicator=@IDQueryIndicator and PeriodType=@PeriodType
		GROUP BY Year,(DATEPART(YEAR,DateEnd));


END
GO


