CREATE PROCEDURE [dbo].[SS_EDMProgramSetOrder]
	-- Add the parameters for the stored procedure here
	@ObjectID uniqueidentifier
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	Update edm
	Set Ordem=mo.row
	from ss_program edm
	join 
		(Select  ROW_NUMBER() OVER(order by p.position,t.shortname,e.EletrodeFamily asc,e.InstanceNum asc,p.ordem asc) AS Row,p.id,p.code
		from ss_program p
		left join ss_eletrode e on e.id=p.ToolID
