-- ----------------------------
-- procedure structure for UpdateTranslatableFUActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateTranslatableFUActivity]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateTranslatableFUActivity]
GO

CREATE PROCEDURE [dbo].[UpdateTranslatableFUActivity]
	@IDActivity int
AS
BEGIN
	
	SET NOCOUNT ON;
	declare @idT uniqueidentifier
	declare @idTT int

	select @idT = followupItemTranslation, @idTT = followupitemTranslationTarget
		from activity
		where IDActivity = @IDActivity 
		
	exec [dbo].[UpdateOrCreateTranslatableActivityFollowUpItem] @idactivity = @IDActivity, @idTransl = @idT output, @target = @idTT output

	update Activity set followupItemTranslation = @idT, followupitemTranslationTarget = @idTT where IDActivity = @IDActivity 
	update Activity set FollowUpItemIds = (
		select STRING_AGG(CONCAT(fup.IDFollowUpItem, '|', fup.IDModule), ';')
		from Activity2Record a2r inner join FollowUpItem fup on a2r.relatedRecord = fup.IDFollowUpItem and a2r.relatedRecordModule = fup.IDModule
		where a2r.IDActivity = @IDActivity and fup.RegisterSysStatus = 0
			) 
	where IDActivity = @IDActivity
		
END
GO


