-- ----------------------------
-- procedure structure for UpdateTranslatableFUAndRelatedActivities
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateTranslatableFUAndRelatedActivities]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateTranslatableFUAndRelatedActivities]
GO

CREATE PROCEDURE [dbo].[UpdateTranslatableFUAndRelatedActivities]
(
	@IDFollowUpItem int,	
	@IDModule uniqueidentifier
)
as 
begin
	SET NOCOUNT ON;

	declare @idTransl uniqueidentifier 

	set @idTransl = (select FollowUpItemTranslation from FollowUpItem where IDFollowUpItem = @IDFollowUpItem and IDModule = @IDModule)

	if @idTransl is null or @idTransl = '00000000-0000-0000-0000-000000000000' 
	begin
		set @idTransl = NEWID()
		insert into SysTranslationData(IDTranslationData) values (@idTransl)

		insert into SysTranslationDataLanguage(IDTranslationData, IDLanguage, Name) 
		select @idtransl, IDLanguage, ''
		from SysLanguage
		where Active = 1

		update FollowUpItem set FollowUpItemTranslation = @idTransl, FollowUpItemTranslationTarget=3 where IDFollowUpItem = @IDFollowUpItem and IDModule = @IDModule
	end
	
	update SysTranslationDataLanguage
	set Name = ModuleName
	from SysTranslationDataLanguage inner join (
		SELECT IDLanguage, STRING_AGG(t_MRRP2.ModuleName ,'; ') as ModuleName
			FROM (Select
			l.IDLanguage,
			CONCAT(ISNULL((CASE 
			WHEN (m.IDTranslationTarget = 1) THEN (t.Acronym) 
			WHEN (m.IDTranslationTarget = 2) THEN (t.ShortName) 
			WHEN (m.IDTranslationTarget = 3) THEN (t.Name) 
			WHEN (m.IDTranslationTarget = 4) THEN (t.Description) END),''), ' [',TRIM(fup.Code),'] | ',fup.Name) as ModuleName
		From
			FollowUpItem fup
			LEFT JOIN SysModule m on fup.IDModule = m.IDModule
			LEFT JOIN SysTranslationValue t on m.IDTranslation = t.IDTranslation
			left join SysLanguage l on t.IDLanguage = l.IDLanguage
		Where
			fup.IDModule in (Select IDModule from GetModulesRec('19164347-8e56-4495-8c87-fb21580ae944'))
			and fup.idfollowupitem=@IDFollowUpItem
			and not l.IDLanguage is null
			 
			) as t_MRRP2 
			group by IDLanguage
			 
	) as aux
	on SysTranslationDataLanguage.IDLanguage = aux.IDLanguage
	where IDTranslationData = @idtransl

	declare @ida int
	
	declare it_r2a cursor for 
		select idactivity
		from Activity2Record  with (nolock)
		where relatedRecord = @IDFollowUpItem and relatedRecordModule = @IDModule
			and not IDActivity is null

	open it_r2a

	fetch next from it_r2a into @ida

	while @@FETCH_STATUS = 0	
	begin
		exec UpdateTranslatableFUActivity @IDActivity = @ida
		fetch next from it_r2a into @ida
	end

	close it_r2a
	deallocate it_r2a
			

end
GO


-- ----------------------------
-- procedure structure for SS_GetNextTODO
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_GetNextTODO]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_GetNextTODO]
GO

CREATE PROCEDURE [dbo].[SS_GetNextTODO]
	@SearchTemplateID uniqueidentifier,
	@ResourceID uniqueidentifier out,
	@ObjectID uniqueidentifier out,
	@MouldID uniqueidentifier out,
	@ToolID uniqueidentifier out,
	@Position int out,
	@TODOID int out,
	@IDJob bigint out,
	@IDJobLine bigint out,
	@ToolCode nvarchar(50) out,
	@LoginID uniqueidentifier
AS
BEGIN	
	Select top 1 @TODOID=ot.id, @ObjectID=idobject, @ResourceID=ot.IDResource, @IDJobLine=idJobLine, @ToolID=idTool ,@Position=Position,@IDJob=IDJob
	from SS_ObjectTODO ot
	left join SysJobPPTemplate m on m.idtemplate=ot.idtemplate
	where ((@SearchTemplateID is null) or (@SearchTemplateID=m.idtemplate)) 
	and (state=0 or (State=5 and IsNull(ProcessingCounter,0)<5))
	order by DateCreated


	if @TODOID is not null
	begin
		set @MouldID = (select mouldid from ss_object where id=@ObjectID)
		update SS_ObjectTODO set state=5,ProcessingCounter=Isnull(ProcessingCounter,0)+1 where id=@TODOID;
	end

	set @ToolCode='';
	if @ToolID is not null
		set @ToolCode =  dbo.SS_GetFullName(@ToolID) 

END
GO


-- ----------------------------
-- function structure for DateGmtPtToUtc
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DateGmtPtToUtc]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[DateGmtPtToUtc]
GO

CREATE FUNCTION [dbo].[DateGmtPtToUtc](@dt datetime ) 
returns datetime 
as begin
	declare @final datetime
	declare @offset int
	declare @yearDt int
	declare @lastSundayMonth3 datetime
	declare @lastSundayMonth10 datetime

	IF (@dt IS NULL)
		return @dt

	set @offset =0	
	set @yearDt=YEAR(@dt)
	
	set @lastSundayMonth3 = DATEADD(day,DATEDIFF(day,'19000107',DATEADD(month,DATEDIFF(MONTH,0,CONVERT(DATETIME, CONCAT (@yearDt,'-03-01T00:00:00.000'), 126)),30))/7*7,'19000107')
	
	set @lastSundayMonth3=dateadd(HOUR,1,@lastSundayMonth3)

	set @lastSundayMonth10 = DATEADD(day,DATEDIFF(day,'19000107',DATEADD(month,DATEDIFF(MONTH,0,CONVERT(DATETIME, CONCAT (@yearDt,'-10-01T00:00:00.000'), 126)),30))/7*7,'19000107')
	
	set @lastSundayMonth10=dateadd(HOUR,2,@lastSundayMonth10)

	if(@dt >=@lastSundayMonth3 and @dt<= @lastSundayMonth10)
		return switchoffset(@dt, '-01:00') 
	return @dt	
end
GO


-- ----------------------------
-- function structure for GetHasAccessToTask
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetHasAccessToTask]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetHasAccessToTask]
GO

CREATE FUNCTION [dbo].[GetHasAccessToTask]
(
	@idTask uniqueidentifier,
	@idOwn uniqueidentifier,
	@IDOwnResource uniqueidentifier
)
RETURNS int
AS
BEGIN	
	DECLARE @ret int
	set @ret = 0

  IF @idtask = '00000000-0000-0000-0000-000000000000'
  BEGIN
    set @ret = 1
  END
  ELSE 
  begin
  	if exists(select idTaskresourcerole from SysTaskResourceRole where idtask = @idtask and (SysTaskResourceRole.IDUser = @IDOwn OR dbo.TestResourceWithTriplet(@IDOwnResource, SysTaskResourceRole.IDResource, SysTaskResourceRole.IDActivityRole, SysTaskResourceRole.TeamMask01, SysTaskResourceRole.TeamMask02, 0) = 1)) 
  	begin
  		set @ret = 1
  	END
	ELSE 
	--- IsSuperAdmin
	if exists(select 1 from SysResources where ResourceId=@IDOwnResource and IsSuperAdmin=1)
		begin
  		set @ret = 1
  	END
  end

	RETURN @ret
END
GO


-- ----------------------------
-- procedure structure for usp_UpdateSysPocValue
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_UpdateSysPocValue]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[usp_UpdateSysPocValue]
GO

CREATE PROCEDURE [dbo].[usp_UpdateSysPocValue]
    @fixDiff DECIMAL(18,4),
    @IDPocValueLine INT,
    @IDPocValueTotalLine INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION T1;

    BEGIN TRY
        -- Atualiza linha principal
        UPDATE SysPocValue
        SET QtyActualStock     = QtyActualStock - @fixDiff,
            TotalCredit        = TotalCredit - @fixDiff,
            TotalQtyActualStock= TotalQtyActualStock - @fixDiff
        WHERE IDPocValue = @IDPocValueLine;

        -- Atualiza linha total
        UPDATE SysPocValue
        SET QtyActualStock     = QtyActualStock - @fixDiff,
            TotalQtyActualStock= TotalQtyActualStock - @fixDiff,
            TotalCredit        = TotalCredit - @fixDiff
        WHERE IDPocValue = @IDPocValueTotalLine;

        COMMIT TRANSACTION T1;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION T1;

        -- Opcional: retorna erro detalhado
        THROW;
    END CATCH
END;
GO


