-- ----------------------------
-- procedure structure for SysTopCpuConsuming
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysTopCpuConsuming]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SysTopCpuConsuming]
GO

CREATE PROCEDURE [dbo].[SysTopCpuConsuming]

AS
BEGIN
	-- https://dbaguides.com/2020/01/06/how-to-troubleshoot-high-cpu-utilization-issue-in-sql-server/
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	SELECT s.session_id, 
		r.status, 
		r.blocking_session_id, 
		r.wait_type, 
		wait_resource, 
		r.wait_time / (1000 * 60) 'wait_time(Min)', 
		r.cpu_time, 
		r.logical_reads, 
		r.reads, 
		r.writes, 
		r.total_elapsed_time / (1000 * 60) 'total_elapsed_time(Min)', 
		Substring(st.TEXT,(r.statement_start_offset / 2) + 1, 
		((CASE r.statement_end_offset 
		WHEN -1 
		THEN Datalength(st.TEXT) 
		ELSE r.statement_end_offset 
		END - r.statement_start_offset) / 2) + 1) AS statement_text, 
		Coalesce(Quotename(Db_name(st.dbid)) + N'.' + Quotename(Object_schema_name(st.objectid, st.dbid)) + N'.' +
		Quotename(Object_name(st.objectid, st.dbid)), '') AS command_text,
		r.command, 
		qp.query_plan, 
		s.login_name, 
		s.host_name, 
		s.program_name, 
		s.last_request_end_time, 
		s.login_time, 
		r.open_transaction_count ,
		info.idsession,
		sess.clientversion
	FROM sys.dm_exec_sessions AS s 
		JOIN sys.dm_exec_requests AS r ON r.session_id = s.session_id 
		CROSS APPLY sys.Dm_exec_sql_text(r.sql_handle) AS st 
		CROSS APPLY sys.dm_exec_query_plan(r.plan_handle) AS qp 
		left join syssessioninfo info on s.session_id = info.spid
		left join SysSession sess on info.idsession = sess.idsession
	WHERE r.session_id != @@SPID
 
	ORDER BY r.cpu_time desc
END
GO


-- ----------------------------
-- procedure structure for UpdateEntity2ServiceContract2BusinessArea
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateEntity2ServiceContract2BusinessArea]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateEntity2ServiceContract2BusinessArea]
GO

CREATE PROCEDURE [dbo].[UpdateEntity2ServiceContract2BusinessArea] 
	@NAlmostExpiringDays int,
	@NAboutToExpireDays int
AS
BEGIN


	truncate table Entity2ServiceContract2BusinessArea;

	declare @AuxTable Table(
		IDRecEntity int null,
		IDRecEntityModule uniqueidentifier null,
		IDServiceContract int null,
		IDServiceContractModule uniqueidentifier null,
		IDBusinessArea int null,
		IDBusinessAreaModule uniqueidentifier null,
		IDBusinessAreaParent int null,
		EndDatePurchase datetime null,
		EndDateSale datetime null,
		HasOwnDates int null,
		LineDepth int null,
		ID uniqueidentifier null
	);

	with initialData as(
		select *, NEWID() ID
		from(
			select distinct e.organizationid IDRecEntity, e.IDModule , sc.IDServiceContract, sc.IDModule as IDServiceContractModule,  ba.IDBusinessArea, ba.IDModule as IDBusinessAreaModule , ba.IDParent as IDBusinessAreaParent,
			case when ba.IDBusinessArea = sc2ba.IDBusinessArea then sc2ba.EndDatePurchase else null end EndDatePurchase,
			case when ba.IDBusinessArea = sc2ba.IDBusinessArea then sc2ba.EndDateSale else null end EndDateSale, 
			case when ba.IDBusinessArea = sc2ba.IDBusinessArea then 1 else 0 end HasOwnDates, ba.LineDepth
			from Entity e
			inner join ServiceContract sc on e.organizationid = sc.IDEntityRelatedTo and e.IDModule = sc.IDEntityRelatedToModule
			inner join ServiceContract2BusinessArea sc2ba on sc.IDServiceContract = sc2ba.IDRecServiceContract and sc.IDModule = sc2ba.IDRecServiceContractModule
			cross apply dbo.GetBAsAscRec(sc2ba.IDBusinessArea) ba
			where sc.status not in(2668,2669,2670) --excludes contracts completed, canceled and archived
		) t
	)
	insert into @AuxTable
	select * from initialData;

	with duplicates as(
		select IDRecEntity, IDServiceContract, IDBusinessArea, IDBusinessAreaParent, LineDepth 
		from @AuxTable
		group by IDRecEntity, IDRecEntityModule, IDServiceContract, IDServiceContractModule, IDBusinessArea, IDBusinessAreaModule, IDBusinessAreaParent, LineDepth
		having count(*) > 1
	), IDsToRemove as(
		select t.ID
		from @AuxTable t
		inner join duplicates d on t.IDServiceContract = d.IDServiceContract and t.IDRecEntity = d.IDRecEntity 
		and t.IDBusinessArea = d.IDBusinessArea and t.LineDepth = d.LineDepth and t.HasOwnDates = 0
	)
	delete from @AuxTable where ID in(select * from IDsToRemove);

	declare @MaxDepth int = (select Max(LineDepth) MaxDepth from @AuxTable);

	insert into Entity2ServiceContract2BusinessArea
	select IDRecEntity, IDRecEntityModule, IDBusinessArea, IDBusinessAreaModule,
	case when  (HasOwnDates = 1 and (DATEDIFF(DAY, EndDateSale, GETDATE()) >= 0)) then 1 else 0 end ,
	null ,IDServiceContract, IDServiceContractModule, null, null,
	case when  HasOwnDates = 1 then EndDatePurchase else null end, 
	case when  HasOwnDates = 1 then EndDateSale else null end 
	from @AuxTable
	where LineDepth = 0;

	declare @i int = 1
	while @i <= @MaxDepth
		begin

			insert into Entity2ServiceContract2BusinessArea
			select IDRecEntity, IDRecEntityModule, IDBusinessArea, IDBusinessAreaModule, 
			case when  (HasOwnDates = 1 and (DATEDIFF(DAY, EndDateSale, GETDATE()) <= 0)) then 1 else 0 end ,
			null ,IDServiceContract, IDServiceContractModule, 
			(
			select id 
				from Entity2ServiceContract2BusinessArea aux 
				where aux.IDRecEntity = t.IDRecEntity and aux.IDRecEntityModule = t.IDRecEntityModule
				and aux.IDServiceContract = t.IDServiceContract and aux.IDServiceContractModule = t.IDServiceContractModule
				and aux.IDBusinessArea = t.IDBusinessAreaParent 
				), null,
				case when  HasOwnDates = 1 then EndDatePurchase else null end, 
				case when  HasOwnDates = 1 then EndDateSale else null end 
			from @AuxTable t
			where LineDepth = @i;
			
			set @i += 1;
		end

		set @i = @MaxDepth - 1;

		while @i >= 0 
		begin
			with minDates as (
				select IDServiceContract IDSC, IDRecEntity IDRecE, IDBusinessAreaParent IDBA, MIN(EndDatePurchase) MinEndPurchase, min(EndDateSale) MinEndSale
				from @AuxTable t
				where LineDepth > @i
				group by IDServiceContract, IDRecEntity,IDBusinessAreaParent
			), linesToUpdate as(
				select md.* 
				from @AuxTable t
				inner join minDates md on t.IDServiceContract = md.IDSC and t.IDRecEntity = md.IDRecE and t.IDBusinessArea = md.IDBA
				where t.LineDepth = @i and HasOwnDates = 0
			)
			update Entity2ServiceContract2BusinessArea set EndDatePurchase = ltu.MinEndPurchase, EndDateSale = ltu.MinEndSale
			from linesToUpdate ltu
			where IDServiceContract = ltu.IDSC and IDBusinessArea = ltu.IDBA and IDRecEntity = ltu.IDRecE

			set @i -= 1;
		end


	update Entity2ServiceContract2BusinessArea 
	set 
	IsMaintenanceActive = case when EndDateSale is not null AND DATEDIFF(DAY,GETDATE(), EndDateSale ) < 0 then 0 else 1 end ,
	Status = case 
		when EndDateSale is null OR DATEDIFF(DAY, GETDATE(), EndDateSale) > @NAlmostExpiringDays then 0 
		when DATEDIFF(DAY, GETDATE(), EndDateSale) between (@NAboutToExpireDays + 1)  and @NAlmostExpiringDays then 1
		when DATEDIFF(DAY, GETDATE(), EndDateSale) between 0 and @NAboutToExpireDays then 2
		else 3 
	end;

END
GO


