-- procedure structure for SS_InsertCMMPoints
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertCMMPoints]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertCMMPoints]
GO

CREATE PROCEDURE [dbo].[SS_InsertCMMPoints]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@ProgramName nvarchar(50),
	@Ordem int,

	@ProgramType int,
	@EstimatedTime int,
	@ParentID uniqueidentifier,
	@HasChilds bit,

	@PX float,
	@PY float,
	@PZ float,
	@PA float,
	@PB float,
	@PC float,
	@PXIni float,
	@PYIni float,
	@PZIni float,
	@PAIni float,
	@PBIni float,
	@PCIni float,
	@VectorI float,
	@VectorJ float,
	@VectorK float,
	@FilePath nvarchar(500),
    @LoginID uniqueidentifier=null,
	@IsPreset bit=0,
	@Pos int=1,
	@GIDStr varbinary(MAX) out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @ObjectID uniqueidentifier;
	--Declare @IDWorkflowItem int
	Declare @CopyMirrX bit;
	Declare @CopyMirrY bit;
	Declare @IsCopy bit;
	declare @gid uniqueidentifier;
	set @GIDStr=null;
	declare @Kind int
	if @IsPreset=0	
		set @Kind=dbo.CMMKind()
	else
		set @Kind=dbo.PRESETKind()

		--LOOP PARTS
	 	DECLARE LocalCursor2 CURSOR LOCAL
		FOR select l.id,o.CopyMirrorX,o.CopyMirrorY ,o.id,l.isCopy
			from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,NULL,null,null,NULL,null,null,@Client,default) l 
			inner join ss_object o on o.id=l.id
		OPEN LocalCursor2;
		FETCH NEXT FROM LocalCursor2
			INTO  @ObjectID,@CopyMirrX,@CopyMirrY,@gid,@IsCopy;
		WHILE @@FETCH_STATUS = 0
		BEGIN
			if @ObjectID is not null
			begin
				set @GIDStr=convert(varbinary(max),concat(@GIDStr,@ObjectID,';'));

					Declare @MultX int;
					Declare @MultY int;

					Set @MultX=1;
					Set @MultY=1;

					if Isnull(@IsCopy,0)=1
					begin
						if @CopyMirrX=1
							Set @MultX=-1;	
						if @CopyMirrY=1
							Set @MultY=-1;
					end
					--Compensação Z de pontos de controlo
					--Queremos guardar sempre o ponto com o 0 no topo da peça
					--Por isso, nao vem entao temos de a compensar					
					declare @CMMOrigin int;
					set @CMMOrigin=(Select top 1 isnull(CMMPointsOrigin,0) from SS_Config);
					--0 Topo, 1 - Mestra, 2 - parte de baixo do bloco, 3 - fundo da base
					declare @CompZ int;
					set @CompZ=0
					--Mestra
					if @CMMOrigin=1
						set @CompZ=(Select MestraZ from ss_object where id=@ObjectID);
					--Altura do Bloco Z
					if @CMMOrigin=2
						set @CompZ=(Select -DimCAD_Z from ss_object where id=@ObjectID);
					--Altura Total - SO FUNCIONA COM BASES POR DEFEITO
					--if @CMMOrigin=3
						--set @CompZ=(Select -(DimCAD_Z+b.DimZ+b.MaterialGap) from ss_object o left join ss_base b on b.num=o.IDMillBase);

					declare @programid uniqueidentifier;
					set @programid=newid();

					Insert into SS_Program(id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
						PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,
						EstimatedTime,ParentID,HasChilds) 
					values (@programid,@ProgramName,@kind,@Ordem,@ObjectID,@FilePath,@Pos,@ProgramType	,@PX*@MultX,
						@PY*@MultY,@PZ+@CompZ,@PA,@PB,@PC,@PXIni*@MultX,@PYIni*@MultY,@PZIni+@CompZ,@PAIni,@PBIni,@PCIni,@VectorI,@VectorJ,@VectorK,
						@EstimatedTime,	@ParentID,@HasChilds);

					insert into SS_CMMPoint(ID, PointXExp, PointYExp, PointZExp, PointXIniExp, PointYIniExp, PointZIniExp,PointRAExp,PointRCExp) values ( 
						@programid,null, null, null, null, null, null,null,null);
				--end
			end
			FETCH NEXT FROM LocalCursor2
			INTO @ObjectID,@CopyMirrX,@CopyMirrY,@gid,@IsCopy;
		END;
		
		CLOSE LocalCursor2;
		DEALLOCATE LocalCursor2;
		
END
GO


-- ----------------------------
-- function structure for GetDomain
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetDomain]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetDomain]
GO

CREATE FUNCTION [dbo].[GetDomain](@email NVARCHAR(4000))
RETURNS NVARCHAR(4000)
AS
BEGIN
    -- Localizar o caractere '@'
    DECLARE @atLocation INT = PATINDEX('%@%', @email);

    -- Se o caractere '@' não for encontrado, retornar string vazia
    IF @atLocation = 0
        RETURN '';

    -- Extrair o domínio a partir do caractere '@'
    RETURN SUBSTRING(@email, @atLocation + 1, LEN(@email) - @atLocation);
END;
GO


