-- ----------------------------
-- function structure for ExplodeDates
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ExplodeDates]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ExplodeDates]
GO

CREATE FUNCTION [dbo].[ExplodeDates](
	@startdate datetime
	, @enddate datetime
)
RETURNS TABLE
AS
RETURN
	WITH DATES AS(
		SELECT @startdate AS dt
		UNION ALL
		SELECT DATEADD(D, 1, dt) FROM DATES WHERE DATEADD(D, 1, dt)<@enddate
	)
	SELECT * FROM DATES
GO


