CREATE PROCEDURE [dbo].[SS_InsertCMMResult]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@ProgramName nvarchar(50),
	@Gap float,
	@instanceNum int,

	@TX FLOAT,
	@TY FLOAT,
	@TZ FLOAT,
	@TC FLOAT,
	@I FLOAT,
	@J FLOAT,
	@K FLOAT,
	@RX FLOAT,
	@RY FLOAT,
	@RZ FLOAT,
	@RC FLOAT,
	@DP float,
	@Family nvarchar(50),
	@SysMirrX bit,
	@SysMirrY bit,
	@Ordem int,
	@FilePath nvarchar(500),
	@ProgramID nvarchar(50),
    @LoginID uniqueidentifier=null,
	@Pos int=1
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @ObjectID uniqueidentifier=(Select top 1 IDObject from ss_program where id=@ProgramID);
	Declare @DGapMod real=(Select top 1 isnull(DGAPModifier,1) from SS_Config);
	declare @ELeGap real=(Select gap from ss_eletrode where id=@ObjectID)

	declare @DGap real;
	--Gap Real no ponto, Usa o GapModifier para sabermos se é para usar Gap Lateral ou nao. e se é para mostrar gap com sinal negativo ou nao.
--	set @DGap=((@ELeGap*ABS(@DGapMod))-@DP)*(ROUND(@DGapMod,0));


	If @DGapMod<>0
 set @DGap=((@ELeGap*ABS(@DGapMod))-@DP)*(ROUND(@DGapMod,0));
 else
 set @DGap=@DP;


	update ss_cmmpoint 
	set TX=@TX, TY=@TY, TZ=@TZ, TC=@TC, I=@I, J=@J, K=@K, RX=@RX, RY=@RY, RZ=@RZ, RC=@RC,dp=@dp,dcad=@DGap
	where id=@ProgramID
		
END
GO


