CREATE PROCEDURE [dbo].[SS_InsertEDMPoints]
	-- Add the parameters for the stored procedure here
	@Client  nvarchar(50),
	@MouldName nvarchar(50),
	@EletrodeName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@Family nvarchar(50),
	@Instance int,
	@ProgramName nvarchar(50),
	@Ordem int,
	@EDMClient nvarchar(50)='',
	@EDMMouldName nvarchar(50)='',
	@EDMPartOf nvarchar (50)='',
	@ProgramType int,
	@EstimatedTime int,
	@ParentID uniqueidentifier,
	@HasChilds bit,

	@PX float,
	@PY float,
	@PZ float,
	@PA float,
	@PB float,
	@PC float,
	@PXIni float,
	@PYIni float,
	@PZIni float,
	@PAIni float,
	@PBIni float,
	@PCIni float,
	@VectorI float,
	@VectorJ float,
	@VectorK float,

	@IDTechnology int,
	@TechnologyText nvarchar(200),
	@TechnologyName nvarchar(100),
	@IDEletrodeType int,

	@FilePath nvarchar(500),
	@ApplyD bit=0,
	@LoginID uniqueidentifier=null,
	@Pos int =1,
	@GIDStr varbinary(MAX) out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	Declare @ObjectID uniqueidentifier;
	--Declare @IDWorkflowItem int;
	Declare @EletrodeID uniqueidentifier;
	declare @programid uniqueidentifier;
	declare @gid uniqueidentifier;
	set @GIDStr=null;
	declare @kind int				
	set @kind=dbo.EDMKind();

	--Defaults
	if (@EDMMouldName='')
		set @EDMMouldName=@MouldName;
	if @EDMClient=''
		set @EDMClient=@Client;
	if @EDMPartOf=''
		set @EDMPartOf=@PartOf;

	-- Se nao vier id de tecnologia vamos procurar pelo nome
	if ((@IDTechnology is null) or (@IDTechnology=0)) and (@TechnologyName is not null) 
		set @IDTechnology= (Select id from SS_PostProcessorEDMTec where code=(@TechnologyName));	

	Declare @SysMirrX bit;
	Declare @SysMirrY bit;
	Declare @IsCopy bit;
	Declare @MultX int;
	Declare @MultY int;
	DECLARE lc CURSOR LOCAL
	FOR select l.id
	from dbo.SS_GetObjectIDByParams(@EDMMouldName,@EDMPartOf,NULL,NULL,null,null,null,null,null,@EDMClient,default) l
	inner join ss_object o on o.id=l.id
	OPEN lc;
	FETCH NEXT FROM lc
		INTO  @objectID;--,@RealPartOf,@RealMouldName;
	--Aqui vai trazer as peças todas sempre.... Dado que estamos a actualizar pontos de erosao até faz sentido... temos de os por todos para as 3 peças, so que para eletrodos diferentes.
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--if @IDWorkflowItem is not null
		begin
	 		DECLARE LocalCursor2 CURSOR LOCAL
			FOR select l.id,o.CopyMirrorX,o.CopyMirrorY,o.id,l.iscopy
				from dbo.SS_GetObjectIDByParams(@MouldName,@EletrodeName,@PartOf,@Gap,@Instance,@Family,NULL,null,null,@Client,default) l 
				inner join ss_object o on o.id=l.id
				inner join ss_eletrode e on e.id=l.id
				left join ss_object p on p.id=o.ParentID
				where (p.CopyFromID is null and p.id=o.ParentID ) 
					or (p.CopyFromID=o.ParentID and p.CopyEletrodes=0) 
					or (p.id=o.ParentID and p.CopyEletrodes=1)  
				order by e.EletrodeFamily asc,e.InstanceNum asc

			OPEN LocalCursor2;
			FETCH NEXT FROM LocalCursor2
				INTO  @EletrodeID,@SysMirrX,@SysMirrY,@gid,@IsCopy;
		
			WHILE @@FETCH_STATUS = 0
			BEGIN
				Set @MultX=1;
				Set @MultY=1;

				if IsNull(@IsCopy,0)=1
				begin
					if @SysMirrX=1
						Set @MultX=-1;	
					if @SysMirrY=1
						Set @MultY=-1;	
				end

				--Inserir m novo programa para associar à task
				set @programid=newid();

				Insert into SS_Program(id,Code,Kind,idObject,FilePath,Position,ProgramType,
					PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,toolid,
					EstimatedTime,ParentID,HasChilds,Ordem) 
				values (@programid,@ProgramName,@kind,@ObjectID,@FilePath,@Pos,@ProgramType	,@PX*@MultX,
					@PY*@MultY,@PZ,@PA,@PB,@PC,@PXIni*@MultX,@PYIni*@MultY,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI,@VectorJ,@VectorK,@EletrodeID,
					@EstimatedTime,	@ParentID,@HasChilds,@Ordem);
				
				
				insert into dbo.SS_EDMPoint(id,	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint) values ( 
					@programid,	@IDTechnology,@TechnologyText,@IDEletrodeType,0);


				FETCH NEXT FROM LocalCursor2
				INTO @EletrodeID,@SysMirrX,@SysMirrY,@gid,@IsCopy;
			END;
		
			CLOSE LocalCursor2;
			DEALLOCATE LocalCursor2;
		end
		FETCH NEXT FROM lc
		INTO @objectid;--,@RealPartOf,@RealMouldName;
	END;
		
	CLOSE lc;
	DEALLOCATE lc;
	
	DECLARE LocalCursor CURSOR LOCAL
	FOR select l.id,o.CopyMirrorX,o.CopyMirrorY,o.id,l.isCopy from dbo.SS_GetObjectIDByParams(@MouldName,@EletrodeName,@PartOf,@Gap,@Instance,@Family,NULL,null,null,@Client,default) l 
		inner join ss_object o on o.id=l.id
	OPEN LocalCursor;
	FETCH NEXT FROM LocalCursor
		INTO  @EletrodeID,@SysMirrX,@SysMirrY,@gid,@IsCopy;
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		Set @MultX=1;
		Set @MultY=1;

		if IsNull(@IsCopy,0)=1
		begin
			if @SysMirrX=1
				Set @MultX=-1;	
			if @SysMirrY=1
				Set @MultY=-1;	
		end


		--Inserir m novo programa para guardar como template para cópias
		set @programid=newid();
		Insert into SS_Program(id,Code,Kind,idObject,FilePath,Position,ProgramType,
			PX,	PY,PZ,PA,PB,PC,PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,VectorI,VectorJ,VectorK,ToolID,
			EstimatedTime,ParentID,HasChilds,Ordem) 
		values (@programid,@ProgramName,@Kind,null,null,@Pos,@ProgramType	,@PX*@MultX,
			@PY*@MultY,@PZ,@PA,@PB,@PC,@PXIni*@MultX,@PYIni*@MultY,@PZIni,@PAIni,@PBIni,@PCIni,@VectorI,@VectorJ,@VectorK,@EletrodeID,
			@EstimatedTime,	@ParentID,@HasChilds,@Ordem);

				insert into dbo.SS_EDMPoint(id,	IDTechnology,TechnologyText,IDEletrodeType,IsTemplatePoint) values ( 
					@programid,	@IDTechnology,@TechnologyText,@IDEletrodeType,1);
		set @GIDStr=convert(varbinary(max),concat(@GIDStr,@ObjectID,';'));


		if @ApplyD=1
		begin
			--Compensação Z de pontos de erosão. Esta compensação é usada para a simulação e para o PP para sabermos exatamente a relação entre o topo do eletrodo e o ponto de erosao
			--Queremos guardar sempre o ponto com o 0 no topo da peça
			--Por isso, nao vem entao temos de a compensar					
			declare @EDMOrigin int;
			set @EDMOrigin=(Select top 1 isnull(EDMPointsOrigin,0) from SS_Config);
			--0 Topo, 1 - Mestra, 2 - parte de baixo do bloco, 3 - fundo da base
			declare @CompZ int;
			set @CompZ=0
			--Mestra
			if @EDMOrigin=1
				set @CompZ=(Select MestraZ from ss_object where id=@EletrodeID);
			--Altura do Bloco Z
			if @EDMOrigin=2
				set @CompZ=(Select -DimCAD_Z from ss_object where id=@EletrodeID);
			--Altura Total - SO FUNCIONA COM BASES POR DEFEITO
			--if @EDMOrigin=3
				--set @CompZ=(Select -(DimCAD_Z+b.DimZ+b.MaterialGap) from ss_object o left join ss_base b on b.num=o.IDMillBase where id=@EletrodeID);

			update SS_Eletrode set 	ToolProgDZ=@CompZ where id=@EletrodeID;
		end
				

		FETCH NEXT FROM LocalCursor
		INTO @EletrodeID,@SysMirrX,@SysMirrY,@gid,@IsCopy;
	END;
		
	CLOSE LocalCursor;
	DEALLOCATE LocalCursor;
		
END
GO


-- ----------------------------
-- procedure structure for UpdateFUPMouldAssetDeadline
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateFUPMouldAssetDeadline]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateFUPMouldAssetDeadline]
GO

CREATE PROCEDURE [dbo].[UpdateFUPMouldAssetDeadline]
	@IDFollowUpItem bigint,
	@IDModule uniqueidentifier
AS
BEGIN
	
	declare @idAsset int = (select top 1 idasset from FollowUpItemMouldFields where IDFollowUpItem = @IDFollowUpItem);
	declare @mouldName nvarchar(max) = (select top 1 name from FollowUpItem where IDFollowUpItem =@IDFollowUpItem);
	if @idAsset is not null
	begin
		update SS_AssetPartValues set Deadline = t.Deadline
		from
		(
			select fup.Deadline, fup.IDAsset IDA
			from FollowUpItemMouldFields fup 
			where IDFollowUpItem = @IDFollowUpItem
		) t
		where IDAsset = t.IDA;

		update Asset set assetName = @mouldName where IDAsset = @idAsset;

		update Asset set IDRelatedEntity = t.IDT, IDRelatedEntityModule = t.IDTM
		from
		(
			select a.IDAsset IDA, fup.IDThirdParty IDT, fup.IDThirdPartyModule IDTM
			from Asset a
			left join FollowUpItem fup on fup.IDFollowUpItem = a.IDFollowUpItem
			where fup.IDFollowUpItem = @IDFollowUpItem
		) t
		where IDAsset = t.IDA

		exec CalculateDeadLineAsset @idAsset;
	end
END
GO


