    set @sql = concat('
		ALTER TABLE [dbo].[DocumentLine]  WITH CHECK ADD  CONSTRAINT [FK_DocumentLineDim', @dimNo ,'_Account] FOREIGN KEY([dim', @dimNo ,'], [dim', @dimNo ,'Module])
