-- ----------------------------
-- procedure structure for SS_InsertMILLProgram
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertMILLProgram]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertMILLProgram]
GO

CREATE PROCEDURE [dbo].[SS_InsertMILLProgram]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@ProgramName nvarchar(50),
	@ProgramPath nvarchar(500),
	@Pos int,
	@Family nvarchar(50),
	@ORdem int,
	@Mirror nvarchar(2),
	@ProgramType int,
	@EstimatedTimeSecs int,
	@ParentID uniqueidentifier,
	@HasChilds bit,

	@FileType int,
	@Feed int,
	@Spindle int,
	@Tool int,
	@TCode nvarchar(50),
	@HolderCode nvarchar(50),
	@TD float,
	@TR float,
	@TH float,
	@TAD float,
	@TZ float,
	@Tol float,
	@Strategy int,
	@StkFin float,
	@XMin float,
	@XMax float,
	@YMin float,
	@YMax float,
	@ZMin float,
	@ZMax float,
	@AMin float,
	@AMax float,
	@BMin float,
	@BMax float,
	@CMin float,
	@CMax float,
	@CadDimX float,
	@CadDimY float,
	@CadDimZ float,
	@MatDimX float,
	@MatDimY float,
	@MatDimZ float,
	@PXIni float,
	@PYIni float,
	@PZIni float,
	@PAIni float,
	@PBIni float,
	@PCIni float,
	@PIniZG01 float,
	@LookAheadUse bit,
	@SplitCondition nvarchar(50),
	@ProgramStartLine int,
	@ProgramLastLine int,
	@NumProgInFile int,
	@FileModificationDate datetime,
    @LoginID uniqueidentifier=null,
	@GIDStr varbinary(MAX) out
AS
BEGIN
	SET NOCOUNT ON;
	declare @mirrX bit;
	declare @mirrY bit;
	set @mirrx=0;
	set @mirry=0;

	if CHARINDEX ('X',@Mirror ,0)>0
		set @mirrx=1;

	if CHARINDEX ('Y',@Mirror ,0)>0
		set @mirrY=1;	

	Declare @ObjectID uniqueidentifier;
	--Declare @IDWorkflowItem int

	Declare @CheckParentID uniqueidentifier=null
	set @GIDStr=null;

	 -- alt para correponder ao ficheiros de familia Acab vs Desb
	 if @Family is not null
	 begin
	  if (@Family='01') or (@Family='1') 
	   set @Family='D'
	  if (@Family='02') or (@Family='2') 
	   set @Family='A'
	 end

	--Update do gap do eletrodo correcto
	if @gap is not null
		UPdate SS_Eletrode set gap=@gap, instancenum=1 where id in (select id from SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,NULL,NULL,@Family,null,@mirrx,@mirry,@Client,default)) and instancenum is null and gap is null;

	-- GET PARTS
	--Verificar se existe algum eletrodo deste tipo mas com gap diferente
	declare @onePArt uniqueidentifier
	set @onePArt= (select top 1 id from SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,NULL,NULL,@Family,null,@mirrx,@mirry,@Client,default))
		--Cria uma nova parte com todos os dados existentes numa original mas com o novo gap ou instancia
	declare @kind int
	set @kind= dbo.CAMKind();

	-- LOOP PARTS
	declare @note nvarchar(100);
	DECLARE LocalCursor2 CURSOR LOCAL
	FOR select o.id
	from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,NULL,@Family,null,@mirrx,@mirry,@Client,default) l 
	left join ss_object o on o.id=l.id
	OPEN LocalCursor2;
	FETCH NEXT FROM LocalCursor2
		INTO  @ObjectID;
	WHILE @@FETCH_STATUS = 0
	BEGIN

		if @ObjectID is not null
		begin
			
				set @CheckParentID=null
				if @HasChilds=0	
					set @CheckParentID= (Select id from sS_program where filepath=@ProgramPath and HasChilds=1 and IDObject=@ObjectID)
				else
					set @GIDStr=convert(varbinary(max),concat(@GIDStr,@ObjectID,';'));

				--VERIFICA SE EXISTE
				if not exists (select id from ss_program where code=@ProgramName and filepath=@ProgramPath and kind=dbo.CAMKind() and programtype=@ProgramType and IDObject=@ObjectID and (idjob is null))
				begin
					--INSERT
					declare @programid uniqueidentifier
					set @programid=newid();

					Insert into SS_Program(id,Code,Kind,Ordem,idObject,FilePath,Position,ProgramType,
					PXIni,PYIni,PZIni,PAIni,PBIni,PCIni,
						EstimatedTime,ParentID,HasChilds,FileType) 
					values (@programid,@ProgramName,@kind,@Ordem,@ObjectID,@ProgramPath,@Pos,@ProgramType,
						@PXIni,@PYIni,@PZIni,@PAIni,@PBIni,@PCIni,
						@EstimatedTimeSecs,	@CheckParentID,@HasChilds,@FileType);

					insert into dbo.SS_MILLProgram(ID,	Feed,Spindle,FactorFeed,FactorSpindle,Tool,TCode,HolderCode,
						TD,TR,TH,TAD,TZ,Tol,Strategy,StkFin,XMin,XMax,YMin,YMax,ZMin,ZMax,AMin,AMax,BMin,BMax,CMin,CMax,PIniZG01,
						LookAheadUse,SplitCondition,ProgramStartLine,ProgramLastLine,NumProgInFile,FileModificationDate) 
						values (@programid,@Feed,@Spindle,1,1,@Tool,@TCode,@HolderCode,
						@TD,@TR,@TH,@TAD,@TZ,@Tol,@Strategy,@StkFin,@XMin,@XMax,@YMin,@YMax,@ZMin,@ZMax,@AMin,@AMax,@BMin,@BMax,@CMin,@CMax,@PIniZG01,
						@LookAheadUse,@SplitCondition,@ProgramStartLine,@ProgramLastLine,@NumProgInFile,@FileModificationDate);
								--
					if @HasChilds=1 
					begin
						if (not (@CadDimX is null)) and (not (@CadDimY is null)) and (not (@CadDimZ is null))
							update ss_object set DimCAD_X=@CadDimX,DimCAD_Y=@CadDimY,DimCAD_Z=@CadDimZ where id=@ObjectID
						if (not (@MatDimX is null)) and (not (@MatDimY is null)) and (not (@MatDimZ is null))
							update ss_object set DimBlock_X=@MatDimX,DimBlock_Y=@MatDimY,DimBlock_Z=@MatDimZ where id=@ObjectID						
						set @note= 'Programa CAM recebido: '+@ProgramName;
						EXEC SS_AddObjectNote	@ObjectID ,	@kind ,	1 ,	@LoginID	,	@note
						--if @Pos>1 
						--	EXEC ChangeVarFromObject @ObjectID,31,1,@LoginID;
						EXEC SS_AfterFileReceived @kind, @ObjectID, @ProgramPath
					end
				end
				else
				begin
--UPDATE
					update ss_program set FilePath=@programPath, FileType=@FileType,[Ordem]=@ORdem,programtype=@ProgramType ,
						EstimatedTime=@EstimatedTimeSecs,ParentID=@CheckParentID,HasChilds=@HasChilds,
						Position=@Pos,PXIni=@PXIni,PYIni=@PYIni,PZIni=@PZIni,PAIni=@PAIni,PBIni=@PBIni,PCIni=@PCIni
					where id in
						(select id from ss_program where code=@ProgramName and filepath=@ProgramPath and kind=@kind and programtype=@ProgramType)
					update dbo.SS_MILLProgram set Feed=@Feed,Spindle=@Spindle,FactorFeed=1,FactorSpindle=1,
						Tool=@Tool,TCode=@TCode,HolderCode=@HolderCode,TD=@TD,TR=@TR,TH=@TH,TAD=@TAD,TZ=@TZ,Tol=@Tol,Strategy=@Strategy,StkFin=@StkFin,
						XMin=@XMin,XMax=@XMax,YMin=@YMin,YMax=@YMax,ZMin=@ZMin,ZMax=@ZMax,PIniZG01=@PIniZG01,
						AMin=@AMin,AMax=@AMax,BMin=@BMin,BMax=@BMax,CMin=@CMin,CMax=@CMax,
						LookAheadUse=@LookAheadUse,SplitCondition=@SplitCondition,ProgramStartLine=@ProgramStartLine,ProgramLastLine=@ProgramLastLine,NumProgInFile=@NumProgInFile,FileModificationDate=@FileModificationDate		
					where id in
						(select id from ss_program where code=@ProgramName and filepath=@ProgramPath and kind=@kind and programtype=@ProgramType)

					set @note= 'Programa CAM Alterado: '+@ProgramName;
					if @HasChilds=1
					begin
						if (not (@CadDimX is null)) and (not (@CadDimY is null)) and (not (@CadDimZ is null))
							update ss_object set DimCAD_X=@CadDimX,DimCAD_Y=@CadDimY,DimCAD_Z=@CadDimZ where id=@ObjectID and DimCAD_X is null and DimCAD_Y is null and DimCAD_Z is null
						if (not (@MatDimX is null)) and (not (@MatDimY is null)) and (not (@MatDimZ is null))
							update ss_object set DimBlock_X=@MatDimX,DimBlock_Y=@MatDimY,DimBlock_Z=@MatDimZ where id=@ObjectID and DimBlock_X is null and DimBlock_Y is null and DimBlock_Z is null		
						EXEC SS_AddObjectNote	@ObjectID ,	@kind ,	1 ,	@LoginID	,	@note

						
						Delete from sS_millprogram where id in (select id from sS_program where filepath=@ProgramPath and HasChilds=0 and (idjob is null) and IDObject=@ObjectID);
						Delete from sS_program where filepath=@ProgramPath and HasChilds=0 and (idjob is null) and IDObject=@ObjectID;
					end

				end;
		end
		FETCH NEXT FROM LocalCursor2
		INTO @ObjectID;
	END;
		
	CLOSE LocalCursor2;
	DEALLOCATE LocalCursor2;
END
GO


-- ----------------------------
-- function structure for GetLeadsChannels
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetLeadsChannels]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetLeadsChannels]
GO

CREATE FUNCTION [dbo].[GetLeadsChannels]
(
	@idLead int
)
RETURNS nvarchar(max)
AS
BEGIN
			
	declare @t nvarchar(max)
	set @t = ''

	declare @u nvarchar(max)

	declare it cursor for 
		select SysWorkRoom.[Name]
		from Leads with(nolock)
			inner join Leads2Channel with(nolock) on Leads.IDLead = Leads2Channel.IDLead
			inner join SysWorkRoom with(nolock) on Leads2Channel.IDChannel = SysWorkRoom.IDWorkRoom
		where
			Leads.IDLead = @idLead

	open it

	fetch next from it into @u

	while @@FETCH_STATUS = 0
	begin
		if @u != '' and not @u is null
		begin
			set @t = CONCAT(@t, case when @t = '' then '' else ', ' end, @u)
		end
		fetch next from it into @u
	end

	close it
	deallocate it

	set @t = TRIM(@t)
	
	RETURN @t
END
GO


-- ----------------------------
-- function structure for WorkflowItemGetState
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[WorkflowItemGetState]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[WorkflowItemGetState]
GO

CREATE FUNCTION [dbo].[WorkflowItemGetState]
(
	@IDWorkflowItem int
)
RETURNS int
AS
BEGIN

--0-InDisponivel
--1-Disponivel
--2-Out
--3-Feito Internamente
--4-Feito Fornedor

	DECLARE @REs int;
	DECLARE @SubContractState int;
	DECLARE @WorkFlowItemDisponibilidade int;
	set @Res=0;

	select @SubContractState=wfi.StateSubContract, @WorkFlowItemDisponibilidade=wfi.disponibilidade 
	from SysWorkflowItem wfi
	where IDWorkflowitem=@IDWorkflowItem;

	if (@SubContractState is null) and (@WorkFlowItemDisponibilidade in (1,2))
		set @res=1;

	if (@SubContractState is null) and (@WorkFlowItemDisponibilidade >2)
		set @res=3;

	if (@SubContractState=1)
		set @res=2;

	if (@SubContractState=2)
		set @res=4;

	-- Return the result of the function
	RETURN @res;

END
GO


