-- ----------------------------
-- procedure structure for RESET_WORKFLOWS
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[RESET_WORKFLOWS]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[RESET_WORKFLOWS]
GO

CREATE PROCEDURE [dbo].[RESET_WORKFLOWS]
	
AS
BEGIN
	DELETE FROM SysWorkflow WHERE IsTemplate <> 1
	DELETE FROM SysWorkflowItem WHERE IDWorkflow NOT IN (SELECT IDWorkflow FROM SysWorkflow)
	DELETE FROM SysWorkflowVars WHERE IDWorkflow NOT IN (SELECT IDWorkflow FROM SysWorkflow)
	DELETE FROM SysWorkflowConditions WHERE IDWorkflowItem NOT IN (SELECT IDWorkflowItem FROM SysWorkflowItem)
	DELETE FROM SysWorkflowConditionsStep WHERE IDCondition NOT IN (SELECT IDWorkflowConditions FROM SysWorkflowConditions)
	DELETE FROM SysWorkflowActions WHERE IDWorkflowItem NOT IN (SELECT IDWorkflowItem FROM SysWorkflowItem)
	DELETE FROM SysWorkflowActionIteractions WHERE IDWorkflowActionIteractions NOT IN (SELECT IDWorkflowAction FROM SysWorkflowActions)
END
GO


-- ----------------------------
-- procedure structure for SS_InsertObjectFile
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertObjectFile]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertObjectFile]
GO

CREATE PROCEDURE [dbo].[SS_InsertObjectFile]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@FilePath nvarchar(500),
	@Family nvarchar(50),
    @LoginID uniqueidentifier=null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @ObjectID uniqueidentifier;

	DECLARE LocalCursor2 CURSOR LOCAL
	FOR select id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,NULL,null,null,null,null,@Client,default);
	OPEN LocalCursor2;
	FETCH NEXT FROM LocalCursor2
		INTO  @ObjectID;
	WHILE @@FETCH_STATUS = 0
	BEGIN
		declare @FileName nvarchar(100)
		declare @Ext nvarchar(30)
		set @ext=reverse(left(reverse(@FilePath),charindex('.',reverse(@FilePath))-1))
		set @FileName=reverse(left(reverse(@FilePath),charindex('\',reverse(@FilePath))-1))

		set @FileName=Left(@FileName,len(@FileName)-len(@Ext)-1)

		--Inserir ficheiro na lista se nao existir já
		declare @id int
		set @id=(Select id from SS_ObjectFiles where FullPath=@FilePath and objectid=@ObjectID)

		if (@id is null)
		begin
			insert into SS_ObjectFiles (Objectid,FullPath,Name,ext)
			values (@Objectid,@FilePath,@FileName,@ext)
		end
		
		declare @note nvarchar(200);
		set @note= 'Lido Ficheiro '+@FileName;
		EXEC SS_AddObjectNote	@ObjectID ,	-1 ,	1 ,	@LoginID	,	@note
		
		FETCH NEXT FROM LocalCursor2
		INTO @ObjectID;
	END;
		
	CLOSE LocalCursor2;
	DEALLOCATE LocalCursor2;
END
GO


-- ----------------------------
-- procedure structure for TestCondition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[TestCondition]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[TestCondition]
GO

CREATE PROCEDURE [dbo].[TestCondition]
	-- Add the parameters for the stored procedure here
	@parent int = 0,
	@oldvalue int = 1,
	@IDWorkflowCondition int = 0, 
	@output int = 0 output 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	CREATE TABLE #Temp(Idx INT IDENTITY PRIMARY KEY, MyValue INT, operator NVARCHAR(50), condition NVARCHAR(50), value NVARCHAR(50))

	INSERT INTO #Temp(MyValue, operator, condition, value)	SELECT IDWorkflowConditionsStep, Operator, Condition, Value FROM [SysWorkflowConditionsStep] WHERE [IDCondition] = @IDWorkflowCondition AND [IDParent] = @parent

	DECLARE @Counter1 INT = 1
	DECLARE @IDVar INT
	DECLARE @MyValue NVARCHAR(50)
	DECLARE @MyOperator NVARCHAR(50)
	DECLARE @MyCondition NVARCHAR(50)
	DECLARE @resultTemp INT = 1;
	SET @resultTemp = @oldvalue;

	WHILE @Counter1 <= (SELECT MAX(Idx) FROM #Temp)
	BEGIN
		SELECT @IDVar = MyValue, @MyOperator = operator, @MyCondition = condition, @MyValue = value FROM #Temp WHERE Idx = @Counter1
		DECLARE @counter NVARCHAR(50) = 0

		SELECT @counter =  currentval FROM SysWorkflowVars
		WHERE 
			IDWorkflowVars = (SELECT IDWorkflowVar FROM SysWorkflowConditionsStep WHERE IDWorkflowConditionsStep = @IDVar) 
			AND 
			IDWorkflow = 
			(
				SELECT [IDWorkflow] FROM SysWorkflowItem WHERE IDWorkflowItem = 
				( 
					SELECT IDWorkflowItem FROM SysWorkflowConditions WHERE [IDWorkflowConditions] = 
					(
						SELECT IDCondition FROM SysWorkflowConditionsStep WHERE IDWorkflowConditionsStep = @IDVar
					)
				)
			)
			/*AND CurrentVal = (SELECT Value FROM SysWorkflowConditionsStep WHERE IDWorkflowConditionsStep = @IDVar) */
		DECLARE @tempResult int = 1;
		IF @MyOperator = 'equal'
			BEGIN
				IF @MyValue = @counter
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'not equal'
			BEGIN
				IF @MyValue <> @counter
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'in'
			BEGIN
				IF CHARINDEX(' '+ @counter + ' ',' ' + REPLACE(REPLACE(''+@MyValue+'',',',' '),'.',' ') + ' ') > 0
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END
	
		IF @MyOperator = 'not in'
			BEGIN
				IF CHARINDEX(' '+ @counter + ' ',' ' + REPLACE(REPLACE(''+@MyValue+'',',',' '),'.',' ') + ' ') <= 0
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'less'
			BEGIN
				IF CAST(@MyValue as float) < CAST(@counter as float)
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'less or equal'
			BEGIN
				IF CAST(@MyValue as float) <= CAST(@counter as float)
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'greater'
			BEGIN
				IF CAST(@MyValue as float) > CAST(@counter as float)
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'greater or equal'
			BEGIN
				IF CAST(@MyValue as float) >= CAST(@counter as float)
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'is null'
			BEGIN
				IF @MyValue IS NULL
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END
		
		IF @MyOperator = 'is not null'
			BEGIN
				IF @MyValue IS NOT NULL
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'is empty'
			BEGIN
				IF @MyValue = ''
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'is not empty'
			BEGIN
				IF @MyValue <> ''
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'contains'
			BEGIN
				IF CHARINDEX(@counter ,@MyValue) > 0
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END
	
		IF @MyOperator = 'doesn\''t contain'
			BEGIN
				IF CHARINDEX(@counter ,@MyValue) <= 0
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'begins with'
			BEGIN
				IF @counter like ''+@MyValue+'%'
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END
	
		IF @MyOperator = 'doesn\''t begin with'
			BEGIN
				IF @counter not like ''+@MyValue+'%'
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END

		IF @MyOperator = 'ends with'
			BEGIN
				IF @counter like '%'+@MyValue+''
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END
	
		IF @MyOperator = 'doesn\''t end with'
			BEGIN
				IF @counter not like '%'+@MyValue+''
					BEGIN
						SET @tempResult = 1
					END
				ELSE
					BEGIN
						SET @tempResult = 0
					END
			END



		/************************/
		/******* AND / OR *******/
		/************************/
		
		IF @MyCondition = 'AND'
			BEGIN
				IF @tempResult = @resultTemp
					BEGIN
						SELECT @resultTemp = @tempResult;
					END
				ELSE
					BEGIN 
						SELECT @resultTemp = 0;
					END
			END
		ELSE
			BEGIN
				IF @tempResult = 0 AND @resultTemp =0
					BEGIN
						SELECT @resultTemp = 0;
					END
				ELSE
					BEGIN
						SELECT @resultTemp = 1;
					END
			END
		SELECT @resultTemp, @MyCondition, @MyOperator, @MyValue as 'Meu Valor', @counter as 'Current Value', @tempResult
		/*SELECT @resultTemp = @tempResult + @resultTemp;*/
		/*SET @output = @counter + @output;*/
		EXEC [dbo].[TestCondition] @parent = @IDVar, @IDWorkflowCondition = @IDWorkflowCondition, @oldvalue = @resultTemp, @output = @resultTemp OUTPUT
		SET @Counter1 = @Counter1 + 1
		
	END
	SELECT @output = @resultTemp
END
GO


-- ----------------------------
-- procedure structure for CloseAllZombieLocks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseAllZombieLocks]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseAllZombieLocks]
GO

CREATE PROCEDURE [dbo].[CloseAllZombieLocks]
	
AS
BEGIN

	SET NOCOUNT ON;

	declare it_CloseAllZombieLocks cursor 
		LOCAL STATIC READ_ONLY FORWARD_ONLY	for 
		select IDLock
		from SysLockRecord
		where IDSession not in (select IDSession from SysSession) and [Status] = 1

	open it_CloseAllZombieLocks

	declare @idLock uniqueidentifier

	fetch next from it_CloseAllZombieLocks into @idLock

	while @@FETCH_STATUS = 0
	begin		
		exec CloseLock @idLock, 99

		fetch next from it_CloseAllZombieLocks into @idLock
	end


	close it_CloseAllZombieLocks
	deallocate it_CloseAllZombieLocks

	--Free Limbo locks from activities and Tasks
	Update Activity set RegisterStatus=0 where RegisterStatus=3
	and 
	 (
	select count(rl.IDLock) 
	from SysLockRecord rl
	where IDRecord=CONVERT(NVARCHAR, Activity.IDActivity) and IDModule=Activity.IDModule and rl.EndDate is  null)=0

	Update SysTask set RegisterStatus=0 where RegisterStatus=3
	and 
	 (
	select count(rl.IDLock) 
	from SysLockRecord rl
	where IDRecord= SysTask.IDTask and IDModule=SysTask.IDModule and rl.EndDate is null)=0


END
GO


-- ----------------------------
-- procedure structure for SS_InsertPRESETResult
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertPRESETResult]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertPRESETResult]
GO

CREATE PROCEDURE [dbo].[SS_InsertPRESETResult]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@DX float,
	@DY float,
	@DZ float,
	@RC float,
	@LoginID uniqueidentifier=null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @Objectid uniqueidentifier
	set @objectid= (select top 1 id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,null,null,null,null,null,null,null,@Client,1));
	if not (@objectid is null)
	begin
		EXEC ChangeVarFromObject @ObjectID,170,@LoginID;
		update ss_object set DispPreset_X=@dx,DispPreset_Y=@dy,DispPreset_Z=@dz,DispPreset_c=@RC where id=@objectid;
		exec SS_AddObjectNote 	@objectid,	1,1,@LoginID,'Recebidos resultados PRESET'		
	end

END
GO


-- ----------------------------
-- procedure structure for UpdateOpportunityAndLeadRelationshipFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateOpportunityAndLeadRelationshipFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateOpportunityAndLeadRelationshipFields]
GO

CREATE PROCEDURE [dbo].[UpdateOpportunityAndLeadRelationshipFields]
(
	@IDRecord int,	
	@IDModule uniqueidentifier
)
as 
begin

	update FollowUpItem set IDLead = t.Lead, IDLeadModule = t.LeadModule
	from(
		select top 1 IDLead as Lead, IDModule as LeadModule, 
		IDOpportunity as FollowUpIT, IDOpportunityModule as FollowUpITModule  
		from Leads
		where IDLead = @IDRecord and IDModule = @IDModule 
		and IDOpportunity is not null and IDOpportunityModule is not null
	) t
	where IDFollowUpItem = t.FollowUpIT and IDModule = t.FollowUpITModule;

	update FollowUpItem set IDLead = null, IDLeadModule = null
	from(
		select l.IDLead as Lead, l.IDModule as LeadModule, 
		fup.IDFollowUpItem as FollowUpIT, fup.IDModule as FollowUpITModule  
		from Leads l
		inner join FollowUpItem fup on fup.IDLead = @IDRecord and fup.IDLeadModule = @IDModule
		where l.IDLead = @IDRecord and l.IDModule = @IDModule 
		and (IDOpportunity is null or IDOpportunity <> fup.IDFollowUpItem)
	) t
	where IDFollowUpItem = t.FollowUpIT and IDModule = t.FollowUpITModule;


	update Leads set IDOpportunity = t.FollowUpIT, IDOpportunityModule = t.FollowUpITModule
	from(
		select top 1 IDLead as Lead, IDLeadModule as LeadModule, 
		IDFollowUpItem as FollowUpIT, IDModule as FollowUpITModule  
		from FollowUpItem
		where IDFollowUpItem = @IDRecord and IDModule = @IDModule 
		and IDLead is not null and IDLeadModule is not null 
		and IDModule in(
			select IDModule from GetModulesRec('596A893B-06E8-48E0-B03C-4E33AA9FE9F1')
		)
	) t
	where IDLead = t.Lead and IDModule = t.LeadModule;

	update Leads set IDOpportunity = null, IDOpportunityModule = null
	from(
		select l.IDLead as Lead, l.IDModule as LeadModule, 
		IDOpportunity as FollowUpIT, IDOpportunityModule as FollowUpITModule  
		from FollowUpItem fup
		inner join Leads l on l.IDOpportunity = @IDRecord and l.IDOpportunityModule = @IDModule
		where fup.IDFollowUpItem = @IDRecord and fup.IDModule = @IDModule 
		and (fup.IDLead is null or fup.IDLead <> l.IDLead)
	) t
	where IDLead = t.Lead and IDModule = t.LeadModule;

end
GO


-- ----------------------------
-- procedure structure for SS_InsertSTLFile
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertSTLFile]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertSTLFile]
GO

CREATE PROCEDURE [dbo].[SS_InsertSTLFile]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@Gap float,
	@OldfilePath nvarchar(500),
	@FilePath nvarchar(500),
	@Family nvarchar(50),
    @LoginID uniqueidentifier=null,
	@CADDimX float out,
	@CADDimY float out,
	@CADDimZ float out,
	@HolderDimX float out,
	@HolderDimY float out,
	@HolderDimZ float out,
	@HolderMaterialGap float out,
	@HolderKindName nvarchar(50) out,
	@HolderKindID uniqueidentifier out,
	@MLocZ float out,
	@RotC float out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @ObjectID uniqueidentifier;
	set @CADDimX= null;

	DECLARE LocalCursor2 CURSOR LOCAL
	FOR select id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,NULL,null,null,null,null,@Client,default);
	OPEN LocalCursor2;
	FETCH NEXT FROM LocalCursor2
		INTO  @ObjectID;
	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Update
		update ss_object set stlfileMILL=@FilePath,stlfileCMM=@FilePath,stlfileEDM=@FilePath where id=@ObjectID
		--Ler dados OUT
		if @CADDimX is null
			Select 
				@CADDimX=DimCAD_X,
				@CADDimY=DimCAD_Y,
				@CADDimZ=DimCAD_Z,
				@MLocZ=MestraZ,
				@HolderDimX=ht.DimX,
				@HolderDimY=ht.DimY,
				@HolderDimZ=ht.DimZ,
				@HolderMaterialGap=ht.MaterialGap,
				@HolderKindName=ht.Code,
				@HolderKindID=ht.ID,
				@RotC=MILLRC
			from ss_object o
			left join SM_HolderTemplate ht on ht.ID=o.IDMillBase
			--left join SM_Holder h on h.id=o.IDHolder
			--left join SM_HolderTemplate ht on ht.ID=h.HolderTemplate
			where o.id=@ObjectID

		--Nota
		declare @note nvarchar(200);
		set @note= 'Lido Ficheiro 3D';
		EXEC SS_AddObjectNote	@ObjectID ,	-1 ,	1 ,	@LoginID	,	@note
		FETCH NEXT FROM LocalCursor2
		INTO @ObjectID;
	END;
		
	CLOSE LocalCursor2;
	DEALLOCATE LocalCursor2;
END
GO


-- ----------------------------
-- procedure structure for SS_InsertWorkingTime
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_InsertWorkingTime]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_InsertWorkingTime]
GO

CREATE PROCEDURE [dbo].[SS_InsertWorkingTime]
	@ObjectID uniqueidentifier,
	@OperationID int,
	@Kind int,
	@IDRecord int,
	@Date nvarchar(50),
	@Start bit=0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	--Sacar id de WFI desta peça
	Declare @WFI int
	set @WFI= (Select IDWorkflowItem from SysWorkflowItem where IDRegisto=@ObjectID and WorkflowItemKind=@OperationID)
	declare @OpenRecord int
	declare @NewRecord int
	if @wfi is not null
	begin	
		--COnverter a string @Date para um datetime
		declare @realDatetime datetime
		set @realDatetime= convert(datetime,@Date,20)
		--set @realDatetime=getdate();
		if @Start=0
		begin	
			--Procurar o registo a fechar			
			set @OpenRecord = (select id from SysWorkflowItemWorkingTimes where [IDWorkflowItem]=@WFI and [Kind]=@Kind and idrecord=@IDRecord and [stop] is null);
			--
			if @OpenRecord is not null
			begin
				update SysWorkflowItemWorkingTimes set [stop]=@realDatetime  where id=@OpenRecord
				exec ChangeVarFromObject @ObjectID, 201, 0, 0, '', @OperationID
				exec ChangeVarFromObject @ObjectID, 50, 1, 0, '', @OperationID
			end		
		end

		if @Start=1
		begin
			----Procurar o registo a fechar			
			--set @OpenRecord = (select id from SysWorkflowItemWorkingTimes where [IDWorkflowItem]=@WFI and [Kind]=@Kind and idrecord=@IDRecord and [stop] is null);
			----
			--if @OpenRecord is not null
			--	update SysWorkflowItemWorkingTimes set [stop]=start  where id=@OpenRecord

			--Se for um start entao vamos criar um novo registo
			set @NewRecord = (select id from SysWorkflowItemWorkingTimes where [IDWorkflowItem]=@WFI and [Kind]=@Kind and idrecord=@IDRecord and Start=@realDatetime);
			--
			if @NewRecord is null
			begin
				insert into SysWorkflowItemWorkingTimes( IDWorkflowItem, Kind, IDRecord, Start,Stop) values (@WFI,@Kind,@IDRecord,@realDatetime,null);
				exec ChangeVarFromObject @ObjectID, 201, 1, 0, '', @OperationID
			end

		end
	end

END
GO


-- ----------------------------
-- procedure structure for UpdateEmployeeAccounts
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateEmployeeAccounts]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateEmployeeAccounts]
GO

CREATE PROCEDURE [dbo].[UpdateEmployeeAccounts]
(
	@IDAccount int,
	@IDModule uniqueidentifier
)
AS
BEGIN
	
	return;
	declare @Status int; 
	declare @StartDate datetime;
	declare @EndDate datetime;
	declare @IDContact int;
	declare @IDContactModule uniqueidentifier;

	select @Status = Status , @StartDate = StartDate,  @EndDate = EndDate, @IDContact = IDContact, @IDContactModule = IDContactModule
	from Account 
	where IDAccount = @IDAccount and IDModule = @IDModule;

	update Account set Status = case when @Status = 1 then 1 else 0 end, 
	StartDate = case when StartDate < @StartDate then @StartDate else StartDate end,
	EndDate = case when EndDate > @EndDate then @EndDate else EndDate end
	where IDParent = @IDAccount and IDParentModule = @IDModule  
	and IDContact = @IDContact and IDContactModule = @IDContactModule;
END
GO


-- ----------------------------
-- procedure structure for UpdateAccountStatus
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAccountStatus]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAccountStatus]
GO

CREATE PROCEDURE [dbo].[UpdateAccountStatus]
(
	@IDAccount int,
	@IDModule uniqueidentifier
)
AS
BEGIN
	return
	update Account set Status = case when (
		(StartDate is not null and GETDATE() < StartDate)
		or (EndDate is not null and GETDATE() > EndDate)
		) then 1 
		else Status end
		where IDAccount =  @IDAccount and IDModule = @IDModule;
END
GO


