-- ----------------------------
-- procedure structure for SysBookMark_Update
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysBookMark_Update]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SysBookMark_Update]
GO

CREATE PROCEDURE [dbo].[SysBookMark_Update]
    @IDLogin uniqueidentifier = NULL,
    @IDResource uniqueidentifier = NULL,
    @IDChat int,
    @IDChannel uniqueidentifier,
    @Action tinyint = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ExistingID uniqueidentifier;
    DECLARE @IsBookMarked bit;

    /* Validate action */
    IF @Action NOT IN (0, 1, 2)
    BEGIN
        RAISERROR('Invalid @Action. Allowed values are 0=Toggle, 1=Mark, 2=Unmark.', 16, 1);
        RETURN;
    END;

    /* Validate that at least one identity reference was provided */
    IF @IDLogin IS NULL AND @IDResource IS NULL
    BEGIN
        RAISERROR('Either IDLogin or IDResource must be provided.', 16, 1);
        RETURN;
    END;

    /* Validate IDLogin existence */
    IF @IDLogin IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.SysLogin
           WHERE IDLogin = @IDLogin
       )
    BEGIN
        RAISERROR('The provided IDLogin does not exist in SysLogin.', 16, 1);
        RETURN;
    END;

    /* Validate IDResource existence */
    IF @IDResource IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM dbo.SysResources
           WHERE ResourceId = @IDResource
       )
    BEGIN
        RAISERROR('The provided IDResource does not exist in SysResources.', 16, 1);
        RETURN;
    END;

    /* Validate IDChat existence */
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.SysChat
        WHERE IDChat2 = @IDChat
    )
    BEGIN
        RAISERROR('The provided IDChat does not exist in SysChat.', 16, 1);
        RETURN;
    END;

    /* Validate IDChannel existence */
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.SysWorkRoom
        WHERE IDWorkRoom = @IDChannel
    )
    BEGIN
        RAISERROR('The provided IDChannel does not exist in SysWorkRoom.', 16, 1);
        RETURN;
    END;

    BEGIN TRANSACTION;

    /* Search existing bookmark */
    SELECT @ExistingID = B.ID
    FROM dbo.SysBookMark AS B WITH (UPDLOCK, HOLDLOCK)
    WHERE B.IDChat = @IDChat
        AND B.IDChannel = @IDChannel
        AND (B.IDLogin = @IDLogin OR B.IDResource = @IDResource);

    /* Action = Toggle */
    IF @Action = 0
    BEGIN
        IF @ExistingID IS NOT NULL
        BEGIN
            DELETE FROM dbo.SysBookMark
            WHERE ID = @ExistingID;

            SET @IsBookMarked = 0;
        END
        ELSE
        BEGIN
            INSERT INTO dbo.SysBookMark
            (
                IDLogin,
                IDResource,
                IDChat,
                IDChannel,
                DateMarked
            )
            VALUES
            (
                @IDLogin,
                @IDResource,
                @IDChat,
                @IDChannel,
                GETDATE()
            );

            SET @IsBookMarked = 1;
        END;
    END;

    /* Action = Mark */
    IF @Action = 1
    BEGIN
        IF @ExistingID IS NULL
        BEGIN
            INSERT INTO dbo.SysBookMark
            (
                IDLogin,
                IDResource,
                IDChat,
                IDChannel,
                DateMarked
            )
            VALUES
            (
                @IDLogin,
                @IDResource,
                @IDChat,
                @IDChannel,
                GETDATE()
            );
        END;

        SET @IsBookMarked = 1;
    END;

    /* Action = Unmark */
    IF @Action = 2
    BEGIN
        IF @ExistingID IS NOT NULL
        BEGIN
            DELETE FROM dbo.SysBookMark
            WHERE ID = @ExistingID;
        END;

        SET @IsBookMarked = 0;
    END;

    COMMIT TRANSACTION;

    /* Return result */
    SELECT @IsBookMarked AS IsBookMarked;
END;
GO


