-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAllAccountsStatus]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAllAccountsStatus]
GO

CREATE PROCEDURE [dbo].[UpdateAllAccountsStatus]
AS
BEGIN
	return;
	declare it cursor for
	select IDAccount, IDModule 
	from Account 
	where ((StartDate is not null and GETDATE() < StartDate)
		or (EndDate is not null and GETDATE() > EndDate) 
		) and (Status = 0 or Status is null)

	open it;

	declare @idrecord int, @idmodule uniqueidentifier

	fetch next from it into @idrecord, @idmodule

	while @@FETCH_STATUS = 0
	begin
		print concat('update account status ', @idrecord, ' ', @idmodule)
		exec [UpdateAccountStatus] @idrecord, @idmodule
		if(@idmodule in (select idmodule from GetModulesRec('C9C1E47C-20CF-4988-82D0-257389FE9213')))
		begin
			exec UpdateEmployeeAccounts @idrecord, @idmodule;
		end
		fetch next from it into @idrecord, @idmodule
	end

	close it;
	deallocate it;
END
GO


-- ----------------------------
-- function structure for Split
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Split]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[Split]
GO

CREATE FUNCTION [dbo].[Split]  
(  
 @RowData nvarchar(MAX),
 @SplitOn nvarchar(5)
)    
RETURNS @ReturnValue TABLE   
(Data NVARCHAR(MAX))   
AS
BEGIN
 Declare @Counter int
 Set @Counter = 1 
 While (Charindex(@SplitOn,@RowData)>0) 
 Begin  
  Insert Into @ReturnValue (data)  
  Select Data = 
      ltrim(rtrim(Substring(@RowData,1,Charindex(@SplitOn,@RowData)-1)))
  Set @RowData = 
      Substring(@RowData,Charindex(@SplitOn,@RowData)+1,len(@RowData)) 
  Set @Counter = @Counter + 1  
 End 
 Insert Into @ReturnValue (data)  
 Select Data = ltrim(rtrim(@RowData))  
 Return  
END
GO


