-- ----------------------------
-- procedure structure for sp_UpdateTaskResourceLinkState
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_UpdateTaskResourceLinkState]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_UpdateTaskResourceLinkState]
GO

CREATE PROCEDURE [dbo].[sp_UpdateTaskResourceLinkState]
    @IDTask UNIQUEidentifier
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        --  Step 1: Set LinkState = 1 (Creator without Participant or Responsible)
        UPDATE trr
        SET trr.LinkState = 1
        FROM SysTaskResourceRole trr
        WHERE trr.Kind = 2  -- Criador
          AND trr.LinkState = 0
          AND trr.IDTask = @IDTask
          AND NOT EXISTS (
              SELECT 1
              FROM SysTaskResourceRole trr2
              WHERE trr2.IDTask = trr.IDTask
                AND trr2.Kind IN (0, 3)  -- Participant or Responsible
          );

        --  Step 2: Set LinkState = 0 (Creator with active Participant or Responsible)
        UPDATE trr
        SET trr.LinkState = 0
        FROM SysTaskResourceRole trr
        WHERE trr.Kind = 2  -- Criador
          AND trr.IDTask = @IDTask
          AND EXISTS (
              SELECT 1
              FROM SysTaskResourceRole trr2
              WHERE trr2.IDTask = trr.IDTask
                AND trr2.Kind IN (0, 3)  -- Participant or Responsible
                AND trr2.IDResource IS NOT NULL
          );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        -- Error handling
        DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT;
        SELECT @ErrMsg = ERROR_MESSAGE(), @ErrSeverity = ERROR_SEVERITY();
        RAISERROR(@ErrMsg, @ErrSeverity, 1);
    END CATCH
END;
GO


