-- ----------------------------
-- procedure structure for CloseObsoleteSessions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseObsoleteSessions]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseObsoleteSessions]
GO

CREATE PROCEDURE [dbo].[CloseObsoleteSessions]
	
AS
BEGIN	
	SET NOCOUNT ON;

	declare @wpf nvarchar(200)
	declare @and nvarchar(200)

	select @wpf = MinWpfClientVersion, @and = MinAndroidVersion
	from SysSettings

	print concat('min wpf ', @wpf, ', min android ', @and)

   declare it cursor for SELECT IDSession, ClientVersion
						   FROM dbo.ActiveSessions
						   WHERE ClientVersion like 'WPF.%' AND ClientVersion not like concat('%',@wpf)
						   union
						   SELECT IDSession, ClientVersion
						   FROM dbo.ActiveSessions
						   WHERE ClientVersion like 'Android.%' AND ClientVersion not like concat('%',@and)
	
	open it
	declare @idS uniqueidentifier
	declare @clientV nvarchar(200)
	fetch next from it into @idS, @clientV
	while @@FETCH_STATUS = 0
	begin
		print concat(' idSession ', @idS, ' clientVersion ', @clientV)
		Exec CloseSession @idS, 1
		fetch next from it into @idS, @clientV
	end

	close it
	deallocate it
   

END
GO


-- ----------------------------
-- procedure structure for UpdatePeopleCompanyList
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdatePeopleCompanyList]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdatePeopleCompanyList]
GO

CREATE PROCEDURE [dbo].[UpdatePeopleCompanyList]
(
	@IDRecord int,	
	@IDModule uniqueidentifier
)
as 
begin
	SET NOCOUNT ON;

	declare @IDRecEntity int; 
	declare @Companies nvarchar(max);
	declare @TEMP table (IDRecEntity int, ShortName nvarchar(max));

	with RecEntity as(
		select distinct e.organizationid
		from Entity e 
		inner join Entity2Entity e2e on e2e.ID = @IDRecord and e2e.IDModule = @IDModule 
		and e2e.IDRecEntityModule = '28BEE890-28FA-45E2-8D51-8D30F36C4F04' and e2e.IDRecEntity = e.organizationid
		union all
		select e.organizationid
		from Entity e 
		inner join Entity2Entity e2e on e2e.ID = @IDRecord and e2e.IDModule = @IDModule 
		and e2e.IDRecEntitychildModule = '28BEE890-28FA-45E2-8D51-8D30F36C4F04' and e2e.IDRecEntitychild = e.organizationid
	)
	insert into @TEMP
	select e2e.IDRecEntity, comp.ShortName
	from entity2entity e2e
	inner join Entity comp on comp.organizationid = e2e.IDRecEntityChild and e2e.IDRecEntityChildModule = comp.IDModule
	where e2e.IDRecEntity in( select distinct organizationid from RecEntity) and e2e.Active = 1
	union all
	select e2e.IDRecEntityChild, comp.ShortName
	from entity2entity e2e
	inner join Entity comp on comp.organizationid = e2e.IDRecEntity and e2e.IDRecEntityModule = comp.IDModule
	where e2e.IDRecEntityChild in( select distinct organizationid from RecEntity) and e2e.Active = 1


	declare it_p2c cursor for 
		select * from @TEMP order by IDRecEntity, ShortName;
	open it_p2c

	fetch next from it_p2c into @IDRecEntity, @Companies;
	declare @AllCompanies nvarchar(max) = '';

	while @@FETCH_STATUS = 0	
	begin
		if(trim(@AllCompanies) = '' )
		begin
			set @AllCompanies = @Companies;
		end
		else
		begin
			set @AllCompanies = CONCAT(@AllCompanies, '; ', @Companies) ;
		end
		fetch next from it_p2c into @IDRecEntity, @Companies;
	end

	close it_p2c
	deallocate it_p2c
			
	update Entity set Companies = @AllCompanies where organizationid = @IDRecEntity
end
GO


-- ----------------------------
-- procedure structure for sp_UpdateActivityResourceLinkState
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_UpdateActivityResourceLinkState]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sp_UpdateActivityResourceLinkState]
GO

CREATE PROCEDURE [dbo].[sp_UpdateActivityResourceLinkState]
    @IDActivity INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -------------------------------------------------------
        -- Step 1: Set LinkState = 1
        -- Criadores (Kind = 2) without any Participant/Responsible (Kind 0 or 3)
        -------------------------------------------------------
        UPDATE arr
        SET arr.LinkState = 1
        FROM SysActivityResourceRoleActivity arr
        INNER JOIN Activity a ON a.IDActivity = arr.IDActivity
        WHERE arr.Kind = 2  -- Criador
          AND arr.LinkState = 0
          AND arr.IDActivity = @IDActivity
          AND NOT EXISTS (
              SELECT 1
              FROM SysActivityResourceRoleActivity arr2
              WHERE arr2.IDActivity = arr.IDActivity
                AND arr2.Kind IN (0, 3)
                AND arr2.IDResource IS NOT NULL
          );

        -------------------------------------------------------
        -- Step 2: Set LinkState = 0
        -- Criadores (Kind = 2) having at least one Participant/Responsible
        -------------------------------------------------------
        UPDATE arr
        SET arr.LinkState = 0
        FROM SysActivityResourceRoleActivity arr
        INNER JOIN Activity a ON a.IDActivity = arr.IDActivity
        WHERE arr.Kind = 2  -- Criador
          AND arr.IDActivity = @IDActivity
          AND EXISTS (
              SELECT 1
              FROM SysActivityResourceRoleActivity arr2
              WHERE arr2.IDActivity = arr.IDActivity
                AND arr2.Kind IN (0, 3)
                AND arr2.IDResource IS NOT NULL
          );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT;
        SELECT @ErrMsg = ERROR_MESSAGE(), @ErrSeverity = ERROR_SEVERITY();
        RAISERROR(@ErrMsg, @ErrSeverity, 1);
    END CATCH
END;
GO


-- ----------------------------
-- procedure structure for SS_RefreshObjectCMMResults
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_RefreshObjectCMMResults]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_RefreshObjectCMMResults]
GO

CREATE PROCEDURE [dbo].[SS_RefreshObjectCMMResults]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@MouldName nvarchar(50),
	@ObjectName nvarchar (50),
	@PartOf nvarchar (50),
	@instanceNum int,
	@Gap float,
    @DX float,
    @DY float,
    @DZ float,
    @EmpZ float,
    @EmpC float,
    @DMin float,
    @DMax float,
    @RealZ float,
    @DAvg float,
	@PrtRotA float,
	@Family nvarchar(50),
	@Mirror nvarchar(2),
	@ProgramID nvarchar(50),
    @LoginID uniqueidentifier=null,
	@GIDStr varbinary(MAX) out
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @SysMirrX bit
	set @SysMirrX=0
	if @Mirror='X'
		set @SysMirrX=1
	declare @SysMirrY bit
	set @SysMirrY=0
	if @Mirror='Y'
		set @SysMirrY=1

	set @GIDStr=null;

	declare @ObjectID uniqueidentifier
	set @objectid =(select top 1 id from dbo.SS_GetObjectIDByParams(@MouldName,@ObjectName,@PartOf,@Gap,@instanceNum,@Family,null,@SysMirrX,@SysMirrY,@Client,1))
    -- Insert statements for procedure here
	update ss_object set CMMDX=@DX,CMMDY=@DY,CMMDZ=@DZ,
	CMMEmpC=@EmpC,CMMEmpZ=@EmpZ,CMMDMin=@DMin,CMMDMax=@DMax,CMMRealZ=@RealZ,CMMDAvg=@DAvg
	where id = @ObjectID;

	set @GIDStr=convert(varbinary(max),concat(@GIDStr,@ObjectID,';'));

	declare @IDJob int
	set @IDJob= (Select idjob from ss_program where id=@ProgramID);
	if @IDJob is not null 
	begin
		declare @exists int=0;
		set @exists = (Select count(*) from sysjobcmmresults where idjob=@IDJob);

		if @exists>0 
			update sysjobcmmresults set CMMDX=@DX,CMMDY=@DY,CMMDZ=@DZ,MEASUREROTATION=@PrtRotA,
			CMMEmpC=@EmpC,CMMEmpZ=@EmpZ,CMMDMin=@DMin,CMMDMax=@DMax,CMMRealZ=@RealZ,CMMDAvg=@DAvg
			where idjob=@IDJob
		else
			insert into sysjobcmmresults(IDJob, IDObject, CMMDX, CMMDY, CMMDZ, CMMEmpC, CMMEmpZ, CMMDMin, CMMDMax,  CMMRealZ,CMMDAvg,MEASUREROTATION)
			values (@IDJob,@ObjectID,@DX,@DY,@DZ,@EmpC,@EmpZ,@DMin,@DMax,@RealZ,@DAvg,@PrtRotA);
	end;

	--Valida resultados e desvios segundo as regras
	Exec SS_ValidateCMMResult @ObjectID,@IDJob

	Exec [SS_AddObjectNote] @ObjectID, 6, 1, @LoginID, 'Resultados de CMM recebidos'
	--exec [dbo].[ChangeVarFromObject] @ObjectID, 70, 1, @LoginID, 'Resultados de CMM recebidos', 6

END
GO


-- ----------------------------
-- procedure structure for FixRecordNumbering
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FixRecordNumbering]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[FixRecordNumbering]
GO

CREATE PROCEDURE [dbo].[FixRecordNumbering]
	@TableName nvarchar(100),
	@PkName nvarchar(100),
	@CodeName nvarchar(100),
	@IdModule uniqueidentifier,
	@ForceModule bit
AS
BEGIN	
	SET NOCOUNT ON;
		
    declare @sql nvarchar(max)
	set @sql = concat('insert into #FixRecordNumbering_tempTable select [',@PkName,']', 
		case when @IdModule is null then ', IDModule' else ', NULL as IDModule' end ,
		' from [',@TableName,'] where isnull([',@CodeName,'], '''') = ''''')

	
	declare @it_id nvarchar(50), @it_idmodule uniqueidentifier
	CREATE TABLE #FixRecordNumbering_tempTable(id nvarchar(50), idmodule uniqueidentifier null)

	if @ForceModule = 1 and not @IdModule is null
	begin
		set @sql = concat(@sql, ' and IDModule = ''' , @IdModule, '''')
	end

	exec sp_executesql @sql

	--select @sql
	--select count(*) from #FixRecordNumbering_tempTable

	declare it cursor for 
		select id, idmodule
		from #FixRecordNumbering_tempTable
			
	open it
	fetch next from it into @it_id, @it_idmodule
	while @@FETCH_STATUS = 0
	begin
		declare @idR nvarchar(50) = @it_id
		declare @idM uniqueidentifier = @it_idmodule

		if not @IdModule is null
		begin
			set @idM = @IdModule
		end

		--print concat('exec for ', @idR, ' ', @idM)

		declare @mask nvarchar(100)
		declare @CodeValue nvarchar(200)
		declare @currentcounter int

		select @mask = Mask, @currentcounter = CurrentCounter
		from SysModule
		where IDModule = @idM

		set @currentcounter = ISNULL(@currentcounter, 0) + 1
		set @CodeValue = @mask

		-- eval mask with updated counter
		-- WARNING this should replaced with expression parse proper

		declare @idxstartC int = charindex('#', @CodeValue)
		declare @idxendC int = charindex(')', @CodeValue, @idxStartC)

		if @idxstartC > 0 and @idxendC > 0
		begin
			declare @substrExpr nvarchar(100) = substring(@CodeValue, @idxStartC, @idxendC)

			if CHARINDEX('c', @substrExpr) = 3 and CHARINDEX(':', @substrExpr) = 4 
			begin
				declare @nzeroes int = len(@substrExpr) - 5
				--print concat('nzeroes: ', @nzeroes)

				declare @format nvarchar(100)
				set @format = ''

				while @nzeroes > 0
				begin
					set @format = concat(@format, '0')
					set @nzeroes =@nzeroes -1
				end

				set @CodeValue = REPLACE(@CodeValue, @substrExpr, format(@currentcounter, @format))
			end
		end

		--print concat('codevalue is ', @CodeValue)

		-- update code for record
		set @sql = concat('update [',@TableName,'] set [',@CodeName,'] = ''', @CodeValue,''' where [',@PkName,'] = ''', @idR, '''')

		exec sp_executesql @sql

		-- update module config
		update SysModule
		set CurrentCounter = @currentcounter,
			LastUpdated = getdate()
		where IDModule = @idM

		fetch next from it into @it_id, @it_idmodule
	end

	close it
	deallocate it

	DROP TABLE #FixRecordNumbering_tempTable
END
GO


