-- function structure for SS_CheckIFPartInFreePosic
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CheckIFPartInFreePosic]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
