-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateMovementBalancesFromDate]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateMovementBalancesFromDate]
GO

CREATE PROCEDURE [dbo].[UpdateMovementBalancesFromDate]
@IDRecord int,
@IDModule uniqueidentifier,
@MinDate datetime
AS
BEGIN

with n(
[IDPocValue], 
IDRecord, IDRecordModule,
IDParent, Depth, hierarchy,
[IDLine], [Description], [DateRecord],
TypeOfValue,
[ValueFinAct],[ValueFinPlan],
[ValueDocAct], [ValueDocPlan],
[ValueTransAct],[ValueTransPlan],
[ValueDebt],
[QtyFinAct], [QtyFinPlan], 
[QtyDocAct], [QtyDocPlan], 
[QtyTransAct], [QtyTransPlan], 

[QtyActualStock],
[QtyOrderedByCustomer],
[QtyOrderedToSupplier],
[QtyInProduction],
[QtyInConsumption],
[QtyReserved],

IDSrc, IDSrcModule, 
Compensation, IDSysActivityType,
IDSysAccountMovementType, MovementMode, 
SumDate, ParentMovementMode, CreatedOn, MovementRootType, idGrandParent, 
TotalCredit, TotalDebit, [QtyPendingProduction]) as 
( 
select 
	[IDPocValue], IDRecord, IDRecordModule,IDParent,0, CAST([IDPocValue] as nvarchar) as Hierarchy,
	[IDLine], [Description], [DateRecord],
	TypeOfValue,
	[ValueFinAct],[ValueFinPlan],
	[ValueDocAct], [ValueDocPlan],
	[ValueTransAct],[ValueTransPlan],

	[ValueDebt],

	[QtyFinAct], [QtyFinPlan], 
	[QtyDocAct], [QtyDocPlan], 
	[QtyTransAct], [QtyTransPlan], 

	[QtyActualStock],
	[QtyOrderedByCustomer],
	[QtyOrderedToSupplier],
	[QtyInProduction],
	[QtyInConsumption],
	[QtyReserved],

	IDSrc, IDSrcModule,
	Compensation, IDSysActivityType,
	IDSysAccountMovementType, MovementMode,
	DateRecord, null, CreatedOn,MovementRootType, null,
	TotalCredit, TotalDebit, [QtyPendingProduction]
from [SysPocValue] r
WHERE MovementMode = 3 AND IDRecordModule = @idModule AND IDRecord = @idRecord and not @idModule is null and not @idrecord is null and MovementRootType = 0
and Compensation = 0		

union all
select 
	p.[IDPocValue], p.IDRecord, p.IDRecordModule,p.IDParent,1, 
	cast(CAST(r.[IDPocValue] as nvarchar) + '.' + CAST(p.[IDPocValue] as nvarchar) as nvarchar),
	p.[IDLine], p.[Description], p.[DateRecord],
	p.TypeOfValue,

	p.[ValueFinAct],p.[ValueFinPlan],
	p.[ValueDocAct], p.[ValueDocPlan],
	p.[ValueTransAct],p.[ValueTransPlan],

	p.[ValueDebt],

	p.[QtyFinAct], p.[QtyFinPlan], 
	p.[QtyDocAct], p.[QtyDocPlan], 
	p.[QtyTransAct], p.[QtyTransPlan], 

	p.[QtyActualStock],
	p.[QtyOrderedByCustomer],
	p.[QtyOrderedToSupplier],
	p.[QtyInProduction],
	p.[QtyInConsumption],
	p.[QtyReserved],

	p.IDSrc, p.IDSrcModule,
	p.Compensation, p.IDSysActivityType,
	p.IDSysAccountMovementType, p.MovementMode,
	p.DateRecord, r.MovementMode , p.CreatedOn, p.MovementRootType, null,
	p.TotalCredit, p.TotalDebit,
	p.[QtyPendingProduction]
	from [SysPocValue] p
	Inner join [SysPocValue] r on r.IDPocValue = p.IDParent 
	WHERE r.MovementMode = 3 AND p.IDRecordModule = @idModule AND p.IDRecord = @idRecord and not @idModule is null and not @idrecord is null and p.MovementRootType = 0
	and r.IDRecord = @IDrecord and r.IDRecordModule = @IDmodule
	and p.Compensation = 0
	--union all

	--select 
	--nplus1.[IDPocValue], 
	--nplus1.IDRecord, nplus1.IDRecordModule,
	--nplus1.IDParent, Depth + 1, 
	--cast(n.hierarchy + '.' + CAST(nplus1.[IDPocValue] as nvarchar) as nvarchar),
	--nplus1.[IDLine], 
	--nplus1.[Description], 
	--nplus1.[DateRecord],
	--nplus1.TypeOfValue,

	--nplus1.[ValueFinAct],nplus1.[ValueFinPlan],
	--nplus1.[ValueDocAct], nplus1.[ValueDocPlan],
	--nplus1.[ValueTransAct],nplus1.[ValueTransPlan],

	--nplus1.[ValueDebt],

	--nplus1.[QtyFinAct], nplus1.[QtyFinPlan], 
	--nplus1.[QtyDocAct], nplus1.[QtyDocPlan], 
	--nplus1.[QtyTransAct], nplus1.[QtyTransPlan], 

	--nplus1.[QtyActualStock],
	--nplus1.[QtyOrderedByCustomer],
	--nplus1.[QtyOrderedToSupplier],
	--nplus1.[QtyInProduction],
	--nplus1.[QtyInConsumption],

	--nplus1.IDSrc, nplus1.IDSrcModule,
	--nplus1.Compensation,
	--nplus1.IDSysActivityType,
	--nplus1.IDSysAccountMovementType,
	--nplus1.MovementMode,
	--case when depth + 1 = 3 then n.SumDate else n.DateRecord end, 
	--n.MovementMode, nplus1.CreatedOn, nplus1.MovementRootType, n.IDParent as idGrandParent,
	--nplus1.TotalCredit, 
	--nplus1.TotalDebit
	--FROM [SysPocValue] as nplus1 
	--inner join n on nplus1.IDParent=n.[IDPocValue] and n.IDParent IS NOT NULL and nplus1.MovementRootType = 0 
	--and nplus1.IDRecord = @IDrecord and nplus1.IDRecordModule = @IDmodule and n.MovementMode <> 3

	--union all
	--select 
	--nplus1.[IDPocValue], 
	--nplus1.IDRecord, nplus1.IDRecordModule,
	--nplus1.IDParent, Depth + 1, 
	--cast(n.hierarchy + '.' + CAST(nplus1.[IDPocValue] as nvarchar) as nvarchar),
	--nplus1.[IDLine], 
	--nplus1.[Description], 
	--nplus1.[DateRecord],
	--nplus1.TypeOfValue,

	--nplus1.[ValueFinAct],nplus1.[ValueFinPlan],
	--nplus1.[ValueDocAct], nplus1.[ValueDocPlan],
	--nplus1.[ValueTransAct],nplus1.[ValueTransPlan],

	--nplus1.[ValueDebt],

	--nplus1.[QtyFinAct], nplus1.[QtyFinPlan], 
	--nplus1.[QtyDocAct], nplus1.[QtyDocPlan], 
	--nplus1.[QtyTransAct], nplus1.[QtyTransPlan], 

	--nplus1.[QtyActualStock],
	--nplus1.[QtyOrderedByCustomer],
	--nplus1.[QtyOrderedToSupplier],
	--nplus1.[QtyInProduction],
	--nplus1.[QtyInConsumption],

	--nplus1.IDSrc, nplus1.IDSrcModule,
	--nplus1.Compensation,
	--nplus1.IDSysActivityType,
	--nplus1.IDSysAccountMovementType,
	--nplus1.MovementMode,
	--case when depth + 1 = 3 then n.SumDate else n.DateRecord end, 
	--n.MovementMode, nplus1.CreatedOn, nplus1.MovementRootType, n.IDParent as idGrandParent,
	--nplus1.TotalCredit, 
	--nplus1.TotalDebit
	--FROM [SysPocValue] as nplus1 
	--inner join n on nplus1.IDParent=n.[IDPocValue] and nplus1.MovementRootType = 0 
	--and nplus1.IDRecord <> @IDrecord and n.MovementMode = 3
),extraN as(
	select *,
	case 
	when depth = 3 then idGrandParent 
	when depth = 2 then IDParent
	else IDPocValue end  as FirstlevelGroupID,
	case 
	when depth = 3 then t.IDParent 
	when depth = 2 and (hasChildrenPlanned + hasChildrenInfo) > 0 then IDPocValue
	when depth = 2 and (hasChildrenPlanned + hasChildrenInfo) = 0  then IDParent
	else IDPocValue end as SecondLevelGroupID,
	hasChildrenPlanned + hasChildrenInfo SumChildren,
	convert(bit, case when ((MovementMode = 0 AND hasChildrenInfo = 0) OR ((MovementMode = 2 AND (hasChildrenInfo = 0) AND (ParentMovementMode = 0 OR ParentMovementMode = 2))) AND IDSysAccountMovementType <> 3) then 1 else 0 end) ConditionActual,
	convert(bit, case when ((MovementMode in(1,4) AND hasChildrenInfo = 0) OR ((MovementMode = 2 AND (hasChildrenPlanned = 0) AND ParentMovementMode in(1,4))) AND IDSysAccountMovementType <> 3) then 1 else 0 end) ConditionPlanned,
	convert(bit, case when MovementMode = 0 then 1 else 0 end) IsMovementActual,
	convert(bit, case when MovementMode in(1,4) then 1 else 0 end) IsMovementPlanned,
	convert(bit, case when idparent is null then 1 else 0 end) IsParentNull,
	convert(bit, case when IDRecordModule in(select idmodule from GetModulesRec('c6e9bf0a-19dd-4536-834f-07fc6334dc3e')) then 1 else 0 end ) IsMovementAccountTime,
	convert(bit, case when IDRecordModule in(select idmodule from GetModulesRec('3020ddd2-d6d9-4e3d-8b6f-70d228e1b7b2')) then 1 else 0 end ) IsMovementAccountVacation
from
(
	select *,
	(select count(distinct IDPocValue) from SysPocValue c where c.IDParent = n.IDPocValue and MovementMode in(1,4)) hasChildrenPlanned, 
	(select count(distinct IDPocValue) from SysPocValue c where c.IDParent = n.IDPocValue and MovementMode = 2) hasChildrenInfo,
	case 
	when depth = 1 and(
		select 
		count(distinct gc.IDPocValue) 
		from SysPocValue c 
		inner join SysPocValue gc on gc.IDParent = c.idpocvalue
		where c.IDParent = n.IDPocValue 
	) > 0 then 1 else 0 end  hasGrandChildren
	from n
	WHERE MovementRootType = 0
)t
)
, updatedValues as(
	select n.*, 
	SUM(CASE WHEN ConditionActual = 1 THEN [ValueTransAct] + [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC,  [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [Compensation] DESC ,[IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumFinActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueTransAct] + [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumFinPlanned],
	SUM(CASE WHEN ConditionActual = 1 THEN [ValueDocAct] + [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumDocActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueDocAct] + [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumDocPlanned],
	SUM(CASE WHEN ConditionActual = 1 THEN [ValueTransAct] - [ValueDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumTransActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueTransAct] - [ValueDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [ValueSumTransPlanned],
	SUM(CASE WHEN ConditionActual = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumFinActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumFinPlanned],
	SUM(CASE WHEN ConditionActual = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumDocActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumDocPlanned],
	SUM(CASE WHEN ConditionActual = 1 THEN [QtyTransAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumTransActual],
	SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyTransAct] + [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [QtySumTransPlanned],
	ABS(SUM(CASE WHEN IsMovementActual = 1 THEN [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueFinAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueFinPlan],
	ABS(SUM(CASE WHEN IsMovementActual = 1  THEN [ValueDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueDocAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueDocPlan],
	ABS(SUM(CASE WHEN IsMovementActual = 1  THEN [ValueTransAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueTransAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [ValueTransAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalValueTransPlan],
	ABS(SUM(CASE WHEN IsMovementActual = 1  THEN [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyFinAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyFinAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyFinPlan],
	ABS(SUM(CASE WHEN IsMovementActual = 1  THEN [QtyDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyDocAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyDocAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyDocPlan],
	ABS(SUM(CASE WHEN IsMovementActual = 1  THEN [QtyTransAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyTransAct],
	ABS(SUM(CASE WHEN ConditionPlanned = 1 THEN [QtyTransAct] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)) AS  [TotalQtyTransPlan],

	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyActualStock] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyActualStock],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyOrderedByCustomer] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyOrderedByCustomer],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyOrderedToSupplier] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyOrderedToSupplier],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyInProduction] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord], [IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyInProduction],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyInConsumption] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord],[IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyInConsumption],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyPendingProduction] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord],[IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyPendingProduction],
	SUM(CASE WHEN IsMovementActual = 1 THEN [QtyReserved] ELSE 0 END) OVER (PARTITION BY MovementRootType ORDER BY IsParentNull, [SumDate],[Compensation] DESC, [FirstlevelGroupID],[hasGrandchildren], [SecondlevelGroupID],[Depth] DESC,SumChildren, [DateRecord],[IDPocValue]  ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS  [TotalQtyReserved],
	CASE 
		WHEN n.MovementMode = 3 THEN (select top 1 account_no from Account where IDAccount = n.IDRecord and IDModule = n.IDRecordModule) 
		ELSE (select top 1 doc_ref from document where IDDocument = n.IDSrc and IDModule = n.IDSrcModule) 
	END as IDSrcCode,
	case when MovementMode = 3 and IDRecord = @IDrecord and IDRecordModule = @IDmodule then 1 else 0 end IsRootMovement
	from extraN n
	WHERE MovementRootType = 0
)
,
finalValues as(
	select [IDPocValue] as NewIDPocValue,
		
	CASE WHEN IsRootMovement = 1 THEN ABS(ValueFinAct)
	ELSE u.[TotalValueFinAct]
	END AS  [NewTotalValueFinAct],

	u.[TotalValueFinPlan] as [NewTotalValueFinPlan],

	CASE WHEN IsRootMovement = 1 THEN ABS(ValueDocAct)
	ELSE u.[TotalValueDocAct]
	END AS  [NewTotalValueDocAct],

	u.[TotalValueDocPlan] as [NewTotalValueDocPlan],

	CASE WHEN IsRootMovement = 1 THEN ABS(ValueTransAct)
	ELSE u.[TotalValueTransAct]
	END AS  [NewTotalValueTransAct],

	u.[TotalValueTransPlan] as [NewTotalValueTransPlan],

	CASE WHEN IsRootMovement = 1 THEN ABS(ValueDocAct)
	ELSE u.[TotalValueDocAct]
	END AS  [NewTotalValueDebt],

	CASE WHEN IsRootMovement = 1 THEN ABS(QtyFinAct)
	ELSE u.[TotalQtyFinAct]
	END AS  [NewTotalQtyFinAct],

	u.[TotalQtyFinPlan] as [NewTotalQtyFinPlan],

	CASE WHEN IsRootMovement = 1 THEN ABS(QtyDocAct)
	ELSE u.[TotalQtyDocAct]
	END AS  [NewTotalQtyDocAct],

	u.[TotalQtyDocPlan] as [NewTotalQtyDocPlan],

	CASE WHEN IsRootMovement = 1 THEN ABS(QtyTransAct)
	ELSE u.[TotalQtyTransAct]
	END AS  [NewTotalQtyTransAct],

	u.[TotalQtyTransPlan] as [NewTotalQtyTransPlan],

	-----------------------------------------------------------

	CASE WHEN IsRootMovement = 1 THEN QtyActualStock
	ELSE TotalQtyActualStock
	END AS  [NewTotalQtyActualStock],

	CASE WHEN IsRootMovement = 1 THEN QtyOrderedByCustomer
	ELSE [TotalQtyOrderedByCustomer]
	END AS  [NewTotalQtyOrderedByCustomer],

	CASE WHEN IsRootMovement = 1 THEN QtyOrderedToSupplier
	ELSE [TotalQtyOrderedToSupplier]
	END AS  [NewTotalQtyOrderedToSupplier],

	CASE WHEN IsRootMovement = 1 THEN QtyInProduction
	ELSE [TotalQtyInProduction]
	END AS  [NewTotalQtyInProduction],

	CASE WHEN IsRootMovement = 1 THEN QtyInConsumption
	ELSE [TotalQtyInConsumption]
	END AS  [NewTotalQtyInConsumption],

	CASE WHEN IsRootMovement = 1 THEN QtyReserved
	ELSE [TotalQtyReserved]
	END AS  [NewTotalQtyReserved],

	CASE WHEN IsRootMovement = 1 THEN QtyPendingProduction
	ELSE [TotalQtyPendingProduction]
	END AS  [NewTotalQtyPendingProduction],

	----------------------------------------------------------

	CASE WHEN IsRootMovement = 1 THEN [ValueDocAct] + [ValueFinAct] ELSE [ValueSumDocActual] END  AS [NewValueDocActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [ValueDocAct] + [ValueFinAct] + [ValueSumDocPlanned]
	ELSE [ValueSumDocActual] + [ValueSumDocPlanned] END  AS [NewValueDocPlanBalance],

	CASE WHEN IsRootMovement = 1 THEN [ValueTransAct] + [ValueFinAct] ELSE [ValueSumFinActual] END AS [NewValueFinActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [ValueTransAct] + [ValueFinAct] + [ValueSumFinPlanned]
	ELSE [ValueSumFinActual] + [ValueSumFinPlanned] END AS [NewValueFinPlanBalance],

	CASE WHEN IsRootMovement = 1 THEN [ValueTransAct] - [ValueDocAct] ELSE [ValueSumTransActual] END  AS [NewValueTransActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [ValueTransAct] - [ValueDocAct] + [ValueSumTransPlanned]
	ELSE [ValueSumTransActual] + [ValueSumTransPlanned] END AS [NewValueTransPlanBalance],

	CASE WHEN IsRootMovement = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE [QtySumDocActual] END  AS [NewQtyDocActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [QtyDocAct] + [QtyFinAct] + [QtySumDocPlanned]
	ELSE [QtySumDocActual] + [QtySumDocPlanned] END  AS [NewQtyDocPlanBalance],

	CASE WHEN IsRootMovement = 1 THEN [QtyDocAct] + [QtyFinAct] ELSE [QtySumFinActual] END AS [NewQtyFinActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [QtyDocAct] + [QtyFinAct] + [QtySumFinPlanned]
	ELSE [QtySumFinActual] + [QtySumFinPlanned] END AS [NewQtyFinPlanBalance],

	CASE WHEN IsRootMovement = 1 THEN [QtyTransAct] + [QtyFinAct] ELSE [QtySumTransActual] END  AS [NewQtyTransActBalance],

	CASE WHEN u.[IDParent] IS NULL THEN [QtyTransAct] + [QtyFinAct] + [QtySumTransPlanned]
	ELSE [QtySumTransActual] + [QtySumTransPlanned] END AS [NewQtyTransPlanBalance],
	CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3) and ValueDocAct < 0 THEN ValueDocAct ELSE 0 END + CASE WHEN IsMovementAccountTime = 0 and ValueFinAct < 0 THEN ValueFinAct ELSE 0 END + 
	CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3) and QtyDocAct < 0 THEN QtyDocAct ELSE 0 END + CASE WHEN IsMovementAccountTime = 0 and QtyFinAct < 0 THEN QtyFinAct ELSE 0 END +
	CASE WHEN IsMovementAccountTime = 1 and IsMovementAccountVacation = 0 THEN TotalDebit ELSE 0 END +
	CASE WHEN MovementMode = 3 and (IsMovementAccountTime = 0 OR IsMovementAccountVacation = 1) THEN (
		select 
		sum(
			CASE WHEN MovementMode not in(3,2,1) and ValueDocAct < 0 THEN  ValueDocAct ELSE 0 END + CASE WHEN MovementMode not in(3,2,1) and ValueFinAct < 0 THEN ValueFinAct ELSE 0 END + 
			CASE WHEN MovementMode not in(3,2,1) and QtyDocAct < 0 THEN QtyDocAct ELSE 0 END + CASE WHEN MovementMode not in(3,2,1) and QtyFinAct < 0 THEN QtyFinAct ELSE 0 END +
			CASE WHEN MovementMode = 3 THEN TotalDebit ELSE 0 END)
		from syspocvalue 
		where IDParent = u.IDPocValue and Compensation = 0
	)
	ELSE 0 END +
	CASE WHEN IsMovementAccountVacation = 1 and MovementMode not in(2,3) and QtyDocAct < 0 THEN QtyDocAct ELSE 0 END
	as [NewTotalDebit],
	CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3,1) and ValueDocAct > 0 THEN ValueDocAct ELSE 0 END + CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3,1) and ValueFinAct > 0 THEN ValueFinAct ELSE 0 END + 
	CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3,1) and QtyDocAct > 0 THEN QtyDocAct ELSE 0 END + CASE WHEN IsMovementAccountTime = 0 and MovementMode not in(2,3,1) and QtyFinAct > 0 THEN QtyFinAct ELSE 0 END + 
	CASE WHEN IsMovementAccountTime = 1 and IsMovementAccountVacation = 0 THEN TotalCredit ELSE 0 END +
	CASE WHEN MovementMode = 3 and (IsMovementAccountTime = 0 OR IsMovementAccountVacation = 1) THEN (
		select 
		sum(
			CASE WHEN MovementMode not in(3,2,1) and ValueDocAct > 0 THEN ValueDocAct ELSE 0 END + CASE WHEN MovementMode not in(2,3,1) and ValueFinAct > 0 THEN ValueFinAct ELSE 0 END + 
			CASE WHEN MovementMode not in(3,2,1) and QtyDocAct > 0 THEN QtyDocAct ELSE 0 END + CASE WHEN MovementMode not in(2,3,1) and QtyFinAct > 0 THEN QtyFinAct ELSE 0 END +
			CASE WHEN MovementMode = 3 THEN TotalCredit ELSE 0 END)
		from syspocvalue 
		where IDParent = u.IDPocValue and Compensation = 0
	) ELSE 0 END +
	CASE WHEN IsMovementAccountVacation = 1 and MovementMode not in(2,3) and QtyDocAct > 0 THEN QtyDocAct ELSE 0 END 
	as [NewTotalCredit],
	IsRootMovement	
	from updatedValues u
	inner join Account acc on acc.IDAccount = u.IDRecord and acc.IDModule = u.IDRecordModule
	where ((DateRecord >= @MinDate) or (MovementMode = 3))
)
UPDATE SysPocValue SET
[TotalValueFinAct] = tt.[NewTotalValueFinAct],
[TotalValueFinPlan] = tt.[NewTotalValueFinPlan],
[TotalValueDocAct] = tt.[NewTotalValueDocAct],
[TotalValueDocPlan] = tt.[NewTotalValueDocPlan],
[TotalValueTransAct] = tt.[NewTotalValueTransAct],
[TotalValueTransPlan] = tt.[NewTotalValueTransPlan],
[TotalValueDebt] = tt.[NewTotalValueDebt],
[TotalQtyFinAct] = tt.[NewTotalQtyFinAct],
[TotalQtyFinPlan] = tt.[NewTotalQtyFinPlan],
[TotalQtyDocAct] = tt.[NewTotalQtyDocAct],
[TotalQtyDocPlan] = tt.[NewTotalQtyDocPlan],
[TotalQtyTransAct] = tt.[NewTotalQtyTransAct],
[TotalQtyTransPlan] = tt.[NewTotalQtyTransPlan],
[ValueDocActBalance] = tt.[NewValueDocActBalance],
[ValueDocPlanBalance] = tt.[NewValueDocPlanBalance],
[ValueFinActBalance] = tt.[NewValueFinActBalance],
[ValueFinPlanBalance] = tt.[NewValueFinPlanBalance],
[ValueTransActBalance] = tt.[NewValueTransActBalance],
[ValueTransPlanBalance] = tt.[NewValueTransPlanBalance],
[QtyDocActBalance] = tt.[NewQtyDocActBalance],
[QtyDocPlanBalance] = tt.[NewQtyDocPlanBalance],
[QtyFinActBalance] = tt.[NewQtyFinActBalance],
[QtyFinPlanBalance] = tt.[NewQtyFinPlanBalance],
[QtyTransActBalance] = tt.[NewQtyTransActBalance],
[QtyTransPlanBalance] = tt.[NewQtyTransPlanBalance],
------------------------------------------------------------
[TotalQtyActualStock] = tt.[NewTotalQtyActualStock],
[TotalQtyOrderedByCustomer] = tt.[NewTotalQtyOrderedByCustomer],
[TotalQtyOrderedToSupplier] = tt.[NewTotalQtyOrderedToSupplier],
[TotalQtyInProduction] = tt.[NewTotalQtyInProduction],
[TotalQtyInConsumption] = tt.[NewTotalQtyInConsumption],
[TotalReservedStock] = tt.[NewTotalQtyReserved],
[TotalQtyPendingProduction] = tt.[NewTotalQtyPendingProduction],

[DateRecord] = case when MovementMode = 3 then GETDATE() else DateRecord end,
[TotalDebit] = ABS(tt.[NewTotalDebit]),
[TotalCredit] = ABS(tt.[NewTotalCredit])
from 
( 
	select * from finalValues
) tt
where IDPocValue = tt.NewIDPocValue
END
GO


-- ----------------------------
-- procedure structure for SS_ValidateCMMResult
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_ValidateCMMResult]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_ValidateCMMResult]
GO

CREATE PROCEDURE [dbo].[SS_ValidateCMMResult]
	@ObjectID uniqueidentifier,
	@JobID int
AS
BEGIN
	--Correr regras de validação deste tipo de objecto

	--Fazer update dos resultados no campo CMMValidated
	declare @PointsNotValidated int
	declare @RefDispNotValidated int

	declare @Gap float
	declare @ObjectType int

	set @ObjectType = (Select typeid from SS_Object where id=@ObjectID)
	set @gap= (Select gap from SS_Eletrode where id=@ObjectID)

	--Validações Ponto a ponto
	set @PointsNotValidated=(		Select count(p.IDObject)
		from  ss_program p 
		left join ss_cmmpoint sp on p.id=sp.id
		inner join ss_cmmvalidationrules r on 
			(	idobjecttype=@ObjectType  
				and ((@GAP is null) or ((@GAP<=isnull(r.gapmax,0)) and (@GAP>=isnull(r.gapmin,0))))
				--and (((isnull(sp.tx,0)-isnull(sp.rx,0)<=isnull(r.Dxmax,0)) and (isnull(sp.tx,0)-isnull(sp.rx,0)>=isnull(r.Dxmin,0))))
				--and (((isnull(sp.ty,0)-isnull(sp.ry,0)<=isnull(r.Dymax,0)) and (isnull(sp.ty,0)-isnull(sp.ry,0)>=isnull(r.Dymin,0))))
				--and (((isnull(sp.tz,0)-isnull(sp.rz,0)<=isnull(r.Dzmax,0)) and (isnull(sp.tz,0)-isnull(sp.rz,0)>=isnull(r.Dzmin,0))))
				--and (((isnull(sp.tc,0)-isnull(sp.rc,0)<=isnull(r.Dcmax,0)) and (isnull(sp.tc,0)-isnull(sp.rc,0)>=isnull(r.Dcmin,0))))
				
				and (((isnull(sp.DP,0)>isnull(r.dpmax,0)) or (isnull(sp.DP,0)<isnull(r.dpmin,0))))
			)
		where p.IDObject=@ObjectID and p.kind=dbo.CMMREsKind())


	--Validação dos desvios encontrados
	set @RefDispNotValidated=(		Select count(o.id)
		from ss_object o
		left join ss_eletrode e on e.id=o.id
		inner join ss_cmmvalidationrules r on 
			(	idobjecttype=o.typeid  
				and ((e.gap is null) or ((e.gap<=isnull(r.gapmax,0)) and (e.gap>=isnull(r.gapmin,0))))
			)
		where (o.id=@ObjectID) 
		and (((isnull(o.CMMDX,0)>isnull(r.refdxmax,0)) or (isnull(o.CMMDX,0)<isnull(r.refdxmin,0))))
		and (((isnull(o.CMMDY,0)>isnull(r.refdymax,0)) or (isnull(o.CMMDy,0)<isnull(r.refdymin,0))))
		and (((isnull(o.CMMDz,0)>isnull(r.refdzmax,0)) or (isnull(o.CMMDz,0)<isnull(r.refdzmin,0))))
		and (((isnull(o.CMMEmpC,0)>isnull(r.refEmpCmax,0)) or (isnull(o.CMMEmpC,0)<isnull(r.refEmpCmin,0))))
		and (((isnull(o.CMMEmpZ,0)>isnull(r.refEmpZmax,0)) or (isnull(o.CMMEmpZ,0)<isnull(r.refEmpZmin,0))))
		 )


	if @PointsNotValidated+@RefDispNotValidated>0 
	begin
		update ss_object set cmmvalidated=0 where id=@ObjectID
		update SysJobCMMResults set cmmvalidated=0  where idjob=@JobID
	end
	else
	begin
		update ss_object set cmmvalidated=1 where id=@ObjectID
		update SysJobCMMResults set cmmvalidated=1  where idjob=@JobID
	end
END
GO


