-- ----------------------------
-- procedure structure for usp_UpdateFollowUpItemFromActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_UpdateFollowUpItemFromActivity]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[usp_UpdateFollowUpItemFromActivity]
GO

CREATE PROCEDURE [dbo].[usp_UpdateFollowUpItemFromActivity]
(
    @IDActivity INT
)
AS
BEGIN
    SET NOCOUNT ON;

    /*
        Purpose:
            Updates redundant activity fields in dbo.FollowUpItem for all follow-up items
            related to a given activity (@IDActivity).

        How it works:
            1) Base CTE:
               - Finds records linked to the provided activity in dbo.Activity2Record.
               - Keeps only modules returned by dbo.GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944').
               - Restricts activity status to (2726, 2724).
            2) Fonte CTE:
               - Reads calculated/redundant values from dbo.FollowUpItemsRedundatActivitiesFields
                 for the follow-up items found in Base.
            3) UPDATE:
               - Updates dbo.FollowUpItem with previous/next activity fields and day counters.

        Input parameter:
            @IDActivity (INT) - Activity identifier to process.

        Output:
            Returns one row with the number of affected rows:
                SELECT @@ROWCOUNT AS RowsUpdated;

        Notes:
            - Mapping used:
                Base.relatedRecord       -> FollowUpItem.IDFollowUpItem
                Base.relatedRecordModule -> FollowUpItem.IDModule
            - This procedure performs a set-based update (no cursor/loop).
        Use:
            EXEC dbo.usp_UpdateFollowUpItemFromActivity @IDActivity = 2821471;
    */

    ;WITH Base AS
    (
        SELECT
            a2r.relatedRecord,          -- IDFollowUpItem
            a2r.relatedRecordModule     -- IDModule / IDFollowUpItemModule
        FROM dbo.Activity AS a
        INNER JOIN dbo.Activity2Record AS a2r
            ON a2r.IDActivity = a.IDActivity
           AND a2r.IDActivityModule = a.IDModule
        WHERE a2r.relatedRecordModule IN
        (
            SELECT IDModule
            FROM dbo.GetModulesRec('19164347-8E56-4495-8C87-FB21580AE944')
        )
          AND a.status IN (2726, 2724)
          AND a.IDActivity = @IDActivity
    ),
    Fonte AS
    (
        SELECT
            f.IDFollowUpItem                       AS IDF,
            f.IDFollowUpItemModule                 AS IDFModule,
            f.PreviousIDActivity                   AS PIDActivity,
            f.PreviousIDActivityModule             AS PIDActivityModule,
            f.PreviousActivityLabel                AS PActivityLabel,
            f.PreviousActivityDate                 AS PActivityDate,
            f.NextIDActivity                       AS NIDActivity,
            f.NextIDActivityModule                 AS NIDActivityModule,
            f.NextActivityLabel                    AS NActivityLabel,
            f.NextActivityDate                     AS NActivityDate,
            f.DaysSinceLastCompleted               AS PDaysSinceLastCompleted,
            f.DaysUntilNextPlannedStatus           AS NDaysUntilNextPlannedStatus,
            f.DaysUntilNextPlanned                 AS NDaysUntilNextPlanned
        FROM dbo.FollowUpItemsRedundatActivitiesFields AS f
        INNER JOIN Base AS b
            ON b.relatedRecord = f.IDFollowUpItem
           AND b.relatedRecordModule = f.IDFollowUpItemModule
    )
    UPDATE fui
       SET fui.PreviousIDActivity          = src.PIDActivity,
           fui.PreviousIDActivityModule    = src.PIDActivityModule,
           fui.PreviousActivityDate        = src.PActivityDate,
           fui.PreviousActivityLabel       = src.PActivityLabel,
           fui.NextIDActivity              = src.NIDActivity,
           fui.NextIDActivityModule        = src.NIDActivityModule,
           fui.NextActivityDate            = src.NActivityDate,
           fui.NextActivityLabel           = src.NActivityLabel,
           fui.DaysSinceLastCompleted      = src.PDaysSinceLastCompleted,
           fui.DaysUntilNextPlanned        = src.NDaysUntilNextPlanned,
           fui.DaysUntilNextPlannedStatus  = src.NDaysUntilNextPlannedStatus
    FROM dbo.FollowUpItem AS fui
    INNER JOIN Fonte AS src
        ON src.IDF = fui.IDFollowUpItem
       AND src.IDFModule = fui.IDModule;

    SELECT @@ROWCOUNT AS RowsUpdated;
END;
GO


-- ----------------------------
-- procedure structure for UpdateAccountStockUnitFromProduct
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateAccountStockUnitFromProduct]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateAccountStockUnitFromProduct]
GO

CREATE PROCEDURE [dbo].[UpdateAccountStockUnitFromProduct]
	@IDProduct int,
	@IDModule uniqueidentifier
AS
BEGIN
	SET NOCOUNT ON;

	update AccountStock set usageunit = newUU
	from(
		select p.usageunit newUU, acc.IDAccount IDACC
		from products p
		inner join account acc on acc.IDContact = p.productid and acc.IDContactModule = p.IDModule
		inner join AccountStock accs on accs.IDAccount = acc.IDAccount
		where p.productid = @IDProduct and p.IDModule = @IDModule
	) t
	where IDAccount = t.IDACC;

END
GO


-- ----------------------------
-- function structure for GetResourcesTeamMask01
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourcesTeamMask01]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourcesTeamMask01]
GO

CREATE FUNCTION [dbo].[GetResourcesTeamMask01]
(
	@IDResource as uniqueidentifier
)
RETURNS bigint
AS
BEGIN
	DECLARE @mask01 bigint,
	@mask bigint
	set @mask =0

	DECLARE CursorTeams CURSOR FOR
	select  t.Mask1
		from SysTeam t
		Inner join SysActivityRoleResource rr on rr.IDTeam=t.IDTeam
		where rr.IDResource=@IDResource

	OPEN CursorTeams
	FETCH NEXT FROM CursorTeams INTO @mask01					
	WHILE  @@FETCH_STATUS = 0
	BEGIN
		
		set  @mask |= @mask01

		FETCH NEXT FROM CursorTeams INTO @mask01	
	END
	CLOSE CursorTeams 
	DEALLOCATE CursorTeams 

	return @mask
END
GO


-- ----------------------------
-- function structure for GetANGroupChildren
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetANGroupChildren]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetANGroupChildren]
GO

CREATE FUNCTION [dbo].[GetANGroupChildren]
(	
	@IDGroup int
)
RETURNS TABLE 
AS
RETURN 
(
with directChildren as
(
	select c.ID as IDGroup, p.id as IDChild, c.Name as GroupName, p.Name as ChildName, 
	p.ID as OriginChild ,c.ID as OriginParent, p.Name OriginName,c.Name OriginParentName
	from ANGroup c
	inner join ANGroup2ANGroup g2g on g2g.IDParent = c.ID
	inner join ANGroup p on p.ID = g2g.IDChild
), rec as
(
	select *
	from directChildren p
	where p.IDGroup = @idgroup
	union all
	select 	m.IDGroup, m.IDchild, m.ChildName, m.ChildName,
	rec.OriginChild ,rec.OriginParent,rec.OriginName,rec.OriginParentName
	from directChildren m
	inner join rec on rec.IDChild = m.IDGroup
)
select  OriginParent, OriginChild,
STUFF 
(
	(
		SELECT Distinct ', '+ CAST 
			(
				IDChild as nvarchar(128)) as Parents  
				FROM rec 
				where r.OriginChild = OriginChild and r.OriginParent = OriginParent
				GROUP By OriginChild, OriginParent, IDChild
				FOR XML PATH(''), TYPE
	)
.value('.[1]', 'nvarchar(max)'), 1, 2, '') as Children
from rec r
group by OriginChild, OriginParent
)
GO


