CREATE FUNCTION [dbo].[ModuleIsChildOf]
(
	@parent uniqueidentifier,
	@possibleChild uniqueidentifier
)
RETURNS bit
AS
BEGIN
	declare @r bit
	set @r = 0
	if exists (
		select *
		from [dbo].[GetModulesRec](@parent)
		where IDModule = @possibleChild
	)
	begin
		set @r = 1
	end

	return @r
END
GO


