CREATE FUNCTION [dbo].[GetANGroupParents]
(	
	@IDGroup int
)
RETURNS TABLE 
AS
RETURN 
(
with directParents as
(
	select c.ID as IDGroup, p.id as IDParent, c.Name as ChildName, p.Name as ParentName, 
	c.ID as OriginChild ,p.ID as OriginParent, c.Name OriginName,p.Name OriginParentName
	from ANGroup c
	inner join ANGroup2ANGroup g2g on g2g.IDChild = c.ID
	inner join ANGroup p on p.ID = g2g.IDParent
), rec as
(
	select *
	from directParents p
	where p.IDGroup = @idgroup
	union all
	select 	m.IDGroup, m.IDParent, m.ChildName, m.ParentName,
	rec.OriginChild ,rec.OriginParent,rec.OriginName,rec.OriginParentName
	from directParents m
	inner join rec on rec.IDParent = m.IDGroup
)
select OriginChild, OriginParent, 
STUFF 
(
	(
		SELECT Distinct ', '+ CAST 
			(
				IDParent as nvarchar(128)) as Parents  
				FROM rec 
				where r.OriginChild = OriginChild and r.OriginParent = OriginParent
				GROUP By OriginChild, OriginParent, IDParent
				FOR XML PATH(''), TYPE
	)
.value('.[1]', 'nvarchar(max)'), 1, 2, '') as Parents
from rec r
group by OriginChild, OriginParent
)
GO


-- ----------------------------
-- function structure for GetModulePendingTypes
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetModulePendingTypes]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetModulePendingTypes]
GO

CREATE FUNCTION [dbo].[GetModulePendingTypes]
(
	@IDModule uniqueidentifier
)
RETURNS @ret
 TABLE 
(
	ID uniqueidentifier
)
AS
BEGIN
	
	declare @c_IDModule uniqueidentifier
	declare @done int
	set @done = 0
	declare  GetModulePendingTypes_it cursor for 
		select IDModule
		from dbo.getModulesAscRec(@IDModule);

	open GetModulePendingTypes_it;

	fetch next from GetModulePendingTypes_it into @c_IDModule;

	while @@fetch_status = 0 and @done = 0
	begin

		if exists(select * from [SysModulePendingTypes] where IDModule = @c_IDModule)
		begin
			insert into @ret(ID)
			select ID from [SysModulePendingTypes] where IDModule = @c_IDModule

			set @done = 1
		end
		fetch next from GetModulePendingTypes_it into @c_IDModule;
	end;

	
	close GetModulePendingTypes_it;
	deallocate GetModulePendingTypes_it;

	return
END
GO


-- ----------------------------
-- procedure structure for sysTopCpuConsumingAggregate
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[sysTopCpuConsumingAggregate]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[sysTopCpuConsumingAggregate]
GO

CREATE PROCEDURE [dbo].[sysTopCpuConsumingAggregate]
	@samples int
as
begin
	set nocount on

	declare @table table (
		session_id	int null,
		query nvarchar(max) null
	)

	-- insert into @table (session_id, query)select 1, 'teste'

	while @samples > 0
	begin
	waitfor delay '00:00:01.000'

		insert into @table (session_id, query)	
		SELECT  s.session_id, /* 
			r.status, 
			r.blocking_session_id, 
			r.wait_type, 
			wait_resource, 
			r.wait_time / (1000 * 60) 'wait_time(Min)', 
			r.cpu_time, 
			r.logical_reads, 
			r.reads, 
			r.writes, 
			r.total_elapsed_time / (1000 * 60) 'total_elapsed_time(Min)', */
			Substring(st.TEXT,(r.statement_start_offset / 2) + 1, 
			((CASE r.statement_end_offset 
			WHEN -1 
			THEN Datalength(st.TEXT) 
			ELSE r.statement_end_offset 
			END - r.statement_start_offset) / 2) + 1) AS statement_text/*, 
			Coalesce(Quotename(Db_name(st.dbid)) + N'.' + Quotename(Object_schema_name(st.objectid, st.dbid)) + N'.' +
			Quotename(Object_name(st.objectid, st.dbid)), '') AS command_text
			r.command, 
			qp.query_plan, 
			s.login_name, 
			s.host_name, 
			s.program_name, 
			s.last_request_end_time, 
			s.login_time, 
			r.open_transaction_count ,
			info.idsession,
			sess.clientversion*/
		FROM sys.dm_exec_sessions AS s 
			JOIN sys.dm_exec_requests AS r ON r.session_id = s.session_id 
			CROSS APPLY sys.Dm_exec_sql_text(r.sql_handle) AS st 
			CROSS APPLY sys.dm_exec_query_plan(r.plan_handle) AS qp 
			left join syssessioninfo info on s.session_id = info.spid
			left join SysSession sess on info.idsession = sess.idsession
		WHERE r.session_id != @@SPID
 
		-- ORDER BY r.cpu_time desc
		set @samples = @samples - 1
	end

	select session_id, query, count(*) from @table group BY session_id, query
end
GO


-- ----------------------------
-- procedure structure for ChangeVarFromObjectParams
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChangeVarFromObjectParams]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChangeVarFromObjectParams]
GO

CREATE PROCEDURE [dbo].[ChangeVarFromObjectParams]
	-- Add the parameters for the stored procedure here
	@Client nvarchar(50),
	@Mould nvarchar(50),
	@Part nvarchar(50),
	@Eletrode nvarchar(50),
	@Var int,
	@VarValue nvarchar(50)
AS
BEGIN
	declare @varint bit;
	set @varint=0
	if @VarValue='S'
		set @varint=1	

	--Deslocado
	if @Var=23 
	begin
		set @varint=0
		if (@VarValue<>'')
			if cast(@varvalue as float)>0
				set @varint=1	
	end

	DECLARE LocalCursor CURSOR LOCAL 
	FOR select id from SS_GetObjectIDByParams(@Mould,@Eletrode,@Part,null,null,null,null,null,null,@Client,default)
	DECLARE @ChildID int
	OPEN LocalCursor;
	FETCH NEXT FROM LocalCursor
		INTO @CHILDID;
		
	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXEC 	dbo.ChangeVarFromObject @CHILDID,@Var,@varint,null,'',null
		FETCH NEXT FROM LocalCursor
			INTO @ChildID;
	END;
		
	CLOSE LocalCursor;
	DEALLOCATE LocalCursor;

end
GO


