CREATE PROCEDURE [dbo].[UpdateANDistributions]
AS
BEGIN

	SET NOCOUNT ON;

	update ANGroup2ANCenterDistribution set Active = t.NewActive
	from
	(
		select ID as IDAN2AN, case when StartDate <= GETDATE() and EndDate >= GETDATE() then 1 else 0 end NewActive
		from ANGroup2ANCenterDistribution
	) t
	where ID = t.IDAN2AN
	
END
