-- ----------------------------
-- procedure structure for CreateOrUpdateMouldTest
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CreateOrUpdateMouldTest]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CreateOrUpdateMouldTest]
GO

CREATE PROCEDURE [dbo].[CreateOrUpdateMouldTest]
(
	@IDSysDocOprRoutine uniqueidentifier
)
AS
BEGIN

	declare @IDModule uniqueidentifier = 'D65FEE8C-575E-40C8-A629-F8969C41DE0D';
	declare @IDProcessTesting uniqueidentifier = '13D0EF64-0D6A-4E25-9E09-FF84D0F427F6';
	declare @IsMouldRoutine int = 
	(
		select COUNT(ri.IDRoutine)
		from SysDocOprRoutine ri
		inner join FollowUpItemMouldFields fup on ri.IDRoutine = fup.IDSysDocOprRoutine
		where IDRoutine = @IDSysDocOprRoutine
	);

	if(@IsMouldRoutine = 0)
		return;

	declare it cursor for
	select IDRoutineItem
	from SysDocOprRoutineItem
	where IDRoutine = @IDSysDocOprRoutine
	and IDProcess = @IDProcessTesting;

	declare @tmp table
	(
		IDThirdParty int,
		IDThirdPartyModule uniqueidentifier,
		PlasticMaterial nvarchar(300),
		OwnMachine nvarchar(300),
		Notes nvarchar(1000),
		IDFollowUpITem bigint
	);

	open it;

	declare @IDSysDocOprRoutineItem uniqueidentifier
	declare @OwnMachine nvarchar(200);  


	fetch next from it into @IDSysDocOprRoutineItem

	while @@FETCH_STATUS = 0
	begin
		declare @IDMouldTest int = (select top 1 IDMouldTest from MouldTest where IDSysDocOprRoutineItem = @IDSysDocOprRoutineItem);
		declare @IDFollowUpItem bigint;

		set @OwnMachine = isnull((
				select top 1 res.DisplayName
				from SysRoutineTeamRoleResource trr
				inner join SysResources res on res.ResourceId = trr.IDResource
				where trr.IDRoutineItem = @IDSysDocOprRoutineItem and res.Kind = 2
			),'');

		if(@IDMouldTest is null)
		begin

			delete from @tmp;

			insert into @tmp
			select top 1 mt.IDThirdParty, mt.IDThirdPartyModule, mt.PlasticMaterial, mt.OwnMachine, mt.notes, fup.IDFollowUpItem
			from SysDocOprRoutineItem ri
			inner join FollowUpItemMouldFields fup on ri.IDRoutine = fup.IDSysDocOprRoutine
			inner join MouldTest mt on mt.IDFollowUpItem = fup.IDFollowUpItem
			where mt.Date < ri.Deadline and IDRoutineItem = @IDSysDocOprRoutineItem
			order by mt.Date desc

			declare @CurrentCounter int = (select CurrentCounter + 1 from SysModule where IDModule = @IDModule);
			declare @Mask nvarchar(50) = concat('MT_', right(concat('0000', @CurrentCounter ), 4));

			INSERT INTO MouldTest
			(
				[Code],[Code_counter],[Code_IsTemp],[IDModule],[Date],[IDFollowUpItem],[IDFollowUpItemModule],[IDSysDocOprRoutineItem], Name,
				[OwnMachine], [PlasticMaterial],[IDThirdParty], [IDThirdPartyModule], [notes]
			)
			select @Mask, @CurrentCounter, 0, @IDModule, dateadd(MINUTE, DATEPART(TZoffset, ri.Deadline At Time Zone 'GMT Standard Time') * -1, ri.Deadline), fup.IDFollowUpItem, fup.IDModule, ri.IDRoutineItem, 
			ri.Name,isnull(mt.OwnMachine, @OwnMachine), mt.PlasticMaterial, mt.IDThirdParty, mt.IDThirdPartyModule, mt.Notes
			from SysDocOprRoutineItem ri
			inner join FollowUpItemMouldFields fup on ri.IDRoutine = fup.IDSysDocOprRoutine
			left join @tmp mt on 1 = 1
			where IDRoutineItem = @IDSysDocOprRoutineItem

			set @IDFollowUpITem = (select top 1 IDFollowUpITem from @tmp);
			update SysModule set CurrentCounter = CurrentCounter + 1 where IDModule = @IDModule;
		end
		else
		begin
			update MouldTest set Date = t.Deadline, Name = t.Name, OwnMachine = @OwnMachine
			from
			(
				select Deadline, Name from SysDocOprRoutineItem where IDRoutineItem = @IDSysDocOprRoutineItem
			) t			
			where IDMouldTest = @IDMouldTest;

			set @IDFollowUpITem = (select top 1 IDFollowUpITem from MouldTest where IDMouldTest = @IDMouldTest);
		end

		exec [UpdateMouldDeadline] @IDFollowUpItem;

		fetch next from it into @IDSysDocOprRoutineItem
	end

	close it;
	deallocate it;

	declare @IDMould bigint = (select top 1 @IDFollowUpItem from FollowUpItemMouldFields where IDSysDocOprRoutine = @IDSysDocOprRoutine);

	delete from MouldTest where IDMouldTest in
	(
		select IDMouldTest
		from MouldTest t
		where IDFollowUpItem = @IDMould
		and t.IDSysDocOprRoutineItem not in
		(
			select distinct idroutineitem from SysDocOprRoutineItem where IDRoutine = @IDSysDocOprRoutine
		)
	);
	
	delete from SysTaskResourceRole
	where IDTask in
	(
		select IDSysTask from SysDocOprRoutineItem where IDRoutine = @IDSysDocOprRoutine
	);
END
GO


-- ----------------------------
-- function structure for greatest
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[greatest]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[greatest]
GO

CREATE FUNCTION [dbo].[greatest]
(
	@a int,
	@b int
)
RETURNS int
AS
BEGIN
	if @a < @b 		
		set @a = @b

	return @a
END
GO


-- ----------------------------
-- function structure for GetANGroupParentsRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetANGroupParentsRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetANGroupParentsRec]
GO

CREATE FUNCTION [dbo].[GetANGroupParentsRec]
(	
	@IDGroup int
)
RETURNS TABLE 
AS
RETURN 
(
with directParents as
(
	select c.ID as IDGroup, p.id as IDParent, c.Name as ChildName, p.Name as ParentName, 
	c.ID as OriginChild ,p.ID as OriginParent, c.Name OriginName,p.Name OriginParentName
	from ANGroup c
	inner join ANGroup2ANGroup g2g on g2g.IDChild = c.ID
	inner join ANGroup p on p.ID = g2g.IDParent
), rec as
(
	select IDParent
	from directParents p
	where p.IDGroup = @IDGroup
	
	union all
	
	select m.IDParent
	from directParents m
	inner join rec on rec.IDParent = m.IDGroup

)
	select IDParent from rec
	union all
	select @IDGroup
)
GO


-- ----------------------------
-- procedure structure for UpdateIndustry2EntityCalculatedFields
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateIndustry2EntityCalculatedFields]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateIndustry2EntityCalculatedFields]
GO

CREATE PROCEDURE [dbo].[UpdateIndustry2EntityCalculatedFields]
	(@IDIndustry int)
AS
BEGIN

declare it cursor for
select IDRecEntity FROM Entity2Industry E2R where IDRecIndustry = @IDIndustry;

	open it;

	declare @IDOrganization int;
	fetch next from it into @IDOrganization

	while @@FETCH_STATUS = 0
	begin
		Update Entity
		set Industries = (SELECT STRING_AGG(Industries ,'; ')
			FROM(SELECT E2R.IDRecEntity, E2R.IDRecIndustry,i.Name AS Industries 
			FROM Entity2Industry E2R LEFT JOIN Industry i ON i.IDIndustry=E2R.IDRecIndustry AND E2R.IDRecEntity = @IDOrganization )m)
		where organizationid = @IDOrganization

		fetch next from it into @IDOrganization
	end

close it;
deallocate it;

end
GO


-- ----------------------------
-- procedure structure for UpdateDocOprRoutineItemDeadline
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateDocOprRoutineItemDeadline]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateDocOprRoutineItemDeadline]
GO

CREATE PROCEDURE [dbo].[UpdateDocOprRoutineItemDeadline]
(
	@IDMouldTest int
)
AS
BEGIN
	update SysDocOprRoutineItem set Deadline = t.Date, Name = t.mname
	from
	(
		select dateadd(MINUTE, DATEPART(TZoffset, date At Time Zone 'GMT Standard Time'), date) Date, IDSysDocOprRoutineItem as IDR, Name as MName
		from MouldTest
		where IDMouldTest = @IDMouldTest
	)t
	where IDRoutineItem = t.IDR
	
	update SysOprRoutineItem set Deadline = t.Date, Name = t.mname
	from
	(
		select dateadd(MINUTE, DATEPART(TZoffset, date At Time Zone 'GMT Standard Time'), date) Date, ri.IDRoutineItem as IDR, mt.Name as MName
		from MouldTest mt
		inner join SysOprRoutineItem ri on ri.DocTemplate = mt.IDSysDocOprRoutineItem
		where IDMouldTest = @IDMouldTest
	)t
	where IDRoutineItem = t.IDR

	declare @IDFollowUpItem bigint = (select top 1 IDFollowUpITem from MouldTest where IDMouldTest = @IDMouldTest);
	exec [UpdateMouldDeadline] @IDFollowUpItem
END
GO


-- ----------------------------
-- function structure for fn_GetChatHierarchy
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[fn_GetChatHierarchy]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[fn_GetChatHierarchy]
GO

CREATE FUNCTION [dbo].[fn_GetChatHierarchy] 
(
    @MessageIDs NVARCHAR(MAX) -- Ex: '1742960,1742961'
)
RETURNS TABLE
AS
RETURN
(
    WITH StartingPoints AS (
        -- Convert the comma-separated string into XML nodes, then extract as rows
        SELECT CAST(O.split.value('.', 'VARCHAR(50)') AS BIGINT) AS IDChat2
        FROM (
            SELECT CAST('<x>' + REPLACE(@MessageIDs, ',', '</x><x>') + '</x>' AS XML) AS x
        ) AS t
        CROSS APPLY x.nodes('/x') AS O(split)
        WHERE LTRIM(RTRIM(O.split.value('.', 'VARCHAR(50)'))) <> ''
    ),
    UpHierarchy AS (
        -- Anchor: start messages
        SELECT c.IDChat2, c.ChatQuestionMessage
        FROM SysChat c
        INNER JOIN StartingPoints sp ON c.IDChat2 = sp.IDChat2

        UNION ALL

        -- Recursive: walk up to parents
        SELECT p.IDChat2, p.ChatQuestionMessage
        FROM SysChat p
        INNER JOIN UpHierarchy uh ON uh.ChatQuestionMessage = p.IDChat2
    ),
    DownHierarchy AS (
        -- Anchor: start messages
        SELECT c.IDChat2, c.ChatQuestionMessage
        FROM SysChat c
        INNER JOIN StartingPoints sp ON c.IDChat2 = sp.IDChat2

        UNION ALL

        -- Recursive: find replies
        SELECT r.IDChat2, r.ChatQuestionMessage
        FROM SysChat r
        INNER JOIN DownHierarchy dh ON r.ChatQuestionMessage = dh.IDChat2
    )
    -- Return the combined distinct IDs from both directions
    SELECT IDChat2 FROM UpHierarchy
    UNION
    SELECT IDChat2 FROM DownHierarchy
);
GO


