-- ----------------------------
-- procedure structure for ChangeVarFromObject
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ChangeVarFromObject]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[ChangeVarFromObject]
GO

CREATE PROCEDURE [dbo].[ChangeVarFromObject]
	-- Add the parameters for the stored procedure here
	@ObjectID int,
	@Var int,
	@VarValue int
	,	@LoginID int =NULL,
	@Note nvarchar(200)='',
	@OperationID int=0
AS
BEGIN
	declare @IDWorkflow int
	declare @IDWorkflowTemplate int
	declare @BitPos int
	declare @VarID int
	set @IDWorkflow = (select top 1 idworkflow from sysworkflowitem where idregisto=@ObjectID);
	Select @VarID=idworkflowvars,@BitPos =bitpos,@IDWorkflowTemplate=IDWorkflow from SysWorkflowVars where syskind=@Var and IDWorkflow = (Select WorkflowClone from SysWorkflow where IDWorkflow=@IDWorkflow)

	declare @StateVar int
	set @StateVar= power(2,@BitPos);

	if @StateVar is not null
	begin
	if @VarValue=1 
		Update [dbo].[SysWorkflow] set StateVars= StateVars | @StateVar where idworkflow=@IDWorkflow
	else
		Update [dbo].[SysWorkflow] set StateVars=StateVars & (~@StateVar) where idworkflow=@IDWorkflow
	end
	--Update nos estados
	declare @Condition int
	DECLARE LC2 CURSOR LOCAL
	
	--FOR select idcondition from SysWorkflowConditionsStep s inner join SysWorkflowConditions c on c.IDWorkflowConditions=s.IDCondition where IDWorkflowVar=@VarID order by c.TargetState asc;
	FOR select idcondition from SysWorkflowConditionsStep s inner join SysWorkflowConditions c on c.IDWorkflowConditions=s.IDCondition where IDWorkflowVar=@VarID order by c.TargetState asc;			
	OPEN LC2;
	FETCH NEXT FROM LC2
		INTO  @Condition;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Chamar funcao para tratar de executar o SQL da condiçao
		Exec ProcSysValidateCondition @Condition,@IDWorkflow;

		FETCH NEXT FROM LC2
			INTO @Condition;
	END;		
	CLOSE LC2;
	DEALLOCATE LC2;

	if( @LoginID is not null) and (@Note is not null)
		exec SS_AddObjectNote @ObjectID, @OperationID, 1, @LoginID, @Note
END
GO


