-- ----------------------------
-- procedure structure for usp_UpdateFollowUpItemAmountRange_FromDocumentNetTotal
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[usp_UpdateFollowUpItemAmountRange_FromDocumentNetTotal]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[usp_UpdateFollowUpItemAmountRange_FromDocumentNetTotal]
GO

CREATE PROCEDURE [dbo].[usp_UpdateFollowUpItemAmountRange_FromDocumentNetTotal]
  @IDDocument INT
AS
BEGIN
  SET NOCOUNT ON;

  /*
    Assumptions / corrections per your note:
      - document.IDModule is UNIQUEIDENTIFIER (not INT)
      - For the given @IDDocument we will use ONLY ONE source value (one DocLines row)

    Source row (single):
      - documentLine.NetTotal
      - documentLine.dim3 (account/opportunity id)
      - documentLine.dim3Module (account/opportunity module id)

    Filters for the single source row:
      - dl.IDLineType = 1   (product lines)
      - dl.IDParent IS NULL (parent row)
      - dl.dim3 IS NOT NULL
      - document.IDModule must be in dbo.GetModulesRec('818D41BB-14CA-43C8-893D-A65797D9E3CA') - Module Quotes

    Update logic on FollowUpItem row matching (dim3, dim3Module):
      - Update AmountValueMin only if NULL or NetTotal < AmountValueMin
      - Update AmountValueMax only if NULL or NetTotal > AmountValueMax
  */

  DECLARE
    @AllowedRoot UNIQUEIDENTIFIER = '818D41BB-14CA-43C8-893D-A65797D9E3CA', 
    @NetTotal DECIMAL(18, 6),
    @Dim3 BIGINT,
    @Dim3Module UNIQUEIDENTIFIER;

  /* Get exactly one DocLines row (if multiple qualify, we pick the first deterministically) */
  SELECT TOP (1)
    @NetTotal = dl.NetTotal,
    @Dim3 = dl.dim3,
    @Dim3Module = TRY_CONVERT(uniqueidentifier, dl.dim3Module)
  FROM documentLine dl
  INNER JOIN document d
    ON d.IDDocument = dl.IDRegister
  WHERE d.IDDocument = @IDDocument
    AND dl.dim3 IS NOT NULL
    AND dl.IDLineType = 1       /* Document lines products */
    AND dl.IDParent IS NULL     /* Parent row */
    AND d.IDModule IN (SELECT IDModule FROM dbo.GetModulesRec(@AllowedRoot))

  /* If no source row found, do nothing */
  IF @Dim3 IS NULL OR @Dim3Module IS NULL OR @NetTotal IS NULL
    RETURN;

  /* Update FollowUpItem for that exact dim3 + module */
  UPDATE f
     SET
       f.AmountValueMin =
         CASE
           WHEN f.AmountValueMin IS NULL THEN @NetTotal
           WHEN @NetTotal < f.AmountValueMin THEN @NetTotal
           ELSE f.AmountValueMin
         END,
       f.AmountValueMax =
         CASE
           WHEN f.AmountValueMax IS NULL THEN @NetTotal
           WHEN @NetTotal > f.AmountValueMax THEN @NetTotal
           ELSE f.AmountValueMax
         END
  FROM FollowUpItem f
  WHERE f.IDRecordAccount = @Dim3
    AND f.IDRecordAccountModule = @Dim3Module;

END;
GO


