-- ----------------------------
-- procedure structure for Query_AllCustomers
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_AllCustomers]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_AllCustomers]
GO

CREATE PROCEDURE [dbo].[Query_AllCustomers]
	@dbmask int
AS
BEGIN
	
	SET NOCOUNT ON;

    select 
		e.organizationid as id,
		e.organization_no as code,
		e.accountname as name,
		coalesce(e.email, '') as email,
		coalesce(e.email2, '') as email2,

		coalesce(replace(replace(e.billingcity, char(13), ' '), char(10), ' '), '') as billingcity,
		coalesce(replace(replace(e.billingcountry, char(13), ' '), char(10), ' '), '') as billingcountry,
		coalesce(replace(replace(e.billingpobox, char(13), ' '), char(10), ' '), '') as billingpobox,
		coalesce(replace(replace(e.billingstate, char(13), ' '), char(10), ' '), '') as billingstate,
		coalesce(replace(replace(e.billingstreet, char(13), ' '), char(10), ' '), '') as billingstreet,
		coalesce(replace(replace(e.billingzip, char(13), ' '), char(10), ' '), '') as billingzip,
		coalesce(replace(replace(e.billingGps, char(13), ' '), char(10), ' '), '') as billingGps,

		coalesce(replace(replace(e.mailingcity, char(13), ' '), char(10), ' '), '') as mailingcity,
		coalesce(replace(replace(e.mailingcountry, char(13), ' '), char(10), ' '), '') as mailingcountry,
		coalesce(replace(replace(e.mailingpobox, char(13), ' '), char(10), ' '), '') as mailingpobox,
		coalesce(replace(replace(e.mailingstate, char(13), ' '), char(10), ' '), '') as mailingstate,
		coalesce(replace(replace(e.mailingstreet, char(13), ' '), char(10), ' '), '') as mailingstreet,
		coalesce(replace(replace(e.mailingzip, char(13), ' '), char(10), ' '), '') as mailingzip,
		coalesce(replace(replace(e.mailingGps, char(13), ' '), char(10), ' '), '') as mailingGps
	from 
		Entity e 
	where (e.dbmask & @dbmask) != 0 and e.RegisterSysStatus = 0 and coalesce(e.emailoptout, 0) = 0
		and
		(e.organizationid in (
			select IDRelatedEntity from asset where IDRelatedEntityModule in ('053A9991-2090-4855-AC8D-34C2F5300DD6') and (dbmask & @dbmask) != 0
			)
		or
		e.organizationid in (
			select IDThirdParty from FollowUpItem where idmodule in (select idmodule from dbo.GetModulesRec('CB18AB15-5DD7-4CFD-8C43-71FE8582F377')) and IDThirdPartyModule in ('053A9991-2090-4855-AC8D-34C2F5300DD6') and (dbmask & @dbmask) != 0
			)
		or
		e.organizationid in (
			select doc_3rd from document where  doc_3rdModule in ('053A9991-2090-4855-AC8D-34C2F5300DD6') 
			and 
				(idmodule in (select idmodule from dbo.GetModulesRec('a61d66d1-31a7-4edc-9059-8341b1611eaf')) -- sales order
				--or
				--idmodule in (select idmodule from dbo.GetModulesRec('0f38b20b-2e4e-4710-b755-f174aa0af572'))  -- pro form
				or
				idmodule in (select idmodule from dbo.GetModulesRec('eb7e2bce-ce1f-43c5-9354-47f5ecf24096'))  -- invoice
				)
				
			and (dbmask & @dbmask) != 0
			)
		)
		and e.organizationid != 50 -- Isicom

 -- select*from SysModule where name like 'compan%'
END
GO


-- ----------------------------
-- function structure for IsValidStatusTransition
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[IsValidStatusTransition]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[IsValidStatusTransition]
GO

CREATE FUNCTION [dbo].[IsValidStatusTransition]
(
	@IDRecord int,
	@IDModule uniqueidentifier,

	@OldStatus int,
	@NewStatus int,

	@IDResource uniqueidentifier
)
RETURNS INT
AS
BEGIN
	-- Declare the return variable here
	DECLARE @r int
	set @r = 0

	declare @enableTransitionValidation int

	select @enableTransitionValidation = coalesce(EnableTransitionValidation, 0) from sysmodule where idmodule = @idmodule

	if @enableTransitionValidation != 0
	begin
		set @r = 1
		
		declare  @Roles table (
			IDRole uniqueidentifier
		)
		-- check resource's roles for the current module
		insert into @Roles (IDRole)
		select IDRole from SysModuleRole where IDResource = @IDResource and IDModule = @IDModule
		
		-- check resource's roles for the current record
		insert into @Roles (IDRole)
		select IDRole from SysRecordResourceRole where IDRecord = @IDRecord and IDRecordModule = @IDModule and IDResource = @IDResource

		-- find a transition between the 2 states using any role owned by the resource
		declare @idtransition uniqueidentifier

		select top 1 @idtransition = IDTransition
		from SysTransition 
		where IniIDModule = @IDModule and IniStatus = @OldStatus AND FinStatus = @NewStatus and IDRole in (
			select IDRole
			from @Roles
		)

		-- return 0 if a transition config was found

		if @idtransition is null 
		begin
			set @r = 1
		end
		else
		begin
			set @r = 0
		end

	end

	return @r

END
GO


-- ----------------------------
-- function structure for GetANGroupDataByPeriod
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetANGroupDataByPeriod]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetANGroupDataByPeriod]
GO

CREATE FUNCTION [dbo].[GetANGroupDataByPeriod]
(	
	@IDANPeriod int
)
RETURNS @Ret Table
(
	ID uniqueidentifier,
	IDParent uniqueidentifier,
	IDGroupChild int,
	IDGroupChildModule uniqueidentifier,
	IDGroupParent int,
	IDGroupParentModule uniqueidentifier,
	IsANCenter int,
	ChildName nvarchar(500),
	ParentName nvarchar(500),
	IDChildCategory int,
	ChildCategory nvarchar(500),
	IDParentCategory int,
	ParentCategory nvarchar(500),
	IDBalance int,
	StartDate datetime,
	EndDate datetime,
	CreditValue numeric(18,5),
	DebitValue numeric(18,5),
	Balance numeric(18,5)
)

AS
Begin

declare @tmp table
(
	IDGroup int,
	IDGroupModule uniqueidentifier,
	IDRoot int, 
	TrueID uniqueidentifier
);

insert into @tmp
select g.ID as IDGroup, g.IDModule ,rec.IDParent as IDRoot, (select GeneratedID from GetNewUniqueidentifierID) as TrueID 
from ANGroup g
cross apply GetANGroupParentsRec(g.ID) rec
inner join ANGroup p on p.ID = rec.IDParent
left join ANGroup2ANGroup g2g on g2g.IDChild = p.ID
where g2g.ID is null;


declare @tmp2 table
(
	IDCenter int,
	IDCenterModule uniqueidentifier,
	IDParent int,
	IDParentModule uniqueidentifier,
	IDRoot int,
	TrueID uniqueidentifier
);

insert into @tmp2
select IDANCenter, g.IDANCenterModule , g.IDANGroup, g.IDANGroupModule, rec.IDParent IDANgroup, (select GeneratedID from GetNewUniqueidentifierID)
from ANGroup2ANCenter g
cross apply GetANGroupParentsRec(g.IDANGroup) rec
left join ANGroup2ANGroup g2g on g2g.IDChild = rec.IDParent
where g2g.ID is null
union all
select c.ID, c.IDModule, null, null, c.ID, (select GeneratedID from GetNewUniqueidentifierID)
from ANCenter c
left join ANGroup2ANCenter g2c on g2c.IDANCenter = c.ID
where g2c.ID is null;

declare @FinalValues Table
(
	IDChild int,
	IDChildModule uniqueidentifier,
	IDParent int,
	IDParentModule uniqueidentifier,
	IDRoot int,
	IDChildID uniqueidentifier,
	IDParentID  uniqueidentifier,
	IsANCenter int,
	ChildName nvarchar(500),
	ParentName nvarchar(500),
	IDChildCategory int,
	ChildCategory nvarchar(500),
	IDParentCategory int,
	ParentCategory nvarchar(500),
	IDBalance int,
	StartDate datetime,
	EndDate datetime,
	CreditValue numeric(18,5),
	DebitValue numeric(18,5),
	Balance numeric(18,5)
);

with base as
(
	select g2g.IDChild, g2g.IDChildModule, g2g.IDParent, g2g.IDParentModule, b1.IDRoot, b.TrueID
	from ANGroup2ANGroup g2g 
	inner join @tmp b on b.IDGroup = g2g.IDChild
	inner join @tmp b1 on b1.IDGroup = g2g.IDParent and b1.IDRoot = b.IDRoot
), baseV2 as
(
	select *
	from base

	union all

	select b1.IDGroup, b1.IDGroupModule, null, null, b1.IDGroup, b1.TrueID 
	from @tmp b1
	where b1.IDGroup = b1.IDRoot
), allGroups as
(
	select b1.IDChild, b1.IDChildModule, b1.IDParent, b1.IDParentModule, b1.IDRoot, b1.TrueID as IDChildID, b2.TrueID as IDParentID
	from baseV2 b1
	left join baseV2 b2 on b1.IDParent = b2.IDChild and b1.IDRoot = b2.IDRoot
), finalGroups as
(
	select ag.*, 0 as IsANCenter, gc.Name as ChildName, gp.Name as ParentName,
	gcc.ID as IDChildCategory, gcc.Name as ChildCategory, gpc.ID as IDParentCategory, gpc.Name as ParentCategory
	from allGroups ag
	inner join ANGroup gc on gc.ID = ag.IDChild
	left join ANCategory gcc on gcc.ID = gc.IDANCategory
	left join ANGroup gp on gp.ID = ag.IDParent
	left join ANCategory gpc on gpc.ID = gp.IDANCategory

	union all

	select c.IDCenter, c.IDCenterModule, g.IDChild, g.IDChildModule, c.IDRoot, c.TrueID, g.IDChildID, 1 as IsAnCenter,
	gc.Name as ChildName, gp.Name as ParentName, gcc.ID as IDChildCategory, gcc.Name as ChildCategory, gpc.ID as IDParentCategory, 
	gpc.Name as ParentCategory
	from @tmp2 c
	left join allGroups g on c.IDParent = g.IDChild and c.IDRoot = g.IDRoot
	inner join ANCenter gc on gc.ID = c.IDCenter
	left join ANCategory gcc on gcc.ID = gc.IDANCategory
	left join ANGroup gp on gp.ID = g.IDChild
	left join ANCategory gpc on gpc.ID = gp.IDANCategory
), groupBalances as
(
	select fg.IDChildID, ap.Name as Period, ab.ID as IDBalance, ab.StartDate , ab.EndDate, isnull(ab.DebitValue,0) DebitValue, isnull(ab.CreditValue,0) CreditValue, 
	isnull(ab.Balance, 0) Balance
	from finalGroups fg
	left join ANBalance ab on ab.IDANGroup = fg.IDChild
	left join ANPeriod ap on ap.ID = ab.IDANPeriod
	where fg.IsANCenter = 0 and ab.IDANPeriod = @IDANPeriod
), anBalancesAll as
(
	select fg.IDChildID, gb.IDBalance ,fg.IDChildCategory, gb.StartDate, gb.EndDate,
	poc.TotalCredit, poc.TotalDebit, poc.movementMode Mode, pocp.movementMode PMode, pocgp.movementMode GPMode, 
	pocggp.movementMode GGPMode, poc.daterecord, poc.IDANCategory IDANCat,
	case when (select COUNT(*) from SysPocValue where IDParent = poc.IDPocValue) = 0 then 0 else 1 end HasChildren
	from finalGroups fg
	inner join ANCenter ac on ac.ID = fg.IDChild
	inner join groupBalances gb on gb.IDChildID = fg.IDParentID
	left join SysPocValue poc on ac.IDAccount = poc.IDRecord and poc.Compensation = 0
	left join SysPocValue pocp on pocp.IDPocValue = poc.IDParent and pocp.Compensation = 0
	left join SysPocValue pocgp on pocgp.IDPocValue = pocp.IDParent and pocgp.Compensation = 0
	left join SysPocValue pocggp on pocggp.IDPocValue = pocgp.IDParent and pocggp.Compensation = 0
	where fg.IsANCenter = 1 
) , anBalances as
(
	select *, CreditValue - DebitValue as Balance
	from
	(
		select b.IDChildID, b.IDBalance, b.IDChildCategory, b.StartDate, b.EndDate,
		isnull(SUM(b.TotalCredit),0) CreditValue, isnull(SUM(b.TotalDebit),0) DebitValue
		from anBalancesAll b
		where (b.IDChildCategory is null or (b.IDChildCategory is not null and b.IDChildCategory = b.IDANCat))
		and datediff(day, b.StartDate, b.DateRecord) >= 0 and datediff(day, b.DateRecord, b.EndDate) >= 0 
		and b.HasChildren = 0
		and
		(
			(b.Mode = 0)
			or (b.Mode = 2 and b.PMode = 0)
			or (b.Mode = 2 and b.PMode = 2 and b.GPMode = 0)
			or (b.Mode = 2 and b.PMode = 2 and b.GPMode = 2 and GGPMode = 0)
		)
		group by b.IDChildID, b.IDBalance, b.IDChildCategory, b.StartDate, b.EndDate
	) t
)
insert into @FinalValues
select fg.*, 
case when fg.IsANCenter = 0 then gb.IDBalance else ab.IDBalance end IDBalance, 
case when fg.IsANCenter = 0 then gb.StartDate else ab.StartDate end StartDate, 
case when fg.IsANCenter = 0 then gb.EndDate else ab.EndDate end EndDate, 
isnull(case when fg.IsANCenter = 0 then gb.CreditValue else ab.CreditValue end,0) CreditValue, 
isnull(case when fg.IsANCenter = 0 then gb.DebitValue else ab.DebitValue end,0) DebitValue, 
isnull(case when fg.IsANCenter = 0 then gb.Balance else ab.Balance end,0) Balance
from finalGroups fg
left join groupBalances gb on gb.IDChildID = fg.IDChildID and fg.IsANCenter = 0
left join anBalances ab on ab.IDChildID = fg.IDChildID and fg.IsANCenter = 1

declare @tmp3 Table
(
	IDChildID uniqueidentifier,
	IDParentID uniqueidentifier,
	IDBalance int, 
	StartDate datetime,
	EndDate datetime,
	NewIDChildID uniqueidentifier
)
insert into @tmp3
select distinct IDChildID, IDParentID, IDBalance, StartDate, EndDate, (select GeneratedID from GetNewUniqueidentifierID)
from @FinalValues;

with newIDs as
(
	select t1.*, t2.NewIDChildID as NewIDParentID 
	from @tmp3 t1
	left join @tmp3 t2 on t1.IDParentID = t2.IDChildID and t1.StartDate = t2.StartDate and t1.EndDate = t2.EndDate
)
insert into @Ret
select ni.NewIDChildID as ID, ni.NewIDParentID as IDParent, fv.IDChild, fv.IDChildModule, fv.IDParent, fv.IDParentModule,
fv.IsANCenter, fv.ChildName, fv.ParentName, fv.IDChildCategory,fv.ChildCategory,fv.IDParentCategory,fv.ParentCategory,
fv.IDBalance,fv.StartDate,fv.EndDate,fv.CreditValue,fv.DebitValue,fv.Balance
from @FinalValues fv
inner join newIDs ni on ni.IDChildID = fv.IDChildID 
and ((ni.IDParentID = fv.IDParentID) or (ni.IDParentID is null and fv.IDParentID is null)) 
and ((ni.IDBalance = fv.IDBalance) or (ni.IDBalance is null and fv.IDBalance is null)) 
and (fv.StartDate = ni.StartDate and fv.EndDate = ni.EndDate)

return

end
GO


-- ----------------------------
-- function structure for GetActivityPoint
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetActivityPoint]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetActivityPoint]
GO

CREATE FUNCTION [dbo].[GetActivityPoint]
(
	@startDate as datetime,
	@endDate as datetime,
	@IDUser as uniqueidentifier,
	@IDUserPerformer as uniqueidentifier
)
RETURNS int
AS
BEGIN
	DECLARE @IDPoint int=null
	DECLARE @typeWork int=7
	
	select top 1 
	@IDPoint=p.IDActivity 
	from Activity p 
	where 
	p.startDate<= DATEADD(second,30, @startDate) and p.endDate >=DATEADD(second,-30,@endDate )

	and p.IDModule='3942890B-539A-4B1B-A491-2CA2A982FB7D'
	and p.type=@typeWork
	and (
	((@IDUserPerformer is not null  and p.IDUserPerformer is null ) and p.IDUser=@IDUserPerformer)
	OR 
	((@IDUserPerformer is null  and p.IDUserPerformer is null )  and p.IDUser=@IDUser)
	OR
	((@IDUserPerformer is not null  and p.IDUserPerformer is not null ) and p.IDUserPerformer=@IDUserPerformer)
	OR 
	((@IDUserPerformer is null  and p.IDUserPerformer is not null )  and p.IDUserPerformer=@IDUser)
	)

	return @IDPoint
END
GO


-- ----------------------------
-- function structure for GetAccountUsageInDocuments
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetAccountUsageInDocuments]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetAccountUsageInDocuments]
GO

CREATE FUNCTION [dbo].[GetAccountUsageInDocuments]
(	
	@IDAccount int,
	@IDAccountModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	
	select
		d.IDDocument,
		d.IDModule as IDDocumentModule,

		d.doc_ref,
		d.doc_date,
		d.doc_3rd_account,
		d.doc_3rd_account_name,
		d.doc_3rd_accountModule,
		d.doc_3rd,
		d.doc_3rdModule,
		d.[subject],

		dl.ID as IDDocLine,

		dl.lineNumber,
		dl.Qty,
		dl.UnitPrice,
		dl.DiscountPerc1,
		dl.DiscountPerc2,
		dl.DiscountPerc3,
		dl.DiscountEur,
		dl.AssetSerial,
		dl.NetTotal

	from 
		document d 
	
		inner join documentline dl on d.iddocument = dl.idregister
	where
		--dl.productid = @IDAccount
		--and
		--dl.productidModule = @IDAccountModule
		(
			(
				(dl.dim1 = @IDAccount and dl.dim1Module = @IDAccountModule)
				or
				(dl.dim2 = @IDAccount and dl.dim2Module = @IDAccountModule)
				or
				(dl.dim3 = @IDAccount and dl.dim3Module = @IDAccountModule)
				or
				(dl.dim4 = @IDAccount and dl.dim4Module = @IDAccountModule)
				or
				(dl.dim5 = @IDAccount and dl.dim5Module = @IDAccountModule)
				or
				(dl.dim6 = @IDAccount and dl.dim6Module = @IDAccountModule)
				or
				(dl.dim7 = @IDAccount and dl.dim7Module = @IDAccountModule)
				or
				(dl.dim8 = @IDAccount and dl.dim8Module = @IDAccountModule)
				or
				(dl.dim9 = @IDAccount and dl.dim9Module = @IDAccountModule)
				or
				(dl.dim10 = @IDAccount and dl.dim10Module = @IDAccountModule)
				or
				(dl.dim11 = @IDAccount and dl.dim11Module = @IDAccountModule)
				or
				(dl.dim12 = @IDAccount and dl.dim12Module = @IDAccountModule)
				or
				(dl.dim13 = @IDAccount and dl.dim13Module = @IDAccountModule)
				or
				(dl.dim14 = @IDAccount and dl.dim14Module = @IDAccountModule)
				or
				(dl.dim15 = @IDAccount and dl.dim15Module = @IDAccountModule)
				or
				(dl.dim16 = @IDAccount and dl.dim16Module = @IDAccountModule)
				or
				(dl.dim17 = @IDAccount and dl.dim17Module = @IDAccountModule)
			)

			OR
			
			(
				(d.IDDocSecund3rdParty = @IDAccount and d.IDDocSecund3rdPartyModule = @IDAccountModule and dl.IDParent is null)
				or
				(d.doc_3rd = @IDAccount and d.doc_3rdModule = @IDAccountModule and dl.IDParent is null)
				or
				(d.doc_account = @IDAccount and d.doc_accountModule = @IDAccountModule and dl.IDParent is null)
			)
		)


		and
		d.RegisterSysStatus = 0
)
GO


