-- ----------------------------
-- function structure for GetSatisfiedQuantitiesForFUP
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetSatisfiedQuantitiesForFUP]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetSatisfiedQuantitiesForFUP]
GO

CREATE FUNCTION [dbo].[GetSatisfiedQuantitiesForFUP]
(
	@ID bigint,
	@IDModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	with documentsRelated as
	(
		select fup.IDFollowUpItem, fup.IDModule as IDFollowUpItemModule ,IDDocument, d.IDModule as IDDocumentModule,  d.IDModule, doc_ref,  d.RegisterStatus, d.status, D.PartitionColumn, d.doc_date, d.doc_3rd, d.doc_3rd_idmodule as doc_3rdModule,
		d.AssignedResourcesList, d.subject
		from FollowUpItem fup
		inner join DocumentLine dl on dl.IDLineType = 1 and dim3 = fup.IDRecordAccount and dl.dim3Module = fup.IDRecordAccountModule
		inner join document d on dl.PartitionColumn = d.PartitionColumn and dl.IDRegister = d.IDDocument and dl.IDModule = d.IDModule
		where fup.IDFollowUpItem = @ID and fup.IDModule = @IDModule
	), documentLinesAscendants as 
	(
		select dr.*, dl.ID, dl.LineNumber, dl.ProductCode, dl.ProductName, dl.Qty, dl.productid, dl.productidModule
		from DocumentLine dl
		inner join documentsRelated dr on dr.PartitionColumn = dl.PartitionColumn and dr.IDDocument = dl.IDRegister and dr.IDModule = dl.IDModule
		where dl.productid is not null

	), documentLineDescendants as
	(
		select dl.ID as IDLineSrc, dl.Qty, dc.IDDocument, dc.IDModule, dc.doc_ref, dc.RegisterStatus, dlc.ID, dlc.LineNumber, dlc.Qty as QtyDescendant
		from DocumentLine dl
		inner join documentLinesAscendants d on d.ID = dl.ID
		inner join DocumentLine dlc on dlc.LineLink = dl.ID and dlc.LineLinkModule = dl.IDModule and dlc.productid = dl.productid
		inner join document dc on dlc.PartitionColumn = dc.PartitionColumn and dlc.IDRegister = dc.IDDocument and dlc.IDModule = dc.IDModule
	), numberOfDescendants as
	(
		select IDLineSrc, COUNT(distinct IDDocument) as CountDocDescendants
		from documentLineDescendants
		group by IDLineSrc
	), quantitiesSatisified as(
		select dlc.IDLineSrc, dlc.Qty, 
		isnull(sum(case when m.KindTransaction = 2 then isnull(dlc.QtyDescendant,0) else 0 end), 0) SalesSatisfied,
		isnull(sum(case when m.KindTransaction = 1 then isnull(dlc.QtyDescendant,0) else 0 end), 0) PurchasesSatisfied
		from documentLineDescendants dlc
		inner join SysModule m on m.IDModule = dlc.IDModule
		where dlc.RegisterStatus = 1
		group by dlc.IDLineSrc, dlc.Qty
	)
	select dl.*,nd.CountDocDescendants, qs.PurchasesSatisfied, qs.SalesSatisfied
	from documentLinesAscendants dl
	left join numberOfDescendants nd on nd.IDLineSrc = dl.ID
	left join quantitiesSatisified qs on qs.IDLineSrc = dl.ID
);
GO


