-- ----------------------------
-- function structure for GetHasTaskProductionAttachments
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetHasTaskProductionAttachments]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetHasTaskProductionAttachments]
GO

CREATE FUNCTION [dbo].[GetHasTaskProductionAttachments]
(
	@IDTask uniqueidentifier
)
RETURNS int
AS
BEGIN	
	DECLARE @ret int
	set @ret = (select case when (t.TechnicalSpecification <> '' and t.TechnicalSpecification is not null) or attachments > 0 then 1 else 0 end as HasInfo
	from
	(
		select  t.TechnicalSpecification ,isnull(count(distinct f2t.ID),0) attachments
		from SysTask t
		inner join SysOprRoutineItem ri on ri.IDSysTask= t.IDTask
		left join File2SysTask f2t on f2t.IDSysTask = t.IDTask and f2t.IDSysTaskModule = t.IDModule
		where IDTask = @IDTask
		group by t.TechnicalSpecification
	) t);

	RETURN @ret
END
GO


