	DROP PROCEDURE [dbo].[UpdateFinishedRoutineNotifications]
GO

CREATE PROCEDURE [dbo].[UpdateFinishedRoutineNotifications]
AS 
BEGIN
	update RoutineNotifications set Finished = 1 
	where ID in
	(
		select rn.ID 
		from RoutineNotifications rn
		inner join SysOprRoutineItem ri on ri.IDRoutineItem = rn.IDRoutineItem
		where Kind = 2 and Finished = 0
		and (DATEDIFF(DAY, isnull(ri.Deadline, ri.CalculatedDeadline), GETDATE()) > ISNULL(rn.DaysAfter, 0))
	) 
	OR Kind in(0,1);
END
GO


-- ----------------------------
-- procedure structure for GetPartsInProdutionList
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPartsInProdutionList]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetPartsInProdutionList]
GO

CREATE PROCEDURE [dbo].[GetPartsInProdutionList]
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    SELECT o.ID, 
o.FullName, 
o.Priority as IDPriority, 
CASE o.Priority   
     WHEN 1 THEN 'Very Low'  
     WHEN 2 THEN 'Low'  
	 WHEN 3 THEN 'Normal'  
	 WHEN 4 THEN 'High'  
	 WHEN 5 THEN 'Urgent'  
	 ELSE ''   
END As Priority ,
o.PriorityManagement, 
CASE o.CleanState   
     WHEN 1 THEN ''  
     WHEN 2 THEN 'Powder'  
	 WHEN 3 THEN 'Dielectric'  
	 WHEN 4 THEN 'Dirty Scobs'  
	 ELSE ''   
END As CleanState ,
COALESCE(np.Code, '') as 'CurrentPosition', 
COALESCE(np.MachineCode, '') as 'CurrentResource' ,

( SELECT COUNT(*) FROM SysOprRoutine WHERE PartID IN (SELECT Distinct(ToolID) FROM SS_Program WHERE IDJob IS NULL AND Kind = 5 AND IDObject = o.ID) AND WorkingStatus = '88B381D9-D1DB-4C80-8E78-3076B1E196F2') as 'DoneEL',
( SELECT COUNT(DISTINct(IDTOOL)) FROM SysJobLine WHERE IDProgram IN ( SELECT ID FROM SS_Program WHERE IDJob IS NOT NULL AND Kind = 5 AND IDObject = o.ID) AND Status = '88B381D9-D1DB-4C80-8E78-3076B1E196F2' AND IDTool IS NOT NULL AND IDTool <> '00000000-0000-0000-0000-000000000000') as 'UsedEL',

( SELECT COUNT(Distinct(ToolID)) FROM SS_Program WHERE IDJob IS NULL AND Kind = 5 AND IDObject = o.ID) as 'TotalEL',
o.DeliveryDate as 'DeliveryDate',
ri.WorkingStatus AS 'EDMState',
COALESCE(ws.Code, '') AS 'EDMStateName',
COALESCE(m.code,'') AS 'Material',
COALESCE(pt.code,'') AS 'PartType',
COALESCE(f.Code, '') AS 'Holder',
COALESCE(o.DimBlock_X, 0) AS 'DimX',
COALESCE(o.DimBlock_Y, 0) AS 'DimY',
COALESCE(o.DimBlock_Z, 0) AS 'DimZ'

FROM SS_Object o 
LEFT JOIN SM_NodePart npt ON o.ID = npt.ID
LEFT JOIN SM_NodePosic np ON npt.IDEntryPosition = np.ID
LEFT JOIN SysOprRoutineItem ri ON o.ID = ri.IDPart AND ri.IDOperationType = '0B310861-E07E-460F-87F0-D9120455CD2D'
LEFT JOIN SysWorkingStatus ws ON ri.WorkingStatus = ws.ID
LEFT JOIN SS_Material m ON o.IDMaterial = m.IDMaterial
LEFT JOIN SysPartType pt ON o.IDPartType = pt.ID
LEFT JOIN SysFixture f ON o.IDHolder = f.ID
WHERE o.TypeID = 1
AND o.IDRoutine IS NOT NULL
--AND o.ID IN (SELECT IDPart FROM SysOprRoutineItem WHERE WorkingStatus <> '88B381D9-D1DB-4C80-8E78-3076B1E196F2')
AND o.Visibility = 0
AND ( SELECT COUNT(Distinct(ToolID)) FROM SS_Program WHERE IDJob IS NULL AND Kind = 5 AND IDObject = o.ID) > 0
ORDER BY o.Priority DESC, ISNULL(o.DeliveryDate, DATEADD(d, 90, GETDATE())) ASC, o.PriorityManagement DESC, o.FullName

END
GO


-- ----------------------------
-- function structure for StringIndex
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[StringIndex]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[StringIndex]
GO

CREATE FUNCTION [dbo].[StringIndex]
(
	@haystack nvarchar(max),
	@needle nvarchar(max)
)
RETURNS INT
AS
BEGIN
	declare @st int
	declare @len int
	declare @slen int
	declare @p int
	declare @t int

	set @st = 1
	set @len = LEN(@haystack)
	set @slen = LEN(@needle)
	set @p = 0

	if @len = 0 or @slen = 0
	begin
		goto _end
	end

	while @st <= @len 
	begin
		
		declare @sst int
		declare @c nvarchar(1)
		declare @prev int 

		set @sst = 1		
		set @prev = -1

		while @sst <= @slen
		begin
			set @c = SUBSTRING(@needle, @sst, 1)
				
			set @t = CHARINDEX(@c, @haystack,  @st + @sst - 1 )
			
			if @t = 0 
			begin
				set @st = @st + 1
				goto _continue
			end
						
			if @prev = -1
			begin
				set @prev = @t
				set @st = @t
			end
			else
			begin
				if @prev + 1 = @t 
				begin
					set @prev = @prev + 1
				end
				else
				begin
					set @st = @st + 1
					goto _continue
				end
			end
			
			set @sst = @sst + 1
		end

		set @p = @st
		goto _end

		_continue:

	end 

	_end:

	RETURN @p
END
GO


-- ----------------------------
-- procedure structure for FixModuleDSITemCodes
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FixModuleDSITemCodes]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[FixModuleDSITemCodes]
GO

CREATE PROCEDURE [dbo].[FixModuleDSITemCodes]
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

DECLARE 
	@IDSysDSItem uniqueidentifier,@IDModuleDSItem uniqueidentifier,
	@counter int,@mask nvarchar(50),@code nvarchar(50)
	
	SET @IDModuleDSItem='3b1b0061-948e-4828-94f7-7787b9ad6891'
	SET @counter=(Select CurrentCounter from SysModule where IDModule=@IDModuleDSItem)
	
	BEGIN TRAN T1;

		DECLARE CursorDSItems CURSOR FOR 
		select IDSysDSItem from SysDSItem where Code_counter is null or Code is null or Code=''
	
		OPEN CursorDSItems
		FETCH NEXT FROM CursorDSItems INTO @IDSysDSItem
		WHILE @@FETCH_STATUS = 0
		BEGIN
	
			set @counter=@counter+1
			SET @code=FORMAT(@counter,'0#####')
			SET @mask = CONCAT ('DSI',@code)
		
			UPDATE SysDSItem SET Code=@mask,Code_counter=@counter WHERE IDSysDSItem=@IDSysDSItem
	
			FETCH NEXT FROM CursorDSItems INTO @IDSysDSItem
		END

		CLOSE CursorDSItems
		DEALLOCATE CursorDSItems
	
		UPDATE SysModule SET CurrentCounter=@counter WHERE IDModule=@IDModuleDSItem
	
	COMMIT TRAN T1;
	--ROLLBACK TRAN T1;

END
GO


