-- ----------------------------
-- function structure for GetResourcesPrevisionV2
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourcesPrevisionV2]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourcesPrevisionV2]
GO

CREATE FUNCTION [dbo].[GetResourcesPrevisionV2]
(	
	-- Add the parameters for the function here
	@IDPart uniqueidentifier, 
	@IDOperationType uniqueidentifier,
	@IDStorage uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT LTRIM(RTRIM(r.Code)) AS Code FROM SM_NodePosic np  
INNER JOIN SysResources r ON r.ResourceId = np.MachineID
 WHERE  np.WorkPosition = 1
 AND r.PartHandlingMode = 0 
 AND r.Mode <> 1 AND np.ID IN (

SELECT DISTINCT(IDNode) FROM SM_NodePosicConfiguration c
INNER JOIN (
SELECT MAX(p.FileType) as FileType, j.IDOperationType, o.IDPartType, O.IDMaterial, nprt.IDEntryPosition FROM SysJobLine jl
INNER JOIN SysJob j ON j.ID = jl.IDJob
INNER JOIN SS_Program p ON p.ID = jl.IDProgram
INNER JOIN SS_Object o ON o.ID = p.IDObject
INNER JOIN SM_NodePart nprt ON nprt.ID = o.ID
INNER JOIN SM_NodePosic nps ON nps.ID = nprt.IDEntryPosition
WHERE o.ID = @IDPart
AND jl.IDOperationType = @IDOperationType
AND jl.Status IN ('CD69321D-BF74-4503-A9D6-0614F0C7CE01',
'2966AB3D-D7B6-4228-831B-342618A0FB13',
'C6812E70-56CB-4394-84A5-4C3DE719B44E',
'483D173F-7287-4751-A9D1-741DAAAB41E0')

GROUP BY j.IDOperationType, o.IDPartType, O.IDMaterial, nprt.IDEntryPosition) t ON 
c.WorkAssignment = 1
AND
(c.IDOperationType = t.IDOperationType) 
AND
(c.IDFileType IS NULL OR c.IDFileType = t.FileType)
AND
(c.IDMaterial IS NULL OR c.IDMaterial = '00000000-0000-0000-0000-000000000000' OR c.IDMaterial = t.IDMaterial)
AND
(c.IDPartType IS NULL OR c.IDPartType = '00000000-0000-0000-0000-000000000000' OR c.IDPartType = t.IDPartType)
AND 
(t.IDEntryPosition IS NOT NULL AND 
	(c.IDStorage IS NULL 
	OR c.IDStorage = '00000000-0000-0000-0000-000000000000' 
	OR c.IDStorage = @IDStorage 
	)
)
WHERE t.IDOperationType = @IDOperationType
)
)
GO


-- ----------------------------
-- function structure for ToTicks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[ToTicks]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[ToTicks]
GO

CREATE FUNCTION [dbo].[ToTicks] ( @DateTime datetime2 )
  RETURNS bigint
AS
BEGIN
    DECLARE @Days bigint = DATEDIFF( DAY, '00010101', cast( @DateTime as date ) );
    DECLARE @Seconds bigint = DATEDIFF( SECOND, '00:00', cast( @DateTime as time( 7 ) ) );
    DECLARE @Nanoseconds bigint = DATEPART( NANOSECOND, @DateTime );
    RETURN  @Days * 864000000000 + @Seconds * 10000000 + @Nanoseconds / 100;
END
GO


-- ----------------------------
-- function structure for GetMouldID
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetMouldID]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetMouldID]
GO

CREATE FUNCTION [dbo].[GetMouldID]
(
	@AssetID int
)
RETURNS int
AS
BEGIN
	declare @ParentKind int;
	declare @ParentID int;
	--Ir buscar todos os assets pai deste até que se encontre uma peça de produção do tipo molde
	set @ParentID=(Select rel.crmid from Crmentityrel rel where rel.relcrmid=@AssetID and rel.rel_assetreltype='Production');
	set @ParentKind = (Select SS_Object.IDType from SS_Object where idobject=@ParentKind);

	while (@ParentID is not null) and (@ParentKind is not null) and (@ParentKind<>3)
	begin
		set @ParentID=(Select rel.crmid from Crmentityrel rel where rel.relcrmid=@AssetID and rel.rel_assetreltype='Production');
		set @ParentKind = (Select SS_Object.IDType from SS_Object where idobject=@ParentKind);
	end;

	return @ParentID;

END
GO


