	DROP PROCEDURE [dbo].[REfreshWFALL]
GO

CREATE PROCEDURE [dbo].[REfreshWFALL]

AS
BEGIN
		DECLARE LocalCursor CURSOR LOCAL 
		FOR select id from SS_Object 
		DECLARE @ChildID int
		OPEN LocalCursor;
		FETCH NEXT FROM LocalCursor
			INTO @CHILDID;
		
		WHILE @@FETCH_STATUS = 0
		BEGIN
			exec [dbo].[RefreshWFTemplate] @ChildID

			FETCH NEXT FROM LocalCursor
				INTO @ChildID;
		END;
		
		CLOSE LocalCursor;
		DEALLOCATE LocalCursor;
			

END
GO


-- ----------------------------
-- procedure structure for FindGUID
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[FindGUID]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[FindGUID]
GO

CREATE PROCEDURE [dbo].[FindGUID] @searchValue uniqueidentifier AS

/*
    Search all tables in the database for a guid

    Revision History
    6/9/2009: Initally created
    6/10/2009: Build or clause of multiple columns on one table
*/

--DECLARE @searchValue uniqueidentifier
--SET @searchValue = '{2A6814B9-8261-452D-A144-13264433864E}'

DECLARE abc CURSOR FOR
    SELECT 
        c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME
    FROM INFORMATION_SCHEMA.Columns c
        INNER JOIN INFORMATION_SCHEMA.Tables t
        ON c.TABLE_NAME = t.TABLE_NAME
        AND t.TABLE_TYPE = 'BASE TABLE'
    WHERE DATA_TYPE = 'uniqueidentifier'

DECLARE @tableSchema varchar(200)
DECLARE @tableName varchar(200)
DECLARE @columnName varchar(200)
DECLARE @szQuery varchar(8000)
SET @szQuery = ''

DECLARE @lasttable varchar(255);
SET @lasttable='';

OPEN ABC

FETCH NEXT FROM abc INTO @tableSchema, @tableName, @columnName;
WHILE (@@FETCH_STATUS = 0)
BEGIN
   IF(@lasttable=@tablename) 
   BEGIN
      SET @szQuery = @szQuery + ' OR [' + @columnName + ']=''' + CAST(@searchValue AS varchar(50)) + '''';
   END 
   ELSE 
   BEGIN
       SET @lasttable = @tablename;

       IF @szQuery <> '' 
       BEGIN
          PRINT @szQuery
          EXEC ('IF EXISTS (' + @szQuery + ') BEGIN ' + @szQuery + ' END');
       END

       SET @szQuery = 
         'SELECT '''+@tableSchema+'.'+@tableName+''' AS TheTable, ''['+@columnName+']'' AS TheColumn '+
         'FROM '+@tableName+' '+
         'WHERE ['+@columnName+'] = '''+CAST(@searchValue AS varchar(50))+''''
   END
   FETCH NEXT FROM abc INTO @tableSchema, @tableName, @columnName;
END

CLOSE abc
DEALLOCATE abc

IF @szQuery <> '' 
BEGIN
    PRINT @szQuery
    EXEC ('IF EXISTS (' + @szQuery + ') BEGIN ' + @szQuery + ' END');
END
GO


-- ----------------------------
-- function structure for aux_MRRP_f_14c4b50cf5724f43a72bb6e5e35b7e3a
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[aux_MRRP_f_14c4b50cf5724f43a72bb6e5e35b7e3a]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[aux_MRRP_f_14c4b50cf5724f43a72bb6e5e35b7e3a]
GO

CREATE FUNCTION [dbo].[aux_MRRP_f_14c4b50cf5724f43a72bb6e5e35b7e3a]
(
@id int
)
RETURNS nvarchar(max)
AS
BEGIN
declare @r nvarchar(max)
SELECT @r = STRING_AGG(t_MRRP2.AssignResourceCode ,'; ')
 FROM (select a2r.ID, arra.IDTaskResourceRole, arra.IDTask,arra.IDResource,arra.IDUser ,l.FullName,r.Code, 
CONCAT(l.FullName,' (',TRIM(r.Code),')') AS AssignResourceCode
FROM  SysTask2Record a2r
inner join SysTaskResourceRole  arra  on a2r.IDTask= arra.IDTask
LEFT JOIN SysResources r on r.ResourceId=arra.IDResource
LEFT Join SysLogin l on l.IDLogin =arra.IDUser) as t_MRRP2 
 WHERE @id=t_MRRP2.ID
return @r
END
GO


-- ----------------------------
-- procedure structure for SearchIntAllTables
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SearchIntAllTables]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SearchIntAllTables]
GO

CREATE PROCEDURE [dbo].[SearchIntAllTables]
(
    @SearchStr nvarchar(100)
)
AS
BEGIN

-- Copyright © 2002 Narayana Vyas Kondreddi. All rights reserved.
-- Purpose: To search all columns of all tables for a given search string
-- Written by: Narayana Vyas Kondreddi
-- Site: http://vyaskn.tripod.com
-- Tested on: SQL Server 7.0 and SQL Server 2000
-- Date modified: 28th July 2002 22:50 GMT

DECLARE @Results TABLE(ColumnName nvarchar(370), ColumnValue nvarchar(3630))

SET NOCOUNT ON

DECLARE @TableName nvarchar(256), @ColumnName nvarchar(128), @SearchStr2 nvarchar(110)
SET  @TableName = ''
SET @SearchStr2 = QUOTENAME('%' + @SearchStr + '%','''')

WHILE @TableName IS NOT NULL
BEGIN
    SET @ColumnName = ''
    SET @TableName = 
    (
        SELECT MIN(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME))
        FROM    INFORMATION_SCHEMA.TABLES
        WHERE       TABLE_TYPE = 'BASE TABLE'
            AND QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) > @TableName
            AND OBJECTPROPERTY(
                    OBJECT_ID(
                        QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)
                         ), 'IsMSShipped'
                           ) = 0
    )

    WHILE (@TableName IS NOT NULL) AND (@ColumnName IS NOT NULL)
    BEGIN
        SET @ColumnName =
        (
            SELECT MIN(QUOTENAME(COLUMN_NAME))
            FROM    INFORMATION_SCHEMA.COLUMNS
            WHERE       TABLE_SCHEMA    = PARSENAME(@TableName, 2)
                AND TABLE_NAME  = PARSENAME(@TableName, 1)
                AND DATA_TYPE IN ('int', 'bigint')
                AND QUOTENAME(COLUMN_NAME) > @ColumnName
        )

        IF @ColumnName IS NOT NULL
        BEGIN
            INSERT INTO @Results
            EXEC
            (
                'SELECT ''' + @TableName + '.' + @ColumnName + ''', LEFT(' + @ColumnName + ', 3630) 
                FROM ' + @TableName + ' (NOLOCK) ' +
                ' WHERE ' + @ColumnName + ' LIKE ' + @SearchStr2
            )
        END
    END 
END

SELECT ColumnName, ColumnValue FROM @Results
END
GO


-- ----------------------------
-- procedure structure for Query_MaintenanceSWSC_NoTicketsInXTime
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Query_MaintenanceSWSC_NoTicketsInXTime]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[Query_MaintenanceSWSC_NoTicketsInXTime]
GO

CREATE PROCEDURE [dbo].[Query_MaintenanceSWSC_NoTicketsInXTime]

AS
BEGIN
	SET NOCOUNT ON;
		
	-- setup helper table with businessarea

	declare @businessarea table (id int null);
	with barea_cte(idbusinessarea, idparent)
	as (
		select IDBusinessArea, IDParent
		from BusinessArea
		where name like 'CAD_CAM'
		union all
		select ba.IDBusinessArea, ba.IDParent
		from BusinessArea ba inner join barea_cte b2 on ba.idparent = b2.idbusinessarea
	)
	insert into @businessarea(id) select idbusinessarea from barea_cte;

	-- setup helper table with service contracts with maintenance 
	
	declare @AllWithMaint table (
		id int null,
		idModule uniqueidentifier null
	)
	
	insert into @AllWithMaint(id, idModule)
	select IDEntityRelatedTo, IDEntityRelatedToModule
	from ServiceContract
	where (dbmask & 1) != 0 
	and 
	-- (subject like '%sw% ' or subject like '%sc%')
	(IDBusinessArea in (select id from @businessarea))
	and 
	RegisterSysStatus = 0
	and
	(status = 2667)

	-- 
	-- costumers with maintenance contract and no activities related to tickets in the last 2 months
	select distinct 
		e.organization_no as orgNo, 
		e.accountname as orgName, 
		isnull(e.email, '') as email, 
		isnull(e.email2, '') as email2
	from 
		entity e 
		inner join @AllWithMaint m on e.organizationid = m.id
		and not exists(
			select*
			from Activity a
				inner join Activity2Record a2r on a.IDActivity = a2r.IDActivity and a.IDModule = a2r.IDActivityModule and a.RegisterSysStatus = 0
				inner join FollowUpItem f on a2r.relatedRecord = f.IDFollowUpItem and a2r.relatedRecordModule = f.idmodule and f.RegisterSysStatus = 0
			where 
				(a.createdtime >= DATEADD(month, -2, getdate()) 
				and
				(a.dbmask & 1) != 0 
				and
				(f.dbmask & 1) != 0 
				and 
				f.IDThirdParty = m.id and f.idthirdpartyModule = m.idModule)
				and 
				f.idmodule in (select idmodule from dbo.GetModulesRec('CB18AB15-5DD7-4CFD-8C43-71FE8582F377'))
		)
	order by e.organization_no


END
GO


-- ----------------------------
-- function structure for GetPartID
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetPartID]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetPartID]
GO

CREATE FUNCTION [dbo].[GetPartID]
(
	@AssetID int
)
RETURNS int
AS
BEGIN
	declare @ParentKind int;
	declare @ParentID int;
	--Ir buscar todos os assets pai deste até que se encontre uma peça de produção do tipo molde
	set @ParentID=(Select rel.crmid from Crmentityrel rel where rel.relcrmid=@AssetID and rel.rel_assetreltype='Production');
	set @ParentKind = (Select SS_Object.IDType from SS_Object where idobject=@ParentKind);

	while (@ParentID is not null) and (@ParentKind is not null) and (@ParentKind<>1)
	begin
		set @ParentID=(Select rel.crmid from Crmentityrel rel where rel.relcrmid=@AssetID and rel.rel_assetreltype='Production');
		set @ParentKind = (Select SS_Object.IDType from SS_Object where idobject=@ParentKind);
	end;

	return @ParentID;

END
GO


