-- ----------------------------
-- procedure structure for RefreshWFTemplate
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[RefreshWFTemplate]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[RefreshWFTemplate]
GO

CREATE PROCEDURE [dbo].[RefreshWFTemplate]
	@ObjectID int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

/****** Script for SelectTopNRows command from SSMS  ******/
Declare @WFID int;
Declare @WFTempID int;
set @WFID = (Select top 1 idworkflow from SysWorkflowItem where idregisto=@ObjectID)
set @WFTempID = (Select WorkflowClone from SysWorkflow where idworkflow=@WFID)

--Adicionar os WFI que existem no WF template e nao no do objecto
INSERT INTO [dbo].[SysWorkflowItem] ([IDWorkflow] ,[IDModule] ,[IDKIND],[IDRegisto] ,[IDRole] ,[Disponibilidade] ,[Priority] ,[Severity] ,[Complexity] ,[Descricao] ,[Code] ,[Order] ,[Template], [WorkflowItemKind],[IDTranslation])
    SELECT @WFID AS 'IsTemplate',[IDModule],[IDKIND],@ObjectID, [IDRole], [Disponibilidade], [Priority],[Severity] ,[Complexity] ,[Descricao] ,[Code] ,[Order] , [IDWorkflowItem], [WorkflowItemKind],[IDTranslation] 
	FROM [SysWorkflowItem] si
	WHERE [IDWorkflow] = @WFTempID  and si.idkind not in (select idkind from SysWorkflowItem where IDWorkflow=@WFID)
	


--Forçar a calcular 
	declare @IDCondition int;
	--Actualizar Estados de operaçoes
	DECLARE lc CURSOR LOCAL
	FOR Select idworkflowconditions
	from SysWorkflowConditions c
	inner join SysWorkflowItem i on i.IDWorkflowItem=c.IDWorkflowItem and i.IDWorkflow=@WFTempID
	OPEN lc;
	FETCH NEXT FROM lc
		INTO  @IDCondition;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Fechar Vars
		exec [dbo].[ProcSysValidateCondition] @IDCondition,@WFID

		FETCH NEXT FROM lc
		INTO @IDCondition;
	END;
		
	CLOSE lc;
	DEALLOCATE lc;
END
GO


-- ----------------------------
-- function structure for Entity2AssetsTree
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[Entity2AssetsTree]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[Entity2AssetsTree]
GO

CREATE FUNCTION [dbo].[Entity2AssetsTree](
	@IDEntity int,
	@IDEntityModule uniqueidentifier
)
  
RETURNS TABLE
AS
RETURN
(
	with GetAssetsRec as(
		select a.*, null as IDParent, cast(null as uniqueidentifier) as IDParentModule
		from Asset a
		left join Asset2Asset a2a on a.IDAsset = a2a.IDRecAssetChild and a2a.IDRecAssetChildModule = a.IDModule
		where a2a.IDRecAssetChild is null and IDRelatedEntity = @IDEntity and IDRelatedEntityModule = @IDEntityModule
		union all
		select ac.*, a2a.IDRecAsset as IDParent, a2a.IDRecAssetModule as IDParentModule
		from Asset ac
		inner join Asset2Asset a2a on ac.IDAsset = a2a.IDRecAssetChild and a2a.IDRecAssetChildModule = ac.IDModule
		inner join GetAssetsRec ap on ap.IDAsset = a2a.IDRecAsset and ap.IDModule = a2a.IDRecAssetModule
	)
	select distinct a.*, rec.IDParent, rec.IDParentModule, case when a2a.IDRecAsset is null then 0 else 1 end HasChildren
	from Asset a
	inner join GetAssetsRec rec on a.IDAsset = rec.IDAsset and a.IDModule = rec.IDModule
	left join Asset2Asset a2a on a2a.IDRecAsset = a.IDAsset and a2a.IDRecAssetModule = a.IDModule
	where a.RegisterSysStatus = 0
)
GO


