-- procedure structure for SysGetLocks
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysGetLocks]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SysGetLocks]
GO

CREATE PROCEDURE [dbo].[SysGetLocks]

AS
BEGIN
	SET NOCOUNT ON;

	select cmd,* from sys.sysprocesses
	where blocked > 0

	SELECT 
		case when resource_type = 'OBJECT' then object_name(resource_associated_entity_id) else '' end as [object_name], 
		resource_associated_entity_id,
		* FROM sys.dm_tran_locks
	  WHERE resource_database_id = DB_ID()and  resource_type <> 'DATABASE'
  
END
GO


-- ----------------------------
-- procedure structure for SysOpenTransactions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SysOpenTransactions]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SysOpenTransactions]
GO

CREATE PROCEDURE [dbo].[SysOpenTransactions]
	
AS
BEGIN	
	SET NOCOUNT ON;

    
	select transaction_id, name, transaction_begin_time
	 ,case transaction_type 
		when 1 then '1 = Read/write transaction'
		when 2 then '2 = Read-only transaction'
		when 3 then '3 = System transaction'
		when 4 then '4 = Distributed transaction'
	end as transaction_type 
	,case transaction_state 
		when 0 then '0 = The transaction has not been completely initialized yet'
		when 1 then '1 = The transaction has been initialized but has not started'
		when 2 then '2 = The transaction is active'
		when 3 then '3 = The transaction has ended. This is used for read-only transactions'
		when 4 then '4 = The commit process has been initiated on the distributed transaction'
		when 5 then '5 = The transaction is in a prepared state and waiting resolution'
		when 6 then '6 = The transaction has been committed'
		when 7 then '7 = The transaction is being rolled back'
		when 8 then '8 = The transaction has been rolled back'
	end as transaction_state
	,case dtc_state 
		when 1 then '1 = ACTIVE'
		when 2 then '2 = PREPARED'
		when 3 then '3 = COMMITTED'
		when 4 then '4 = ABORTED'
		when 5 then '5 = RECOVERED'
	end as dtc_state 
	,transaction_status, transaction_status2,dtc_status, dtc_isolation_level, filestream_transaction_id
	from sys.dm_tran_active_transactions

	select*from sys.sysprocesses where open_tran = 1
END
GO


-- ----------------------------
-- function structure for GetOrganizationRelatedRecords
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetOrganizationRelatedRecords]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetOrganizationRelatedRecords]
GO

CREATE FUNCTION [dbo].[GetOrganizationRelatedRecords]
(	
	@IdRecord int,
	@IdModule uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	select organizationid as idrecord, idmodule
	from Entity
	where organizationid = @IDRecord and idmodule = @IdModule

	union

	select idLead , IDModule
	from Leads
	where idorganization = @IDRecord and idorganizationModule = @IdModule

	union

	select idaccount, IDModule
	from account
	where idcontact = @IDRecord and IDContactModule = @IdModule

	union

	select d.IDDocument, d.IDModule
	from document d
		inner join account a on d.doc_3rd_account = a.idaccount and d.doc_3rd_accountModule = a.IDModule
	where a.idcontact = @IDRecord and a.IDContactModule = @IdModule 
	
	union

	select d.IDDocument, d.IDModule
	from document d		
	where d.doc_3rd = @IDRecord and d.doc_3rdModule = @IdModule 


	union

	select o.idfollowupitem, o.IDModule
	from followupitem o
		inner join account a on o.IDThirdPartyAccount = a.idaccount and o.IDThirdPartyAccountModule = a.IDModule
	where a.idcontact = @IDRecord and a.IDContactModule = @IdModule 

	union

	select o.idfollowupitem, o.IDModule
	from followupitem o		
	where o.IDThirdParty = @IDRecord and o.IDThirdPartyModule = @IdModule

	union

	select t.IDFollowUpItem, t.IDModule
	from followupitem t
	where t.IDThirdParty = @IDRecord and IDThirdPartyModule = @IdModule

	union

	select t.IDServiceContract, t.IDModule
	from servicecontract t
	where t.IDRelatedTo = @IDRecord and t.IDRelatedToModule = @IdModule


)
GO


