GO

CREATE FUNCTION [dbo].[DateDiffInTicks] (@StartDate DATETIME, @EndDate DATETIME)
RETURNS
	BIGINT
AS BEGIN
	DECLARE @ms BIGINT = DATEDIFF(ms, @StartDate, @EndDate)
	RETURN @ms * 10000
END
GO


-- ----------------------------
-- procedure structure for UpdateTasksRecordRelationsFromActivity
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[UpdateTasksRecordRelationsFromActivity]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[UpdateTasksRecordRelationsFromActivity]
GO

CREATE PROCEDURE [dbo].[UpdateTasksRecordRelationsFromActivity]
	@IDActivity int
AS
BEGIN

	--INSERTS MISSING RECORD RELATIONS
	insert into SysTask2Record(IDRecord,IDRecordModule,IDTask,IDTaskModule,IDRelationActivity) 
	select a2r.relatedRecord, a2r.relatedRecordModule, t.IDTask, t.IDModule, a2r.IDActivity2Record
	from SysTask t
	left join Activity2Record a2r on a2r.IDActivity = t.IDActivity and a2r.relatedRecord is not null and a2r.relatedRecordModule is not null
	left join SysTask2Record t2r on t2r.IDTask = t.IDTask and a2r.IDActivity2Record = t2r.IDRelationActivity
	where t.IDActivity = @IDActivity and t2r.ID is null and a2r.IDActivity2Record is not null;

	--FIXES EXISTING RECORD RELATIONS WITH WRONG IDRECORDS
	update SysTask2Record set IDRecord = t.rec, IDRecordModule = recModule
	from(
		select t2r.ID as IDRel, a2r.relatedRecord rec, a2r.relatedRecordModule recModule
		from SysTask t
		left join Activity2Record a2r on a2r.IDActivity = t.IDActivity and a2r.relatedRecord is not null and a2r.relatedRecordModule is not null
		left join SysTask2Record t2r on t2r.IDTask = t.IDTask and a2r.IDActivity2Record = t2r.IDRelationActivity 
		where t.IDActivity = @IDActivity and t2r.ID is not null and (t2r.IDRecord <> a2r.relatedRecord or t2r.IDRecordModule <> a2r.relatedRecordModule)
	) t
	where ID = t.IDRel;

	--DELETES RECORD RELATIONS THAT WERE REMOVED IN ACTIVITY
	delete from SysTask2Record where ID in(
		select t2r.ID 
		from SysTask t
		left join SysTask2Record t2r on t2r.IDTask = t.IDTask 
		left join Activity2Record a2r on a2r.IDActivity = t.IDActivity and a2r.IDActivity2Record = t2r.IDRelationActivity and a2r.relatedRecord is not null and a2r.relatedRecordModule is not null
		where t.IDActivity = @IDActivity and t2r.ID is not null and t2r.IDRelationActivity is not null and a2r.IDActivity2Record is null
	);

END
GO


-- ----------------------------
-- function structure for GetNextStep
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetNextStep]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetNextStep]
GO

CREATE FUNCTION [dbo].[GetNextStep]()
RETURNS TABLE 
AS
RETURN 
(
	select t.relatedRecord IDRecord, t.relatedRecordModule IDModule, a.IDActivity, a.IDModule as IDActivityModule, a.startDate, 
	CONCAT(a.activityCode, ' | ', convert(varchar(19), a.startdate, 120), ' | ', LEFT(a.subject,30), ' | ', r.DisplayName) FieldDisplay,
	dbo.GetIDIconFromModule(a.IDModule) ActivityModuleIcon
	from Activity a
	inner join (
		select a2r.relatedRecord, a2r.relatedRecordModule, min(a.IDActivity) IDActivity ,min(tt.MinStart) MinStart
		FROM Activity2Record a2r
		inner join Activity a on a2r.IDActivity = a.IDActivity
		inner join (
			select a2r.relatedRecord, a2r.relatedRecordModule, min(a.startDate) as MinStart
			from Activity2Record a2r
			inner join Activity a on a2r.IDActivity = a.IDActivity
			and [status] = 2724
			group by a2r.relatedRecord, a2r.relatedRecordModule 
		) tt on a2r.relatedRecord = tt.relatedRecord and a2r.relatedRecordModule = tt.relatedRecordModule and (a.startDate = tt.MinStart or (a.startDate is null and tt.MinStart is null))
		group by a2r.relatedRecord, a2r.relatedRecordModule
	) t on a.IDActivity = t.idactivity
	left join SysResources r on a.IDResourceAssign = r.ResourceId
)
GO


-- ----------------------------
-- procedure structure for GetActiveSessions
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetActiveSessions]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[GetActiveSessions]
GO

CREATE PROCEDURE [dbo].[GetActiveSessions]
	
AS
BEGIN
	SET NOCOUNT ON;

	select *
	from dbo.ActiveSessions
	order by Username, IDWorkstation


	select 
		lr.idlock,
		lr.IDRecord, 
		lr.IDModule, 
		m.name,
		s.IDSession,
		l.Username,
		w.HostName,

		s.ActualDateStart,
		DATEDIFF(minute, s.DateStart , GETUTCDATE()) EllapsedSessionHeartbeat,

		lr.ActualStartDate,
		DATEDIFF(minute, lr.StartDate , GETUTCDATE()) EllapsedHeartbeat
	from SysLockRecord lr 
		inner join
		sysmodule m on lr.idmodule = m.IDModule
		inner join
		syssession s on lr.IDSession = s.IDSession
		inner join SysLogin l on s.IDLogin = l.IDLogin
		inner join sysworkstation w on s.idworkstation = w.Code
	where lr.[Status] = 1
	order by l.Username
END
GO


-- ----------------------------
-- function structure for GetResourceSharedRolesWithModule
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetResourceSharedRolesWithModule]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetResourceSharedRolesWithModule]
GO

CREATE FUNCTION [dbo].[GetResourceSharedRolesWithModule]
(
	@resourceid uniqueidentifier,
	@moduleid uniqueidentifier
)
RETURNS 
@Ret table
(	
	ResourceId uniqueidentifier	
)
AS
BEGIN
	-- Fill the table variable with the rows for your result set
	insert into @Ret(ResourceId)
	select Idresource
	from GetResourceSharedRoles(@resourceid)
	

	declare it_GetResourceSharedRolesWithModule cursor for
		select IDResourceSubTree, SubTreeKind
		from 
			dbo.SysAccessRecord
		where 
			IDResource = @resourceid AND IDModule = @moduleid
			and
			IDResourceSubTree is not null
	open it_GetResourceSharedRolesWithModule

	declare @idresourcesubtree uniqueidentifier
	declare @subtreekind int

	fetch next from it_GetResourceSharedRolesWithModule into @idresourcesubtree, @subtreekind

	while @@FETCH_STATUS = 0
	begin
		insert into @ret(ResourceId)
		select @idresourcesubtree

		if @subtreekind = 1 
		begin

			insert into @Ret(ResourceId)
			select Idresource
			from GetResourceDescendants(@idresourcesubtree)
		
		end

		fetch next from it_GetResourceSharedRolesWithModule into @idresourcesubtree, @subtreekind
	end

	close it_GetResourceSharedRolesWithModule
	deallocate it_GetResourceSharedRolesWithModule

	RETURN 
END
GO


-- ----------------------------
-- procedure structure for CloseRevision
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[CloseRevision]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[CloseRevision]
GO

CREATE PROCEDURE [dbo].[CloseRevision]
	-- Add the parameters for the stored procedure here
	@TableName sysname,
	@PrimaryKey nvarchar(100),
	@IDRecord nvarchar(100)
AS
BEGIN
	DECLARE @sql AS NVARCHAR(MAX)
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	SET @sql = 'UPDATE '+@TableName+' SET relActive=0 WHERE '+@PrimaryKey+'='''+@IDRecord+''''
	EXEC sp_executesql @sql

	-- Update status to Reviewed
	SET @sql = 'UPDATE '+@TableName+' SET status=2498 WHERE '+@PrimaryKey+'='''+@IDRecord+''''
	EXEC sp_executesql @sql

END
GO


-- ----------------------------
-- function structure for GetTranslationValue
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetTranslationValue]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetTranslationValue]
GO

CREATE FUNCTION [dbo].[GetTranslationValue]
(
@IDTranslation as uniqueidentifier,
@IDTranslationTarget as int null,
@IDLanguage as int null
)
RETURNS nvarchar(MAX)
AS
BEGIN
if(@IDTranslationTarget is null)
begin
	set @IDTranslationTarget = 3;
end
	
if(@IDLanguage is null)
begin
	set @IDLanguage = 1;
end
declare @Translation nvarchar(max) = '';

set @Translation = 
(
	select top 1 
	CASE
		WHEN @IDTranslationTarget = 1 THEN Acronym
		WHEN @IDTranslationTarget = 2 THEN ShortName
		WHEN @IDTranslationTarget = 3 THEN Name
		WHEN @IDTranslationTarget = 4 THEN Description
		WHEN @IDTranslationTarget = 5 THEN States
	END as Translation
	from SysTranslationValue 
	where IDTranslation = @IDTranslation and IDLanguage = @IDLanguage
)

return @Translation;
END
GO


-- ----------------------------
-- procedure structure for SS_CancelOperation
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CancelOperation]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CancelOperation]
GO

CREATE PROCEDURE [dbo].[SS_CancelOperation]
	-- Add the parameters for the stored procedure here
	@ObjectID uniqueidentifier,
	@IDKind int,
    @LoginID int=null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @IDWorkflowItem int;
	declare @IDWorkflowItemTemplate int;
	--Procurar Workflowitem a fechar
	Select @IDWorkflowItem =IDWorkflowItem,@IDWorkflowItemTemplate=template from sysworkflowitem where idregisto=@objectid and idkind=@IDKind;

	declare @IDWorkflow int;
	declare @IDWorkflowTemplate int;
	--Procurar IDWorkflow do item
	Select @IDWorkflow = wf.idworkflow, @IDWorkflowTemplate=wf.WorkflowClone from sysworkflowitem wfi inner join sysworkflow wf on wf.IDWorkflow=wfi.IDWorkflow where idregisto=@objectid and idkind=@IDKind;

	--Procurar o ID da sua condição de fecho
	declare @IDClosingCondition int;
	set @IDClosingCondition = (Select IDWorkflowConditions from SysWorkflowConditions where idworkflowitem=@IDWorkflowItemTemplate and targetstate=5);


	--Procurar as variaveis que definem a condiçao de fim deste item e provocar a sua mudança para o mecanismo fechar a operaçao normalmente
	declare @IDWorkflowVar int;
	declare @TargetValue int;
	DECLARE lc2 CURSOR LOCAL
	FOR select v.SysKind,value from SysWorkflowConditionsStep s inner join SysWorkflowVars  v on v.IDWorkflowVars=s.IDWorkflowVar where idcondition=@IDClosingCondition;
	OPEN lc2;
	FETCH NEXT FROM lc2
		INTO  @IDWorkflowVar,@TargetValue;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		--Fechar Vars
		EXEC dbo.ChangeVarFromObject @ObjectID,@IDWorkflowVar,@TargetValue,null,''

		FETCH NEXT FROM lc2
		INTO @IDWorkflowVar,@TargetValue;
	END;
		
	CLOSE lc2;
	DEALLOCATE lc2;

	EXEC SS_AddObjectNote	@ObjectID ,	@IDKind ,	1 ,	@LoginID	,	'Operação abortada.' 
END
GO


-- ----------------------------
-- function structure for GetBankAccount
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetBankAccount]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetBankAccount]
GO

CREATE FUNCTION [dbo].[GetBankAccount]
(	
	@OnlyDefault int
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT 
		a.IDAccount, a.IDModule as IDAccountModule,
		ba.IDAccount as IDBankAccount, ba.IDModule as IDBankAccountModule
	FROM 
		Account ba
		INNER JOIN
		Entity e ON ba.IDContact =  e.organizationid and ba.IDContactModule = e.IDModule 
		INNER JOIN
		Account a ON a.IDContact = e.organizationid and a.IDContactModule = e.IDModule

	WHERE
		(
			(@OnlyDefault = 1 AND BA.IsDefaultAccount = 1)
			OR
			(@OnlyDefault != 1)	
		)
		AND
		(
			(a.IDModule in (select idmodule from dbo.GetModulesRec('514C56EA-F7A6-4B27-805A-8D918C70F807')) and ba.IDModule in (select idmodule from dbo.GetModulesRec('639490F6-654B-4723-ADDA-D9E87D3E3C5E')))
			or
			(a.IDModule in (select idmodule from dbo.GetModulesRec('AADBC233-B9C6-43F9-A18F-F050984556AF')) and ba.IDModule in (select idmodule from dbo.GetModulesRec('CEE4AA46-3CFD-430E-B984-24CD9D612365')))
		)
		AND
		ba.dbmask = a.dbmask

)
GO


-- ----------------------------
-- function structure for GetViewContainersRec
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetViewContainersRec]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetViewContainersRec]
GO

CREATE FUNCTION [dbo].[GetViewContainersRec]
(	
	@IDSysViewContainer uniqueidentifier
)
RETURNS TABLE 
AS
RETURN 
(
	with SysViewContainerRec as (
		select IDSysViewContainer, IDSysViewContainerParent 
		from SysViewContainer 
		where IDSysViewContainer = @IDSysViewContainer
		union all
		select m.IDSysViewContainer, m.IDSysViewContainerParent
		from SysViewContainer m inner join SysViewContainerRec p on m.IDSysViewContainerParent = p.IDSysViewContainer
	)
	select vc.*
	from SysViewContainer vc
		inner join
		SysViewContainerRec vcr on vc.IDSysViewContainer = vcr.IDSysViewContainer
)
GO


-- ----------------------------
-- procedure structure for SS_CloseMould
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[SS_CloseMould]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[SS_CloseMould]
GO

CREATE PROCEDURE [dbo].[SS_CloseMould]
	@MouldID uniqueidentifier,
    @LoginID int=null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @ObjectID int;
	DECLARE LocalCursor2 CURSOR LOCAL
	FOR select id from ss_object where MouldID=@MouldID
	OPEN LocalCursor2;
	FETCH NEXT FROM LocalCursor2
		INTO  @ObjectID;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		declare @IDWorkflow int;

		--[dbo].[SS_EndOperation]

		FETCH NEXT FROM LocalCursor2
		INTO @ObjectID;
	END;
		
	CLOSE LocalCursor2;
	DEALLOCATE LocalCursor2;
	EXEC SS_AddObjectNote	@MouldID ,	-1 ,	1 ,	@LoginID	,	'Molde Fechado.' 
END
GO


-- ----------------------------
-- function structure for GetModulePayOn
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetModulePayOn]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetModulePayOn]
GO

CREATE FUNCTION [dbo].[GetModulePayOn] 
(
	@IDModule uniqueidentifier
)
RETURNS int
AS
BEGIN	
	DECLARE @PayOn int
	declare @idparent uniqueidentifier
	select @PayOn = PaymentsOn, @idparent = IDParent from sysmodule where idmodule = @IDModule

	if @PayOn = 999 and not @idparent is null
	begin
		return dbo.GetModulePayOn(@idparent)
	end

	RETURN @PayOn
END
GO


-- ----------------------------
-- function structure for GetEntityDefaultFinanceAccountOwn
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[GetEntityDefaultFinanceAccountOwn]') AND type IN ('FN', 'FS', 'FT', 'IF', 'TF'))
	DROP FUNCTION [dbo].[GetEntityDefaultFinanceAccountOwn]
GO

CREATE FUNCTION [dbo].[GetEntityDefaultFinanceAccountOwn]
(	
	@IDEntity int,
	@IDModule uniqueidentifier,
	@dbmask int,
	@Direction int
)
RETURNS TABLE 
AS
RETURN 
(
	SELECT top 1 acc.* 
    FROM  Entity2AccountFinance e2acc 
    INNER JOIN Account acc ON e2acc.IDAccountFinance = acc.IDAccount AND e2acc.IDAccountFinanceModule = acc.IDModule
    WHERE e2acc.[IDEntity] = @IDEntity AND e2acc.IDEntityModule = @IDModule AND e2acc.Direction = @Direction
	AND (e2acc.dbmask & @dbmask) != 0
    ORDER BY e2acc.[Default] DESC 
)
GO


-- ----------------------------
-- procedure structure for DeleteChatMessage
-- ----------------------------
IF EXISTS (SELECT * FROM sys.all_objects WHERE object_id = OBJECT_ID(N'[dbo].[DeleteChatMessage]') AND type IN ('P', 'PC', 'RF', 'X'))
	DROP PROCEDURE [dbo].[DeleteChatMessage]
GO

CREATE PROCEDURE [dbo].[DeleteChatMessage]
    @IDChat int,
    @IDSession uniqueidentifier,
    @IDWorkRoom uniqueidentifier OUTPUT,
    @IsPublic INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    declare @status_scheduler int
    declare @status_deleted int
    declare @r int
    set @r = -1

    -- Chat Status Scheduler = 4
    set @status_scheduler = 4
    -- Chat Status Deleted = 6
    set @status_deleted = 6

    -- Table variable to capture deleted read-references for counter updates
    DECLARE @DeletedRefs TABLE (
        IDChannel UNIQUEIDENTIFIER,
        IDUser UNIQUEIDENTIFIER,
        IDResource UNIQUEIDENTIFIER,
        MessageState INT
    );

    -- check if session is valid
    set @IDWorkRoom = null

    declare @idUserSession uniqueidentifier
    set @idUserSession = null

    select @idUserSession = IDLogin
    from SysSession
    where IDSession = @IDSession

    if @idUserSession is null or @idUserSession = '00000000-0000-0000-0000-000000000000'
    begin
        set @r = 3
        goto _end
    end
    
    -- check if message exists and was sent by the owner of the session
    declare @idChatDel int
    set @idChatDel = null

    select @idChatDel = IDChat2, @IDWorkRoom = IDWorkRoom, @IsPublic = IsPublic
    from SysChat
    where IDChat2 = @IDChat AND IDSender = @idUserSession

    if @idChatDel is null or @idChatDel = 0 
    begin
        set @r = 1
        goto _end
    end

    if not (@IDWorkRoom = '00000000-0000-0000-0000-000000000000' OR @IDWorkRoom is null)
    begin
        -- check if is today message (Business Rule)
        if @idChatDel in (
            select idchat2 
            from syschat 
            where 
                CAST(Stamp as DATE) = CAST(GETUTCDATE() as DATE)
                and [Status] != @status_deleted
                and @IDWorkRoom = IDWorkRoom
                AND Kind != 23 /*TaskVote*/
        )
        begin
            -- Start Transaction to ensure Counters and Message Status are updated atomically
            BEGIN TRANSACTION;

            BEGIN TRY
                -- 1. CLEANUP REFERENCES & UPDATE COUNTERS (New Logic)
                -- Even though it's a soft delete on SysChat, we must hard delete from SysChatUserRead
                -- so users don't have "phantom" unread messages.
                
                --DELETE FROM SysChatUserRead
                --OUTPUT deleted.IDChannel, deleted.IDUser, deleted.IDResource, deleted.MessageState
                --INTO @DeletedRefs
                --WHERE IDChat = @idChatDel;

                ---- Aggregate decrements per channel/user
                --;WITH CounterAdjustments AS (
                --    SELECT 
                --        IDChannel,
                --        IDUser,
                --        IDResource,
                --        COUNT(1) AS DecrementAmount
                --    FROM @DeletedRefs
                --    WHERE MessageState IN (1, 2) -- Unread or ToBeRead
                --    GROUP BY IDChannel, IDUser, IDResource
                --)
                ---- Update the WorkRoom Resource counters
                --UPDATE R
                --SET UnreadMessagesCounter = CASE 
                --                                WHEN R.UnreadMessagesCounter >= CA.DecrementAmount 
                --                                THEN R.UnreadMessagesCounter - CA.DecrementAmount
                --                                ELSE 0 
                --                            END
                --FROM SysWorkRoomResource R
                --INNER JOIN CounterAdjustments CA ON R.IDWorkRoom = CA.IDChannel
                --AND (
                --    (R.IDLogin IS NOT NULL AND R.IDLogin = CA.IDUser)
                --    OR
                --    (R.IDResource IS NOT NULL AND R.IDResource = CA.IDResource)
                --);

                -- 2. SOFT DELETE MESSAGE (Existing Logic)
                UPDATE SysChat Set 
                    [Status] = @status_deleted,
                    RawMessage = 'This message was deleted',
                    TaskStatus = NULL,
                    TaskTitle = NULL,
                    TaskStatusStr = NULL,
                    TaskShortName = NULL,
                    TaskKind = NULL,
                    ExtraData = NULL,
                    IDTask = NULL,
                    IDMail = NULL,
                    IDVideoCall = NULL,
                    IDActivity = NULL,
                    QuestionID = NULL,
                    IDRecord = NULL,
                    GIDRecord = NULL,
                    RecordShortName = NULL,
                    Kind = 0, -- Regular msg
                    ChatAnswerMessage = NULL,
                    ChatQuestionMessage = NULL,
                    ChatAnswerValue = NULL,
                    Importance = 1
                WHERE IDChat2 = @idChatDel;

                -- 3. CLEANUP ASSOCIATED TABLES (Existing Logic)
                DELETE SysChat2Record WHERE IDChat = @idChatDel;
                --DELETE SysChat2SysResource WHERE IDChat = @idChatDel;

                COMMIT TRANSACTION;
                set @r = 0

            END TRY
            BEGIN CATCH
                IF @@TRANCOUNT > 0
                    ROLLBACK TRANSACTION;
                
                -- Keep original error code logic or return specific error
                set @r = -1; 
            END CATCH
        end
        else
        begin 
            set @r = 2
            goto _end
        end
    end

_end:
    return @r
END
GO


