-- ----------------------------
-- Triggers structure for table Activity
-- ----------------------------
CREATE TRIGGER [dbo].[Activity_Update_AutoEnd_Status_Change]
ON [dbo].[Activity]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
	SET NOCOUNT ON;
	IF UPDATE(status)
	BEGIN
		UPDATE [Activity] SET AutoEnd=0  
		FROM inserted INNER JOIN [Activity] On inserted.IDActivity = [Activity].IDActivity
		WHERE inserted.status<>2725 and inserted.AutoEnd=1
	END
END
GO

CREATE TRIGGER [dbo].[Update_StartDateGroup]
ON [dbo].[Activity]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

		 Update Activity
		 Set startDateGroup= i.startDate
		  from inserted i
		   INNER JOIN Activity t ON i.IDActivity=t.IDActivity

END
GO


