CREATE TRIGGER [dbo].[Asset_CancelDelete]
ON [dbo].[Asset]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	 IF UPDATE(RegisterSysStatus)
	  BEGIN
		ROLLBACK
		RAISERROR('Changes column RegisterSysStatus not allowed', 16, 1);
	  END

END
GO

