CREATE TRIGGER [dbo].[TRG_AfterInsert_SysCompany]
ON [dbo].[Entity]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;

	SET IDENTITY_INSERT SysPerson ON;
    INSERT INTO SysPerson 
	(
        organizationid, organization_no, dbmask, departament, donotcall, email, email2, emailoptout, fax, firstname, imagename, 
        isconvertedfromlead, lastname, mobile, notify_owner, phone, reference, reportsto, salutation, secondaryemail, title, 
        isSystemCompany, mailingGps, mailingcity, mailingstreet, mailingcountry, mailingstate, mailingpobox, mailingzip, 
        billingGps, billingcity, billingstreet, billingcountry, billingstate, billingpobox, billingzip, Skype, ctsstamp, Area, 
        Identification, NIF, assistant, assistphone, birthday, homephone, leadsource, otherphone, website, accountname, 
        employees, ShortName, portal, support_start_date, support_end_date, description, entityno, entityno_counter, IsTemplate, 
        TemplateCode, isContact, isOrganization, ModifiedTime, CreatedTime, ExchangeID, IDGeographicArea, IDLanguage, 
        IDCountry, RegisterStatus, RegisterSysStatus, _autoDescription, IDModule, IDUserCreation, IDUser, IDResourceCreation, 
        IDResource, IDResourceAssign, IDGeographicAreaModule, topline, image, imageModule, kindEntity, organization_no_counter, 
        IdentFullName, IdentType, IdentCheckDigit, IdentExpire, IdentEmitCity, IdentEmitState, InsuranceNumber, 
        IdentQualification, IdentKindResidency, IdentVisa, IdentNationality, Gender, IDRelatedLogin, organizationType, Industry, 
        IndustryModule, organization_no_IsTemp, IDLanguageDoc, IDTemplateSource, IDTemplateSourceModule, dpgrApprovalFormHash, 
        dpgrApprovalFormSent, dpgrApprovalFormSentDate, dpgrApprovalAnswerReceived, dpgrApprovalAnswerReceivedDate, 
        dpgrApprovalAnswerReceivedIpAddress, dpgrOptIn, dpgrPassword, dpgrPasswordSalt, IdentNaturalCity, IdentNaturalPlace, 
        IdentNaturalState, IdentValidUntil, IdentNumber, dpgrRequestedDataDeletion, ConsentToCommunicate, ConsentSource, 
        ConsentCopy, ConsentCopyModule, IDPrintQualificationsLayout, Alias, TeamMask01, TeamMask02, IndustryLegacyName, 
        TemplateDefaultMFVCreate, TemplateMFVCreate, TeamAssignedMask01, TeamAssignedMask02, Industries, Companies, 
        SchoolDegree, CAE, CurrentResource, ID, IDFilesSystem, Visibility
    )
    SELECT 
        organizationid, organization_no, dbmask, departament, donotcall, email, email2, emailoptout, fax, firstname, imagename, 
        isconvertedfromlead, lastname, mobile, notify_owner, phone, reference, reportsto, salutation, secondaryemail, title, 
        isSystemCompany, mailingGps, mailingcity, mailingstreet, mailingcountry, mailingstate, mailingpobox, mailingzip, 
        billingGps, billingcity, billingstreet, billingcountry, billingstate, billingpobox, billingzip, Skype, ctsstamp, Area, 
        Identification, NIF, assistant, assistphone, birthday, homephone, leadsource, otherphone, website, accountname, 
        employees, ShortName, portal, support_start_date, support_end_date, description, entityno, entityno_counter, IsTemplate, 
        TemplateCode, isContact, isOrganization, ModifiedTime, CreatedTime, ExchangeID, IDGeographicArea, IDLanguage, 
        IDCountry, RegisterStatus, RegisterSysStatus, _autoDescription, IDModule, IDUserCreation, IDUser, IDResourceCreation, 
        IDResource, IDResourceAssign, IDGeographicAreaModule, topline, image, imageModule, kindEntity, organization_no_counter, 
        IdentFullName, IdentType, IdentCheckDigit, IdentExpire, IdentEmitCity, IdentEmitState, InsuranceNumber, 
        IdentQualification, IdentKindResidency, IdentVisa, IdentNationality, Gender, IDRelatedLogin, organizationType, Industry, 
        IndustryModule, organization_no_IsTemp, IDLanguageDoc, IDTemplateSource, IDTemplateSourceModule, dpgrApprovalFormHash, 
        dpgrApprovalFormSent, dpgrApprovalFormSentDate, dpgrApprovalAnswerReceived, dpgrApprovalAnswerReceivedDate, 
        dpgrApprovalAnswerReceivedIpAddress, dpgrOptIn, dpgrPassword, dpgrPasswordSalt, IdentNaturalCity, IdentNaturalPlace, 
        IdentNaturalState, IdentValidUntil, IdentNumber, dpgrRequestedDataDeletion, ConsentToCommunicate, ConsentSource, 
        ConsentCopy, ConsentCopyModule, IDPrintQualificationsLayout, Alias, TeamMask01, TeamMask02, IndustryLegacyName, 
        TemplateDefaultMFVCreate, TemplateMFVCreate, TeamAssignedMask01, TeamAssignedMask02, Industries, Companies, 
        SchoolDegree, CAE, CurrentResource, ID, IDFilesSystem, Visibility
    FROM Inserted
    WHERE kindEntity = 1;

	SET IDENTITY_INSERT SysPerson OFF;
END;
GO

CREATE TRIGGER [dbo].[TRG_AfterUpdate_SysCompany]
ON [dbo].[Entity]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    MERGE INTO SysPerson AS target
    USING (SELECT * FROM Inserted WHERE KindEntity = 1) AS source
    ON target.ID = source.ID
    WHEN MATCHED THEN
        UPDATE SET
            target.organization_no = source.organization_no,
            target.dbmask = source.dbmask,
            target.departament = source.departament,
            target.donotcall = source.donotcall, 
            target.email = source.email,
