-- ----------------------------
-- Triggers structure for table ServerFile
-- ----------------------------
CREATE TRIGGER [dbo].[ServerFileInsert]
ON [dbo].[ServerFile]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	UPDATE ServerFile
	SET filenameGuid =[dbo].[str2uniq] (i.[filename])
	 FROM Inserted i
    WHERE ServerFile.IDFile = i.IDFile
END
GO


