-- ----------------------------
-- Triggers structure for table SS_Program
-- ----------------------------
CREATE TRIGGER [dbo].[SS_CheckStateObject]
ON [dbo].[SS_Program]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	declare @ObjectID uniqueidentifier;
	declare @ProgramKind int;
	declare @ProgramID uniqueidentifier
	declare @Position int;

	SET NOCOUNT ON;
	
		DECLARE LocalCursor CURSOR LOCAL 
		FOR select idobject,kind,position from inserted where (haschilds=0) or ( haschilds is null);
		DECLARE @ChildID int
		OPEN LocalCursor;
		
		FETCH NEXT FROM LocalCursor
			INTO  @ObjectID,@ProgramKind,@Position
		
		WHILE @@FETCH_STATUS = 0
		BEGIN

			if (@Position>1)
			begin
				declare @Exists int =(Select id from SS_ObjectPosition where IDObject=@objectid and num=@Position)
				if @Exists is null
					Insert into SS_ObjectPosition (IDObject, Num, X, Y, Z, A, B, C, Img)
					values( @objectid,@Position,0,0,0,0,0,0,'' )
			end

			FETCH NEXT FROM LocalCursor
				INTO @ObjectID,@ProgramKind,@Position;
		END;
		
		CLOSE LocalCursor;
		DEALLOCATE LocalCursor;

END


SET ANSI_NULLS ON
GO


