-- ----------------------------
-- Triggers structure for table SysChannel2Email
-- ----------------------------
CREATE TRIGGER [dbo].[SysChannel2Email_TAfterDelete]
ON [dbo].[SysChannel2Email]
WITH EXECUTE AS CALLER
FOR DELETE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	if exists(select top 1 id from [dbo].[SysInfoChannel2Email])
	begin
		update [dbo].[SysInfoChannel2Email]
		set LastChange = GETUTCDATE()
	end
	else
	begin
		insert into [dbo].[SysInfoChannel2Email](LastChange) values(GETUTCDATE())
	end
END
GO

CREATE TRIGGER [dbo].[SysChannel2Email_TAfterInsert]
ON [dbo].[SysChannel2Email]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN	
	SET NOCOUNT ON;
	    
	update SysChannel2Email
	set LastChange = GETUTCDATE()
	where ID in (select id from inserted)

	-- Insert statements for trigger here
	if exists(select top 1 id from [dbo].[SysInfoChannel2Email])
	begin
		update [dbo].[SysInfoChannel2Email]
		set LastChange = GETUTCDATE()
	end
	else
	begin
		insert into [dbo].[SysInfoChannel2Email](LastChange) values(GETUTCDATE())
	end
END
GO

CREATE TRIGGER [dbo].[SysChannel2Email_TAfterUpdate]
ON [dbo].[SysChannel2Email]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
	SET NOCOUNT ON;

	update SysChannel2Email
	set LastChange = GETUTCDATE()
	where ID in (select id from inserted)

	-- Insert statements for trigger here
	if exists(select top 1 id from [dbo].[SysInfoChannel2Email])
	begin
		update [dbo].[SysInfoChannel2Email]
		set LastChange = GETUTCDATE()
	end
	else
	begin
		insert into [dbo].[SysInfoChannel2Email](LastChange) values(GETUTCDATE())
	end
END
GO


