-- ----------------------------
-- Triggers structure for table SysDSTable
-- ----------------------------
CREATE TRIGGER [dbo].[inserupdate_DSTableRelation]
ON [dbo].[SysDSTable]
WITH EXECUTE AS CALLER
FOR INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- Insert statements for trigger here

    declare @IDSysDSTable uniqueidentifier,
			@Count int

    select @IDSysDSTable=(select IDSysDSTable from inserted)

	SET @Count =(Select count(*) from SysDSTableRelation where IDSysDSTable =@IDSysDSTable)
	if @Count=0
	begin
		Insert INTO SysDSTableRelation(IDRelation,RelationKind,IDSysDSTable) VALUES (newid(),0,@IDSysDSTable)
	end
END
GO


