-- ----------------------------
-- Triggers structure for table SysFormView
-- ----------------------------
CREATE TRIGGER [dbo].[TG_BaseViewContainers]
ON [dbo].[SysFormView]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
		SET NOCOUNT ON
		DECLARE @IDTabContainer uniqueidentifier, 
				@SystemType int,
				@IDUIBTab uniqueidentifier,
				@IDUITab uniqueidentifier,
				@IDUIBC uniqueidentifier,
				@IDUIROOT uniqueidentifier,
				@IDUIBBP uniqueidentifier,
				@IDUIBRP uniqueidentifier,
				@IDUIBSA uniqueidentifier,
				@IDUIRC uniqueidentifier,
				@IDBTabContainer uniqueidentifier,
				@IDROOTContainer uniqueidentifier,
				@IDBRPConatainer uniqueidentifier,
				@IDBodyContainer uniqueidentifier,
				@BaseViewContainer uniqueidentifier,
				@IDSABViewContainer uniqueidentifier,
				@IDRCViewContainer uniqueidentifier,
				@IDSysFormView uniqueidentifier,
				@IDTranslation uniqueidentifier,
				@IDSysModule uniqueidentifier,
				@Name char(75),
				@IDStyle uniqueidentifier
				
		SELECT  @SystemType=i.SystemType,
				@BaseViewContainer =i.IDSysViewContainer,
				@IDSysFormView=i.IDSysFormView,
				@IDTranslation=i.IDTranslation,
				@IDSysModule=i.IDSysModule,
				@Name=i.Name
		FROM inserted i
		IF @BaseViewContainer IS  NULL
		BEGIN
			SET @IDUIBTab='C784E743-4CD9-4620-9695-E4ACB44CBD65'
			SET @IDUITab='0D040E5F-4630-4A37-BDE3-4E7697871813'
			SET @IDUIBC='03722544-B46D-4AE2-B13E-2F64630B48CF'
			SET @IDUIBRP='8288E3D9-CFE1-4807-9DD3-26425EA8EF14'
			SET @IDUIROOT='C2EC5292-E333-4F77-8F77-1FA9B45E9021'
			SET @IDUIBBP='C79133F9-59DF-46FA-9287-E81D59E54E68'
			SET @IDUIBSA='72E9C9A4-89EA-4C5D-AD59-39A1ADF66142'
			SET @IDUIRC='89E1193B-14EE-4BD6-84AD-92182E27A06D'
			
			SET @IDROOTContainer=newid()
			SET @IDBodyContainer=newid()
			SET @IDBTabContainer=newid()
			SET @IDTabContainer=newid()
			SET @IDBRPConatainer=newid()
			SET @IDSABViewContainer=newid()
			
			SET @IDRCViewContainer =newid()
			
			SET @IDStyle=(select top 1 IDSysStyle from SysStyle )
			
			SET @SystemType =(select SystemType from inserted)
			
			-- Insert ROOT Container
			INSERT INTO SysViewContainer(IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDTranslation,IDStyle)
					  VALUES(@IDROOTContainer,2,2,@IDUIROOT,'ROOT1',12,1,@SystemType,1,0,1,0,0,@IDTranslation,@IDStyle)
					  
					  			-- Update Base view Container 
			Update [SysFormView] 
			SET  IDSysViewContainer =@IDROOTContainer,
					codeCounter=5
			where IDSysFormView in (select IDSysFormView from inserted)
			
			-- INSERT BODY Container child root
			
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent,IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
					  VALUES(@IDROOTContainer,@IDBodyContainer,2,2,@IDUIBBP,'BBP2',12,1,@SystemType,1,0,1,0,1,@IDStyle)
			
			-- INSERT Right Menu child root
			
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent,IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
					  VALUES(@IDROOTContainer,@IDBRPConatainer,2,2,@IDUIBRP,'BRP3',12,1,@SystemType,1,0,1,0,2,@IDStyle)
			
			
			-- INSERT Block Write Panel child right menu !! Necessary ?
	
			-- INSERT Block Sections Actions ,child new row
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent,IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
			     VALUES(@IDBRPConatainer,@IDRCViewContainer,10,2,@IDUIRC,'RC4',12,1,@SystemType,1,0,1,0,2,@IDStyle)
			
			
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent,IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
					  VALUES(@IDRCViewContainer,@IDSABViewContainer,2,2,@IDUIBSA,'BSA5',12,1,@SystemType,1,0,1,0,2,@IDStyle)
			
			
			-- Insert Tab Container child body panel
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent,IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
								  VALUES(@IDBodyContainer, @IDBTabContainer,3,2,@IDUIBTab,'TC6',12,1,@SystemType,1,0,1,0,0,@IDStyle)
								  

			-- Insert TAB
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent, IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
						VALUES(@IDBTabContainer,@IDTabContainer, 3,2,@IDUITab,'BTAB7',12,1,@SystemType,1,0,1,0,0,@IDStyle)

			-- Insert BC
			INSERT INTO SysViewContainer(IDSysViewCOntainerParent, IDSysViewContainer,ControlType,HeightDrivenBy,IDSysUIComponent,Code,ControlColumns,LabelColumns,SystemType,AGmask01,AGmask02,AGWmask01,AGWmask02,Sequence,IDStyle)
						VALUES(@IDTabContainer,newid(), 2,2,@IDUIBC,'BC8',12,1,@SystemType,1,0,1,0,0,@IDStyle)

				
			-- Insert ModuleFilter2FormView
			
			INSERT INTO SysModuleFilter2FormView(IDModuleFilter2FormView,IDSysFormView,IDTranslation,IDSysModule,AGmask01,AGmask02,AGWmask01,AGWmask02,Name)
						VALUES(newid(),@IDSysFormView,@IDTranslation,@IDSysModule,1,0,1,0,@Name)
		END
    END
GO


