-- ----------------------------
-- Triggers structure for table SysJobPP
-- ----------------------------
CREATE TRIGGER [dbo].[SS_Trigger_Setup]
ON [dbo].[SysJobPP]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	declare @IDJobPPTemplate uniqueidentifier;
	declare @ID int;
	--Recolher id e templateid do registo inserido
	Select @ID=ID, @IDJobPPTemplate=idjobPPtemplate from inserted;
	if @IDJobPPTemplate is not null 
	begin
		--Calcular novo numero para preparaçao
		Update SysJobPPTemplate set CounterCurrValue=CounterCurrValue+1, PPCounterCurrValue= ((CounterCurrValue+1) % PPCounterMax)+1 where 
			idtemplate=@IDJobPPTemplate;

		--Actualizar registo inserido
		update sysjobPP set 
			Name=Isnull(Name,st.[CodePrefix]+cast([CounterCurrValue] as nvarchar(10))),
			PPCode=isnull(st.[PPCodePrefix],'')+FORMAT([PPCounterCurrValue], [PPCounterCharMask]),
			kind=st.kind
		From sysjobPP s
		inner join sysjobPPtemplate st on st.idtemplate=s.IDjobPPTemplate
		where s.id=@ID;
	end
    -- Insert statements for trigger here
END
GO


