-- ----------------------------
-- Triggers structure for table SysLogin
-- ----------------------------
CREATE TRIGGER [dbo].[TRG_AfterInsert_SysLogin]
ON [dbo].[SysLogin]
WITH EXECUTE AS CALLER
FOR INSERT
AS
BEGIN
    SET NOCOUNT ON;

	-- Update IDPersonGuid
	/*
    UPDATE L
    SET L.IDPersonGuid = P.ID
    FROM SysLogin L
    INNER JOIN inserted I ON L.IDPerson = I.IDPerson
    INNER JOIN SysPerson P ON P.organizationid = L.IDPerson;
	*/
	
	UPDATE L
	SET L.IDPersonGuid = P.ID
	FROM SysLogin L
	INNER JOIN inserted I ON L.IDLogin = I.IDLogin  -- Alterado para garantir que só atualiza os novos registros
	INNER JOIN SysPerson P ON P.organizationid = I.IDPerson; -- Mantendo o vínculo correto com SysPerson
END;
GO

CREATE TRIGGER [dbo].[TRG_AfterUpdate_SysLogin]
ON [dbo].[SysLogin]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;
	IF UPDATE(IDPerson)
	BEGIN 
    -- Update IDPersonGuid when IDPerson is changed
		UPDATE L
		SET L.IDPersonGuid = P.ID
		FROM SysLogin L
		INNER JOIN inserted I ON L.IDPerson = I.IDPerson
		INNER JOIN SysPerson P ON P.organizationid = L.IDPerson
		WHERE I.IDPerson IS NOT NULL; -- Only if IDPerson was changed
	end
END;
GO


