-- ----------------------------
-- Triggers structure for table SysMeeting
-- ----------------------------
CREATE TRIGGER [dbo].[TR_SysMeeting_SetModifiedTime]
ON [dbo].[SysMeeting]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE m
       SET m.[ModifiedTime] = SYSUTCDATETIME()
    FROM [dbo].[SysMeeting] m
    INNER JOIN inserted i ON i.[ID] = m.[ID];
END
GO


