-- ----------------------------
-- Triggers structure for table SysNotify2SysResource
-- ----------------------------
CREATE TRIGGER [dbo].[TRG_SysNotify2SysResource_UpdateModifiedTime]
ON [dbo].[SysNotify2SysResource]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- Exit if no rows are affected
    IF (ROWCOUNT_BIG() = 0)
        RETURN;

    -- Update ModifiedTime for the affected rows
    UPDATE t
    SET t.[ModifiedTime] = CURRENT_TIMESTAMP
    FROM [dbo].[SysNotify2SysResource] AS t
    INNER JOIN Inserted AS i ON t.[ID] = i.[ID];
END;
GO


