-- ----------------------------
-- Triggers structure for table SysReminder2SysResource
-- ----------------------------
CREATE TRIGGER [dbo].[TRG_SysReminder2SysResource_UpdateModifiedTime]
ON [dbo].[SysReminder2SysResource]
WITH EXECUTE AS CALLER
FOR UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- Exit if no rows are affected
    IF (@@ROWCOUNT = 0)
        RETURN;

    -- Update ModifiedTime for the affected rows using UTC to maintain consistency
    UPDATE t
    SET t.[ModifiedTime] = SYSUTCDATETIME()
    FROM [dbo].[SysReminder2SysResource] AS t
    INNER JOIN Inserted AS i ON t.[ID] = i.[ID];
END;
GO


