-- ----------------------------
-- Triggers structure for table SysTranslation
-- ----------------------------
CREATE TRIGGER [dbo].[T_Translation_D]
ON [dbo].[SysTranslation]
WITH EXECUTE AS CALLER
INSTEAD OF DELETE
AS
set nocount on
	delete from SysTranslation
	where IDTranslationParent in (select IDTranslation from deleted)

	delete from SysTranslation where IDTranslation in (select IDTranslation from deleted)
GO


