ON [dbo].[SysWorkRoomResource]
WITH EXECUTE AS CALLER
FOR DELETE
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for trigger here
	if exists(select * from deleted where IDWorkRoom = 'dd37c910-8f26-ec11-872f-d850e63f5833') 	
	begin
		throw 50001, 'error detected: removing resources from 3d print suporte, contact development team', 0
	end

END
GO

